INSERT INTO content_unit (slug, bucket, title, kind, sort_order) VALUES ('mukhtasar-ul-asar-2', 'Islamic', 'Mukhtasar-ul-Asaar 2', 'book', 0) ON CONFLICT(slug) DO UPDATE SET bucket = excluded.bucket, title = excluded.title;
