INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'blurb', NULL, 'Mukhtasar-ul-Asaar 2', 0, NULL, 'What you have here is a compendium of transmitted reports — short, gathered accounts of practice and ruling — arranged by subject rather than told as a continuous story. Its very title marks it as an abridgement: a condensed collection of asar, the received reports, and the numeral signals that it is a second gathering, a companion to a first. It reads the way such collections read, moving topic by topic through the ordinary business of a life lived under law.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2', 'what you have here is a compendium of transmitted reports short gathered accounts of practice and ruling arranged by subject rather than told as a continuous story its very title marks it as an abridgement a condensed collection of asar the received reports and the numeral signals that it is a second gathering a companion to a first it reads the way such collections read moving topic by topic through the ordinary business of a life lived under law', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'introduction', 'Introduction', 0, NULL, 'What you have here is a compendium of transmitted reports — short, gathered accounts of practice and ruling — arranged by subject rather than told as a continuous story. Its very title marks it as an abridgment: a condensed collection of asar, the received reports, and the numeral signals that it is a second gathering, a companion to a first. It reads the way such collections read, moving topic by topic through the ordinary business of a life lived under law. It was compiled by Qadi al-Numan ibn Muhammad ibn Hayyun al-Tamimi, whose arrangement gives the reports their order without adding a voice of his own to them.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 introduction', 'what you have here is a compendium of transmitted reports short gathered accounts of practice and ruling arranged by subject rather than told as a continuous story its very title marks it as an abridgment a condensed collection of asar the received reports and the numeral signals that it is a second gathering a companion to a first it reads the way such collections read moving topic by topic through the ordinary business of a life lived under law it was compiled by qadi al numan ibn muhammad ibn hayyun al tamimi whose arrangement gives the reports their order without adding a voice of his own to them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'introduction', 'Introduction', 1, NULL, 'Because the book is built from transmitted reports, no single author speaks to you in his own voice. Where a first person appears, it belongs to a figure inside a report — someone whose words or conduct are being relayed — not to a narrator confiding in the reader. Keep that distinction in mind: the "I" of a passage is a person being quoted, and the book itself stands at a step''s remove, carrying the account forward. Nothing here has been added or augmented; the edition presents the reports as they come, faithfully.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 introduction', 'because the book is built from transmitted reports no single author speaks to you in his own voice where a first person appears it belongs to a figure inside a report someone whose words or conduct are being relayed not to a narrator confiding in the reader keep that distinction in mind the i of a passage is a person being quoted and the book itself stands at a steps remove carrying the account forward nothing here has been added or augmented the edition presents the reports as they come faithfully', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'introduction', 'Introduction', 2, NULL, 'The nine chapters map the terrain of everyday obligation. They begin in the marketplace, with honest earning and property, then take up the weight of a sworn word — oaths and vows and how they are answered for. From there the book turns to the body''s needs: what may be eaten and drunk and used to heal, what may be worn and how one is adorned, and how an animal is lawfully hunted, slaughtered, or offered. The later chapters move into the household — marriage and its ordering, and then its ending in divorce — before closing with the freeing of slaves, the giving of gifts, the dividing of estates, and finally the work of the judge in setting wrong to right.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 introduction', 'the nine chapters map the terrain of everyday obligation they begin in the marketplace with honest earning and property then take up the weight of a sworn word oaths and vows and how they are answered for from there the book turns to the bodys needs what may be eaten and drunk and used to heal what may be worn and how one is adorned and how an animal is lawfully hunted slaughtered or offered the later chapters move into the household marriage and its ordering and then its ending in divorce before closing with the freeing of slaves the giving of gifts the dividing of estates and finally the work of the judge in setting wrong to right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'introduction', 'Introduction', 3, NULL, 'The figures who recur are not named heroes but roles: the trader, the one who swears, the spouse, the heir, the judge. Read them as the standing parties to the situations the reports address.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 introduction', 'the figures who recur are not named heroes but roles the trader the one who swears the spouse the heir the judge read them as the standing parties to the situations the reports address', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 0, NULL, 'God has commanded the believer to seek what He has set aside of His bounty. He says, ﴿وَاسْأَلُوا اللَّهَ مِن فَضْلِهِ﴾, "And ask Allah of His bounty," and He says, ﴿فَإِذَا قُضِيَتِ الصَّلَاةُ فَانتَشِرُوا فِي الْأَرْضِ وَابْتَغُوا مِن فَضْلِ اللَّهِ﴾, "When the prayer is concluded, spread out in the land and seek the bounty of Allah." The pursuit of provision is therefore not a lapse from religion but something religion itself enjoins, provided it is pursued in the manner God has prescribed.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'god has commanded the believer to seek what he has set aside of his bounty he says واسالوا الله من فضله and ask allah of his bounty and he says فاذا قضيت الصلاه فانتشروا في الارض وابتغوا من فضل الله when the prayer is concluded spread out in the land and seek the bounty of allah the pursuit of provision is therefore not a lapse from religion but something religion itself enjoins provided it is pursued in the manner god has prescribed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 1, NULL, 'A man came to the Prophet ﷺ and said, "O Messenger of Allah, my soul has not been content with anything of this world, nor is it satisfied by it." The Messenger of Allah ﷺ said to him, "Say: O Allah, please me with Your decree, bless me in what You have given me, and make me content with what You have apportioned for me, so that I may not wish to hasten what You have delayed, nor to delay what You have hastened." Contentment, then, is the first discipline of the one who earns, for the soul that cannot be satisfied will not be steadied by any increase of wealth.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'a man came to the prophet ﷺ and said o messenger of allah my soul has not been content with anything of this world nor is it satisfied by it the messenger of allah ﷺ said to him say o allah please me with your decree bless me in what you have given me and make me content with what you have apportioned for me so that i may not wish to hasten what you have delayed nor to delay what you have hastened contentment then is the first discipline of the one who earns for the soul that cannot be satisfied will not be steadied by any increase of wealth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 2, NULL, 'It is narrated through the Imams of his household, from al-Sadiq Jafar ibn Muhammad, upon him be the prayers of Allah, from his father, from his forefathers, upon them be the prayers of Allah, from the Messenger of Allah, that he said, "The faithful spirit breathed into my heart that no soul shall die until it has completed its provision. So be measured and at ease in seeking sustenance. There is no servant of Allah but that he has a provision, and between him and it there is a veil. If he is patient with restraint, Allah brings it to him lawfully; and if he is not patient, he tears the veil and so consumes it unlawfully." The same provision reaches a man either way, but his patience decides whether it reaches him as a blessing or as a sin.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'it is narrated through the imams of his household from al sadiq jafar ibn muhammad upon him be the prayers of allah from his father from his forefathers upon them be the prayers of allah from the messenger of allah that he said the faithful spirit breathed into my heart that no soul shall die until it has completed its provision so be measured and at ease in seeking sustenance there is no servant of allah but that he has a provision and between him and it there is a veil if he is patient with restraint allah brings it to him lawfully and if he is not patient he tears the veil and so consumes it unlawfully the same provision reaches a man either way but his patience decides whether it reaches him as a blessing or as a sin', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 3, NULL, 'He said, upon him be peace, "Do not let the slowness of any provision drive you to seek it through disobedience to Allah, and be gracious in your seeking, for what is with Allah is not attained by disobedience." He also said, "If one of you becomes destitute, let him go out and seek his provision, strike out into the earth, and seek the bounty of Allah. Let him not sit in his house, grieving himself and his family and becoming a burden upon others." And he said, "Beneath the shade of the Throne, on the Day when there is no shade but His, will be a man who went out striking the earth, seeking the bounty of Allah, to restrain himself from begging and to provide for his dependents."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he said upon him be peace do not let the slowness of any provision drive you to seek it through disobedience to allah and be gracious in your seeking for what is with allah is not attained by disobedience he also said if one of you becomes destitute let him go out and seek his provision strike out into the earth and seek the bounty of allah let him not sit in his house grieving himself and his family and becoming a burden upon others and he said beneath the shade of the throne on the day when there is no shade but his will be a man who went out striking the earth seeking the bounty of allah to restrain himself from begging and to provide for his dependents', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 4, NULL, 'A man came and said, "O Messenger of Allah, I am skilled in no trade that I take up without finding it goes badly for me." The Messenger said, "Look at something you have once managed to earn from, and hold fast to it." The man said, "The cutting and selling of acacia for tanning." He said, "Then keep to the acacia trade."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'a man came and said o messenger of allah i am skilled in no trade that i take up without finding it goes badly for me the messenger said look at something you have once managed to earn from and hold fast to it the man said the cutting and selling of acacia for tanning he said then keep to the acacia trade', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 5, NULL, 'The Messenger of Allah once passed through one of the markets and said, "O company of merchants, the merchant is a licentious man, and the licentious are in the Fire." When they heard this, they shut the doors of their shops and abandoned trade. The next day he passed through the market and found no one there, and asked, "What is the matter with them?" It was said, "They abandoned trade, O Messenger of Allah, when they heard what you said yesterday." He said, "I say the same again today, except for the one who takes what is rightfully his and gives others their right." The condemnation, then, fell not upon trade itself but upon the dishonesty that so often accompanies it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the messenger of allah once passed through one of the markets and said o company of merchants the merchant is a licentious man and the licentious are in the fire when they heard this they shut the doors of their shops and abandoned trade the next day he passed through the market and found no one there and asked what is the matter with them it was said they abandoned trade o messenger of allah when they heard what you said yesterday he said i say the same again today except for the one who takes what is rightfully his and gives others their right the condemnation then fell not upon trade itself but upon the dishonesty that so often accompanies it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 6, NULL, 'He said, "I was sent as a mercy to people; I was not sent as a merchant, nor as a farmer. The worst of this nation are its merchants and its cultivators, except for those among them who guard their religion jealously." And he said, "Verily Allah loves the servant who is easy in selling, easy in buying, easy in settling what he owes, and easy in seeking what is owed to him."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he said i was sent as a mercy to people i was not sent as a merchant nor as a farmer the worst of this nation are its merchants and its cultivators except for those among them who guard their religion jealously and he said verily allah loves the servant who is easy in selling easy in buying easy in settling what he owes and easy in seeking what is owed to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 7, NULL, 'The Messenger of Allah once saw a strong young man driving fat, well-laden camels. Someone said to him, "O Messenger of Allah, how excellent is this man''s strength, and the strength of his camels — if only it were in the way of Allah." The Messenger of Allah turned to the youth and asked, "What do you do with these camels of yours?" The boy said, "I labor with them and earn my living from them." He asked, "And what do you do with your earnings?" The boy said, "I have a wife and children whom I support, sparing them from having to ask of others, and I pay off a debt I owe." He said, "If he speaks truthfully, he has a reward like the reward of the one who fights in the way of Allah, and of the one who performs the Hajj and the Umrah." And Ali, upon him be the prayers of Allah, said, "The setting out of one of you in the way of Allah is no greater than his setting out to seek for his children and dependents that which will sustain them."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the messenger of allah once saw a strong young man driving fat well laden camels someone said to him o messenger of allah how excellent is this mans strength and the strength of his camels if only it were in the way of allah the messenger of allah turned to the youth and asked what do you do with these camels of yours the boy said i labor with them and earn my living from them he asked and what do you do with your earnings the boy said i have a wife and children whom i support sparing them from having to ask of others and i pay off a debt i owe he said if he speaks truthfully he has a reward like the reward of the one who fights in the way of allah and of the one who performs the hajj and the umrah and ali upon him be the prayers of allah said the setting out of one of you in the way of allah is no greater than his setting out to seek for his children and dependents that which will sustain them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 8, NULL, 'The Prophet, upon him be peace, said to a man who asked his permission to take up trade, "Have you gained understanding in religion?" The man said, "Some of it." He said, "Woe to you. Understanding first, then the marketplace; for whoever buys and sells without understanding falls into usury" — and by usury here he meant that which is deferred. Knowledge of what is lawful must precede the transaction, or the trader sinks unknowingly into what is forbidden.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the prophet upon him be peace said to a man who asked his permission to take up trade have you gained understanding in religion the man said some of it he said woe to you understanding first then the marketplace for whoever buys and sells without understanding falls into usury and by usury here he meant that which is deferred knowledge of what is lawful must precede the transaction or the trader sinks unknowingly into what is forbidden', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 9, NULL, 'Muhammad ibn al-Munkadir said, "I saw Muhammad ibn Ali ibn al-Husayn, upon him be peace, on a day of severe heat. He had come in from a farm, and being a heavy man, he was worn out with fatigue. I said to myself: I shall counsel a man of his nobility. I said, May I be your ransom. With your standing of honor, you exert yourself like this in seeking the world? Tell me — if your appointed hour came upon you in this state, what would you say of it? He said, Were my hour to come upon me in this state, it would find me in an act of obedience to Allah. By it I restrain myself from needing others and prepare provision for my Hereafter, striving to earn from what is lawful. What I would truly fear is that my hour should come upon me while I was in disobedience to Allah Almighty — and I seek refuge in Allah from that. So I said to him, May I be your ransom. I meant to counsel you, and you have counseled me."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'muhammad ibn al munkadir said i saw muhammad ibn ali ibn al husayn upon him be peace on a day of severe heat he had come in from a farm and being a heavy man he was worn out with fatigue i said to myself i shall counsel a man of his nobility i said may i be your ransom with your standing of honor you exert yourself like this in seeking the world tell me if your appointed hour came upon you in this state what would you say of it he said were my hour to come upon me in this state it would find me in an act of obedience to allah by it i restrain myself from needing others and prepare provision for my hereafter striving to earn from what is lawful what i would truly fear is that my hour should come upon me while i was in disobedience to allah almighty and i seek refuge in allah from that so i said to him may i be your ransom i meant to counsel you and you have counseled me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 10, NULL, 'A man said to Jafar ibn Muhammad, upon him be the prayers of Allah, "O son of the Messenger of Allah, pray to Allah to grant me provision in ease, without effort." He replied, "I will not pray to Allah for that. Seek as Allah Almighty has commanded you." And he said, upon him be peace, "It befits the Muslim to seek his provision until the heat of the sun reaches him."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'a man said to jafar ibn muhammad upon him be the prayers of allah o son of the messenger of allah pray to allah to grant me provision in ease without effort he replied i will not pray to allah for that seek as allah almighty has commanded you and he said upon him be peace it befits the muslim to seek his provision until the heat of the sun reaches him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 11, NULL, 'Among the supplications of the Ahl al-Bayt, upon them be peace, is this: "O Allah, do not burden me with seeking what You have not apportioned for me, lest my occupation with it draw me away from obeying You and I be unable to attain any of it. O Allah, whatever You have apportioned for me of this, bring it to me in chastity and ease, and set me right by that which You have set right the righteous, for the righteousness of the righteous comes from You." It is reported, in the words of Abu Muhammad ibn Ali — (رضي الله عنه) and may mercy and blessing be upon him — that this was among the supplications of Dawud, upon him be peace.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'among the supplications of the ahl al bayt upon them be peace is this o allah do not burden me with seeking what you have not apportioned for me lest my occupation with it draw me away from obeying you and i be unable to attain any of it o allah whatever you have apportioned for me of this bring it to me in chastity and ease and set me right by that which you have set right the righteous for the righteousness of the righteous comes from you it is reported in the words of abu muhammad ibn ali رضي الله عنه and may mercy and blessing be upon him that this was among the supplications of dawud upon him be peace', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 12, NULL, 'Jafar ibn Muhammad, upon him be peace, said to Sufyan, who had come to ask him, "O Sufyan, when a blessing appears upon you, praise Allah; and when something of your provision is slow in coming, seek the forgiveness of Allah." Then he recited, "Ask forgiveness of your Lord; verily He is ever Forgiving. He will send the sky upon you in abundant rain," up to His words, "and will make for you rivers." He continued, "And when something of the terrors of this world befalls you, say: There is no power and no strength save with Allah, the Most High, the Most Great."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'jafar ibn muhammad upon him be peace said to sufyan who had come to ask him o sufyan when a blessing appears upon you praise allah and when something of your provision is slow in coming seek the forgiveness of allah then he recited ask forgiveness of your lord verily he is ever forgiving he will send the sky upon you in abundant rain up to his words and will make for you rivers he continued and when something of the terrors of this world befalls you say there is no power and no strength save with allah the most high the most great', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 13, NULL, 'Sufyan said, "Grant me these three — and what are the three?"', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'sufyan said grant me these three and what are the three', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 14, NULL, 'He, upon him be peace, also addressed one of his Shia, counseling him: "When you go out, morning or evening, in search of your provision and you desire success in it, pray two units of prayer. When you have finished the tashahhud, say:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he upon him be peace also addressed one of his shia counseling him when you go out morning or evening in search of your provision and you desire success in it pray two units of prayer when you have finished the tashahhud say', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 15, NULL, 'O Allah, I have gone forth — if I am one going forth — or set out — if I am one setting out — seeking of Your bounty as You commanded me. So grant me of Your bounty a lawful and wholesome provision as You commanded me, and grant me well-being in what You have provided for me.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'o allah i have gone forth if i am one going forth or set out if i am one setting out seeking of your bounty as you commanded me so grant me of your bounty a lawful and wholesome provision as you commanded me and grant me well being in what you have provided for me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 16, NULL, 'Say that three times. Then pray two more units, and after the tashahhud say:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'say that three times then pray two more units and after the tashahhud say', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 17, NULL, 'I have gone forth — if I am one going forth — or set out — if I am one setting out — by the power of Allah and His strength, with no power or strength of my own, but by Your power, O my Lord, and Your strength. I declare myself free, O my Lord, before You, of all power and strength. O Allah, I ask You for the good of this day, if it is day, or the good of this night, if it is night, and I ask You to provide me from Your bounty a lawful and wholesome provision, driven to me by Your power and Your strength, while I remain at ease, in chastity.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'i have gone forth if i am one going forth or set out if i am one setting out by the power of allah and his strength with no power or strength of my own but by your power o my lord and your strength i declare myself free o my lord before you of all power and strength o allah i ask you for the good of this day if it is day or the good of this night if it is night and i ask you to provide me from your bounty a lawful and wholesome provision driven to me by your power and your strength while i remain at ease in chastity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 18, NULL, 'Say that three times, then rise to your purpose."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'say that three times then rise to your purpose', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 19, NULL, 'The Prophet said, upon him be peace, "Allah Almighty has divided provision among His servants, and He has reserved beyond it a great surplus that He did not divide among them; so ask Allah of His bounty." He also said, "The one who sets out in pursuit of lawful provision is like the one who strives in the way of Allah." And to a man of his Shia who was engaged in trade, he said, "When you seek something of this world and it escapes you, remember what Allah Almighty has singled you out for from His religion, and the favor He has shown you in turning others away from it. That is more fitting to lift your soul above the loss."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the prophet said upon him be peace allah almighty has divided provision among his servants and he has reserved beyond it a great surplus that he did not divide among them so ask allah of his bounty he also said the one who sets out in pursuit of lawful provision is like the one who strives in the way of allah and to a man of his shia who was engaged in trade he said when you seek something of this world and it escapes you remember what allah almighty has singled you out for from his religion and the favor he has shown you in turning others away from it that is more fitting to lift your soul above the loss', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 20, NULL, 'Ali ibn al-Husayn, upon him be the prayers of Allah, said, "Allah Almighty has made provision ten parts: nine of them in trade and one part in all other things."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'ali ibn al husayn upon him be the prayers of allah said allah almighty has made provision ten parts nine of them in trade and one part in all other things', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 21, NULL, 'A man said to Abu Abd Allah Jafar ibn Muhammad, upon him be the prayers of Allah, to whom he was devoted, "O son of the Messenger of Allah, I have abandoned trade, waiting for the appearance of your cause." The Imam said to him, "Do not do so. Open your door, spread out your mat, and seek provision from your Lord, for that is better for you. If you hold back from seeking your provision, your wealth will dwindle. So seek of the bounty of Allah, your Lord."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'a man said to abu abd allah jafar ibn muhammad upon him be the prayers of allah to whom he was devoted o son of the messenger of allah i have abandoned trade waiting for the appearance of your cause the imam said to him do not do so open your door spread out your mat and seek provision from your lord for that is better for you if you hold back from seeking your provision your wealth will dwindle so seek of the bounty of allah your lord', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 22, NULL, 'On What Is Forbidden to Sell', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'on what is forbidden to sell', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 23, NULL, 'The Messenger of Allah forbade the sale of free persons and declared such transactions void. He likewise forbade the sale of carrion and of wine. Transmitted from the Imams of his household, upon them be the prayers of Allah, is the ruling that everything unlawful may neither be sold nor earned from, nor may its price be received. This covers filth, carrion, blood, swine, wine, every intoxicant, and all instruments of idle amusement. The Imams forbade the making of such things, earning from them, buying and selling them, learning them, and lending any assistance toward them.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the messenger of allah forbade the sale of free persons and declared such transactions void he likewise forbade the sale of carrion and of wine transmitted from the imams of his household upon them be the prayers of allah is the ruling that everything unlawful may neither be sold nor earned from nor may its price be received this covers filth carrion blood swine wine every intoxicant and all instruments of idle amusement the imams forbade the making of such things earning from them buying and selling them learning them and lending any assistance toward them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 24, NULL, 'They permitted, however, the sale of:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'they permitted however the sale of', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 25, NULL, 'Grapes, pressed juice, raisins, honey, dates, and figs — even to one who will turn them into wine or another intoxicant — because the sale of these goods is itself lawful, and the sin falls only upon the one who renders them unlawful.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'grapes pressed juice raisins honey dates and figs even to one who will turn them into wine or another intoxicant because the sale of these goods is itself lawful and the sin falls only upon the one who renders them unlawful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 26, NULL, 'They likewise permitted the taking of payment in every case where the sale of a thing is forbidden, when it is sold to one who will use it for himself — though it remains forbidden for that buyer to do so. As for the price received by one into whose hands a thing has passed by lawful means, there is no harm in it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'they likewise permitted the taking of payment in every case where the sale of a thing is forbidden when it is sold to one who will use it for himself though it remains forbidden for that buyer to do so as for the price received by one into whose hands a thing has passed by lawful means there is no harm in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 27, NULL, 'There is no harm, either, in dealing with polytheists and accepting payment for what they purchase from Muslims, nor in receiving what they hold from the proceeds of things they have sold that were not lawful to sell. Most of their wealth derives from usury and unlawful gain, yet it may be taken from them as the jizya or as payment for what they purchase from Muslims, and it becomes lawful for the one who receives it through its rightful means.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'there is no harm either in dealing with polytheists and accepting payment for what they purchase from muslims nor in receiving what they hold from the proceeds of things they have sold that were not lawful to sell most of their wealth derives from usury and unlawful gain yet it may be taken from them as the jizya or as payment for what they purchase from muslims and it becomes lawful for the one who receives it through its rightful means', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 28, NULL, 'They — upon them be peace — disliked the price of the biting dog, yet permitted the price of the hunting dog, and the sale of the herding dog is allowed. They disliked the price of the cat. They forbade buying what one knows to be stolen or taken by treachery until it has been returned to its rightful owners, who may then sell it. They permitted the sale of copies of the Quran.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'they upon them be peace disliked the price of the biting dog yet permitted the price of the hunting dog and the sale of the herding dog is allowed they disliked the price of the cat they forbade buying what one knows to be stolen or taken by treachery until it has been returned to its rightful owners who may then sell it they permitted the sale of copies of the quran', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 29, NULL, 'From the Messenger of Allah, upon him be peace, comes a general prohibition against the sale of water, of pasture (al-kala), and of fire. This prohibition bears upon the sale of what no one owns: water lying open in the wilderness, rainwater gathered there, and all such waters that belong to nobody, as well as the flame of a fire from which a man lights his lamp or takes a brand without diminishing it. However, if a man has dug a well on his own land, or possesses a flowing spring, a developed river, a cistern, or anything similar — including rainwater that has settled on his property, water stored in a vessel, or water carried on his back, his mount, or by any other means — then its sale is permitted. Likewise, if he has gathered pasture grass from the wild, uprooted it, or tended and watered it on land he owns, the sale of it is permitted. The same principle applies to fire: when it resides in something owned — firewood, charcoal, or any other material in which fire is kindled — its sale is permitted, for it becomes property among the recognized kinds of property.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'from the messenger of allah upon him be peace comes a general prohibition against the sale of water of pasture al kala and of fire this prohibition bears upon the sale of what no one owns water lying open in the wilderness rainwater gathered there and all such waters that belong to nobody as well as the flame of a fire from which a man lights his lamp or takes a brand without diminishing it however if a man has dug a well on his own land or possesses a flowing spring a developed river a cistern or anything similar including rainwater that has settled on his property water stored in a vessel or water carried on his back his mount or by any other means then its sale is permitted likewise if he has gathered pasture grass from the wild uprooted it or tended and watered it on land he owns the sale of it is permitted the same principle applies to fire when it resides in something owned firewood charcoal or any other material in which fire is kindled its sale is permitted for it becomes property among the recognized kinds of property', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 30, NULL, 'Buying from or selling to someone known for treachery, theft, or other wrongdoing carries no prohibition in itself — unless one knows that the specific item being purchased was itself stolen or taken by treachery. Where that knowledge is absent, the transaction is permissible. As has already been established, trade with polytheists is likewise permitted, provided one does not know that their goods were acquired by treachery or theft; the Muslim, however, bears the greater obligation to inquire.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'buying from or selling to someone known for treachery theft or other wrongdoing carries no prohibition in itself unless one knows that the specific item being purchased was itself stolen or taken by treachery where that knowledge is absent the transaction is permissible as has already been established trade with polytheists is likewise permitted provided one does not know that their goods were acquired by treachery or theft the muslim however bears the greater obligation to inquire', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 31, NULL, 'On the Prohibition of the Sale of Gharar', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'on the prohibition of the sale of gharar', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 32, NULL, 'Allah Almighty has said: ﴿وَلَا تَأْكُلُوا أَمْوَالَكُم بَيْنَكُم بِالْبَاطِلِ﴾ — "And do not consume one another''s wealth among yourselves unjustly." The Messenger of Allah, as transmitted by the pure Imams of the Ahl al-Bayt — upon them all be the prayers of Allah — prohibited the sale of gharar in general terms. The sale of gharar is every sale concluded over something unknown. The Messenger of Allah then specified several of its forms.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'allah almighty has said ولا تاكلوا اموالكم بينكم بالباطل and do not consume one anothers wealth among yourselves unjustly the messenger of allah as transmitted by the pure imams of the ahl al bayt upon them all be the prayers of allah prohibited the sale of gharar in general terms the sale of gharar is every sale concluded over something unknown the messenger of allah then specified several of its forms', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 33, NULL, 'Among them, he forbade the sale of habal al-habalah — the offspring of an offspring. This was a transaction practiced in the time of ignorance: a man would sell a commodity against the price of the offspring of a she-camel, to be paid once she had given birth and her young had itself produced young. Of the same kind is the sale of an animal''s offspring before it is born, for people of that era traded in what still lay in the wombs of camels and other beasts.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'among them he forbade the sale of habal al habalah the offspring of an offspring this was a transaction practiced in the time of ignorance a man would sell a commodity against the price of the offspring of a she camel to be paid once she had given birth and her young had itself produced young of the same kind is the sale of an animals offspring before it is born for people of that era traded in what still lay in the wombs of camels and other beasts', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 34, NULL, 'Among the forbidden transactions, the Prophet also prohibited the sale of al-madamin and al-malaqih. The malaqih are the embryos already described — sold while still in their mothers'' wombs. The madamin are what lies in the loins of stallions: people traded in whatever a stallion would sire over a stated period, whether once or a fixed number of times.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'among the forbidden transactions the prophet also prohibited the sale of al madamin and al malaqih the malaqih are the embryos already described sold while still in their mothers wombs the madamin are what lies in the loins of stallions people traded in whatever a stallion would sire over a stated period whether once or a fixed number of times', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 35, NULL, 'Also forbidden was the sale of al-mulamasah — the sale by touch. This occurs when a man sells a garment or some article that is folded so its inside cannot be seen, or when the mere touching of it with the hand is made to stand in for a proper inspection, on the condition that the buyer has no right to reconsider once he sees, unfolds, or spreads out the item. It also occurs when a seller says, "When you touch this commodity, the transaction between us is binding." The contract of sale, however, is made binding only by spoken agreement and by the parting of the two parties in mutual consent. Of the same kind is the touching of goods from behind a curtain, where the sale is concluded on that contact alone.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'also forbidden was the sale of al mulamasah the sale by touch this occurs when a man sells a garment or some article that is folded so its inside cannot be seen or when the mere touching of it with the hand is made to stand in for a proper inspection on the condition that the buyer has no right to reconsider once he sees unfolds or spreads out the item it also occurs when a seller says when you touch this commodity the transaction between us is binding the contract of sale however is made binding only by spoken agreement and by the parting of the two parties in mutual consent of the same kind is the touching of goods from behind a curtain where the sale is concluded on that contact alone', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 36, NULL, 'Also forbidden was the sale of al-munabadhah. This occurs when a man looks at a folded garment in another man''s hand and says, "I buy this from you, and when you throw it to me the sale between us is complete, with no right of withdrawal for either party" — or when each of the two throws a garment or some article to the other.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'also forbidden was the sale of al munabadhah this occurs when a man looks at a folded garment in another mans hand and says i buy this from you and when you throw it to me the sale between us is complete with no right of withdrawal for either party or when each of the two throws a garment or some article to the other', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 37, NULL, 'Among the sales the Prophet (may Allah bless him and his family) nullified were those in which a man concluded a bargain by saying simply, "This for this," without turning the goods over or examining them. Also nullified was the sale of pebbles — a practice of the pre-Islamic era in which the two parties sealed a contract by each throwing his pebble, making that throw the binding act of sale. He nullified all such sales.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'among the sales the prophet may allah bless him and his family nullified were those in which a man concluded a bargain by saying simply this for this without turning the goods over or examining them also nullified was the sale of pebbles a practice of the pre islamic era in which the two parties sealed a contract by each throwing his pebble making that throw the binding act of sale he nullified all such sales', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 38, NULL, 'He also prohibited the sale of al-wala and the giving of it as a gift, declaring that al-wala belongs only to those who hold it by lineage and is neither to be sold nor given away. He prohibited the sale of a slave on condition of keeping him before the slave had come into one''s possession, and likewise the sale of a stray camel or similar animal before it is found.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he also prohibited the sale of al wala and the giving of it as a gift declaring that al wala belongs only to those who hold it by lineage and is neither to be sold nor given away he prohibited the sale of a slave on condition of keeping him before the slave had come into ones possession and likewise the sale of a stray camel or similar animal before it is found', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 39, NULL, 'Al-Sadiq Jafar ibn Muhammad (ع) said: If such a stray animal — or anything like it among absent goods — is sold together with something present, such as a slave, a beast, a garment, or any other permissible item that is at hand, then the sale of that combination is permissible, provided that both seller and buyer know the stray or absent item. Upon its arrival, the price falls upon the present item that both parties have seen. Such a sale does not fall under the words of Allah Almighty, ﴿وَلَا تَأْكُلُوا أَمْوَالَكُمْ بَيْنَكُمْ بِالْبَاطِلِ﴾, "And do not consume one another''s wealth unjustly" (Al-Baqarah 188).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'al sadiq jafar ibn muhammad ع said if such a stray animal or anything like it among absent goods is sold together with something present such as a slave a beast a garment or any other permissible item that is at hand then the sale of that combination is permissible provided that both seller and buyer know the stray or absent item upon its arrival the price falls upon the present item that both parties have seen such a sale does not fall under the words of allah almighty ولا تاكلوا اموالكم بينكم بالباطل and do not consume one anothers wealth unjustly al baqarah 188', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 40, NULL, 'Likewise, if a man sells the milk still in the udder of his sheep together with a quantity already drawn from it that is lawful to sell, the sale is permissible, because the price falls upon the present portion that both parties have seen. Most sales are of this kind: the price rests upon what is seen, or upon the part that is seen and purchased while the greater portion remains concealed — as with houses, dwellings, garments, and animals. Only what is apparent is visible; what lies hidden is not. Yet the sale covers both the visible and the hidden, both what has been examined and what has not.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'likewise if a man sells the milk still in the udder of his sheep together with a quantity already drawn from it that is lawful to sell the sale is permissible because the price falls upon the present portion that both parties have seen most sales are of this kind the price rests upon what is seen or upon the part that is seen and purchased while the greater portion remains concealed as with houses dwellings garments and animals only what is apparent is visible what lies hidden is not yet the sale covers both the visible and the hidden both what has been examined and what has not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 41, NULL, 'It is permissible to buy the dust of mines with gold or silver, hand to hand, even if upon extraction it yields more or less than the price paid — because at the moment of purchase it was neither silver nor gold but merely dust. Selling it on deferred terms, however, is disliked.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'it is permissible to buy the dust of mines with gold or silver hand to hand even if upon extraction it yields more or less than the price paid because at the moment of purchase it was neither silver nor gold but merely dust selling it on deferred terms however is disliked', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 42, NULL, 'It is narrated from Ali that he disliked the sale of fish still in the water when they can be reached only by fishing. If a catch is already secured and can be had without hunting, however, selling it is permissible. The Prophet forbade the sale of wool upon the backs of sheep, and of their hides likewise, until the wool is shorn and the hide flayed. He forbade a man to sell his share of the spoils before he has received it, because he does not know what will come to him from it. The sale of sukuk — that is, written certificates of debt — is also forbidden.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'it is narrated from ali that he disliked the sale of fish still in the water when they can be reached only by fishing if a catch is already secured and can be had without hunting however selling it is permissible the prophet forbade the sale of wool upon the backs of sheep and of their hides likewise until the wool is shorn and the hide flayed he forbade a man to sell his share of the spoils before he has received it because he does not know what will come to him from it the sale of sukuk that is written certificates of debt is also forbidden', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 44, NULL, 'The Imams of the Prophet''s household narrated that he forbade, in general terms, the sale of fruits until their goodness becomes apparent. Jafar ibn Muhammad said that the ripening of fruits begins when they turn red or yellow. What the Prophet meant was their coming to soundness: if some portion of the fruit has reached that condition, the whole of it may be sold; if nothing has yet ripened, the sale falls under the principle already established concerning present and absent goods. If nothing has appeared that is free of what is objectionable, the sale is not permissible unless both parties agree to it — and if either of them moves to annul it, the sale is annulled. If one variety among several shows ripeness, that variety may be sold together with the others even where nothing of them has yet ripened, provided the whole is sold in a single transaction, all according to the principle already named.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the imams of the prophets household narrated that he forbade in general terms the sale of fruits until their goodness becomes apparent jafar ibn muhammad said that the ripening of fruits begins when they turn red or yellow what the prophet meant was their coming to soundness if some portion of the fruit has reached that condition the whole of it may be sold if nothing has yet ripened the sale falls under the principle already established concerning present and absent goods if nothing has appeared that is free of what is objectionable the sale is not permissible unless both parties agree to it and if either of them moves to annul it the sale is annulled if one variety among several shows ripeness that variety may be sold together with the others even where nothing of them has yet ripened provided the whole is sold in a single transaction all according to the principle already named', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 45, NULL, 'The Imams (عَلَيْهِمُ السَّلَامُ) said: when the fruit blooms, or part of it does, it may be sold together with whatever the same trees will bear of such fruit for a year or two afterward, so long as that is named and stated. If nothing comes forth in the future, the price falls upon what was present at the time of sale. This too rests upon the principle already mentioned.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the imams عليهم السلام said when the fruit blooms or part of it does it may be sold together with whatever the same trees will bear of such fruit for a year or two afterward so long as that is named and stated if nothing comes forth in the future the price falls upon what was present at the time of sale this too rests upon the principle already mentioned', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 46, NULL, 'The generality of scholars do not permit selling fruit for years in advance, on the grounds that such a sale constitutes gharar — an uncertain and deceptive transaction — yet they do permit selling fruit once part of it has shown soundness. The position is not consistent. Whatever soundness appears while the sale still encompasses the remainder falls under the same ruling, and that is precisely the point they denied: they objected that part of the price would rest upon fruit whose soundness had not yet begun, while they themselves allowed selling such fruit together with what had already become sound, with the price resting upon the sound portion. Their own concession reopens the very door they claimed to shut. Jafar ibn Muhammad said accordingly: it is permissible to sell fruit once its soundness, or the soundness of part of it, has begun — for a year or two afterward; if it does not come forth in that year, it comes forth in the next.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the generality of scholars do not permit selling fruit for years in advance on the grounds that such a sale constitutes gharar an uncertain and deceptive transaction yet they do permit selling fruit once part of it has shown soundness the position is not consistent whatever soundness appears while the sale still encompasses the remainder falls under the same ruling and that is precisely the point they denied they objected that part of the price would rest upon fruit whose soundness had not yet begun while they themselves allowed selling such fruit together with what had already become sound with the price resting upon the sound portion their own concession reopens the very door they claimed to shut jafar ibn muhammad said accordingly it is permissible to sell fruit once its soundness or the soundness of part of it has begun for a year or two afterward if it does not come forth in that year it comes forth in the next', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 47, NULL, 'The people''s duty is to follow the teaching of the Imams and to abandon dispute with them, for what issues from the Imams is itself a proof — whoever holds to it is spared any further search for evidence or witness.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the peoples duty is to follow the teaching of the imams and to abandon dispute with them for what issues from the imams is itself a proof whoever holds to it is spared any further search for evidence or witness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 48, NULL, 'The strongest argument those who reject the multi-year sale of fruit have been able to advance is an unspecified hadith they claim to narrate from the Prophet (may Allah bless him and his family), in which he forbade "the sale of years," without mentioning fruit or anything else. Even if that hadith is established, it is unspecified in its scope, and the Imams'' interpretation makes plain that its intent is not what the generality have supposed.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the strongest argument those who reject the multi year sale of fruit have been able to advance is an unspecified hadith they claim to narrate from the prophet may allah bless him and his family in which he forbade the sale of years without mentioning fruit or anything else even if that hadith is established it is unspecified in its scope and the imams interpretation makes plain that its intent is not what the generality have supposed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 49, NULL, 'If the hadith is taken as general, those who invoke it are bound to apply it to everything that falls within its scope — and it admits many meanings. Among them:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if the hadith is taken as general those who invoke it are bound to apply it to everything that falls within its scope and it admits many meanings among them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 50, NULL, 'In Arabic usage, "years" denotes times of hardship and adversity. The Arabs say, "The years have come upon us," meaning trials and distress have descended; and a year of drought and affliction is itself called "a year." On this reading, the prohibition would fall upon whatever is sold during times of hardship, rendering every transaction concluded in such a period void. In the figurative usage of the language, "the sale of years" may mean selling by the year and for years to come — which itself opens onto further meanings.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'in arabic usage years denotes times of hardship and adversity the arabs say the years have come upon us meaning trials and distress have descended and a year of drought and affliction is itself called a year on this reading the prohibition would fall upon whatever is sold during times of hardship rendering every transaction concluded in such a period void in the figurative usage of the language the sale of years may mean selling by the year and for years to come which itself opens onto further meanings', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 51, NULL, 'Given this range of possible interpretations, following what has come from the Imams with clear explanation is more deserving of acceptance — all the more so when the foundational principles attest to it and upon which the subsidiary rulings are built.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'given this range of possible interpretations following what has come from the imams with clear explanation is more deserving of acceptance all the more so when the foundational principles attest to it and upon which the subsidiary rulings are built', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 52, NULL, 'When fruit is sold before its soundness has become apparent, and the buyer accepts the terms, and neither party moves to cancel but both proceed, the sale is permissible — not forbidden — despite the reports of prohibition. Jafar ibn Muhammad said: The Messenger of Allah (may Allah bless him and his family) forbade the sale of fruits before their soundness appeared only because people were buying them while the fruit was still liable to perish. Blight might strike before the crop was complete and sound, and the disputes this caused were brought before the Messenger of Allah. When such disputes multiplied, he forbade the practice until soundness became clear; he did not declare it unlawful for them.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'when fruit is sold before its soundness has become apparent and the buyer accepts the terms and neither party moves to cancel but both proceed the sale is permissible not forbidden despite the reports of prohibition jafar ibn muhammad said the messenger of allah may allah bless him and his family forbade the sale of fruits before their soundness appeared only because people were buying them while the fruit was still liable to perish blight might strike before the crop was complete and sound and the disputes this caused were brought before the messenger of allah when such disputes multiplied he forbade the practice until soundness became clear he did not declare it unlawful for them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 53, NULL, 'He said: Whoever sells his fruit and reserves from it a known portion, that sale is permissible. Whoever makes a sale reserving an unknown portion, that sale is not permissible, because it was concluded over something unknown.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he said whoever sells his fruit and reserves from it a known portion that sale is permissible whoever makes a sale reserving an unknown portion that sale is not permissible because it was concluded over something unknown', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 54, NULL, 'He said: If the buyer sells the fruit before he gathers it, the sale is permissible.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he said if the buyer sells the fruit before he gathers it the sale is permissible', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 55, NULL, 'The Messenger of Allah (may Allah bless him and his family) forbade al-muzabana: the sale of dates still on the heads of the palms for a measured quantity of dates, and of grapes still on the vine for raisins. He ruled that grain may not be sold before it can be reaped in the customary manner. If it is sold for wheat, or on the condition that it be left standing, and the buyer then reaps it or leaves it until it ripens fully, there is no harm in that. Likewise, if it is bought for something other than wheat and then reaped or left to ripen, there is no harm in that either. It is therefore permissible to sell standing crops and fresh herbage when the quantity is known, the buyer taking one cutting or several where the plant grows back, while the root remains the seller''s once the cuttings are spent.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the messenger of allah may allah bless him and his family forbade al muzabana the sale of dates still on the heads of the palms for a measured quantity of dates and of grapes still on the vine for raisins he ruled that grain may not be sold before it can be reaped in the customary manner if it is sold for wheat or on the condition that it be left standing and the buyer then reaps it or leaves it until it ripens fully there is no harm in that likewise if it is bought for something other than wheat and then reaped or left to ripen there is no harm in that either it is therefore permissible to sell standing crops and fresh herbage when the quantity is known the buyer taking one cutting or several where the plant grows back while the root remains the sellers once the cuttings are spent', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 56, NULL, 'The Messenger of Allah (may Allah bless him and his family) said: Whoever buys palm trees already bearing fruit that has appeared, that fruit belongs to the seller unless the buyer stipulates otherwise. The same ruling applies to the sale of trees bearing fruit that has reached the stage the fruit of the palm reaches at the time of pollination: if the buyer does not stipulate it, the fruit belongs to the seller.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the messenger of allah may allah bless him and his family said whoever buys palm trees already bearing fruit that has appeared that fruit belongs to the seller unless the buyer stipulates otherwise the same ruling applies to the sale of trees bearing fruit that has reached the stage the fruit of the palm reaches at the time of pollination if the buyer does not stipulate it the fruit belongs to the seller', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 58, NULL, 'The Imams from the household of the Messenger of Allah (may Allah bless him and them all) narrated that he said, "مَنْ غَشَّنَا فَلَيْسَ مِنَّا" — that is, "Whoever cheats us is not one of us." He forbade cheating, treachery, deception, and beguilement in selling, and the breaking of pledges, and he commanded the fulfillment of contracts in selling, buying, marriage, and covenant.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the imams from the household of the messenger of allah may allah bless him and them all narrated that he said من غشنا فليس منا that is whoever cheats us is not one of us he forbade cheating treachery deception and beguilement in selling and the breaking of pledges and he commanded the fulfillment of contracts in selling buying marriage and covenant', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 59, NULL, 'The words "Whoever cheats us is not one of us" mean that such a person is not among those who follow the command of the Prophet and belong to his company. They do not mean that the act of cheating causes a person to leave Islam and fall into apostasy — for were that the case, the cheater would incur what the apostate incurs, namely death. Allah Almighty said, reporting the words of Ibrahim (ع): ﴿فَمَن تَبِعَنِي فَإِنَّهُ مِنِّي وَمَنْ عَصَانِي فَإِنَّكَ غَفُورٌ رَحِيمٌ﴾ — "Whoever follows me is of me, and whoever disobeys me, then You are Forgiving and Merciful." The one who cheats has likewise not followed the command of the Messenger of Allah and is therefore not of those who followed his command. Yet if he is a Muslim, he remains among those who followed the Prophet but disobeyed him in some of what he commanded, and his affair is referred to Allah Almighty: if He wills, He forgives him, and if He wills, He punishes him, as with other disobedient Muslims.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the words whoever cheats us is not one of us mean that such a person is not among those who follow the command of the prophet and belong to his company they do not mean that the act of cheating causes a person to leave islam and fall into apostasy for were that the case the cheater would incur what the apostate incurs namely death allah almighty said reporting the words of ibrahim ع فمن تبعني فانه مني ومن عصاني فانك غفور رحيم whoever follows me is of me and whoever disobeys me then you are forgiving and merciful the one who cheats has likewise not followed the command of the messenger of allah and is therefore not of those who followed his command yet if he is a muslim he remains among those who followed the prophet but disobeyed him in some of what he commanded and his affair is referred to allah almighty if he wills he forgives him and if he wills he punishes him as with other disobedient muslims', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 60, NULL, 'Al-Sadiq Jafar ibn Muhammad said that mixing two grades of food — or similar goods — the superior with the inferior, when done for the purpose of sale, constitutes cheating. His meaning was that cheating occurs when the superior grade is what is displayed to the buyer while the inferior is concealed. If both grades are shown together, however, or the inferior is displayed while the superior is kept back, that does not amount to cheating. Ali used to move through the markets of Kufa warning the people against this practice, saying, "Show the poorer part of your wares just as you show the good part of them."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'al sadiq jafar ibn muhammad said that mixing two grades of food or similar goods the superior with the inferior when done for the purpose of sale constitutes cheating his meaning was that cheating occurs when the superior grade is what is displayed to the buyer while the inferior is concealed if both grades are shown together however or the inferior is displayed while the superior is kept back that does not amount to cheating ali used to move through the markets of kufa warning the people against this practice saying show the poorer part of your wares just as you show the good part of them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 61, NULL, 'He forbade blowing into meat and said, "إِنَّمَا النَّفْخُ مِنَ الشَّيْطَانِ فَلَا تَنْفُخُوا فِي طَعَامٍ وَلَا شَرَابٍ" — that is, "Blowing is from the devil, so do not blow into food or drink." He permitted blowing to separate the hide from the flesh in skinning, but forbade blowing into the flesh itself for the reason already given: it is a form of cheating, since the blown air works into the sinews and the thin membranes beneath the skin, making the flesh appear fat when it is not. He likewise forbade mixing milk with water when the intention is to sell it, though for one who means to drink it himself there is no harm in doing so.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he forbade blowing into meat and said انما النفخ من الشيطان فلا تنفخوا في طعام ولا شراب that is blowing is from the devil so do not blow into food or drink he permitted blowing to separate the hide from the flesh in skinning but forbade blowing into the flesh itself for the reason already given it is a form of cheating since the blown air works into the sinews and the thin membranes beneath the skin making the flesh appear fat when it is not he likewise forbade mixing milk with water when the intention is to sell it though for one who means to drink it himself there is no harm in doing so', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 62, NULL, 'The Messenger of Allah (may Allah bless him and his family) forbade tatfif — the giving of short measure and short weight, taking more than one''s due while giving less than is owed. Whoever gives full measure, or more, to the one he sells to, or accepts less than his due from that person, has done well. Whoever takes exactly his right and renders the like has acted justly. Allah, exalted be His mention, said:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the messenger of allah may allah bless him and his family forbade tatfif the giving of short measure and short weight taking more than ones due while giving less than is owed whoever gives full measure or more to the one he sells to or accepts less than his due from that person has done well whoever takes exactly his right and renders the like has acted justly allah exalted be his mention said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 63, NULL, '﴿وَيْلٌ لِلْمُطَفِّفِينَ الَّذِينَ إِذَا اكْتَالُوا عَلَى النَّاسِ يَسْتَوْفُونَ وَإِذَا كَالُوهُمْ أَو وَزَنُوهُمْ يُخْسِرُونَ﴾', '', '﴿وَيْلٌ لِلْمُطَفِّفِينَ الَّذِينَ إِذَا اكْتَالُوا عَلَى النَّاسِ يَسْتَوْفُونَ وَإِذَا كَالُوهُمْ أَو وَزَنُوهُمْ يُخْسِرُونَ﴾', NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'ويل للمطففين الذين اذا اكتالوا علي الناس يستوفون واذا كالوهم او وزنوهم يخسرون', 'ويل للمطففين الذين اذا اكتالوا علي الناس يستوفون واذا كالوهم او وزنوهم يخسرون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 64, NULL, '"Woe to the defrauders, who, when they take measure from people, take in full, but when they measure or weigh for them, give less" (Al-Mutaffifin 1–3). The meaning is that when they receive they claim their full due, and when they give they fall short. This applies to matters of sale and exchange. As for the gift and voluntary charity, whoever renders it in full earns the greater reward, and if he falls short in it nothing is held against him; but where it is an obligation, he must render it in full.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'woe to the defrauders who when they take measure from people take in full but when they measure or weigh for them give less al mutaffifin 1 3 the meaning is that when they receive they claim their full due and when they give they fall short this applies to matters of sale and exchange as for the gift and voluntary charity whoever renders it in full earns the greater reward and if he falls short in it nothing is held against him but where it is an obligation he must render it in full', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 65, NULL, 'Ali instructed that care be taken in buying and selling with dinars and dirhams, and he ordered that no debased coin enter his treasury. The concern is with coin whose defect is concealed — detectable only by those with a practiced eye — while it passes freely among others. Debased coin that is widely recognized and openly known, however, traded at its proper rate, presents no difficulty; nor do known mintings that differ in value, nor coins of pure copper, nor any other currency that is familiar and free of obscurity. There is no harm in buying and selling with any of these. It is narrated from Jafar ibn Muhammad that he forbade the use of differing measures and weights within a single town, on account of the doubt and confusion such variation invites.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'ali instructed that care be taken in buying and selling with dinars and dirhams and he ordered that no debased coin enter his treasury the concern is with coin whose defect is concealed detectable only by those with a practiced eye while it passes freely among others debased coin that is widely recognized and openly known however traded at its proper rate presents no difficulty nor do known mintings that differ in value nor coins of pure copper nor any other currency that is familiar and free of obscurity there is no harm in buying and selling with any of these it is narrated from jafar ibn muhammad that he forbade the use of differing measures and weights within a single town on account of the doubt and confusion such variation invites', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 66, NULL, 'The Messenger of Allah (may Allah bless him and his family) forbade tasriyah: the practice of leaving a ewe or a milking camel unmilked for a day or two before a sale, so that milk accumulates in the udder and the animal appears to the buyer to be a generous producer. The buyer is deceived and harmed by the sight of the swollen udder.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the messenger of allah may allah bless him and his family forbade tasriyah the practice of leaving a ewe or a milking camel unmilked for a day or two before a sale so that milk accumulates in the udder and the animal appears to the buyer to be a generous producer the buyer is deceived and harmed by the sight of the swollen udder', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 67, NULL, 'The buyer therefore has three days — reckoned from the time he first milks the animal — in which to decide. If he wishes, he may keep it; if he wishes, he may return it, together with a sa of dates as compensation for the milk he drew from it. If he found little milk in the udder, nothing beyond that is owed.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the buyer therefore has three days reckoned from the time he first milks the animal in which to decide if he wishes he may keep it if he wishes he may return it together with a sa of dates as compensation for the milk he drew from it if he found little milk in the udder nothing beyond that is owed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 68, NULL, 'This right of return belongs to the option that attaches to the sale of animals, khiyar al-hayawan. The musarrat is returnable even when the buyer has already relinquished the three-day option, provided the seller knew of the defect before the sale and concealed it. If, however, the seller disclosed the matter before the sale — stating plainly how many days the milking had been withheld — and the buyer accepted those terms, then no right of return on account of the tasriyah remains. It remains only if the buyer discovers some separate defect beyond it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'this right of return belongs to the option that attaches to the sale of animals khiyar al hayawan the musarrat is returnable even when the buyer has already relinquished the three day option provided the seller knew of the defect before the sale and concealed it if however the seller disclosed the matter before the sale stating plainly how many days the milking had been withheld and the buyer accepted those terms then no right of return on account of the tasriyah remains it remains only if the buyer discovers some separate defect beyond it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 69, NULL, 'The Messenger of Allah (may Allah bless him and his family) forbade najsh in transactions, saying, "لَا تَدَابَرُوا وَلَا تَنَاجَشُوا" — that is, "Do not turn your backs upon one another, and do not drive up bids against one another." Those who turn their backs fall into severance, enmity, harshness, and estrangement; the prohibition carries the sense that no one should turn his back upon his brother in this way. Najsh is the practice whereby a person who has no intention of buying approaches a commodity and raises its stated price, not because he wishes to purchase it, but so that others nearby will hear him and raise their own bids in turn — inflating the price against the genuine buyer. It is a form of deception: the false bidder is taken as a reliable guide, and others follow his lead upward. On that ground, the practice was forbidden.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the messenger of allah may allah bless him and his family forbade najsh in transactions saying لا تدابروا ولا تناجشوا that is do not turn your backs upon one another and do not drive up bids against one another those who turn their backs fall into severance enmity harshness and estrangement the prohibition carries the sense that no one should turn his back upon his brother in this way najsh is the practice whereby a person who has no intention of buying approaches a commodity and raises its stated price not because he wishes to purchase it but so that others nearby will hear him and raise their own bids in turn inflating the price against the genuine buyer it is a form of deception the false bidder is taken as a reliable guide and others follow his lead upward on that ground the practice was forbidden', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 70, NULL, 'The Messenger of Allah (may Allah bless him and his family) forbade a townsman from selling on behalf of a Bedouin. The meaning is this: the Bedouin brings a commodity, entrusts it to the townsman to sell, and the townsman sells it without ever offering it openly in the market. That much is plain from the wording of the prohibition itself.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the messenger of allah may allah bless him and his family forbade a townsman from selling on behalf of a bedouin the meaning is this the bedouin brings a commodity entrusts it to the townsman to sell and the townsman sells it without ever offering it openly in the market that much is plain from the wording of the prohibition itself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 71, NULL, 'The prohibition does not apply, however, when the townsman cries the goods publicly, announces their price, makes that price known, and offers his counsel — then reports back to the owner what he has learned, whereupon the owner either directs him to sell or comes and sells the goods himself. In that case the prohibition is not engaged, because a command issued for an act ascribes that act to the one who commanded it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the prohibition does not apply however when the townsman cries the goods publicly announces their price makes that price known and offers his counsel then reports back to the owner what he has learned whereupon the owner either directs him to sell or comes and sells the goods himself in that case the prohibition is not engaged because a command issued for an act ascribes that act to the one who commanded it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 72, NULL, 'The principle is well established. It is said of the Messenger of Allah (may Allah bless him and his family) that he cut off the hand of a thief, stoned the married adulterer, and put to death those upon whom death was due — yet all of this was carried out by his command, not by his own hand. Likewise it is said, "The prince killed so-and-so" or "struck so-and-so," even when another performed the deed on his order.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the principle is well established it is said of the messenger of allah may allah bless him and his family that he cut off the hand of a thief stoned the married adulterer and put to death those upon whom death was due yet all of this was carried out by his command not by his own hand likewise it is said the prince killed so and so or struck so and so even when another performed the deed on his order', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 73, NULL, 'By the same reasoning, when the Bedouin orders the townsman to sell his goods, it is the Bedouin who has sold them. But if the townsman, or any other party, sells those goods without having been ordered to do so and without the owner''s leave, the sale is not permissible unless the owner afterward authorizes it. That is the scope of what the prohibition addressed.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'by the same reasoning when the bedouin orders the townsman to sell his goods it is the bedouin who has sold them but if the townsman or any other party sells those goods without having been ordered to do so and without the owners leave the sale is not permissible unless the owner afterward authorizes it that is the scope of what the prohibition addressed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 74, NULL, 'The Prophet ﷺ forbade going out to meet the rukban — the caravans and traders arriving with their goods — before they reach the city or marketplace where they intend to sell. The prohibition guards against two harms:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the prophet ﷺ forbade going out to meet the rukban the caravans and traders arriving with their goods before they reach the city or marketplace where they intend to sell the prohibition guards against two harms', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 75, NULL, 'The arriving merchants are wronged, since whoever rides out to meet them knows the prevailing prices and market values of which those sellers are themselves unaware. The townspeople who could not ride out are shut out from buying.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the arriving merchants are wronged since whoever rides out to meet them knows the prevailing prices and market values of which those sellers are themselves unaware the townspeople who could not ride out are shut out from buying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 76, NULL, 'There is also an element of deception in the practice, since the one who goes out holds knowledge of price and worth that the seller does not.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'there is also an element of deception in the practice since the one who goes out holds knowledge of price and worth that the seller does not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 77, NULL, 'Al-Sadiq Jafar ibn Muhammad fixed its measure: whoever goes out to meet incoming goods at a distance of a day''s journey or less falls within the prohibition; beyond that distance, the act is no longer counted as meeting them. And whenever goods are dressed up so that their price is raised with no benefit to the buyer, that is deceit (ghishsh), and it is forbidden.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'al sadiq jafar ibn muhammad fixed its measure whoever goes out to meet incoming goods at a distance of a days journey or less falls within the prohibition beyond that distance the act is no longer counted as meeting them and whenever goods are dressed up so that their price is raised with no benefit to the buyer that is deceit ghishsh and it is forbidden', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 78, NULL, 'Jafar ibn Muhammad was asked about a man who buys food and then sells the same measure of it in return. He said: "If he does not add to its price, there is no harm in it; but if he uses it to deceive the Muslims, there is no good in it, and it is not sound." He was also asked about a man who buys food by weight and finds in it more than he had paid for. He replied: "If the surplus is of the kind that people do not haggle over — the sort of variance that may ordinarily occur between two measurings — there is no harm in it. But if it is excessive, it is an error and must be returned to the seller, unless the seller is content to leave it with him."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'jafar ibn muhammad was asked about a man who buys food and then sells the same measure of it in return he said if he does not add to its price there is no harm in it but if he uses it to deceive the muslims there is no good in it and it is not sound he was also asked about a man who buys food by weight and finds in it more than he had paid for he replied if the surplus is of the kind that people do not haggle over the sort of variance that may ordinarily occur between two measurings there is no harm in it but if it is excessive it is an error and must be returned to the seller unless the seller is content to leave it with him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 79, NULL, 'From Ali: he permitted the buyer to ask the seller for a little more — to tip the balance in the buyer''s favor or to add to the measure — but only after the seller has already given the buyer his full due, and only as a request from the buyer. If the seller''s heart is content with it, he may do so, and it is wholesome for the buyer; if his heart is not content, the buyer has no right to compel him. Should the buyer stipulate such an increase as a condition within the contract of sale while it remains unspecified, the sale is void; if it is specified, however, the sale stands, and the known increase enters into the contract of measure and weight. Justice in this matter is what keeps to the truth, neither adding nor subtracting — and that is the fulfillment (al-wafa) that Allah Almighty commanded, where He says, and He is the most truthful of speakers:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'from ali he permitted the buyer to ask the seller for a little more to tip the balance in the buyers favor or to add to the measure but only after the seller has already given the buyer his full due and only as a request from the buyer if the sellers heart is content with it he may do so and it is wholesome for the buyer if his heart is not content the buyer has no right to compel him should the buyer stipulate such an increase as a condition within the contract of sale while it remains unspecified the sale is void if it is specified however the sale stands and the known increase enters into the contract of measure and weight justice in this matter is what keeps to the truth neither adding nor subtracting and that is the fulfillment al wafa that allah almighty commanded where he says and he is the most truthful of speakers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 80, NULL, '﴿أَوْفُوا الْكَيْلَ وَلَا تَكُونُوا مِنَ الْمُخْسِرِينَ ۝ وَزِنُوا بِالْقِسْطَاسِ الْمُسْتَقِيمِ ۝ وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ﴾', '', '﴿أَوْفُوا الْكَيْلَ وَلَا تَكُونُوا مِنَ الْمُخْسِرِينَ ۝ وَزِنُوا بِالْقِسْطَاسِ الْمُسْتَقِيمِ ۝ وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ﴾', NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'اوفوا الكيل ولا تكونوا من المخسرين وزنوا بالقسطاس المستقيم ولا تبخسوا الناس اشياءهم ولا تعثوا في الارض مفسدين', 'اوفوا الكيل ولا تكونوا من المخسرين وزنوا بالقسطاس المستقيم ولا تبخسوا الناس اشياءهم ولا تعثوا في الارض مفسدين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 81, NULL, '"Give full measure and be not of those who cause loss. Weigh with the straight balance (al-qistas). And do not defraud people of their things, nor go about the earth spreading corruption." (al-Shuara 181–183)', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'give full measure and be not of those who cause loss weigh with the straight balance al qistas and do not defraud people of their things nor go about the earth spreading corruption al shuara 181 183', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 82, NULL, 'Fulfillment is justice and truth, without increase or decrease. Shortchanging (al-bakhs) is to give less than is due, and skimping (al-tatfif) is to receive one''s full due yet give short to others, as Allah Almighty has said, and He is the most truthful of speakers:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'fulfillment is justice and truth without increase or decrease shortchanging al bakhs is to give less than is due and skimping al tatfif is to receive ones full due yet give short to others as allah almighty has said and he is the most truthful of speakers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 83, NULL, '﴿وَيْلٌ لِّلْمُطَفِّفِينَ ۝ الَّذِينَ إِذَا اكْتَالُوا عَلَى النَّاسِ يَسْتَوْفُونَ ۝ وَإِذَا كَالُوهُمْ أَوْ وَزَنُوهُمْ يُخْسِرُونَ﴾', '', '﴿وَيْلٌ لِّلْمُطَفِّفِينَ ۝ الَّذِينَ إِذَا اكْتَالُوا عَلَى النَّاسِ يَسْتَوْفُونَ ۝ وَإِذَا كَالُوهُمْ أَوْ وَزَنُوهُمْ يُخْسِرُونَ﴾', NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'ويل للمطففين الذين اذا اكتالوا علي الناس يستوفون واذا كالوهم او وزنوهم يخسرون', 'ويل للمطففين الذين اذا اكتالوا علي الناس يستوفون واذا كالوهم او وزنوهم يخسرون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 84, NULL, '"Woe to those who skimp, who, when they take by measure from people, take in full, but when they give to them by measure or by weight, give less." (al-Mutaffifin 1–3)', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'woe to those who skimp who when they take by measure from people take in full but when they give to them by measure or by weight give less al mutaffifin 1 3', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 86, NULL, 'The Imams of the Ahl al-Bayt (عَلَيْهِمُ السَّلَامُ) transmitted that the Prophet ﷺ forbade two conditions within a single sale. An example is a seller who says, "I sell you this commodity for such a price in cash, or for such a price on credit," leaving the choice to the buyer, so that whichever he takes — the lesser amount paid immediately or the greater amount deferred — is binding, and the contract closes on that basis. Such a sale is impermissible because the price remains indeterminate. The following are of the same kind:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the imams of the ahl al bayt عليهم السلام transmitted that the prophet ﷺ forbade two conditions within a single sale an example is a seller who says i sell you this commodity for such a price in cash or for such a price on credit leaving the choice to the buyer so that whichever he takes the lesser amount paid immediately or the greater amount deferred is binding and the contract closes on that basis such a sale is impermissible because the price remains indeterminate the following are of the same kind', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 87, NULL, 'Selling a thing for dinars on the condition that the seller receive their equivalent value in dirhams at a fixed rate. Selling on the condition that the other party in turn sells him some other thing — whether guaranteed or not, for immediate or deferred delivery. Selling for a fixed term at a set price, then raising the price each time the term is extended.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'selling a thing for dinars on the condition that the seller receive their equivalent value in dirhams at a fixed rate selling on the condition that the other party in turn sells him some other thing whether guaranteed or not for immediate or deferred delivery selling for a fixed term at a set price then raising the price each time the term is extended', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 88, NULL, 'All of this, and whatever resembles it, constitutes two conditions in one sale. The sale is corrupt when the two parties contract upon it and part upon it. If, however, what passed between them was negotiation only, and they afterward agreed on one of the two options — annulling the other and parting upon that single agreed term — the sale is permissible, and it stands as whatever they settled upon.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'all of this and whatever resembles it constitutes two conditions in one sale the sale is corrupt when the two parties contract upon it and part upon it if however what passed between them was negotiation only and they afterward agreed on one of the two options annulling the other and parting upon that single agreed term the sale is permissible and it stands as whatever they settled upon', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 89, NULL, 'They also narrated that he forbade profiting from what one does not yet guarantee (ribh ma lam yudman): something measured or weighed that the seller is owed by a debtor, or a provision due to come to him, which he sells before he has taken possession of it. Of the same kind is the craftsman who accepts a piece of work for a wage and then hands it to another to complete for less than he undertook it, pocketing the difference — having neither labored on it nor stood surety for it. If, however, he has done something to it, or contributed some part of the work himself, the surplus is lawful to him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'they also narrated that he forbade profiting from what one does not yet guarantee ribh ma lam yudman something measured or weighed that the seller is owed by a debtor or a provision due to come to him which he sells before he has taken possession of it of the same kind is the craftsman who accepts a piece of work for a wage and then hands it to another to complete for less than he undertook it pocketing the difference having neither labored on it nor stood surety for it if however he has done something to it or contributed some part of the work himself the surplus is lawful to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 90, NULL, 'Of the same kind is a man who rents a dwelling and then sublets it for more than he pays; this is not permitted. He is, however, allowed to sublet part of it for the same amount he himself pays and to live in the remainder. And if he has tended the property in some way — kept it up or attended to its affairs — the surplus becomes lawful to him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'of the same kind is a man who rents a dwelling and then sublets it for more than he pays this is not permitted he is however allowed to sublet part of it for the same amount he himself pays and to live in the remainder and if he has tended the property in some way kept it up or attended to its affairs the surplus becomes lawful to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 91, NULL, 'The same principle applies to a khan that a man rents and then opens for business: he hangs a curtain over its door, sweeps it, attends to its affairs, and sublets its rooms at a profit. In return for the care he has expended, there is no harm in that surplus.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the same principle applies to a khan that a man rents and then opens for business he hangs a curtain over its door sweeps it attends to its affairs and sublets its rooms at a profit in return for the care he has expended there is no harm in that surplus', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 92, NULL, 'The Messenger of Allah ﷺ is reported to have forbidden any sale joined to a loan (bay wa salaf) — as when a man says to another, "I will sell you such-and-such on condition that you lend me such-and-such," or "Lend me this sum on the understanding that I owe you so much." A sale contracted on that footing is void: the borrower owes only what was actually lent, and the sale is annulled. If, however, the loan was given without being made a condition of the sale, the sale stands unimpaired.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the messenger of allah ﷺ is reported to have forbidden any sale joined to a loan bay wa salaf as when a man says to another i will sell you such and such on condition that you lend me such and such or lend me this sum on the understanding that i owe you so much a sale contracted on that footing is void the borrower owes only what was actually lent and the sale is annulled if however the loan was given without being made a condition of the sale the sale stands unimpaired', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 93, NULL, 'They also narrated that he forbade selling what one does not possess (bay ma laysa indak) — as when a man bargains over something he does not yet have. If such a sale is contracted, the thing belongs to the buyer, and the buyer retains the option once he sees it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'they also narrated that he forbade selling what one does not possess bay ma laysa indak as when a man bargains over something he does not yet have if such a sale is contracted the thing belongs to the buyer and the buyer retains the option once he sees it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 94, NULL, 'Of the same kind is selling goods for guaranteed future delivery at a time when no such goods exist — grapes or fruit, for instance, in a season when none are available. This is the forbidden kali for kali: debt exchanged for debt, which is not permissible. The case runs as follows: a man hands another a sum of dinars for a specified quantity of food to be delivered at a set time; when the time arrives and no food can be found, he purchases it from a man who owes him a debt payable at a later date, and sets that food against a deferred price. This is not permissible, for it amounts to a debt nested within a debt.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'of the same kind is selling goods for guaranteed future delivery at a time when no such goods exist grapes or fruit for instance in a season when none are available this is the forbidden kali for kali debt exchanged for debt which is not permissible the case runs as follows a man hands another a sum of dinars for a specified quantity of food to be delivered at a set time when the time arrives and no food can be found he purchases it from a man who owes him a debt payable at a later date and sets that food against a deferred price this is not permissible for it amounts to a debt nested within a debt', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 95, NULL, 'Likewise, when a debt has fallen due and the two parties agree to extend the term in exchange for an increase in the amount owed, that too is unlawful. If, however, the debtor is released from part of the debt and pays the remainder early, before the term expires, there is no harm in that — for had the creditor remitted the whole debt to him, that would have been a good and praiseworthy act.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'likewise when a debt has fallen due and the two parties agree to extend the term in exchange for an increase in the amount owed that too is unlawful if however the debtor is released from part of the debt and pays the remainder early before the term expires there is no harm in that for had the creditor remitted the whole debt to him that would have been a good and praiseworthy act', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 96, NULL, 'Also counted among transactions of kali for kali is the case where a man owes another a debt and the creditor arranges for him to perform work against it by mutual agreement. Such an arrangement is void. The worker is entitled to the wage customary for someone of his station; if one or both parties have already acted on the agreement, any surplus is returned, or recovered where something remains outstanding. If, however, a fixed-term debt is settled early — before it falls due — in exchange for the remission of part of it, there is no harm in that.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'also counted among transactions of kali for kali is the case where a man owes another a debt and the creditor arranges for him to perform work against it by mutual agreement such an arrangement is void the worker is entitled to the wage customary for someone of his station if one or both parties have already acted on the agreement any surplus is returned or recovered where something remains outstanding if however a fixed term debt is settled early before it falls due in exchange for the remission of part of it there is no harm in that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 97, NULL, 'Of the same character is the case where a man hires a riding beast and then transfers that hire to another party: this is not permissible. Similarly, where a debt owed to a group of men is divided on the condition that each member collects the share falling to him, that too is impermissible, and whatever any one of them collects is pooled among them all. Any transaction that falls within this meaning — entering the category of debt exchanged for debt — belongs to the class of kali for kali.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'of the same character is the case where a man hires a riding beast and then transfers that hire to another party this is not permissible similarly where a debt owed to a group of men is divided on the condition that each member collects the share falling to him that too is impermissible and whatever any one of them collects is pooled among them all any transaction that falls within this meaning entering the category of debt exchanged for debt belongs to the class of kali for kali', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 98, NULL, 'Where two men each owe the other a debt, whether in foodstuffs or other goods, and neither knows the exact amount the other owes him, yet they mutually agree that each releases his fellow from what he owes in exchange for what is his own — there is no harm in that. It is a matter they have settled by mutual agreement, unspecified in amount, and it does not fall within the category of kali for kali.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'where two men each owe the other a debt whether in foodstuffs or other goods and neither knows the exact amount the other owes him yet they mutually agree that each releases his fellow from what he owes in exchange for what is his own there is no harm in that it is a matter they have settled by mutual agreement unspecified in amount and it does not fall within the category of kali for kali', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 99, NULL, 'The scholars permitted the sale of animals one for another, even one for more than its like. It is narrated that Ali sold a camel of his named Usayfir for twenty camels to be delivered at a future date — and this is permissible when the camels are described. They forbade the sale of meat for a live animal, and they forbade a man bidding over the bid of his brother (sawm al-rajul ala sawm akhihi). This prohibition applies once the seller has inclined toward concluding the sale; but the mere raising of offers in a transaction still open to public call, or one held open for bidding, is no harm. The Messenger of Allah ﷺ himself sold by auction to the highest bidder some of what he was commanded to sell. The scholars also permitted the resale at cost (tawliyah) of food before taking possession of it — in the purchase of one who buys fruits still on the trees, and in the sale of food by the seller''s own measure when the buyer is aware of this and trusts him in it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the scholars permitted the sale of animals one for another even one for more than its like it is narrated that ali sold a camel of his named usayfir for twenty camels to be delivered at a future date and this is permissible when the camels are described they forbade the sale of meat for a live animal and they forbade a man bidding over the bid of his brother sawm al rajul ala sawm akhihi this prohibition applies once the seller has inclined toward concluding the sale but the mere raising of offers in a transaction still open to public call or one held open for bidding is no harm the messenger of allah ﷺ himself sold by auction to the highest bidder some of what he was commanded to sell the scholars also permitted the resale at cost tawliyah of food before taking possession of it in the purchase of one who buys fruits still on the trees and in the sale of food by the sellers own measure when the buyer is aware of this and trusts him in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 100, NULL, 'The scholars forbade the hoarding of food (ihtikar), and it is narrated that the Messenger of Allah ﷺ was severe and stern on the matter. Al-Sadiq Jafar ibn Muhammad said that the Messenger of Allah was harsh in his reproof of Hakim ibn Hizam — a man of Quraysh of great wealth who, whenever food entered Madinah, would buy up all of it and hoard it to sell at whatever price he chose. He said: as for a man who buys food while it is plentiful among the people in order to store it and trade in it, there is no harm in that, so long as the people can still find what they need to buy. But when none is to be found, he has no right to hoard it against them and leave them to perish; he must bring it out and sell it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the scholars forbade the hoarding of food ihtikar and it is narrated that the messenger of allah ﷺ was severe and stern on the matter al sadiq jafar ibn muhammad said that the messenger of allah was harsh in his reproof of hakim ibn hizam a man of quraysh of great wealth who whenever food entered madinah would buy up all of it and hoard it to sell at whatever price he chose he said as for a man who buys food while it is plentiful among the people in order to store it and trade in it there is no harm in that so long as the people can still find what they need to buy but when none is to be found he has no right to hoard it against them and leave them to perish he must bring it out and sell it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 101, NULL, 'The scholars also forbade pricing above the prevailing rate of the place (al-tasir). Whoever departs from the local price is told: either sell at the people''s price, as they sell, or take your goods out of their market, so that you bring no inflation upon them.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the scholars also forbade pricing above the prevailing rate of the place al tasir whoever departs from the local price is told either sell at the peoples price as they sell or take your goods out of their market so that you bring no inflation upon them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 102, NULL, 'Ali was asked about an unjust ruler (sultan jair) who seizes a man and compels him, through that pressure, to sell his property — whether the man may afterward reclaim it. He said: No. The buyer did not compel him; on the contrary, the buyer did him a service by relieving him of harm through the purchase, provided the buyer himself applied no force and the compulsion came from the unjust ruler alone. A sale made under coercion is annulled only when the seller was directly coerced into it by the very person who bought — in such a case the seller may seek remedy against the one who forced him. But when it is only the unjust ruler who drove him to sell, and the seller, fearing punishment if he refused, sold to a buyer who neither compelled him nor was specifically designated by the ruler as the buyer, then the sale stands and cannot be revoked.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'ali was asked about an unjust ruler sultan jair who seizes a man and compels him through that pressure to sell his property whether the man may afterward reclaim it he said no the buyer did not compel him on the contrary the buyer did him a service by relieving him of harm through the purchase provided the buyer himself applied no force and the compulsion came from the unjust ruler alone a sale made under coercion is annulled only when the seller was directly coerced into it by the very person who bought in such a case the seller may seek remedy against the one who forced him but when it is only the unjust ruler who drove him to sell and the seller fearing punishment if he refused sold to a buyer who neither compelled him nor was specifically designated by the ruler as the buyer then the sale stands and cannot be revoked', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 103, NULL, 'It is narrated that the Messenger of Allah ﷺ instructed a man who had sold a house to place its price into something of like kind. This was a directive of discipline (tadib), for it has been related that when estates are sold and their proceeds are not reinvested in their like, that wealth comes to nothing. He also forbade buying and selling in the mosque, during the time of the Friday prayer, and before the rising of the sun. Al-Sadiq Jafar ibn Muhammad said that the second call to prayer on Friday — the one given before the Imam while he stands upon the pulpit — is what forbids buying and selling until the Friday prayer has been performed.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'it is narrated that the messenger of allah ﷺ instructed a man who had sold a house to place its price into something of like kind this was a directive of discipline tadib for it has been related that when estates are sold and their proceeds are not reinvested in their like that wealth comes to nothing he also forbade buying and selling in the mosque during the time of the friday prayer and before the rising of the sun al sadiq jafar ibn muhammad said that the second call to prayer on friday the one given before the imam while he stands upon the pulpit is what forbids buying and selling until the friday prayer has been performed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 105, NULL, 'Currency exchange is governed by strict rules. The Prophet ﷺ is reported to have cursed every party to a transaction involving riba:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'currency exchange is governed by strict rules the prophet ﷺ is reported to have cursed every party to a transaction involving riba', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 106, NULL, 'the one who consumes it the one who pays it the one who sells through it the one who buys through it the one who records it its two witnesses', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the one who consumes it the one who pays it the one who sells through it the one who buys through it the one who records it its two witnesses', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 107, NULL, 'He further declared that the consumer of riba will be raised on the Day of Resurrection as a madman. The Commander of the Believers, Ali, said that riba is among the major sins.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he further declared that the consumer of riba will be raised on the day of resurrection as a madman the commander of the believers ali said that riba is among the major sins', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 108, NULL, 'Allah Almighty said:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'allah almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 109, NULL, '﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَأْكُلُوا الرِّبَا أَضْعَافًا مُضَاعَفَةً وَاتَّقُوا اللَّهَ لَعَلَّكُمْ تُفْلِحُونَ﴾', '', '﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَأْكُلُوا الرِّبَا أَضْعَافًا مُضَاعَفَةً وَاتَّقُوا اللَّهَ لَعَلَّكُمْ تُفْلِحُونَ﴾', NULL, 3, 130, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'يا ايها الذين امنوا لا تاكلوا الربا اضعافا مضاعفه واتقوا الله لعلكم تفلحون', 'يا ايها الذين امنوا لا تاكلوا الربا اضعافا مضاعفه واتقوا الله لعلكم تفلحون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 110, NULL, '"O you who believe, do not devour riba, doubled and multiplied, and fear Allah, that you may prosper." (Al Imran 130)', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'o you who believe do not devour riba doubled and multiplied and fear allah that you may prosper al imran 130', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 111, NULL, 'Abu Abdullah al-Sadiq Jafar ibn Muhammad (ع) was asked about the words of Allah Almighty, ﴿يَمْحَقُ اللَّهُ الرِّبَا وَيُرْبِي الصَّدَقَاتِ﴾, "Allah blots out riba and causes acts of charity to grow." The question put to him was this: there are those who deal in riba and yet grow great in wealth — how then is it blotted out?', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'abu abdullah al sadiq jafar ibn muhammad ع was asked about the words of allah almighty يمحق الله الربا ويربي الصدقات allah blots out riba and causes acts of charity to grow the question put to him was this there are those who deal in riba and yet grow great in wealth how then is it blotted out', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 112, NULL, 'He said: "And what blotting could be more thorough than that of a single dirham of riba? If its owner repents of it, he returns it to its rightful owners and nothing of it remains to him; and if he withholds it and does not repent, He casts him into the Fire."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he said and what blotting could be more thorough than that of a single dirham of riba if its owner repents of it he returns it to its rightful owners and nothing of it remains to him and if he withholds it and does not repent he casts him into the fire', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 113, NULL, 'The people of the covenant (ahl al-dhimmah), it was held, are to be barred from dealing in riba and from practicing it openly. Abu Jafar Muhammad ibn Ali related that the Messenger of Allah (ع and his family) did not accept the jizyah from the people of the covenant until he had laid down certain conditions upon them: that they would not consume riba nor deal in it, nor eat the flesh of swine, nor marry their sisters, the daughters of their brothers, or the daughters of their sisters. Whoever among them violates these conditions today has forfeited the covenant of protection. For He, exalted be the Speaker, has said:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the people of the covenant ahl al dhimmah it was held are to be barred from dealing in riba and from practicing it openly abu jafar muhammad ibn ali related that the messenger of allah ع and his family did not accept the jizyah from the people of the covenant until he had laid down certain conditions upon them that they would not consume riba nor deal in it nor eat the flesh of swine nor marry their sisters the daughters of their brothers or the daughters of their sisters whoever among them violates these conditions today has forfeited the covenant of protection for he exalted be the speaker has said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 114, NULL, '﴿فَبِظُلْمٍ مِنَ الَّذِينَ هَادُوا حَرَّمْنَا عَلَيْهِمْ طَيِّبَاتٍ أُحِلَّتْ لَهُمْ وَبِصَدِّهِمْ عَنْ سَبِيلِ اللَّهِ كَثِيرًا ۝ وَأَخْذِهِمُ الرِّبَا وَقَدْ نُهُوا عَنْهُ وَأَكْلِهِمْ أَمْوَالَ النَّاسِ بِالْبَاطِلِ وَأَعْتَدْنَا لِلْكَافِرِينَ مِنْهُمْ عَذَابًا أَلِيمًا﴾', '', '﴿فَبِظُلْمٍ مِنَ الَّذِينَ هَادُوا حَرَّمْنَا عَلَيْهِمْ طَيِّبَاتٍ أُحِلَّتْ لَهُمْ وَبِصَدِّهِمْ عَنْ سَبِيلِ اللَّهِ كَثِيرًا ۝ وَأَخْذِهِمُ الرِّبَا وَقَدْ نُهُوا عَنْهُ وَأَكْلِهِمْ أَمْوَالَ النَّاسِ بِالْبَاطِلِ وَأَعْتَدْنَا لِلْكَافِرِينَ مِنْهُمْ عَذَابًا أَلِيمًا﴾', NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'فبظلم من الذين هادوا حرمنا عليهم طيبات احلت لهم وبصدهم عن سبيل الله كثيرا واخذهم الربا وقد نهوا عنه واكلهم اموال الناس بالباطل واعتدنا للكافرين منهم عذابا اليما', 'فبظلم من الذين هادوا حرمنا عليهم طيبات احلت لهم وبصدهم عن سبيل الله كثيرا واخذهم الربا وقد نهوا عنه واكلهم اموال الناس بالباطل واعتدنا للكافرين منهم عذابا اليما');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 115, NULL, 'Riba is forbidden under the Jews'' own Law, even though they deem it lawful for themselves. In the Arabic language, riba means increase. The wealth grew — raba al-mal yarbu — meaning it increased, and its owner makes it grow (yurbi) when he adds to it. From this same root, raised ground is called rabwah, for its rising above the surrounding land. Yet not every increase that comes from a lawful source, even one that follows this same pattern, falls within the riba that is forbidden. The forbidden riba is specifically what the Imams — may Allah bless them — have transmitted from the Messenger of Allah ﷺ: the exchange of measured or weighed goods at a disparity, kind against its own kind. Such an exchange is not permissible except like for like, hand to hand, with neither increase nor decrease on either side.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'riba is forbidden under the jews own law even though they deem it lawful for themselves in the arabic language riba means increase the wealth grew raba al mal yarbu meaning it increased and its owner makes it grow yurbi when he adds to it from this same root raised ground is called rabwah for its rising above the surrounding land yet not every increase that comes from a lawful source even one that follows this same pattern falls within the riba that is forbidden the forbidden riba is specifically what the imams may allah bless them have transmitted from the messenger of allah ﷺ the exchange of measured or weighed goods at a disparity kind against its own kind such an exchange is not permissible except like for like hand to hand with neither increase nor decrease on either side', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 116, NULL, 'The Messenger of Allah ﷺ said: "Gold for gold, and silver for silver, hand to hand and weight for weight; whoever increases or seeks increase has dealt in riba. And wheat for wheat, barley for barley, flour for flour, dates for dates, raisins for raisins, corn for corn, basket for basket, and rice for rice, measure for measure; whoever increases or seeks increase has dealt in riba."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the messenger of allah ﷺ said gold for gold and silver for silver hand to hand and weight for weight whoever increases or seeks increase has dealt in riba and wheat for wheat barley for barley flour for flour dates for dates raisins for raisins corn for corn basket for basket and rice for rice measure for measure whoever increases or seeks increase has dealt in riba', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 117, NULL, 'Muhammad ibn Ali said that no copper coin (fulus), nor anything else, may be introduced into an exchange of gold for gold or silver for silver as an addition to the weight.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'muhammad ibn ali said that no copper coin fulus nor anything else may be introduced into an exchange of gold for gold or silver for silver as an addition to the weight', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 118, NULL, 'Abu Abdullah Jafar ibn Muhammad said that no increase is permissible in such exchanges, even when one of the two kinds is of finer quality than the other. When gold is sold for gold, silver for silver, or any measured or weighed commodity for its like, the exchange is valid only weight for weight among things that are weighed, or measure for measure among things that are measured.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'abu abdullah jafar ibn muhammad said that no increase is permissible in such exchanges even when one of the two kinds is of finer quality than the other when gold is sold for gold silver for silver or any measured or weighed commodity for its like the exchange is valid only weight for weight among things that are weighed or measure for measure among things that are measured', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 119, NULL, 'Should a man trade refined gold (ibriz) of the purest grade for gold of the lowest grade, the exchange remains valid only weight for weight, so long as the name of gold still applies to both. The rule holds until a piece contains so much copper that copper predominates — until it is reckoned as copper and the name of gold no longer falls upon it. At that point it may be purchased with gold as copper is purchased, meaning at a disparity. The same principle governs silver against silver, and extends equally to everything that is measured or weighed.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'should a man trade refined gold ibriz of the purest grade for gold of the lowest grade the exchange remains valid only weight for weight so long as the name of gold still applies to both the rule holds until a piece contains so much copper that copper predominates until it is reckoned as copper and the name of gold no longer falls upon it at that point it may be purchased with gold as copper is purchased meaning at a disparity the same principle governs silver against silver and extends equally to everything that is measured or weighed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 120, NULL, 'When two different metals are joined in a single object — a decorated sword, a ring set with both — al-Sadiq Jafar ibn Muhammad (may Allah''s blessings be upon him) taught that it should be sold against the opposite kind: gold against silver, or silver against gold. It is sold at the higher value, until it is established that the price exceeds the worth of the precious metal contained in it, so that gold is matched against gold and silver against silver, weight for weight, while the remainder of the price falls upon the sword, the ring, or whatever the object may be.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'when two different metals are joined in a single object a decorated sword a ring set with both al sadiq jafar ibn muhammad may allahs blessings be upon him taught that it should be sold against the opposite kind gold against silver or silver against gold it is sold at the higher value until it is established that the price exceeds the worth of the precious metal contained in it so that gold is matched against gold and silver against silver weight for weight while the remainder of the price falls upon the sword the ring or whatever the object may be', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 121, NULL, 'He also said that it is permissible to take dirhams in place of dinars, and dinars in place of dirhams. When a man is owed dinars — whether as an advance, from a sale, or from any other rightful claim — he may receive dirhams instead, at their value or at whatever rate the two parties agree upon; and likewise, when he is owed dirhams, he may receive dinars in their place.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he also said that it is permissible to take dirhams in place of dinars and dinars in place of dirhams when a man is owed dinars whether as an advance from a sale or from any other rightful claim he may receive dirhams instead at their value or at whatever rate the two parties agree upon and likewise when he is owed dirhams he may receive dinars in their place', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 122, NULL, 'He said that exchange (sarf) is lawful only hand to hand. If a man buys dinars for dirhams, dirhams for dinars, gold for silver, silver for gold, or any portion of one for the other, he must not part from his counterpart until he has taken delivery. If the other party says, "Send a messenger and he will settle it for you," that offer should not be accepted. Instead the buyer should say, "Give and take," and remain with the man rather than leave him. If he does send a messenger along with the other party, he must instruct that messenger himself to take delivery on the spot before parting. Should either party depart before delivery is taken, the exchange between them is void.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he said that exchange sarf is lawful only hand to hand if a man buys dinars for dirhams dirhams for dinars gold for silver silver for gold or any portion of one for the other he must not part from his counterpart until he has taken delivery if the other party says send a messenger and he will settle it for you that offer should not be accepted instead the buyer should say give and take and remain with the man rather than leave him if he does send a messenger along with the other party he must instruct that messenger himself to take delivery on the spot before parting should either party depart before delivery is taken the exchange between them is void', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 123, NULL, 'Whoever repays a loan of dirhams or dinars with something better than what was owed has done nothing wrong, provided the improvement springs from the borrower''s own willing generosity and was not stipulated as a condition at the time the loan was made.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'whoever repays a loan of dirhams or dinars with something better than what was owed has done nothing wrong provided the improvement springs from the borrowers own willing generosity and was not stipulated as a condition at the time the loan was made', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 125, NULL, 'The pure Imams of the household of the Messenger of Allah ﷺ transmitted his prohibition of any disparity in the exchange of goods of the same kind, where those goods are measured or weighed, as has already been noted. Whoever buys something for another quantity of its own kind may take no excess on either side. When the two kinds differ, however, disparity between them is permitted — just as it is permitted between silver and gold, or between iron and comparable metals whose kinds differ — so long as both belong to what is customarily weighed or measured.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the pure imams of the household of the messenger of allah ﷺ transmitted his prohibition of any disparity in the exchange of goods of the same kind where those goods are measured or weighed as has already been noted whoever buys something for another quantity of its own kind may take no excess on either side when the two kinds differ however disparity between them is permitted just as it is permitted between silver and gold or between iron and comparable metals whose kinds differ so long as both belong to what is customarily weighed or measured', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 126, NULL, 'On this basis, al-Sadiq Jafar ibn Muhammad (may Allah''s blessings be upon him) ruled as follows:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'on this basis al sadiq jafar ibn muhammad may allahs blessings be upon him ruled as follows', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 127, NULL, 'It is not permissible to sell a sa of almonds for two sa''s of almonds, nor a sa of dates for two sa''s of dates. It is permissible to sell a sa of wheat for two sa''s of dates, and a sa of dates for two sa''s of raisins.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'it is not permissible to sell a sa of almonds for two sas of almonds nor a sa of dates for two sas of dates it is permissible to sell a sa of wheat for two sas of dates and a sa of dates for two sas of raisins', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 128, NULL, 'Foodstuffs and the dried fruits of the land answer to one rule: when the two kinds differ, a disparity between them causes no harm, provided the exchange is hand to hand. On deferred terms, such an exchange is not lawful.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'foodstuffs and the dried fruits of the land answer to one rule when the two kinds differ a disparity between them causes no harm provided the exchange is hand to hand on deferred terms such an exchange is not lawful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 129, NULL, 'Barley and wheat are a single kind, so a disparity between them is not permitted. Likewise, wheat, flour, and sawiq may be exchanged only measure for measure.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'barley and wheat are a single kind so a disparity between them is not permitted likewise wheat flour and sawiq may be exchanged only measure for measure', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 130, NULL, 'It was said to him that there is a surplus in the grain itself. He answered that it carries a cost — the milling and the other labor of preparation. It was said that this was so. He said that the one is therefore set against the other.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'it was said to him that there is a surplus in the grain itself he answered that it carries a cost the milling and the other labor of preparation it was said that this was so he said that the one is therefore set against the other', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 131, NULL, 'The Master said that the Messenger of Allah (may Allah bless him and his family) forbade the sale of fresh, moist dates for dried dates, because when the moist dates dry they diminish in measure. He permitted the sale of garments one for another — one garment for more than one. The Master also said that the Messenger of Allah forbade the sale of food for food by guesswork, without measure, but permitted the exchange of bread for flour, and vinegar for vinegar even when their kinds differ, and the molasses of sugar cane for the honey of bees, like for like, hand to hand.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the master said that the messenger of allah may allah bless him and his family forbade the sale of fresh moist dates for dried dates because when the moist dates dry they diminish in measure he permitted the sale of garments one for another one garment for more than one the master also said that the messenger of allah forbade the sale of food for food by guesswork without measure but permitted the exchange of bread for flour and vinegar for vinegar even when their kinds differ and the molasses of sugar cane for the honey of bees like for like hand to hand', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 133, NULL, 'The pure Imams of the household of the Messenger of Allah ﷺ narrated that the two parties to a transaction retain the right to withdraw until they part by mutual consent. Al-Sadiq Jafar ibn Muhammad explained that this parting is the parting of their bodies from the place in which they concluded the sale. He related that his father (رض) bought a piece of land, and when he wished to make the purchase binding upon himself, he rose, walked a few steps, and then returned — intending by this to render the sale binding. He said that the Messenger of Allah (may Allah bless him and his family) said that Muslims are bound by their conditions, except a condition that contradicts the Book of Allah, mighty and majestic.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the pure imams of the household of the messenger of allah ﷺ narrated that the two parties to a transaction retain the right to withdraw until they part by mutual consent al sadiq jafar ibn muhammad explained that this parting is the parting of their bodies from the place in which they concluded the sale he related that his father رض bought a piece of land and when he wished to make the purchase binding upon himself he rose walked a few steps and then returned intending by this to render the sale binding he said that the messenger of allah may allah bless him and his family said that muslims are bound by their conditions except a condition that contradicts the book of allah mighty and majestic', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 134, NULL, 'He then recalled the story of Barirah, a bondwoman belonging to people who had drawn up a contract of emancipation with her. She approached one of the wives of the Messenger of Allah ﷺ seeking help with her emancipation payment, and that wife said to her: "I will pay what you owe and set you free." Her masters, however, refused: "We will not sell her to one who frees her unless the right of patronage (al-wala) remains with us." When the matter was brought to the Messenger of Allah ﷺ, he said: "Buy her and free her, for patronage belongs to the one who frees." He then addressed the people and said: "What is the matter with people who stipulate conditions not found in the Book of Allah? Every condition that contradicts the Book of Allah is void." Whoever makes a sale and stipulates a permissible condition in the contract, that condition is binding; but whoever stipulates what is not permissible, the condition is void. This is precisely what the Messenger of Allah ﷺ applied in the case of Barirah: he refused to honour the condition of patronage set by those who sold her, having already declared that patronage belongs to the one who frees.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he then recalled the story of barirah a bondwoman belonging to people who had drawn up a contract of emancipation with her she approached one of the wives of the messenger of allah ﷺ seeking help with her emancipation payment and that wife said to her i will pay what you owe and set you free her masters however refused we will not sell her to one who frees her unless the right of patronage al wala remains with us when the matter was brought to the messenger of allah ﷺ he said buy her and free her for patronage belongs to the one who frees he then addressed the people and said what is the matter with people who stipulate conditions not found in the book of allah every condition that contradicts the book of allah is void whoever makes a sale and stipulates a permissible condition in the contract that condition is binding but whoever stipulates what is not permissible the condition is void this is precisely what the messenger of allah ﷺ applied in the case of barirah he refused to honour the condition of patronage set by those who sold her having already declared that patronage belongs to the one who frees', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 135, NULL, 'Scholars differed on the question of a sale made with an attached condition. One group held that whoever sells something and stipulates a condition in the contract renders that condition void, arguing from a report transmitted in general terms from the Messenger of Allah ﷺ that he forbade a sale coupled with a condition. A second group held that both the sale and the condition are binding, citing the report that the Messenger of Allah ﷺ purchased a camel from Jabir ibn Abdullah al-Ansari during one of his expeditions on the condition that Jabir could ride it back to Madinah. A third group held that the sale stands but the condition is void, citing the account of Barirah already mentioned.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'scholars differed on the question of a sale made with an attached condition one group held that whoever sells something and stipulates a condition in the contract renders that condition void arguing from a report transmitted in general terms from the messenger of allah ﷺ that he forbade a sale coupled with a condition a second group held that both the sale and the condition are binding citing the report that the messenger of allah ﷺ purchased a camel from jabir ibn abdullah al ansari during one of his expeditions on the condition that jabir could ride it back to madinah a third group held that the sale stands but the condition is void citing the account of barirah already mentioned', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 136, NULL, 'The teaching transmitted from the People of the House, may Allah''s blessings be upon them, resolves all of this, establishes the sound position, and makes the matter clear. The condition stipulated by Barirah''s masters was voided only because they had stipulated something impermissible: the Messenger of Allah ﷺ had already ruled that patronage belongs to the one who grants freedom, yet they stipulated that patronage remain with themselves rather than with the one who freed her. As for the Messenger of Allah''s ﷺ permitting Jabir ibn Abdullah the condition of riding the camel he had sold — that was a lawful arrangement, neither forbidding what is permitted nor making lawful what is forbidden. As for the report that he forbade a sale coupled with a condition, if that report is sound, it is a general statement whose intended meaning is a condition that is itself unlawful and impermissible. On this basis, the People of the House (عَلَيْهِمُ السَّلَامُ) held that any sale containing a condition must be examined: if the condition is lawful, it stands and is binding; if it is unlawful, it is neither binding nor enforced — while the sale itself remains valid in either case.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the teaching transmitted from the people of the house may allahs blessings be upon them resolves all of this establishes the sound position and makes the matter clear the condition stipulated by barirahs masters was voided only because they had stipulated something impermissible the messenger of allah ﷺ had already ruled that patronage belongs to the one who grants freedom yet they stipulated that patronage remain with themselves rather than with the one who freed her as for the messenger of allahs ﷺ permitting jabir ibn abdullah the condition of riding the camel he had sold that was a lawful arrangement neither forbidding what is permitted nor making lawful what is forbidden as for the report that he forbade a sale coupled with a condition if that report is sound it is a general statement whose intended meaning is a condition that is itself unlawful and impermissible on this basis the people of the house عليهم السلام held that any sale containing a condition must be examined if the condition is lawful it stands and is binding if it is unlawful it is neither binding nor enforced while the sale itself remains valid in either case', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 137, NULL, 'Al-Sadiq Jafar ibn Muhammad (may Allah''s blessings be upon him) made this plain: if a man sells a bondwoman and stipulates in the contract that the buyer shall not sell her, shall not give her away, and that she shall not pass by inheritance should he die, then the first two conditions — that she not be sold and not be given away — are binding, because those are his to grant. The third condition, however, that she not be inherited, is void, because Allah, mighty and majestic, has ordained inheritance for a man''s heirs; whoever stipulates that they shall have no share contradicts what Allah has decreed. This position of the People of the House diverges from what the generality of scholars have held, yet its proof is evident.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'al sadiq jafar ibn muhammad may allahs blessings be upon him made this plain if a man sells a bondwoman and stipulates in the contract that the buyer shall not sell her shall not give her away and that she shall not pass by inheritance should he die then the first two conditions that she not be sold and not be given away are binding because those are his to grant the third condition however that she not be inherited is void because allah mighty and majestic has ordained inheritance for a mans heirs whoever stipulates that they shall have no share contradicts what allah has decreed this position of the people of the house diverges from what the generality of scholars have held yet its proof is evident', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 138, NULL, 'Al-Sadiq Jafar ibn Muhammad also said: whoever buys something on the understanding that he holds an option over it for a fixed term, and the thing perishes within that term before the buyer has made his choice, the loss falls upon the seller''s property, and the buyer must swear that he had neither chosen the goods nor accepted them. If he refuses to swear, the sale becomes binding upon him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'al sadiq jafar ibn muhammad also said whoever buys something on the understanding that he holds an option over it for a fixed term and the thing perishes within that term before the buyer has made his choice the loss falls upon the sellers property and the buyer must swear that he had neither chosen the goods nor accepted them if he refuses to swear the sale becomes binding upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 139, NULL, 'The Master said that the Messenger of Allah (may Allah bless him and his family) granted the buyer of an animal a three-day option, whether or not it had been stipulated in the contract, and that the seller holds no such option once the two parties have parted. Should the buyer perform some new act upon the animal before the three days expire, the sale becomes binding upon him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the master said that the messenger of allah may allah bless him and his family granted the buyer of an animal a three day option whether or not it had been stipulated in the contract and that the seller holds no such option once the two parties have parted should the buyer perform some new act upon the animal before the three days expire the sale becomes binding upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 140, NULL, 'The boy asked what was meant by such an act. The Master said it was as when the animal is a bondwoman and the buyer touches her, or kisses her, or looks upon what had been forbidden to him before the purchase — and likewise if he has intercourse with her. If he offers her for sale, he is made to swear that he did not offer her intending to keep her, but only wishing to inspect the matter before returning her if he should choose to do so.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the boy asked what was meant by such an act the master said it was as when the animal is a bondwoman and the buyer touches her or kisses her or looks upon what had been forbidden to him before the purchase and likewise if he has intercourse with her if he offers her for sale he is made to swear that he did not offer her intending to keep her but only wishing to inspect the matter before returning her if he should choose to do so', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 141, NULL, 'The Master said that if a buyer sells what he purchased while his option still stands, then:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the master said that if a buyer sells what he purchased while his option still stands then', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 142, NULL, 'If he had called a witness beforehand, stating that he had chosen the goods and was satisfied with them, the surplus of the price belongs to him. If he called no witness, he must swear to that effect, and if he refuses the oath, the surplus belongs to the seller.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if he had called a witness beforehand stating that he had chosen the goods and was satisfied with them the surplus of the price belongs to him if he called no witness he must swear to that effect and if he refuses the oath the surplus belongs to the seller', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 143, NULL, 'The Master said that whoever buys a commodity and goes off to bring the price, but does not return with it until three days have passed, leaves the seller with a choice:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the master said that whoever buys a commodity and goes off to bring the price but does not return with it until three days have passed leaves the seller with a choice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 144, NULL, 'He may demand the price. He may sell the goods to another. He may hold the goods back and rescind the sale.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he may demand the price he may sell the goods to another he may hold the goods back and rescind the sale', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 145, NULL, 'After the three days, the buyer holds no standing claim upon the goods.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'after the three days the buyer holds no standing claim upon the goods', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 146, NULL, 'If a buyer holds an option for a fixed term, spends on the goods, and draws profit or use from them, then later chooses to return the purchase, he must return whatever he gained from it — while what he spent upon it remains his to recover. And if a buyer purchases a commodity on the understanding that the option belongs to another party, the option rests with the one for whom it was made.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if a buyer holds an option for a fixed term spends on the goods and draws profit or use from them then later chooses to return the purchase he must return whatever he gained from it while what he spent upon it remains his to recover and if a buyer purchases a commodity on the understanding that the option belongs to another party the option rests with the one for whom it was made', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 148, NULL, 'The saying of the Messenger of Allah (may Allah bless him and his family), "Whoever deceives us is not of us," together with its explanation and his prohibition of deceit, has already been mentioned. Whoever knows of a defect in what he sells and conceals it has committed deceit. Equally, no one who knows of a defect should hide it from the buyer, for the Messenger of Allah (may Allah bless him and his family) said that sincere counsel is part of religion. He also said that it is not lawful for a Muslim to sell to his brother goods in which he knows there is a defect without making it plain, nor is it lawful for one who knows of it to keep it hidden.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the saying of the messenger of allah may allah bless him and his family whoever deceives us is not of us together with its explanation and his prohibition of deceit has already been mentioned whoever knows of a defect in what he sells and conceals it has committed deceit equally no one who knows of a defect should hide it from the buyer for the messenger of allah may allah bless him and his family said that sincere counsel is part of religion he also said that it is not lawful for a muslim to sell to his brother goods in which he knows there is a defect without making it plain nor is it lawful for one who knows of it to keep it hidden', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 149, NULL, 'Whoever wishes to sell free of liability for a defect must disclose that defect to the buyer and state it clearly. It does not suffice to say, "I sell to you with disavowal (baraa)," without naming the specific defect from which he disclaims liability, informing the buyer of it, and showing it to him. If he does no more than say, "I sell to you with disavowal," and the buyer later encounters a defect, the buyer may hold him to account for it — provided the buyer had not already seen and accepted it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'whoever wishes to sell free of liability for a defect must disclose that defect to the buyer and state it clearly it does not suffice to say i sell to you with disavowal baraa without naming the specific defect from which he disclaims liability informing the buyer of it and showing it to him if he does no more than say i sell to you with disavowal and the buyer later encounters a defect the buyer may hold him to account for it provided the buyer had not already seen and accepted it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 150, NULL, 'If a group buys a commodity and divides it among themselves, and one of them finds a defect in the portion that fell to him, he may claim its diminished value from the seller. If the commodity remains undivided, or if a single buyer purchased the whole and finds a defect in part of it, he likewise claims the value of the defect — unless the defective part is the very face of the commodity, in which case he may return the whole if he chooses. If the commodity is of the kind sold by weight or measure, or is otherwise uniform — cotton, linen, silk, foodstuffs, and the like — and a defect is found in part of it, the seller replaces that part with an equal quantity of the same kind.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if a group buys a commodity and divides it among themselves and one of them finds a defect in the portion that fell to him he may claim its diminished value from the seller if the commodity remains undivided or if a single buyer purchased the whole and finds a defect in part of it he likewise claims the value of the defect unless the defective part is the very face of the commodity in which case he may return the whole if he chooses if the commodity is of the kind sold by weight or measure or is otherwise uniform cotton linen silk foodstuffs and the like and a defect is found in part of it the seller replaces that part with an equal quantity of the same kind', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 151, NULL, 'When the buyer discovers a defect and the seller says to him, "Keep it as it is, or return it — the choice is yours," the buyer has no recourse beyond that choice: he may keep the goods or return them. If he asks instead for the value of the defect, he has no right to it unless the seller agrees.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'when the buyer discovers a defect and the seller says to him keep it as it is or return it the choice is yours the buyer has no recourse beyond that choice he may keep the goods or return them if he asks instead for the value of the defect he has no right to it unless the seller agrees', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 152, NULL, 'If a buyer acquires goods, then causes some new damage to them or introduces a defect of his own, and subsequently discovers an old defect for which the seller had not absolved him, he may hold the seller to account — but he must first pay the seller the value of the damage he himself caused. He may then return the goods if he wishes, or keep them along with their defect. If, however, the seller deliberately concealed the defect from him, the buyer may return the goods and owes nothing for whatever diminishment occurred in his hands. This right of return rests on clear evidence of the concealment; in the absence of such evidence, the seller swears that he neither knew of the defect nor practiced any deception regarding it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if a buyer acquires goods then causes some new damage to them or introduces a defect of his own and subsequently discovers an old defect for which the seller had not absolved him he may hold the seller to account but he must first pay the seller the value of the damage he himself caused he may then return the goods if he wishes or keep them along with their defect if however the seller deliberately concealed the defect from him the buyer may return the goods and owes nothing for whatever diminishment occurred in his hands this right of return rests on clear evidence of the concealment in the absence of such evidence the seller swears that he neither knew of the defect nor practiced any deception regarding it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 153, NULL, 'When a buyer presses a claim against the seller on account of a defect, the seller may require him to take an oath. The buyer swears:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'when a buyer presses a claim against the seller on account of a defect the seller may require him to take an oath the buyer swears', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 154, NULL, 'that he had no knowledge of the defect before the purchase, nor at the moment of it; that since learning of it he has neither put the goods to use, nor derived profit from them, nor permitted anyone else their use.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'that he had no knowledge of the defect before the purchase nor at the moment of it that since learning of it he has neither put the goods to use nor derived profit from them nor permitted anyone else their use', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 155, NULL, 'If he takes that oath, he is entitled to return the goods, or to receive the assessed value of the defect where both parties agree to that settlement, or where the case is one in which such a value is owed. If, on the other hand, he refuses the oath — or it emerges that he was aware of the defect beforehand, or that he profited from the goods after discovering it, or that he offered them for sale — then the purchase stands binding upon him and he has no further claim against the seller.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if he takes that oath he is entitled to return the goods or to receive the assessed value of the defect where both parties agree to that settlement or where the case is one in which such a value is owed if on the other hand he refuses the oath or it emerges that he was aware of the defect beforehand or that he profited from the goods after discovering it or that he offered them for sale then the purchase stands binding upon him and he has no further claim against the seller', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 156, NULL, 'It is related from the Commander of the Believers, Ali (may Allah''s blessings be upon him), and from Muhammad ibn Ali ibn al-Husayn and Jafar ibn Muhammad (may Allah''s blessings be upon them), concerning a man who buys a bondwoman, has intercourse with her, and then discovers a defect in her: he may not return her, but he may claim the assessed value of the defect from the seller — unless he finds her to be pregnant, in which case he returns her and recovers half of a tenth of her value along with her.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'it is related from the commander of the believers ali may allahs blessings be upon him and from muhammad ibn ali ibn al husayn and jafar ibn muhammad may allahs blessings be upon them concerning a man who buys a bondwoman has intercourse with her and then discovers a defect in her he may not return her but he may claim the assessed value of the defect from the seller unless he finds her to be pregnant in which case he returns her and recovers half of a tenth of her value along with her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 157, NULL, 'They also said that a purchased slave is returnable under the warranty — al-uhda — for any of the following conditions arising within one year while in the buyer''s possession:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'they also said that a purchased slave is returnable under the warranty al uhda for any of the following conditions arising within one year while in the buyers possession', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 158, NULL, 'madness leprosy vitiligo al-qarn', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'madness leprosy vitiligo al qarn', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 159, NULL, 'Should any of these appear within that year, the liability falls upon the seller. So too does the calamity of death. This warranty applies specifically to slaves, not to other animals.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'should any of these appear within that year the liability falls upon the seller so too does the calamity of death this warranty applies specifically to slaves not to other animals', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 160, NULL, 'It is further reported from Ali (may Allah''s blessings be upon him) that he said: the warranty on a slave covers the gravest disease for one year, and the calamity of death for three days.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'it is further reported from ali may allahs blessings be upon him that he said the warranty on a slave covers the gravest disease for one year and the calamity of death for three days', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 161, NULL, 'Jafar ibn Muhammad (may Allah''s blessings be upon him) said: if the seller, at the moment of concluding the sale, explicitly disclaims to the buyer both the year''s warranty and the three-day option for all animals, and the buyer releases him from these, that release is binding and the buyer has no recourse to either.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'jafar ibn muhammad may allahs blessings be upon him said if the seller at the moment of concluding the sale explicitly disclaims to the buyer both the years warranty and the three day option for all animals and the buyer releases him from these that release is binding and the buyer has no recourse to either', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 162, NULL, 'On this basis, the practice among people today is to write into the deeds for the purchase of slaves a disclaimer of the year''s warranty and of the three-day option, and into the deeds for other animals a disclaimer of the three-day option. Al-Mahdi (may Allah''s blessings be upon him), according to what has been transmitted, ordered that this be written into the deeds so that people would not later turn against one another and draw out their disputes. Whoever consents to the disclaimer is bound by it; whoever dislikes it is not compelled to accept it. And if the seller is content to omit the disclaimer entirely, he is not compelled to include it, and the rules described previously apply to him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'on this basis the practice among people today is to write into the deeds for the purchase of slaves a disclaimer of the years warranty and of the three day option and into the deeds for other animals a disclaimer of the three day option al mahdi may allahs blessings be upon him according to what has been transmitted ordered that this be written into the deeds so that people would not later turn against one another and draw out their disputes whoever consents to the disclaimer is bound by it whoever dislikes it is not compelled to accept it and if the seller is content to omit the disclaimer entirely he is not compelled to include it and the rules described previously apply to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 163, NULL, 'Al-Sadiq Jafar ibn Muhammad (may Allah''s blessings be upon him) said: there is no warranty in a sale concluded with disavowal, nor in the sale of an inheritance — neither the year''s warranty nor the three-day option.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'al sadiq jafar ibn muhammad may allahs blessings be upon him said there is no warranty in a sale concluded with disavowal nor in the sale of an inheritance neither the years warranty nor the three day option', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 164, NULL, 'The Marketplace: Honest Earning, Trade, and Property', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the marketplace honest earning trade and property', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 165, NULL, 'On the Sale of Murabaha', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'on the sale of murabaha', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 166, NULL, 'Selling by murabaha — in which a price is set as the cost of purchase together with a stated profit — is permissible when both elements are declared plainly. Yet the pure Imams of the Ahl al-Bayt of the Messenger of Allah disliked the practice of conducting such a sale on the condition that the profit be fixed as a proportion of the price, because that resemblance to riba. When a man says, "I will sell you this commodity at a profit of one-tenth of its price," or any similar formula, the increase is no longer simply a profit; it has become an addition folded into the price itself, and in that form it comes to resemble riba. This is precisely the form of sale practiced among the merchants of Iraq, who say, "I will sell you this commodity for dowzadeh," or "for yazda" — Persian words meaning "for every ten, twelve," or "for every ten, one."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'selling by murabaha in which a price is set as the cost of purchase together with a stated profit is permissible when both elements are declared plainly yet the pure imams of the ahl al bayt of the messenger of allah disliked the practice of conducting such a sale on the condition that the profit be fixed as a proportion of the price because that resemblance to riba when a man says i will sell you this commodity at a profit of one tenth of its price or any similar formula the increase is no longer simply a profit it has become an addition folded into the price itself and in that form it comes to resemble riba this is precisely the form of sale practiced among the merchants of iraq who say i will sell you this commodity for dowzadeh or for yazda persian words meaning for every ten twelve or for every ten one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 167, NULL, 'Abu Abdullah Jafar ibn Muhammad related that his father once received goods from Egypt. He prepared food and invited the merchants to his home so that they might purchase the goods. He ordered that they be fed, and they ate; then he ordered the goods to be brought out before them. The merchants said, "We will take them from you at dowzadeh." He replied, "No. I bought these goods for ten thousand dinars, and I will sell them to you for twelve thousand." They said, "We accept," and he handed the goods over to them.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'abu abdullah jafar ibn muhammad related that his father once received goods from egypt he prepared food and invited the merchants to his home so that they might purchase the goods he ordered that they be fed and they ate then he ordered the goods to be brought out before them the merchants said we will take them from you at dowzadeh he replied no i bought these goods for ten thousand dinars and i will sell them to you for twelve thousand they said we accept and he handed the goods over to them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 168, NULL, 'Whoever buys goods and then incurs additional expenses — freight, the cost of containers, and the like — may sell them by Murabaha and reckon those expenses into the price. He should state that the goods stand him at such and such in total. He must not say that he bought them for a sum that already includes his added expenditure, for that would be a lie and would draw him toward the boundary of riba, unless he sets out the purchase price, the profit, and the expenditure separately, or combines them openly by saying, "This stands me at such and such in total." He must not claim he bought a thing for more than he actually paid.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'whoever buys goods and then incurs additional expenses freight the cost of containers and the like may sell them by murabaha and reckon those expenses into the price he should state that the goods stand him at such and such in total he must not say that he bought them for a sum that already includes his added expenditure for that would be a lie and would draw him toward the boundary of riba unless he sets out the purchase price the profit and the expenditure separately or combines them openly by saying this stands me at such and such in total he must not claim he bought a thing for more than he actually paid', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 169, NULL, 'He was asked about a man who bought a quantity of merchandise, divided it into parts, and wished to sell each part by Murabaha for what it had cost him within the whole. He replied that this was not permissible, unless the seller made clear to the buyer that he himself had apportioned the cost in that way.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he was asked about a man who bought a quantity of merchandise divided it into parts and wished to sell each part by murabaha for what it had cost him within the whole he replied that this was not permissible unless the seller made clear to the buyer that he himself had apportioned the cost in that way', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 170, NULL, 'He was asked about a man who bought a commodity on a deferred term of payment — that is, upon nazira — and then sold it on by Murabaha without informing the buyer of that deferment, and the buyer afterward came to learn of it. He replied that the buyer was entitled, if he wished, to the same term of deferment the seller had enjoyed, unless the seller had said to him at the time of the contract, "On this day it stands me at such a price, and I sell it to you for such a price," and had not phrased it as a fixed rate of profit.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he was asked about a man who bought a commodity on a deferred term of payment that is upon nazira and then sold it on by murabaha without informing the buyer of that deferment and the buyer afterward came to learn of it he replied that the buyer was entitled if he wished to the same term of deferment the seller had enjoyed unless the seller had said to him at the time of the contract on this day it stands me at such a price and i sell it to you for such a price and had not phrased it as a fixed rate of profit', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 171, NULL, 'If a man buys a garment for one dinar yet pays for it in dirhams, or agrees a price in dirhams and pays with a dinar, he may sell it by Murabaha at the price he paid, without specifying which currency he actually tendered. This rests on the ruling that it is permissible to discharge a debt of gold with silver, and a debt of silver with gold. Once he has purchased the article at the agreed price of gold or silver, and that price has become a binding obligation between him and the seller, whatever he afterward pays in settlement of it is a lawful discharge — and the sale holds firm against the one who made it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if a man buys a garment for one dinar yet pays for it in dirhams or agrees a price in dirhams and pays with a dinar he may sell it by murabaha at the price he paid without specifying which currency he actually tendered this rests on the ruling that it is permissible to discharge a debt of gold with silver and a debt of silver with gold once he has purchased the article at the agreed price of gold or silver and that price has become a binding obligation between him and the seller whatever he afterward pays in settlement of it is a lawful discharge and the sale holds firm against the one who made it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 172, NULL, 'He said that a man who buys his own slave and then sells him by Murabaha may do so, because such use does not diminish the slave''s value and is not something for which compensation is owed. The same applies to:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he said that a man who buys his own slave and then sells him by murabaha may do so because such use does not diminish the slaves value and is not something for which compensation is owed the same applies to', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 173, NULL, 'a man who buys a beast and rides it, a man who buys a slave and puts him to work, or a man who buys a garment and wears it —', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'a man who buys a beast and rides it a man who buys a slave and puts him to work or a man who buys a garment and wears it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 174, NULL, 'provided, in each case, that the use causes no wear that lessens the article''s worth. To disclose such use to the buyer is the safer course for the seller where his religion is concerned; yet if he does not disclose it, no liability falls upon him, as the narrations have come down.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'provided in each case that the use causes no wear that lessens the articles worth to disclose such use to the buyer is the safer course for the seller where his religion is concerned yet if he does not disclose it no liability falls upon him as the narrations have come down', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 175, NULL, 'On al-salam', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'on al salam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 176, NULL, 'Al-Baqarah: 282رِّجَالِكُمْ ۖ فَإِن لَّمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌۭ وَٱمْرَأَتَانِ مِمَّن تَرْضَوْنَ مِنَ ٱلشُّهَدَآءِ', '', 'رِّجَالِكُمْ ۖ فَإِن لَّمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌۭ وَٱمْرَأَتَانِ مِمَّن تَرْضَوْنَ مِنَ ٱلشُّهَدَآءِ', 'Al-Baqarah: 282', 2, 282, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'al baqarah 282رجالكم فان لم يكونا رجلين فرجل وامراتان ممن ترضون من الشهداء', 'رجالكم فان لم يكونا رجلين فرجل وامراتان ممن ترضون من الشهداء');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 177, NULL, 'Allah, mighty and majestic, said: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنْتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى فَاكْتُبُوهُ﴾, "O you who believe, when you contract a debt for a specified term, write it down" (al-Baqarah: 282). The pure Imams of the family of the Messenger of Allah narrated that he said: Whoever enters into a sale for an unknown term, or for an unspecified thing, has not made a true sale.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'allah mighty and majestic said يا ايها الذين امنوا اذا تداينتم بدين الي اجل مسمي فاكتبوه o you who believe when you contract a debt for a specified term write it down al baqarah 282 the pure imams of the family of the messenger of allah narrated that he said whoever enters into a sale for an unknown term or for an unspecified thing has not made a true sale', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 178, NULL, 'They taught that al-salam rests on four conditions, and that the contract is void if any one of them is absent or breached:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'they taught that al salam rests on four conditions and that the contract is void if any one of them is absent or breached', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 179, NULL, 'The goods must be described by a known and precise description. Their measure must be named — by volume or by weight, according to the nature of the goods. The place of delivery must be specified. The term at which delivery falls due must be stated.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the goods must be described by a known and precise description their measure must be named by volume or by weight according to the nature of the goods the place of delivery must be specified the term at which delivery falls due must be stated', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 180, NULL, 'They further held that a salam contract is not concluded unless the price is paid before the two parties part from the place where they contracted. If the price is not handed over at that session, the transaction becomes a debt exchanged for a debt — and the Messenger of Allah forbade that.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'they further held that a salam contract is not concluded unless the price is paid before the two parties part from the place where they contracted if the price is not handed over at that session the transaction becomes a debt exchanged for a debt and the messenger of allah forbade that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 181, NULL, 'Al-Sadiq Jafar ibn Muhammad held that whoever enters a salam contract for the produce of a particular village or named locality may not do so until that locality''s soundness becomes apparent. Where no locality is specified, however, the salam is permissible and stands as a binding obligation on the one who received the advance. He also permitted a salam contract with a seller who does not yet possess what he has undertaken to deliver, provided that, at the time of guarantee, the goods lie within his means when delivery falls due — so that he may then acquire them, pay for them, and hand them over. The Imams further permitted salam contracts in animals, where the animal is sufficiently known and precisely described.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'al sadiq jafar ibn muhammad held that whoever enters a salam contract for the produce of a particular village or named locality may not do so until that localitys soundness becomes apparent where no locality is specified however the salam is permissible and stands as a binding obligation on the one who received the advance he also permitted a salam contract with a seller who does not yet possess what he has undertaken to deliver provided that at the time of guarantee the goods lie within his means when delivery falls due so that he may then acquire them pay for them and hand them over the imams further permitted salam contracts in animals where the animal is sufficiently known and precisely described', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 182, NULL, 'Jafar ibn Muhammad was asked about a man who enters a salam contract for a known thing and then receives either less than it or more than it. He said that if this is by mutual consent, there is no harm in it. The Imams permitted salam in well-known, described garments, and held that if a man takes back his capital — in whole or in part — without anything added to it, that is permissible; but if he takes back something more, it is not.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'jafar ibn muhammad was asked about a man who enters a salam contract for a known thing and then receives either less than it or more than it he said that if this is by mutual consent there is no harm in it the imams permitted salam in well known described garments and held that if a man takes back his capital in whole or in part without anything added to it that is permissible but if he takes back something more it is not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 183, NULL, 'Jafar ibn Muhammad was asked about the holder of a salam obligation who pays the price to the entitled party, and that party then says to him, "Buy it for yourself and take what is due to you." He disliked this, and said that the man should have another person carry out the purchase, and should not himself undertake both the buying for his own benefit and the taking of delivery from himself.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'jafar ibn muhammad was asked about the holder of a salam obligation who pays the price to the entitled party and that party then says to him buy it for yourself and take what is due to you he disliked this and said that the man should have another person carry out the purchase and should not himself undertake both the buying for his own benefit and the taking of delivery from himself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 184, NULL, 'He was then asked about a holder of a salam obligation that falls due who cannot find the specific thing owed but finds others of its kind — beasts or goods — and hands those over at their value. He said there was no harm in that. Likewise, if a man had sold food for dirhams and when the term arrived said he had no dirhams but offered food instead, there was no harm in the creditor accepting food from him, since his right was in dirhams and he might take with them whatever he wished. The Imams held it reprehensible to enter salam contracts for things that do not keep, such as fresh fruit, meat, and the like.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he was then asked about a holder of a salam obligation that falls due who cannot find the specific thing owed but finds others of its kind beasts or goods and hands those over at their value he said there was no harm in that likewise if a man had sold food for dirhams and when the term arrived said he had no dirhams but offered food instead there was no harm in the creditor accepting food from him since his right was in dirhams and he might take with them whatever he wished the imams held it reprehensible to enter salam contracts for things that do not keep such as fresh fruit meat and the like', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 185, NULL, 'On the Conditions and Rulings Governing Sale Contracts', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'on the conditions and rulings governing sale contracts', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 186, NULL, 'Al-Sadiq Jafar ibn Muhammad said: whoever buys a slave and finds money with him, that money belongs to the seller, unless the buyer stipulated otherwise in the contract. If he did stipulate it, the seller has no claim to it, even if it exceeds the price of the slave. Whatever a slave possesses and holds in his hand at the time of sale is reckoned as part of his price. This does not fall under the forbidden riba, particularly in any of the following circumstances:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'al sadiq jafar ibn muhammad said whoever buys a slave and finds money with him that money belongs to the seller unless the buyer stipulated otherwise in the contract if he did stipulate it the seller has no claim to it even if it exceeds the price of the slave whatever a slave possesses and holds in his hand at the time of sale is reckoned as part of his price this does not fall under the forbidden riba particularly in any of the following circumstances', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 187, NULL, 'the exchange involves goods on both sides; the thing being sold is a tangible object and the slave was bought with goods; the slave was himself a tangible object bought with currency; the slave was himself currency bought with a tangible object.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the exchange involves goods on both sides the thing being sold is a tangible object and the slave was bought with goods the slave was himself a tangible object bought with currency the slave was himself currency bought with a tangible object', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 188, NULL, 'In all such cases the contract of sale is valid, and there is no disagreement on the point.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'in all such cases the contract of sale is valid and there is no disagreement on the point', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 189, NULL, 'The form of a sale that is soundly contracted, and on which there is no dispute, is as follows. One man says to another, "Sell me this slave of yours" — or "this commodity of yours" — "for such and such," naming something lawful as the price, and the other replies, "I have sold it to you." Alternatively, the seller may begin by saying, "I have sold you this for such and such," and the buyer answers, "I have bought it," or "I accept this purchase." By these words the sale is concluded between them.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the form of a sale that is soundly contracted and on which there is no dispute is as follows one man says to another sell me this slave of yours or this commodity of yours for such and such naming something lawful as the price and the other replies i have sold it to you alternatively the seller may begin by saying i have sold you this for such and such and the buyer answers i have bought it or i accept this purchase by these words the sale is concluded between them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 190, NULL, 'After the contract is made, both parties retain the right of option for as long as they remain together in the place where they contracted, and have not yet parted bodily from one another. Either party may retract before they separate, and the sale is annulled by that retraction. The sale is completed only by their parting, as described above.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'after the contract is made both parties retain the right of option for as long as they remain together in the place where they contracted and have not yet parted bodily from one another either party may retract before they separate and the sale is annulled by that retraction the sale is completed only by their parting as described above', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 191, NULL, 'Jafar ibn Muhammad addressed the case of two contracting parties in which the buyer claims, "I have handed you the price," while the commodity is still in his possession, and the seller says, "You handed me nothing." The ruling turns on the nature of the transaction:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'jafar ibn muhammad addressed the case of two contracting parties in which the buyer claims i have handed you the price while the commodity is still in his possession and the seller says you handed me nothing the ruling turns on the nature of the transaction', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 192, NULL, 'If it is a transaction of the kind in which witnesses are customarily called and testimony is ordinarily taken, the buyer''s claim of payment is not accepted without proof. In that case the seller must swear that he did not receive the price and obtained nothing of it from the buyer in any way. If it is a transaction of the kind in which witnesses are not customarily called, the word of the party in whose hand the thing lies prevails, together with his oath.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if it is a transaction of the kind in which witnesses are customarily called and testimony is ordinarily taken the buyers claim of payment is not accepted without proof in that case the seller must swear that he did not receive the price and obtained nothing of it from the buyer in any way if it is a transaction of the kind in which witnesses are not customarily called the word of the party in whose hand the thing lies prevails together with his oath', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 193, NULL, 'The Master said: if a seller later claims he erred in a sale — that he did not know the true price at the time, or intended otherwise and was mistaken — the matter is examined by reference to value. If the gap between his selling price and the true value falls within the range by which people commonly differ in transactions of that kind, the sale stands and his claim is set aside. If the disparity is great, exceeding what people ordinarily tolerate, the sale is returned to him; and the buyer may require him to swear that he did indeed err, as he claims.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the master said if a seller later claims he erred in a sale that he did not know the true price at the time or intended otherwise and was mistaken the matter is examined by reference to value if the gap between his selling price and the true value falls within the range by which people commonly differ in transactions of that kind the sale stands and his claim is set aside if the disparity is great exceeding what people ordinarily tolerate the sale is returned to him and the buyer may require him to swear that he did indeed err as he claims', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 194, NULL, 'From Abu Jafar Muhammad ibn Ali: he was asked about a man who appointed an agent to sell his goods, where the agent claimed to have sold them at an undervalue, and the owner sought to undo the sale and recover the goods. He said: the matter is again examined by reference to value. If the value on the day of sale matched the price at which it was sold, or the difference fell within the range by which people commonly differ, the sale is valid and cannot be undone. If the value was greater by a margin beyond what people ordinarily tolerate, the sale is returned. Should the buyer wish to put the owner — who seeks the return — to his oath, swearing that he neither consented to his agent''s sale nor ratified it after learning of the loss, that is the buyer''s right; and if the owner refuses to swear, the buyer has no further claim.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'from abu jafar muhammad ibn ali he was asked about a man who appointed an agent to sell his goods where the agent claimed to have sold them at an undervalue and the owner sought to undo the sale and recover the goods he said the matter is again examined by reference to value if the value on the day of sale matched the price at which it was sold or the difference fell within the range by which people commonly differ the sale is valid and cannot be undone if the value was greater by a margin beyond what people ordinarily tolerate the sale is returned should the buyer wish to put the owner who seeks the return to his oath swearing that he neither consented to his agents sale nor ratified it after learning of the loss that is the buyers right and if the owner refuses to swear the buyer has no further claim', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 195, NULL, 'Abu Jafar Muhammad ibn Ali was asked about two agents jointly appointed to sell something, where one of them sold it without the other. He said that the sale was not valid, unless authority had been granted to whichever of them might act alone — when acting alone — or to both together, when acting together.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'abu jafar muhammad ibn ali was asked about two agents jointly appointed to sell something where one of them sold it without the other he said that the sale was not valid unless authority had been granted to whichever of them might act alone when acting alone or to both together when acting together', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 196, NULL, 'Abu Abdullah Jafar ibn Muhammad was asked about a man bargaining over a slave girl whose owner sold her to him at his discretion, saying, "I have sold her to you for whatever price you wish." The buyer accepted the sale, then named a price the seller found unsatisfactory and considered too low. He said that her value on the day of the sale must be examined. If the price offered falls short of that value, the buyer must make up the difference, for although the seller left the price to the buyer''s judgment, that judgment may not be exercised against the seller unjustly.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'abu abdullah jafar ibn muhammad was asked about a man bargaining over a slave girl whose owner sold her to him at his discretion saying i have sold her to you for whatever price you wish the buyer accepted the sale then named a price the seller found unsatisfactory and considered too low he said that her value on the day of the sale must be examined if the price offered falls short of that value the buyer must make up the difference for although the seller left the price to the buyers judgment that judgment may not be exercised against the seller unjustly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 197, NULL, 'He said that whatever a judge or a ruler sells in settlement of an obligatory debt, or on behalf of a child, or in matters resembling these, carries no warranty or liability of recourse upon the one who ordered the sale. The sale is made from the property of the one against whom it is ordered, as his own obligation, even if he possesses no other wealth.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he said that whatever a judge or a ruler sells in settlement of an obligatory debt or on behalf of a child or in matters resembling these carries no warranty or liability of recourse upon the one who ordered the sale the sale is made from the property of the one against whom it is ordered as his own obligation even if he possesses no other wealth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 198, NULL, 'He said that whoever trades with the property of an orphan — whether as executor, guardian, or in any other capacity — if he gains a profit, the profit belongs to the orphan; and if he suffers a loss, the loss falls upon the one who traded with it, and he must make it good from the orphan''s funds, because he overstepped his bounds in doing so.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he said that whoever trades with the property of an orphan whether as executor guardian or in any other capacity if he gains a profit the profit belongs to the orphan and if he suffers a loss the loss falls upon the one who traded with it and he must make it good from the orphans funds because he overstepped his bounds in doing so', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 199, NULL, 'He also addressed the case of a slave whose master gave him money, which the slave used to purchase his own freedom, and whose master subsequently learned of it. In that situation, the master reclaims the money the slave received, and the slave remains in his ownership, the case reverting to the condition it was in before. This applies when the money had been earned by the slave and came to him without his master''s permission. If, however, the master had released that money to him, made him a gift of something, or it had reached him through a lawful channel, and he used it to buy his freedom, then the purchase stands. A slave may also enter into a contract of manumission — mukataba — paying its installments out of his earnings; once he has paid the full amount stipulated upon him, he is freed.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he also addressed the case of a slave whose master gave him money which the slave used to purchase his own freedom and whose master subsequently learned of it in that situation the master reclaims the money the slave received and the slave remains in his ownership the case reverting to the condition it was in before this applies when the money had been earned by the slave and came to him without his masters permission if however the master had released that money to him made him a gift of something or it had reached him through a lawful channel and he used it to buy his freedom then the purchase stands a slave may also enter into a contract of manumission mukataba paying its installments out of his earnings once he has paid the full amount stipulated upon him he is freed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 200, NULL, 'It has been narrated from the Imams that when a man dies leaving no heir but a slave he owns, the slave is purchased out of the estate — provided his master consents to the sale — and the remainder of the estate is then given to him as his inheritance. If the master refuses to sell, the slave does not inherit, and the inheritance passes to the public treasury, there being no other heir.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'it has been narrated from the imams that when a man dies leaving no heir but a slave he owns the slave is purchased out of the estate provided his master consents to the sale and the remainder of the estate is then given to him as his inheritance if the master refuses to sell the slave does not inherit and the inheritance passes to the public treasury there being no other heir', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 201, NULL, 'He also addressed the sale of a house for a house, a share for a share, a quarter for a quarter, and the sale of a part of any such thing for a part of another: all of this is permissible, so long as both parties know precisely what they are exchanging.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he also addressed the sale of a house for a house a share for a share a quarter for a quarter and the sale of a part of any such thing for a part of another all of this is permissible so long as both parties know precisely what they are exchanging', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 202, NULL, 'From the Commander of the Faithful, Ali: he gave judgment in the case of two men who had together bought a commodity from a single seller. After the sale was concluded, both left to fetch the price. The first to return paid his share, and Ali ruled that he was entitled to take the goods from the seller. When the second man returned and paid the first half of the price, he became a partner in the goods.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'from the commander of the faithful ali he gave judgment in the case of two men who had together bought a commodity from a single seller after the sale was concluded both left to fetch the price the first to return paid his share and ali ruled that he was entitled to take the goods from the seller when the second man returned and paid the first half of the price he became a partner in the goods', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 203, NULL, 'A further case was narrated concerning a woman of Quraysh who held a large sum of money in trust. Two men came to her, deposited the whole amount, and said, "Do not release it to either one of us without the other." Some time later, one of them returned bearing a sign that had been agreed between him and his companion. He presented it to her and said, "He has sent me to collect the money, and this is the token between him and you." She released the money to him, and he departed with it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'a further case was narrated concerning a woman of quraysh who held a large sum of money in trust two men came to her deposited the whole amount and said do not release it to either one of us without the other some time later one of them returned bearing a sign that had been agreed between him and his companion he presented it to her and said he has sent me to collect the money and this is the token between him and you she released the money to him and he departed with it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 204, NULL, 'The second man then came and demanded his share. She said, "Your companion has already taken it. He brought your message and the token — such and such — that was agreed between me and you." He said, "I sent nothing to you, and I gave him no token."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the second man then came and demanded his share she said your companion has already taken it he brought your message and the token such and such that was agreed between me and you he said i sent nothing to you and i gave him no token', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 205, NULL, 'The matter was brought before Umar, and he gave judgment against her for the money. She then went to Ali seeking his help, and he said to Umar, "Did these two not instruct her that the money was not to be released to either one of them without the other?" Umar said, "Yes." Ali said, "Then he has no right to hold her liable until he brings his companion with him."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the matter was brought before umar and he gave judgment against her for the money she then went to ali seeking his help and he said to umar did these two not instruct her that the money was not to be released to either one of them without the other umar said yes ali said then he has no right to hold her liable until he brings his companion with him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 206, NULL, 'The woman was released, and the device that had been contrived against her was undone.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the woman was released and the device that had been contrived against her was undone', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 207, NULL, 'It is related from Jafar ibn Muhammad (may Allah''s blessings be upon him) that an emissary of the Messenger of Allah ﷺ came from Yemen with captives. When they reached al-Jahfa their provisions ran out, and they sold a slave girl from among the captives — a girl whose mother was with her — and brought the mother forward without her. When news of this reached the Messenger of Allah ﷺ, he disapproved and ordered that the girl be returned, saying: "Do not separate kindred by sale" (لَا تُفَرِّقُوا بَيْنَ ذَوِي الْأَرْحَامِ بِالْبَيْعِ).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'it is related from jafar ibn muhammad may allahs blessings be upon him that an emissary of the messenger of allah ﷺ came from yemen with captives when they reached al jahfa their provisions ran out and they sold a slave girl from among the captives a girl whose mother was with her and brought the mother forward without her when news of this reached the messenger of allah ﷺ he disapproved and ordered that the girl be returned saying do not separate kindred by sale لا تفرقوا بين ذوي الارحام بالبيع', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 208, NULL, 'Jafar ibn Muhammad (may Allah''s blessings be upon him) also addressed the case of a man who buys a commodity and then seeks to return it, but the seller refuses. The buyer, wishing to be rid of the transaction, surrenders part of the price in exchange for the seller accepting the return. The Imam held that the buyer may reclaim from the seller whatever he gave up in that surrender, provided the seller has genuinely accepted the return — for a valid rescission is not accomplished merely by remitting part of the price. If, however, the seller purchases from the buyer some other, entirely separate commodity for less than the price at which he originally sold to him, that is permissible.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'jafar ibn muhammad may allahs blessings be upon him also addressed the case of a man who buys a commodity and then seeks to return it but the seller refuses the buyer wishing to be rid of the transaction surrenders part of the price in exchange for the seller accepting the return the imam held that the buyer may reclaim from the seller whatever he gave up in that surrender provided the seller has genuinely accepted the return for a valid rescission is not accomplished merely by remitting part of the price if however the seller purchases from the buyer some other entirely separate commodity for less than the price at which he originally sold to him that is permissible', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 209, NULL, 'On Debts', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'on debts', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 210, NULL, 'The pure Imams from the household of the Messenger of Allah ﷺ related that he said: Allah the Almighty is with the debtor until he discharges his debt, so long as he intends to discharge it and the debt was not incurred for something Allah hates. And he said: whoever frees a captive, or relieves one burdened by debt, and grants respite to one in hardship or remits what is owed him, will stand beneath the shade of the Throne on a Day when there is no shade but His shade.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the pure imams from the household of the messenger of allah ﷺ related that he said allah the almighty is with the debtor until he discharges his debt so long as he intends to discharge it and the debt was not incurred for something allah hates and he said whoever frees a captive or relieves one burdened by debt and grants respite to one in hardship or remits what is owed him will stand beneath the shade of the throne on a day when there is no shade but his shade', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 211, NULL, 'The Master said: "Whoever extends a loan has the reward of charity for it." Then, afterward, he said: "Whoever extends a loan has the reward of charity for it every day." Ali (may Allah''s blessings be upon him) said: "O Messenger of Allah, before this you said that whoever extends a loan has the reward of charity, and now you say every day?" He replied: "If a man lends to a fixed term, he is as one who has given it in charity; and when the term has passed and he grants further respite, it is for him the reward of charity every day until he collects it."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the master said whoever extends a loan has the reward of charity for it then afterward he said whoever extends a loan has the reward of charity for it every day ali may allahs blessings be upon him said o messenger of allah before this you said that whoever extends a loan has the reward of charity and now you say every day he replied if a man lends to a fixed term he is as one who has given it in charity and when the term has passed and he grants further respite it is for him the reward of charity every day until he collects it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 212, NULL, 'A man bound by a contract of manumission once stood before Ali seeking his help, but Ali found at that moment nothing to give him. So he said to him: "Shall I direct you to something better than that?" The man said: "Yes, what is it?" Ali said: "Something I heard from the Messenger of Allah (and his family). He said: were there upon you a debt as great as Sabr, Allah the Almighty would discharge it for you." And Sabr is a mountain in Yemen. The man said: "And what is it?" Ali said: "Say: O Allah, suffice me by what You have made lawful so that I need not what You have made unlawful, and enrich me by Your bounty so that I need none besides You" (اَللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ وَاغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'a man bound by a contract of manumission once stood before ali seeking his help but ali found at that moment nothing to give him so he said to him shall i direct you to something better than that the man said yes what is it ali said something i heard from the messenger of allah and his family he said were there upon you a debt as great as sabr allah the almighty would discharge it for you and sabr is a mountain in yemen the man said and what is it ali said say o allah suffice me by what you have made lawful so that i need not what you have made unlawful and enrich me by your bounty so that i need none besides you اللهم اكفني بحلالك عن حرامك واغنني بفضلك عمن سواك', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 213, NULL, 'The Messenger of Allah ﷺ forbade any loan that draws a benefit. Ali (may Allah''s blessings be upon him) said that none should accept the riding of a beast or the loan of goods from a man to whom he has given a loan. Jafar ibn Muhammad (may Allah''s blessings be upon him) likewise disapproved of a creditor lodging with his debtor and eating his food, drinking his drink, or feeding from his fodder. Abu Jafar Muhammad ibn Ali (may Allah''s blessings be upon him) stated the principle plainly: every loan that draws a benefit is riba.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the messenger of allah ﷺ forbade any loan that draws a benefit ali may allahs blessings be upon him said that none should accept the riding of a beast or the loan of goods from a man to whom he has given a loan jafar ibn muhammad may allahs blessings be upon him likewise disapproved of a creditor lodging with his debtor and eating his food drinking his drink or feeding from his fodder abu jafar muhammad ibn ali may allahs blessings be upon him stated the principle plainly every loan that draws a benefit is riba', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 214, NULL, 'This applies when the benefit arises from a stipulation or an intention — as when a creditor lodges with his debtor, eats his food, and feeds from his fodder, since the debtor may be doing so solely on account of the loan. If, however, the benefit is freely offered and was already customary between the two parties independent of the loan, there is no harm in it. It has also been transmitted from them that one who advances dirhams or dinars and is repaid in better coin commits no wrong, provided he did not stipulate it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'this applies when the benefit arises from a stipulation or an intention as when a creditor lodges with his debtor eats his food and feeds from his fodder since the debtor may be doing so solely on account of the loan if however the benefit is freely offered and was already customary between the two parties independent of the loan there is no harm in it it has also been transmitted from them that one who advances dirhams or dinars and is repaid in better coin commits no wrong provided he did not stipulate it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 215, NULL, 'Abu Abdullah Jafar ibn Muhammad (may Allah''s blessings be upon him) was asked about a man whose regular customer or business partner borrows from him — the lender lending precisely because he profits from that borrower through their buying and selling together — and about brokers who advance money to people against their crops, intending to sell on their behalf and recover the loan from the proceeds, and who would not lend at all were that arrangement not in place. He permitted this where it is well-known and customary between the parties, but disapproved of any element from which the lender derives a direct benefit, on account of the Prophet''s prohibition of a loan that draws a benefit.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'abu abdullah jafar ibn muhammad may allahs blessings be upon him was asked about a man whose regular customer or business partner borrows from him the lender lending precisely because he profits from that borrower through their buying and selling together and about brokers who advance money to people against their crops intending to sell on their behalf and recover the loan from the proceeds and who would not lend at all were that arrangement not in place he permitted this where it is well known and customary between the parties but disapproved of any element from which the lender derives a direct benefit on account of the prophets prohibition of a loan that draws a benefit', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 216, NULL, 'It is also related of Ali, of al-Husayn ibn Ali, of Muhammad ibn Ali ibn al-Husayn, and of Jafar ibn Muhammad (may Allah''s blessings be upon them all) that they permitted the bills of exchange known as al-safatij: money that a man borrows in one land on the understanding that he, or another acting on his behalf, will repay it in another land. They saw no harm in this, for it is simply a loan and a debt.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'it is also related of ali of al husayn ibn ali of muhammad ibn ali ibn al husayn and of jafar ibn muhammad may allahs blessings be upon them all that they permitted the bills of exchange known as al safatij money that a man borrows in one land on the understanding that he or another acting on his behalf will repay it in another land they saw no harm in this for it is simply a loan and a debt', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 217, NULL, 'It is related of them (may Allah''s blessings be upon them) that dealing on credit is permitted, provided the contract is properly formed. If a man owes a debt that has fallen due and says to his creditor, "I cannot find what I might pay you with, but sell me something on a deferred term, and I will sell it and pay you from the proceeds," and the creditor does so, there is no harm in it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'it is related of them may allahs blessings be upon them that dealing on credit is permitted provided the contract is properly formed if a man owes a debt that has fallen due and says to his creditor i cannot find what i might pay you with but sell me something on a deferred term and i will sell it and pay you from the proceeds and the creditor does so there is no harm in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 218, NULL, 'If, however, the creditor transacts with him in words alone, in a manner that is not lawful, there is harm. An example would be his saying, "Lend me one hundred dinars for two hundred," or any similar increase tied to a named term, and then dressing this as a sale — selling the man something at a nominally valid price that he has inflated by that same increase, payable at that same term. Bargaining over such an increase is disliked. To leave it aside entirely and intend a plain sale, with no mention of any increase, is the safer course.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if however the creditor transacts with him in words alone in a manner that is not lawful there is harm an example would be his saying lend me one hundred dinars for two hundred or any similar increase tied to a named term and then dressing this as a sale selling the man something at a nominally valid price that he has inflated by that same increase payable at that same term bargaining over such an increase is disliked to leave it aside entirely and intend a plain sale with no mention of any increase is the safer course', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 219, NULL, 'A sale contract validly concluded after such bargaining is, nevertheless, permissible. The situation resembles that of a man and a woman who exchange words bargaining over an unlawful union and then abandon it and contract a sound marriage between them: the bargaining and the back-and-forth over what is immoral is disliked and forbidden, yet it does not invalidate the marriage they afterward contract, nor anything that proceeds from it. Their returning to what is lawful, with repentance from what they had bargained over, is well, if Allah wills.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'a sale contract validly concluded after such bargaining is nevertheless permissible the situation resembles that of a man and a woman who exchange words bargaining over an unlawful union and then abandon it and contract a sound marriage between them the bargaining and the back and forth over what is immoral is disliked and forbidden yet it does not invalidate the marriage they afterward contract nor anything that proceeds from it their returning to what is lawful with repentance from what they had bargained over is well if allah wills', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 220, NULL, 'Abu Abdullah Jafar ibn Muhammad (may Allah''s blessings be upon him) was asked about a man who says to another, "Buy me such-and-such goods for so much, and I will buy them from you at a deferred price for so much, with such-and-such an increase." He replied that there is no harm in this, since the buyer acquires the goods only after the other man has come to own them. He also permitted the following: a creditor who is owed a debt payable at a future term, and who finds himself in need of it before that term arrives, may remit part of the debt so that the debtor pays the remainder early, or may accept partial payment on condition that the rest is extended to a later term — and there is no harm in either arrangement, so long as nothing is added above the original capital.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'abu abdullah jafar ibn muhammad may allahs blessings be upon him was asked about a man who says to another buy me such and such goods for so much and i will buy them from you at a deferred price for so much with such and such an increase he replied that there is no harm in this since the buyer acquires the goods only after the other man has come to own them he also permitted the following a creditor who is owed a debt payable at a future term and who finds himself in need of it before that term arrives may remit part of the debt so that the debtor pays the remainder early or may accept partial payment on condition that the rest is extended to a later term and there is no harm in either arrangement so long as nothing is added above the original capital', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 221, NULL, 'On Transfer of Debt and Suretyship', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'on transfer of debt and suretyship', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 222, NULL, 'A transfer of debt (حَوَل) is the assignment, by a creditor, of the debt owed to him onto a third party. Suretyship (al-kafala) is the bearing of another''s burden on his behalf; the one who bears it is called surety, guarantor, pledge, warrant, and underwriter, and whoever takes on such a burden is obliged to discharge what he has undertaken. The Messenger of Allah ﷺ said: "The underwriter is liable" (اَلزَّعِيمُ غَارِمٌ). The underwriter, as stated, is the bearer of the burden. Allah says: "They said, while turning toward them: What is it you are missing? They said: We are missing the king''s measuring-cup, and for whoever brings it there is a camel''s load" (Yusuf 71–72), and then, "and I am underwriter for it" (وَأَنَا۠ بِهِۦ زَعِيمٌۭ) — that is, the bearer of the burden.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'a transfer of debt حول is the assignment by a creditor of the debt owed to him onto a third party suretyship al kafala is the bearing of anothers burden on his behalf the one who bears it is called surety guarantor pledge warrant and underwriter and whoever takes on such a burden is obliged to discharge what he has undertaken the messenger of allah ﷺ said the underwriter is liable الزعيم غارم the underwriter as stated is the bearer of the burden allah says they said while turning toward them what is it you are missing they said we are missing the kings measuring cup and for whoever brings it there is a camels load yusuf 71 72 and then and i am underwriter for it وانا به زعيم that is the bearer of the burden', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 223, NULL, 'Abu Jafar Muhammad ibn Ali and Abu Abdullah Jafar ibn Muhammad (may Allah''s blessings be upon them) said: when a man transfers onto another a debt he is owed, the creditor may pursue whichever of the two he wishes — either the original debtor or the one onto whom the debt was transferred — unless he has already discharged the original debtor. If that discharge was made at the time of the transfer, the creditor may pursue only the one onto whom the debt was transferred, and he has no claim against the original debtor he discharged.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'abu jafar muhammad ibn ali and abu abdullah jafar ibn muhammad may allahs blessings be upon them said when a man transfers onto another a debt he is owed the creditor may pursue whichever of the two he wishes either the original debtor or the one onto whom the debt was transferred unless he has already discharged the original debtor if that discharge was made at the time of the transfer the creditor may pursue only the one onto whom the debt was transferred and he has no claim against the original debtor he discharged', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 224, NULL, 'When two men together stand surety for one man''s debt, the creditor may take from whichever of the two sureties he wishes, unless they stipulated that the suretyship is divided equally between them. If no such stipulation was made and each gave an unrestricted suretyship, he may take the whole from whichever of them he can reach. If they stipulated in the contract of suretyship that each is surety for the other, he may take from whichever he wishes, and the one from whom he takes then recovers from his fellow surety half of what he paid. If one surety is added after another, all of them are sureties together, and he may take from whichever he wishes, unless he has discharged one of them.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'when two men together stand surety for one mans debt the creditor may take from whichever of the two sureties he wishes unless they stipulated that the suretyship is divided equally between them if no such stipulation was made and each gave an unrestricted suretyship he may take the whole from whichever of them he can reach if they stipulated in the contract of suretyship that each is surety for the other he may take from whichever he wishes and the one from whom he takes then recovers from his fellow surety half of what he paid if one surety is added after another all of them are sureties together and he may take from whichever he wishes unless he has discharged one of them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 225, NULL, 'Where the surety has guaranteed a sum of money, or the very thing for which he stood surety, he must discharge that obligation unless the creditor releases him from it. Producing the person on whose behalf he stood surety does not suffice in such a case. If, however, the suretyship was one of person — guaranteeing the individual''s appearance — and he produces that person to the creditor on the agreed terms and is thereby quit of him, he is fully discharged and nothing further remains upon him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'where the surety has guaranteed a sum of money or the very thing for which he stood surety he must discharge that obligation unless the creditor releases him from it producing the person on whose behalf he stood surety does not suffice in such a case if however the suretyship was one of person guaranteeing the individuals appearance and he produces that person to the creditor on the agreed terms and is thereby quit of him he is fully discharged and nothing further remains upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 226, NULL, 'If he undertook to produce the person without restriction, he must do so whenever called upon. If the suretyship runs to a fixed term, the creditor has no recourse against the surety until that term has passed; should the surety then fail to produce the person, he becomes liable for what is owed — unless the person has died. If the person has died and the surety bore responsibility only for his appearance, nothing remains upon the surety.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if he undertook to produce the person without restriction he must do so whenever called upon if the suretyship runs to a fixed term the creditor has no recourse against the surety until that term has passed should the surety then fail to produce the person he becomes liable for what is owed unless the person has died if the person has died and the surety bore responsibility only for his appearance nothing remains upon the surety', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 227, NULL, 'If the person is absent and the surety says, "I will pay what is owed upon him," and the amount owed is unknown, the surety is liable for no more than what is proven. If the amount is known, only that amount is upon him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if the person is absent and the surety says i will pay what is owed upon him and the amount owed is unknown the surety is liable for no more than what is proven if the amount is known only that amount is upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 228, NULL, 'If the matter is one in which the person must of necessity be produced — on account of an oath that has become due upon him, a vow of abstention, his being held, or the like — then he must be produced without exception, unless he dies or the creditor releases the surety from his obligation.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if the matter is one in which the person must of necessity be produced on account of an oath that has become due upon him a vow of abstention his being held or the like then he must be produced without exception unless he dies or the creditor releases the surety from his obligation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 229, NULL, 'There is no suretyship in a prescribed penalty. Whoever has become liable for a hadd, or retribution, or execution, or amputation cannot be released against a surety in that matter; rather, the penalty is exacted from him directly. If witnesses testify to it and he must be held until the testimony is established, he is detained, and no surety is accepted for him — for if he were to slip away, the retribution could not be exacted from the surety in his place. Nor does suretyship bind a slave to stand as surety, even if he has been permitted to trade, unless his master grants him leave to do so.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'there is no suretyship in a prescribed penalty whoever has become liable for a hadd or retribution or execution or amputation cannot be released against a surety in that matter rather the penalty is exacted from him directly if witnesses testify to it and he must be held until the testimony is established he is detained and no surety is accepted for him for if he were to slip away the retribution could not be exacted from the surety in his place nor does suretyship bind a slave to stand as surety even if he has been permitted to trade unless his master grants him leave to do so', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 230, NULL, 'On Interdiction and the Spendthrift', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'on interdiction and the spendthrift', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 231, NULL, 'Interdiction (al-hajr) is restraint. Allah the Almighty has said: "And test the orphans" (al-Nisa 6) — meaning, try them — "until, when they reach marriageable age," meaning puberty, "then, if you perceive in them sound judgment, hand over to them their wealth." And the Messenger of Allah ﷺ forbade the wasting of wealth, and Allah the Almighty has said: "And do not squander wastefully; indeed the squanderers are the brothers of the devils" (al-Isra 26–27).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'interdiction al hajr is restraint allah the almighty has said and test the orphans al nisa 6 meaning try them until when they reach marriageable age meaning puberty then if you perceive in them sound judgment hand over to them their wealth and the messenger of allah ﷺ forbade the wasting of wealth and allah the almighty has said and do not squander wastefully indeed the squanderers are the brothers of the devils al isra 26 27', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 232, NULL, 'The child is therefore barred from his wealth by the ruling of the Book until he comes of age and sound judgment and care for his property are recognized in him, whereupon his wealth is handed over to him. The bar was imposed on account of the danger of foolishness and squandering. If he comes of age and remains foolish and wasteful, he remains under interdiction; and likewise, if these qualities arise in him after maturity, he is placed under interdiction.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the child is therefore barred from his wealth by the ruling of the book until he comes of age and sound judgment and care for his property are recognized in him whereupon his wealth is handed over to him the bar was imposed on account of the danger of foolishness and squandering if he comes of age and remains foolish and wasteful he remains under interdiction and likewise if these qualities arise in him after maturity he is placed under interdiction', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 233, NULL, 'Ali ibn Abi Talib (may Allah''s blessings be upon him) placed Abdullah ibn Jafar ibn Abi Talib (may Allah''s blessings be upon him) under interdiction when his squandering of wealth was established, and brought the matter before Uthman during his caliphate, calling upon him to act. Uthman hesitated. Later, Abdullah purchased a salt marsh for sixty thousand, and Uthman said: "By Allah, it would not please me to own it even for these two sandals of mine." Ali (may Allah''s blessings be upon him) then came to him and said: "Will you not interdict your nephew?"', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'ali ibn abi talib may allahs blessings be upon him placed abdullah ibn jafar ibn abi talib may allahs blessings be upon him under interdiction when his squandering of wealth was established and brought the matter before uthman during his caliphate calling upon him to act uthman hesitated later abdullah purchased a salt marsh for sixty thousand and uthman said by allah it would not please me to own it even for these two sandals of mine ali may allahs blessings be upon him then came to him and said will you not interdict your nephew', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 234, NULL, 'The insane person is likewise placed under interdiction. Whoever falls under interdiction has his maintenance met from his own wealth in a fitting measure, and a guardian is appointed to protect that wealth and spend from it on his behalf. When the foolish one becomes upright, the squanderer becomes careful, and the insane one regains his reason — and those whose testimony is acceptable bear witness to the change — the interdiction is lifted. Should they relapse, it is reimposed. Whatever they disposed of from their wealth while under interdiction is likewise void.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the insane person is likewise placed under interdiction whoever falls under interdiction has his maintenance met from his own wealth in a fitting measure and a guardian is appointed to protect that wealth and spend from it on his behalf when the foolish one becomes upright the squanderer becomes careful and the insane one regains his reason and those whose testimony is acceptable bear witness to the change the interdiction is lifted should they relapse it is reimposed whatever they disposed of from their wealth while under interdiction is likewise void', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 235, NULL, 'On Bankruptcy', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'on bankruptcy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 236, NULL, 'A man who falls into bankruptcy — owing debts he cannot pay, with nothing left to sell and no wealth to draw on — may not be imprisoned once his insolvency is established. If he owes debts to a group of creditors and what remains in his hand falls short of the total owed, that remainder is divided among them proportionally: each creditor receives a share corresponding to his debt, and each bears the shortfall in the same proportion.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'a man who falls into bankruptcy owing debts he cannot pay with nothing left to sell and no wealth to draw on may not be imprisoned once his insolvency is established if he owes debts to a group of creditors and what remains in his hand falls short of the total owed that remainder is divided among them proportionally each creditor receives a share corresponding to his debt and each bears the shortfall in the same proportion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 237, NULL, 'By way of example: a man goes bankrupt owing one creditor a hundred dinars and another two hundred, and only thirty dinars are found in his possession. The owner of the hundred receives ten, and the owner of the two hundred receives twenty. The same reckoning applies whatever the amounts, however few or many the creditors.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'by way of example a man goes bankrupt owing one creditor a hundred dinars and another two hundred and only thirty dinars are found in his possession the owner of the hundred receives ten and the owner of the two hundred receives twenty the same reckoning applies whatever the amounts however few or many the creditors', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 238, NULL, 'If a creditor finds in the bankrupt''s possession something he had sold him — or part of it — that creditor has a stronger claim to that specific property than any of the other creditors, until he has recovered his debt in full. Should the sale of that property yield a surplus beyond what he is owed, the remainder passes to the other creditors.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if a creditor finds in the bankrupts possession something he had sold him or part of it that creditor has a stronger claim to that specific property than any of the other creditors until he has recovered his debt in full should the sale of that property yield a surplus beyond what he is owed the remainder passes to the other creditors', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 239, NULL, 'The bankrupt may not dispose of his assets independently, setting the creditors aside, until he has discharged what he owes them. The assets are to be examined carefully, with the creditors bidding against one another, until the price holds firm and no higher offer can be found. When all parties — creditors and bankrupt alike — are satisfied and consent to the sale, the assets are sold and the proceeds divided among the creditors in proportion to their claims.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the bankrupt may not dispose of his assets independently setting the creditors aside until he has discharged what he owes them the assets are to be examined carefully with the creditors bidding against one another until the price holds firm and no higher offer can be found when all parties creditors and bankrupt alike are satisfied and consent to the sale the assets are sold and the proceeds divided among the creditors in proportion to their claims', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 240, NULL, 'Should the bankrupt refuse to sell, or should one of the creditors withhold consent, and the matter is brought before the competent authority, and it is attested before him that the sale was conducted with the utmost diligence and at the best attainable price, he orders the assets sold and the proceeds apportioned among the creditors. If the proceeds fall short of the debts, they are distributed accordingly. If they cover the debts and leave a surplus, that surplus is returned to the bankrupt. If only part of the assets is needed to settle what is owed, and the bankrupt does not wish all of them sold, only so much is sold as is required to discharge the debts upon him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'should the bankrupt refuse to sell or should one of the creditors withhold consent and the matter is brought before the competent authority and it is attested before him that the sale was conducted with the utmost diligence and at the best attainable price he orders the assets sold and the proceeds apportioned among the creditors if the proceeds fall short of the debts they are distributed accordingly if they cover the debts and leave a surplus that surplus is returned to the bankrupt if only part of the assets is needed to settle what is owed and the bankrupt does not wish all of them sold only so much is sold as is required to discharge the debts upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 241, NULL, 'Once the creditors have come forward, a bankrupt''s acknowledgment of a new debt is not accepted unless the person named in it produces clear evidence, or the creditors themselves affirm its truth. Any debt he acknowledged while he was still solvent, however, stands without question. And if something comes into his hands from which wages are owed to him, he may step forward to claim it alongside the other creditors, holding the better right to it until his wages have been paid from it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'once the creditors have come forward a bankrupts acknowledgment of a new debt is not accepted unless the person named in it produces clear evidence or the creditors themselves affirm its truth any debt he acknowledged while he was still solvent however stands without question and if something comes into his hands from which wages are owed to him he may step forward to claim it alongside the other creditors holding the better right to it until his wages have been paid from it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 242, NULL, 'A question was put to Abu Abdullah Jafar ibn Muhammad concerning a man who buys a slave and frees him, or takes a concubine who bears him a child, or gives something away in charity — and who afterward falls into bankruptcy. How do those earlier acts stand?', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'a question was put to abu abdullah jafar ibn muhammad concerning a man who buys a slave and frees him or takes a concubine who bears him a child or gives something away in charity and who afterward falls into bankruptcy how do those earlier acts stand', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 243, NULL, 'He replied that if the man made the purchase at a fair price while he was still solvent, before any bankruptcy had been established against him, and only later became insolvent, then the manumission and the charity both hold. The seller in that case takes his place among the creditors and is treated as they are with respect to whatever remains in the man''s possession. If, on the other hand, the man was already destitute and had nothing of substance to give, neither the manumission nor the charity is valid, for he was disposing of what was not truly his to dispose of.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he replied that if the man made the purchase at a fair price while he was still solvent before any bankruptcy had been established against him and only later became insolvent then the manumission and the charity both hold the seller in that case takes his place among the creditors and is treated as they are with respect to whatever remains in the mans possession if on the other hand the man was already destitute and had nothing of substance to give neither the manumission nor the charity is valid for he was disposing of what was not truly his to dispose of', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 244, NULL, 'It has been narrated from the People of the House that the Commander of the Faithful (ع) held that a mother by virtue of her child — the umm walad — may be sold for the price of her own freedom. That is, if a man purchases her and she bears him a child, and he dies possessing nothing else, she stands as the equivalent of what he owed. If, however, he had means, the seller takes his portion alongside the other creditors, and whatever portion of the debt remains continues as an obligation upon the freed person, to be sought whenever that person becomes able, at which point it must be paid.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'it has been narrated from the people of the house that the commander of the faithful ع held that a mother by virtue of her child the umm walad may be sold for the price of her own freedom that is if a man purchases her and she bears him a child and he dies possessing nothing else she stands as the equivalent of what he owed if however he had means the seller takes his portion alongside the other creditors and whatever portion of the debt remains continues as an obligation upon the freed person to be sought whenever that person becomes able at which point it must be paid', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 245, NULL, 'Whichever of the two — the freed man or the freed woman — finds it easier to discharge the remainder may be called upon to do so, and the path of least difficulty is followed. The one who has been freed may not, however, be compelled back into service — neither as a concubine nor in any other capacity of ownership — nor may what remains of the debt be demanded of such a person in the manner it would be demanded of one still enslaved.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'whichever of the two the freed man or the freed woman finds it easier to discharge the remainder may be called upon to do so and the path of least difficulty is followed the one who has been freed may not however be compelled back into service neither as a concubine nor in any other capacity of ownership nor may what remains of the debt be demanded of such a person in the manner it would be demanded of one still enslaved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 246, NULL, 'If the one who freed them dies with nothing to his name, yet the freed person''s assessed worth exceeds what was owed, preference is given to completing the manumission at that assessed value. Where a charitable gift is involved, preference is given to ensuring the charity reaches its recipient in full, and whatever remains beyond the debt is returned.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if the one who freed them dies with nothing to his name yet the freed persons assessed worth exceeds what was owed preference is given to completing the manumission at that assessed value where a charitable gift is involved preference is given to ensuring the charity reaches its recipient in full and whatever remains beyond the debt is returned', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 247, NULL, 'A man who carries debts and owns slaves whose sale would cover those debts may not free them; the slaves are sold and the debt discharged, provided he has no other funds. If he does have other funds, then what already passed through his hands stands: what he spent, what he sold, and what some creditors received while others did not — all of it holds, and it is lawful for whoever received it. A man may not discharge a debt, nor sell, nor buy, except by lawful means. So long as a solvent man is still trading openly and his creditors have not moved against him, what he pays out and what he sells is valid for those who receive it; he is restrained from such dealings only once his creditors have come forward and his bankruptcy has been declared. The wife, for her part, stands among the creditors and contends for her dowry, and she is not deprived of her right.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'a man who carries debts and owns slaves whose sale would cover those debts may not free them the slaves are sold and the debt discharged provided he has no other funds if he does have other funds then what already passed through his hands stands what he spent what he sold and what some creditors received while others did not all of it holds and it is lawful for whoever received it a man may not discharge a debt nor sell nor buy except by lawful means so long as a solvent man is still trading openly and his creditors have not moved against him what he pays out and what he sells is valid for those who receive it he is restrained from such dealings only once his creditors have come forward and his bankruptcy has been declared the wife for her part stands among the creditors and contends for her dowry and she is not deprived of her right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 248, NULL, 'When a creditor or claimant comes forward and the man against whom the claim is made acknowledges it — or proof is established against him and judgment is given — and he then pleads that he has nothing while the claimant calls him a liar, the question of where the burden of proof falls turns on the nature of the obligation:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'when a creditor or claimant comes forward and the man against whom the claim is made acknowledges it or proof is established against him and judgment is given and he then pleads that he has nothing while the claimant calls him a liar the question of where the burden of proof falls turns on the nature of the obligation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 249, NULL, 'If it arose from a debt, or from something that actually reached his hands, the burden falls on him to prove that he lost it and that it left his possession. If what was owed never reached his hands — a liability arising from an offense, from standing as surety, from a transfer of debt by hawala, from the maintenance of a dependent, or from a woman''s dowry — his plea of insolvency is accepted upon his oath, and the burden shifts to the one pressing the claim.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if it arose from a debt or from something that actually reached his hands the burden falls on him to prove that he lost it and that it left his possession if what was owed never reached his hands a liability arising from an offense from standing as surety from a transfer of debt by hawala from the maintenance of a dependent or from a womans dowry his plea of insolvency is accepted upon his oath and the burden shifts to the one pressing the claim', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 250, NULL, 'As for property he claims to own: if he can prove any of it, he is held to it. If he cannot, it stands as a debt against him, to be collected whenever he becomes able. Whenever it appears that he has something in hand, it is sold and his debts are paid from the proceeds.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'as for property he claims to own if he can prove any of it he is held to it if he cannot it stands as a debt against him to be collected whenever he becomes able whenever it appears that he has something in hand it is sold and his debts are paid from the proceeds', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 251, NULL, 'If witnesses testify that he is in fact wealthy and that the means to satisfy his debt are merely concealed, he is imprisoned and pressed until he pays. If, when confronted, he says to his opponent, "I will settle your right and give you what I owe," and enters no plea of insolvency, that word is taken at face value, and he is held to it — imprisoned until he discharges the obligation. When a debtor who has visible property turns obstinate, the judge imprisons him and presses him to sell, disciplining him should he delay; if he persists, the sale is carried out on his behalf. And if he acknowledges the debt, or it is proven that he has funds, yet still withholds payment, he is imprisoned at his opponent''s request and compelled until he renders what he owes.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if witnesses testify that he is in fact wealthy and that the means to satisfy his debt are merely concealed he is imprisoned and pressed until he pays if when confronted he says to his opponent i will settle your right and give you what i owe and enters no plea of insolvency that word is taken at face value and he is held to it imprisoned until he discharges the obligation when a debtor who has visible property turns obstinate the judge imprisons him and presses him to sell disciplining him should he delay if he persists the sale is carried out on his behalf and if he acknowledges the debt or it is proven that he has funds yet still withholds payment he is imprisoned at his opponents request and compelled until he renders what he owes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 252, NULL, 'On tenant farming and musaqah: tenant farming, or muzaraah, is a partnership in cultivation in which each party holds a defined share of the produce — or in which a man sows another man''s land using his own oxen or his own seed in return for a known portion of the yield. Abu Abdullah Jafar ibn Muhammad was asked about this and permitted it. He said that the Messenger of Allah and his family gave the land of Khaybar to the Jews on the condition that they cultivate it and receive half of what it produced, and he apportioned it with them on that basis. The land held palms and trees, and whoever worked it took a third or a quarter. Whatever the two parties agree upon, whether little or much, is permissible.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'on tenant farming and musaqah tenant farming or muzaraah is a partnership in cultivation in which each party holds a defined share of the produce or in which a man sows another mans land using his own oxen or his own seed in return for a known portion of the yield abu abdullah jafar ibn muhammad was asked about this and permitted it he said that the messenger of allah and his family gave the land of khaybar to the jews on the condition that they cultivate it and receive half of what it produced and he apportioned it with them on that basis the land held palms and trees and whoever worked it took a third or a quarter whatever the two parties agree upon whether little or much is permissible', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 253, NULL, 'It is likewise permissible to rent land for a fixed term in order to cultivate it for a known and understood consideration. He disapproved, however, of renting land for wheat on the condition that wheat be grown in it. The tenant farmer may undertake whatever the parties stipulate as to labor, plowing, oxen, and the rest, and according to whatever they agree, whether the land belongs to both of them or to one alone. What he disliked was that they fix a separate known share for the seed, a separate share for the land, and a separate share for the oxen; rather, each party should stipulate for himself a known portion of the whole yield.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'it is likewise permissible to rent land for a fixed term in order to cultivate it for a known and understood consideration he disapproved however of renting land for wheat on the condition that wheat be grown in it the tenant farmer may undertake whatever the parties stipulate as to labor plowing oxen and the rest and according to whatever they agree whether the land belongs to both of them or to one alone what he disliked was that they fix a separate known share for the seed a separate share for the land and a separate share for the oxen rather each party should stipulate for himself a known portion of the whole yield', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 254, NULL, 'Musaqah is work upon land bearing trees, undertaken by a worker in return for a defined share of the produce. Jafar ibn Muhammad said that if a man is given land to plow, water, and tend — land holding pomegranates, palms, fruits, legumes, or the like — on the condition that he receive half of what it yields, or whatever portion the two parties agree upon, that arrangement is permissible. The same holds when land is handed over to be built up and cultivated.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'musaqah is work upon land bearing trees undertaken by a worker in return for a defined share of the produce jafar ibn muhammad said that if a man is given land to plow water and tend land holding pomegranates palms fruits legumes or the like on the condition that he receive half of what it yields or whatever portion the two parties agree upon that arrangement is permissible the same holds when land is handed over to be built up and cultivated', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 255, NULL, 'If the worker plants the land and then claims that the owner had given him leave to do so, while the owner denies it, the word stands with the owner, confirmed by his oath — unless it was known at the time of planting that the worker had permission. In that case the worker swears, and he is entitled to the equivalent of a tenant''s wage for that land. If, however, he advances a claim that does not fit the circumstances, he owes the customary rent of the land instead.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if the worker plants the land and then claims that the owner had given him leave to do so while the owner denies it the word stands with the owner confirmed by his oath unless it was known at the time of planting that the worker had permission in that case the worker swears and he is entitled to the equivalent of a tenants wage for that land if however he advances a claim that does not fit the circumstances he owes the customary rent of the land instead', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 256, NULL, 'The same principle applies when the owner had no knowledge of the planting and holds no proof against the worker: if the worker swears that he did not rent the land on the terms alleged against him, the cultivator is liable for the equivalent of the land''s rent. The owner, for his part, has no right to tear up the standing crop.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the same principle applies when the owner had no knowledge of the planting and holds no proof against the worker if the worker swears that he did not rent the land on the terms alleged against him the cultivator is liable for the equivalent of the lands rent the owner for his part has no right to tear up the standing crop', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 257, NULL, 'Where the cultivators plowed as trespassers and this is proven against them, and neither party will take the oath once it has been offered, and no fault is established on the owner''s side, the owner is given a choice: he may claim the equivalent of the land''s rent from them, or he may pay their expenses and the cost of their planting and take the crop for himself. He may not uproot it, for tearing up a standing crop is an act of corruption.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'where the cultivators plowed as trespassers and this is proven against them and neither party will take the oath once it has been offered and no fault is established on the owners side the owner is given a choice he may claim the equivalent of the lands rent from them or he may pay their expenses and the cost of their planting and take the crop for himself he may not uproot it for tearing up a standing crop is an act of corruption', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 258, NULL, 'He also said that if a man plows a piece of land and another asks to share in what he has plowed — on the condition that he contribute half the seed and half the costs — and the two agree, the arrangement is permissible.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he also said that if a man plows a piece of land and another asks to share in what he has plowed on the condition that he contribute half the seed and half the costs and the two agree the arrangement is permissible', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 259, NULL, 'He said further that there is no harm in a man giving his ruined land to another who will restore it for a fixed period, on the condition that everything it produces during that time belongs to the one who works it; when the agreed term has passed, the land returns to its owner in improved condition.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he said further that there is no harm in a man giving his ruined land to another who will restore it for a fixed period on the condition that everything it produces during that time belongs to the one who works it when the agreed term has passed the land returns to its owner in improved condition', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 260, NULL, 'Likewise, if the land carries a tribute charge and another man takes it on together with that charge, there is no harm in the arrangement. He may sow it. If he leaves it unsown, and the owner neither prevents him nor stands between him and the land, he owes the rent for the full term he contracted — whether he chooses to plow or to leave it fallow — unless it was stipulated at the outset that no rent falls due except when he actually plows.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'likewise if the land carries a tribute charge and another man takes it on together with that charge there is no harm in the arrangement he may sow it if he leaves it unsown and the owner neither prevents him nor stands between him and the land he owes the rent for the full term he contracted whether he chooses to plow or to leave it fallow unless it was stipulated at the outset that no rent falls due except when he actually plows', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 261, NULL, 'The choice between plowing and leaving the land rests with him, and he is bound by the condition placed upon him; where such a condition was made, both parties are held to what they contracted.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the choice between plowing and leaving the land rests with him and he is bound by the condition placed upon him where such a condition was made both parties are held to what they contracted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 262, NULL, 'He was asked about the people of a village burdened with a tribute that the ruler pressed upon them harshly, who then assigned the matter to a man on the condition that whatever he paid on their behalf — little or much — would discharge their obligation, and that any surplus beyond what was demanded would be his. He replied that if they agreed to this willingly, the arrangement is permissible, and the man who took the burden from them is entitled to the surplus they agreed upon.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he was asked about the people of a village burdened with a tribute that the ruler pressed upon them harshly who then assigned the matter to a man on the condition that whatever he paid on their behalf little or much would discharge their obligation and that any surplus beyond what was demanded would be his he replied that if they agreed to this willingly the arrangement is permissible and the man who took the burden from them is entitled to the surplus they agreed upon', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 263, NULL, 'On rents and hire: the Imams of the household of the Messenger of Allah narrated that there was found in the sheath of a sword a writing that bore the curse of Allah, of the angels, of the prophets and the messengers, and the curse of the Prophet Muhammad upon whoever claims as his father one who is not his father, or claims as his patron one who is not his patron, or wrongs a hired laborer of his wage, or moves the landmark boundaries of a road. Ali, the Commander of the Faithful, said, "I found this writing in the sheath of the sword of the Messenger of Allah and his family, and I know it." That subject is a long one, and its full treatment belongs elsewhere.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'on rents and hire the imams of the household of the messenger of allah narrated that there was found in the sheath of a sword a writing that bore the curse of allah of the angels of the prophets and the messengers and the curse of the prophet muhammad upon whoever claims as his father one who is not his father or claims as his patron one who is not his patron or wrongs a hired laborer of his wage or moves the landmark boundaries of a road ali the commander of the faithful said i found this writing in the sheath of the sword of the messenger of allah and his family and i know it that subject is a long one and its full treatment belongs elsewhere', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 264, NULL, 'Allah, mighty and majestic, said: ﴿قُل لَّا أَسْأَلُكُ عَلَيْهِ أَجْرًا إِلَّا الْمَوَدَّةَ فِى الْقُرْبَى﴾, "Say: I do not ask you for any reward for it except affection in kinship" (Al-Shura 23). This verse too opens onto a longer discourse that belongs in its own place.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'allah mighty and majestic said قل لا اسالك عليه اجرا الا الموده في القربي say i do not ask you for any reward for it except affection in kinship al shura 23 this verse too opens onto a longer discourse that belongs in its own place', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 265, NULL, 'The consensus transmitted from the Imams holds that a man may lease out himself, those under his charge, and whatever he owns — whether a beast, a tool, a ship, land, a dwelling, or anything else — in all its lawful forms. The wage for such a lease is lawful, and earning it is permitted, provided the hire is contracted for a fixed term, a known purpose, and on terms that are right and allowed. None of this holds where the subject of the hire is something unlawful to profit from or unlawful to do. That is a foundational principle from which many particular rulings branch.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the consensus transmitted from the imams holds that a man may lease out himself those under his charge and whatever he owns whether a beast a tool a ship land a dwelling or anything else in all its lawful forms the wage for such a lease is lawful and earning it is permitted provided the hire is contracted for a fixed term a known purpose and on terms that are right and allowed none of this holds where the subject of the hire is something unlawful to profit from or unlawful to do that is a foundational principle from which many particular rulings branch', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 266, NULL, 'A man who has no authority over himself cannot validly hire himself out, nor can he hire out what he does not own and has no right over. A man who holds something it is not lawful for him to own — one who has seized a free person, for instance, or who keeps instruments of forbidden amusement — may not rent these out, and no one may lawfully hire them from him. Nor may a man lease even what he rightfully owns to one who will use it for an unlawful end: as when a man hires out himself, his beast, his tools, or his ship for the making of wine, for carrying it, or for anything of that kind.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'a man who has no authority over himself cannot validly hire himself out nor can he hire out what he does not own and has no right over a man who holds something it is not lawful for him to own one who has seized a free person for instance or who keeps instruments of forbidden amusement may not rent these out and no one may lawfully hire them from him nor may a man lease even what he rightfully owns to one who will use it for an unlawful end as when a man hires out himself his beast his tools or his ship for the making of wine for carrying it or for anything of that kind', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 267, NULL, 'Jafar ibn Muhammad was asked about taking a wage for teaching the Quran, and he found it objectionable. He related that a man had once said to the Commander of the Faithful, Ali, "I love you, O Commander of the Faithful." Ali replied, "But I hold something against you." The man asked why, and Ali said, "Because you take a wage for teaching the Quran, and I have heard the Messenger of Allah and his family say that whoever takes the teaching of the Quran as a livelihood will have that as his only portion on the Day of Resurrection."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'jafar ibn muhammad was asked about taking a wage for teaching the quran and he found it objectionable he related that a man had once said to the commander of the faithful ali i love you o commander of the faithful ali replied but i hold something against you the man asked why and ali said because you take a wage for teaching the quran and i have heard the messenger of allah and his family say that whoever takes the teaching of the quran as a livelihood will have that as his only portion on the day of resurrection', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 268, NULL, 'Yet they permitted the taking of wages for teaching writing, literature, and the other subjects that teachers impart to children, and they themselves paid such wages; had it been forbidden or even disliked, they would not have paid it. What was disliked was solely the wage for teaching the Quran on its own. When a teacher instructs children in the Quran together with other subjects for which a wage may lawfully be taken, there is no harm in it, and the wage falls upon what is lawful rather than upon what is not.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'yet they permitted the taking of wages for teaching writing literature and the other subjects that teachers impart to children and they themselves paid such wages had it been forbidden or even disliked they would not have paid it what was disliked was solely the wage for teaching the quran on its own when a teacher instructs children in the quran together with other subjects for which a wage may lawfully be taken there is no harm in it and the wage falls upon what is lawful rather than upon what is not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 269, NULL, 'It is narrated that the Messenger of God and his family married a woman to one of his companions on the condition that he teach her a surah of the Quran. The report survives only in summary and does not state that he made the teaching itself her dowry; and a marriage may be valid even without a named dowry, as the matters of marriage will address. Abu Jafar Muhammad ibn Ali was asked about a man over whom the Quran is recited, who, once the recitation is complete, prepares food as people customarily do and invites those who recited with him, including the one who led the recitation. He replied that there is no harm in it, so long as it is not done for the sake of the Quran recitation itself.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'it is narrated that the messenger of god and his family married a woman to one of his companions on the condition that he teach her a surah of the quran the report survives only in summary and does not state that he made the teaching itself her dowry and a marriage may be valid even without a named dowry as the matters of marriage will address abu jafar muhammad ibn ali was asked about a man over whom the quran is recited who once the recitation is complete prepares food as people customarily do and invites those who recited with him including the one who led the recitation he replied that there is no harm in it so long as it is not done for the sake of the quran recitation itself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 270, NULL, 'The scholars also permitted the taking of a wage for ruqyah performed by means of the Book of God and His names. It is narrated that the Messenger of God and his family dispatched a company who passed by one of the Arab encampments and lodged there. The chief of that encampment was stung, and its people came to ask whether any among the company could perform ruqyah. One of the companions recited the opening chapter of the Book, al-Fatihah, over him, and he recovered. The company was given thirty sheep, which they accepted. When they returned to the Messenger of God and his family and recounted what had happened, he allowed them to keep what they had taken.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the scholars also permitted the taking of a wage for ruqyah performed by means of the book of god and his names it is narrated that the messenger of god and his family dispatched a company who passed by one of the arab encampments and lodged there the chief of that encampment was stung and its people came to ask whether any among the company could perform ruqyah one of the companions recited the opening chapter of the book al fatihah over him and he recovered the company was given thirty sheep which they accepted when they returned to the messenger of god and his family and recounted what had happened he allowed them to keep what they had taken', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 271, NULL, 'Abu Abdullah al-Sadiq, Jafar ibn Muhammad, was asked about a man who pays another a wage on the condition that the other teach him a craft and allow him to work alongside him. He permitted it. This falls within what was established earlier: if the craft is lawful, the arrangement is permitted. Whoever hires, or is hired, to teach something unlawful — singing, idle entertainment, and the like — the arrangement is not permitted.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'abu abdullah al sadiq jafar ibn muhammad was asked about a man who pays another a wage on the condition that the other teach him a craft and allow him to work alongside him he permitted it this falls within what was established earlier if the craft is lawful the arrangement is permitted whoever hires or is hired to teach something unlawful singing idle entertainment and the like the arrangement is not permitted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 272, NULL, 'On the question of the muezzin, it was related that the Commander of the Faithful said the muezzin''s wage falls among unlawful gain, suht, yet he also said there is no harm in the muezzin receiving a stipend from the public treasury. The apparent intent is that he disliked only the muezzin taking a wage directly from those for whom he calls the adhan. By the same principle, it was held undesirable for an imam to take a wage from those he leads in prayer, or for a judge to take one from the parties between whom he adjudicates — while it was permitted for all of them to be sustained from the Bayt al-Mal, the House of Wealth.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'on the question of the muezzin it was related that the commander of the faithful said the muezzins wage falls among unlawful gain suht yet he also said there is no harm in the muezzin receiving a stipend from the public treasury the apparent intent is that he disliked only the muezzin taking a wage directly from those for whom he calls the adhan by the same principle it was held undesirable for an imam to take a wage from those he leads in prayer or for a judge to take one from the parties between whom he adjudicates while it was permitted for all of them to be sustained from the bayt al mal the house of wealth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 273, NULL, 'Abu Abdullah Jafar ibn Muhammad was asked about the wage of the broker — the samsar — engaged by either the seller or the buyer, and he permitted it, provided the transaction on which the broker is hired is itself lawful. He was also asked about a broker who is given a commodity to sell and is set a price for it, on the condition that whatever he obtains above that price is his as his fee, and he permitted that arrangement as well. It was further held that a hired worker or craftsman who spoils or destroys what he was engaged to handle is liable for the damage — as with the fuller who tears a garment, or the tailor or the dyer who ruins it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'abu abdullah jafar ibn muhammad was asked about the wage of the broker the samsar engaged by either the seller or the buyer and he permitted it provided the transaction on which the broker is hired is itself lawful he was also asked about a broker who is given a commodity to sell and is set a price for it on the condition that whatever he obtains above that price is his as his fee and he permitted that arrangement as well it was further held that a hired worker or craftsman who spoils or destroys what he was engaged to handle is liable for the damage as with the fuller who tears a garment or the tailor or the dyer who ruins it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 274, NULL, 'A hired worker who spoils a task entrusted to him — who cuts a garment wrongly or departs from his instructions — and likewise a porter or carrier who breaks what he was paid to transport, bears responsibility for the loss whenever the goods were surrendered into his keeping and he himself took charge of them. Where a man merely lets out his animal while the renter accompanies his own goods, however, and those goods are broken or damaged while in the renter''s charge, no liability falls on the animal''s owner.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'a hired worker who spoils a task entrusted to him who cuts a garment wrongly or departs from his instructions and likewise a porter or carrier who breaks what he was paid to transport bears responsibility for the loss whenever the goods were surrendered into his keeping and he himself took charge of them where a man merely lets out his animal while the renter accompanies his own goods however and those goods are broken or damaged while in the renters charge no liability falls on the animals owner', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 275, NULL, 'If the hired worker or porter claims that what was handed to him was lost from his hands, and the one who delivered it denies this, the burden of proof lies with the claimant, and the oath falls on the one who handed over the goods — swearing that he does not know it to have been lost. The worker or porter remains liable unless he can produce proof of the loss; yet if proof establishes that the goods were stolen or wrested from his hands by force, nothing is owed by him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if the hired worker or porter claims that what was handed to him was lost from his hands and the one who delivered it denies this the burden of proof lies with the claimant and the oath falls on the one who handed over the goods swearing that he does not know it to have been lost the worker or porter remains liable unless he can produce proof of the loss yet if proof establishes that the goods were stolen or wrested from his hands by force nothing is owed by him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 276, NULL, 'Leasing and hiring are permitted for a price paid in specie or in goods. Jafar ibn Muhammad — prayers of Allah be upon him — was asked about taking the use of one house in exchange for the use of another, and he said, "There is nothing wrong with that." He was also asked about a man who rents dwellings by the month on the understanding that if he occupies them for a single day he is bound for the whole month, or for the whole year. The Master said that the man is held to whatever he has bound himself to.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'leasing and hiring are permitted for a price paid in specie or in goods jafar ibn muhammad prayers of allah be upon him was asked about taking the use of one house in exchange for the use of another and he said there is nothing wrong with that he was also asked about a man who rents dwellings by the month on the understanding that if he occupies them for a single day he is bound for the whole month or for the whole year the master said that the man is held to whatever he has bound himself to', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 277, NULL, 'When two parties dispute the payment of rent, with the house owner wishing to take payment in advance and the renter saying, "I will not pay you until the end of the month or the year," the Master ruled as follows: if they stipulated this arrangement as a condition at the outset, it stands as they contracted it; if they laid down no condition, the owner may take the rent day by day, each day as it falls due.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'when two parties dispute the payment of rent with the house owner wishing to take payment in advance and the renter saying i will not pay you until the end of the month or the year the master ruled as follows if they stipulated this arrangement as a condition at the outset it stands as they contracted it if they laid down no condition the owner may take the rent day by day each day as it falls due', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 278, NULL, 'He was also asked about a man who rents a house that has trees on the property and stipulates their fruit as part of the rental agreement. The Master said that this is permissible if the fruit was already in blossom at the time the contract was made — or if some of it was in blossom, or if there was some present yield alongside it. If none of these conditions held, the stipulation is not permissible, and the rental contract itself is void if it was concluded on that footing.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he was also asked about a man who rents a house that has trees on the property and stipulates their fruit as part of the rental agreement the master said that this is permissible if the fruit was already in blossom at the time the contract was made or if some of it was in blossom or if there was some present yield alongside it if none of these conditions held the stipulation is not permissible and the rental contract itself is void if it was concluded on that footing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 279, NULL, 'When asked about a man who rents a house that has been partly demolished, or that came to him through inheritance, or whose rooms leak when rain falls — and the renter presses the owner to carry out repairs — the Master said that the owner cannot be compelled to do so. If the damage harms the renter, however, he may reduce the rent and vacate, owing only for what he has already occupied. If the damage works no harm, the rental is not dissolved. The Master added that even where the renter has not stipulated that the owner repair what has decayed and clear out its drains, that obligation still falls upon the owner without any stipulation, because it is among the things known by custom to be incumbent upon the owner of a house. He also said that it is not permissible for the renter to bring into the house anything that would harm it, unless he has stipulated that right in the rental contract.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'when asked about a man who rents a house that has been partly demolished or that came to him through inheritance or whose rooms leak when rain falls and the renter presses the owner to carry out repairs the master said that the owner cannot be compelled to do so if the damage harms the renter however he may reduce the rent and vacate owing only for what he has already occupied if the damage works no harm the rental is not dissolved the master added that even where the renter has not stipulated that the owner repair what has decayed and clear out its drains that obligation still falls upon the owner without any stipulation because it is among the things known by custom to be incumbent upon the owner of a house he also said that it is not permissible for the renter to bring into the house anything that would harm it unless he has stipulated that right in the rental contract', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 280, NULL, 'When asked about a dispute between renter and owner over the amount of the rent — the owner claiming the greater sum and the renter the lesser, whether or not the renter has already occupied the house — the Master said that both parties take an oath. Whichever of them shrinks from the oath, the word of the other prevails, provided that other has sworn. If both swear, or both refuse the oath together, the rental is dissolved.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'when asked about a dispute between renter and owner over the amount of the rent the owner claiming the greater sum and the renter the lesser whether or not the renter has already occupied the house the master said that both parties take an oath whichever of them shrinks from the oath the word of the other prevails provided that other has sworn if both swear or both refuse the oath together the rental is dissolved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 281, NULL, 'When asked about the hire of undivided property (kira al-musha), the Master said that the hire of undivided property is permissible, just as its sale is permissible.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'when asked about the hire of undivided property kira al musha the master said that the hire of undivided property is permissible just as its sale is permissible', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 282, NULL, 'The Master was then asked about a man living in another man''s house who claims he was given lodging there free of charge, while the house''s owner says, "No — I let it to you for such and such a sum," and neither party has proof. The Master said that the owner swears he did not lodge the man without charge, and the resident then owes him the fair rental value — unless that fair value exceeds what the owner himself claimed to have charged, in which case the owner receives only the amount he acknowledged and no more. Likewise, if the renter claims the owner instructed him to spend on the house and to repair it, and he did so, but the owner denies having given any such instruction, then where the renter has no proof, the owner swears that he issued no such order, and the renter is entitled to recover the materials of the repair.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the master was then asked about a man living in another mans house who claims he was given lodging there free of charge while the houses owner says no i let it to you for such and such a sum and neither party has proof the master said that the owner swears he did not lodge the man without charge and the resident then owes him the fair rental value unless that fair value exceeds what the owner himself claimed to have charged in which case the owner receives only the amount he acknowledged and no more likewise if the renter claims the owner instructed him to spend on the house and to repair it and he did so but the owner denies having given any such instruction then where the renter has no proof the owner swears that he issued no such order and the renter is entitled to recover the materials of the repair', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 283, NULL, 'The Master was also asked about a man who rents a house in which the owner''s goods are stored, on the condition that the owner clears them out, and who after the contract is concluded finds the owner slow to remove them. The Master said that in such a case the owner is owed rent only to the extent the renter was actually able to occupy the house.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the master was also asked about a man who rents a house in which the owners goods are stored on the condition that the owner clears them out and who after the contract is concluded finds the owner slow to remove them the master said that in such a case the owner is owed rent only to the extent the renter was actually able to occupy the house', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 284, NULL, 'The Master was then asked about a house damaged, in whole or in part, through some act of the renter that had not been stipulated in the rental contract. He said that the renter guarantees whatever damage he caused in that way — unless the act in question is one that tenants customarily perform, in which case no liability falls on him even without an explicit stipulation, so long as it remains within what is commonly understood. Not every action a renter takes needs to be spelled out as a condition.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the master was then asked about a house damaged in whole or in part through some act of the renter that had not been stipulated in the rental contract he said that the renter guarantees whatever damage he caused in that way unless the act in question is one that tenants customarily perform in which case no liability falls on him even without an explicit stipulation so long as it remains within what is commonly understood not every action a renter takes needs to be spelled out as a condition', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 285, NULL, 'He was asked about an animal or a ship damaged before reaching the destination for which it was hired. He said that whoever hired a particular animal or ship — having seen it, inspected it, and taken it into his charge — finds the hire dissolved when it is damaged, and owes only the proportional rent for the distance already traveled. If, however, he hired carriage without naming any particular animal or ship, the carrier (makari) must furnish a substitute of equal quality to carry the load to the agreed destination, and the full rent remains due.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he was asked about an animal or a ship damaged before reaching the destination for which it was hired he said that whoever hired a particular animal or ship having seen it inspected it and taken it into his charge finds the hire dissolved when it is damaged and owes only the proportional rent for the distance already traveled if however he hired carriage without naming any particular animal or ship the carrier makari must furnish a substitute of equal quality to carry the load to the agreed destination and the full rent remains due', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 286, NULL, 'He was asked about one who hires an animal for a known number of days — to ride it, load it, grind with it, or thresh with it — fixing no precise schedule but naming only the intended use. He said that this arrangement is permissible, and the renter may put the animal to that use within just bounds. He must not press it beyond proper use, and the owner may not cut the agreed period short. If the renter named no intended use and then wishes to put the animal to some labor that would harm or diminish it, he has no right to do so.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he was asked about one who hires an animal for a known number of days to ride it load it grind with it or thresh with it fixing no precise schedule but naming only the intended use he said that this arrangement is permissible and the renter may put the animal to that use within just bounds he must not press it beyond proper use and the owner may not cut the agreed period short if the renter named no intended use and then wishes to put the animal to some labor that would harm or diminish it he has no right to do so', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 287, NULL, 'When someone asked about a person who hires an animal or a ship to carry a known load, on the condition that it be delivered within a fixed period, and then fails to deliver within that period and exceeds it, the Master said that a hire on such terms is void, and the hirer owes only the equivalent wage.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'when someone asked about a person who hires an animal or a ship to carry a known load on the condition that it be delivered within a fixed period and then fails to deliver within that period and exceeds it the master said that a hire on such terms is void and the hirer owes only the equivalent wage', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 288, NULL, 'It was related of Ali (prayers of Allah be upon him) that he gave judgment concerning a man who hired an animal to a named destination and then took it beyond that point, so that it perished. Ali held him liable for the animal itself but did not also charge him rent for the distance beyond the agreed limit. Al-Sadiq Jafar ibn Muhammad (prayers of Allah be upon him) added: if the animal did not perish, and the renter took it beyond the stipulated limit, then when its owner calls him to account for the excess, the owner may — as he chooses — either take a wage commensurate with that excess or take compensation for the diminishment the excess caused, but he may not take both together.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'it was related of ali prayers of allah be upon him that he gave judgment concerning a man who hired an animal to a named destination and then took it beyond that point so that it perished ali held him liable for the animal itself but did not also charge him rent for the distance beyond the agreed limit al sadiq jafar ibn muhammad prayers of allah be upon him added if the animal did not perish and the renter took it beyond the stipulated limit then when its owner calls him to account for the excess the owner may as he chooses either take a wage commensurate with that excess or take compensation for the diminishment the excess caused but he may not take both together', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 289, NULL, 'Likewise, if a man hires an animal for a day or several days and then keeps it beyond that term, the owner has the choice between taking the proportional rent for the time held after the term expired and taking the equivalent hire rate. If the animal perishes while he has held it past the stipulated term, he is a guarantor of its value.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'likewise if a man hires an animal for a day or several days and then keeps it beyond that term the owner has the choice between taking the proportional rent for the time held after the term expired and taking the equivalent hire rate if the animal perishes while he has held it past the stipulated term he is a guarantor of its value', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 290, NULL, 'When asked about a dispute between two parties over the distance of a journey — the renter claiming a far destination while the animal''s owner claims a near one, both agreeing that a hire took place — the Master said: the burden of proof falls on the one making the greater claim, which is the renter. If the renter produces no proof, the oath passes to the carrier (makari). If the two parties agree on the destination but differ over the route, the burden of proof falls on whoever claims the more arduous of the two roads, and the oath falls on the other. If the routes are equal in difficulty and the dispute is simply over which was contracted, the matter turns on whether the journey has begun:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'when asked about a dispute between two parties over the distance of a journey the renter claiming a far destination while the animals owner claims a near one both agreeing that a hire took place the master said the burden of proof falls on the one making the greater claim which is the renter if the renter produces no proof the oath passes to the carrier makari if the two parties agree on the destination but differ over the route the burden of proof falls on whoever claims the more arduous of the two roads and the oath falls on the other if the routes are equal in difficulty and the dispute is simply over which was contracted the matter turns on whether the journey has begun', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 291, NULL, 'If the renter has neither ridden nor set out, both parties take an oath and the contract is dissolved when neither produces proof; whoever refuses the oath is bound by his fellow''s claim. If the renter has already ridden or set out, the owner''s word prevails and the renter stands as the claimant.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if the renter has neither ridden nor set out both parties take an oath and the contract is dissolved when neither produces proof whoever refuses the oath is bound by his fellows claim if the renter has already ridden or set out the owners word prevails and the renter stands as the claimant', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 292, NULL, 'When asked about a man who hires carriage to a country, and the carrier, upon reaching the first settlement of that country, wishes the renter to alight there, while the renter insists on being taken to its farthest point — no particular place within that country having been named in the contract, as when a man hires carriage to Iraq, to Khurasan, to the Levant (al-Sham), to Africa (Ifriqiya), or to any country of that kind — the Master said: in such a case, the obligation is discharged upon reaching the chief city of that region: the one that is its mother-city, the one renowned as its heart, the one by whose name the region is known, and the one that travelers customarily have in mind when they set out for it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'when asked about a man who hires carriage to a country and the carrier upon reaching the first settlement of that country wishes the renter to alight there while the renter insists on being taken to its farthest point no particular place within that country having been named in the contract as when a man hires carriage to iraq to khurasan to the levant al sham to africa ifriqiya or to any country of that kind the master said in such a case the obligation is discharged upon reaching the chief city of that region the one that is its mother city the one renowned as its heart the one by whose name the region is known and the one that travelers customarily have in mind when they set out for it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 293, NULL, 'He was then asked about land taken on hire that is struck by calamity — flooding, the recession of water, the drying of a spring, or the cutting off of a river by which it was irrigated. The Master said: if the renter wishes to spend from that year''s rent on restoring it, he may do so, and the cost falls upon the landowner; otherwise, he owes only in proportion to what he has cultivated and benefited from, and the hire is dissolved from that point forward.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he was then asked about land taken on hire that is struck by calamity flooding the recession of water the drying of a spring or the cutting off of a river by which it was irrigated the master said if the renter wishes to spend from that years rent on restoring it he may do so and the cost falls upon the landowner otherwise he owes only in proportion to what he has cultivated and benefited from and the hire is dissolved from that point forward', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 294, NULL, 'He was asked about a hire in which an option (khiyar) is stipulated. The Master said: whatever is stipulated from among what is lawful and permissible stands as valid; whatever is not lawful and not permissible does not stand, and the hire itself remains in force as it is.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he was asked about a hire in which an option khiyar is stipulated the master said whatever is stipulated from among what is lawful and permissible stands as valid whatever is not lawful and not permissible does not stand and the hire itself remains in force as it is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 295, NULL, 'He was asked about a man who delivers wheat to the miller, or sesame to the oil-presser, stipulating a known measure to be returned to him in exchange for a fixed wage for the work. The Master said: to fix the arrangement in that manner is not permissible. The miller and the oil-presser are entitled to a fair wage for their labor, and the owner of the wheat or the sesame takes back whatever each of them actually produces.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he was asked about a man who delivers wheat to the miller or sesame to the oil presser stipulating a known measure to be returned to him in exchange for a fixed wage for the work the master said to fix the arrangement in that manner is not permissible the miller and the oil presser are entitled to a fair wage for their labor and the owner of the wheat or the sesame takes back whatever each of them actually produces', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 296, NULL, 'He was asked about the earnings of the cupper (al-hajjam), and he saw no harm in them. The Master said: the Messenger of Allah — may Allah bless him and his family and grant them peace — paid the cupper, and the Imams continue to pay them to this day; had it been unlawful, they would never have given it to them.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he was asked about the earnings of the cupper al hajjam and he saw no harm in them the master said the messenger of allah may allah bless him and his family and grant them peace paid the cupper and the imams continue to pay them to this day had it been unlawful they would never have given it to them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 297, NULL, 'He was asked about the craftsman approached by someone wanting work done, who promises what he later cannot deliver — a tailor, for instance, shown a garment who says he will cut matching cloth and then finds the cloth falls short; or a goldsmith who says a piece will require a certain weight of gold or silver, begins the work, melts the metal, and finds he cannot finish it; or one who presents gold or silver as sound when it proves to be base. The Master said: if each of them spoke to the best of his knowledge and the full extent of his effort, and then erred, nothing is held against him. But if it is established, or commonly known of him, that he intended to deceive his client, he is liable for whatever he has spoiled.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he was asked about the craftsman approached by someone wanting work done who promises what he later cannot deliver a tailor for instance shown a garment who says he will cut matching cloth and then finds the cloth falls short or a goldsmith who says a piece will require a certain weight of gold or silver begins the work melts the metal and finds he cannot finish it or one who presents gold or silver as sound when it proves to be base the master said if each of them spoke to the best of his knowledge and the full extent of his effort and then erred nothing is held against him but if it is established or commonly known of him that he intended to deceive his client he is liable for whatever he has spoiled', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 298, NULL, 'On Pledges', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'on pledges', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 299, NULL, 'Al-Baqarah: 282رِّجَالِكُمْ ۖ فَإِن لَّمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌۭ وَٱمْرَأَتَانِ مِمَّن تَرْضَوْنَ مِنَ ٱلشُّهَدَآءِ', '', 'رِّجَالِكُمْ ۖ فَإِن لَّمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌۭ وَٱمْرَأَتَانِ مِمَّن تَرْضَوْنَ مِنَ ٱلشُّهَدَآءِ', 'Al-Baqarah: 282', 2, 282, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'al baqarah 282رجالكم فان لم يكونا رجلين فرجل وامراتان ممن ترضون من الشهداء', 'رجالكم فان لم يكونا رجلين فرجل وامراتان ممن ترضون من الشهداء');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 300, NULL, '﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنْتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى فَاكْتُبُوهُ﴾, "O you who believe, when you contract a debt for a specified term, write it down" (al-Baqarah: 282), and ﴿وَلَمْ تَجِدُوا كَاتِبًا فَرِهَانٌ مَقْبُوضَةٌ﴾, "and you do not find a scribe, then a pledge taken in hand" (al-Baqarah: 283). These verses establish that a pledge (رَهِن) is valid only once it has been taken into possession; whatever has not been received is no pledge at all. Whatever may be sold may likewise be pledged. Whoever takes an undivided share in pledge receives possession of it in the same way an undivided share is received in a sale. The one holding a pledge may not derive any benefit from it. If the pledge perishes, the loss falls upon the wealth of the pledgor (رَهِن), unless the pledgee brought about its destruction. When a pledge is destroyed, the pledgee has no right to demand a replacement; his only recourse is to claim his debt when it falls due.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'يا ايها الذين امنوا اذا تداينتم بدين الي اجل مسمي فاكتبوه o you who believe when you contract a debt for a specified term write it down al baqarah 282 and ولم تجدوا كاتبا فرهان مقبوضه and you do not find a scribe then a pledge taken in hand al baqarah 283 these verses establish that a pledge رهن is valid only once it has been taken into possession whatever has not been received is no pledge at all whatever may be sold may likewise be pledged whoever takes an undivided share in pledge receives possession of it in the same way an undivided share is received in a sale the one holding a pledge may not derive any benefit from it if the pledge perishes the loss falls upon the wealth of the pledgor رهن unless the pledgee brought about its destruction when a pledge is destroyed the pledgee has no right to demand a replacement his only recourse is to claim his debt when it falls due', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 301, NULL, 'If the pledgor and the pledgee disagree over what the pledge was intended to secure, the burden of proof rests on the one claiming the greater amount, who is the pledgee, and the oath falls upon the pledgor regarding the excess claimed against him. If the pledge has already perished and the parties then differ over its value, the burden of proof again rests on the one claiming the surplus — here the pledgor, since the pledge was in his possession — and the pledgee swears regarding the excess he claims.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if the pledgor and the pledgee disagree over what the pledge was intended to secure the burden of proof rests on the one claiming the greater amount who is the pledgee and the oath falls upon the pledgor regarding the excess claimed against him if the pledge has already perished and the parties then differ over its value the burden of proof again rests on the one claiming the surplus here the pledgor since the pledge was in his possession and the pledgee swears regarding the excess he claims', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 302, NULL, 'The pledgee may not sell the pledge when its term falls due except by order of a judge, and only after the debt has been established before him. If the pledgor is absent, the judge orders the pledge sold on his behalf and the pledgor''s due paid from the proceeds — just as an absent debtor''s property is sold for his debt, the judge acting in the pledgor''s stead. Should the pledgee sell the pledge — whether at maturity, after it, or before it — without the pledgor having authorized him to do so, he is liable for it; and whatever he has enjoyed or profited from the pledge belongs to the pledgor.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the pledgee may not sell the pledge when its term falls due except by order of a judge and only after the debt has been established before him if the pledgor is absent the judge orders the pledge sold on his behalf and the pledgors due paid from the proceeds just as an absent debtors property is sold for his debt the judge acting in the pledgors stead should the pledgee sell the pledge whether at maturity after it or before it without the pledgor having authorized him to do so he is liable for it and whatever he has enjoyed or profited from the pledge belongs to the pledgor', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 303, NULL, 'The pledgor, for his part, may not sell the pledge, give it away, donate it as charity, free it if it is a slave, or remove it from his ownership by any means whatever, until he has redeemed it. The pledgee does not sell it either; rather, the matter is referred to the judge, who sells it on behalf of the absent party once the debt is established before him, appointing someone to carry out the sale and settle the debt from its proceeds, just as is done with property not held in pledge.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the pledgor for his part may not sell the pledge give it away donate it as charity free it if it is a slave or remove it from his ownership by any means whatever until he has redeemed it the pledgee does not sell it either rather the matter is referred to the judge who sells it on behalf of the absent party once the debt is established before him appointing someone to carry out the sale and settle the debt from its proceeds just as is done with property not held in pledge', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 304, NULL, 'If, however, the pledgor has authorized the pledgee to sell the pledge at maturity, and the pledgee then sells it — calling witnesses, striving to obtain the highest price, and conducting the sale to the fullest — nothing is held against him in that, even should the pledgor suspect him in the sale and wish to have him swear to it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if however the pledgor has authorized the pledgee to sell the pledge at maturity and the pledgee then sells it calling witnesses striving to obtain the highest price and conducting the sale to the fullest nothing is held against him in that even should the pledgor suspect him in the sale and wish to have him swear to it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 305, NULL, 'If the pledgee wishes to purchase the pledge himself, there is no objection, provided both parties agree: the price is set against the debt, and any surplus is settled between them.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if the pledgee wishes to purchase the pledge himself there is no objection provided both parties agree the price is set against the debt and any surplus is settled between them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 306, NULL, 'On Partnership', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'on partnership', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 307, NULL, 'Partnership in wealth — al-shirka — is permissible under the teaching of the Imams of the Ahl al-Bayt (prayers of Allah be upon them) when two men, or a group, enter into it together. Each party contributes wealth of his own and mingles it with his partner''s until the funds form a single pool, no longer separately distinguishable, from which they buy and sell together. Profit arising from that pool is shared between them; any loss falls upon them in proportion to what each contributed.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'partnership in wealth al shirka is permissible under the teaching of the imams of the ahl al bayt prayers of allah be upon them when two men or a group enter into it together each party contributes wealth of his own and mingles it with his partners until the funds form a single pool no longer separately distinguishable from which they buy and sell together profit arising from that pool is shared between them any loss falls upon them in proportion to what each contributed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 308, NULL, 'Neither partner may sell, buy, or initiate any new transaction involving their common fund without the knowledge and consent of the other. If, however, each grants the other full discretion to act as he sees fit, that latitude is permitted and the other partner has no claim against him for it — unless he wrongs him. In that case, the aggrieved partner may say to him:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'neither partner may sell buy or initiate any new transaction involving their common fund without the knowledge and consent of the other if however each grants the other full discretion to act as he sees fit that latitude is permitted and the other partner has no claim against him for it unless he wrongs him in that case the aggrieved partner may say to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 309, NULL, '"You have betrayed me," or "You favored another over me in buying and selling," or "in what I entrusted to your charge," or "you set out to squander my wealth" —', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'you have betrayed me or you favored another over me in buying and selling or in what i entrusted to your charge or you set out to squander my wealth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 310, NULL, 'or words to that effect. The aggrieved party then has the right to require his partner''s oath that he committed no such wrong and intended none of it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'or words to that effect the aggrieved party then has the right to require his partners oath that he committed no such wrong and intended none of it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 311, NULL, 'Where the two partners hold equal shares and stipulate that profit and loss are likewise to be divided equally, that stipulation is binding. Where they stipulate an unequal division, the profit is distributed as stipulated, while loss is borne in proportion to each partner''s capital, regardless of what was agreed regarding profit.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'where the two partners hold equal shares and stipulate that profit and loss are likewise to be divided equally that stipulation is binding where they stipulate an unequal division the profit is distributed as stipulated while loss is borne in proportion to each partners capital regardless of what was agreed regarding profit', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 312, NULL, 'When two partners contribute capital and labor in equal measure, both profit and loss are divided according to their agreed terms. If they stipulate a different arrangement, profit follows what they have stipulated, while loss remains proportional to the capital each has put in. The same principle holds when their contributions are unequal, so that one partner brings more than the other: profit is shared according to their agreement, but loss is borne in proportion to the capital.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'when two partners contribute capital and labor in equal measure both profit and loss are divided according to their agreed terms if they stipulate a different arrangement profit follows what they have stipulated while loss remains proportional to the capital each has put in the same principle holds when their contributions are unequal so that one partner brings more than the other profit is shared according to their agreement but loss is borne in proportion to the capital', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 313, NULL, 'When the money belongs to only one of the two partners, the arrangement becomes mudaraba — that is, speculation — and the partner who contributes no capital is the mudarib, the working partner. The terms may stipulate that the mudarib alone shall work the money and trade with it, or that both partners shall work together; either way, both are bound by what they have stipulated. Profit is divided between them according to their contract, but loss falls upon the owner of the money alone and not upon the mudarib. If the owner of the money guarantees the mudarib against any shortfall or loss he might incur, that guarantee voids the arrangement: it is no longer a valid mudaraba or partnership but becomes a loan. The borrower then keeps whatever gain he earns, and he must guarantee the principal as he would for any loan taken upon himself.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'when the money belongs to only one of the two partners the arrangement becomes mudaraba that is speculation and the partner who contributes no capital is the mudarib the working partner the terms may stipulate that the mudarib alone shall work the money and trade with it or that both partners shall work together either way both are bound by what they have stipulated profit is divided between them according to their contract but loss falls upon the owner of the money alone and not upon the mudarib if the owner of the money guarantees the mudarib against any shortfall or loss he might incur that guarantee voids the arrangement it is no longer a valid mudaraba or partnership but becomes a loan the borrower then keeps whatever gain he earns and he must guarantee the principal as he would for any loan taken upon himself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 314, NULL, 'When the mudarib violates any condition the owner of the money stipulated — whether in what he buys, what he trades in, where he travels, or any other term of the mudaraba contract — profit is still divided between them according to their agreement. Yet if a loss occurs, or the money passes out of his hands, he is its guarantor and answerable for whatever is lost, because he transgressed the terms.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'when the mudarib violates any condition the owner of the money stipulated whether in what he buys what he trades in where he travels or any other term of the mudaraba contract profit is still divided between them according to their agreement yet if a loss occurs or the money passes out of his hands he is its guarantor and answerable for whatever is lost because he transgressed the terms', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 315, NULL, 'If a man gives money to another to work with and trade in, on the condition that the recipient returns a specified, fixed profit, that arrangement is not permissible and is not binding upon the recipient. It is riba, which is unlawful, and he must return whatever he took and repent to Allah Almighty for it. The single exception arises when the one handing over the money is the master and the recipient his slave: what is paid to the slave is then lawful and permitted to him. There is no riba between a master and his slave, because the slave''s wealth belongs to his master in any case.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if a man gives money to another to work with and trade in on the condition that the recipient returns a specified fixed profit that arrangement is not permissible and is not binding upon the recipient it is riba which is unlawful and he must return whatever he took and repent to allah almighty for it the single exception arises when the one handing over the money is the master and the recipient his slave what is paid to the slave is then lawful and permitted to him there is no riba between a master and his slave because the slaves wealth belongs to his master in any case', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 316, NULL, 'When one of the partners dies, the partnership is dissolved. Any partner may also annul and dissolve it whenever he wishes. If a partner or a mudarib is accused of wrongdoing, he clears himself by oath.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'when one of the partners dies the partnership is dissolved any partner may also annul and dissolve it whenever he wishes if a partner or a mudarib is accused of wrongdoing he clears himself by oath', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 317, NULL, 'Partnership is disliked when it is formed over goods that remain distinct and are not mingled — each contribution kept separate from the other. When two parties share in what each holds apart, whatever each one holds remains his own, whether it increases or decreases. If they wish to enter a genuine partnership, however, each may sell to the other half of the separate goods in his possession at a known price, commit to that sale, and on that basis form a valid partnership.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'partnership is disliked when it is formed over goods that remain distinct and are not mingled each contribution kept separate from the other when two parties share in what each holds apart whatever each one holds remains his own whether it increases or decreases if they wish to enter a genuine partnership however each may sell to the other half of the separate goods in his possession at a known price commit to that sale and on that basis form a valid partnership', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 318, NULL, 'It is disliked for a Muslim to enter into partnership with a dhimmi, or for a believer to partner with one who differs from him in religion. Such a partner may buy and sell in ways the believer does not permit and cannot prevent, and that opens the door to unlawful gain and riba-tainted wealth entering his holdings. If, however, the believer or Muslim himself oversees all buying and selling and the dhimmi or the differing party has no hand in any transaction, the partnership is unobjectionable.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'it is disliked for a muslim to enter into partnership with a dhimmi or for a believer to partner with one who differs from him in religion such a partner may buy and sell in ways the believer does not permit and cannot prevent and that opens the door to unlawful gain and riba tainted wealth entering his holdings if however the believer or muslim himself oversees all buying and selling and the dhimmi or the differing party has no hand in any transaction the partnership is unobjectionable', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 319, NULL, 'When a mudarib dies leaving a debt he owes, speculation funds entrusted to him, and deposits held in his keeping, and none of these is found intact within his estate, the ruling distinguishes the debt from the trust. The debt is binding, because it rested upon his personal liability. The speculation funds and the deposit are a different matter — he held them as a trustee. If they are not found in his estate by their own substance, and no proof is established against him that he consumed them, was compensated for them, destroyed them, mingled them with his own wealth, or did anything else that would render him liable, then nothing is required of his heirs beyond an oath: that they do not know him to have done any such thing, that they have not done it themselves, and that none of it is in their possession.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'when a mudarib dies leaving a debt he owes speculation funds entrusted to him and deposits held in his keeping and none of these is found intact within his estate the ruling distinguishes the debt from the trust the debt is binding because it rested upon his personal liability the speculation funds and the deposit are a different matter he held them as a trustee if they are not found in his estate by their own substance and no proof is established against him that he consumed them was compensated for them destroyed them mingled them with his own wealth or did anything else that would render him liable then nothing is required of his heirs beyond an oath that they do not know him to have done any such thing that they have not done it themselves and that none of it is in their possession', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 320, NULL, 'If the holder of such a claim names, before his death, the party to whom a particular asset belongs, that asset goes to the one he named. If he did not hand it over before dying, however, the debt takes precedence and is satisfied first.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if the holder of such a claim names before his death the party to whom a particular asset belongs that asset goes to the one he named if he did not hand it over before dying however the debt takes precedence and is satisfied first', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 321, NULL, 'When the funds are already fully committed, they may not be shared with an absent partner, and partnership with one who is absent is not valid.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'when the funds are already fully committed they may not be shared with an absent partner and partnership with one who is absent is not valid', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 322, NULL, 'If a man is owed a debt and, before recovering it, attempts to bring that debt into a partnership or a mudaraba with the debtor, the arrangement is not valid and no partnership or mudaraba is formed — not until the creditor takes actual possession of the debt and hands it over. Only then may he use it to form a partnership or mudaraba.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if a man is owed a debt and before recovering it attempts to bring that debt into a partnership or a mudaraba with the debtor the arrangement is not valid and no partnership or mudaraba is formed not until the creditor takes actual possession of the debt and hands it over only then may he use it to form a partnership or mudaraba', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 323, NULL, 'When two partners separate and settle accounts while a debt from their partnership remains outstanding, they may not divide that debt on the condition that each recovers only his assigned share, to be held separately if a dispute arises later. What is required is that whatever either partner recovers belongs to both of them in common, and whatever portion of the debt is lost falls upon both alike. If, however, one says to the other, "Give me my capital" — or whatever sum they had agreed upon — "and yours is whatever exceeds it, and upon you falls whatever falls short," and both agree to this, then it is permissible for them to act on that agreement.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'when two partners separate and settle accounts while a debt from their partnership remains outstanding they may not divide that debt on the condition that each recovers only his assigned share to be held separately if a dispute arises later what is required is that whatever either partner recovers belongs to both of them in common and whatever portion of the debt is lost falls upon both alike if however one says to the other give me my capital or whatever sum they had agreed upon and yours is whatever exceeds it and upon you falls whatever falls short and both agree to this then it is permissible for them to act on that agreement', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 324, NULL, 'On Pre-emption', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'on pre emption', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 325, NULL, 'Pre-emption — shufah — applies to dwellings and real property when an undivided share or shares are sold: portions held in common that have not yet been partitioned between the seller and his partner or partners. In such a case, the partner holds a stronger claim to the sale than any stranger who has no share in it, and is the worthier pre-emptor. If one partner exercises his right while the others do not, he stands ahead of those who held back. If all come forward together, the property is shared equally among them, each taking according to his portion in the partnership. Where their shares differ, pre-emption follows those shares proportionally; where their shares are equal, it is divided equally among them.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'pre emption shufah applies to dwellings and real property when an undivided share or shares are sold portions held in common that have not yet been partitioned between the seller and his partner or partners in such a case the partner holds a stronger claim to the sale than any stranger who has no share in it and is the worthier pre emptor if one partner exercises his right while the others do not he stands ahead of those who held back if all come forward together the property is shared equally among them each taking according to his portion in the partnership where their shares differ pre emption follows those shares proportionally where their shares are equal it is divided equally among them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 326, NULL, 'Pre-emption does not apply to a neighbor or anyone else in property that has already been divided, nor does it apply to a river, a ship, an animal, or anything other than real estate and undivided shares — that is, land and whatever stands upon it of buildings or planted trees. Where a property is jointly owned and one partner sells his share, the other holds the stronger claim by pre-emption.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'pre emption does not apply to a neighbor or anyone else in property that has already been divided nor does it apply to a river a ship an animal or anything other than real estate and undivided shares that is land and whatever stands upon it of buildings or planted trees where a property is jointly owned and one partner sells his share the other holds the stronger claim by pre emption', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 327, NULL, 'Pre-emption is preserved on behalf of a minor until he comes of age. If his guardian or whoever is responsible for his affairs is able to exercise it for him, and doing so would benefit the child, it should be taken on his behalf. It is likewise preserved for an absent partner until he returns or news of the sale reaches him, at which point he has up to a year to take it up or let it pass. A partner who is present has the same span: one year from the moment the sale comes to his knowledge, unless he surrenders his right before that time.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'pre emption is preserved on behalf of a minor until he comes of age if his guardian or whoever is responsible for his affairs is able to exercise it for him and doing so would benefit the child it should be taken on his behalf it is likewise preserved for an absent partner until he returns or news of the sale reaches him at which point he has up to a year to take it up or let it pass a partner who is present has the same span one year from the moment the sale comes to his knowledge unless he surrenders his right before that time', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 328, NULL, 'The right belongs to the pre-emptor by virtue of his partnership in what is sold — whether his share is small or large, and whether he holds a stake in the whole property or only in part. This includes a wall standing between two houses that belongs to both owners, or in which one of them holds a common share, or any other right they own together that the sale touches, whether slight or considerable. Pre-emption in such a thing belongs to whoever holds a share in it, however small or large that share may be.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the right belongs to the pre emptor by virtue of his partnership in what is sold whether his share is small or large and whether he holds a stake in the whole property or only in part this includes a wall standing between two houses that belongs to both owners or in which one of them holds a common share or any other right they own together that the sale touches whether slight or considerable pre emption in such a thing belongs to whoever holds a share in it however small or large that share may be', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 329, NULL, 'Pre-emption belongs to the people of a private lane — al-Raighah — who share the lane without directly partnering with one another in ownership, provided no barrier separates them from the property in question. No such right exists in a public thoroughfare, because the people whose dwellings open onto a public street do not own it as the people of a private lane own theirs. They benefit from it only through their courtyards, and in this they stand on exactly the same footing as any passer-by. The right of pre-emption over what is sold along a public street therefore does not belong to those who front it; it belongs to the people of the private lane among themselves.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'pre emption belongs to the people of a private lane al raighah who share the lane without directly partnering with one another in ownership provided no barrier separates them from the property in question no such right exists in a public thoroughfare because the people whose dwellings open onto a public street do not own it as the people of a private lane own theirs they benefit from it only through their courtyards and in this they stand on exactly the same footing as any passer by the right of pre emption over what is sold along a public street therefore does not belong to those who front it it belongs to the people of the private lane among themselves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 330, NULL, 'Where a house sits within a private lane and contains a dwelling, and that dwelling is sold, the people of the surrounding houses hold a stronger claim to pre-emption than the buyer, and they may exercise it over whatever is sold within the lane — because they hold ownership of their own courtyards, while the people of the lane itself own nothing of those interior houses. The same principle applies when a lane runs within a lane: the people of the inner lane may pre-empt what lies along their own path and passage. The people of the outer lane, including those at its upper reaches, may not pre-empt what lies below them, in which they hold no right and to which they have no path beyond the boundaries of their own portion of the lane. The question in every case is examined in light of shared rights, for it is the sharing of rights that governs.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'where a house sits within a private lane and contains a dwelling and that dwelling is sold the people of the surrounding houses hold a stronger claim to pre emption than the buyer and they may exercise it over whatever is sold within the lane because they hold ownership of their own courtyards while the people of the lane itself own nothing of those interior houses the same principle applies when a lane runs within a lane the people of the inner lane may pre empt what lies along their own path and passage the people of the outer lane including those at its upper reaches may not pre empt what lies below them in which they hold no right and to which they have no path beyond the boundaries of their own portion of the lane the question in every case is examined in light of shared rights for it is the sharing of rights that governs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 331, NULL, 'Whoever holds a right in what is sold — or in any of the rights upon which the sale falls — is a partner, and therefore a pre-emptor. This reflects the principle of shared rights among the people of the lane.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'whoever holds a right in what is sold or in any of the rights upon which the sale falls is a partner and therefore a pre emptor this reflects the principle of shared rights among the people of the lane', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 332, NULL, 'If a man owned outright all the houses within his lane, it would be his right to open the lane from the outside, to possess the whole of it, and to bar anyone from entering or passing through it without his leave. So too, when there is a lane within a lane and the owner of the inner lane owns all the houses opening onto it, he may take possession of the whole and withhold it from others. The same applies to everything within the lane, except what is bordered by a wall belonging to others among the people of the lane — there his ownership reaches only to its boundary.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if a man owned outright all the houses within his lane it would be his right to open the lane from the outside to possess the whole of it and to bar anyone from entering or passing through it without his leave so too when there is a lane within a lane and the owner of the inner lane owns all the houses opening onto it he may take possession of the whole and withhold it from others the same applies to everything within the lane except what is bordered by a wall belonging to others among the people of the lane there his ownership reaches only to its boundary', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 333, NULL, 'A Jew or a Christian has no right of pre-emption against a Muslim. Muslims, however, may exercise pre-emption in property they share with other Muslims and with dhimmis alike. Dhimmis, for their part, may pre-empt against one another in transactions where pre-emption would ordinarily apply, but they hold no such right against Muslims.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'a jew or a christian has no right of pre emption against a muslim muslims however may exercise pre emption in property they share with other muslims and with dhimmis alike dhimmis for their part may pre empt against one another in transactions where pre emption would ordinarily apply but they hold no such right against muslims', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 334, NULL, 'Pre-emption does not arise in the following cases:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'pre emption does not arise in the following cases', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 335, NULL, 'A gift Charity A grant of residence A life grant A grant made for the lifetime of the recipient', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'a gift charity a grant of residence a life grant a grant made for the lifetime of the recipient', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 336, NULL, 'Nor does pre-emption apply when a sale is concluded against goods rather than a monetary price — as when a house is exchanged for another house, for a riding animal, or for any other livestock or merchandise. In such a case, the pre-emptor cannot claim the house by offering the value of the goods on which the transaction was concluded.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'nor does pre emption apply when a sale is concluded against goods rather than a monetary price as when a house is exchanged for another house for a riding animal or for any other livestock or merchandise in such a case the pre emptor cannot claim the house by offering the value of the goods on which the transaction was concluded', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 337, NULL, 'The same principle holds when a man gives a house as a dowry upon marrying a woman. Even if pre-emption would ordinarily be due in such a house, the pre-emptor cannot say, "I will pay a dowry equal to this woman''s and take the house."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the same principle holds when a man gives a house as a dowry upon marrying a woman even if pre emption would ordinarily be due in such a house the pre emptor cannot say i will pay a dowry equal to this womans and take the house', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 338, NULL, 'If, however, a house was sold for a price and a quantity of goods was received in settlement of that price, the pre-emptor is offered the house at the price on which the sale was concluded. Likewise, if the owner of a house marries a woman for a known dowry and then hands her a house in settlement of it, this constitutes a sale, and the pre-emptor may take the house for the dowry by which the woman received it. When what is subject to pre-emption is sold for something that has a known equivalent — measured wheat, dates, or anything else sold by measure or weight for which an equivalent is established — pre-emption is due, and the pre-emptor receives that equivalent in place of the price.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if however a house was sold for a price and a quantity of goods was received in settlement of that price the pre emptor is offered the house at the price on which the sale was concluded likewise if the owner of a house marries a woman for a known dowry and then hands her a house in settlement of it this constitutes a sale and the pre emptor may take the house for the dowry by which the woman received it when what is subject to pre emption is sold for something that has a known equivalent measured wheat dates or anything else sold by measure or weight for which an equivalent is established pre emption is due and the pre emptor receives that equivalent in place of the price', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 339, NULL, 'The pre-emptor may press his claim against either the seller or the buyer, depending on which party bears the obligation at the time. When a sale has been concluded and completed between the two parties, and the pre-emptor comes forward against the seller before the price has been collected from the buyer and pays it to him, what he receives in return is rightfully his. The buyer cannot block him or say, "I will pay what I bought it for and take it from you, since the pre-emption stands against me." The pre-emptor''s claim rests upon the seller, and the buyer is bound to deliver. If, on the other hand, the buyer pays the price first and the pre-emptor then presses his claim against the buyer within the period in which the claim remains valid, that too is his right.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the pre emptor may press his claim against either the seller or the buyer depending on which party bears the obligation at the time when a sale has been concluded and completed between the two parties and the pre emptor comes forward against the seller before the price has been collected from the buyer and pays it to him what he receives in return is rightfully his the buyer cannot block him or say i will pay what i bought it for and take it from you since the pre emption stands against me the pre emptors claim rests upon the seller and the buyer is bound to deliver if on the other hand the buyer pays the price first and the pre emptor then presses his claim against the buyer within the period in which the claim remains valid that too is his right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 340, NULL, 'When property subject to pre-emption passes from buyer to buyer in a chain of successive sales — whether the pre-emptor is aware of them or not — he may press his claim against whichever party in that chain he chooses, paying that party the price that party itself paid to acquire the property, whether more or less than the original purchase price. This right holds as long as the pre-emption period has not expired and he has not relinquished his claim. He stands as pre-emptor at the moment of every sale in the chain, and his failure to act against any one of those sales does not forfeit his right while the period still runs.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'when property subject to pre emption passes from buyer to buyer in a chain of successive sales whether the pre emptor is aware of them or not he may press his claim against whichever party in that chain he chooses paying that party the price that party itself paid to acquire the property whether more or less than the original purchase price this right holds as long as the pre emption period has not expired and he has not relinquished his claim he stands as pre emptor at the moment of every sale in the chain and his failure to act against any one of those sales does not forfeit his right while the period still runs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 341, NULL, 'The principle may be illustrated as follows. A buyer acquires property that is subject to another''s right of pre-emption, then sells it to a second party for more or less than he paid; that second party sells to a third, and so on through a succession of owners. The pre-emptor may press his claim against any one of them he selects, provided the period reckoned from the original purchase has not elapsed and he has not surrendered his right.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the principle may be illustrated as follows a buyer acquires property that is subject to anothers right of pre emption then sells it to a second party for more or less than he paid that second party sells to a third and so on through a succession of owners the pre emptor may press his claim against any one of them he selects provided the period reckoned from the original purchase has not elapsed and he has not surrendered his right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 342, NULL, 'If he presses his claim against the first buyer — who had, within the pre-emption period, already sold the property for more than he paid — the effect is to unwind that sale and every subsequent transfer. The pre-emptor then takes the property at the price the first buyer paid, delivering that amount to him. The same course applies to each party who came after: the claim against any one of them unwinds the chain from that point forward on the same terms.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if he presses his claim against the first buyer who had within the pre emption period already sold the property for more than he paid the effect is to unwind that sale and every subsequent transfer the pre emptor then takes the property at the price the first buyer paid delivering that amount to him the same course applies to each party who came after the claim against any one of them unwinds the chain from that point forward on the same terms', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 343, NULL, 'Where a single house contains an upper and a lower dwelling, divided and sold separately, the owner of the upper has no pre-emption over the owner of the lower, nor the lower over the upper, provided the division took place before the sale. However one part stands above the other, the relationship between them is simply that of neighbors. If, however, they share a common entrance or any other element that remains undivided, and the sale falls upon the seller''s share in that common property, then pre-emption applies to it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'where a single house contains an upper and a lower dwelling divided and sold separately the owner of the upper has no pre emption over the owner of the lower nor the lower over the upper provided the division took place before the sale however one part stands above the other the relationship between them is simply that of neighbors if however they share a common entrance or any other element that remains undivided and the sale falls upon the sellers share in that common property then pre emption applies to it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 344, NULL, 'When undivided and divided property are sold together in a single transaction, the partner in the jointly held portion may claim the whole — both the common and the divided parts. He may not take one without the other, unless both parties agree to it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'when undivided and divided property are sold together in a single transaction the partner in the jointly held portion may claim the whole both the common and the divided parts he may not take one without the other unless both parties agree to it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 345, NULL, 'If a buyer purchases the common share at an agreed price and the sale is concluded between him and the seller, and the seller then reduces part of that price so that the sale finally rests on the lesser amount actually received, the pre-emptor who subsequently comes forward may not demand to take the property at the original, higher price. He is entitled only to what was in fact paid, since the sale came to rest on that reduced sum.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if a buyer purchases the common share at an agreed price and the sale is concluded between him and the seller and the seller then reduces part of that price so that the sale finally rests on the lesser amount actually received the pre emptor who subsequently comes forward may not demand to take the property at the original higher price he is entitled only to what was in fact paid since the sale came to rest on that reduced sum', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 346, NULL, 'If a seller sells the property at an agreed price and then returns some or all of that price to the buyer — whether as a gift or as charity — the pre-emptor who comes forward to exercise his right must pay the price upon which the sale was originally contracted. He may not deduct what the seller returned to the buyer, for that return was a stratagem designed to extinguish the pre-emption.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if a seller sells the property at an agreed price and then returns some or all of that price to the buyer whether as a gift or as charity the pre emptor who comes forward to exercise his right must pay the price upon which the sale was originally contracted he may not deduct what the seller returned to the buyer for that return was a stratagem designed to extinguish the pre emption', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 347, NULL, 'The same principle applies when the device runs the other way. Should the seller inflate the declared price and then hand the surplus back to the buyer, or should the buyer pay part of the sum as profit and part as price in order to circumvent the pre-emptor, what governs is the underlying contract and the true intention behind it. The sale is held to rest upon the whole price, or upon what was genuinely received. Gifts and charitable transfers used to disguise the real transaction do not defeat the pre-emptor''s right.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the same principle applies when the device runs the other way should the seller inflate the declared price and then hand the surplus back to the buyer or should the buyer pay part of the sum as profit and part as price in order to circumvent the pre emptor what governs is the underlying contract and the true intention behind it the sale is held to rest upon the whole price or upon what was genuinely received gifts and charitable transfers used to disguise the real transaction do not defeat the pre emptors right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 348, NULL, 'If the price was inflated and the pre-emptor still wishes to proceed, he pays only what the buyer actually paid and receives everything the two parties genuinely agreed upon. This is established either by the buyer''s own acknowledgment — made against his own interest — or by clear proof that the arrangement was a contrivance. If the pre-emptor merely alleges manipulation without proof, and the other party denies it, the most that can be required of the denying party is an oath in answer to the claim.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if the price was inflated and the pre emptor still wishes to proceed he pays only what the buyer actually paid and receives everything the two parties genuinely agreed upon this is established either by the buyers own acknowledgment made against his own interest or by clear proof that the arrangement was a contrivance if the pre emptor merely alleges manipulation without proof and the other party denies it the most that can be required of the denying party is an oath in answer to the claim', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 349, NULL, 'Such manipulation to defeat pre-emption is unlawful for both seller and buyer alike. It is a conspiracy to extinguish one of the established rights.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'such manipulation to defeat pre emption is unlawful for both seller and buyer alike it is a conspiracy to extinguish one of the established rights', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 350, NULL, 'Where a sale has been concealed, the pre-emptor''s right runs from the moment the sale comes to his knowledge, and remains open for one year — just as it does when the sale is open and known. Equally, if the shafi holds the right of pre-emption and the sale was conducted in secret, his claim may be pressed from the moment he learns of it, and that right remains available to him for one year, even if the sale was in fact publicly known and he was present when it took place.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'where a sale has been concealed the pre emptors right runs from the moment the sale comes to his knowledge and remains open for one year just as it does when the sale is open and known equally if the shafi holds the right of pre emption and the sale was conducted in secret his claim may be pressed from the moment he learns of it and that right remains available to him for one year even if the sale was in fact publicly known and he was present when it took place', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 351, NULL, 'If he allows the year to pass and only then claims he was never informed of the sale, his claim is not accepted, because the sale was a matter of common knowledge. The duty to claim does not arise until the sale has been concluded and finalized. Once it is concluded and finalized and the pre-emptor is bound to his claim, that obligation holds even if the seller has not yet received the price — and the pre-emptor may pay whichever of the two parties he chooses, whether the seller or the buyer.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if he allows the year to pass and only then claims he was never informed of the sale his claim is not accepted because the sale was a matter of common knowledge the duty to claim does not arise until the sale has been concluded and finalized once it is concluded and finalized and the pre emptor is bound to his claim that obligation holds even if the seller has not yet received the price and the pre emptor may pay whichever of the two parties he chooses whether the seller or the buyer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 352, NULL, 'If the pre-emptor proceeds against the buyer, the buyer''s obligation extends only to delivering the property to him. The warranty for that property rests upon the original seller; no warranty falls upon the buyer when the pre-emptor proceeds against him, since the delivery traces back to the seller.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if the pre emptor proceeds against the buyer the buyers obligation extends only to delivering the property to him the warranty for that property rests upon the original seller no warranty falls upon the buyer when the pre emptor proceeds against him since the delivery traces back to the seller', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 353, NULL, 'If the buyer has built upon the purchased property that is subject to pre-emption, or has sown it, that act counts as a completed taking of possession.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if the buyer has built upon the purchased property that is subject to pre emption or has sown it that act counts as a completed taking of possession', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 354, NULL, 'If a man claims to have purchased the property from someone who is absent, the pre-emptor may come forward, yet neither the sale nor the pre-emption is established against the absent party. The pre-emptor may not exercise his right until the sale is shown to be valid. Likewise, if a man claims to have purchased from someone present who denies the sale, the pre-emptor may not press his claim until the sale is validated — and his right of pre-emption then runs from the moment of that validation.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if a man claims to have purchased the property from someone who is absent the pre emptor may come forward yet neither the sale nor the pre emption is established against the absent party the pre emptor may not exercise his right until the sale is shown to be valid likewise if a man claims to have purchased from someone present who denies the sale the pre emptor may not press his claim until the sale is validated and his right of pre emption then runs from the moment of that validation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 355, NULL, 'If a house is held as an endowment for particular named persons, and one of them builds within it and then dies — so that his portion passes to his heirs — and some of those heirs sell their inherited share, the right of pre-emption belongs to the remaining heirs. Whoever relinquished his pre-emption before the sale, and then comes forward after the sale has taken place, is free to press his claim or to leave it, since a relinquishment is not binding until after the sale has been concluded.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if a house is held as an endowment for particular named persons and one of them builds within it and then dies so that his portion passes to his heirs and some of those heirs sell their inherited share the right of pre emption belongs to the remaining heirs whoever relinquished his pre emption before the sale and then comes forward after the sale has taken place is free to press his claim or to leave it since a relinquishment is not binding until after the sale has been concluded', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 356, NULL, 'If the pre-emptor and the buyer disagree over the price, the buyer''s word is accepted under oath that he purchased at the price he names, and that price is what the pre-emptor pays — unless clear evidence is established to the contrary. Equally, if the pre-emptor accepts the buyer''s word, or the buyer swears and the pre-emptor pays him that sworn price, and it afterward emerges through evidence that the buyer in fact purchased for less, or the buyer himself admits as much, the pre-emptor may recover from him whatever was charged above the true price.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if the pre emptor and the buyer disagree over the price the buyers word is accepted under oath that he purchased at the price he names and that price is what the pre emptor pays unless clear evidence is established to the contrary equally if the pre emptor accepts the buyers word or the buyer swears and the pre emptor pays him that sworn price and it afterward emerges through evidence that the buyer in fact purchased for less or the buyer himself admits as much the pre emptor may recover from him whatever was charged above the true price', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 357, NULL, 'If the pre-emptor exercises his right and then exchanges the property and sells it onward, and afterward turns to the buyer demanding that the buyer pay him the price and return what was bought from him — making that the substance of his pre-emption claim — he is bound to carry it through. If he does not press the claim, nothing is required of him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'if the pre emptor exercises his right and then exchanges the property and sells it onward and afterward turns to the buyer demanding that the buyer pay him the price and return what was bought from him making that the substance of his pre emption claim he is bound to carry it through if he does not press the claim nothing is required of him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 358, NULL, 'This represents, in its entirety, the position of the Ahl al-Bayt, may.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'this represents in its entirety the position of the ahl al bayt may', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 359, NULL, 'On the preservation of oaths and covenants', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'on the preservation of oaths and covenants', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 360, NULL, 'Allah, Mighty and Majestic, said: "And guard your oaths" (Al-Maidah 89). And: "And those who are keepers of their trusts and their covenant" (Al-Muminun 8). And He said: "Fulfill the covenant of Allah when you have made a covenant, and do not break your oaths after their confirmation, when you have made Allah a surety over you" (Al-Nahl 91). And He said: "Indeed, those who exchange the covenant of Allah and their own oaths for a small price will have no share in the Hereafter; Allah will not speak to them, nor look upon them on the Day of Resurrection, nor purify them, and theirs is a painful punishment" (Al Imran 77).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'allah mighty and majestic said and guard your oaths al maidah 89 and and those who are keepers of their trusts and their covenant al muminun 8 and he said fulfill the covenant of allah when you have made a covenant and do not break your oaths after their confirmation when you have made allah a surety over you al nahl 91 and he said indeed those who exchange the covenant of allah and their own oaths for a small price will have no share in the hereafter allah will not speak to them nor look upon them on the day of resurrection nor purify them and theirs is a painful punishment al imran 77', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 361, NULL, 'The Messenger of Allah forbade swearing by any other than Allah, Mighty and Majestic, and said: "Whoever swears, let him swear by Allah; whoever swears by Allah, let him be truthful; and whoever has another swear to him by Allah, let him accept it; and whoever does not do so is no Muslim." He also said: "Three are those at whom Allah will not look on the Day of Resurrection, whom He will not purify, and for whom there is a painful punishment: a man who pledges allegiance to an imam for a portion of this world, so that if he is given it he keeps faith, and if he is not given it he withholds it; a man who has water beside the road and denies it to the traveler; and a man who swears after the afternoon prayer that he was offered such-and-such for his goods, so that another takes him at his word and accepts it, while he is lying."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the messenger of allah forbade swearing by any other than allah mighty and majestic and said whoever swears let him swear by allah whoever swears by allah let him be truthful and whoever has another swear to him by allah let him accept it and whoever does not do so is no muslim he also said three are those at whom allah will not look on the day of resurrection whom he will not purify and for whom there is a painful punishment a man who pledges allegiance to an imam for a portion of this world so that if he is given it he keeps faith and if he is not given it he withholds it a man who has water beside the road and denies it to the traveler and a man who swears after the afternoon prayer that he was offered such and such for his goods so that another takes him at his word and accepts it while he is lying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 362, NULL, 'Ali, may the blessings of Allah be upon him, said: "Allah, Mighty and Majestic, does not hallow one who swears by His name falsely." It is also related from him that he said: "Beware the false oath, for it makes the merchandise sell but wipes away the blessing; and whoever swears a false oath has been audacious against Allah, so let him await His punishment." And he, the blessings of Allah be upon him, said: "Whoever breaks his pledge of allegiance will meet Allah on the Day of Resurrection maimed" — meaning he will have no hand.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'ali may the blessings of allah be upon him said allah mighty and majestic does not hallow one who swears by his name falsely it is also related from him that he said beware the false oath for it makes the merchandise sell but wipes away the blessing and whoever swears a false oath has been audacious against allah so let him await his punishment and he the blessings of allah be upon him said whoever breaks his pledge of allegiance will meet allah on the day of resurrection maimed meaning he will have no hand', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 363, NULL, 'On what is binding in oaths and what is not', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'on what is binding in oaths and what is not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 364, NULL, 'Allah, Mighty and Majestic, said: "Allah will not take you to task for the thoughtless word in your oaths" (Al-Baqarah 225). Jafar ibn Muhammad, the blessings of Allah be upon him, said: Allah will not call you to account for the thoughtless word in your oaths. The thoughtlessness meant here is a man''s saying "No, by Allah" and "Yes, by Allah" while his heart is not set upon the oath — that is, what a person utters in the ordinary flow of speech, swearing by Allah within it without any intention of swearing. This is confirmed by the words of Allah, Mighty and Majestic, that follow: "Allah will not take you to task for the thoughtless word in your oaths, but He will take you to task for the oaths your hearts have deliberately bound" (Al-Maidah 89) — meaning what the swearer has resolved in his heart to swear upon.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'allah mighty and majestic said allah will not take you to task for the thoughtless word in your oaths al baqarah 225 jafar ibn muhammad the blessings of allah be upon him said allah will not call you to account for the thoughtless word in your oaths the thoughtlessness meant here is a mans saying no by allah and yes by allah while his heart is not set upon the oath that is what a person utters in the ordinary flow of speech swearing by allah within it without any intention of swearing this is confirmed by the words of allah mighty and majestic that follow allah will not take you to task for the thoughtless word in your oaths but he will take you to task for the oaths your hearts have deliberately bound al maidah 89 meaning what the swearer has resolved in his heart to swear upon', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 365, NULL, 'Jafar ibn Muhammad, the blessings of Allah be upon him, made this plain. Of a man who declares, in the course of ordinary speech, "By Allah, I did not do it," concerning something he did in fact do — while his conscience is not fixed upon the oath — he said: "It is a lie he has told; let him seek Allah''s forgiveness for it." He also said: "The oath is according to what the claimant administers it upon."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'jafar ibn muhammad the blessings of allah be upon him made this plain of a man who declares in the course of ordinary speech by allah i did not do it concerning something he did in fact do while his conscience is not fixed upon the oath he said it is a lie he has told let him seek allahs forgiveness for it he also said the oath is according to what the claimant administers it upon', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 366, NULL, 'It is further related that he forbade equivocation in oaths. He held that if a man has been wronged, the oath is judged by the intention of the one who swears it; if he is the wrongdoer, it is judged by the intention of the one who administers it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'it is further related that he forbade equivocation in oaths he held that if a man has been wronged the oath is judged by the intention of the one who swears it if he is the wrongdoer it is judged by the intention of the one who administers it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 367, NULL, 'Equivocation is the use of likeness in speech: a man intends one thing but frames it in terms that suggest another, leading the listener to take the suggested meaning as the true one, while he conceals an altogether different intent. As for the People of the Book, they are made to swear by Allah and by whatever they hold in reverence within their own faith.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'equivocation is the use of likeness in speech a man intends one thing but frames it in terms that suggest another leading the listener to take the suggested meaning as the true one while he conceals an altogether different intent as for the people of the book they are made to swear by allah and by whatever they hold in reverence within their own faith', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 368, NULL, 'Abu Abd Allah Jafar ibn Muhammad, the blessings of Allah be upon him, commented on the words of Allah, Mighty and Majestic: "And remember your Lord when you forget" (Al-Kahf 24). The verse, he said, concerns the oath. If one says, "By Allah, I will surely do such-and-such," and forgets to make the exception, then upon remembering, one should say, "if Allah wills."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'abu abd allah jafar ibn muhammad the blessings of allah be upon him commented on the words of allah mighty and majestic and remember your lord when you forget al kahf 24 the verse he said concerns the oath if one says by allah i will surely do such and such and forgets to make the exception then upon remembering one should say if allah wills', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 369, NULL, 'He then related that Ali, the blessings of Allah be upon him, reported that a company of Jews came to the Messenger of Allah and put a question to him. The Messenger replied, "Tomorrow I will tell you of it," and waited for revelation from Allah, Mighty and Majestic — yet he had not made the exception in his words. The revelation was withheld from him for forty days, after which these verses came down upon him: "And never say of anything, Indeed I will do that tomorrow, except that Allah wills; and remember your Lord when you forget" (Al-Kahf 23–24).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'he then related that ali the blessings of allah be upon him reported that a company of jews came to the messenger of allah and put a question to him the messenger replied tomorrow i will tell you of it and waited for revelation from allah mighty and majestic yet he had not made the exception in his words the revelation was withheld from him for forty days after which these verses came down upon him and never say of anything indeed i will do that tomorrow except that allah wills and remember your lord when you forget al kahf 23 24', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 370, NULL, 'The masters of this tradition commanded that an oath include the exception — placing the will of Allah before the sworn word — and held this to be commendable. The Commander of the Believers, the blessings of Allah be upon him, said that whoever swears and then says "if Allah wills" incurs no perjury. Jafar ibn Muhammad, the blessings of Allah be upon him, said that if a man moves his tongue with the exception, the exception holds, even if he does not say it aloud. He also related that the Messenger of Allah said: a man''s oath admits of an exception, and that exception stands when it is joined to the oath — when he swears and then says "if Allah wills" before his speech breaks off. By consensus, this is a permissible exception, and one who swears and excepts in this way does not fall into perjury.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the masters of this tradition commanded that an oath include the exception placing the will of allah before the sworn word and held this to be commendable the commander of the believers the blessings of allah be upon him said that whoever swears and then says if allah wills incurs no perjury jafar ibn muhammad the blessings of allah be upon him said that if a man moves his tongue with the exception the exception holds even if he does not say it aloud he also related that the messenger of allah said a mans oath admits of an exception and that exception stands when it is joined to the oath when he swears and then says if allah wills before his speech breaks off by consensus this is a permissible exception and one who swears and excepts in this way does not fall into perjury', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 371, NULL, 'Jafar ibn Muhammad, the blessings of Allah be upon him, said further that the exception remains permissible even after forty days. The ground for this is the case of the Messenger of Allah himself: revelation was withheld from him after his words to the Jews who questioned him — "Tomorrow I will tell you" — and when it came, Allah, Mighty and Majestic, said, "And remember your Lord when you forget" (Al-Kahf 24). The exception arrived with that verse, forty days after the oath was spoken. A parallel report is transmitted from Ali, the Commander of the Believers, the blessings of Allah be upon him. And it is related from Abu Jafar Muhammad ibn Ali, the blessings of Allah be upon him, that he said: the exception is permissible even after a year.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'jafar ibn muhammad the blessings of allah be upon him said further that the exception remains permissible even after forty days the ground for this is the case of the messenger of allah himself revelation was withheld from him after his words to the jews who questioned him tomorrow i will tell you and when it came allah mighty and majestic said and remember your lord when you forget al kahf 24 the exception arrived with that verse forty days after the oath was spoken a parallel report is transmitted from ali the commander of the believers the blessings of allah be upon him and it is related from abu jafar muhammad ibn ali the blessings of allah be upon him that he said the exception is permissible even after a year', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 372, NULL, 'The exception in an oath applies only to what the swearer himself swore he would or would not do. When a man is put under oath over a right claimed against him — when he swears to the claimant and makes an exception, whether silently or aloud — that exception counts for nothing. Such an oath rests on intentions, on the apparent words spoken, and on the intention of the one who administers it. If the swearer conceals something by which he means to escape the oath, or devises a trick within it, or equivocates, nothing of the obligation is lifted from him; the oath and the perjury both stand. He must discharge what he swore to the one to whom it is due, and repent thereafter and seek forgiveness. There is no expiation for perjury in such a case except that he carry out what he swore for the one entitled to it, and then turn in repentance and seek forgiveness.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the exception in an oath applies only to what the swearer himself swore he would or would not do when a man is put under oath over a right claimed against him when he swears to the claimant and makes an exception whether silently or aloud that exception counts for nothing such an oath rests on intentions on the apparent words spoken and on the intention of the one who administers it if the swearer conceals something by which he means to escape the oath or devises a trick within it or equivocates nothing of the obligation is lifted from him the oath and the perjury both stand he must discharge what he swore to the one to whom it is due and repent thereafter and seek forgiveness there is no expiation for perjury in such a case except that he carry out what he swore for the one entitled to it and then turn in repentance and seek forgiveness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 373, NULL, 'No oath binds over what the swearer does not possess. A man who swears he will free a slave he does not own, or give away something not in his possession, has sworn nothing that holds. There is no oath by divorce, nor by manumission, nor by Hajj, nor by Umrah, nor by anything else among the forms sworn by other than Allah, Blessed and Exalted. The oath is by Allah alone, Mighty and Majestic.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'no oath binds over what the swearer does not possess a man who swears he will free a slave he does not own or give away something not in his possession has sworn nothing that holds there is no oath by divorce nor by manumission nor by hajj nor by umrah nor by anything else among the forms sworn by other than allah blessed and exalted the oath is by allah alone mighty and majestic', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 374, NULL, 'At-Tahrim: 3وَإِذْ أَسَرَّ ٱلنَّبِىُّ إِلَىٰ بَعْضِ أَزْوَجِهِۦ حَدِيثًۭا', '', 'وَإِذْ أَسَرَّ ٱلنَّبِىُّ إِلَىٰ بَعْضِ أَزْوَجِهِۦ حَدِيثًۭا', 'At-Tahrim: 3', 66, 3, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'at tahrim 3واذ اسر النبي الي بعض ازوجه حديثا', 'واذ اسر النبي الي بعض ازوجه حديثا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 375, NULL, 'Abu Jafar Muhammad ibn Ali, the blessings of Allah be upon him, was asked about the words of Allah, Mighty and Majestic:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'abu jafar muhammad ibn ali the blessings of allah be upon him was asked about the words of allah mighty and majestic', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 376, NULL, 'Sayingوَإِذْ أَسَرَّ ٱلنَّبِىُّ إِلَىٰ بَعْضِ أَزْوَجِهِۦ حَدِيثًۭا', '', 'وَإِذْ أَسَرَّ ٱلنَّبِىُّ إِلَىٰ بَعْضِ أَزْوَجِهِۦ حَدِيثًۭا', 'Saying', 66, 3, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'sayingواذ اسر النبي الي بعض ازوجه حديثا', 'واذ اسر النبي الي بعض ازوجه حديثا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 377, NULL, '"And when the Prophet confided to one of his wives a certain matter" (Al-Tahrim 3), to the end of the verse.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'and when the prophet confided to one of his wives a certain matter al tahrim 3 to the end of the verse', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 378, NULL, 'The Master said that the Messenger of Allah had been alone with his bondwoman Mariyah the Copt at the very beginning of her arrival, before he had yet settled her in a house, when Aishah came upon him. She questioned him about it, and he, wishing to please her, swore that he would not return to Mariyah, forbade her to himself, and charged his wife to keep the matter secret. She did not keep it secret, but told it to Hafsah, and the two of them joined together against him. So Allah, Mighty and Majestic, sent down:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'the master said that the messenger of allah had been alone with his bondwoman mariyah the copt at the very beginning of her arrival before he had yet settled her in a house when aishah came upon him she questioned him about it and he wishing to please her swore that he would not return to mariyah forbade her to himself and charged his wife to keep the matter secret she did not keep it secret but told it to hafsah and the two of them joined together against him so allah mighty and majestic sent down', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 379, NULL, '"O Prophet, why do you forbid yourself what Allah has made lawful for you?" (Al-Tahrim 1)', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'o prophet why do you forbid yourself what allah has made lawful for you al tahrim 1', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 380, NULL, 'and commanded him to expiate the oath he had sworn (Al-Tahrim 5).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'and commanded him to expiate the oath he had sworn al tahrim 5', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 381, NULL, 'Allah did not make anything binding upon him through his act of forbidding to himself what was lawful; He rebuked him for it. Therefore, whoever forbids to himself what Allah, Mighty and Majestic, has made lawful for him, that thing is not thereby forbidden to him. It remains lawful for him, he may partake of it, and nothing is upon him. If he has also sworn an oath, he expiates that oath and partakes of what Allah, Mighty and Majestic, has made lawful for him. The Messenger of Allah said: "Whoever swears an oath upon a matter and then sees that what is contrary to what he swore is better for him, let him do that which is better and expiate his oath."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'allah did not make anything binding upon him through his act of forbidding to himself what was lawful he rebuked him for it therefore whoever forbids to himself what allah mighty and majestic has made lawful for him that thing is not thereby forbidden to him it remains lawful for him he may partake of it and nothing is upon him if he has also sworn an oath he expiates that oath and partakes of what allah mighty and majestic has made lawful for him the messenger of allah said whoever swears an oath upon a matter and then sees that what is contrary to what he swore is better for him let him do that which is better and expiate his oath', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 382, NULL, 'Abu Jafar Muhammad ibn Ali, the blessings of Allah be upon him, said that every oath sworn in disobedience counts for nothing — there is neither perjury nor expiation in it. Whoever swears that he will not do what is obligatory upon him, or that he will do what is permitted to him, and then refrains from what is forbidden and does what is obligatory, incurs neither perjury nor expiation. Whoever swears, in an act of obedience, that he will perform it, must fulfil what he swore; and if he does not, he expiates his oath.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'abu jafar muhammad ibn ali the blessings of allah be upon him said that every oath sworn in disobedience counts for nothing there is neither perjury nor expiation in it whoever swears that he will not do what is obligatory upon him or that he will do what is permitted to him and then refrains from what is forbidden and does what is obligatory incurs neither perjury nor expiation whoever swears in an act of obedience that he will perform it must fulfil what he swore and if he does not he expiates his oath', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 383, NULL, 'On Vows', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'on vows', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the marketplace: honest earning, trade, and property', '1. The Marketplace: Honest Earning, Trade, and Property', 384, NULL, 'Allah, Mighty and Majestic, said: "Indeed the righteous will drink from a cup whose mixture is camphor" (Al-Insan 5), up to His words, Mighty and Majestic: "They fulfill their vows and fear a Day whose evil is widespread" (Al-Insan 7). The Messenger of Allah forbade the vow made to other than Allah, Blessed and Exalted, and equally forbade any vow made in disobedience or in the severing of kinship.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 1 the marketplace honest earning trade and property', 'allah mighty and majestic said indeed the righteous will drink from a cup whose mixture is camphor al insan 5 up to his words mighty and majestic they fulfill their vows and fear a day whose evil is widespread al insan 7 the messenger of allah forbade the vow made to other than allah blessed and exalted and equally forbade any vow made in disobedience or in the severing of kinship', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'binding words: oaths, vows, and their atonement', '2. Binding Words: Oaths, Vows, and Their Atonement', 0, NULL, 'Jafar ibn Muhammad (ع) gave the example of a man who vows that, if he is able, he will drink until intoxicated, commit adultery, steal, or kill. Such acts are already forbidden to him. Even if he binds himself to them by a vow, an oath, or any other means, he must not carry them out — and no guilt of perjury or oath-obligation falls upon him for leaving them undone. He must not make a vow that involves the severing of kinship ties.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 2 binding words oaths vows and their atonement', 'jafar ibn muhammad ع gave the example of a man who vows that if he is able he will drink until intoxicated commit adultery steal or kill such acts are already forbidden to him even if he binds himself to them by a vow an oath or any other means he must not carry them out and no guilt of perjury or oath obligation falls upon him for leaving them undone he must not make a vow that involves the severing of kinship ties', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'binding words: oaths, vows, and their atonement', '2. Binding Words: Oaths, Vows, and Their Atonement', 1, NULL, 'If a man says, "If Allah heals my illness, or returns the one who is absent, or grants me wealth or a child, then I owe such and such a vow" — and names that vow — he is bound to fulfill it once Allah, Mighty and Majestic, has granted what he longed for, since he laid that vow upon himself in the matter. If, however, he does not name the vow, saying only, "If such a thing comes to pass, I owe a vow to Allah," without specifying what it is, then nothing is required of him. Should he then vow some particular thing, that vow suffices and stands as a voluntary act, not an obligation. If he makes his vow equal in measure to the expiation of an oath, that is good and seemly.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 2 binding words oaths vows and their atonement', 'if a man says if allah heals my illness or returns the one who is absent or grants me wealth or a child then i owe such and such a vow and names that vow he is bound to fulfill it once allah mighty and majestic has granted what he longed for since he laid that vow upon himself in the matter if however he does not name the vow saying only if such a thing comes to pass i owe a vow to allah without specifying what it is then nothing is required of him should he then vow some particular thing that vow suffices and stands as a voluntary act not an obligation if he makes his vow equal in measure to the expiation of an oath that is good and seemly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'binding words: oaths, vows, and their atonement', '2. Binding Words: Oaths, Vows, and Their Atonement', 3, NULL, 'Al-Ma''idah: 89لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغْوِ فِىٓ أَيْمَنِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلْأَيْمَنَ ۖ فَكَفَّرَتُهُۥٓ إِطْعَامُ عَشَرَةِ مَسَكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍۢ', '', 'لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغْوِ فِىٓ أَيْمَنِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلْأَيْمَنَ ۖ فَكَفَّرَتُهُۥٓ إِطْعَامُ عَشَرَةِ مَسَكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍۢ', 'Al-Ma''idah: 89', 5, 89, 'mukhtasar ul asaar 2 2 binding words oaths vows and their atonement', 'al maidah 89لا يواخذكم الله باللغو في ايمنكم ولكن يواخذكم بما عقدتم الايمن فكفرته اطعام عشره مسكين من اوسط ما تطعمون اهليكم او كسوتهم او تحرير رقبه', 'لا يواخذكم الله باللغو في ايمنكم ولكن يواخذكم بما عقدتم الايمن فكفرته اطعام عشره مسكين من اوسط ما تطعمون اهليكم او كسوتهم او تحرير رقبه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'binding words: oaths, vows, and their atonement', '2. Binding Words: Oaths, Vows, and Their Atonement', 4, NULL, 'Allah, Mighty and Majestic, has said: "Allah will not take you to task for the thoughtless word in your oaths, but He will take you to task for the oaths you have deliberately sworn. Its expiation is the feeding of ten poor persons from the average of that with which you feed your own families, or the clothing of them, or the freeing of a slave. Whoever does not find the means, then a fast of three days. That is the expiation of your oaths when you have sworn. And guard your oaths. Thus does Allah make clear to you His signs, that you may be grateful" (al-Maidah: 89).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 2 binding words oaths vows and their atonement', 'allah mighty and majestic has said allah will not take you to task for the thoughtless word in your oaths but he will take you to task for the oaths you have deliberately sworn its expiation is the feeding of ten poor persons from the average of that with which you feed your own families or the clothing of them or the freeing of a slave whoever does not find the means then a fast of three days that is the expiation of your oaths when you have sworn and guard your oaths thus does allah make clear to you his signs that you may be grateful al maidah 89', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'binding words: oaths, vows, and their atonement', '2. Binding Words: Oaths, Vows, and Their Atonement', 5, NULL, 'Whoever swears by Allah and then breaks that oath — with a breach that makes expiation obligatory — owes the expiation set out above. If he is able, he may feed ten poor persons, or clothe them, or free a slave; the choice among these three is his to make freely.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 2 binding words oaths vows and their atonement', 'whoever swears by allah and then breaks that oath with a breach that makes expiation obligatory owes the expiation set out above if he is able he may feed ten poor persons or clothe them or free a slave the choice among these three is his to make freely', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'binding words: oaths, vows, and their atonement', '2. Binding Words: Oaths, Vows, and Their Atonement', 6, NULL, 'If the one who broke his oath can find no means to feed ten poor persons, and has neither the means to free a slave — of small or great worth — nor the means to clothe ten poor persons, he must then fast three days. Fasting does not stand in place of the other forms of expiation until none of what has been named — neither food, nor clothing, nor manumission — is available to him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 2 binding words oaths vows and their atonement', 'if the one who broke his oath can find no means to feed ten poor persons and has neither the means to free a slave of small or great worth nor the means to clothe ten poor persons he must then fast three days fasting does not stand in place of the other forms of expiation until none of what has been named neither food nor clothing nor manumission is available to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'binding words: oaths, vows, and their atonement', '2. Binding Words: Oaths, Vows, and Their Atonement', 7, NULL, 'This principle extends beyond the oath. Wherever the Quran states an obligation with "or," offering a choice among options, the one upon whom the obligation rests may take any of those options freely. But wherever the Quran says "if he does not find" or "if he is not able," the first option must be pursued whenever it can be found and carried out; the second does not suffice until the first is genuinely beyond both finding and performing. So said Jafar ibn Muhammad, عليه السلام.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 2 binding words oaths vows and their atonement', 'this principle extends beyond the oath wherever the quran states an obligation with or offering a choice among options the one upon whom the obligation rests may take any of those options freely but wherever the quran says if he does not find or if he is not able the first option must be pursued whenever it can be found and carried out the second does not suffice until the first is genuinely beyond both finding and performing so said jafar ibn muhammad عليه السلام', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'binding words: oaths, vows, and their atonement', '2. Binding Words: Oaths, Vows, and Their Atonement', 8, NULL, 'Al-Ma''idah: 89لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغْوِ فِىٓ أَيْمَنِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلْأَيْمَنَ ۖ فَكَفَّرَتُهُۥٓ إِطْعَامُ عَشَرَةِ مَسَكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍۢ', '', 'لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغْوِ فِىٓ أَيْمَنِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلْأَيْمَنَ ۖ فَكَفَّرَتُهُۥٓ إِطْعَامُ عَشَرَةِ مَسَكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍۢ', 'Al-Ma''idah: 89', 5, 89, 'mukhtasar ul asaar 2 2 binding words oaths vows and their atonement', 'al maidah 89لا يواخذكم الله باللغو في ايمنكم ولكن يواخذكم بما عقدتم الايمن فكفرته اطعام عشره مسكين من اوسط ما تطعمون اهليكم او كسوتهم او تحرير رقبه', 'لا يواخذكم الله باللغو في ايمنكم ولكن يواخذكم بما عقدتم الايمن فكفرته اطعام عشره مسكين من اوسط ما تطعمون اهليكم او كسوتهم او تحرير رقبه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'binding words: oaths, vows, and their atonement', '2. Binding Words: Oaths, Vows, and Their Atonement', 9, NULL, 'The feeding required by oath expiation is not discharged by a single day''s provision to the poor. The minimum is a mudd of food, together with whatever accompanies it. The idam — the middle grade of seasoning — is vinegar and oil; meat constitutes the highest grade; salt alone is the lowest, and it does not suffice. This rests on the word of Allah, Mighty and Majestic: "from the average of that with which you feed your families" (al-Maidah: 89). The average here is the most balanced measure: whatever the one making expiation ordinarily feeds his household — in the usual run of his circumstances — is what he ought to provide in expiation of his oath. To feed them better than that is the more excellent course.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 2 binding words oaths vows and their atonement', 'the feeding required by oath expiation is not discharged by a single days provision to the poor the minimum is a mudd of food together with whatever accompanies it the idam the middle grade of seasoning is vinegar and oil meat constitutes the highest grade salt alone is the lowest and it does not suffice this rests on the word of allah mighty and majestic from the average of that with which you feed your families al maidah 89 the average here is the most balanced measure whatever the one making expiation ordinarily feeds his household in the usual run of his circumstances is what he ought to provide in expiation of his oath to feed them better than that is the more excellent course', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'binding words: oaths, vows, and their atonement', '2. Binding Words: Oaths, Vows, and Their Atonement', 10, NULL, 'As for the clothing in oath expiation, each poor person is to receive two garments.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 2 binding words oaths vows and their atonement', 'as for the clothing in oath expiation each poor person is to receive two garments', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'binding words: oaths, vows, and their atonement', '2. Binding Words: Oaths, Vows, and Their Atonement', 11, NULL, 'Regarding the freeing of a slave as oath expiation, a slave born into bondage suffices. A mudabbar — one whose release has been tied to his master''s death — may not be freed for this purpose unless the master first revokes that arrangement, the tadbir, returns him to the full condition of a slave, and then frees him. The fast in oath expiation is three consecutive days.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 2 binding words oaths vows and their atonement', 'regarding the freeing of a slave as oath expiation a slave born into bondage suffices a mudabbar one whose release has been tied to his masters death may not be freed for this purpose unless the master first revokes that arrangement the tadbir returns him to the full condition of a slave and then frees him the fast in oath expiation is three consecutive days', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'binding words: oaths, vows, and their atonement', '2. Binding Words: Oaths, Vows, and Their Atonement', 12, NULL, 'The feeding and clothing of the people of allegiance from oath expiation is an obligation on those commanded to perform it. If such persons cannot be found, those among the weak who bear no enmity are entitled to receive it. Nothing from expiation, nor from charity, nor from anything of that kind, may be given to a Nasib — one known for his hostility toward the family of Muhammad (ع) — even if no one else can be found.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 2 binding words oaths vows and their atonement', 'the feeding and clothing of the people of allegiance from oath expiation is an obligation on those commanded to perform it if such persons cannot be found those among the weak who bear no enmity are entitled to receive it nothing from expiation nor from charity nor from anything of that kind may be given to a nasib one known for his hostility toward the family of muhammad ع even if no one else can be found', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'binding words: oaths, vows, and their atonement', '2. Binding Words: Oaths, Vows, and Their Atonement', 13, NULL, 'When a person lays a vow upon himself regarding some matter, conditional on its coming to pass, and that matter had already occurred before he bound himself — without his knowledge — nothing is required of him. A man put a case of this kind to Abu Jafar Muhammad ibn Ali. He said: "I have a slave girl by whom I am loath to have a child. Her menses ceased to come at the expected time, and I feared she had conceived, so I bound myself before Allah to free a slave, to fast, and to give charity if she should menstruate. She did menstruate — but before I had made that vow, and I did not know it."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 2 binding words oaths vows and their atonement', 'when a person lays a vow upon himself regarding some matter conditional on its coming to pass and that matter had already occurred before he bound himself without his knowledge nothing is required of him a man put a case of this kind to abu jafar muhammad ibn ali he said i have a slave girl by whom i am loath to have a child her menses ceased to come at the expected time and i feared she had conceived so i bound myself before allah to free a slave to fast and to give charity if she should menstruate she did menstruate but before i had made that vow and i did not know it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'binding words: oaths, vows, and their atonement', '2. Binding Words: Oaths, Vows, and Their Atonement', 14, NULL, 'Abu Jafar said: "Nothing is required of you."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 2 binding words oaths vows and their atonement', 'abu jafar said nothing is required of you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'binding words: oaths, vows, and their atonement', '2. Binding Words: Oaths, Vows, and Their Atonement', 15, NULL, 'Abu Jafar Muhammad ibn Ali held that:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 2 binding words oaths vows and their atonement', 'abu jafar muhammad ibn ali held that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'binding words: oaths, vows, and their atonement', '2. Binding Words: Oaths, Vows, and Their Atonement', 16, NULL, 'If a man swears he will not give another man dinars, and then gives him goods in their place, he has not broken his oath. If a man swears he will not sell his wares at a named price, and then sells them for goods worth that same price, he has not broken his oath. If a man is owed dinars and swears he will not receive them except in full, and is then paid part in coin and part in goods of equal value, he has not broken his oath.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 2 binding words oaths vows and their atonement', 'if a man swears he will not give another man dinars and then gives him goods in their place he has not broken his oath if a man swears he will not sell his wares at a named price and then sells them for goods worth that same price he has not broken his oath if a man is owed dinars and swears he will not receive them except in full and is then paid part in coin and part in goods of equal value he has not broken his oath', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'binding words: oaths, vows, and their atonement', '2. Binding Words: Oaths, Vows, and Their Atonement', 17, NULL, 'He (ع) was asked about a man who swears to slaughter his son. He said: "There is nothing upon him in that, and it is among the steps of Satan."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 2 binding words oaths vows and their atonement', 'he ع was asked about a man who swears to slaughter his son he said there is nothing upon him in that and it is among the steps of satan', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'binding words: oaths, vows, and their atonement', '2. Binding Words: Oaths, Vows, and Their Atonement', 18, NULL, 'He also said that expiation falls due after the oath is broken.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 2 binding words oaths vows and their atonement', 'he also said that expiation falls due after the oath is broken', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 0, NULL, 'The law draws a clear line between what may be eaten from a slaughtered animal and what must be left aside. Among the parts that are forbidden are the male glands, the penis, the female organ, and the inner flesh of the kidneys.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'the law draws a clear line between what may be eaten from a slaughtered animal and what must be left aside among the parts that are forbidden are the male glands the penis the female organ and the inner flesh of the kidneys', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 1, NULL, 'It is narrated from him (ع) that he said: "Nothing of the creatures of the sea is to be eaten except what is caught alive and has scales. As for what dies in the water before it is taken, or what has no scales, eating it is forbidden."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it is narrated from him ع that he said nothing of the creatures of the sea is to be eaten except what is caught alive and has scales as for what dies in the water before it is taken or what has no scales eating it is forbidden', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 2, NULL, 'He forbade eating cheese made by Magians and polytheists when rennet (al-anfaha) drawn from carrion — or from an animal over which the name of Allah was not pronounced — had been introduced into it. If the origin of the cheese is unknown, however, and there is no evidence that any such substance is present, then eating it is permitted when it is sold in the market of the Muslims, just as one may eat the slaughtered meat sold there.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'he forbade eating cheese made by magians and polytheists when rennet al anfaha drawn from carrion or from an animal over which the name of allah was not pronounced had been introduced into it if the origin of the cheese is unknown however and there is no evidence that any such substance is present then eating it is permitted when it is sold in the market of the muslims just as one may eat the slaughtered meat sold there', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 3, NULL, 'Everything otherwise forbidden to eat becomes permissible for one in dire necessity, when no other food can be found and life is at risk. The one compelled by need may eat of it until satisfied, if he so wishes.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'everything otherwise forbidden to eat becomes permissible for one in dire necessity when no other food can be found and life is at risk the one compelled by need may eat of it until satisfied if he so wishes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 4, NULL, 'Everything that nourishes — grains, green herbs, the produce of the earth, and all fruits that neither harm nor kill — is lawful to eat. The flesh of camels, cattle, sheep, and wild animals, together with their milk, is likewise lawful, with one exception: beasts of prey that possess fangs and seize and devour other animals. Nothing of such creatures is lawful to eat. All birds are lawful when properly slaughtered, except birds of prey that possess talons and seize and devour other birds; eating them is not lawful, nor is eating their eggs.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'everything that nourishes grains green herbs the produce of the earth and all fruits that neither harm nor kill is lawful to eat the flesh of camels cattle sheep and wild animals together with their milk is likewise lawful with one exception beasts of prey that possess fangs and seize and devour other animals nothing of such creatures is lawful to eat all birds are lawful when properly slaughtered except birds of prey that possess talons and seize and devour other birds eating them is not lawful nor is eating their eggs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 5, NULL, 'When an egg is found and its origin is unknown, it is examined. If its two ends differ — one pointed, one rounded — it may be eaten, for it belongs to a creature whose flesh is lawful. If its two ends are alike, it is not eaten, for it belongs to a creature whose flesh is not lawful.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'when an egg is found and its origin is unknown it is examined if its two ends differ one pointed one rounded it may be eaten for it belongs to a creature whose flesh is lawful if its two ends are alike it is not eaten for it belongs to a creature whose flesh is not lawful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 6, NULL, 'The Messenger of Allah ﷺ permitted the eating of rabbit, but disliked the lizard (al-dabb), the hedgehog, and the other creeping things of the earth.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'the messenger of allah ﷺ permitted the eating of rabbit but disliked the lizard al dabb the hedgehog and the other creeping things of the earth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 7, NULL, 'From Jafar ibn Muhammad (ع) it is narrated that he permitted the use of vessels that had been touched by impurity or wine, provided they were first washed and cleaned. Concerning food in which small creatures of the earth, flies, or other bloodless things happened to die, he held that this neither forbids the food nor renders it impure. Whoever is repelled by it may leave it; whoever wishes may eat. If, however, a creature possessing blood dies in the food, the ruling differs: if the food is liquid, it is entirely spoiled; if it is solid, only what immediately surrounds the dead creature is spoiled. Once that portion has been removed and discarded, the rest may be eaten freely, and there is no harm in it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'from jafar ibn muhammad ع it is narrated that he permitted the use of vessels that had been touched by impurity or wine provided they were first washed and cleaned concerning food in which small creatures of the earth flies or other bloodless things happened to die he held that this neither forbids the food nor renders it impure whoever is repelled by it may leave it whoever wishes may eat if however a creature possessing blood dies in the food the ruling differs if the food is liquid it is entirely spoiled if it is solid only what immediately surrounds the dead creature is spoiled once that portion has been removed and discarded the rest may be eaten freely and there is no harm in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 8, NULL, 'On the Etiquette of Drinking', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'on the etiquette of drinking', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 9, NULL, 'It is narrated from the Messenger of Allah ﷺ that he forbade drinking in a single continuous draft. Instead, he commanded that one drink in sips, that the drinker name Allah at the first sip and praise Him when finished, and that he not breathe into the vessel. One says "Bismillah" when beginning and "Alhamdulillah" when pausing.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it is narrated from the messenger of allah ﷺ that he forbade drinking in a single continuous draft instead he commanded that one drink in sips that the drinker name allah at the first sip and praise him when finished and that he not breathe into the vessel one says bismillah when beginning and alhamdulillah when pausing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 10, NULL, 'Ali (ع) said: "I observed the Messenger of Allah ﷺ drinking water more than once. He would breathe three times during the drink, taking the vessel away from his mouth at each breath, saying Bismillah when he began and Alhamdulillah when he paused."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'ali ع said i observed the messenger of allah ﷺ drinking water more than once he would breathe three times during the drink taking the vessel away from his mouth at each breath saying bismillah when he began and alhamdulillah when he paused', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 11, NULL, 'Abu Jafar Muhammad ibn Ali (ع) said: "Three breaths in a drink are better than one."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'abu jafar muhammad ibn ali ع said three breaths in a drink are better than one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 12, NULL, 'He forbade drinking from the mouth of a waterskin — that is, bending its opening back and drinking directly from it — on the grounds that doing so fouls the skin and risks a creature lurking unseen in the water slipping down the drinker''s throat.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'he forbade drinking from the mouth of a waterskin that is bending its opening back and drinking directly from it on the grounds that doing so fouls the skin and risks a creature lurking unseen in the water slipping down the drinkers throat', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 13, NULL, 'The Messenger of Allah ﷺ himself drank both standing and sitting, yet he forbade lapping water directly from a river, a basin, a pond, or anything of that kind. Seeing a man do so, he said to him: "You lap as a beast laps. If you find no vessel, drink from your hand, for it is the best of your vessels."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'the messenger of allah ﷺ himself drank both standing and sitting yet he forbade lapping water directly from a river a basin a pond or anything of that kind seeing a man do so he said to him you lap as a beast laps if you find no vessel drink from your hand for it is the best of your vessels', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 14, NULL, 'He also forbade gulping water down, saying: "Suck the water as it is sucked, and do not gulp it down as a burden upon yourself, for that brings on disease of the liver (al-kubad)." Milk, however, he would gulp. Ali ibn al-Husayn (ع) was once observed gulping milk, and when he was asked, "Will you not take it in sips?" he replied: "Only the people of the Fire take it in sips." When he drank milk he would say: "O Allah, bless us in it and increase us from it." When he drank water he would say: "Praise be to Allah, who has given us fresh, sweet water by His mercy, and has not given us bitter, briny water on account of our sins."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'he also forbade gulping water down saying suck the water as it is sucked and do not gulp it down as a burden upon yourself for that brings on disease of the liver al kubad milk however he would gulp ali ibn al husayn ع was once observed gulping milk and when he was asked will you not take it in sips he replied only the people of the fire take it in sips when he drank milk he would say o allah bless us in it and increase us from it when he drank water he would say praise be to allah who has given us fresh sweet water by his mercy and has not given us bitter briny water on account of our sins', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 15, NULL, 'It is narrated from Jafar ibn Muhammad that he forbade drinking, or performing ablution, from the side of the handle (urwa) of the vessel.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it is narrated from jafar ibn muhammad that he forbade drinking or performing ablution from the side of the handle urwa of the vessel', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 16, NULL, 'On What Is Permissible to Drink', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'on what is permissible to drink', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 17, NULL, 'The Messenger of Allah ﷺ is reported to have said: "Water is the master of drinks in this world and the Hereafter." Any naturally occurring water, in which no human labor plays any part, is lawful to drink, so long as it has not been mixed with impurity and is neither harmful nor injurious. It is likewise permissible to drink the milk of every animal whose flesh is lawful to eat.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'the messenger of allah ﷺ is reported to have said water is the master of drinks in this world and the hereafter any naturally occurring water in which no human labor plays any part is lawful to drink so long as it has not been mixed with impurity and is neither harmful nor injurious it is likewise permissible to drink the milk of every animal whose flesh is lawful to eat', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 18, NULL, 'The Messenger of Allah ﷺ said of camel''s milk: "It draws from every tree." He also said: "Cow''s ghee is a cure, and its milk is medicine." A prophet once complained of a weakness in his body, and Allah, Blessed and Exalted, revealed to him: "The finest meat is that taken with milk; eat them both, for I have placed strength in both of them." It is likewise said: "Meat and milk are the broth of the prophets."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'the messenger of allah ﷺ said of camels milk it draws from every tree he also said cows ghee is a cure and its milk is medicine a prophet once complained of a weakness in his body and allah blessed and exalted revealed to him the finest meat is that taken with milk eat them both for i have placed strength in both of them it is likewise said meat and milk are the broth of the prophets', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 19, NULL, 'He said: "Honey is a healing." Ali said: "No sick person was ever healed by the like of honey." And he said: "Can any of you not, when he falls ill, ask his wife to give him a dirham or two from her dowry, and buy honey with it, and drink it dissolved in rainwater?"', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'he said honey is a healing ali said no sick person was ever healed by the like of honey and he said can any of you not when he falls ill ask his wife to give him a dirham or two from her dowry and buy honey with it and drink it dissolved in rainwater', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 20, NULL, 'Qaf: 9وَنَزَّلْنَا مِنَ ٱلسَّمَآءِ مَآءًۭ مُّبَرَكًۭا', '', 'وَنَزَّلْنَا مِنَ ٱلسَّمَآءِ مَآءًۭ مُّبَرَكًۭا', 'Qaf: 9', 50, 9, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'qaf 9ونزلنا من السماء ماء مبركا', 'ونزلنا من السماء ماء مبركا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 21, NULL, 'Allah, Blessed and Exalted, says regarding the dowry: ﴿فَإِنْ طِبْنَ لَكُمْ عَنْ شَيْءٍ مِنْهُ نَفْسًا فَكُلُوهُ هَنِيئًا مَرِيئًا﴾, "If they willingly give up to you any part of it, then consume it in satisfaction and ease" (al-Nisa: 4). Regarding honey, He says: ﴿فِيهِ شِفَاءٌ لِلنَّاسِ﴾, "In it is healing for people" (al-Nahl: 69). And regarding rainwater, He says: ﴿وَنَزَّلْنَا مِنَ السَّمَاءِ مَاءً مُبَارَكًا﴾, "And We sent down from the sky blessed water" (Qaf: 9).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'allah blessed and exalted says regarding the dowry فان طبن لكم عن شيء منه نفسا فكلوه هنييا مرييا if they willingly give up to you any part of it then consume it in satisfaction and ease al nisa 4 regarding honey he says فيه شفاء للناس in it is healing for people al nahl 69 and regarding rainwater he says ونزلنا من السماء ماء مباركا and we sent down from the sky blessed water qaf 9', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 22, NULL, 'Water mixed with honey, milk, or anything similar is lawful to drink, as are drinks made from dates, raisins, or other sweeteners, provided they have not fermented. The same applies to everything pressed from grape juice, dates, raisins, or lawful fruits and herbs: such juice is lawful to drink as long as it has not turned, whether taken pure or mixed with water, and buying, selling, and benefiting from it are equally lawful. Grape juice cooked until it thickens, without turning, is likewise lawful to drink — pure or mixed with water — for as long as it remains unchanged.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'water mixed with honey milk or anything similar is lawful to drink as are drinks made from dates raisins or other sweeteners provided they have not fermented the same applies to everything pressed from grape juice dates raisins or lawful fruits and herbs such juice is lawful to drink as long as it has not turned whether taken pure or mixed with water and buying selling and benefiting from it are equally lawful grape juice cooked until it thickens without turning is likewise lawful to drink pure or mixed with water for as long as it remains unchanged', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 23, NULL, 'It has been narrated of Ali that he used to supply the people with al-tila: grape juice boiled until it gains body, so that if left to stand it does not ferment but sets instead like honey. That preparation, and anything like it, is lawful to drink, pure or mixed with water, so long as it does not change.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it has been narrated of ali that he used to supply the people with al tila grape juice boiled until it gains body so that if left to stand it does not ferment but sets instead like honey that preparation and anything like it is lawful to drink pure or mixed with water so long as it does not change', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 24, NULL, 'Abu Jafar Muhammad ibn Ali was asked about drinking pressed juice. He said: "There is no harm in it. Drink from a clean vessel that has not been seasoned with wine, and drink it as long as a large quantity does not intoxicate. But if a large quantity intoxicates, then a small quantity of it is forbidden. Do not drink what has stood a long while, for after an hour, or after a night, the pleasure of wine departs and only its sin remains. So fear Allah and call yourselves to account."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'abu jafar muhammad ibn ali was asked about drinking pressed juice he said there is no harm in it drink from a clean vessel that has not been seasoned with wine and drink it as long as a large quantity does not intoxicate but if a large quantity intoxicates then a small quantity of it is forbidden do not drink what has stood a long while for after an hour or after a night the pleasure of wine departs and only its sin remains so fear allah and call yourselves to account', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 25, NULL, 'The Shia of Ali were known by recognizable marks:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'the shia of ali were known by recognizable marks', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 26, NULL, 'piety diligence restraint the shunning of sins great and small love for the friends of Allah, the Mighty and Majestic', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'piety diligence restraint the shunning of sins great and small love for the friends of allah the mighty and majestic', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 27, NULL, 'It has been narrated from Ali that he said: "We used to soak raisins or dates in water in a clean vessel for the Messenger of Allah ﷺ. He would drink it that day and the next; and if it had changed by the third day, he ordered it poured away." This is the lawful drink called nabidh — named for what is cast, that is, thrown, into the water: dates, raisins, or the like, which sweeten it when the water is brackish. But if it is left to ferment, so that it boils, intensifies, and throws up froth, then it is wine, and a large quantity of it is forbidden once it intoxicates.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it has been narrated from ali that he said we used to soak raisins or dates in water in a clean vessel for the messenger of allah ﷺ he would drink it that day and the next and if it had changed by the third day he ordered it poured away this is the lawful drink called nabidh named for what is cast that is thrown into the water dates raisins or the like which sweeten it when the water is brackish but if it is left to ferment so that it boils intensifies and throws up froth then it is wine and a large quantity of it is forbidden once it intoxicates', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 28, NULL, 'On What Is Forbidden to Drink', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'on what is forbidden to drink', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 29, NULL, 'Al-Baqarah: 104يَٓأَيُّهَا ٱلَّذِينَ آمَنُوٓا۟', '', 'يَٓأَيُّهَا ٱلَّذِينَ آمَنُوٓا۟', 'Al-Baqarah: 104', 2, 104, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'al baqarah 104يايها الذين امنوا', 'يايها الذين امنوا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 30, NULL, 'Allah, the Mighty and Majestic, said: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالْأَنْصَابُ وَالْأَزْلَامُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ﴾, "O you who believe, intoxicants, gambling, stone altars, and divining arrows are but an abomination of Satan''s handiwork, so avoid it, that you may be successful" (al-Maidah: 90). By this He forbade wine, just as He forbade all things unlawful.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'allah the mighty and majestic said يا ايها الذين امنوا انما الخمر والميسر والانصاب والازلام رجس من عمل الشيطان فاجتنبوه لعلكم تفلحون o you who believe intoxicants gambling stone altars and divining arrows are but an abomination of satans handiwork so avoid it that you may be successful al maidah 90 by this he forbade wine just as he forbade all things unlawful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 31, NULL, 'The Messenger of Allah ﷺ is reported to have said: "Wine is forbidden; no one drinks it in this world and then drinks it in the Hereafter, in the sacred enclosure of holiness (hazirat al-quds)." He also said: "Allah has cursed wine: its presser, the one who has it pressed, its seller, its buyer, its drinker, the one who serves it, the one who consumes its price, the one who carries it, and the one to whom it is carried." And he said: "That which intoxicates in large quantity is forbidden even in a small quantity." He forbade treating illness with wine and intoxicants, and forbade giving them to children or animals, declaring that the sin falls upon whoever does so.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'the messenger of allah ﷺ is reported to have said wine is forbidden no one drinks it in this world and then drinks it in the hereafter in the sacred enclosure of holiness hazirat al quds he also said allah has cursed wine its presser the one who has it pressed its seller its buyer its drinker the one who serves it the one who consumes its price the one who carries it and the one to whom it is carried and he said that which intoxicates in large quantity is forbidden even in a small quantity he forbade treating illness with wine and intoxicants and forbade giving them to children or animals declaring that the sin falls upon whoever does so', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 32, NULL, 'It is narrated from Ali ibn al-Husayn that he said: "Intoxicating drink comes from five things: dates, raisins, wheat, barley, and honey — that is, besides grapes." From Muhammad ibn Ali, upon his forefathers be peace, it is narrated: "The one addicted to wine will meet Allah, the Mighty and Majestic, on the day he meets Him as one who worships an idol; and whoever drinks a single draft of it, Allah, Blessed and Exalted, will not accept a prayer from him for forty nights."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it is narrated from ali ibn al husayn that he said intoxicating drink comes from five things dates raisins wheat barley and honey that is besides grapes from muhammad ibn ali upon his forefathers be peace it is narrated the one addicted to wine will meet allah the mighty and majestic on the day he meets him as one who worships an idol and whoever drinks a single draft of it allah blessed and exalted will not accept a prayer from him for forty nights', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 33, NULL, 'From Jafar ibn Muhammad it is narrated: "Paradise is forbidden to three: the one addicted to wine, the worshipper of idols, and the enemy of the family of Muhammad." From Ali it is narrated: "Whoever drinks wine and dies within forty days of having drunk it meets Allah, Blessed and Exalted, as one who worships an idol." He also said: "The Messenger of Allah ﷺ forbade every intoxicant from every drink, and whatever the Messenger of Allah has forbidden, Allah, the Mighty and Majestic, has forbidden. Every intoxicant is forbidden, and that which intoxicates in large quantity is forbidden even in a small quantity."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'from jafar ibn muhammad it is narrated paradise is forbidden to three the one addicted to wine the worshipper of idols and the enemy of the family of muhammad from ali it is narrated whoever drinks wine and dies within forty days of having drunk it meets allah blessed and exalted as one who worships an idol he also said the messenger of allah ﷺ forbade every intoxicant from every drink and whatever the messenger of allah has forbidden allah the mighty and majestic has forbidden every intoxicant is forbidden and that which intoxicates in large quantity is forbidden even in a small quantity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 34, NULL, 'A man from the people of Kufa said to him: "May Allah set you right — the jurists of our land say that only wine made from grapes is forbidden."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'a man from the people of kufa said to him may allah set you right the jurists of our land say that only wine made from grapes is forbidden', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 35, NULL, 'He replied: "O Sheikh, I do not know what the jurists of your land say. My father narrated to me, from his father, from his grandfather, from Ali ibn Abi Talib, that the Messenger of Allah ﷺ said: that which intoxicates in large quantity is forbidden even in a small quantity."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'he replied o sheikh i do not know what the jurists of your land say my father narrated to me from his father from his grandfather from ali ibn abi talib that the messenger of allah ﷺ said that which intoxicates in large quantity is forbidden even in a small quantity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 36, NULL, 'Jafar ibn Muhammad then said: "Taqiyya is my religion and the religion of my forefathers in everything except three matters:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'jafar ibn muhammad then said taqiyya is my religion and the religion of my forefathers in everything except three matters', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 37, NULL, 'the prohibition of intoxicants the removing of the two leather socks at ablution the saying aloud of Bismillah al-Rahman al-Rahim, meaning that it be recited aloud in the prayer"', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'the prohibition of intoxicants the removing of the two leather socks at ablution the saying aloud of bismillah al rahman al rahim meaning that it be recited aloud in the prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 38, NULL, 'Jafar ibn Muhammad said: "One must not treat illness with wine or intoxicants, nor may women use such things to dress their hair, for my father narrated to me, from his father, from his grandfather, that Ali said: Allah, Blessed and Exalted, has placed no cure in any impurity that He has forbidden."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'jafar ibn muhammad said one must not treat illness with wine or intoxicants nor may women use such things to dress their hair for my father narrated to me from his father from his grandfather that ali said allah blessed and exalted has placed no cure in any impurity that he has forbidden', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 39, NULL, 'He was also asked about drinking al-fuqqa. When the questioner had described its nature, he said: "It is forbidden; do not drink it."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'he was also asked about drinking al fuqqa when the questioner had described its nature he said it is forbidden do not drink it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 40, NULL, 'Concerning seasoned vessels, he said that wine was not forbidden on account of such vessels, but that he had forbidden the intoxicant in small quantity and large alike; he disapproved of seasoned vessels only because they alter the drinks.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'concerning seasoned vessels he said that wine was not forbidden on account of such vessels but that he had forbidden the intoxicant in small quantity and large alike he disapproved of seasoned vessels only because they alter the drinks', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 41, NULL, 'On What Makes Medicine Beneficial', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'on what makes medicine beneficial', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 42, NULL, 'What has come down from the Imams of the Ahl al-Bayt, (عَلَيْهِمُ السَّلَامُ), concerning medicine — the treatments and remedies they permitted and those they forbade — belongs to the domain of the lawful and the unlawful. One who doubts what has come from them may well deny it upon hearing it; and if he applies it without true belief, he will find no benefit in it and will cast it aside. Allah, Blessed and Exalted, brings benefit through it only to those who affirm them and submit to their command, who receive what has come from them with acceptance — not to one who takes it as a mere trial, without belief, without intention, and without conviction.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'what has come down from the imams of the ahl al bayt عليهم السلام concerning medicine the treatments and remedies they permitted and those they forbade belongs to the domain of the lawful and the unlawful one who doubts what has come from them may well deny it upon hearing it and if he applies it without true belief he will find no benefit in it and will cast it aside allah blessed and exalted brings benefit through it only to those who affirm them and submit to their command who receive what has come from them with acceptance not to one who takes it as a mere trial without belief without intention and without conviction', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 43, NULL, 'What confirms this is the report narrated from Jafar ibn Muhammad. Muhammad ibn Khalid, the governor of Medina, was recovering from an illness and, before a gathering of people, complained of a pain in his abdomen. Jafar ibn Muhammad said to him: "Shall I not tell you a hadith my father narrated to me, from his father, from his grandfather, from Ali, from the Messenger of Allah ﷺ?" He said: "Yes." Jafar said: "Abu Muhammad ibn Ali ibn al-Husayn told me, from his father, from his grandfather, that a man complained to the Messenger of Allah ﷺ of a pain he felt in his abdomen. The Messenger of Allah ﷺ said to him: Take a drink of honey and cast into it three grains of black seed (shuniz), or five, or seven, and you will be cured by the leave of Allah. He did so and was cured. So take this yourself."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'what confirms this is the report narrated from jafar ibn muhammad muhammad ibn khalid the governor of medina was recovering from an illness and before a gathering of people complained of a pain in his abdomen jafar ibn muhammad said to him shall i not tell you a hadith my father narrated to me from his father from his grandfather from ali from the messenger of allah ﷺ he said yes jafar said abu muhammad ibn ali ibn al husayn told me from his father from his grandfather that a man complained to the messenger of allah ﷺ of a pain he felt in his abdomen the messenger of allah ﷺ said to him take a drink of honey and cast into it three grains of black seed shuniz or five or seven and you will be cured by the leave of allah he did so and was cured so take this yourself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 44, NULL, 'A man of Medina present in the gathering objected and said: "O Abu Abd Allah, the hadith is sound, and we have heard it, but we tried it and gained no benefit from it."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'a man of medina present in the gathering objected and said o abu abd allah the hadith is sound and we have heard it but we tried it and gained no benefit from it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 45, NULL, 'At that, Abu Abd Allah (ع) grew very angry and said: "Allah brings benefit through this only to those who believe in Him and affirm His Messenger (ع) — the Muslims who submit to his command and receive it from him with acceptance. As for the hypocrites who doubt it and do not affirm him, Allah, Blessed and Exalted, will not benefit them by it. Perhaps you are a hypocrite, and you took it without affirming the Messenger of Allah ﷺ, and so you were denied its benefit."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'at that abu abd allah ع grew very angry and said allah brings benefit through this only to those who believe in him and affirm his messenger ع the muslims who submit to his command and receive it from him with acceptance as for the hypocrites who doubt it and do not affirm him allah blessed and exalted will not benefit them by it perhaps you are a hypocrite and you took it without affirming the messenger of allah ﷺ and so you were denied its benefit', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 46, NULL, 'The man fell silent, overcome with shame, and bowed his head. All who were present in the gathering affirmed the truth of Abu Abd Allah''s words.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'the man fell silent overcome with shame and bowed his head all who were present in the gathering affirmed the truth of abu abd allahs words', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 47, NULL, 'As for those who have used these remedies with sincere intention and certainty, the benefit they have received cannot be reckoned. Whoever turns to anything reported from the Messenger of Allah ﷺ and from the Imams of the family of the Messenger of Allah ﷺ, seeking treatment and cure, ought to approach it with intention, sincerity, and certainty — and it will benefit him, if Allah wills. If doubt has entered his heart, he should not treat himself with such remedies; and if he inclines instead toward the word of the physicians where they have spoken against it, he will gain no benefit from it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'as for those who have used these remedies with sincere intention and certainty the benefit they have received cannot be reckoned whoever turns to anything reported from the messenger of allah ﷺ and from the imams of the family of the messenger of allah ﷺ seeking treatment and cure ought to approach it with intention sincerity and certainty and it will benefit him if allah wills if doubt has entered his heart he should not treat himself with such remedies and if he inclines instead toward the word of the physicians where they have spoken against it he will gain no benefit from it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 48, NULL, 'It is Allah who grants, to those servants whom He is pleased with and chooses for His guardianship, the success of affirming His friends, submitting to their command, and receiving and accepting from them.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it is allah who grants to those servants whom he is pleased with and chooses for his guardianship the success of affirming his friends submitting to their command and receiving and accepting from them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 49, NULL, 'On Seeking Healing Through Acts of Righteousness', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'on seeking healing through acts of righteousness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 50, NULL, 'The Imams of the family of the Messenger of Allah ﷺ narrated that he said: "In the black seed (al-habba al-sawda) is a cure for every disease except al-sam" — that is, death. Abu Jafar Muhammad ibn Ali conveyed this hadith to some of his companions, and it delighted them. They said: "O son of the Messenger of Allah, what an easy remedy this is — one that heals every disease but death!" He said: "Yes. Shall I not tell you of something easier still, one in which the Messenger of Allah ﷺ excluded neither death nor anything else?" They said: "What is it, O son of the Messenger of Allah ﷺ?" He said: "Supplication, for it turns back the decree even after it has been firmly sealed." He then brought all his fingers together, placing the two little fingers side by side, to depict the firm sealing of the decree.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'the imams of the family of the messenger of allah ﷺ narrated that he said in the black seed al habba al sawda is a cure for every disease except al sam that is death abu jafar muhammad ibn ali conveyed this hadith to some of his companions and it delighted them they said o son of the messenger of allah what an easy remedy this is one that heals every disease but death he said yes shall i not tell you of something easier still one in which the messenger of allah ﷺ excluded neither death nor anything else they said what is it o son of the messenger of allah ﷺ he said supplication for it turns back the decree even after it has been firmly sealed he then brought all his fingers together placing the two little fingers side by side to depict the firm sealing of the decree', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 51, NULL, 'It is narrated that the Messenger of Allah ﷺ noticed the absence of a man from among the Ansar. When the man came to him some time later, the Messenger of Allah ﷺ asked: "What has kept you from us?" The man replied: "Sickness and poverty, O Messenger of Allah ﷺ." The Messenger of Allah ﷺ said: "Shall I not teach you words to call upon Allah with, by which Allah, Blessed and Exalted, will lift that from you?" The man said: "Yes, by my father and my mother, O Messenger of Allah ﷺ." The Messenger of Allah ﷺ said: "Say: There is no power and no strength except through Allah; I place my trust in the Living who does not die. Praise be to Allah, who has taken no son, who has no partner in His dominion, and who has no protector from humiliation; and magnify Him greatly."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it is narrated that the messenger of allah ﷺ noticed the absence of a man from among the ansar when the man came to him some time later the messenger of allah ﷺ asked what has kept you from us the man replied sickness and poverty o messenger of allah ﷺ the messenger of allah ﷺ said shall i not teach you words to call upon allah with by which allah blessed and exalted will lift that from you the man said yes by my father and my mother o messenger of allah ﷺ the messenger of allah ﷺ said say there is no power and no strength except through allah i place my trust in the living who does not die praise be to allah who has taken no son who has no partner in his dominion and who has no protector from humiliation and magnify him greatly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 52, NULL, 'It is also narrated from Ali that he said: "I complained to the Messenger of Allah ﷺ of a forgetfulness that had come over me, on account of which much of the Quran was slipping away from me. He said to me: O Ali, I will teach you words that will drive that from you and fix the Quran firmly in your heart. Say: O Allah, have mercy on me through the forsaking of disobedience to You for as long as You keep me alive; have mercy on me by sparing me what does not concern me; grant me good discernment in what pleases You with me; bind my heart to the keeping of Your Book as You taught it to me; and grant that I recite it in the manner that pleases You."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it is also narrated from ali that he said i complained to the messenger of allah ﷺ of a forgetfulness that had come over me on account of which much of the quran was slipping away from me he said to me o ali i will teach you words that will drive that from you and fix the quran firmly in your heart say o allah have mercy on me through the forsaking of disobedience to you for as long as you keep me alive have mercy on me by sparing me what does not concern me grant me good discernment in what pleases you with me bind my heart to the keeping of your book as you taught it to me and grant that i recite it in the manner that pleases you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 53, NULL, 'Among the words he taught for the firm holding of revelation was this: "By Your Book give light to my sight, release my tongue, open my chest with it, employ my body in it, and grant me strength through it, for none can grant strength in it but You." He then said that he prayed with those words, and Allah established the Quran firmly in his chest.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'among the words he taught for the firm holding of revelation was this by your book give light to my sight release my tongue open my chest with it employ my body in it and grant me strength through it for none can grant strength in it but you he then said that he prayed with those words and allah established the quran firmly in his chest', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 54, NULL, 'It was narrated from him that he said: "If one of you sets before him a vessel containing food or drink and fears that something in it may harm him, let him name Allah over it and take from it, for nothing harms alongside the name of Allah."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it was narrated from him that he said if one of you sets before him a vessel containing food or drink and fears that something in it may harm him let him name allah over it and take from it for nothing harms alongside the name of allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 55, NULL, 'It was narrated from Abu Abd-Allah (ع) that a man among his companions complained to him of a corruption he found in his stomach, saying that he could eat no food without it harming and distressing him. He said to him: "Say the name of Allah over every food you eat, and over every variety of it as you eat it, and it will not harm you." The man did so and was cured.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it was narrated from abu abd allah ع that a man among his companions complained to him of a corruption he found in his stomach saying that he could eat no food without it harming and distressing him he said to him say the name of allah over every food you eat and over every variety of it as you eat it and it will not harm you the man did so and was cured', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 56, NULL, 'It was also narrated from him that a man among his companions was struck with a whiteness between his eyes and complained of it, for the affliction had taken hold of him and caused him grief. The Master said to him: Make supplication while you are in prostration. The man said: O son of the Messenger of Allah, teach me the words to pray with. He said: Say: O Allah, O Most Merciful, O Compassionate, O Hearer of prayers, O Giver of good things, grant me the good of the Hereafter and of this world, turn away from me the evil of them both, and remove from me this affliction that is between my eyes, for it has grieved and saddened me. The man did so and was healed.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it was also narrated from him that a man among his companions was struck with a whiteness between his eyes and complained of it for the affliction had taken hold of him and caused him grief the master said to him make supplication while you are in prostration the man said o son of the messenger of allah teach me the words to pray with he said say o allah o most merciful o compassionate o hearer of prayers o giver of good things grant me the good of the hereafter and of this world turn away from me the evil of them both and remove from me this affliction that is between my eyes for it has grieved and saddened me the man did so and was healed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 57, NULL, 'It was narrated from him that he said: Be eager for charity and give it early in the day, for there is no believer who gives a charity sincerely, desiring by it what is with Allah, except that Allah wards off from him the evil of what descends from the sky on that day and shields him from it. Then he said: And do not think little of the prayers of the poor for the sick among you, for they are answered on your behalf, though they may not be answered for the poor themselves.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it was narrated from him that he said be eager for charity and give it early in the day for there is no believer who gives a charity sincerely desiring by it what is with allah except that allah wards off from him the evil of what descends from the sky on that day and shields him from it then he said and do not think little of the prayers of the poor for the sick among you for they are answered on your behalf though they may not be answered for the poor themselves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 58, NULL, 'Ismail ibn Ali entered Medina while ill, and Abu Abd-Allah Jafar ibn Muhammad came to visit him. Seeing his condition, he said: Call for a basket, fill it with wheat, and set it before you. Then instruct your servants that when a beggar comes, they bring him in to you — and hand him some of that wheat with your own hand, and ask him to pray to Allah for you.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'ismail ibn ali entered medina while ill and abu abd allah jafar ibn muhammad came to visit him seeing his condition he said call for a basket fill it with wheat and set it before you then instruct your servants that when a beggar comes they bring him in to you and hand him some of that wheat with your own hand and ask him to pray to allah for you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 59, NULL, 'Ismail said: "Shall I not rather give them dirhams and dinars?"', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'ismail said shall i not rather give them dirhams and dinars', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 60, NULL, 'Abu Abd-Allah said: "Do what I have commanded you."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'abu abd allah said do what i have commanded you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 61, NULL, 'He did so, and was granted health.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'he did so and was granted health', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 62, NULL, 'It was narrated from Abu Abd-Allah that he said: "Three things drive away forgetfulness and bring on remembrance:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it was narrated from abu abd allah that he said three things drive away forgetfulness and bring on remembrance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 63, NULL, 'reciting the Quran using the siwak fasting"', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'reciting the quran using the siwak fasting', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 64, NULL, 'It was narrated from him that a man among his companions complained of being heavily overtaken by worry and grief. Abu Abd-Allah said: "When anything of that befalls you, pass your hand over the place of your prostration, then draw your hand across your face — from the left side of your cheek, across your forehead, to the right side of your cheek — then say: In the name of Allah, there is no god but He, the Knower of the unseen and the witnessed, He is the Most Merciful, the Most Compassionate. O Allah, remove from me worry and grief. Let him do this three times."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it was narrated from him that a man among his companions complained of being heavily overtaken by worry and grief abu abd allah said when anything of that befalls you pass your hand over the place of your prostration then draw your hand across your face from the left side of your cheek across your forehead to the right side of your cheek then say in the name of allah there is no god but he the knower of the unseen and the witnessed he is the most merciful the most compassionate o allah remove from me worry and grief let him do this three times', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 65, NULL, 'It was narrated from him that whoever says, thirty times each day, the following words — In the name of Allah, the Most Gracious, the Most Merciful; praise be to Allah, Lord of the worlds; and blessed be Allah, the best of creators; and there is no power and no strength except through Allah, the Most High, the Most Great — Allah will ward off from him ninety-nine kinds of affliction, the least of which is madness.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it was narrated from him that whoever says thirty times each day the following words in the name of allah the most gracious the most merciful praise be to allah lord of the worlds and blessed be allah the best of creators and there is no power and no strength except through allah the most high the most great allah will ward off from him ninety nine kinds of affliction the least of which is madness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 66, NULL, 'Mention of bearing illness with patience for its reward', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'mention of bearing illness with patience for its reward', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 67, NULL, 'The narration from the Imams of the family of the Messenger of Allah reports that the Messenger of Allah, peace and blessings be upon him and his family, said: "The groaning of a sick man, if he is patient and counts it for reward, is recorded for him as good deeds. But if it is in panic, he is called one given to panic, and there is no reward for him."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'the narration from the imams of the family of the messenger of allah reports that the messenger of allah peace and blessings be upon him and his family said the groaning of a sick man if he is patient and counts it for reward is recorded for him as good deeds but if it is in panic he is called one given to panic and there is no reward for him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 68, NULL, 'The full treatment of this matter — and of the reward that illness carries for one who is patient and counts it for reward — belongs among the chapters on funerals.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'the full treatment of this matter and of the reward that illness carries for one who is patient and counts it for reward belongs among the chapters on funerals', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 69, NULL, 'It is also narrated from them that a woman came to the Messenger of Allah with a son of hers who was afflicted in his mind. She said: "O Messenger of Allah, pray to Allah for this son of mine, that He may heal him."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it is also narrated from them that a woman came to the messenger of allah with a son of hers who was afflicted in his mind she said o messenger of allah pray to allah for this son of mine that he may heal him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 70, NULL, 'He said: "As you wish. If you wish, I will pray to Allah for him and He will heal him; and if you wish, I will leave him, and there will be no reckoning or punishment upon him."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'he said as you wish if you wish i will pray to allah for him and he will heal him and if you wish i will leave him and there will be no reckoning or punishment upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 71, NULL, 'She said: "Then leave him, O Messenger of Allah" — and may Allah''s prayers and —', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'she said then leave him o messenger of allah and may allahs prayers and', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 72, NULL, 'Mention of seeking refuge and the ruqyah', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'mention of seeking refuge and the ruqyah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 73, NULL, 'The Imams of the family of the Messenger of Allah have transmitted that he would seat al-Hasan and al-Husayn upon his thighs and seek refuge for them, saying: "I seek refuge for you both in the perfect words of Allah from every devil and every crawling thing, and from every envious eye." He would then add: "Thus did my father Ibrahim (ع) seek refuge for his two sons Ismail and Ishaq."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'the imams of the family of the messenger of allah have transmitted that he would seat al hasan and al husayn upon his thighs and seek refuge for them saying i seek refuge for you both in the perfect words of allah from every devil and every crawling thing and from every envious eye he would then add thus did my father ibrahim ع seek refuge for his two sons ismail and ishaq', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 74, NULL, 'It was narrated that Labid ibn al-Asam the Jew and the Jewish woman Umm Abd-Allah worked sorcery against the Prophet by tying eleven knots in a cord of red and yellow threads, placing it inside the sheath of a date-palm, and lowering it into one of the steps of a well in Medina. As a result, the Messenger of Allah and his family were left unable to hear, to see, to stand, to speak, to eat, or to drink.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it was narrated that labid ibn al asam the jew and the jewish woman umm abd allah worked sorcery against the prophet by tying eleven knots in a cord of red and yellow threads placing it inside the sheath of a date palm and lowering it into one of the steps of a well in medina as a result the messenger of allah and his family were left unable to hear to see to stand to speak to eat or to drink', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 75, NULL, 'Then Jibril (ع) descended with the two chapters of refuge and informed him that Labid ibn al-Asam and the Jewish woman Umm Abd-Allah had worked sorcery against him. Jibril told him where the sorcery lay and recited over him: In the name of Allah, the Most Gracious, the Most Merciful. Say, I seek refuge in the Lord of the Falaq, and Say, I seek refuge in the Lord of mankind, to the end of the two chapters.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'then jibril ع descended with the two chapters of refuge and informed him that labid ibn al asam and the jewish woman umm abd allah had worked sorcery against him jibril told him where the sorcery lay and recited over him in the name of allah the most gracious the most merciful say i seek refuge in the lord of the falaq and say i seek refuge in the lord of mankind to the end of the two chapters', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 76, NULL, 'As the Messenger of Allah ﷺ and his family recited, one knot was loosened and he sat up; he recited again and another knot was loosened. This continued until he had recited eleven times, all eleven knots were loosened, and the Prophet ﷺ and his family sat up, free of the sorcery''s hold. He then ordered Ali, who retrieved the sorcery from the well in which it had been placed. The Prophet summoned Labid and Umm Abd-Allah and said: "What moved you to do what you have done?" Then he said to Labid: "May Allah not bring you out of this world safe and sound." Labid was a man of wealth and great means.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'as the messenger of allah ﷺ and his family recited one knot was loosened and he sat up he recited again and another knot was loosened this continued until he had recited eleven times all eleven knots were loosened and the prophet ﷺ and his family sat up free of the sorcerys hold he then ordered ali who retrieved the sorcery from the well in which it had been placed the prophet summoned labid and umm abd allah and said what moved you to do what you have done then he said to labid may allah not bring you out of this world safe and sound labid was a man of wealth and great means', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 77, NULL, 'Labid met his end not long after. He passed by a boy wearing an earring worth a dinar, snatched it, and tore the boy''s ear in the taking. His hand was cut off and cauterized for the crime, yet the bleeding would not stop, and he bled until he died.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'labid met his end not long after he passed by a boy wearing an earring worth a dinar snatched it and tore the boys ear in the taking his hand was cut off and cauterized for the crime yet the bleeding would not stop and he bled until he died', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 78, NULL, 'Ali said: "I fell gravely ill, so that I could find no rest upon my bed, and the Prophet and his family came to visit me. He said to me: O Ali, the most sorely tried of people in this world are the prophets, then those who come after them, then those who come after them. Rejoice, for this is your share of the chastisement of Allah the Mighty and Majestic, together with the reward laid up for you. Then he said to me: Would you like Allah to lift from you what afflicts you? I said: Yes, O Messenger of Allah. He said: Say: O Allah, have mercy upon my thin skin and my fragile bone, and I seek refuge in You from the surge of the burning. O Umm Maldam, if you have believed in Allah, then do not eat flesh, do not drink blood, and do not boil over upon the mouth; depart instead to one who claims that there is another god alongside Allah. And I bear witness that there is no god but Allah alone, with no partner, and I bear witness that Muhammad is His servant and His messenger. I said it, and I was healed at that very hour."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'ali said i fell gravely ill so that i could find no rest upon my bed and the prophet and his family came to visit me he said to me o ali the most sorely tried of people in this world are the prophets then those who come after them then those who come after them rejoice for this is your share of the chastisement of allah the mighty and majestic together with the reward laid up for you then he said to me would you like allah to lift from you what afflicts you i said yes o messenger of allah he said say o allah have mercy upon my thin skin and my fragile bone and i seek refuge in you from the surge of the burning o umm maldam if you have believed in allah then do not eat flesh do not drink blood and do not boil over upon the mouth depart instead to one who claims that there is another god alongside allah and i bear witness that there is no god but allah alone with no partner and i bear witness that muhammad is his servant and his messenger i said it and i was healed at that very hour', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 79, NULL, 'Jafar ibn Muhammad said: "I never turned to it in distress but that I found it answered; and they used to teach it even to women and children."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'jafar ibn muhammad said i never turned to it in distress but that i found it answered and they used to teach it even to women and children', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 80, NULL, 'It was narrated from Ali that the Messenger of Allah, and his family, granted license for ruqyah by the Book of Allah the Mighty and Majestic, and by whatever is known of His remembrance and His names. These incantations, he said, are among what Sulayman ibn Dawud, peace be upon him, held as authority over the jinn.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it was narrated from ali that the messenger of allah and his family granted license for ruqyah by the book of allah the mighty and majestic and by whatever is known of his remembrance and his names these incantations he said are among what sulayman ibn dawud peace be upon him held as authority over the jinn', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 81, NULL, 'It was also narrated from him that the Messenger of Allah, and his family, said: "There is no ruqyah except in three things: a festering wound, an evil eye, or blood." Some hold that ruqyah extends to the sting of the scorpion and the sting of the wasp, but that is a mistake. The hummah is the venom present in such creatures — the scorpion, the serpent, and others like them — for the hummah is itself a venomous creature, while the scorpion''s sting is merely a needle.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it was also narrated from him that the messenger of allah and his family said there is no ruqyah except in three things a festering wound an evil eye or blood some hold that ruqyah extends to the sting of the scorpion and the sting of the wasp but that is a mistake the hummah is the venom present in such creatures the scorpion the serpent and others like them for the hummah is itself a venomous creature while the scorpions sting is merely a needle', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 82, NULL, 'It was narrated of the Messenger of Allah, and his family, that he sent out a company of men, and they passed by an Arab tribe whose chief had been stung. The tribesmen asked whether anyone among the company could perform a ruqyah. One of them recited over the chief the Opening of the Book, and the man was cured. When the Messenger of Allah, peace be upon him and his family, was told of this, he approved it. One of his wives likewise performed a ruqyah with the two chapters of refuge, and he approved that as well, saying to her: "And how did you know that it is a ruqyah?"', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it was narrated of the messenger of allah and his family that he sent out a company of men and they passed by an arab tribe whose chief had been stung the tribesmen asked whether anyone among the company could perform a ruqyah one of them recited over the chief the opening of the book and the man was cured when the messenger of allah peace be upon him and his family was told of this he approved it one of his wives likewise performed a ruqyah with the two chapters of refuge and he approved that as well saying to her and how did you know that it is a ruqyah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 83, NULL, 'The Master said, peace be upon him and his family: There is no contagion, no ill omen from birds, and no ham; but the evil eye is real and the good omen is real. He also said, peace be upon him and his family: When one of you looks upon a person, or a beast, or anything pleasing that delights him, let him say: I have believed in Allah; may Allah bless Muhammad and the family of Muhammad — then his eye will not harm what he looked upon. It is narrated that when an evil eye struck him, or a headache came upon him, he would spread his two hands open, recite into them the Opening of the Book and the two chapters of refuge, then wipe his face with them, and whatever he had been feeling would depart.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'the master said peace be upon him and his family there is no contagion no ill omen from birds and no ham but the evil eye is real and the good omen is real he also said peace be upon him and his family when one of you looks upon a person or a beast or anything pleasing that delights him let him say i have believed in allah may allah bless muhammad and the family of muhammad then his eye will not harm what he looked upon it is narrated that when an evil eye struck him or a headache came upon him he would spread his two hands open recite into them the opening of the book and the two chapters of refuge then wipe his face with them and whatever he had been feeling would depart', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 84, NULL, 'He and his family also forbade:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'he and his family also forbade', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 85, NULL, 'Sorcery Soothsaying Amulets Tiwalah', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'sorcery soothsaying amulets tiwalah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 86, NULL, 'Amulets are objects hung upon a person that bear something other than the names of Allah, Blessed and Exalted. Tiwalah is what women prepare in order to draw their husbands'' love toward them. Jafar ibn Muhammad said: There is no harm in a charm that is hung if it contains something of the Quran.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'amulets are objects hung upon a person that bear something other than the names of allah blessed and exalted tiwalah is what women prepare in order to draw their husbands love toward them jafar ibn muhammad said there is no harm in a charm that is hung if it contains something of the quran', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 87, NULL, 'A man once complained to Abu Abd-Allah Jafar ibn Muhammad of a pain he had found in himself. The Master said: "Say In the name of Allah and wipe over the place, then say: I seek refuge in the might of Allah, I seek refuge in the power of Allah, I seek refuge in the majesty of Allah, I seek refuge in the greatness of Allah, I seek refuge in all the bounds of Allah, I seek refuge in the names of Allah, and I seek refuge in the names of the Messenger, may Allah bless him and his family, from the evil of what I find. Let him say this seven times."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'a man once complained to abu abd allah jafar ibn muhammad of a pain he had found in himself the master said say in the name of allah and wipe over the place then say i seek refuge in the might of allah i seek refuge in the power of allah i seek refuge in the majesty of allah i seek refuge in the greatness of allah i seek refuge in all the bounds of allah i seek refuge in the names of allah and i seek refuge in the names of the messenger may allah bless him and his family from the evil of what i find let him say this seven times', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 88, NULL, 'The man said: "I said it, and what I had been suffering left me."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'the man said i said it and what i had been suffering left me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 89, NULL, 'It was also narrated from him and his family that he said: "When you wish to seek refuge, clasp your two palms together and recite into them the Opening of the Book and Say, He is Allah, One three times, then lay them upon the place of pain. Clasp them again, recite into them the Opening of the Book and Say, I seek refuge in the Lord of the Falaq three times, and lay them upon the pain a second time. Clasp them once more, recite into them the Opening of the Book and Say, I seek refuge in the Lord of mankind three times, and lay them upon the pain. Three times in all."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it was also narrated from him and his family that he said when you wish to seek refuge clasp your two palms together and recite into them the opening of the book and say he is allah one three times then lay them upon the place of pain clasp them again recite into them the opening of the book and say i seek refuge in the lord of the falaq three times and lay them upon the pain a second time clasp them once more recite into them the opening of the book and say i seek refuge in the lord of mankind three times and lay them upon the pain three times in all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 90, NULL, 'It was narrated from Ali that he said: whoever is ill-tempered, let the call to prayer be given in his ear. Abu Abd-Allah Jafar ibn Muhammad said of a sick man for whom a ruqyah is performed: there is no harm in it, so long as the ruqyah is by something known. It was narrated from Abu Jafar Muhammad ibn Ali that he said: "When you wish to perform a ruqyah upon a wound, against pain, or blood, or what is feared for it, place your hand upon the wound and say: In the name of Allah I perform your ruqyah; in the name of Allah the Greatest, against iron and stone, and the dark fang and the running of sweat, so let it not deceive, and against the eye, so let it not keep vigil. Repeat it three times."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it was narrated from ali that he said whoever is ill tempered let the call to prayer be given in his ear abu abd allah jafar ibn muhammad said of a sick man for whom a ruqyah is performed there is no harm in it so long as the ruqyah is by something known it was narrated from abu jafar muhammad ibn ali that he said when you wish to perform a ruqyah upon a wound against pain or blood or what is feared for it place your hand upon the wound and say in the name of allah i perform your ruqyah in the name of allah the greatest against iron and stone and the dark fang and the running of sweat so let it not deceive and against the eye so let it not keep vigil repeat it three times', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 91, NULL, 'Mention of treatment and medicine:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'mention of treatment and medicine', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 92, NULL, 'The Imams of the Ahl al-Bayt narrate that the Messenger of Allah, and his family, was asked whether the sick should be treated and given remedies. He said: "Yes. Allah, Blessed and Exalted, has sent down no disease without sending down a remedy with it, so seek treatment — except for the sam, which is death, for it has no cure."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'the imams of the ahl al bayt narrate that the messenger of allah and his family was asked whether the sick should be treated and given remedies he said yes allah blessed and exalted has sent down no disease without sending down a remedy with it so seek treatment except for the sam which is death for it has no cure', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 93, NULL, 'A group of the Ansar brought him a question concerning one of their number who was suffering from a stomach complaint, and concerning a Jewish physician who treated such conditions by opening the abdomen. The Messenger of Allah, and his family, was reluctant and withheld his permission. They returned to him two or three times, and each time he refused, until at last he said to them: "Do as you wish." The Jewish physician was summoned. He opened the man''s abdomen, removed a great deal of foul matter, washed and stitched it closed, and administered treatment — and the man recovered. When the Messenger of Allah, and his family, was told of this, he said: "He who created the disease has appointed for it a remedy; and the best of remedies are cupping, phlebotomy, and the black seed — which is the shuneez." The Messenger of Allah, and his family, also forbade imposing strict diets upon the sick.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'a group of the ansar brought him a question concerning one of their number who was suffering from a stomach complaint and concerning a jewish physician who treated such conditions by opening the abdomen the messenger of allah and his family was reluctant and withheld his permission they returned to him two or three times and each time he refused until at last he said to them do as you wish the jewish physician was summoned he opened the mans abdomen removed a great deal of foul matter washed and stitched it closed and administered treatment and the man recovered when the messenger of allah and his family was told of this he said he who created the disease has appointed for it a remedy and the best of remedies are cupping phlebotomy and the black seed which is the shuneez the messenger of allah and his family also forbade imposing strict diets upon the sick', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 94, NULL, 'He looked at Salman, who was eating dates while suffering from sore eyes, and said: "O Salman, you eat dates while your eyes are afflicted?"', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'he looked at salman who was eating dates while suffering from sore eyes and said o salman you eat dates while your eyes are afflicted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 95, NULL, 'Salman replied: "O Messenger of Allah, it is only my right eye that is sore, and I am chewing with my left teeth."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'salman replied o messenger of allah it is only my right eye that is sore and i am chewing with my left teeth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 96, NULL, 'The Messenger of Allah smiled and did not stop him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'the messenger of allah smiled and did not stop him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 97, NULL, 'It was also narrated from him and his family that skipping the evening meal is a cause of weakness in old age. He and his family said that the sick should not be compelled to eat, for Allah the Mighty and Majestic feeds them and gives them drink. It was narrated from him and his family that there is no harm in an enema, were it not that it enlarges the belly. He and his family also said: when blood becomes excessive in one of you, let him draw it off, even with a small blade — meaning when the blood overcomes him. They further said that cupping of the head is a cure for every disease, and that remedy lies in four things:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it was also narrated from him and his family that skipping the evening meal is a cause of weakness in old age he and his family said that the sick should not be compelled to eat for allah the mighty and majestic feeds them and gives them drink it was narrated from him and his family that there is no harm in an enema were it not that it enlarges the belly he and his family also said when blood becomes excessive in one of you let him draw it off even with a small blade meaning when the blood overcomes him they further said that cupping of the head is a cure for every disease and that remedy lies in four things', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 98, NULL, 'Cupping The enema The depilatory Vomiting', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'cupping the enema the depilatory vomiting', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 99, NULL, 'Ali said that the Messenger of Allah was never seized by fever but that he turned to cupping. He used to say: "When blood becomes excessive in one of you, let him be cupped on whatever day it may be, and let him recite Ayat al-Kursi, seek the forgiveness of Allah the Mighty and Majestic, and send blessings upon the Prophet, may Allah bless him and his family. Do not hold certain days to be against you, lest they be set against you; be cupped on whichever of them you wish; and let him name Allah over the cupping vessel."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'ali said that the messenger of allah was never seized by fever but that he turned to cupping he used to say when blood becomes excessive in one of you let him be cupped on whatever day it may be and let him recite ayat al kursi seek the forgiveness of allah the mighty and majestic and send blessings upon the prophet may allah bless him and his family do not hold certain days to be against you lest they be set against you be cupped on whichever of them you wish and let him name allah over the cupping vessel', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 100, NULL, 'Among the narrated traditions concerning the body and its remedies: cupping of the head brings relief, and cupping of the upper back — the kahil — is beneficial. Fever, being from the heat of Hell, is to be cooled with water; whenever the Messenger of Allah and his family was seized with fever, he would call for water and place his hand in it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'among the narrated traditions concerning the body and its remedies cupping of the head brings relief and cupping of the upper back the kahil is beneficial fever being from the heat of hell is to be cooled with water whenever the messenger of allah and his family was seized with fever he would call for water and place his hand in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 101, NULL, 'Al-Hasan and al-Husayn once fell ill with fever, and Fatima came to the Messenger of Allah seeking help and refuge. She said, "O Messenger of Allah, pray to Allah for your son that He heal him, for he is gravely ill." The Messenger of Allah and his family rose, came to the boy, sat at his head, and found him in a heavy state. He said, "O Fatima, it is Allah the Almighty who bestowed him upon you, and He is able to heal him." Then Jibril came to him and said, "O Muhammad, Allah the Almighty has not sent down upon you a sura of the Quran that does not contain a fa — and every fa is an affliction, an afa — save al-Hamd, for there is no fa in it. So call for a cup of water, recite al-Hamd over it forty times, then pour it over him, and Allah the Almighty will heal him." The Messenger of Allah and his family did so, and it was as though the boy had been loosed from a tether.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'al hasan and al husayn once fell ill with fever and fatima came to the messenger of allah seeking help and refuge she said o messenger of allah pray to allah for your son that he heal him for he is gravely ill the messenger of allah and his family rose came to the boy sat at his head and found him in a heavy state he said o fatima it is allah the almighty who bestowed him upon you and he is able to heal him then jibril came to him and said o muhammad allah the almighty has not sent down upon you a sura of the quran that does not contain a fa and every fa is an affliction an afa save al hamd for there is no fa in it so call for a cup of water recite al hamd over it forty times then pour it over him and allah the almighty will heal him the messenger of allah and his family did so and it was as though the boy had been loosed from a tether', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 102, NULL, 'He was asked about cauterisation, and he forbade it. Jafar ibn Muhammad said, "There is no objection to cauterisation. What was forbidden concerns that which is feared to cause death, or that which disfigures the body. As for what one hopes will bring a cure, there is nothing wrong with it."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'he was asked about cauterisation and he forbade it jafar ibn muhammad said there is no objection to cauterisation what was forbidden concerns that which is feared to cause death or that which disfigures the body as for what one hopes will bring a cure there is nothing wrong with it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 103, NULL, 'The Messenger of Allah and his family used to command applying kohl with ithmid before sleep. He would say, "Apply kohl an odd number of times." He also said, "Use ithmid, for it makes the lashes grow, removes the motes from the eye, and clears the sight." He and his family confirmed that al-Ajwa is from Paradise and carries within it a cure for poison. Some of the Ahl al-Bayt described its preparation as follows:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'the messenger of allah and his family used to command applying kohl with ithmid before sleep he would say apply kohl an odd number of times he also said use ithmid for it makes the lashes grow removes the motes from the eye and clears the sight he and his family confirmed that al ajwa is from paradise and carries within it a cure for poison some of the ahl al bayt described its preparation as follows', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 104, NULL, 'Take Ajwa dates and remove their stones. Pound them thoroughly, then knead them with aged cow''s ghee. Set the mixture aside; when someone who has taken poison is in need of it, he eats it, and it benefits him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'take ajwa dates and remove their stones pound them thoroughly then knead them with aged cows ghee set the mixture aside when someone who has taken poison is in need of it he eats it and it benefits him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 105, NULL, 'It is narrated that a scorpion stung the Messenger of Allah. He struck it down and said, "May Allah curse you, for you spare neither believer nor disbeliever from your sting." He then called for salt, placed it upon the site of the sting, and pressed it with his thumb until it dissolved. He said, "If people knew what is in salt, they would have no need of any antidote alongside it."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it is narrated that a scorpion stung the messenger of allah he struck it down and said may allah curse you for you spare neither believer nor disbeliever from your sting he then called for salt placed it upon the site of the sting and pressed it with his thumb until it dissolved he said if people knew what is in salt they would have no need of any antidote alongside it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 106, NULL, 'It is narrated that he said, "Whoever eats twenty-one seedless raisins each morning on an empty stomach will not fall ill except with the illness in which he dies." And: "Whoever eats seven dates at his bedtime will be spared colic, and the worms in his belly will be killed." He said to Jafar ibn Abi Talib, "Eat quince, for it strengthens the heart and emboldens the coward."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it is narrated that he said whoever eats twenty one seedless raisins each morning on an empty stomach will not fall ill except with the illness in which he dies and whoever eats seven dates at his bedtime will be spared colic and the worms in his belly will be killed he said to jafar ibn abi talib eat quince for it strengthens the heart and emboldens the coward', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 107, NULL, 'He said, "Honey is a healing." Jafar ibn Muhammad noted that Allah the Almighty has mentioned it in His Book, saying of it, "فِيهِ شِفَآءٌۭ لِّلنَّاسِ" — that is, "In it is a healing for people." He said (ع and his family), "Beware of al-shabram, for it is hot; and you must take senna, so treat yourselves with it, for if anything could repel death, senna would repel it. And treat yourselves with fenugreek, for if my nation knew what it holds for them, they would treat themselves with it even were it to cost its weight in gold."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'he said honey is a healing jafar ibn muhammad noted that allah the almighty has mentioned it in his book saying of it فيه شفاء للناس that is in it is a healing for people he said ع and his family beware of al shabram for it is hot and you must take senna so treat yourselves with it for if anything could repel death senna would repel it and treat yourselves with fenugreek for if my nation knew what it holds for them they would treat themselves with it even were it to cost its weight in gold', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 108, NULL, 'He forbade (ع and his family) the eating of clay and charcoal, and said that Allah the Almighty created Adam from clay and therefore forbade the eating of clay to his descendants. "Whoever eats clay has aided in his own harm, and whoever persists in eating clay until he dies of it, I will not pray over him." Jafar ibn Muhammad said that the eating of clay breeds hypocrisy.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'he forbade ع and his family the eating of clay and charcoal and said that allah the almighty created adam from clay and therefore forbade the eating of clay to his descendants whoever eats clay has aided in his own harm and whoever persists in eating clay until he dies of it i will not pray over him jafar ibn muhammad said that the eating of clay breeds hypocrisy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 109, NULL, 'The Messenger of Allah (ع and his family) said that eating fresh, soft fish dissolves the body, and warned against making a habit of it. When he ate fish, he would say, "O Allah, bless it for us and give us in its place what is better than it." Jafar ibn Muhammad said, "Whoever eats fish, let him eat dates afterward, for that removes its harm." The Messenger of Allah (ع and his family) also forbade drinking al-hamim. Al-hamim is the rain that falls during the worst of summer heat; it is also hot water, and more broadly any rainwater that falls in intense heat, runs along the ground, and grows hot and harmful in doing so. His prohibition rested on that harm alone — not because al-hamim is unlawful or impure, but because its harmful nature made it blameworthy.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'the messenger of allah ع and his family said that eating fresh soft fish dissolves the body and warned against making a habit of it when he ate fish he would say o allah bless it for us and give us in its place what is better than it jafar ibn muhammad said whoever eats fish let him eat dates afterward for that removes its harm the messenger of allah ع and his family also forbade drinking al hamim al hamim is the rain that falls during the worst of summer heat it is also hot water and more broadly any rainwater that falls in intense heat runs along the ground and grows hot and harmful in doing so his prohibition rested on that harm alone not because al hamim is unlawful or impure but because its harmful nature made it blameworthy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 110, NULL, 'It is narrated from him that he said, "Whoever is a physician, or undertakes treatment — Arab or non-Arab — let him not treat anyone until he has obtained from him a written release, witnessed by witnesses. Let him fear Allah the Almighty, strive diligently, and counsel sincerely." By the release, he meant that the physician must be learned in medicine and must not treat people from a position of ignorance; for if he does, he bears liability for whatever harm results.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it is narrated from him that he said whoever is a physician or undertakes treatment arab or non arab let him not treat anyone until he has obtained from him a written release witnessed by witnesses let him fear allah the almighty strive diligently and counsel sincerely by the release he meant that the physician must be learned in medicine and must not treat people from a position of ignorance for if he does he bears liability for whatever harm results', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 111, NULL, 'It is narrated from him that he used to say, "Whoever desires to endure — though there is no enduring — let him lighten his burden, keep to his sandals, take his morning meal early, draw his evening meal near, and lessen intercourse." He was asked, "O Commander of the Faithful, what is the lightening of the burden?" He replied, "It is debt."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it is narrated from him that he used to say whoever desires to endure though there is no enduring let him lighten his burden keep to his sandals take his morning meal early draw his evening meal near and lessen intercourse he was asked o commander of the faithful what is the lightening of the burden he replied it is debt', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 112, NULL, 'The Master said, "The truffle is from the manna, and its water is a cure for the eye." Some of the Ahl al-Bayt described its preparation:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'the master said the truffle is from the manna and its water is a cure for the eye some of the ahl al bayt described its preparation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 113, NULL, 'Wash the truffle until clean, then squeeze its water into a vessel. Kindle a fire beneath the vessel until the liquid thickens. Add musk, then apply the preparation as kohl for all ailments of the eye. When its moisture dries, moisten it with rainwater and apply it as kohl once more.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'wash the truffle until clean then squeeze its water into a vessel kindle a fire beneath the vessel until the liquid thickens add musk then apply the preparation as kohl for all ailments of the eye when its moisture dries moisten it with rainwater and apply it as kohl once more', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 114, NULL, 'It is also narrated from Ali that he said, "Nothing restores the woman in childbirth like eating fresh, moist dates. Allah the Almighty fed Maryam fresh dates in her childbirth." He said, "Eat the pomegranate with its pith, for it is a tanner for the stomach. And eat apples, for they cleanse the stomach."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it is also narrated from ali that he said nothing restores the woman in childbirth like eating fresh moist dates allah the almighty fed maryam fresh dates in her childbirth he said eat the pomegranate with its pith for it is a tanner for the stomach and eat apples for they cleanse the stomach', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 115, NULL, 'It is narrated from him and his family that the Messenger of Allah said, "Celery is the herb of the prophets, and there is no leaf of endive but that upon it is water from Paradise. Take the gourd, for it strengthens the heart and the mind." He once trod upon scorching ground and it burned him, so he stepped onto purslane — the herb known as the foolish herb — and the heat of the ground subsided for him. He blessed it, and thereafter he ate it regularly and was fond of it. Ali said, "The sick are healed by nothing like the drinking of honey."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it is narrated from him and his family that the messenger of allah said celery is the herb of the prophets and there is no leaf of endive but that upon it is water from paradise take the gourd for it strengthens the heart and the mind he once trod upon scorching ground and it burned him so he stepped onto purslane the herb known as the foolish herb and the heat of the ground subsided for him he blessed it and thereafter he ate it regularly and was fond of it ali said the sick are healed by nothing like the drinking of honey', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 116, NULL, 'Jafar ibn Muhammad was asked about a man who seeks treatment from a Jewish or Christian physician. He said, "There is nothing wrong with that, for healing is in the hand of Allah the Almighty." He was also asked whether a woman who has a disease, a fracture, or a wound in a place not proper to be looked upon may uncover it before a male physician. He said, "There is nothing wrong with that when she is compelled to it." He was further asked about a man who treats people with medicine and charges a fee for doing so, and he said, "There is nothing wrong with it."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'jafar ibn muhammad was asked about a man who seeks treatment from a jewish or christian physician he said there is nothing wrong with that for healing is in the hand of allah the almighty he was also asked whether a woman who has a disease a fracture or a wound in a place not proper to be looked upon may uncover it before a male physician he said there is nothing wrong with that when she is compelled to it he was further asked about a man who treats people with medicine and charges a fee for doing so and he said there is nothing wrong with it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 117, NULL, 'It is narrated from him that he said, "If people were moderate in their food and drink, their bodies would remain sound." He said, "Abandoning the evening meal is the ruin of the body." He said, "Allah the Almighty says, وَلَهُمْ رِزْقُهُمْ فِيهَا بُكْرَةًۭ وَعَشِيًّۭا — that is, and they shall have their provision therein, morning and evening." A man complained to him of pains and indigestion, and he said, "Take your midday meal and your evening meal, and eat nothing between them, for that is the corruption of the body." He said, "Abandoning the evening meal diminishes a strength that does not return," and, "Let not the aged man abandon the evening meal, even if it be only a morsel." He said, "Eating meat with milk makes the flesh grow and strengthens the bone." And he said, "A prophet among the prophets complained to Allah the Almighty of his few children, so He commanded him to eat meat with eggs."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it is narrated from him that he said if people were moderate in their food and drink their bodies would remain sound he said abandoning the evening meal is the ruin of the body he said allah the almighty says ولهم رزقهم فيها بكره وعشيا that is and they shall have their provision therein morning and evening a man complained to him of pains and indigestion and he said take your midday meal and your evening meal and eat nothing between them for that is the corruption of the body he said abandoning the evening meal diminishes a strength that does not return and let not the aged man abandon the evening meal even if it be only a morsel he said eating meat with milk makes the flesh grow and strengthens the bone and he said a prophet among the prophets complained to allah the almighty of his few children so he commanded him to eat meat with eggs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 118, NULL, 'The Messenger of Allah, narrating from him and his family, counseled Ali with these words: "O Ali, sleep upon your back, for it slims the belly. Drink water by sipping, for thereby your food is made wholesome. Wear a ring, and apply kohl an odd number of times, for it will brighten your sight. Anoint yourself every other day, in keeping with the Sunnah of your Prophet. Renew your sandals, for they are the anklets of a man, and turbans are the crowns of the Arabs. When you cook a pot, make its broth plentiful, for if your neighbors do not receive some of its meat, they will receive some of its broth. Wear a ring of ruby and carnelian, for it is fortunate and blessed; whenever a man looks at his face within it, it increases him in light, and the prayer offered wearing it is worth seventy prayers. Wear the ring upon your right hand, for that is the practice of the Messengers, and whoever turns away from my Sunnah is not of me. Do not wear a ring upon the left, nor of anything but ruby and carnelian."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'the messenger of allah narrating from him and his family counseled ali with these words o ali sleep upon your back for it slims the belly drink water by sipping for thereby your food is made wholesome wear a ring and apply kohl an odd number of times for it will brighten your sight anoint yourself every other day in keeping with the sunnah of your prophet renew your sandals for they are the anklets of a man and turbans are the crowns of the arabs when you cook a pot make its broth plentiful for if your neighbors do not receive some of its meat they will receive some of its broth wear a ring of ruby and carnelian for it is fortunate and blessed whenever a man looks at his face within it it increases him in light and the prayer offered wearing it is worth seventy prayers wear the ring upon your right hand for that is the practice of the messengers and whoever turns away from my sunnah is not of me do not wear a ring upon the left nor of anything but ruby and carnelian', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 119, NULL, 'It is narrated from Jafar ibn Muhammad that one of his companions came to him complaining of pain in his loin. He said to the man, "Take what falls from the table during a meal, gather it up, and eat it." The man said, "I did so, and I was healed." Jafar ibn Muhammad then said, "Eat of the food that falls from the table, for in it is a healing, by the leave of Allah the Almighty, for whoever seeks healing by it — that is, for every disease."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it is narrated from jafar ibn muhammad that one of his companions came to him complaining of pain in his loin he said to the man take what falls from the table during a meal gather it up and eat it the man said i did so and i was healed jafar ibn muhammad then said eat of the food that falls from the table for in it is a healing by the leave of allah the almighty for whoever seeks healing by it that is for every disease', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 120, NULL, 'A man once looked at the apples in Abu Abdullah Jafar ibn Muhammad''s hands, and the Master said to him, "The apple cools heat and quenches it, and drives off fever."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'a man once looked at the apples in abu abdullah jafar ibn muhammads hands and the master said to him the apple cools heat and quenches it and drives off fever', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 121, NULL, 'Of vinegar he said, "It firms the mouth and kills the worms of the belly."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'of vinegar he said it firms the mouth and kills the worms of the belly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 122, NULL, 'He said, "Rice sawiq, when parched and ground, binds the belly; whether part of it is made into sawiq and part into a gruel, it binds the belly all the same. Sawiq builds flesh and strengthens bone, and it benefits the feverish when moistened and washed three times. Take sawiq dry on an empty stomach, for it dispels phlegm and bile."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'he said rice sawiq when parched and ground binds the belly whether part of it is made into sawiq and part into a gruel it binds the belly all the same sawiq builds flesh and strengthens bone and it benefits the feverish when moistened and washed three times take sawiq dry on an empty stomach for it dispels phlegm and bile', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the body''s portion: food, drink, and healing', '3. The Body''s Portion: Food, Drink, and Healing', 123, NULL, 'It is also narrated from Ali ibn al-Husayn that he permitted treatment with the milk of she-asses, and that the milk of the wild ass, if one can obtain it, is better still.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 3 the bodys portion food drink and healing', 'it is also narrated from ali ibn al husayn that he permitted treatment with the milk of she asses and that the milk of the wild ass if one can obtain it is better still', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 0, NULL, 'Jafar ibn Muhammad (ع) said: "Dress and adorn yourselves with what is lawful, for Allah, mighty and exalted, loves beauty." It is narrated that he went out one cold day wearing a fur cloak of yellow khazz and a yellow khazz mantle. When he saw the people staring at him, he said: "There was a prophet, the son of a prophet, the son of a prophet, the son of a prophet" — meaning Yusuf (ع) — "who wore robes of brocade fastened with gold and sat upon his throne to judge among the people."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'jafar ibn muhammad ع said dress and adorn yourselves with what is lawful for allah mighty and exalted loves beauty it is narrated that he went out one cold day wearing a fur cloak of yellow khazz and a yellow khazz mantle when he saw the people staring at him he said there was a prophet the son of a prophet the son of a prophet the son of a prophet meaning yusuf ع who wore robes of brocade fastened with gold and sat upon his throne to judge among the people', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 1, NULL, 'Ali ibn al-Husayn (ع) used to wear in summer two garments bought for five hundred dirhams each, and in winter he wore khazz. Jafar ibn Muhammad was asked about a man who acquires many garments to adorn himself, keeping some in reserve to protect the others, and whether this constitutes excess. He said: "No, that is not extravagance. Allah, mighty and exalted, says: ﴿لِيُنفِقْ ذُو سَعَةٍ مِّن سَعَتِهِ﴾ Let the one who has abundance spend out of his abundance." (Al-Talaq: 7)', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'ali ibn al husayn ع used to wear in summer two garments bought for five hundred dirhams each and in winter he wore khazz jafar ibn muhammad was asked about a man who acquires many garments to adorn himself keeping some in reserve to protect the others and whether this constitutes excess he said no that is not extravagance allah mighty and exalted says لينفق ذو سعه من سعته let the one who has abundance spend out of his abundance al talaq 7', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 2, NULL, 'Al-A''raf: 32قُلْ مَنْ حَرَّمَ زِينَةَ ٱللَّهِ ٱلَّتِىٓ أَخْرَجَ لِعِبَادِهِۦ وَٱلطَّيِّبَتِ مِنَ ٱلرِّزْقِ', '', 'قُلْ مَنْ حَرَّمَ زِينَةَ ٱللَّهِ ٱلَّتِىٓ أَخْرَجَ لِعِبَادِهِۦ وَٱلطَّيِّبَتِ مِنَ ٱلرِّزْقِ', 'Al-A''raf: 32', 7, 32, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'al araf 32قل من حرم زينه الله التي اخرج لعباده والطيبت من الرزق', 'قل من حرم زينه الله التي اخرج لعباده والطيبت من الرزق');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 3, NULL, 'Sufyan al-Thawri came in upon him and saw that he was wearing fine garments. He said: "O son of the Messenger of Allah, may Allah bless him and his family and grant him peace, you tell us that Ali, (ع), used to wear coarse cloth and rough fabric, yet here you are dressed in al-Quhi and al-Muwri." He answered: "Woe to you, Sufyan. Ali lived in a time of hardship and scarcity, but Allah, mighty and exalted, has widened our means, and it is fitting for the one upon whom Allah has bestowed abundance that the trace of that bounty be seen upon him."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'sufyan al thawri came in upon him and saw that he was wearing fine garments he said o son of the messenger of allah may allah bless him and his family and grant him peace you tell us that ali ع used to wear coarse cloth and rough fabric yet here you are dressed in al quhi and al muwri he answered woe to you sufyan ali lived in a time of hardship and scarcity but allah mighty and exalted has widened our means and it is fitting for the one upon whom allah has bestowed abundance that the trace of that bounty be seen upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 4, NULL, 'Ali ibn al-Husayn used to have a khazz mantle bought for him for fifty dinars, which he would wear through the winter, entering the mosque and praying in it. When summer came he would order that it be given away as charity on his behalf, and he would command that two garments of the Egyptian sort be bought for him, which would be readied and which he would wear in the summer, wearing between these the fine and the plain alike. When this was remarked upon to him, he would recite the words of Allah, mighty and exalted: ﴿قُلْ مَنْ حَرَّمَ زِينَةَ اللَّهِ الَّتِي أَخْرَجَ لِعِبَادِهِ وَالطَّيِّبَاتِ مِنَ الرِّزْقِ﴾ "Say: Who has forbidden the adornment of Allah which He has brought forth for His servants, and the good things of sustenance?" (Al-Araf: 32)', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'ali ibn al husayn used to have a khazz mantle bought for him for fifty dinars which he would wear through the winter entering the mosque and praying in it when summer came he would order that it be given away as charity on his behalf and he would command that two garments of the egyptian sort be bought for him which would be readied and which he would wear in the summer wearing between these the fine and the plain alike when this was remarked upon to him he would recite the words of allah mighty and exalted قل من حرم زينه الله التي اخرج لعباده والطيبات من الرزق say who has forbidden the adornment of allah which he has brought forth for his servants and the good things of sustenance al araf 32', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 5, NULL, 'Ali once looked upon a group of people wearing wool and hair garments, and said to them: "Wear cotton, for that was the clothing of the Messenger of Allah — the best he could find — and it is our dress. He wore neither wool nor hair, so do not wear them except out of need, or when nothing else can be found. Allah, mighty and exalted, is beautiful and loves beauty, and He loves to see the trace of His blessing upon His servant."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'ali once looked upon a group of people wearing wool and hair garments and said to them wear cotton for that was the clothing of the messenger of allah the best he could find and it is our dress he wore neither wool nor hair so do not wear them except out of need or when nothing else can be found allah mighty and exalted is beautiful and loves beauty and he loves to see the trace of his blessing upon his servant', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 6, NULL, 'It is narrated from Jafar ibn Muhammad that he performed the Hajj, entering ihram in two fine garments. While he was making tawaf in them, a man tugged at the edge of his cloak. He turned and found it was Abbad al-Basri, who said to him: "O Abu Abdullah, you wear garments such as these, in a place such as this — knowing where you stand in relation to Ali, and knowing what his clothing was like?" He replied, (ع): "Woe to you, Abbad. Ali lived in a time when what he wore suited it. Were I to wear his dress today, people would say: this man is a pretender, like Abbad al-Basri." Abbad was already known for ostentation. He fell silent, covered in shame, while those around him exchanged glances at his expense.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'it is narrated from jafar ibn muhammad that he performed the hajj entering ihram in two fine garments while he was making tawaf in them a man tugged at the edge of his cloak he turned and found it was abbad al basri who said to him o abu abdullah you wear garments such as these in a place such as this knowing where you stand in relation to ali and knowing what his clothing was like he replied ع woe to you abbad ali lived in a time when what he wore suited it were i to wear his dress today people would say this man is a pretender like abbad al basri abbad was already known for ostentation he fell silent covered in shame while those around him exchanged glances at his expense', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 7, NULL, 'It is also narrated from him that the Messenger of Allah, may Allah bless him and his family, said: "Wear fine turbans, for they are the crowns of the Arabs."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'it is also narrated from him that the messenger of allah may allah bless him and his family said wear fine turbans for they are the crowns of the arabs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 8, NULL, 'It is further narrated from Abu Jafar Muhammad (ع) that some of his companions once entered his room and found it richly appointed — furnished with cushions, embroidered coverings, armrests, and bedding. On a later visit they found him in a room with nothing but a reed mat. They said to him: "May we be your ransom — what is this room?" He said: "This is my room. The room you saw before belongs to the women. Let me tell you something my father told me. He said: Some people once came in upon al-Husayn and found his dwelling spread with carpets, rugs, and many furnishings. They said: O son of the Messenger of Allah, we see in your house things that were not in the house of the Messenger of Allah, may Allah bless him and his family. He said: We marry women and give them their dowries, with which they furnish and prepare their homes."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'it is further narrated from abu jafar muhammad ع that some of his companions once entered his room and found it richly appointed furnished with cushions embroidered coverings armrests and bedding on a later visit they found him in a room with nothing but a reed mat they said to him may we be your ransom what is this room he said this is my room the room you saw before belongs to the women let me tell you something my father told me he said some people once came in upon al husayn and found his dwelling spread with carpets rugs and many furnishings they said o son of the messenger of allah we see in your house things that were not in the house of the messenger of allah may allah bless him and his family he said we marry women and give them their dowries with which they furnish and prepare their homes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 9, NULL, 'As for clothing — whether fine or plain — wearing it, spreading it out, and wrapping oneself in it are all permissible, and nothing in this is disliked. Whoever chooses the plain out of humility, though finer clothing was within reach, has done nothing wrong. Whoever chooses the fine, finding it accessible and within his means, that too is permissible — indeed it is recommended, as a display of the grace of Allah, mighty and exalted. The Messenger of Allah, may Allah bless him and his family, wore both the fine and the plain, whatever he chose for himself and whatever others clothed him in.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'as for clothing whether fine or plain wearing it spreading it out and wrapping oneself in it are all permissible and nothing in this is disliked whoever chooses the plain out of humility though finer clothing was within reach has done nothing wrong whoever chooses the fine finding it accessible and within his means that too is permissible indeed it is recommended as a display of the grace of allah mighty and exalted the messenger of allah may allah bless him and his family wore both the fine and the plain whatever he chose for himself and whatever others clothed him in', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 10, NULL, 'The Imams (عَلَيْهِمُ السَّلَامُ) are reported to have taught that clothing made from whatever the earth produces — wearing it, spreading it, wrapping oneself in it, praying in it and upon it — is lawful. Likewise, the skin, wool, hair, and fur of any animal whose flesh is permissible to eat are lawful and permitted, provided the animal was properly slaughtered. As for the wool, hair, fur, and skin of an animal that died without proper slaughter, wrapping oneself in such material, spreading it, and making use of it is permitted, as already noted — just as use is permitted of things that have been touched by impurities — with one exception: one may not pray in any of it, just as one does not pray in an impure garment.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'the imams عليهم السلام are reported to have taught that clothing made from whatever the earth produces wearing it spreading it wrapping oneself in it praying in it and upon it is lawful likewise the skin wool hair and fur of any animal whose flesh is permissible to eat are lawful and permitted provided the animal was properly slaughtered as for the wool hair fur and skin of an animal that died without proper slaughter wrapping oneself in such material spreading it and making use of it is permitted as already noted just as use is permitted of things that have been touched by impurities with one exception one may not pray in any of it just as one does not pray in an impure garment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 11, NULL, 'Al-Anfal: 60وَأَعِدُّوا۟ لَهُم مَّا ٱسْتَطَعْتُم مِّن قُوَّةٍۢ وَمِن رِّبَاطِ ٱلْخَيْلِ تُرْهِبُونَ بِهِۦ عَدُوَّ', '', 'وَأَعِدُّوا۟ لَهُم مَّا ٱسْتَطَعْتُم مِّن قُوَّةٍۢ وَمِن رِّبَاطِ ٱلْخَيْلِ تُرْهِبُونَ بِهِۦ عَدُوَّ', 'Al-Anfal: 60', 8, 60, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'al anfal 60واعدوا لهم ما استطعتم من قوه ومن رباط الخيل ترهبون به عدو', 'واعدوا لهم ما استطعتم من قوه ومن رباط الخيل ترهبون به عدو');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 12, NULL, 'The Imams disliked for a man to wear pure silk, though they permitted what was woven together with other material grown from the earth. It is narrated that the Messenger of Allah, may Allah bless him and his family, permitted it to certain people and allowed that one display and adorn oneself with it before the enemy, so that they might recognize the strength of the Muslims — in keeping with the words of Allah, blessed and exalted: ﴿وَأَعِدُّوا لَهُم مَّا اسْتَطَعْتُم مِّن قُوَّةٍ وَمِن رِّبَاطِ الْخَيْلِ تُرْهِبُونَ بِهِ عَدُوَّ اللَّهِ﴾ "And prepare against them whatever force you are able, and steeds of war, by which you strike fear into the enemy of Allah." (Al-Anfal: 60)', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'the imams disliked for a man to wear pure silk though they permitted what was woven together with other material grown from the earth it is narrated that the messenger of allah may allah bless him and his family permitted it to certain people and allowed that one display and adorn oneself with it before the enemy so that they might recognize the strength of the muslims in keeping with the words of allah blessed and exalted واعدوا لهم ما استطعتم من قوه ومن رباط الخيل ترهبون به عدو الله and prepare against them whatever force you are able and steeds of war by which you strike fear into the enemy of allah al anfal 60', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 13, NULL, 'The Imams would themselves wear silk in this manner — woven with other materials and lined with what the earth grows — displaying it before the enemies of Allah, and they permitted it to whoever would display it in the same way. The world and all it contains ranked among the most trifling of things in their sight, yet they showed of it what they showed as a preparation for the strength of Islam and the Muslims, and as a display before those who set themselves against them and made themselves their enemies among all people.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'the imams would themselves wear silk in this manner woven with other materials and lined with what the earth grows displaying it before the enemies of allah and they permitted it to whoever would display it in the same way the world and all it contains ranked among the most trifling of things in their sight yet they showed of it what they showed as a preparation for the strength of islam and the muslims and as a display before those who set themselves against them and made themselves their enemies among all people', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 14, NULL, 'The Messenger of Allah, may Allah bless him and his family, loved white garments above all others, and would say: "It is the best of your clothing, so wear it, and shroud your dead in it." No dye, however, renders a garment forbidden to wear. The Messenger of Allah, may Allah bless him and his family, and the Imams of his house wore dyed cloth, though they preferred certain dyes over others. It is narrated from Ali that he said: "Saffron is ours, and safflower yellow is for the Banu Umayyah." Jafar ibn Muhammad disliked a deep, heavily saturated red, saying: "It is the garb of Qarun and the dye of the Banu Umayyah." He himself wore safflower that was not intense in color.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'the messenger of allah may allah bless him and his family loved white garments above all others and would say it is the best of your clothing so wear it and shroud your dead in it no dye however renders a garment forbidden to wear the messenger of allah may allah bless him and his family and the imams of his house wore dyed cloth though they preferred certain dyes over others it is narrated from ali that he said saffron is ours and safflower yellow is for the banu umayyah jafar ibn muhammad disliked a deep heavily saturated red saying it is the garb of qarun and the dye of the banu umayyah he himself wore safflower that was not intense in color', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 15, NULL, 'It is narrated that Ali went out one day to the people of Kufa, walking from the palace to the open ground of al-Rahba. He wore a yellow waist-wrapper and a black khamisa, sandals on his feet, and in his hand an anaza — a staff upon which he leaned.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'it is narrated that ali went out one day to the people of kufa walking from the palace to the open ground of al rahba he wore a yellow waist wrapper and a black khamisa sandals on his feet and in his hand an anaza a staff upon which he leaned', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 16, NULL, 'It is narrated of Jafar ibn Muhammad that he entered ihram in a green cloak, and of Ali ibn al-Husayn that he was seen wearing a black overgarment with a blue border. Yet the Imams (عَلَيْهِمُ السَّلَامُ) disliked black as adornment, because the Banu al-Abbas had adopted it as their garb and claimed to wear it in grief for al-Husayn ibn Ali. Had there been any merit in that claim, the duty to be first to it would have fallen on the Imams among his own descendants; and had they truly grieved for him as they claimed, they would not have treated his descendants as they did. The Imams therefore disliked adorning themselves in the garb of such people.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'it is narrated of jafar ibn muhammad that he entered ihram in a green cloak and of ali ibn al husayn that he was seen wearing a black overgarment with a blue border yet the imams عليهم السلام disliked black as adornment because the banu al abbas had adopted it as their garb and claimed to wear it in grief for al husayn ibn ali had there been any merit in that claim the duty to be first to it would have fallen on the imams among his own descendants and had they truly grieved for him as they claimed they would not have treated his descendants as they did the imams therefore disliked adorning themselves in the garb of such people', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 17, NULL, 'They saw no harm, however, in images or figures worked into garments. One of the companions of Abu Jafar Muhammad ibn Ali narrated that he entered upon him while he was seated on a carpet bearing figures, and raised the matter with him. The Master said that the sunnah regarding such a carpet is that one tread upon it. When the dislike that some people hold for living figures was mentioned before him — on the grounds that Allah, mighty and exalted, created such things — he said: "Is it not He, mighty and exalted, who created everything: the trees and the inanimate, all that is seen? Yet they portray that and see no harm in portraying it. So what is the difference between the one and the other?"', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'they saw no harm however in images or figures worked into garments one of the companions of abu jafar muhammad ibn ali narrated that he entered upon him while he was seated on a carpet bearing figures and raised the matter with him the master said that the sunnah regarding such a carpet is that one tread upon it when the dislike that some people hold for living figures was mentioned before him on the grounds that allah mighty and exalted created such things he said is it not he mighty and exalted who created everything the trees and the inanimate all that is seen yet they portray that and see no harm in portraying it so what is the difference between the one and the other', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 18, NULL, 'On Ornaments and What May Be Made of Them', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'on ornaments and what may be made of them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 19, NULL, 'The Imams of the house of the Messenger of Allah — may Allah bless him and his family — transmitted from him that he permitted women to adorn themselves with gold. When Jafar ibn Muhammad was asked about this, he said: "My father used to adorn his children and his women with gold and silver." He also said: "There is no harm in ornamenting swords and copies of the Quran with gold and silver."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'the imams of the house of the messenger of allah may allah bless him and his family transmitted from him that he permitted women to adorn themselves with gold when jafar ibn muhammad was asked about this he said my father used to adorn his children and his women with gold and silver he also said there is no harm in ornamenting swords and copies of the quran with gold and silver', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 20, NULL, 'It is narrated of Ali that he said: I heard the Messenger of Allah, may Allah bless him and his family, say: "A woman should not pray except with an earring upon her, or more" — meaning when she is able to obtain such a thing. He forbade women to leave themselves bare of ornament, and to imitate men, and he cursed those among them who did so.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'it is narrated of ali that he said i heard the messenger of allah may allah bless him and his family say a woman should not pray except with an earring upon her or more meaning when she is able to obtain such a thing he forbade women to leave themselves bare of ornament and to imitate men and he cursed those among them who did so', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 21, NULL, 'Jafar ibn Muhammad said: "It is not fitting for a woman to leave herself unadorned, even if only by hanging a necklace about her neck."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'jafar ibn muhammad said it is not fitting for a woman to leave herself unadorned even if only by hanging a necklace about her neck', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 22, NULL, 'The Messenger of Allah, may Allah bless him and his family, also forbade women, when they go out, to wear ornaments that make an audible sound. This accords with the words of Allah, mighty and exalted:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'the messenger of allah may allah bless him and his family also forbade women when they go out to wear ornaments that make an audible sound this accords with the words of allah mighty and exalted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 23, NULL, '﴿وَلَا يَضْرِبْنَ بِأَرْجُلِهِنَّ لِيُعْلَمَ مَا يُخْفِينَ مِن زِينَتِهِنَّ﴾', '', '﴿وَلَا يَضْرِبْنَ بِأَرْجُلِهِنَّ لِيُعْلَمَ مَا يُخْفِينَ مِن زِينَتِهِنَّ﴾', NULL, 24, 31, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'ولا يضربن بارجلهن ليعلم ما يخفين من زينتهن', 'ولا يضربن بارجلهن ليعلم ما يخفين من زينتهن');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 24, NULL, '"And let them not strike their feet so as to make known what they conceal of their adornment." (Al-Nur: 31)', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'and let them not strike their feet so as to make known what they conceal of their adornment al nur 31', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 25, NULL, 'It is also narrated that the Messenger of Allah, may Allah bless him and his family, forbade men from wearing a gold seal-ring. His own seal was of silver, its stone likewise silver, engraved with the words "Muhammad, the Messenger of Allah." He further forbade the wearing of iron rings and all adornment in iron, saying: "It is the ornament of the people of the Fire." It is narrated as well that he wore his ring on his right hand. The Imams followed the same practice, wearing their rings on the right hand and instructing their followers and companions to do likewise.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'it is also narrated that the messenger of allah may allah bless him and his family forbade men from wearing a gold seal ring his own seal was of silver its stone likewise silver engraved with the words muhammad the messenger of allah he further forbade the wearing of iron rings and all adornment in iron saying it is the ornament of the people of the fire it is narrated as well that he wore his ring on his right hand the imams followed the same practice wearing their rings on the right hand and instructing their followers and companions to do likewise', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 26, NULL, 'Ali narrated that he heard the Messenger of Allah, may Allah bless him and his family, say: "Whoever sets a ring with a stone of red carnelian, Allah seals his affair with what is good." The Prophet recommended it, and the ruby as well, and would say: "Each time a man looks into it, light increases upon his face, and the prayer wearing it is worth seventy prayers." He also said: "How excellent a stone is crystal." The engraving on Ali''s seal read "Ali believes in Allah." Jafar ibn Muhammad forbade the setting of a ring whose stone bears an engraved figure, and the engraving on his own seal read "My Lord, You are my trust, so protect me from the evil of Your creation." It is further narrated that the Messenger of Allah, may Allah bless him and his family, used to turn his ring so that the stone lay against the inside of his palm.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'ali narrated that he heard the messenger of allah may allah bless him and his family say whoever sets a ring with a stone of red carnelian allah seals his affair with what is good the prophet recommended it and the ruby as well and would say each time a man looks into it light increases upon his face and the prayer wearing it is worth seventy prayers he also said how excellent a stone is crystal the engraving on alis seal read ali believes in allah jafar ibn muhammad forbade the setting of a ring whose stone bears an engraved figure and the engraving on his own seal read my lord you are my trust so protect me from the evil of your creation it is further narrated that the messenger of allah may allah bless him and his family used to turn his ring so that the stone lay against the inside of his palm', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 27, NULL, 'On Fragrance, Its Excellence, and Its Recommendation', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'on fragrance its excellence and its recommendation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 28, NULL, 'From the Imams of the house of the Messenger of Allah, may Allah bless him and his family, it is narrated through Ali that he said: "Three things were given to the prophets: fragrance, marriage, and the siwak." When the Prophet, may Allah bless him and his family, traveled, he carried certain things with him:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'from the imams of the house of the messenger of allah may allah bless him and his family it is narrated through ali that he said three things were given to the prophets fragrance marriage and the siwak when the prophet may allah bless him and his family traveled he carried certain things with him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 29, NULL, 'the flask the shears the kohl-vessel the mirror the comb the siwak', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'the flask the shears the kohl vessel the mirror the comb the siwak', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 30, NULL, 'He said, may Allah bless him and his family: "No servant''s garment is cleansed but that his faults are lessened, and his scent is not made sweet but that his understanding is increased."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'he said may allah bless him and his family no servants garment is cleansed but that his faults are lessened and his scent is not made sweet but that his understanding is increased', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 31, NULL, 'Jafar ibn Muhammad said: "A sweet fragrance strengthens the heart and increases vigor. The fragrance of men is that whose scent is apparent and whose color is hidden, and the fragrance of women is that whose color is apparent and whose scent is concealed — except when they go out, for then it is disliked that they perfume themselves so that it can be detected from them."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'jafar ibn muhammad said a sweet fragrance strengthens the heart and increases vigor the fragrance of men is that whose scent is apparent and whose color is hidden and the fragrance of women is that whose color is apparent and whose scent is concealed except when they go out for then it is disliked that they perfume themselves so that it can be detected from them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 32, NULL, 'It is narrated of Ali that he said: the Messenger of Allah, may Allah bless him and his family, used to apply fragrance, and to apply it abundantly, until it would change the color of his hair. And he said, may Allah bless him and his family: "Whoever goes to the Friday prayer, let him apply perfume, even if only from his family''s flask."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'it is narrated of ali that he said the messenger of allah may allah bless him and his family used to apply fragrance and to apply it abundantly until it would change the color of his hair and he said may allah bless him and his family whoever goes to the friday prayer let him apply perfume even if only from his familys flask', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 33, NULL, 'It is also narrated of Ali that he would sometimes perfume himself from the fragrance of his wives — by which is meant the kind of women''s fragrance whose color does not show, only its scent. As for fragrance that shows its color, such as khaluq and the like, it is disliked for men except in the company of their wives.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'it is also narrated of ali that he would sometimes perfume himself from the fragrance of his wives by which is meant the kind of womens fragrance whose color does not show only its scent as for fragrance that shows its color such as khaluq and the like it is disliked for men except in the company of their wives', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 34, NULL, 'The Imams disliked that one return a gift of fragrance to the one who offered it, and likewise that one refuse an offering of water.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'the imams disliked that one return a gift of fragrance to the one who offered it and likewise that one refuse an offering of water', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 35, NULL, 'Al-Muizz (ع) said: Al-Mansur, may Allah sanctify his soul, told him: One day, when he was a small boy, he was present at the table of al-Mahdi (ع). A company of al-Mahdi''s sons and grandsons were eating before him, with a serving-girl standing by with water. She offered water to one of the boys, who refused it, and al-Mahdi rebuked her sharply and said: "Were it not for the sanctity of your sharing in this food, I would have disciplined you well. What moved you to offer him water when he had not asked for it?" Then he turned to the boy and said: "And you — when it was offered to you, why did you refuse it? Water is too noble a thing to be offered to one who did not ask, or to be refused by one to whom it is offered."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'al muizz ع said al mansur may allah sanctify his soul told him one day when he was a small boy he was present at the table of al mahdi ع a company of al mahdis sons and grandsons were eating before him with a serving girl standing by with water she offered water to one of the boys who refused it and al mahdi rebuked her sharply and said were it not for the sanctity of your sharing in this food i would have disciplined you well what moved you to offer him water when he had not asked for it then he turned to the boy and said and you when it was offered to you why did you refuse it water is too noble a thing to be offered to one who did not ask or to be refused by one to whom it is offered', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 36, NULL, 'Al-Mansur (ع) said: "I did not understand at the time what manner of thing this was, but when I came to understand, I grasped his meaning. And so it is with fragrance as well."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'al mansur ع said i did not understand at the time what manner of thing this was but when i came to understand i grasped his meaning and so it is with fragrance as well', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 37, NULL, 'From Ali it is narrated that the Messenger of Allah, may Allah bless him and his family, used to anoint himself with musk, المسك. He held it in such regard that he directed it be placed in his embalming, his حنوط, so that its fragrance would remain with him — and something finer than it was also used over him in that embalming.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'from ali it is narrated that the messenger of allah may allah bless him and his family used to anoint himself with musk المسك he held it in such regard that he directed it be placed in his embalming his حنوط so that its fragrance would remain with him and something finer than it was also used over him in that embalming', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 38, NULL, 'It is further narrated, on the authority of the Imams, that the Messenger of Allah, may Allah bless him and his family, forbade a woman to pray unless she has applied henna, الحناء, or has at least touched the place of the henna with something.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'it is further narrated on the authority of the imams that the messenger of allah may allah bless him and his family forbade a woman to pray unless she has applied henna الحناء or has at least touched the place of the henna with something', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 39, NULL, 'Abu Jafar Muhammad ibn Ali said that a woman should therefore not leave off the dye, الخضاب, even when she has grown old — even if she does no more than wipe her hand with henna as a light anointing. She should not make herself resemble men.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'abu jafar muhammad ibn ali said that a woman should therefore not leave off the dye الخضاب even when she has grown old even if she does no more than wipe her hand with henna as a light anointing she should not make herself resemble men', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 40, NULL, 'From Ali it is narrated that the Messenger of Allah, may Allah bless him and his family, said: "It is not for a menstruating woman to tell a story or to engrave."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'from ali it is narrated that the messenger of allah may allah bless him and his family said it is not for a menstruating woman to tell a story or to engrave', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'what we wear: dress, adornment, and fragrance', '4. What We Wear: Dress, Adornment, and Fragrance', 41, NULL, 'And from Ali: "The Children of Israel perished through stories, engravings, henna, and excessive ornamentation."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 4 what we wear dress adornment and fragrance', 'and from ali the children of israel perished through stories engravings henna and excessive ornamentation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 1, NULL, 'Al-Ma''idah: 96أُحِلَّ لَكُمْ صَيْدُ ٱلْبَحْرِ وَطَعَامُهُۥ مَتَعًۭا لَّكُمْ وَلِلسَّيَّارَةِ ۖ وَحُرِّمَ عَلَيْكُمْ صَيْدُ ٱلْبَرِّ مَا دُمْتُمْ حُرُمًۭا', '', 'أُحِلَّ لَكُمْ صَيْدُ ٱلْبَحْرِ وَطَعَامُهُۥ مَتَعًۭا لَّكُمْ وَلِلسَّيَّارَةِ ۖ وَحُرِّمَ عَلَيْكُمْ صَيْدُ ٱلْبَرِّ مَا دُمْتُمْ حُرُمًۭا', 'Al-Ma''idah: 96', 5, 96, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'al maidah 96احل لكم صيد البحر وطعامه متعا لكم وللسياره وحرم عليكم صيد البر ما دمتم حرما', 'احل لكم صيد البحر وطعامه متعا لكم وللسياره وحرم عليكم صيد البر ما دمتم حرما');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 2, NULL, '﴿أُحِلَّ لَكُمْ صَيْدُ الْبَحْرِ وَطَعَامُهُ مَتَاعًا لَكُمْ وَلِلسَّيَّارَةِ وَحُرِّمَ عَلَيْكُمْ صَيْدُ الْبَرِّ مَا دُمْتُمْ حُرُمًا﴾ "He has made permissible for you the hunting of the sea and its food, as a pleasure for you and for travelers, and forbidden for you is the hunting of land as long as you are in the sacred state" (al-Maidah: 96), and He said: ﴿وَإِذَا حَلَلْتُمْ فَاصْطَادُوا﴾ "But when you leave the sacred state, then hunt" (al-Maidah: 2). The Almighty thus permitted sea hunting even while one remains in the state of consecration, and forbade land hunting for the duration of it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'احل لكم صيد البحر وطعامه متاعا لكم وللسياره وحرم عليكم صيد البر ما دمتم حرما he has made permissible for you the hunting of the sea and its food as a pleasure for you and for travelers and forbidden for you is the hunting of land as long as you are in the sacred state al maidah 96 and he said واذا حللتم فاصطادوا but when you leave the sacred state then hunt al maidah 2 the almighty thus permitted sea hunting even while one remains in the state of consecration and forbade land hunting for the duration of it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 3, NULL, 'He addressed this to the generality of the believers, except for what was excluded from it on the tongue of His Messenger and the Imams of his household, who make plain what He intends, as He says: ﴿وَأَنزَلْنَا إِلَيْكَ الذِّكْرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ﴾ "And We have sent down to you the Remembrance that you may make clear to the people what has been revealed to them" (al-Nahl: 44).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'he addressed this to the generality of the believers except for what was excluded from it on the tongue of his messenger and the imams of his household who make plain what he intends as he says وانزلنا اليك الذكر لتبين للناس ما نزل اليهم and we have sent down to you the remembrance that you may make clear to the people what has been revealed to them al nahl 44', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 4, NULL, 'The Imams of the household of the Messenger of Allah, may Allah bless him and his family and grant them peace, are reported to have forbidden the hunting of birds in their nests. He said: "The bird in its nest is under the protection of Allah; but if it takes to the air upon its wings, then hunt it if you wish. Set a trap for it and shoot at it." It is further narrated from him, and from Ali (ع), and from Jafar ibn Muhammad (عَلَيْهِمُ السَّلَامُ), that pigeons in towns should not be hunted, because they belong to their owners even when they fly free. What is lawful and what is forbidden among the beasts of land and sea has already been treated in the chapters on food. Whatever is caught of what is lawful to eat is eaten; whatever is caught of what is forbidden to eat is left and not eaten, except in a case of dire necessity for one who is compelled.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'the imams of the household of the messenger of allah may allah bless him and his family and grant them peace are reported to have forbidden the hunting of birds in their nests he said the bird in its nest is under the protection of allah but if it takes to the air upon its wings then hunt it if you wish set a trap for it and shoot at it it is further narrated from him and from ali ع and from jafar ibn muhammad عليهم السلام that pigeons in towns should not be hunted because they belong to their owners even when they fly free what is lawful and what is forbidden among the beasts of land and sea has already been treated in the chapters on food whatever is caught of what is lawful to eat is eaten whatever is caught of what is forbidden to eat is left and not eaten except in a case of dire necessity for one who is compelled', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 6, NULL, 'Al-Ma''idah: 4عَلَيْهِ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ', '', 'عَلَيْهِ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ', 'Al-Ma''idah: 4', 5, 4, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'al maidah 4عليه واتقوا الله ان الله', 'عليه واتقوا الله ان الله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 7, NULL, '﴿يَسْأَلُونَكَ مَاذَا أُحِلَّ لَهُمْ قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ وَمَا عَلَّمْتُم مِّنَ الْجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ اللَّهُ فَكُلُوا مِمَّا أَمْسَكْنَ عَلَيْكُمْ وَاذْكُرُوا اسْمَ اللَّهِ عَلَيْهِ وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ سَرِيعُ الْحِسَابِ﴾ "They ask you what has been made lawful for them.', '', '﴿يَسْأَلُونَكَ مَاذَا أُحِلَّ لَهُمْ قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ وَمَا عَلَّمْتُم مِّنَ الْجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ اللَّهُ فَكُلُوا مِمَّا أَمْسَكْنَ عَلَيْكُمْ وَاذْكُرُوا اسْمَ اللَّهِ عَلَيْهِ وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ سَرِيعُ الْحِسَابِ﴾', NULL, 5, 4, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'يسالونك ماذا احل لهم قل احل لكم الطيبات وما علمتم من الجوارح مكلبين تعلمونهن مما علمكم الله فكلوا مما امسكن عليكم واذكروا اسم الله عليه واتقوا الله ان الله سريع الحساب they ask you what has been made lawful for them', 'يسالونك ماذا احل لهم قل احل لكم الطيبات وما علمتم من الجوارح مكلبين تعلمونهن مما علمكم الله فكلوا مما امسكن عليكم واذكروا اسم الله عليه واتقوا الله ان الله سريع الحساب');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 8, NULL, 'Say: Lawful for you are all good things, and what you have trained of hunting animals, training them as Allah has taught you, so eat of what they have caught for you, and mention the name of Allah over it, and fear Allah. Indeed, Allah is swift in reckoning" (al-Maidah: 4).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'say lawful for you are all good things and what you have trained of hunting animals training them as allah has taught you so eat of what they have caught for you and mention the name of allah over it and fear allah indeed allah is swift in reckoning al maidah 4', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 9, NULL, 'The Imams of the household of the Messenger of Allah — may Allah bless him and his family and grant them peace — transmitted from Ali, upon him be peace, that he said: if a hunting animal seizes prey and the prey dies before slaughter can be performed, then provided the animal is trained and a Muslim sent it forth and invoked the name of Allah at the moment of release, the prey may be eaten. If he forgot to invoke the name at the moment of release, he invokes it when he remembers. If he deliberately omitted it, however, the prey is not to be eaten.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'the imams of the household of the messenger of allah may allah bless him and his family and grant them peace transmitted from ali upon him be peace that he said if a hunting animal seizes prey and the prey dies before slaughter can be performed then provided the animal is trained and a muslim sent it forth and invoked the name of allah at the moment of release the prey may be eaten if he forgot to invoke the name at the moment of release he invokes it when he remembers if he deliberately omitted it however the prey is not to be eaten', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 10, NULL, 'The word الجوارح, in the Arabic tongue in which the Quran was revealed, means the earners. The Arabs say, "So-and-so is the جارحة of his household," meaning the one who earns for them. Dogs and their like, and the birds of prey used in hunting, are earners that earn the catch for those who have trained them. If such an animal is untrained yet seizes prey, and the prey is reached while still alive and then slaughtered, it may be eaten; but if slaughter cannot be reached in time, it may not be eaten. They — (عَلَيْهِمُ السَّلَامُ) — held that whatever trained hunting animals seize may be eaten, even if slaughter was not reached, and even if the animal has eaten from it. Every trained hunting creature, such as cheetahs and other land predators, as well as birds of prey, may have its catch eaten.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'the word الجوارح in the arabic tongue in which the quran was revealed means the earners the arabs say so and so is the جارحه of his household meaning the one who earns for them dogs and their like and the birds of prey used in hunting are earners that earn the catch for those who have trained them if such an animal is untrained yet seizes prey and the prey is reached while still alive and then slaughtered it may be eaten but if slaughter cannot be reached in time it may not be eaten they عليهم السلام held that whatever trained hunting animals seize may be eaten even if slaughter was not reached and even if the animal has eaten from it every trained hunting creature such as cheetahs and other land predators as well as birds of prey may have its catch eaten', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 11, NULL, 'It is narrated from the Messenger of Allah, may Allah bless him and his family and grant them peace, that concerning the hunting of the black dog, he disliked it for them and ordered that it be killed. They further held that all dogs are equal in their ruling, apart from this distinction, whether of the Kurdish kind or the greyhound kind: what they seize may be eaten when they are trained. They held as well that if the prey is reached while still alive and the hunting animal has wounded it, but the hunter does not then slaughter it and it dies in his hands from the wound the hunting animal inflicted, it may be eaten. If, however, the hunting animal did not wound it, and it was carried off and died afterward, it may not be eaten.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'it is narrated from the messenger of allah may allah bless him and his family and grant them peace that concerning the hunting of the black dog he disliked it for them and ordered that it be killed they further held that all dogs are equal in their ruling apart from this distinction whether of the kurdish kind or the greyhound kind what they seize may be eaten when they are trained they held as well that if the prey is reached while still alive and the hunting animal has wounded it but the hunter does not then slaughter it and it dies in his hands from the wound the hunting animal inflicted it may be eaten if however the hunting animal did not wound it and it was carried off and died afterward it may not be eaten', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 12, NULL, 'From Ali comes a prohibition on eating any game that dies before slaughter can be reached — whether taken by the dogs of the Magians, by the Arabs who are Christians, or by any hunting animal they have trained — unless Muslims afterward retrain those animals.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'from ali comes a prohibition on eating any game that dies before slaughter can be reached whether taken by the dogs of the magians by the arabs who are christians or by any hunting animal they have trained unless muslims afterward retrain those animals', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 14, NULL, 'Al-Baqarah: 178ٱعْتَدَىٰ بَعْدَ ذَلِكَ فَلَهُۥ عَذَابٌ أَلِيمٌۭ', '', 'ٱعْتَدَىٰ بَعْدَ ذَلِكَ فَلَهُۥ عَذَابٌ أَلِيمٌۭ', 'Al-Baqarah: 178', 2, 178, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'al baqarah 178اعتدي بعد ذلك فله عذاب اليم', 'اعتدي بعد ذلك فله عذاب اليم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 15, NULL, '﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَيَبْلُوَنَّكُمُ اللَّهُ بِشَيْءٍ مِّنَ الصَّيْدِ تَنَالُهُ أَيْدِيكُمْ وَرِمَاحُكُمْ لِيَعْلَمَ اللَّهُ مَن يَخَافُهُ بِالْغَيْبِ فَمَنِ اعْتَدَى بَعْدَ ذَلِكَ فَلَهُ عَذَابٌ أَلِيمٌ﴾ "O you who believe, Allah will surely test you with something of the game that your hands and your spears can reach, that Allah may know who fears Him in the unseen. So whoever transgresses after that, for him is a painful punishment" (al-Maidah: 94).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'يا ايها الذين امنوا ليبلونكم الله بشيء من الصيد تناله ايديكم ورماحكم ليعلم الله من يخافه بالغيب فمن اعتدي بعد ذلك فله عذاب اليم o you who believe allah will surely test you with something of the game that your hands and your spears can reach that allah may know who fears him in the unseen so whoever transgresses after that for him is a painful punishment al maidah 94', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 16, NULL, 'One of the Imams of the household of the Messenger of Allah ﷺ was asked by a man about hunting — specifically, about throwing at prey, striking it, and having it die. The Imam said: "Eat what you have killed outright (al-isma), and do not eat what you have driven off (al-inma)."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'one of the imams of the household of the messenger of allah ﷺ was asked by a man about hunting specifically about throwing at prey striking it and having it die the imam said eat what you have killed outright al isma and do not eat what you have driven off al inma', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 17, NULL, 'Al-isma is when a man throws at quarry, strikes it, and it dies on the spot. Al-inma is when he strikes it and it moves off, passing out of his sight until it is hidden from him and disappears, and then it dies and he finds it dead — with no way of knowing whether it died from his blow or from something else.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'al isma is when a man throws at quarry strikes it and it dies on the spot al inma is when he strikes it and it moves off passing out of his sight until it is hidden from him and disappears and then it dies and he finds it dead with no way of knowing whether it died from his blow or from something else', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 18, NULL, 'It has been narrated from Jafar ibn Muhammad that he said: if a hunter shoots game with an arrow, strikes it in a fatal spot, and it then disappears from him, yet he later finds his arrow in it and knows from that it died from his shot, he may eat it. If he does not know that, he may not eat it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'it has been narrated from jafar ibn muhammad that he said if a hunter shoots game with an arrow strikes it in a fatal spot and it then disappears from him yet he later finds his arrow in it and knows from that it died from his shot he may eat it if he does not know that he may not eat it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 19, NULL, 'From Ali it has been narrated that he said: if a hunter shoots game, strikes it, and it then falls from a height or falls into water and dies, he may not eat it — unless he knows with certainty that it died from the blow that struck it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'from ali it has been narrated that he said if a hunter shoots game strikes it and it then falls from a height or falls into water and dies he may not eat it unless he knows with certainty that it died from the blow that struck it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 20, NULL, 'Whatever has been mentioned of game struck or killed by a projectile is lawful to eat only when it has been struck with a sword, a spear, an arrow, or an iron implement. Anything struck with a stick, a stone, or a pellet may not be eaten — according to the position of the people of the household — unless it is reached while still alive and properly slaughtered. They permitted the مِعْراض when a hunter has no other arrow: the مِعْراض is a featherless arrow thrown so that it strikes game with its body. From Ali it has been narrated that he said: whatever a snare takes of game, if it dies in the snare before being slaughtered, may not be eaten. But if the snare severs a hand, a leg, or a limb, and the animal is then reached and slaughtered while still alive, it may be eaten — except for the severed limb itself. The الحبالة is any device set up to take game, such as nets, traps, and the like.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'whatever has been mentioned of game struck or killed by a projectile is lawful to eat only when it has been struck with a sword a spear an arrow or an iron implement anything struck with a stick a stone or a pellet may not be eaten according to the position of the people of the household unless it is reached while still alive and properly slaughtered they permitted the معراض when a hunter has no other arrow the معراض is a featherless arrow thrown so that it strikes game with its body from ali it has been narrated that he said whatever a snare takes of game if it dies in the snare before being slaughtered may not be eaten but if the snare severs a hand a leg or a limb and the animal is then reached and slaughtered while still alive it may be eaten except for the severed limb itself the الحباله is any device set up to take game such as nets traps and the like', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 23, NULL, 'It has been narrated from the Imams of the household of the Messenger of Allah, may Allah bless him and his family and grant them peace, that they transmitted from him that he said: "Whoever slaughters an animal, let him sharpen his blade and let him give his animal ease."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'it has been narrated from the imams of the household of the messenger of allah may allah bless him and his family and grant them peace that they transmitted from him that he said whoever slaughters an animal let him sharpen his blade and let him give his animal ease', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 24, NULL, 'Abu Jafar Muhammad ibn Ali, (ع), said: "When you intend to slaughter an animal, do not torment the beast. Sharpen the blade, face the qiblah, and invoke the name of Allah, and do not sever it through until it dies — meaning do not cut off its head." He likewise forbade that an animal be skinned until it has died and grown still.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'abu jafar muhammad ibn ali ع said when you intend to slaughter an animal do not torment the beast sharpen the blade face the qiblah and invoke the name of allah and do not sever it through until it dies meaning do not cut off its head he likewise forbade that an animal be skinned until it has died and grown still', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 25, NULL, 'On the matter of the invocation, the teaching is as follows: whoever slaughters and forgets to invoke the name of Allah, or forgets to face the animal toward the qiblah, or is simply unaware of the requirement, should invoke the name of Allah the Almighty when he remembers, and the slaughtered animal may be eaten. But if he deliberately omits it, the slaughter is not permissible to eat. If he says "There is no god but Allah," or "Allah is the Greatest," or remembers Allah the Almighty by whatever words he uses, that suffices in place of the full invocation. What the Imams recommended to say at the moment of slaughter is: "In the name of Allah, and Allah is the Greatest."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'on the matter of the invocation the teaching is as follows whoever slaughters and forgets to invoke the name of allah or forgets to face the animal toward the qiblah or is simply unaware of the requirement should invoke the name of allah the almighty when he remembers and the slaughtered animal may be eaten but if he deliberately omits it the slaughter is not permissible to eat if he says there is no god but allah or allah is the greatest or remembers allah the almighty by whatever words he uses that suffices in place of the full invocation what the imams recommended to say at the moment of slaughter is in the name of allah and allah is the greatest', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 26, NULL, 'It is also narrated from the Messenger of Allah, may Allah bless him and his family and grant them peace, that he forbade mutilating beasts and commanded that they be slaughtered as is their due. He further forbade المجثمة and الْمَصْبُورَةُ — that is, an animal that is held captive, or buried, or tied in place and then shot at until it dies.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'it is also narrated from the messenger of allah may allah bless him and his family and grant them peace that he forbade mutilating beasts and commanded that they be slaughtered as is their due he further forbade المجثمه and المصبوره that is an animal that is held captive or buried or tied in place and then shot at until it dies', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 27, NULL, 'Abu Jafar Muhammad ibn Ali said: "Whoever kills a sparrow without cause, Allah the Almighty will bring it before him on the Day of Resurrection, and it will cry out: My Lord, ask this one why he killed me without slaughter."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'abu jafar muhammad ibn ali said whoever kills a sparrow without cause allah the almighty will bring it before him on the day of resurrection and it will cry out my lord ask this one why he killed me without slaughter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 28, NULL, 'Mutilation, then, is a grave matter.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'mutilation then is a grave matter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 29, NULL, 'The Master said: Slaughter belongs at the place of slaughter — that is, below the غلصمة. The غلصمة is the knot in the windpipe, and it is to be left in the head. The slaughterer cuts the windpipe, the gullet, and the two jugular veins, falling short of none of these, and without cutting into the bone. That is the Sunnah of slaughter. Abu Jafar Muhammad ibn Ali — and upon his family — was asked about breaking an animal''s neck before it dies, and he disapproved of it. It was said: if the knife outruns the slaughterer, or if out of ignorance he cuts off the animal''s head without intending it and without knowing that this is not permitted, there is nothing against him and the animal may be eaten. But if he does so deliberately, he has done wrong, and the animal is not to be eaten.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'the master said slaughter belongs at the place of slaughter that is below the غلصمه the غلصمه is the knot in the windpipe and it is to be left in the head the slaughterer cuts the windpipe the gullet and the two jugular veins falling short of none of these and without cutting into the bone that is the sunnah of slaughter abu jafar muhammad ibn ali and upon his family was asked about breaking an animals neck before it dies and he disapproved of it it was said if the knife outruns the slaughterer or if out of ignorance he cuts off the animals head without intending it and without knowing that this is not permitted there is nothing against him and the animal may be eaten but if he does so deliberately he has done wrong and the animal is not to be eaten', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 30, NULL, 'It was further said: if the beast bolts — that is, flees or refuses — so that it cannot be slaughtered, or if it falls into a well and cannot be lifted out, nor can one reach the place of slaughter, then let it be stabbed with a spear, struck with a sword, or struck with an iron implement until it dies, and it may be eaten. It was said: there is no valid slaughter except with iron. One may not slaughter with a stone, nor a tooth, nor a nail, nor a bone, nor anything else — only with iron.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'it was further said if the beast bolts that is flees or refuses so that it cannot be slaughtered or if it falls into a well and cannot be lifted out nor can one reach the place of slaughter then let it be stabbed with a spear struck with a sword or struck with an iron implement until it dies and it may be eaten it was said there is no valid slaughter except with iron one may not slaughter with a stone nor a tooth nor a nail nor a bone nor anything else only with iron', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 32, NULL, 'The Imams of the household of the Messenger of Allah — may Allah bless him and his family and grant them peace — are reported to have disliked the slaughter of a milk-giving animal or a pregnant one, though they did not forbid it outright. The dislike arose from the benefit such animals hold for one who has nothing else.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'the imams of the household of the messenger of allah may allah bless him and his family and grant them peace are reported to have disliked the slaughter of a milk giving animal or a pregnant one though they did not forbid it outright the dislike arose from the benefit such animals hold for one who has nothing else', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 33, NULL, 'Al-An''am: 118فَكُلُوا۟ مِمَّا ذُكِرَ ٱسْمُ ٱللَّهِ عَلَيْهِ إِن', '', 'فَكُلُوا۟ مِمَّا ذُكِرَ ٱسْمُ ٱللَّهِ عَلَيْهِ إِن', 'Al-An''am: 118', 6, 118, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'al anam 118فكلوا مما ذكر اسم الله عليه ان', 'فكلوا مما ذكر اسم الله عليه ان');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 34, NULL, 'Abu Jafar Muhammad ibn Ali was asked about the slaughtered animals of the Jews, the Christians, the Magians, and those of divergent belief. In reply, he recited the word of Allah the Almighty: ﴿فَكُلُوا مِمَّا ذُكِرَ اسْمُ اللَّهِ عَلَيْهِ إِن كُنتُم بِآيَاتِهِ مُؤْمِنِينَ﴾ — "So eat of that over which the name of Allah has been mentioned, if you are believers in His signs" (al-Anam: 118). He then said: "When you hear them invoking the name of Allah, then eat; and what they do not invoke the name of Allah over, do not eat. And if any among them is suspected of omitting the invocation, believing it permissible to do so, his slaughtered animal need not be eaten — unless one is present at the moment of slaughter and hears him invoke the name of Allah the Almighty over it."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'abu jafar muhammad ibn ali was asked about the slaughtered animals of the jews the christians the magians and those of divergent belief in reply he recited the word of allah the almighty فكلوا مما ذكر اسم الله عليه ان كنتم باياته مومنين so eat of that over which the name of allah has been mentioned if you are believers in his signs al anam 118 he then said when you hear them invoking the name of allah then eat and what they do not invoke the name of allah over do not eat and if any among them is suspected of omitting the invocation believing it permissible to do so his slaughtered animal need not be eaten unless one is present at the moment of slaughter and hears him invoke the name of allah the almighty over it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 35, NULL, 'Jafar ibn Muhammad said: "There is no harm in meat sold in the markets of the Muslims, so long as it is not known of the slaughterers that they depart from the Sunnah in their slaughter, and so long as no such departure has been witnessed in their practice."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'jafar ibn muhammad said there is no harm in meat sold in the markets of the muslims so long as it is not known of the slaughterers that they depart from the sunnah in their slaughter and so long as no such departure has been witnessed in their practice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 36, NULL, 'The scholars of this tradition held a dislike for slaughtered animals offered by Magians and by Arab Christians. They permitted slaughter performed by a blind man, provided he is directed toward the qiblah and slaughters correctly; likewise by a woman, when she does so correctly; and by a boy who has not yet reached maturity, when he does so correctly and there is genuine need of him. They saw no harm in slaughter performed without ritual purity. They also permitted slaughter by a mute person, provided he understands the invocation and signals it by gesture.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'the scholars of this tradition held a dislike for slaughtered animals offered by magians and by arab christians they permitted slaughter performed by a blind man provided he is directed toward the qiblah and slaughters correctly likewise by a woman when she does so correctly and by a boy who has not yet reached maturity when he does so correctly and there is genuine need of him they saw no harm in slaughter performed without ritual purity they also permitted slaughter by a mute person provided he understands the invocation and signals it by gesture', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 38, NULL, 'From the Imams of the household of the Messenger of Allah, may Allah bless him and his family and grant them peace, it is transmitted that Ali was asked about the fetuses of livestock whose mothers are slaughtered while the fetuses remain in the womb — whether they become lawful when brought out. He said: "Their slaughter is the slaughter of their mothers, for the fetus is one of her limbs. But if it comes out alive, it is left until it dies, and then it may be eaten, provided it has grown hair or fur — or has something of that upon it, even on its tail, for the tail is the first place where hair appears." He disliked any fetus that had not yet grown hair or fur.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'from the imams of the household of the messenger of allah may allah bless him and his family and grant them peace it is transmitted that ali was asked about the fetuses of livestock whose mothers are slaughtered while the fetuses remain in the womb whether they become lawful when brought out he said their slaughter is the slaughter of their mothers for the fetus is one of her limbs but if it comes out alive it is left until it dies and then it may be eaten provided it has grown hair or fur or has something of that upon it even on its tail for the tail is the first place where hair appears he disliked any fetus that had not yet grown hair or fur', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 39, NULL, 'He was then asked about limbs cut from a living animal — the fatty tails of sheep, the humps of camels, and the like. He said: "Whatever is cut from them and separated while they are still alive, before slaughter, is carrion and may not be eaten — and the rest of the animal may not be eaten when it is slaughtered."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'he was then asked about limbs cut from a living animal the fatty tails of sheep the humps of camels and the like he said whatever is cut from them and separated while they are still alive before slaughter is carrion and may not be eaten and the rest of the animal may not be eaten when it is slaughtered', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 40, NULL, 'He also said that valid slaughter is recognized by four signs:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'he also said that valid slaughter is recognized by four signs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 41, NULL, 'the eye flickering the leg kicking the tail moving the ear stirring', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'the eye flickering the leg kicking the tail moving the ear stirring', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 42, NULL, 'Any animal that moves, thrashes, flickers its eye, or shows any motion after the knife has been drawn across it has been validly slaughtered. An animal that falls and is slaughtered without any movement at all may not be eaten, even if blood flows from it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'any animal that moves thrashes flickers its eye or shows any motion after the knife has been drawn across it has been validly slaughtered an animal that falls and is slaughtered without any movement at all may not be eaten even if blood flows from it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 43, NULL, 'The Master was asked about an animal that is properly slaughtered and then falls from a height or into water and dies. He said: "If you have done the slaughter well and fulfilled what is required of it, then eat."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'the master was asked about an animal that is properly slaughtered and then falls from a height or into water and dies he said if you have done the slaughter well and fulfilled what is required of it then eat', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 44, NULL, 'From Jafar ibn Muhammad: the Sunnah for large animals is that they be sacrificed standing, with one leg bound. The Messenger of Allah, may Allah bless him and his family and grant them peace, sacrificed his gift-offering in that manner. If that is not possible, there is no harm in the animal kneeling and being hobbled. He disliked that the sheep be slaughtered standing, except when there is a reason, and held the Sunnah to be that it is laid on its side. If a sheep is sacrificed in the manner of large animals, however, there is no harm in that either.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'from jafar ibn muhammad the sunnah for large animals is that they be sacrificed standing with one leg bound the messenger of allah may allah bless him and his family and grant them peace sacrificed his gift offering in that manner if that is not possible there is no harm in the animal kneeling and being hobbled he disliked that the sheep be slaughtered standing except when there is a reason and held the sunnah to be that it is laid on its side if a sheep is sacrificed in the manner of large animals however there is no harm in that either', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 45, NULL, 'He was asked about an animal slaughtered from behind the nape of the neck. He said that if the slaughterer was unaware, there is no harm; but if he did so intentionally, knowing the Sunnah, the animal may not be eaten and he is to be corrected.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'he was asked about an animal slaughtered from behind the nape of the neck he said that if the slaughterer was unaware there is no harm but if he did so intentionally knowing the sunnah the animal may not be eaten and he is to be corrected', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 46, NULL, 'He was asked about two sheep — one validly slaughtered and the other not — when it is unknown which of the two was valid. He said that neither is to be eaten until the valid one is identified.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'he was asked about two sheep one validly slaughtered and the other not when it is unknown which of the two was valid he said that neither is to be eaten until the valid one is identified', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 48, NULL, 'The Imams of the household of the Messenger of Allah, may Allah bless him and his family, transmitted — and the Messenger himself transmitted — that he addressed the people before the Day of Sacrifice and said: "O people, whoever has the means, let him sacrifice and let him magnify the rites of Allah. And whoever does not have the means, then Allah the Almighty does not burden a soul beyond its capacity."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'the imams of the household of the messenger of allah may allah bless him and his family transmitted and the messenger himself transmitted that he addressed the people before the day of sacrifice and said o people whoever has the means let him sacrifice and let him magnify the rites of allah and whoever does not have the means then allah the almighty does not burden a soul beyond its capacity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 49, NULL, 'A man of the Ansar met the Messenger of Allah, may Allah bless him and his family and grant them peace, on the Day of Sacrifice, after the prayer had concluded, and said: "O Messenger of Allah, if you would honor me with your presence today — I have prepared food for you." The Messenger of Allah, may Allah bless him and his family and grant them peace, went with him. The man brought out the food and said: "O Messenger of Allah, I slaughtered my sacrifice before going out to the place of prayer, and I instructed my family to prepare this meal, so that I might be the first to bring it to you." The Messenger of Allah, may Allah bless him and his family and grant them peace, said to him: "Your sheep is a sheep of meat. If you have another, sacrifice that one in its place." The man said: "I have nothing but a young goat of mine." He said: "Then sacrifice it — though this will not be lawful for anyone who comes after you."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'a man of the ansar met the messenger of allah may allah bless him and his family and grant them peace on the day of sacrifice after the prayer had concluded and said o messenger of allah if you would honor me with your presence today i have prepared food for you the messenger of allah may allah bless him and his family and grant them peace went with him the man brought out the food and said o messenger of allah i slaughtered my sacrifice before going out to the place of prayer and i instructed my family to prepare this meal so that i might be the first to bring it to you the messenger of allah may allah bless him and his family and grant them peace said to him your sheep is a sheep of meat if you have another sacrifice that one in its place the man said i have nothing but a young goat of mine he said then sacrifice it though this will not be lawful for anyone who comes after you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 50, NULL, 'The Sunnah holds that the sacrifice is not slaughtered until after the Eid prayer on the Day of Sacrifice. Whoever slaughters before the prayer, that act does not count as a valid sacrifice, and he must repeat it when he is able. The best time to slaughter is the Day of Sacrifice itself, though the sacrifice remains valid throughout the days of Mina — the Day of Sacrifice and the three days that follow it. Jafar ibn Muhammad said that among camels and cattle, nothing suffices as a sacrifice except the mature animal, and the same applies to goats; the yearling of sheep, however, suffices. He also said that the sacrifice is an obligation upon every Muslim who has the means, and that a single sacrifice on a man''s part suffices for his entire household.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'the sunnah holds that the sacrifice is not slaughtered until after the eid prayer on the day of sacrifice whoever slaughters before the prayer that act does not count as a valid sacrifice and he must repeat it when he is able the best time to slaughter is the day of sacrifice itself though the sacrifice remains valid throughout the days of mina the day of sacrifice and the three days that follow it jafar ibn muhammad said that among camels and cattle nothing suffices as a sacrifice except the mature animal and the same applies to goats the yearling of sheep however suffices he also said that the sacrifice is an obligation upon every muslim who has the means and that a single sacrifice on a mans part suffices for his entire household', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 51, NULL, 'It is narrated from the Messenger of Allah, may Allah bless him and his family and grant them peace, that he addressed the people on the Day of Sacrifice and said: "This is the day of العَجّ and الثَّجّ. الثَّجّ is the blood you pour out, and whoever''s intention is sincere, its first drop is an expiation for every sin. And العَجّ is supplication, so cry out to Allah the Almighty. By the One in whose hand is the soul of Muhammad, no one will leave this standing-place except that he is forgiven — save the one persisting in a great sin among the great sins, who does not bring himself to forsake it."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'it is narrated from the messenger of allah may allah bless him and his family and grant them peace that he addressed the people on the day of sacrifice and said this is the day of العج and الثج الثج is the blood you pour out and whoevers intention is sincere its first drop is an expiation for every sin and العج is supplication so cry out to allah the almighty by the one in whose hand is the soul of muhammad no one will leave this standing place except that he is forgiven save the one persisting in a great sin among the great sins who does not bring himself to forsake it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 52, NULL, 'The Prophet, may Allah bless him and his family, entered upon Fatimah, (ع), on the Day of Sacrifice and said: "O Fatimah, arise and witness your sacrifice, for its very first drop of blood is an expiation for every sin that is yours. Its flesh, its dung, its bones, its wool — everything of it — will be placed in your balance and multiplied for you seventy times over." Al-Miqdad heard this and said: "May my father and mother be your ransom, O Messenger of Allah — is this something singled out for the family of Muhammad, or is it general?" He said: "Rather, it is for the Muslims in general."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'the prophet may allah bless him and his family entered upon fatimah ع on the day of sacrifice and said o fatimah arise and witness your sacrifice for its very first drop of blood is an expiation for every sin that is yours its flesh its dung its bones its wool everything of it will be placed in your balance and multiplied for you seventy times over al miqdad heard this and said may my father and mother be your ransom o messenger of allah is this something singled out for the family of muhammad or is it general he said rather it is for the muslims in general', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 53, NULL, 'Jafar ibn Muhammad said that what is recommended for a man is that he undertake the slaughter of his sacrifice with his own hand. If he is unable to do so, he should place his hand alongside the hand of the slaughterer. If he is unable to do even that, he should stand over it, invoking the name of Allah upon it until it is slaughtered. From Ali it is reported that he said: a Muslim''s sacrifice should not be slaughtered except by a Muslim, who says at the moment of slaughter: "In the name of Allah, and Allah is the Greatest. I have turned my face toward the One who created the heavens and the earth, upright and submitting, and I am not among the polytheists. Truly my prayer, my sacrifice, my living, and my dying are for Allah, Lord of the worlds, who has no partner. By this I have been commanded, and I am the first of those who submit."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'jafar ibn muhammad said that what is recommended for a man is that he undertake the slaughter of his sacrifice with his own hand if he is unable to do so he should place his hand alongside the hand of the slaughterer if he is unable to do even that he should stand over it invoking the name of allah upon it until it is slaughtered from ali it is reported that he said a muslims sacrifice should not be slaughtered except by a muslim who says at the moment of slaughter in the name of allah and allah is the greatest i have turned my face toward the one who created the heavens and the earth upright and submitting and i am not among the polytheists truly my prayer my sacrifice my living and my dying are for allah lord of the worlds who has no partner by this i have been commanded and i am the first of those who submit', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 54, NULL, 'From Jafar ibn Muhammad it is reported that he was asked about the best sacrificial animals. He replied: "The females of camels, then their males, then the females of cattle, then their males, then the rams of sheep, then the wethers" — meaning those whose testicles have been crushed or bound until they spoil — "then the ewes, then the male of the goats, then the females of them." He held in low regard any animal whose ears had been cut off. Among all these, the best is the fattest and the largest. The finest of rams is the horned ram that eats amid blackness, drinks amid blackness, walks amid blackness, looks amid blackness, urinates amid blackness, and drops dung amid blackness. It was with such an animal that the Messenger of Allah, may Allah bless him and his family and grant them peace, used to sacrifice. That ram is the الأملح — the black-and-white. It is transmitted that he sacrificed with two such black-and-white rams, and it is said that this is the very description of the ram sent down to Ibrahim, (ع) and upon his family.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'from jafar ibn muhammad it is reported that he was asked about the best sacrificial animals he replied the females of camels then their males then the females of cattle then their males then the rams of sheep then the wethers meaning those whose testicles have been crushed or bound until they spoil then the ewes then the male of the goats then the females of them he held in low regard any animal whose ears had been cut off among all these the best is the fattest and the largest the finest of rams is the horned ram that eats amid blackness drinks amid blackness walks amid blackness looks amid blackness urinates amid blackness and drops dung amid blackness it was with such an animal that the messenger of allah may allah bless him and his family and grant them peace used to sacrifice that ram is the الاملح the black and white it is transmitted that he sacrificed with two such black and white rams and it is said that this is the very description of the ram sent down to ibrahim ع and upon his family', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 55, NULL, 'It is transmitted from Jafar ibn Muhammad that he permitted sharing in a sacrifice for one who cannot find an animal to offer alone but is able to contribute to a shared offering. From Ali, it is transmitted that he disliked sacrificing an animal with a broken horn, one that is clearly lame, one that is clearly emaciated, or one whose ear has been wholly cut away. He permitted a slit ear when it is a distinguishing mark, and an aged animal when it carries no defect or leanness. He said: "Whoever buys a sacrifice and it falls ill or dies before the Day of Sacrifice, it has sufficed for him; but if he obtains another to sacrifice in its place and does so, that is better."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'it is transmitted from jafar ibn muhammad that he permitted sharing in a sacrifice for one who cannot find an animal to offer alone but is able to contribute to a shared offering from ali it is transmitted that he disliked sacrificing an animal with a broken horn one that is clearly lame one that is clearly emaciated or one whose ear has been wholly cut away he permitted a slit ear when it is a distinguishing mark and an aged animal when it carries no defect or leanness he said whoever buys a sacrifice and it falls ill or dies before the day of sacrifice it has sufficed for him but if he obtains another to sacrifice in its place and does so that is better', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 56, NULL, 'Al-Hajj: 36فَكُلُوا۟ مِنْهَا وَأَطْعِمُوا۟ ٱلْقَانِعَ وَٱلْمُعْتَرَّ', '', 'فَكُلُوا۟ مِنْهَا وَأَطْعِمُوا۟ ٱلْقَانِعَ وَٱلْمُعْتَرَّ', 'Al-Hajj: 36', 22, 36, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'al hajj 36فكلوا منها واطعموا القانع والمعتر', 'فكلوا منها واطعموا القانع والمعتر');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 57, NULL, 'It is transmitted from Jafar ibn Muhammad that he was asked about the word of Allah the Almighty, ﴿فَكُلُوا مِنْهَا وَأَطْعِمُوا الْقَانِعَ وَالْمُعْتَرَّ﴾ — "So eat of it and feed the contented and the petitioner" (al-Hajj: 36) — and about His word, ﴿فَكُلُوا مِنْهَا وَأَطْعِمُوا الْبَائِسَ الْفَقِيرَ﴾ — "So eat of it and feed the wretched poor" (al-Hajj: 28). He said: "The قانع is the beggar who is content with what he is given and does not deem it too little; the مُعْتَرّ is the one who presents himself for charity but does not ask; the poor man is the one who finds nothing; and the مسكين is harder pressed than he in his condition — and the wretched poor man is the worst of them all in condition and the most hard pressed."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'it is transmitted from jafar ibn muhammad that he was asked about the word of allah the almighty فكلوا منها واطعموا القانع والمعتر so eat of it and feed the contented and the petitioner al hajj 36 and about his word فكلوا منها واطعموا البايس الفقير so eat of it and feed the wretched poor al hajj 28 he said the قانع is the beggar who is content with what he is given and does not deem it too little the معتر is the one who presents himself for charity but does not ask the poor man is the one who finds nothing and the مسكين is harder pressed than he in his condition and the wretched poor man is the worst of them all in condition and the most hard pressed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 58, NULL, 'The speaker recounted that his father — رض — when slaughtering his sacrifice at Mina or offering a gift-offering, would set the head of the animal before him. Whenever a beggar passed, he would stop the man and say, "Take the head." If the beggar took it gladly and went on his way, he gave it to him. If the beggar took it but showed reluctance, he would say, "Leave it," and give him meat instead. And if the beggar turned away from it and refused it altogether, he left him with nothing — testing by this the true condition of each poor man who came before him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'the speaker recounted that his father رض when slaughtering his sacrifice at mina or offering a gift offering would set the head of the animal before him whenever a beggar passed he would stop the man and say take the head if the beggar took it gladly and went on his way he gave it to him if the beggar took it but showed reluctance he would say leave it and give him meat instead and if the beggar turned away from it and refused it altogether he left him with nothing testing by this the true condition of each poor man who came before him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 59, NULL, 'Al-Hajj: 36فَكُلُوا۟ مِنْهَا وَأَطْعِمُوا۟ ٱلْقَانِعَ وَٱلْمُعْتَرَّ', '', 'فَكُلُوا۟ مِنْهَا وَأَطْعِمُوا۟ ٱلْقَانِعَ وَٱلْمُعْتَرَّ', 'Al-Hajj: 36', 22, 36, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'al hajj 36فكلوا منها واطعموا القانع والمعتر', 'فكلوا منها واطعموا القانع والمعتر');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 60, NULL, 'It is related from Ali that he said, concerning the word of God Almighty — ﴿فَكُلُوا مِنْهَا﴾ "So eat of it" (al-Hajj: 36) — "This is a command of recommendation, not of obligation. Whoever wishes may eat of his sacrifice, and whoever wishes need not eat of it; and to eat of it is better."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'it is related from ali that he said concerning the word of god almighty فكلوا منها so eat of it al hajj 36 this is a command of recommendation not of obligation whoever wishes may eat of his sacrifice and whoever wishes need not eat of it and to eat of it is better', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 61, NULL, 'It has also come down from the Messenger of God, may God bless him and his family and grant them peace, that he made Ali a partner in a gift-offering consisting of one hundred sacrificial camels. He gave the order that a piece be taken from each camel, placed in a pot, and cooked. He then called Ali, and the two of them ate of the meat as much as they could manage and drank of the broth, so that they might partake of every one of the animals. The Messenger of God, may God bless him and his family and grant them peace, said: "The broth is one of the two meats, for the strength of the meat passes out into it."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'it has also come down from the messenger of god may god bless him and his family and grant them peace that he made ali a partner in a gift offering consisting of one hundred sacrificial camels he gave the order that a piece be taken from each camel placed in a pot and cooked he then called ali and the two of them ate of the meat as much as they could manage and drank of the broth so that they might partake of every one of the animals the messenger of god may god bless him and his family and grant them peace said the broth is one of the two meats for the strength of the meat passes out into it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'the hunt and the knife: game, slaughter, and sacrifice', '5. The Hunt and the Knife: Game, Slaughter, and Sacrifice', 62, NULL, 'Jafar ibn Muhammad was then asked...', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 5 the hunt and the knife game slaughter and sacrifice', 'jafar ibn muhammad was then asked', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 0, NULL, 'Jafar ibn Muhammad (ع) was asked about a man so overwhelmed by fear of Allah Almighty that he had abandoned women, abandoned wholesome food, and could no longer raise his head toward heaven out of reverence for Allah Almighty. The questioner said, "As for his turning away from women, I know what the Messenger of Allah ﷺ had of them. As for his turning away from wholesome food, the Messenger of Allah used to eat meat and honey. And as for the fear of Allah Almighty overtaking him until he could no longer raise his head toward the sky out of reverence — who was ever more fearful of Allah, or more humbled before Him, than the Messenger of Allah? Yet he did not do this." For Allah Almighty has said, "Indeed in the Messenger of Allah you have a good example," and true humility resides in the heart.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'jafar ibn muhammad ع was asked about a man so overwhelmed by fear of allah almighty that he had abandoned women abandoned wholesome food and could no longer raise his head toward heaven out of reverence for allah almighty the questioner said as for his turning away from women i know what the messenger of allah ﷺ had of them as for his turning away from wholesome food the messenger of allah used to eat meat and honey and as for the fear of allah almighty overtaking him until he could no longer raise his head toward the sky out of reverence who was ever more fearful of allah or more humbled before him than the messenger of allah yet he did not do this for allah almighty has said indeed in the messenger of allah you have a good example and true humility resides in the heart', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'marriage and the household', '6. Marriage and the Household', 1, NULL, 'An-Nur: 32إِن يَكُونُوا۟ فُقَرَآءَ يُغْنِهِمُ ٱللَّهُ مِن فَضْلِهِۦ', '', 'إِن يَكُونُوا۟ فُقَرَآءَ يُغْنِهِمُ ٱللَّهُ مِن فَضْلِهِۦ', 'An-Nur: 32', 24, 32, 'mukhtasar ul asaar 2 6 marriage and the household', 'an nur 32ان يكونوا فقراء يغنهم الله من فضله', 'ان يكونوا فقراء يغنهم الله من فضله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 2, NULL, 'The merits of marriage rest on this understanding, for there is no monasticism in Islam. Allah Almighty said: "And marry the unmarried among you and the righteous among your male and female slaves. If they should be poor, Allah will enrich them from His bounty, and Allah is all-Encompassing and Knowing."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the merits of marriage rest on this understanding for there is no monasticism in islam allah almighty said and marry the unmarried among you and the righteous among your male and female slaves if they should be poor allah will enrich them from his bounty and allah is all encompassing and knowing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 3, NULL, 'The Imams of the House of the Messenger of Allah transmitted that he said: "Whoever loves to follow my way among my nation, let him know that marriage is one of my Sunnahs." And he said: "Whoever loves to meet Allah pure and purified, let him meet Him with a wife." And he said: "There is no young man who marries in his youth except that his devil cries out, Woe to him, he has protected two-thirds of his religion! So let the servant then fear Allah Almighty in the remaining third." Whenever he learned that one of his companions had married, he would say, "He has completed his religion." And he said, (ع), "The more a believer increases in faith, the more he loves women." And he said: "There is no monasticism in Islam. Marry, for I shall boast of your numbers before the nations." He forbade celibacy and the forsaking of marriage.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the imams of the house of the messenger of allah transmitted that he said whoever loves to follow my way among my nation let him know that marriage is one of my sunnahs and he said whoever loves to meet allah pure and purified let him meet him with a wife and he said there is no young man who marries in his youth except that his devil cries out woe to him he has protected two thirds of his religion so let the servant then fear allah almighty in the remaining third whenever he learned that one of his companions had married he would say he has completed his religion and he said ع the more a believer increases in faith the more he loves women and he said there is no monasticism in islam marry for i shall boast of your numbers before the nations he forbade celibacy and the forsaking of marriage', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 4, NULL, 'He said: "When a believing man comes to his believing wife, two angels enfold him, and he is like one who has drawn his sword in the path of Allah. When he is done, his sins fall from him as the leaves fall from the tree, as though he had washed himself clean of sin. If she conceives by him, he has the reward of one who fasts and stands in prayer. When the pangs of labor seize her, no one knows her reward but Allah Almighty. When she delivers, with every draft of milk she suckles the child, Allah Almighty writes for her a good deed and erases from her an evil one. And if she should die of her travail, she will rise on the Day of Resurrection without reckoning, for she died of her affliction."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he said when a believing man comes to his believing wife two angels enfold him and he is like one who has drawn his sword in the path of allah when he is done his sins fall from him as the leaves fall from the tree as though he had washed himself clean of sin if she conceives by him he has the reward of one who fasts and stands in prayer when the pangs of labor seize her no one knows her reward but allah almighty when she delivers with every draft of milk she suckles the child allah almighty writes for her a good deed and erases from her an evil one and if she should die of her travail she will rise on the day of resurrection without reckoning for she died of her affliction', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 5, NULL, 'The Master said: "Whoever abandons marriage out of fear of household expense has thought ill of his Lord the Almighty, who says, If they should be poor, Allah will enrich them from His bounty." He also said: "Whoever amasses wealth and does not marry, so that the women left unwed because of him fall into sin, their sin rests upon him." From Jafar ibn Muhammad comes this: "No two believers are joined in a lawful marriage but that a caller from heaven cries out, Allah Almighty has wedded such a one to such a one; and no two believing spouses are parted from a marriage but that a caller from heaven cries out, Allah Almighty has permitted the separation of such a one from such a one."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the master said whoever abandons marriage out of fear of household expense has thought ill of his lord the almighty who says if they should be poor allah will enrich them from his bounty he also said whoever amasses wealth and does not marry so that the women left unwed because of him fall into sin their sin rests upon him from jafar ibn muhammad comes this no two believers are joined in a lawful marriage but that a caller from heaven cries out allah almighty has wedded such a one to such a one and no two believing spouses are parted from a marriage but that a caller from heaven cries out allah almighty has permitted the separation of such a one from such a one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 6, NULL, 'On what is recommended in a spouse, and from whose marriage one should turn away, it is narrated from the Imams of the family of the Messenger of Allah that he said: "Choose well for your seed, for the maternal uncle is one of the two who share the bed." His meaning was that seed should be placed nowhere but in purity — that the child''s mother be neither of corrupt origin nor corrupt in herself. From this same principle he forbade that a child be suckled by the milk of a wicked woman. If such a thing is disliked in nursing and forbidden there, then in lineage it is graver still, and the prohibition more emphatic. He said: "Marry those who are your equals, and give your daughters in marriage to them, and choose well for your seed."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'on what is recommended in a spouse and from whose marriage one should turn away it is narrated from the imams of the family of the messenger of allah that he said choose well for your seed for the maternal uncle is one of the two who share the bed his meaning was that seed should be placed nowhere but in purity that the childs mother be neither of corrupt origin nor corrupt in herself from this same principle he forbade that a child be suckled by the milk of a wicked woman if such a thing is disliked in nursing and forbidden there then in lineage it is graver still and the prohibition more emphatic he said marry those who are your equals and give your daughters in marriage to them and choose well for your seed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 7, NULL, 'He related that Allah Almighty says: "When I wish to grant My servant the good of this world and the Hereafter, I give him a tongue that remembers Me, a humble heart, a body patient in affliction, and a believing wife who gladdens him when he looks upon her and guards herself and his wealth in his absence." And he said: "Five things are of happiness: a righteous wife, upright children, righteous companions, a man''s provision in his own land, and love for the family of Muhammad, (ع) and his family."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he related that allah almighty says when i wish to grant my servant the good of this world and the hereafter i give him a tongue that remembers me a humble heart a body patient in affliction and a believing wife who gladdens him when he looks upon her and guards herself and his wealth in his absence and he said five things are of happiness a righteous wife upright children righteous companions a mans provision in his own land and love for the family of muhammad ع and his family', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 8, NULL, 'He said: "A good woman among women is like the albino crow, and the albino crow is seldom found." By "good" he meant the believing, chaste, and beautiful woman — fitting in every one of her states. Such a woman is rare, and so he likened her to the albino crow, the rarest of birds. He said: "A woman of standing has no price, neither the good among them nor the bad. As for the good, she has no price in gold or silver or all the possessions of this world; and as for the bad, she has no price, not even of dust, for dust is better than she." And he said: "The world is but enjoyment, and the best enjoyment of the world is a righteous wife." And he said: "Of the believing man''s happiness are a righteous wife, a spacious dwelling, an easy mount, and a righteous child."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he said a good woman among women is like the albino crow and the albino crow is seldom found by good he meant the believing chaste and beautiful woman fitting in every one of her states such a woman is rare and so he likened her to the albino crow the rarest of birds he said a woman of standing has no price neither the good among them nor the bad as for the good she has no price in gold or silver or all the possessions of this world and as for the bad she has no price not even of dust for dust is better than she and he said the world is but enjoyment and the best enjoyment of the world is a righteous wife and he said of the believing mans happiness are a righteous wife a spacious dwelling an easy mount and a righteous child', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 9, NULL, 'He forbade marrying a woman for her wealth or her beauty alone, saying, "Her wealth makes her overbearing, and her beauty destroys her." And he said: "Take the one of religion." And he said, comparing what is most prized: "There is no horse finer than the deep black, and no woman like the daughter of one''s age." And he said: "The best of your women are the women of Quraysh, the most tender toward a husband and the most devoted to a child."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he forbade marrying a woman for her wealth or her beauty alone saying her wealth makes her overbearing and her beauty destroys her and he said take the one of religion and he said comparing what is most prized there is no horse finer than the deep black and no woman like the daughter of ones age and he said the best of your women are the women of quraysh the most tender toward a husband and the most devoted to a child', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 10, NULL, 'He said: "Marry the one of clear, healthy complexion, for there is blessing in that. And when one of you would marry a woman, let him ask about her hair as he asks about her face, for the hair is one of the two beauties. And keep to those of shorter stature, for that is better suited to what you seek." He said: "A woman is but a necklace, so let each of you consider well with what he adorns himself." And he said: "If there is ill fortune in anything, it is in a woman, a dwelling, and a mount."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he said marry the one of clear healthy complexion for there is blessing in that and when one of you would marry a woman let him ask about her hair as he asks about her face for the hair is one of the two beauties and keep to those of shorter stature for that is better suited to what you seek he said a woman is but a necklace so let each of you consider well with what he adorns himself and he said if there is ill fortune in anything it is in a woman a dwelling and a mount', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 11, NULL, 'He said: "Women are four: a gathering that gathers, a spring that gives water, a war that subdues, and a galling fetter."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he said women are four a gathering that gathers a spring that gives water a war that subdues and a galling fetter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 12, NULL, 'The galling fetter requires explanation. In the Age of Ignorance, captors would bind those they wished to torment with a thong of fresh hide stripped from a camel, turned hair-inward against the skin and bound fast. As the hide dried it contracted, pulling tighter and tighter; lice would breed within it and could not be reached because of the tightness, and so the captive suffered enormously — a torment that struck without a single blow. This is the image the Prophet ﷺ applied to the bad wife and to what her husband endures at her hands.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the galling fetter requires explanation in the age of ignorance captors would bind those they wished to torment with a thong of fresh hide stripped from a camel turned hair inward against the skin and bound fast as the hide dried it contracted pulling tighter and tighter lice would breed within it and could not be reached because of the tightness and so the captive suffered enormously a torment that struck without a single blow this is the image the prophet ﷺ applied to the bad wife and to what her husband endures at her hands', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 13, NULL, 'The remaining three are:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the remaining three are', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 14, NULL, 'A gathering that gathers: a woman in whom goodness and purity are gathered together. A spring that gives water: a woman who holds one child in her arms and carries another in her womb. A war that subdues: a woman of ill manners toward her husband.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'a gathering that gathers a woman in whom goodness and purity are gathered together a spring that gives water a woman who holds one child in her arms and carries another in her womb a war that subdues a woman of ill manners toward her husband', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'marriage and the household', '6. Marriage and the Household', 15, NULL, 'An-Nisa: 12وَلَدٌۭ ۚ فَإِن كَانَ لَكُمْ وَلَدٌۭ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكْتُم ۚ مِّنۢ بَعْدِ وَصِيَّةٍۢ تُوصُونَ بِهَآ أَوْ دَيْنٍۢ ۗ وَإِن كَانَ رَجُلٌۭ يُورَثُ كَلَلَةً أَوِ ٱمْرَأَةٌۭ وَلَهُۥٓ أَخٌ أَوْ أُخْتٌۭ فَلِكُلِّ وَحِدٍۢ مِّنْهُمَا ٱلسُّدُسُ ۚ فَإِن كَانُوٓا۟ أَكْثَرَ مِن ذَلِكَ فَهُمْ شُرَكَآءُ فِى ٱلثُّلُثِ ۚ مِنۢ بَعْدِ وَصِيَّةٍۢ يُوصَىٰ بِهَآ أَوْ دَيْنٍ غَيْرَ مُضَآرٍّۢ ۚ وَصِيَّةًۭ مِّنَ ٱللَّهِ ۗ وَٱللَّهُ عَلِيمٌ حَلِيمٌۭHe said: "Beware of marrying the foolish woman, for her companionship is an affliction and her child is a loss."', '', 'وَلَدٌۭ ۚ فَإِن كَانَ لَكُمْ وَلَدٌۭ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكْتُم ۚ مِّنۢ بَعْدِ وَصِيَّةٍۢ تُوصُونَ بِهَآ أَوْ دَيْنٍۢ ۗ وَإِن كَانَ رَجُلٌۭ يُورَثُ كَلَلَةً أَوِ ٱمْرَأَةٌۭ وَلَهُۥٓ أَخٌ أَوْ أُخْتٌۭ فَلِكُلِّ وَحِدٍۢ مِّنْهُمَا ٱلسُّدُسُ ۚ فَإِن كَانُوٓا۟ أَكْثَرَ مِن ذَلِكَ فَهُمْ شُرَكَآءُ فِى ٱلثُّلُثِ ۚ مِنۢ بَعْدِ وَصِيَّةٍۢ يُوصَىٰ بِهَآ أَوْ دَيْنٍ غَيْرَ مُضَآرٍّۢ ۚ وَصِيَّةًۭ مِّنَ ٱللَّهِ ۗ وَٱللَّهُ عَلِيمٌ حَلِيمٌۭ', 'An-Nisa: 12', 4, 12, 'mukhtasar ul asaar 2 6 marriage and the household', 'an nisa 12ولد فان كان لكم ولد فلهن الثمن مما تركتم من بعد وصيه توصون بها او دين وان كان رجل يورث كلله او امراه وله اخ او اخت فلكل وحد منهما السدس فان كانوا اكثر من ذلك فهم شركاء في الثلث من بعد وصيه يوصي بها او دين غير مضار وصيه من الله والله عليم حليمhe said beware of marrying the foolish woman for her companionship is an affliction and her child is a loss', 'ولد فان كان لكم ولد فلهن الثمن مما تركتم من بعد وصيه توصون بها او دين وان كان رجل يورث كلله او امراه وله اخ او اخت فلكل وحد منهما السدس فان كانوا اكثر من ذلك فهم شركاء في الثلث من بعد وصيه يوصي بها او دين غير مضار وصيه من الله والله عليم حليم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 16, NULL, 'He said: "The best women of my nation are those fairest of face and lightest in dowry." He also said: "Among the blessings of a woman is that her firstborn be a girl." He said again: "Women are four: a spring that gives water, a gathering that gathers, a war that subdues, and a barren woman." And he said: "Marry the dark-complexioned woman who is fertile, and do not marry the beautiful barren woman, for I will boast of your numbers before the nations on the Day of Resurrection. The children who die young are beneath the Throne of the Most Merciful, seeking forgiveness for their parents; Ibrahim, (ع), takes them into his care, and Sarah raises them upon a mountain of musk and amber and saffron."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he said the best women of my nation are those fairest of face and lightest in dowry he also said among the blessings of a woman is that her firstborn be a girl he said again women are four a spring that gives water a gathering that gathers a war that subdues and a barren woman and he said marry the dark complexioned woman who is fertile and do not marry the beautiful barren woman for i will boast of your numbers before the nations on the day of resurrection the children who die young are beneath the throne of the most merciful seeking forgiveness for their parents ibrahim ع takes them into his care and sarah raises them upon a mountain of musk and amber and saffron', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 17, NULL, 'He said: "The best of your women is the ardent yet chaste one, ardent toward her husband and chaste from all besides him." He also said: "Marry the virgins, for they are sweetest of mouth, purest of womb, quickest of the women to learn, and most steadfast in affection." And he said: "Marry the ayyami" — meaning Allah Almighty will better their character, broaden their provision, and increase their blessing. The command to marry the ayyami — those women whose husbands have died or who have been divorced — is a command of encouragement, not of binding obligation, just as the word of Allah Almighty, "And marry the unmarried among you," is of the same kind. Whoever marries one of the ayyami, desiring what Allah Almighty and His Messenger have urged, has done what he was called to; and whoever marries a virgin, there is no fault in that, for the virtue of marrying virgins has already been affirmed from the Messenger of Allah. Yet the ayyami should not be passed over out of mere preference or disdain on account of a prior marriage, for most of the wives of the Messenger of Allah had been married before, and Allah Almighty says: "Indeed in the Messenger of Allah you have a good example for those who hope for Allah and the Last Day."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he said the best of your women is the ardent yet chaste one ardent toward her husband and chaste from all besides him he also said marry the virgins for they are sweetest of mouth purest of womb quickest of the women to learn and most steadfast in affection and he said marry the ayyami meaning allah almighty will better their character broaden their provision and increase their blessing the command to marry the ayyami those women whose husbands have died or who have been divorced is a command of encouragement not of binding obligation just as the word of allah almighty and marry the unmarried among you is of the same kind whoever marries one of the ayyami desiring what allah almighty and his messenger have urged has done what he was called to and whoever marries a virgin there is no fault in that for the virtue of marrying virgins has already been affirmed from the messenger of allah yet the ayyami should not be passed over out of mere preference or disdain on account of a prior marriage for most of the wives of the messenger of allah had been married before and allah almighty says indeed in the messenger of allah you have a good example for those who hope for allah and the last day', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'marriage and the household', '6. Marriage and the Household', 18, NULL, 'An-Nur: 32إِن يَكُونُوا۟ فُقَرَآءَ يُغْنِهِمُ ٱللَّهُ مِن فَضْلِهِۦ', '', 'إِن يَكُونُوا۟ فُقَرَآءَ يُغْنِهِمُ ٱللَّهُ مِن فَضْلِهِۦ', 'An-Nur: 32', 24, 32, 'mukhtasar ul asaar 2 6 marriage and the household', 'an nur 32ان يكونوا فقراء يغنهم الله من فضله', 'ان يكونوا فقراء يغنهم الله من فضله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 19, NULL, 'A Muslim must respond to his Muslim brother who comes forward as a suitor, provided he is satisfied with that man''s religion. He warned that to refuse such a proposal invites strife and grave corruption across the land. He forbade marriage sought for any purpose other than the face of Allah Almighty and the preservation of chastity, and he forbade marriage undertaken for show or reputation. He said: "Whoever marries a woman for her standing or her wealth, Allah leaves him to that; but whoever marries her for her religion and her excellence, Allah Almighty grants him beauty and wealth besides." He then recited the words of Allah Almighty: "If they should be poor, Allah will enrich them from His bounty, and Allah is all-Encompassing, Knowing." And he said: "There is no calamity heavier upon a servant in his religion than that his Muslim kinsman should come to him and say, Marry me your daughter, and he answer, I will not, because he is wealthier than the suitor."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'a muslim must respond to his muslim brother who comes forward as a suitor provided he is satisfied with that mans religion he warned that to refuse such a proposal invites strife and grave corruption across the land he forbade marriage sought for any purpose other than the face of allah almighty and the preservation of chastity and he forbade marriage undertaken for show or reputation he said whoever marries a woman for her standing or her wealth allah leaves him to that but whoever marries her for her religion and her excellence allah almighty grants him beauty and wealth besides he then recited the words of allah almighty if they should be poor allah will enrich them from his bounty and allah is all encompassing knowing and he said there is no calamity heavier upon a servant in his religion than that his muslim kinsman should come to him and say marry me your daughter and he answer i will not because he is wealthier than the suitor', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 20, NULL, 'It is told of Ali ibn al-Husayn (ع) that he passed a woman in one of the districts of Makkah and was struck by her beauty and character. He inquired about her, learned she had no husband, proposed, married her, and consummated the marriage. Afterward, a kinsman came to him and said, "O son of the Messenger of Allah, something concerning your marriage to this woman has weighed upon me, for you married her without asking after her lineage. I could not rest until I looked into the matter myself. I found her to be of the Banu Shayban, among the noblest of her people, and so I was gladdened and set at ease."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it is told of ali ibn al husayn ع that he passed a woman in one of the districts of makkah and was struck by her beauty and character he inquired about her learned she had no husband proposed married her and consummated the marriage afterward a kinsman came to him and said o son of the messenger of allah something concerning your marriage to this woman has weighed upon me for you married her without asking after her lineage i could not rest until i looked into the matter myself i found her to be of the banu shayban among the noblest of her people and so i was gladdened and set at ease', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 21, NULL, 'Ali ibn al-Husayn asked, "And what was it you had feared?"', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'ali ibn al husayn asked and what was it you had feared', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 22, NULL, 'The man replied, "I feared she might not be your equal, and that people would speak of it."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the man replied i feared she might not be your equal and that people would speak of it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 23, NULL, 'Ali ibn al-Husayn said to him: "I had thought you of sounder judgment than this. Do you not know that Allah Almighty brought Islam, and by it raised the lowly, completed what was deficient, and ennobled what was base? There is no reproach upon the affair of a Muslim; reproach belongs only to the Age of Ignorance."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'ali ibn al husayn said to him i had thought you of sounder judgment than this do you not know that allah almighty brought islam and by it raised the lowly completed what was deficient and ennobled what was base there is no reproach upon the affair of a muslim reproach belongs only to the age of ignorance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 24, NULL, 'He also married a freedwoman who had borne a son to a man now dead. When Abd al-Malik ibn Marwan heard of it, he wrote to reproach him, believing he had found grounds for fault, saying, "Was there not enough for you among the women of Quraysh and the noble Arabs to keep you from the mother of another man''s son?"', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he also married a freedwoman who had borne a son to a man now dead when abd al malik ibn marwan heard of it he wrote to reproach him believing he had found grounds for fault saying was there not enough for you among the women of quraysh and the noble arabs to keep you from the mother of another mans son', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 25, NULL, 'Ali ibn al-Husayn wrote back to him: "To proceed: Allah Almighty has by Islam raised the lowly and completed the deficient, so there is no reproach upon the affair of a Muslim; reproach belongs only to the Age of Ignorance. And the Messenger of Allah married such a one" — meaning Safiyyah bint Hayy ibn Akhtab — "and in him is a good example."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'ali ibn al husayn wrote back to him to proceed allah almighty has by islam raised the lowly and completed the deficient so there is no reproach upon the affair of a muslim reproach belongs only to the age of ignorance and the messenger of allah married such a one meaning safiyyah bint hayy ibn akhtab and in him is a good example', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 26, NULL, 'Were it permissible to disdain the mothers of children, the marriage bed would be abandoned and corruption would appear in the land. The Imams — عَلَيْهِمُ السَّلَامُ — are the most fit to make this plain, so that the people might follow their example.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'were it permissible to disdain the mothers of children the marriage bed would be abandoned and corruption would appear in the land the imams عليهم السلام are the most fit to make this plain so that the people might follow their example', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 27, NULL, 'Allah Almighty said: "O mankind, indeed We have created you from male and female and made you peoples and tribes that you may know one another. Indeed, the most honored of you in the sight of Allah is the most righteous of you. Indeed, Allah is Knowing and Aware."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'allah almighty said o mankind indeed we have created you from male and female and made you peoples and tribes that you may know one another indeed the most honored of you in the sight of allah is the most righteous of you indeed allah is knowing and aware', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 28, NULL, 'On the day of the conquest of Makkah, he addressed the people, praised and glorified Allah, then said: "O people, Allah Almighty has taken from you the arrogance of the Age of Ignorance and its boasting in forefathers. You are all from Adam, and Adam was from clay. The best of Allah''s servants before Allah are those most fearful of Him. Arabness is not a thing born of a father; it is a tongue that speaks. Whoever is held back by his deeds, his lineage will not advance him." Every claim of blood or rancor from the Age of Ignorance lay beneath his feet until the Day of Resurrection.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'on the day of the conquest of makkah he addressed the people praised and glorified allah then said o people allah almighty has taken from you the arrogance of the age of ignorance and its boasting in forefathers you are all from adam and adam was from clay the best of allahs servants before allah are those most fearful of him arabness is not a thing born of a father it is a tongue that speaks whoever is held back by his deeds his lineage will not advance him every claim of blood or rancor from the age of ignorance lay beneath his feet until the day of resurrection', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 29, NULL, 'It is told that he gave Dubaa bint al-Zubayr ibn Abd al-Muttalib in marriage to al-Miqdad ibn al-Aswad, and said that he had done so only to make marriage humble — so that the people might follow the example of the Messenger of Allah and know that the most honored among them before Allah is the most God-fearing. Al-Zubayr was the brother of Abd Allah, the father of the Prophet — — by both father and mother. Jafar ibn Muhammad said: "The Messenger of Allah married Qurayshi women to freedmen: he gave Dubaa bint al-Zubayr ibn Abd al-Muttalib to al-Miqdad ibn al-Aswad, and he married Tamim al-Dari to a woman of the Banu Hashim ibn Abd Manaf."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it is told that he gave dubaa bint al zubayr ibn abd al muttalib in marriage to al miqdad ibn al aswad and said that he had done so only to make marriage humble so that the people might follow the example of the messenger of allah and know that the most honored among them before allah is the most god fearing al zubayr was the brother of abd allah the father of the prophet by both father and mother jafar ibn muhammad said the messenger of allah married qurayshi women to freedmen he gave dubaa bint al zubayr ibn abd al muttalib to al miqdad ibn al aswad and he married tamim al dari to a woman of the banu hashim ibn abd manaf', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 30, NULL, 'The Messenger of Allah said: "When one whose religion and trustworthiness are pleasing to you comes seeking marriage, then marry him; for if you do not, there will be strife in the earth and great corruption."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the messenger of allah said when one whose religion and trustworthiness are pleasing to you comes seeking marriage then marry him for if you do not there will be strife in the earth and great corruption', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 31, NULL, 'It is narrated from Abu Abd Allah Jafar ibn Muhammad that he was in Makkah when word reached him that Dawud ibn Ali had ordered the killing of al-Maali ibn Hunaish — one of his own companions — and that the killing had been carried out. Al-Sadiq (ع) rose in anger, dragging his garment behind him. His son Ismail (ع) came to meet him and said: "O my father, where are you going? The people are defiant, and their insolence against Allah Almighty is such as you well know. Leave them be." Al-Sadiq struck him upon the chest and said: "Step aside from me. Were it a blazing fire, I would plunge into it." He went on until he came to Dawud and said: "O Dawud, you have committed a sin that Allah will never forgive you." Dawud said: "And what is that?" He said: "You have killed a believing man from among the people of Paradise."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it is narrated from abu abd allah jafar ibn muhammad that he was in makkah when word reached him that dawud ibn ali had ordered the killing of al maali ibn hunaish one of his own companions and that the killing had been carried out al sadiq ع rose in anger dragging his garment behind him his son ismail ع came to meet him and said o my father where are you going the people are defiant and their insolence against allah almighty is such as you well know leave them be al sadiq struck him upon the chest and said step aside from me were it a blazing fire i would plunge into it he went on until he came to dawud and said o dawud you have committed a sin that allah will never forgive you dawud said and what is that he said you have killed a believing man from among the people of paradise', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 32, NULL, 'Dawud grew angry and fell silent for a time, then said: "And you too have committed a sin that Allah Almighty will not forgive you." He said: "And what is that?" He said: "Your daughter has been given in marriage to a man from Banu Umayyah." Abu Abd Allah Jafar ibn Muhammad answered that in this his example was the Messenger of Allah himself: the Messenger had given his daughter Zaynab in marriage to Abu al-As ibn Rabiah, and he had given Umm Kulthum in marriage to Uthman ibn Affan, and when she died he married Uthman to Ruqayyah — both being his daughters and his family.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'dawud grew angry and fell silent for a time then said and you too have committed a sin that allah almighty will not forgive you he said and what is that he said your daughter has been given in marriage to a man from banu umayyah abu abd allah jafar ibn muhammad answered that in this his example was the messenger of allah himself the messenger had given his daughter zaynab in marriage to abu al as ibn rabiah and he had given umm kulthum in marriage to uthman ibn affan and when she died he married uthman to ruqayyah both being his daughters and his family', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 33, NULL, 'Then he said: "You are the one who forbade the killing of believers unjustly." Dawud said: "I did not command that he be killed." Al-Sadiq said that al-Sarraqi had reported, "We have lost him," and that the killer himself had said, "I have taken responsibility for him." Abu Abd Allah Jafar ibn Muhammad then had his companions seize the man and bring him forward to be put to death. The man cried out: "O servants of Allah, do you command me to kill men for them, and then exact retribution from me?" Abu Abd Allah Jafar ibn Muhammad said: "As for you, O enemy of Allah, you confess to the killing, and your companion has denied that he commanded you to it. Have you any proof of that?" The man said: "And who will bear witness for me against Dawud?" He said: "Then retribution from you is obligatory and must be exacted." And he delivered him over to the kinsmen of al-Maali, and they put him to death.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'then he said you are the one who forbade the killing of believers unjustly dawud said i did not command that he be killed al sadiq said that al sarraqi had reported we have lost him and that the killer himself had said i have taken responsibility for him abu abd allah jafar ibn muhammad then had his companions seize the man and bring him forward to be put to death the man cried out o servants of allah do you command me to kill men for them and then exact retribution from me abu abd allah jafar ibn muhammad said as for you o enemy of allah you confess to the killing and your companion has denied that he commanded you to it have you any proof of that the man said and who will bear witness for me against dawud he said then retribution from you is obligatory and must be exacted and he delivered him over to the kinsmen of al maali and they put him to death', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 34, NULL, 'Abu Abd Allah Jafar ibn Muhammad was asked whether it was permissible to give daughters in marriage to men of opposing views. He answered that the Messenger of Allah had given his own daughters in marriage to certain men who were known to them, and that Umar had sought the hand of Ali''s daughter Umm Kulthum (ع), only for Ali to refuse him. Umar then went to al-Abbas and laid his grievance before him, pressing the Banu Abd al-Muttalib hard on the matter. Al-Abbas came to Ali (ع) and said: "O son of my brother, you see the position we are in. Umar has sought her hand and has pressed us hard over your refusal." He continued in this way until Ali finally committed her affair to him, whereupon al-Abbas gave her in marriage to Umar on his behalf.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'abu abd allah jafar ibn muhammad was asked whether it was permissible to give daughters in marriage to men of opposing views he answered that the messenger of allah had given his own daughters in marriage to certain men who were known to them and that umar had sought the hand of alis daughter umm kulthum ع only for ali to refuse him umar then went to al abbas and laid his grievance before him pressing the banu abd al muttalib hard on the matter al abbas came to ali ع and said o son of my brother you see the position we are in umar has sought her hand and has pressed us hard over your refusal he continued in this way until ali finally committed her affair to him whereupon al abbas gave her in marriage to umar on his behalf', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 35, NULL, 'It is therefore preferable to give daughters in marriage to people of sound faith, or at least to those who do not stir up enmity against the family of the Messenger of Allah. The marriage of a believer is better than any other, yet where necessity exists there is no harm in contracting marriage with Muslims of differing views. Marrying among them is likewise not forbidden in the way that marriage to polytheists is forbidden. The meritorious and preferred course, however, is marriage among people of sound faith; after them come the weak ones who are neither loyal nor hostile.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it is therefore preferable to give daughters in marriage to people of sound faith or at least to those who do not stir up enmity against the family of the messenger of allah the marriage of a believer is better than any other yet where necessity exists there is no harm in contracting marriage with muslims of differing views marrying among them is likewise not forbidden in the way that marriage to polytheists is forbidden the meritorious and preferred course however is marriage among people of sound faith after them come the weak ones who are neither loyal nor hostile', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'marriage and the household', '6. Marriage and the Household', 36, NULL, 'An-Nisa: 4فَإِن طِبْنَ لَكُمْ عَن شَىْءٍۢ مِّنْهُ', '', 'فَإِن طِبْنَ لَكُمْ عَن شَىْءٍۢ مِّنْهُ', 'An-Nisa: 4', 4, 4, 'mukhtasar ul asaar 2 6 marriage and the household', 'an nisa 4فان طبن لكم عن شيء منه', 'فان طبن لكم عن شيء منه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 37, NULL, 'A man asked Abu Jafar Muhammad ibn Ali about his wife''s sister — a believing woman of knowledge living in Basra with no male guardian among her kin to oversee her affairs. Abu Jafar said to him: "Do not give her in marriage to them. As for yourselves, there is no harm in giving the weak women in marriage to them; but a Nasibiyyah, the daughter of a Nasib — no."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'a man asked abu jafar muhammad ibn ali about his wifes sister a believing woman of knowledge living in basra with no male guardian among her kin to oversee her affairs abu jafar said to him do not give her in marriage to them as for yourselves there is no harm in giving the weak women in marriage to them but a nasibiyyah the daughter of a nasib no', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 38, NULL, 'Zurara ibn Ayan asked Abu Abd Allah Jafar ibn Muhammad about the same matter, and he likewise permitted giving the weak women in marriage to them, but not a Nasibiyyah, the daughter of a Nasib.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'zurara ibn ayan asked abu abd allah jafar ibn muhammad about the same matter and he likewise permitted giving the weak women in marriage to them but not a nasibiyyah the daughter of a nasib', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 39, NULL, 'Abu Jafar also said to Zurara ibn Ayan concerning the weak women: "Keep to the simple and weak among women."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'abu jafar also said to zurara ibn ayan concerning the weak women keep to the simple and weak among women', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 40, NULL, 'And Abu Jafar said: "Marry into the people of doubt, but do not give your women to them in marriage, for a woman takes on her husband''s manners, and he prevails over her in the matter of his religion."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'and abu jafar said marry into the people of doubt but do not give your women to them in marriage for a woman takes on her husbands manners and he prevails over her in the matter of his religion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 41, NULL, 'The Master said: "Marriage among the people of knowledge, and to them, is foremost, best, and nearest to Allah Almighty. If that is not to be had, then the weak ones — those who are neither loyal nor hostile — are better than the people of enmity."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the master said marriage among the people of knowledge and to them is foremost best and nearest to allah almighty if that is not to be had then the weak ones those who are neither loyal nor hostile are better than the people of enmity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 42, NULL, 'After them come the Muslims of the people of truce, whom the Shariah binds together: they marry one another, inherit from one another, and the testimony of one of them concerning another is admissible, provided they are upright and free from suspicion. As for the people of disbelief — Jews, Christians, and polytheists — it is not lawful for any of them to marry a Muslim woman, though marriage among themselves is permissible. Muslim men may marry their women when necessity requires it and Muslim women are not to be found. Muslim women, however, are not lawful to them.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'after them come the muslims of the people of truce whom the shariah binds together they marry one another inherit from one another and the testimony of one of them concerning another is admissible provided they are upright and free from suspicion as for the people of disbelief jews christians and polytheists it is not lawful for any of them to marry a muslim woman though marriage among themselves is permissible muslim men may marry their women when necessity requires it and muslim women are not to be found muslim women however are not lawful to them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 43, NULL, 'Abu Abd Allah (ع) was asked about the saying of Allah Almighty: ﴿الزَّانِي لَا يَنْكِحُ إِلَّا زَانِيَةً أَوْ مُشْرِكَةً وَالزَّانِيَةُ لَا يَنْكِحُهَا إِلَّا زَانٍ أَوْ مُشْرِكٌ وَحُرِّمَ ذَٰلِكَ عَلَى الْمُؤْمِنِينَ﴾ — "The adulterer shall not marry except an adulteress or a polytheist, and the adulteress shall not marry except an adulterer or a polytheist, and that is forbidden to the believers."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'abu abd allah ع was asked about the saying of allah almighty الزاني لا ينكح الا زانيه او مشركه والزانيه لا ينكحها الا زان او مشرك وحرم ذلك علي المومنين the adulterer shall not marry except an adulteress or a polytheist and the adulteress shall not marry except an adulterer or a polytheist and that is forbidden to the believers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 44, NULL, 'He said: "This was revealed concerning women known for licentiousness in the time of ignorance — women who were openly hired out for adultery and kept houses marked for that purpose. The truce came with the provision that whoever wished might return to them. Among them were Habibah, al-Rabab, and Sarah — the last of whom the Messenger of Allah and his family declared lawful to be killed on the day of the conquest of Makkah, because she had been inciting the polytheists to fight the Messenger of Allah and his family. As for a slave girl who has fallen into fornication, there is no harm in purchasing her and having relations with her, and there is likewise no harm in marrying such a woman when necessity requires it, provided one is fortified and guarded against her. Yet chaste women are better and more fitting."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he said this was revealed concerning women known for licentiousness in the time of ignorance women who were openly hired out for adultery and kept houses marked for that purpose the truce came with the provision that whoever wished might return to them among them were habibah al rabab and sarah the last of whom the messenger of allah and his family declared lawful to be killed on the day of the conquest of makkah because she had been inciting the polytheists to fight the messenger of allah and his family as for a slave girl who has fallen into fornication there is no harm in purchasing her and having relations with her and there is likewise no harm in marrying such a woman when necessity requires it provided one is fortified and guarded against her yet chaste women are better and more fitting', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 45, NULL, 'A man came to the Messenger of Allah and his family and said: "O Messenger of Allah, I have a woman who does not turn away the hand of one who touches her, and I love her."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'a man came to the messenger of allah and his family and said o messenger of allah i have a woman who does not turn away the hand of one who touches her and i love her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 46, NULL, 'The Master said: "Then keep her."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the master said then keep her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 47, NULL, 'It was narrated of a man who saw his wife committing adultery yet was loath to part from her: he may keep her if he wishes.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was narrated of a man who saw his wife committing adultery yet was loath to part from her he may keep her if he wishes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 48, NULL, 'He was asked about a man marrying an immoral woman, and he said: "What prevents him? But if he does so, let him fortify the door of his house."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he was asked about a man marrying an immoral woman and he said what prevents him but if he does so let him fortify the door of his house', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 49, NULL, 'He was asked about a man who marries a slave girl born of adultery, and he said: "There is no harm in it, though to keep clear of that is dearer to me."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he was asked about a man who marries a slave girl born of adultery and he said there is no harm in it though to keep clear of that is dearer to me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 50, NULL, 'Concerning a man who has a slave girl who has fallen into fornication, asking whether he may have relations with her, he said: "Yes, if he wishes."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'concerning a man who has a slave girl who has fallen into fornication asking whether he may have relations with her he said yes if he wishes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 51, NULL, 'Concerning a man who marries a woman without full discernment, he said: "It is permissible, so long as no fault remains attached to his child."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'concerning a man who marries a woman without full discernment he said it is permissible so long as no fault remains attached to his child', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 52, NULL, 'Concerning a child of adultery — whether one may have relations with her, sell her if she is a slave girl, and buy her — he said: "Yes; the forbidden does not render the lawful forbidden, nor corrupt it. Were people to turn away from the like of these and forbid their marriage, corruption in the land would multiply, and Allah may yet set right the corrupters and accept the repentance of the sinners."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'concerning a child of adultery whether one may have relations with her sell her if she is a slave girl and buy her he said yes the forbidden does not render the lawful forbidden nor corrupt it were people to turn away from the like of these and forbid their marriage corruption in the land would multiply and allah may yet set right the corrupters and accept the repentance of the sinners', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 53, NULL, 'One of the Ahl al-Bayt (عَلَيْهِمُ السَّلَامُ) was asked about the saying of Allah Almighty, "The adulterer shall not marry except an adulteress or a polytheist." He said: "The word marry here may mean the act of union and intercourse, or it may mean the contract and marriage. If it means union and intercourse, then it may indeed signify adultery, not lawful marriage." He said: "As for His words, except an adulterer or a polytheist — a man does not bring upon himself the wrath of Allah Almighty in this except while he is a polytheist." And the Messenger of Allah said: "The adulterer does not commit adultery at the moment of his adultery while he is a believer."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'one of the ahl al bayt عليهم السلام was asked about the saying of allah almighty the adulterer shall not marry except an adulteress or a polytheist he said the word marry here may mean the act of union and intercourse or it may mean the contract and marriage if it means union and intercourse then it may indeed signify adultery not lawful marriage he said as for his words except an adulterer or a polytheist a man does not bring upon himself the wrath of allah almighty in this except while he is a polytheist and the messenger of allah said the adulterer does not commit adultery at the moment of his adultery while he is a believer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 54, NULL, 'Mentioning the Seeking of Women''s Hands in Marriage', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'mentioning the seeking of womens hands in marriage', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 55, NULL, 'The Imams of the household of the Messenger of Allah are reported to have forbidden a man to propose marriage over his brother''s proposal, and to bid over his brother''s bid. Some of the Ahl al-Bayt explained this teaching: the prohibition on proposing over a brother''s proposal applies only after mutual approach, contentment, inclination, attentiveness, and agreement have all been established — so that nothing remains but the contract itself. Where matters have not yet reached that point, there is no harm in two men, or a group, proposing to a woman until she inclines toward one of them and answers him; only at that moment does it become disliked for another to press a rival proposal. The same principle governs commerce: it is permissible for a man to bid on a commodity and for another to bid above him, so long as the two parties to the sale have not yet reached agreement.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the imams of the household of the messenger of allah are reported to have forbidden a man to propose marriage over his brothers proposal and to bid over his brothers bid some of the ahl al bayt explained this teaching the prohibition on proposing over a brothers proposal applies only after mutual approach contentment inclination attentiveness and agreement have all been established so that nothing remains but the contract itself where matters have not yet reached that point there is no harm in two men or a group proposing to a woman until she inclines toward one of them and answers him only at that moment does it become disliked for another to press a rival proposal the same principle governs commerce it is permissible for a man to bid on a commodity and for another to bid above him so long as the two parties to the sale have not yet reached agreement', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 56, NULL, 'The Messenger of Allah commanded selling by open auction, and people have continued ever since to outbid one another, each raising upon the other, until the commodity is settled and the seller accepts a buyer. After that, no further bid should be made, nor any raising upon what has already been agreed. This is a matter of recommendation, on account of the benefit it carries. Should a suitor propose, or a bidder raise his bid on a commodity, after agreement has been reached but before the contract of marriage or sale is concluded, the same ruling applies: if one surpasses another in merit before the contract is concluded, it does not invalidate the marriage or the sale, since nothing has yet become binding on another party by contract. The Messenger of Allah said: "When one of you wishes to marry a woman, let him cast his gaze upon her, for he is but a buyer." And he said: "When one of you wishes to marry a woman, there is no harm in his looking at what draws him to her."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the messenger of allah commanded selling by open auction and people have continued ever since to outbid one another each raising upon the other until the commodity is settled and the seller accepts a buyer after that no further bid should be made nor any raising upon what has already been agreed this is a matter of recommendation on account of the benefit it carries should a suitor propose or a bidder raise his bid on a commodity after agreement has been reached but before the contract of marriage or sale is concluded the same ruling applies if one surpasses another in merit before the contract is concluded it does not invalidate the marriage or the sale since nothing has yet become binding on another party by contract the messenger of allah said when one of you wishes to marry a woman let him cast his gaze upon her for he is but a buyer and he said when one of you wishes to marry a woman there is no harm in his looking at what draws him to her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 57, NULL, 'Abu Jafar Muhammad ibn Ali said that he mentioned this hadith to Jabir ibn Abd Allah al-Ansari, and Jabir said: "I heard it from the Messenger of Allah. I sought the hand of a young woman from among the women of the Ansar, and I concealed myself for her behind a wall of her father''s garden, and I looked at her and saw what I wished to see and what I had not meant to see, and she pleased me, so I married her, and she was the best of women."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'abu jafar muhammad ibn ali said that he mentioned this hadith to jabir ibn abd allah al ansari and jabir said i heard it from the messenger of allah i sought the hand of a young woman from among the women of the ansar and i concealed myself for her behind a wall of her fathers garden and i looked at her and saw what i wished to see and what i had not meant to see and she pleased me so i married her and she was the best of women', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'marriage and the household', '6. Marriage and the Household', 58, NULL, 'An-Nur: 30قُل لِّلْمُؤْمِنِينَ يَغُضُّوا۟ مِنْ أَبْصَرِهِمْ', '', 'قُل لِّلْمُؤْمِنِينَ يَغُضُّوا۟ مِنْ أَبْصَرِهِمْ', 'An-Nur: 30', 24, 30, 'mukhtasar ul asaar 2 6 marriage and the household', 'an nur 30قل للمومنين يغضوا من ابصرهم', 'قل للمومنين يغضوا من ابصرهم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 59, NULL, 'Abu Abd Allah Jafar ibn Muhammad said: "There is no harm in a man who intends to marry a woman looking at her. He should not, however, look at a slave girl without her master''s permission, since the master may have no wish to sell her or to present her."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'abu abd allah jafar ibn muhammad said there is no harm in a man who intends to marry a woman looking at her he should not however look at a slave girl without her masters permission since the master may have no wish to sell her or to present her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 60, NULL, 'The permission granted by the Messenger of Allah — allowing a man to look at the woman he intends to marry — extends that gaze to the point where he has learned that her family will consent to the match: where agreement has been reached and only the marriage contract remains. Even then, he should look only to acquaint himself with her condition, not from desire and not for the pleasure of it. He must not deliberately direct his gaze toward her private parts or toward anything it is not fitting to see.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the permission granted by the messenger of allah allowing a man to look at the woman he intends to marry extends that gaze to the point where he has learned that her family will consent to the match where agreement has been reached and only the marriage contract remains even then he should look only to acquaint himself with her condition not from desire and not for the pleasure of it he must not deliberately direct his gaze toward her private parts or toward anything it is not fitting to see', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 61, NULL, 'It is not lawful for a man to look with deliberate intent upon women who are not his — meaning women other than his wives, those forbidden to him by blood relation, and those his right hand possesses — whether they appear bareheaded or unveiled. Allah, exalted be He, says: ﴿قُل لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ﴾ — "Say to the believing men that they lower their gaze."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it is not lawful for a man to look with deliberate intent upon women who are not his meaning women other than his wives those forbidden to him by blood relation and those his right hand possesses whether they appear bareheaded or unveiled allah exalted be he says قل للمومنين يغضوا من ابصارهم say to the believing men that they lower their gaze', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 62, NULL, 'Abu Abd Allah Jafar ibn Muhammad was asked about a man past whom a woman walks, and who looks at her from behind. He said: "Would it please any of you that men should look upon his womenfolk and his kinswomen? Be content for others with what you are content with for yourselves."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'abu abd allah jafar ibn muhammad was asked about a man past whom a woman walks and who looks at her from behind he said would it please any of you that men should look upon his womenfolk and his kinswomen be content for others with what you are content with for yourselves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 63, NULL, 'He also spoke about the words of Allah Almighty in the story of Moses — quoting what the woman said: ﴿قَالَتْ إِحْدَاهُمَا يَا أَبَتِ اسْتَأْجِرْهُ إِنَّ خَيْرَ مَنِ اسْتَأْجَرْتَ الْقَوِيُّ الْأَمِينُ﴾ — "One of the two women said: O my father, hire him; indeed, the best one you can hire is the strong and the trustworthy." He explained that she was speaking of Moses (ع) and his character. Her father said to her: "As for your saying that he is strong, that is evident from what you saw of his lifting the rock from the well. But how did you come to know his trustworthiness?" She said: "When he set out with me to come to you, I wished to walk ahead of him to show him the road. He came forward instead and said: Walk behind me and direct me to the road, for we are a people who do not look upon the backs of women."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he also spoke about the words of allah almighty in the story of moses quoting what the woman said قالت احداهما يا ابت استاجره ان خير من استاجرت القوي الامين one of the two women said o my father hire him indeed the best one you can hire is the strong and the trustworthy he explained that she was speaking of moses ع and his character her father said to her as for your saying that he is strong that is evident from what you saw of his lifting the rock from the well but how did you come to know his trustworthiness she said when he set out with me to come to you i wished to walk ahead of him to show him the road he came forward instead and said walk behind me and direct me to the road for we are a people who do not look upon the backs of women', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 64, NULL, 'It is narrated from Ali that he said: "I heard the Messenger of Allah when the subject of looking at women was raised, and he said: The first glance is for you — meaning the glance that falls unawares — and the second is against you, and the third glance is a poisoned arrow from the arrows of Iblis. Whoever forsakes such glances for the sake of Allah Almighty, and for no other, Allah Almighty will requite him with a faith whose sweetness he will taste." And Abu Abd Allah Jafar ibn Muhammad said: "Do those who look upon the forms of women not fear that they may be afflicted with the like in their own wives?"', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it is narrated from ali that he said i heard the messenger of allah when the subject of looking at women was raised and he said the first glance is for you meaning the glance that falls unawares and the second is against you and the third glance is a poisoned arrow from the arrows of iblis whoever forsakes such glances for the sake of allah almighty and for no other allah almighty will requite him with a faith whose sweetness he will taste and abu abd allah jafar ibn muhammad said do those who look upon the forms of women not fear that they may be afflicted with the like in their own wives', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 65, NULL, 'It is narrated from Ali that a man came to the Messenger of Allah and said: "O Messenger of Allah, should I ask my mother''s leave before entering upon her?" He said: "Yes." The man asked: "And why, O Messenger of Allah?" He said: "Would it please you to see her unclothed?" The man said: "No." He said: "Then ask her leave." The man said: "O Messenger of Allah, my sister uncovers her hair before me." He said: "No." The man asked: "Why?" He said: "I fear that, should she reveal one of her charms before you, Satan may invite you toward her." And he said — upon him and his family be peace — "When one of you would kiss a woman who is a mahram to him and has come of age — a mother, a sister, an aunt, or any who is forbidden to him in marriage — let him kiss her upon the head and between the eyes, or let him refrain from her cheeks and her mouth."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it is narrated from ali that a man came to the messenger of allah and said o messenger of allah should i ask my mothers leave before entering upon her he said yes the man asked and why o messenger of allah he said would it please you to see her unclothed the man said no he said then ask her leave the man said o messenger of allah my sister uncovers her hair before me he said no the man asked why he said i fear that should she reveal one of her charms before you satan may invite you toward her and he said upon him and his family be peace when one of you would kiss a woman who is a mahram to him and has come of age a mother a sister an aunt or any who is forbidden to him in marriage let him kiss her upon the head and between the eyes or let him refrain from her cheeks and her mouth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 66, NULL, 'Concerning Fatimah (ع): a blind man sought leave to enter upon her, and she veiled herself from him. It was said to her that he was blind — his sight wholly gone, unable to see anything of her. She said: "Even if he does not see me, I see him, and he perceives the voice and senses the scent."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'concerning fatimah ع a blind man sought leave to enter upon her and she veiled herself from him it was said to her that he was blind his sight wholly gone unable to see anything of her she said even if he does not see me i see him and he perceives the voice and senses the scent', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 67, NULL, 'The Messenger of Allah once posed a question to Ali and a company gathered before him: what is best for women? They did not know what to answer. Ali withdrew to Fatimah and put the question to her. She said: "What is best for women is that they should not see men and that men should not see them." Ali returned to the Messenger of Allah and reported this. He asked: "Did you arrive at this of yourself, or did another say it?" Ali said: "O Messenger of Allah, it was Fatimah who said it." The Messenger of Allah was pleased and said: "Fatimah is but a part of me."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the messenger of allah once posed a question to ali and a company gathered before him what is best for women they did not know what to answer ali withdrew to fatimah and put the question to her she said what is best for women is that they should not see men and that men should not see them ali returned to the messenger of allah and reported this he asked did you arrive at this of yourself or did another say it ali said o messenger of allah it was fatimah who said it the messenger of allah was pleased and said fatimah is but a part of me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 69, NULL, 'The Messenger of Allah taught that whoever desires to marry should not approach the matter heedlessly. He should begin by turning to Allah, praising Him and extolling Him, and then asking Him for the kind of companion that makes a household whole. He said that such a person should pray:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the messenger of allah taught that whoever desires to marry should not approach the matter heedlessly he should begin by turning to allah praising him and extolling him and then asking him for the kind of companion that makes a household whole he said that such a person should pray', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 70, NULL, '"O Allah, grant me a wife who is affectionate and fruitful, grateful and jealous in her honor. If I do good, she thanks me; if I do wrong, she forgives me; if I remember Allah, she helps me; if I forget, she reminds me; if I go out from her, she guards herself; if I come in to her, she gladdens me; if I command her, she obeys me; if I swear by her, she fulfills my oath; if she becomes angry, You satisfy me. O Lord of majesty and honor, grant me what I have asked for, and what You have apportioned and given."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'o allah grant me a wife who is affectionate and fruitful grateful and jealous in her honor if i do good she thanks me if i do wrong she forgives me if i remember allah she helps me if i forget she reminds me if i go out from her she guards herself if i come in to her she gladdens me if i command her she obeys me if i swear by her she fulfills my oath if she becomes angry you satisfy me o lord of majesty and honor grant me what i have asked for and what you have apportioned and given', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 71, NULL, 'A clear promise was attached to this supplication. The Messenger of Allah said that whoever recites these words and acts upon them, Allah Almighty will give him what he has asked.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'a clear promise was attached to this supplication the messenger of allah said that whoever recites these words and acts upon them allah almighty will give him what he has asked', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 72, NULL, 'He also taught that marriage is not to be entered without its proper preliminaries. The Messenger of Allah said that every marriage in which there is no engagement is like a leprous hand.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he also taught that marriage is not to be entered without its proper preliminaries the messenger of allah said that every marriage in which there is no engagement is like a leprous hand', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 73, NULL, 'This same care for the right beginning was preserved by his descendants. When Jafar ibn Muhammad ibn Ali gave a woman in marriage, or when a marriage was contracted in his presence, he would open with words of praise and testimony, saying: "Praise be to Allah. We praise Him and seek refuge with Him from the evils of ourselves and the evils of our deeds. Whoever Allah guides, none can mislead, and whoever He leaves to stray, none can guide. I bear witness that there is no god but Allah alone, with no partner, and I bear witness that Muhammad is His servant and His messenger."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'this same care for the right beginning was preserved by his descendants when jafar ibn muhammad ibn ali gave a woman in marriage or when a marriage was contracted in his presence he would open with words of praise and testimony saying praise be to allah we praise him and seek refuge with him from the evils of ourselves and the evils of our deeds whoever allah guides none can mislead and whoever he leaves to stray none can guide i bear witness that there is no god but allah alone with no partner and i bear witness that muhammad is his servant and his messenger', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 74, NULL, 'He would then recite the words of Allah Almighty:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he would then recite the words of allah almighty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'marriage and the household', '6. Marriage and the Household', 75, NULL, '﴿ يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُم مِّن نَّفْسٍ وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَاءً ۚ وَاتَّقُوا اللَّهَ الَّذِي تَسَاءَلُونَ بِهِ وَالْأَرْحَامَ ۚ إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا ﴾', '', '﴿ يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُم مِّن نَّفْسٍ وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَاءً ۚ وَاتَّقُوا اللَّهَ الَّذِي تَسَاءَلُونَ بِهِ وَالْأَرْحَامَ ۚ إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا ﴾', NULL, 4, 1, 'mukhtasar ul asaar 2 6 marriage and the household', 'يا ايها الناس اتقوا ربكم الذي خلقكم من نفس واحده وخلق منها زوجها وبث منهما رجالا كثيرا ونساء واتقوا الله الذي تساءلون به والارحام ان الله كان عليكم رقيبا', 'يا ايها الناس اتقوا ربكم الذي خلقكم من نفس واحده وخلق منها زوجها وبث منهما رجالا كثيرا ونساء واتقوا الله الذي تساءلون به والارحام ان الله كان عليكم رقيبا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 76, NULL, 'He would also recite the words of Allah Almighty:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he would also recite the words of allah almighty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'marriage and the household', '6. Marriage and the Household', 77, NULL, '﴿ يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ ﴾', '', '﴿ يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ ﴾', NULL, 3, 102, 'mukhtasar ul asaar 2 6 marriage and the household', 'يا ايها الذين امنوا اتقوا الله حق تقاته ولا تموتن الا وانتم مسلمون', 'يا ايها الذين امنوا اتقوا الله حق تقاته ولا تموتن الا وانتم مسلمون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 78, NULL, 'Once marriage has been commended in this way and each party''s standing made known to the other, the contract is concluded. The one who performs it praises Allah as He deserves, prays upon the Prophet ﷺ and his family, and reflects on the virtue of marriage and its purpose — only then does he tie the knot. It is fitting that the husband disclose to his prospective companion whatever he can of his circumstances, so that she enters the union with full knowledge of his situation. If the contract is not preceded by a formal engagement, it remains permissible, though the khutbah is the better course.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'once marriage has been commended in this way and each partys standing made known to the other the contract is concluded the one who performs it praises allah as he deserves prays upon the prophet ﷺ and his family and reflects on the virtue of marriage and its purpose only then does he tie the knot it is fitting that the husband disclose to his prospective companion whatever he can of his circumstances so that she enters the union with full knowledge of his situation if the contract is not preceded by a formal engagement it remains permissible though the khutbah is the better course', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 79, NULL, 'The scholars forbade a formal proposal during the iddah, yet they permitted a discreet hint at marriage, in keeping with the words of Allah Almighty:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the scholars forbade a formal proposal during the iddah yet they permitted a discreet hint at marriage in keeping with the words of allah almighty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 80, NULL, '﴿ يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَقُولُوا قَوْلًا سَدِيدًا ۝ يُصْلِحْ لَكُمْ أَعْمَالَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ ۚ وَمَن يُطِعِ اللَّهَ وَرَسُولَهُ فَقَدْ فَازَ فَوْزًا عَظِيمًا ﴾', '', '﴿ يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَقُولُوا قَوْلًا سَدِيدًا ۝ يُصْلِحْ لَكُمْ أَعْمَالَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ ۚ وَمَن يُطِعِ اللَّهَ وَرَسُولَهُ فَقَدْ فَازَ فَوْزًا عَظِيمًا ﴾', NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'يا ايها الذين امنوا اتقوا الله وقولوا قولا سديدا يصلح لكم اعمالكم ويغفر لكم ذنوبكم ومن يطع الله ورسوله فقد فاز فوزا عظيما', 'يا ايها الذين امنوا اتقوا الله وقولوا قولا سديدا يصلح لكم اعمالكم ويغفر لكم ذنوبكم ومن يطع الله ورسوله فقد فاز فوزا عظيما');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'marriage and the household', '6. Marriage and the Household', 81, NULL, '﴿ وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا عَرَّضْتُم بِهِ مِنْ خِطْبَةِ النِّسَاءِ أَوْ أَكْنَنتُمْ فِي أَنفُسِكُمْ ۚ عَلِمَ اللَّهُ أَنَّكُمْ سَتَذْكُرُونَهُنَّ وَلَٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا إِلَّا أَن تَقُولُوا قَوْلًا مَّعْرُوفًا ۚ وَلَا تَعْزِمُوا عُقْدَةَ النِّكَاحِ حَتَّىٰ يَبْلُغَ الْكِتَابُ أَجَلَهُ ﴾', '', '﴿ وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا عَرَّضْتُم بِهِ مِنْ خِطْبَةِ النِّسَاءِ أَوْ أَكْنَنتُمْ فِي أَنفُسِكُمْ ۚ عَلِمَ اللَّهُ أَنَّكُمْ سَتَذْكُرُونَهُنَّ وَلَٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا إِلَّا أَن تَقُولُوا قَوْلًا مَّعْرُوفًا ۚ وَلَا تَعْزِمُوا عُقْدَةَ النِّكَاحِ حَتَّىٰ يَبْلُغَ الْكِتَابُ أَجَلَهُ ﴾', NULL, 2, 235, 'mukhtasar ul asaar 2 6 marriage and the household', 'ولا جناح عليكم فيما عرضتم به من خطبه النساء او اكننتم في انفسكم علم الله انكم ستذكرونهن ولكن لا تواعدوهن سرا الا ان تقولوا قولا معروفا ولا تعزموا عقده النكاح حتي يبلغ الكتاب اجله', 'ولا جناح عليكم فيما عرضتم به من خطبه النساء او اكننتم في انفسكم علم الله انكم ستذكرونهن ولكن لا تواعدوهن سرا الا ان تقولوا قولا معروفا ولا تعزموا عقده النكاح حتي يبلغ الكتاب اجله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 82, NULL, 'Jafar ibn Muhammad, commenting on the words of Allah Almighty — "do not make a secret commitment with them" — explained that this refers to a secret pledge of marriage. Gently broaching the subject and speaking goodly words, however, constitute the permitted form of hinting at the khutbah.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'jafar ibn muhammad commenting on the words of allah almighty do not make a secret commitment with them explained that this refers to a secret pledge of marriage gently broaching the subject and speaking goodly words however constitute the permitted form of hinting at the khutbah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 83, NULL, 'It is narrated that Abu Jafar Muhammad ibn Ali once visited Sakina bint Handhalah, a woman who had recently been separated from a cousin of hers — a man who had married her and then died. Abu Jafar greeted her and said, "How have you been, O daughter of Handhalah?"', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it is narrated that abu jafar muhammad ibn ali once visited sakina bint handhalah a woman who had recently been separated from a cousin of hers a man who had married her and then died abu jafar greeted her and said how have you been o daughter of handhalah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 84, NULL, 'She said, "May I be your ransom, O son of the Messenger of Allah."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'she said may i be your ransom o son of the messenger of allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 85, NULL, 'He said, "You know my kinship to the Messenger of Allah and his family, my standing with Ali, my right in Islam, and my honor among the Arabs."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he said you know my kinship to the messenger of allah and his family my standing with ali my right in islam and my honor among the arabs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 86, NULL, 'She said, "May Allah forgive you, O Abu Jafar. You propose to me while I am in my iddah!"', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'she said may allah forgive you o abu jafar you propose to me while i am in my iddah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 87, NULL, 'He said, "I have done no such thing. I have only made known my status and my standing. The Messenger of Allah and his family once visited Umm Salamah, the daughter of Umayyah ibn al-Mughirah al-Makhzumiyyah, while she was in her iddah from Abu Salamah, who was her cousin. He continued to speak of his standing to her until the impression of the mat showed upon his palm from the force with which he leaned upon his hand — and yet that was not a formal proposal."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he said i have done no such thing i have only made known my status and my standing the messenger of allah and his family once visited umm salamah the daughter of umayyah ibn al mughirah al makhzumiyyah while she was in her iddah from abu salamah who was her cousin he continued to speak of his standing to her until the impression of the mat showed upon his palm from the force with which he leaned upon his hand and yet that was not a formal proposal', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 88, NULL, 'The scholars held that it is recommended for one who wishes to marry to acquaint his prospective companion with his situation, so that she may come to know his circumstances.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the scholars held that it is recommended for one who wishes to marry to acquaint his prospective companion with his situation so that she may come to know his circumstances', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 89, NULL, 'It is related that when the Messenger of Allah (ﷺ and his family) proposed to her, Umm Salamah (رض) sent word to him saying, "O Messenger of Allah, I am an elderly woman, I have children, and I am a woman of great jealousy, and I fear there may be something in me of which you are unaware." The Messenger of Allah ﷺ sent back to her, "As for your age, you have mentioned it, and I am older than you. As for your children, they shall be among the children of the Messenger of Allah. And as for your jealousy, I shall pray to Allah Almighty to remove it from you." And he married her (ﷺ and his family).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it is related that when the messenger of allah ﷺ and his family proposed to her umm salamah رض sent word to him saying o messenger of allah i am an elderly woman i have children and i am a woman of great jealousy and i fear there may be something in me of which you are unaware the messenger of allah ﷺ sent back to her as for your age you have mentioned it and i am older than you as for your children they shall be among the children of the messenger of allah and as for your jealousy i shall pray to allah almighty to remove it from you and he married her ﷺ and his family', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 90, NULL, 'The Wedding Feast and the Consummation of Marriage', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the wedding feast and the consummation of marriage', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 91, NULL, 'The Imams of the family of the Messenger of Allah ﷺ are reported to have taught that the wedding feast takes four forms:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the imams of the family of the messenger of allah ﷺ are reported to have taught that the wedding feast takes four forms', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 92, NULL, 'The walimah — the food prepared when a husband first enters upon his wife. The khurs — the food of the aqiqah, prepared for the newborn on the seventh day; its obligations have already been addressed. The idhar — the food prepared at the circumcision of a boy. The wakirah — the food a man prepares upon returning from a journey, to which he then invites people.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the walimah the food prepared when a husband first enters upon his wife the khurs the food of the aqiqah prepared for the newborn on the seventh day its obligations have already been addressed the idhar the food prepared at the circumcision of a boy the wakirah the food a man prepares upon returning from a journey to which he then invites people', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 93, NULL, 'The Master (peace be upon him and his family) said that providing food at marriage is among the Sunnah of the Prophets. The Prophet ﷺ held a wedding feast for each of his wives upon consummating the marriage, and at some of those feasts he served al-hays — a food made of dates, ghee, and condensed milk. To one of his companions who had married, he said, "Give a feast, even if it be only with a sheep."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the master peace be upon him and his family said that providing food at marriage is among the sunnah of the prophets the prophet ﷺ held a wedding feast for each of his wives upon consummating the marriage and at some of those feasts he served al hays a food made of dates ghee and condensed milk to one of his companions who had married he said give a feast even if it be only with a sheep', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 94, NULL, 'He also said (peace be upon him and his family), "The feast of the first day is a duty, the feast of the second day is a kindness known among people, and what lies beyond that is ostentation and reputation-seeking."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he also said peace be upon him and his family the feast of the first day is a duty the feast of the second day is a kindness known among people and what lies beyond that is ostentation and reputation seeking', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 95, NULL, 'Abu Abdullah Jafar ibn Muhammad (may the prayers of Allah be upon them) was once invited to a feast on the first day and accepted; he was invited again on the second day and accepted. When a messenger arrived on the third day to invite him, he ordered the messenger turned away until he had gone from sight.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'abu abdullah jafar ibn muhammad may the prayers of allah be upon them was once invited to a feast on the first day and accepted he was invited again on the second day and accepted when a messenger arrived on the third day to invite him he ordered the messenger turned away until he had gone from sight', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 96, NULL, 'It was narrated from the Messenger of Allah (peace be upon him and his family) that he passed by Banu Zurayq and heard the sound of instruments and singing. He asked, "What is this?" They answered, "O Messenger of Allah, so-and-so has married so-and-so." He said, "He has completed his religion. This is marriage, not a clandestine affair — and there is no marriage in secret, until its smoke is seen and the sound of the tambourine is heard."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was narrated from the messenger of allah peace be upon him and his family that he passed by banu zurayq and heard the sound of instruments and singing he asked what is this they answered o messenger of allah so and so has married so and so he said he has completed his religion this is marriage not a clandestine affair and there is no marriage in secret until its smoke is seen and the sound of the tambourine is heard', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 97, NULL, 'He also said (peace be upon him and his family), "What distinguishes marriage from fornication is the beating of the tambourine."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he also said peace be upon him and his family what distinguishes marriage from fornication is the beating of the tambourine', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 98, NULL, 'It was further narrated from him (peace be upon him and his family) that on the night Fatimah was brought to Ali, he heard the beat of the tambourine and asked, "What is this?" Umm Salamah said, "O Messenger of Allah, this is Asma bint Umays beating the tambourine for Fatimah, lest she say within herself, My mother has died and there is no one to rejoice with me." The Messenger of Allah raised his hands toward the heavens and said, "O Allah, bring joy to Asma bint Umays as she has gladdened the daughter of Your Prophet." Then he called to her and said, "O Asma, what do you say when you beat the tambourine?" She replied, "O Messenger of Allah, by Allah I do not know what to say — I only wished to gladden her." He said, "Then say nothing indecent, but say: We have come to you, we have come to you; so greet us and we will greet you."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was further narrated from him peace be upon him and his family that on the night fatimah was brought to ali he heard the beat of the tambourine and asked what is this umm salamah said o messenger of allah this is asma bint umays beating the tambourine for fatimah lest she say within herself my mother has died and there is no one to rejoice with me the messenger of allah raised his hands toward the heavens and said o allah bring joy to asma bint umays as she has gladdened the daughter of your prophet then he called to her and said o asma what do you say when you beat the tambourine she replied o messenger of allah by allah i do not know what to say i only wished to gladden her he said then say nothing indecent but say we have come to you we have come to you so greet us and we will greet you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 99, NULL, 'Such speech, together with the beating of the tambourine and what resembles it, is what has been permitted at weddings and banquets. As for speech that carries vulgarity, the singing that accompanies it, and the instruments of diversion and the entrancing flutes that people of frivolity take up — those are disliked.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'such speech together with the beating of the tambourine and what resembles it is what has been permitted at weddings and banquets as for speech that carries vulgarity the singing that accompanies it and the instruments of diversion and the entrancing flutes that people of frivolity take up those are disliked', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 100, NULL, 'Al-Sadiq Jafar ibn Muhammad was asked about such things, and he recited the words of Allah Almighty:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'al sadiq jafar ibn muhammad was asked about such things and he recited the words of allah almighty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 101, NULL, '﴿ وَمَا خَلَقْنَا السَّمَاءَ وَالْأَرْضَ وَمَا بَيْنَهُمَا لَاعِبِينَ ۝ لَوْ أَرَدْنَا أَن نَّتَّخِذَ لَهْوًا لَّاتَّخَذْنَاهُ مِن لَّدُنَّا إِن كُنَّا فَاعِلِينَ ۝ بَلْ نَقْذِفُ بِالْحَقِّ عَلَى الْبَاطِلِ فَيَدْمَغُهُ فَإِذَا هُوَ زَاهِقٌ ۚ وَلَكُمُ الْوَيْلُ مِمَّا تَصِفُونَ ﴾', '', '﴿ وَمَا خَلَقْنَا السَّمَاءَ وَالْأَرْضَ وَمَا بَيْنَهُمَا لَاعِبِينَ ۝ لَوْ أَرَدْنَا أَن نَّتَّخِذَ لَهْوًا لَّاتَّخَذْنَاهُ مِن لَّدُنَّا إِن كُنَّا فَاعِلِينَ ۝ بَلْ نَقْذِفُ بِالْحَقِّ عَلَى الْبَاطِلِ فَيَدْمَغُهُ فَإِذَا هُوَ زَاهِقٌ ۚ وَلَكُمُ الْوَيْلُ مِمَّا تَصِفُونَ ﴾', NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'وما خلقنا السماء والارض وما بينهما لاعبين لو اردنا ان نتخذ لهوا لاتخذناه من لدنا ان كنا فاعلين بل نقذف بالحق علي الباطل فيدمغه فاذا هو زاهق ولكم الويل مما تصفون', 'وما خلقنا السماء والارض وما بينهما لاعبين لو اردنا ان نتخذ لهوا لاتخذناه من لدنا ان كنا فاعلين بل نقذف بالحق علي الباطل فيدمغه فاذا هو زاهق ولكم الويل مما تصفون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 102, NULL, 'It was narrated from him that he said, "Singing is a gathering upon which Allah Almighty does not look." It was also narrated that he was asked about the flute, and he said, "The Messenger of Allah ﷺ said: there are two voices that Allah Almighty detests — a wailing at the time of calamity, and a flute at the time of blessing."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was narrated from him that he said singing is a gathering upon which allah almighty does not look it was also narrated that he was asked about the flute and he said the messenger of allah ﷺ said there are two voices that allah almighty detests a wailing at the time of calamity and a flute at the time of blessing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 103, NULL, 'Narrations from him concerning the words of Allah Almighty,', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'narrations from him concerning the words of allah almighty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'marriage and the household', '6. Marriage and the Household', 104, NULL, '﴿ فَاجْتَنِبُوا الرِّجْسَ مِنَ الْأَوْثَانِ وَاجْتَنِبُوا قَوْلَ الزُّورِ ﴾', '', '﴿ فَاجْتَنِبُوا الرِّجْسَ مِنَ الْأَوْثَانِ وَاجْتَنِبُوا قَوْلَ الزُّورِ ﴾', NULL, 22, 30, 'mukhtasar ul asaar 2 6 marriage and the household', 'فاجتنبوا الرجس من الاوثان واجتنبوا قول الزور', 'فاجتنبوا الرجس من الاوثان واجتنبوا قول الزور');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 105, NULL, 'So avoid the abomination of idols, and avoid the false statement (al-Hajj: 30)', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'so avoid the abomination of idols and avoid the false statement al hajj 30', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'marriage and the household', '6. Marriage and the Household', 106, NULL, 'Luqman: 6وَمِنَ ٱلنَّاسِ مَن يَشْتَرِى لَهْوَ ٱلْحَدِيثِ', '', 'وَمِنَ ٱلنَّاسِ مَن يَشْتَرِى لَهْوَ ٱلْحَدِيثِ', 'Luqman: 6', 31, 6, 'mukhtasar ul asaar 2 6 marriage and the household', 'luqman 6ومن الناس من يشتري لهو الحديث', 'ومن الناس من يشتري لهو الحديث');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 107, NULL, 'record that "the abomination of idols" encompasses chess, and that "the false statement" encompasses singing. He said further, concerning the words of Allah Almighty, ﴿ وَمِنَ النَّاسِ مَن يَشْتَرِي لَهْوَ الْحَدِيثِ ﴾ And among the people is he who purchases idle talk (Luqman: 6), that this verse likewise refers to singing.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'record that the abomination of idols encompasses chess and that the false statement encompasses singing he said further concerning the words of allah almighty ومن الناس من يشتري لهو الحديث and among the people is he who purchases idle talk luqman 6 that this verse likewise refers to singing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 108, NULL, 'One of his companions reported: "I was in Madinah and came upon a place where singing was taking place, so I sat and listened. The following day I entered upon Abu Abdullah Jafar ibn Muhammad, and when I had taken my seat before him, he opened by reciting the words of Allah, exalted be His mention:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'one of his companions reported i was in madinah and came upon a place where singing was taking place so i sat and listened the following day i entered upon abu abdullah jafar ibn muhammad and when i had taken my seat before him he opened by reciting the words of allah exalted be his mention', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 109, NULL, '﴿ إِنَّ السَّمْعَ وَالْبَصَرَ وَالْفُؤَادَ كُلُّ أُولَٰئِكَ كَانَ عَنْهُ مَسْئُولًا ﴾', '', '﴿ إِنَّ السَّمْعَ وَالْبَصَرَ وَالْفُؤَادَ كُلُّ أُولَٰئِكَ كَانَ عَنْهُ مَسْئُولًا ﴾', NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'ان السمع والبصر والفواد كل اوليك كان عنه مسيولا', 'ان السمع والبصر والفواد كل اوليك كان عنه مسيولا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 110, NULL, 'Indeed, the hearing, the sight, and the heart: about all those one will be questioned. (al-Isra: 36)', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'indeed the hearing the sight and the heart about all those one will be questioned al isra 36', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 111, NULL, 'Then he looked at the companion and said, "You will be asked of your hearing what it heard, of your heart what it understood, and of your sight what it beheld."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'then he looked at the companion and said you will be asked of your hearing what it heard of your heart what it understood and of your sight what it beheld', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 112, NULL, 'It was also narrated from him that the sale of singing is not lawful, nor its purchase; that listening to it is hypocrisy, and teaching it is disbelief. It was further narrated that a delegation of his Shia once arrived from various towns and entered upon him. He asked them, "Where have you lodged?" They said, "O son of the Messenger of Allah, we lodged in a house, and when we drew near to the place we heard singing within it, so we sought another lodging but could not find one." He said, "Even so, be noble: keep your hearing far from listening to it and lending it your ear, for Allah — exalted is the One who speaks — says:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was also narrated from him that the sale of singing is not lawful nor its purchase that listening to it is hypocrisy and teaching it is disbelief it was further narrated that a delegation of his shia once arrived from various towns and entered upon him he asked them where have you lodged they said o son of the messenger of allah we lodged in a house and when we drew near to the place we heard singing within it so we sought another lodging but could not find one he said even so be noble keep your hearing far from listening to it and lending it your ear for allah exalted is the one who speaks says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'marriage and the household', '6. Marriage and the Household', 113, NULL, '﴿ وَالَّذِينَ لَا يَشْهَدُونَ الزُّورَ وَإِذَا مَرُّوا بِاللَّغْوِ مَرُّوا كِرَامًا ﴾', '', '﴿ وَالَّذِينَ لَا يَشْهَدُونَ الزُّورَ وَإِذَا مَرُّوا بِاللَّغْوِ مَرُّوا كِرَامًا ﴾', NULL, 25, 72, 'mukhtasar ul asaar 2 6 marriage and the household', 'والذين لا يشهدون الزور واذا مروا باللغو مروا كراما', 'والذين لا يشهدون الزور واذا مروا باللغو مروا كراما');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 114, NULL, 'And those who do not bear witness to falsehood, and when they pass by idle talk, they pass by with dignity. (al-Furqan: 72)"', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'and those who do not bear witness to falsehood and when they pass by idle talk they pass by with dignity al furqan 72', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 115, NULL, 'It was narrated from him that he said, "My father passed by me one day when I was a boy, and I had stopped to listen to two pipers. He took me by the hand and said, Step away; do not be of those who gloated over Adam (ع). I said, How is that, O my father? He said, All the amusement, play, and singing that you see was devised by Iblis to gloat over Adam when he was expelled from Paradise."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was narrated from him that he said my father passed by me one day when i was a boy and i had stopped to listen to two pipers he took me by the hand and said step away do not be of those who gloated over adam ع i said how is that o my father he said all the amusement play and singing that you see was devised by iblis to gloat over adam when he was expelled from paradise', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 116, NULL, 'It was narrated from him that he said, "The house in which singing takes place is a house in which no calamity is met with comfort, no supplication is answered, and no angel enters."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was narrated from him that he said the house in which singing takes place is a house in which no calamity is met with comfort no supplication is answered and no angel enters', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 117, NULL, 'It was narrated from him that he said, "Singing causes hypocrisy to grow in the heart as water causes the date palm to bring forth its spathe."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was narrated from him that he said singing causes hypocrisy to grow in the heart as water causes the date palm to bring forth its spathe', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 118, NULL, 'It was narrated from him that he said, "Whoever has the lute played in his house for forty days, Allah sets over him a devil called al-Anqad, who leaves no limb of his without sitting upon it; and when he is thus afflicted, his sense of shame is stripped from him, and he no longer cares what he says or what is said to him."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was narrated from him that he said whoever has the lute played in his house for forty days allah sets over him a devil called al anqad who leaves no limb of his without sitting upon it and when he is thus afflicted his sense of shame is stripped from him and he no longer cares what he says or what is said to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'marriage and the household', '6. Marriage and the Household', 119, NULL, 'Luqman: 6وَمِنَ ٱلنَّاسِ مَن يَشْتَرِى لَهْوَ ٱلْحَدِيثِ', '', 'وَمِنَ ٱلنَّاسِ مَن يَشْتَرِى لَهْوَ ٱلْحَدِيثِ', 'Luqman: 6', 31, 6, 'mukhtasar ul asaar 2 6 marriage and the household', 'luqman 6ومن الناس من يشتري لهو الحديث', 'ومن الناس من يشتري لهو الحديث');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 120, NULL, 'وَمِنَ النَّاسِ مَن يَشْتَرِي لَهْوَ الْحَدِيثِ ﴾ And among the people is he who purchases idle talk (Luqman: 6).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'ومن الناس من يشتري لهو الحديث and among the people is he who purchases idle talk luqman 6', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 121, NULL, 'It was also narrated from him that singing bequeaths hypocrisy and brings on poverty.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was also narrated from him that singing bequeaths hypocrisy and brings on poverty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 122, NULL, 'It was reported to Jafar ibn Muhammad that a man of his Shia had visited an acquaintance, and that the host had brought out a slave-girl who played and sang before the guest. Jafar ibn Muhammad said, "Did he not fear that the command of Allah Almighty might come upon him in such a state — in a gathering upon which Allah does not look?"', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was reported to jafar ibn muhammad that a man of his shia had visited an acquaintance and that the host had brought out a slave girl who played and sang before the guest jafar ibn muhammad said did he not fear that the command of allah almighty might come upon him in such a state in a gathering upon which allah does not look', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 123, NULL, 'It was also narrated from him that a man asked him about singing. He said to the man, "Tell me: when Allah Almighty separates truth from falsehood, where do you see singing falling?"', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was also narrated from him that a man asked him about singing he said to the man tell me when allah almighty separates truth from falsehood where do you see singing falling', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 124, NULL, 'The man said, "O son of the Messenger of Allah, I see it only with falsehood."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the man said o son of the messenger of allah i see it only with falsehood', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 125, NULL, 'He said, "Then you have judged it yourself. Leave it, for there is no good in it, and it is among those things for which Allah Almighty has promised the Fire." Then he recited: ﴿ وَمِنَ النَّاسِ مَن يَشْتَرِي لَهْوَ الْحَدِيثِ ﴾ And among the people is he who purchases idle talk (Luqman: 6).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he said then you have judged it yourself leave it for there is no good in it and it is among those things for which allah almighty has promised the fire then he recited ومن الناس من يشتري لهو الحديث and among the people is he who purchases idle talk luqman 6', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 126, NULL, 'The Master also related that the Messenger of Allah (ع and his family) forbade his community al-zafn, the flute, the drums, and the reed-pipes. He further related that a man who had broken a lute was once brought before Ali, and Ali approved his deed and ruled that no liability attached to the breaking of it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the master also related that the messenger of allah ع and his family forbade his community al zafn the flute the drums and the reed pipes he further related that a man who had broken a lute was once brought before ali and ali approved his deed and ruled that no liability attached to the breaking of it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 127, NULL, 'All of this points to the prohibition of frivolity and of listening to singing, flutes, lyres, and the like when they are taken up for diversion. What is used in war, however — in the marshaling and parading of troops — stands apart. This includes what is raised before the Imams and the commanders of armies: the beating of drums and shields, and the blowing of horns and pipes not taken for enjoyment or amusement. Such things fall outside what has been forbidden and are, in their proper place, among what is recommended.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'all of this points to the prohibition of frivolity and of listening to singing flutes lyres and the like when they are taken up for diversion what is used in war however in the marshaling and parading of troops stands apart this includes what is raised before the imams and the commanders of armies the beating of drums and shields and the blowing of horns and pipes not taken for enjoyment or amusement such things fall outside what has been forbidden and are in their proper place among what is recommended', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 128, NULL, 'A narration from the Messenger of Allah (ع and his family) bears this out: he passed by a company of Abyssinians beating their drums, and he said, "Carry on, O sons of Arfidah, that the Jews may know there is breadth in our religion."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'a narration from the messenger of allah ع and his family bears this out he passed by a company of abyssinians beating their drums and he said carry on o sons of arfidah that the jews may know there is breadth in our religion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 129, NULL, 'If someone should ask why, in the lands where the Imams hold authority (may the prayers of Allah be upon them), one hears and sees the very instruments of diversion they have forbidden, the answer is that this is no greater a problem than the indecencies Allah Almighty has forbidden and made unlawful, which people nonetheless commit behind their doors and curtains. Allah has commanded that the prescribed penalties be carried out for those indecencies upon which He has commanded such penalties — in what appears openly and is witnessed by witnesses. What remains hidden He alone, glorified be He, holds knowledge of, and He has reserved to Himself both its punishment and its pardon, advancing what He wills and deferring what He defers. It is well known and widely established among all people that the Imams denounced these things upon those who did them and withheld any license for them, holding that this is not a matter for which the hadd is due, but rather one calling for denunciation and prohibition.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'if someone should ask why in the lands where the imams hold authority may the prayers of allah be upon them one hears and sees the very instruments of diversion they have forbidden the answer is that this is no greater a problem than the indecencies allah almighty has forbidden and made unlawful which people nonetheless commit behind their doors and curtains allah has commanded that the prescribed penalties be carried out for those indecencies upon which he has commanded such penalties in what appears openly and is witnessed by witnesses what remains hidden he alone glorified be he holds knowledge of and he has reserved to himself both its punishment and its pardon advancing what he wills and deferring what he defers it is well known and widely established among all people that the imams denounced these things upon those who did them and withheld any license for them holding that this is not a matter for which the hadd is due but rather one calling for denunciation and prohibition', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 130, NULL, 'It was narrated from the Messenger of Allah (ع and his family) that he said, "Bring your brides in by night, and give the feast by day." It was also narrated from him that he said, "There is no staying awake save in three: a vigil with the Quran, the seeking of knowledge, or the bringing of a bride to her husband." And it was narrated from him that a man should make himself ready for his wife as he would wish her to make herself ready for him. Jafar ibn Muhammad said that this means cleanliness.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was narrated from the messenger of allah ع and his family that he said bring your brides in by night and give the feast by day it was also narrated from him that he said there is no staying awake save in three a vigil with the quran the seeking of knowledge or the bringing of a bride to her husband and it was narrated from him that a man should make himself ready for his wife as he would wish her to make herself ready for him jafar ibn muhammad said that this means cleanliness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 131, NULL, 'When a man''s wife is brought to him and she enters upon him, he should pray two rakahs, then place his hand upon her forelock and say, "O Allah, bless me in my wife and bless her in me; in whatever You have joined between us, join us in goodness, felicity, and blessing; and if You decree a parting, make it a parting toward every good." Then, when he sits beside her, he should wipe her forelock and say, "Praise be to Allah, who guided my straying, enriched my poverty, raised up my burden, gave might to my lowliness, sheltered my dependents, gave a spouse to my solitude, bore up my step, served my need, brought company to my loneliness, and lifted my standing; a praise wholesome, abundant, and blessed, for what You have granted, O Lord, and for what You have apportioned, and for what You have honored."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'when a mans wife is brought to him and she enters upon him he should pray two rakahs then place his hand upon her forelock and say o allah bless me in my wife and bless her in me in whatever you have joined between us join us in goodness felicity and blessing and if you decree a parting make it a parting toward every good then when he sits beside her he should wipe her forelock and say praise be to allah who guided my straying enriched my poverty raised up my burden gave might to my lowliness sheltered my dependents gave a spouse to my solitude bore up my step served my need brought company to my loneliness and lifted my standing a praise wholesome abundant and blessed for what you have granted o lord and for what you have apportioned and for what you have honored', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 132, NULL, 'Abu Jafar Muhammad ibn Ali said that the woman too is commanded to be in a state of ablution on the night she is brought as a bride. When her husband prays, she prays; when he supplicates, she says amen. He further said that one should increase in supplication, sending prayers upon the Messenger of Allah (ع and his family) at the beginning, the middle, and the end, and saying within it, "O Allah, grant me her affection, her warmth, her contentment with me and my contentment with her, and join us in the best of unions and the gentlest of bonds, for You love the lawful and hate the unlawful."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'abu jafar muhammad ibn ali said that the woman too is commanded to be in a state of ablution on the night she is brought as a bride when her husband prays she prays when he supplicates she says amen he further said that one should increase in supplication sending prayers upon the messenger of allah ع and his family at the beginning the middle and the end and saying within it o allah grant me her affection her warmth her contentment with me and my contentment with her and join us in the best of unions and the gentlest of bonds for you love the lawful and hate the unlawful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 133, NULL, 'Jafar ibn Muhammad said that when a man wishes to come to his wife, he should say, "O Allah, if You decree from me this day a child, then make him purely Yours, and grant the devil no share in him, no portion and no part; indeed You are powerful over all things." It was narrated from the Messenger of Allah and his family that he said, "When one of you comes to his wife, let him not hasten her," and that when he is with her, he should deal kindly and truly with her. He and his family also forbade that a man be intimate with a free woman while another woman is present in the room. Abu Jafar Muhammad ibn Ali held that there is no harm in that with a bondwoman, and Jafar ibn Muhammad said the same. It was further narrated from Ali that he said it does not befit a man to be intimate with his wife in the presence of another man.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'jafar ibn muhammad said that when a man wishes to come to his wife he should say o allah if you decree from me this day a child then make him purely yours and grant the devil no share in him no portion and no part indeed you are powerful over all things it was narrated from the messenger of allah and his family that he said when one of you comes to his wife let him not hasten her and that when he is with her he should deal kindly and truly with her he and his family also forbade that a man be intimate with a free woman while another woman is present in the room abu jafar muhammad ibn ali held that there is no harm in that with a bondwoman and jafar ibn muhammad said the same it was further narrated from ali that he said it does not befit a man to be intimate with his wife in the presence of another man', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 134, NULL, 'Jafar ibn Muhammad also said that when a man wishes to come to his wife, he should say: «اَللَّهُمَّ إِنْ قَضَيْتَ مِنِّي الْيَوْمَ خَلْقًا فَاجْعَلْهُ لَكَ خَالِصًا، وَلَا تَجْعَلْ لِلشَّيْطَانِ فِيهِ شِرْكًا وَلَا حَظًّا وَلَا نَصِيبًا، إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ» — "O Allah, if You decree from me today a creation, make it purely for You, and grant the devil in it no share, no portion, and no part, for You are able to do all things." It was also related from the Messenger of Allah and his family that he said: «إِذَا أَتَىٰ أَحَدُكُمُ امْرَأَتَهُ فَلَا يُعْجِلْهَا، وَإِذَا وَاقَعَهَا فَلْيَصْدُقْهَا» — "When one of you comes to his wife, let him not hasten her, and when he is with her, let him deal truthfully with her."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'jafar ibn muhammad also said that when a man wishes to come to his wife he should say اللهم ان قضيت مني اليوم خلقا فاجعله لك خالصا ولا تجعل للشيطان فيه شركا ولا حظا ولا نصيبا انك علي كل شيء قدير o allah if you decree from me today a creation make it purely for you and grant the devil in it no share no portion and no part for you are able to do all things it was also related from the messenger of allah and his family that he said اذا اتي احدكم امراته فلا يعجلها واذا واقعها فليصدقها when one of you comes to his wife let him not hasten her and when he is with her let him deal truthfully with her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 135, NULL, 'The Imams permitted a man to come to a free wife even while another wife was present in the house. Abu Jafar Muhammad ibn Ali, may Allah''s blessings be upon him, held that there was no objection to this in the case of a bondwoman, and Jafar ibn Muhammad said the same. It was related from Ali that a man should not come to his wife while facing the qibla, and he further said that gazing during intercourse brings on blindness. The Prophet, his family, and the Imams of his progeny would turn their faces away whenever an animal was being mounted upon the road.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the imams permitted a man to come to a free wife even while another wife was present in the house abu jafar muhammad ibn ali may allahs blessings be upon him held that there was no objection to this in the case of a bondwoman and jafar ibn muhammad said the same it was related from ali that a man should not come to his wife while facing the qibla and he further said that gazing during intercourse brings on blindness the prophet his family and the imams of his progeny would turn their faces away whenever an animal was being mounted upon the road', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 136, NULL, 'He named a hidden form of infanticide — الْوَأْدُ الْخَفِيُّ: a man comes to a woman and, sensing the approach of emission, withdraws and spills elsewhere. Of this he said, "So do not do that." He also said that the Messenger of Allah, and his family, forbade withdrawal from a free woman except with her leave, and from a bondwoman taken in marriage except with the leave of her master. Ali said that a man may withdraw from his own bondwoman as he wishes, and Jafar ibn Muhammad said the same.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he named a hidden form of infanticide الواد الخفي a man comes to a woman and sensing the approach of emission withdraws and spills elsewhere of this he said so do not do that he also said that the messenger of allah and his family forbade withdrawal from a free woman except with her leave and from a bondwoman taken in marriage except with the leave of her master ali said that a man may withdraw from his own bondwoman as he wishes and jafar ibn muhammad said the same', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 137, NULL, 'From Ali by way of Jafar ibn Muhammad: a man should not lie between two free women, though he may lie between two bondwomen. He should not look upon the awrah of a free woman, nor expose his own awrah to her.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'from ali by way of jafar ibn muhammad a man should not lie between two free women though he may lie between two bondwomen he should not look upon the awrah of a free woman nor expose his own awrah to her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 138, NULL, 'Abu Jafar Muhammad ibn Ali said that intercourse is disliked at the following times:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'abu jafar muhammad ibn ali said that intercourse is disliked at the following times', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 139, NULL, 'From the breaking of dawn until sunrise, and from the setting of the sun until the fading of twilight On the night in which the moon is eclipsed, and on the day in which the sun is eclipsed On the day and night in which the earth quakes When the yellow, the black, and the red winds blow', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'from the breaking of dawn until sunrise and from the setting of the sun until the fading of twilight on the night in which the moon is eclipsed and on the day in which the sun is eclipsed on the day and night in which the earth quakes when the yellow the black and the red winds blow', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 140, NULL, 'The Messenger of Allah and his family spent a night with one of his wives on a night when the moon was eclipsed, and nothing passed between them. It was said, "O Messenger of Allah, what is this coldness?" He said, "It is no coldness, but this was a sign, and I was loath to take my pleasure on such a night, that I might not be among those whom Allah, mighty and majestic, has rebuked in His Book where He says: «وَإِن يَرَوْا كِسْفًا مِّنَ السَّمَاءِ سَاقِطًا يَقُولُوا سَحَابٌ مَّرْكُومٌ» And were they to see a fragment falling from the sky, they would say: a heaped-up cloud."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the messenger of allah and his family spent a night with one of his wives on a night when the moon was eclipsed and nothing passed between them it was said o messenger of allah what is this coldness he said it is no coldness but this was a sign and i was loath to take my pleasure on such a night that i might not be among those whom allah mighty and majestic has rebuked in his book where he says وان يروا كسفا من السماء ساقطا يقولوا سحاب مركوم and were they to see a fragment falling from the sky they would say a heaped up cloud', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 141, NULL, 'Then Abu Jafar, may Allah''s blessings be upon him, said: By Him who sent Muhammad with prophethood, singled him out with the message, and honored him with nobility, none of you comes to his wife at any of these disliked times and is then granted offspring in whom he sees the delight of his eye.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'then abu jafar may allahs blessings be upon him said by him who sent muhammad with prophethood singled him out with the message and honored him with nobility none of you comes to his wife at any of these disliked times and is then granted offspring in whom he sees the delight of his eye', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 142, NULL, 'From Ali, may Allah''s blessings be upon him: a slave girl under nine years of age is not to be approached; if a man does so and she is harmed, he is liable. Jafar ibn Muhammad, may Allah''s blessings be upon him and his family, said that if a man marries a young girl, he does not enter upon her until she has completed nine years from the day of her birth.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'from ali may allahs blessings be upon him a slave girl under nine years of age is not to be approached if a man does so and she is harmed he is liable jafar ibn muhammad may allahs blessings be upon him and his family said that if a man marries a young girl he does not enter upon her until she has completed nine years from the day of her birth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 143, NULL, 'It was also related from Ali, may Allah bless him and grant him peace, that he disliked approaching women in their hinder parts and used to forbid it, citing the words of Allah, mighty and majestic, that one may come to them only «فِي الْفُرُوجِ مِنْ قُبُلٍ أَوْ دُبُرٍ» — in the place of tilth, whether from before or from behind. From the Messenger of Allah and his family it was related that he said: «لَا يَخْلُو رَجُلٌ بِامْرَأَةٍ غَيْرِ ذَاتِ مَحْرَمٍ مِنْهُ إِلَّا كَانَ الشَّيْطَانُ ثَالِثَهُمَا» — "No man is alone with a woman who is not his mahram but that the devil is the third of them." He forbade conversing with women other than one''s wives and one''s mahrams.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was also related from ali may allah bless him and grant him peace that he disliked approaching women in their hinder parts and used to forbid it citing the words of allah mighty and majestic that one may come to them only في الفروج من قبل او دبر in the place of tilth whether from before or from behind from the messenger of allah and his family it was related that he said لا يخلو رجل بامراه غير ذات محرم منه الا كان الشيطان ثالثهما no man is alone with a woman who is not his mahram but that the devil is the third of them he forbade conversing with women other than ones wives and ones mahrams', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 144, NULL, 'Jafar ibn Muhammad, may Allah''s blessings be upon him, said: «حَدِيثُ النِّسَاءِ يُورِثُ النِّسْيَانَ وَيُزِيغُ الْقَلْبَ وَهُوَ مِنْ مَصَائِدِ الشَّيْطَانِ» — "Idle talk with women breeds forgetfulness and makes the heart swerve, and it is among the snares of the devil."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'jafar ibn muhammad may allahs blessings be upon him said حديث النساء يورث النسيان ويزيغ القلب وهو من مصايد الشيطان idle talk with women breeds forgetfulness and makes the heart swerve and it is among the snares of the devil', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'marriage and the household', '6. Marriage and the Household', 145, NULL, 'An-Nisa: 4فَإِن طِبْنَ لَكُمْ عَن شَىْءٍۢ مِّنْهُ', '', 'فَإِن طِبْنَ لَكُمْ عَن شَىْءٍۢ مِّنْهُ', 'An-Nisa: 4', 4, 4, 'mukhtasar ul asaar 2 6 marriage and the household', 'an nisa 4فان طبن لكم عن شيء منه', 'فان طبن لكم عن شيء منه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 146, NULL, 'The Messenger of Allah, upon him and his family be peace, said: «اِتَّقُوا اللَّهَ فِي النِّسَاءِ، فَإِنَّهُنَّ عِيٌّ وَعَوْرَةٌ، وَإِنَّكُمُ اسْتَحْلَلْتُمُوهُنَّ بِأَمَانَةِ اللَّهِ» — "Fear Allah concerning women, for they are weak of speech and are a thing to be covered, and you have made them lawful to you by the trust of Allah."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the messenger of allah upon him and his family be peace said اتقوا الله في النساء فانهن عي وعوره وانكم استحللتموهن بامانه الله fear allah concerning women for they are weak of speech and are a thing to be covered and you have made them lawful to you by the trust of allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 147, NULL, 'Their weakness, he explained, calls for restraint in speech toward them, and what is to be covered must be sheltered within the home. Women are not to be lodged in upper rooms, nor taught writing — but they are to be taught Surat al-Nur.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'their weakness he explained calls for restraint in speech toward them and what is to be covered must be sheltered within the home women are not to be lodged in upper rooms nor taught writing but they are to be taught surat al nur', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 148, NULL, 'It is also related from him, upon him and his family be peace: «نِعْمَ شُغْلُ الْمَرْأَةِ الْمُؤْمِنَةِ الْمِغْزَلُ» — "How excellent an occupation for a believing woman is the spindle."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it is also related from him upon him and his family be peace نعم شغل المراه المومنه المغزل how excellent an occupation for a believing woman is the spindle', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 149, NULL, 'And from him likewise: when he took the pledge from women, he required of them that they would not speak with men other than their husbands and their mahrams.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'and from him likewise when he took the pledge from women he required of them that they would not speak with men other than their husbands and their mahrams', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 150, NULL, 'It was also related that he forbade women to look upon men, and that a woman should not leave her house without her husband''s leave — not even for the bath, save out of necessity. One day he said to his companions, "What is the woman?" They said, "An awrah, O Messenger of Allah." He said, "Yes." Then he asked, "And when is she nearest to her Lord?" They had no answer to give. Ali mentioned this to Fatimah, may Allah''s blessings be upon her, and she said, "Return to him and say: O Messenger of Allah, the nearest a woman is to her Lord is when she keeps to the innermost of her house." He went and informed the Prophet and his family, who said, "This is from you, O Ali." He replied, "No, O Messenger of Allah, rather it was Fatimah who said it." The Messenger of Allah, upon him and his family be peace, said, "She has spoken truly; «إِنَّهَا بِضْعَةٌ مِنِّي» indeed she is a part of me."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was also related that he forbade women to look upon men and that a woman should not leave her house without her husbands leave not even for the bath save out of necessity one day he said to his companions what is the woman they said an awrah o messenger of allah he said yes then he asked and when is she nearest to her lord they had no answer to give ali mentioned this to fatimah may allahs blessings be upon her and she said return to him and say o messenger of allah the nearest a woman is to her lord is when she keeps to the innermost of her house he went and informed the prophet and his family who said this is from you o ali he replied no o messenger of allah rather it was fatimah who said it the messenger of allah upon him and his family be peace said she has spoken truly انها بضعه مني indeed she is a part of me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 151, NULL, 'From the Messenger of Allah and his family, the following prohibitions are related:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'from the messenger of allah and his family the following prohibitions are related', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 152, NULL, 'He forbade a woman to walk unclothed before her husband, and forbade a man to be unclothed before her. He forbade women to dress their hair with wine or to apply its dregs. He forbade women to imitate men and men to imitate women, and he cursed whoever did so. He said, "Any woman who perfumes herself, let her not leave her house, nor attend the prayer with us." He forbade women, when walking behind men, to take the middle of the road alongside them, saying, "Women have no portion of the middle of the road." He forbade a woman, when going out, to wear a garment that draws notice, to adorn herself with anything that makes a sound, or to strike her foot so that the chime of her anklet is heard. He forbade women from open display, from wailing, and from raising the voice except out of necessity — and from conversing freely with men, and from spending the night away from their homes. He forbade the giving of greeting to women. He said that a man should not touch another man unless there is a garment between them, nor a woman another woman unless there is a garment between them.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he forbade a woman to walk unclothed before her husband and forbade a man to be unclothed before her he forbade women to dress their hair with wine or to apply its dregs he forbade women to imitate men and men to imitate women and he cursed whoever did so he said any woman who perfumes herself let her not leave her house nor attend the prayer with us he forbade women when walking behind men to take the middle of the road alongside them saying women have no portion of the middle of the road he forbade a woman when going out to wear a garment that draws notice to adorn herself with anything that makes a sound or to strike her foot so that the chime of her anklet is heard he forbade women from open display from wailing and from raising the voice except out of necessity and from conversing freely with men and from spending the night away from their homes he forbade the giving of greeting to women he said that a man should not touch another man unless there is a garment between them nor a woman another woman unless there is a garment between them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 153, NULL, 'A woman came to him and said, "O Messenger of Allah, I have a husband who is harsh of nature, and I have worked something to turn his affection toward me." The Messenger of Allah said to her, "Fie upon you! You have sullied your religion, and the angels of heaven and the angels of earth have cursed you."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'a woman came to him and said o messenger of allah i have a husband who is harsh of nature and i have worked something to turn his affection toward me the messenger of allah said to her fie upon you you have sullied your religion and the angels of heaven and the angels of earth have cursed you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 154, NULL, 'He also said: «لَوْ كُنْتُ آمِرًا أَحَدًا أَنْ يَسْجُدَ لِأَحَدٍ لَأَمَرْتُ الْمَرْأَةَ أَنْ تَسْجُدَ لِزَوْجِهَا» — "Had I been commanding anyone to prostrate to another, I would have commanded the woman to prostrate to her husband."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he also said لو كنت امرا احدا ان يسجد لاحد لامرت المراه ان تسجد لزوجها had i been commanding anyone to prostrate to another i would have commanded the woman to prostrate to her husband', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 155, NULL, 'He forbade a woman to withhold herself from her husband when he summoned her, and to deny him her help and her labor. He said, "The best thing with which a woman adorns herself is the fear of Allah and obedience to her husband."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he forbade a woman to withhold herself from her husband when he summoned her and to deny him her help and her labor he said the best thing with which a woman adorns herself is the fear of allah and obedience to her husband', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 156, NULL, 'When a woman knows her Lord, believes in Him and in His Messenger, acknowledges the merit of the People of the House of her Prophet, performs the five prayers, fasts the month of Ramadan, guards her chastity, and obeys her husband, she may enter Paradise by whichever of its gates she wishes.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'when a woman knows her lord believes in him and in his messenger acknowledges the merit of the people of the house of her prophet performs the five prayers fasts the month of ramadan guards her chastity and obeys her husband she may enter paradise by whichever of its gates she wishes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 157, NULL, 'A woman once sent word to him saying, "O Messenger of Allah, my husband has ordered me not to go out, near or far, until he returns from his journey; and my father is in the market. Shall I go out to him?" The Messenger of Allah said to her, "Sit in your house and obey your husband." She did so, and her father died. The Messenger of Allah, peace be upon him and his family, then sent word to her saying, "Truly Allah, mighty and majestic, has forgiven your father on account of your obedience to your husband."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'a woman once sent word to him saying o messenger of allah my husband has ordered me not to go out near or far until he returns from his journey and my father is in the market shall i go out to him the messenger of allah said to her sit in your house and obey your husband she did so and her father died the messenger of allah peace be upon him and his family then sent word to her saying truly allah mighty and majestic has forgiven your father on account of your obedience to your husband', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 158, NULL, 'A woman put a question to him, may Allah''s blessings be upon him and his family: "O Messenger of Allah, what is the right of the husband over the wife?"', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'a woman put a question to him may allahs blessings be upon him and his family o messenger of allah what is the right of the husband over the wife', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 159, NULL, 'He said, "She must not give in charity from his house without his leave, nor deny him herself even on the saddle''s back, nor fast a voluntary day without his leave, nor leave her house without his leave. And if she goes out without his leave, the angels of heaven, the angels of earth, the angels of mercy, and the angels of wrath curse her until she returns."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he said she must not give in charity from his house without his leave nor deny him herself even on the saddles back nor fast a voluntary day without his leave nor leave her house without his leave and if she goes out without his leave the angels of heaven the angels of earth the angels of mercy and the angels of wrath curse her until she returns', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 160, NULL, 'She said, "O Messenger of Allah, who has the greatest right over a man?"', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'she said o messenger of allah who has the greatest right over a man', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 161, NULL, 'He said, "His parents."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he said his parents', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 162, NULL, '"And who has the greatest right over a woman?"', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'and who has the greatest right over a woman', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 163, NULL, 'He said, "Her husband."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he said her husband', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 164, NULL, 'She said, "O Messenger of Allah, then have I no right over him to match what he has over me?"', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'she said o messenger of allah then have i no right over him to match what he has over me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 165, NULL, 'He said, "No, not even one in a hundred."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he said no not even one in a hundred', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 166, NULL, 'It was also related that he assigned to his daughter Fatimah, may Allah''s blessings be upon her, responsibility for the affairs within the house, and assigned to Ali, may Allah''s blessings be upon him, responsibility for the affairs outside it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was also related that he assigned to his daughter fatimah may allahs blessings be upon her responsibility for the affairs within the house and assigned to ali may allahs blessings be upon him responsibility for the affairs outside it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 167, NULL, 'Jafar ibn Muhammad, may Allah''s blessings be upon him, was asked what constituted the right of a wife over her husband — what, if fulfilled, would make the husband a doer of good. He said that the husband feeds her, clothes her, and when she wrongs him, he pardons her. He added that his father, may Allah''s blessings be upon him, had a wife who used to vex him, and he would forgive her, citing the words of the Messenger of Allah and his family:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'jafar ibn muhammad may allahs blessings be upon him was asked what constituted the right of a wife over her husband what if fulfilled would make the husband a doer of good he said that the husband feeds her clothes her and when she wrongs him he pardons her he added that his father may allahs blessings be upon him had a wife who used to vex him and he would forgive her citing the words of the messenger of allah and his family', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 168, NULL, '«اَلْمَرْأَةُ كَالضِّلَعِ، إِنْ تَرَكْتَهَا اِنْتَفَعْتَ بِهَا، وَإِنْ أَقَمْتَهَا كَسَرْتَهَا»', '', '«اَلْمَرْأَةُ كَالضِّلَعِ، إِنْ تَرَكْتَهَا اِنْتَفَعْتَ بِهَا، وَإِنْ أَقَمْتَهَا كَسَرْتَهَا»', NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'المراه كالضلع ان تركتها انتفعت بها وان اقمتها كسرتها', 'المراه كالضلع ان تركتها انتفعت بها وان اقمتها كسرتها');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 169, NULL, '"The woman is like a rib: if you leave it be, you take benefit from it, and if you try to straighten it, you break it."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the woman is like a rib if you leave it be you take benefit from it and if you try to straighten it you break it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 170, NULL, 'It was then said to him, "But the woman is jealous about her husband." He said, "That is love."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was then said to him but the woman is jealous about her husband he said that is love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 171, NULL, 'He was also asked about a man who turns away from his wife because worship, fasting, and prayer occupy him entirely. He said that the wife of Uthman ibn Mazun came to the Messenger of Allah and said, "O Messenger of Allah, Uthman fasts the day and stands the night in prayer." The Messenger of Allah and his family understood what she intended. He went out to the mosque, where he found Uthman ibn Mazun standing in prayer, and said to him, "O Uthman, Allah, mighty and majestic, did not send me with monasticism; He sent me with the upright way. Whoever loves my nature, let him follow my Sunnah, and among my Sunnah is marriage." The Messenger of Allah and his family also forbade the striking of women where it is not warranted.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he was also asked about a man who turns away from his wife because worship fasting and prayer occupy him entirely he said that the wife of uthman ibn mazun came to the messenger of allah and said o messenger of allah uthman fasts the day and stands the night in prayer the messenger of allah and his family understood what she intended he went out to the mosque where he found uthman ibn mazun standing in prayer and said to him o uthman allah mighty and majestic did not send me with monasticism he sent me with the upright way whoever loves my nature let him follow my sunnah and among my sunnah is marriage the messenger of allah and his family also forbade the striking of women where it is not warranted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 172, NULL, 'A man of the Ansar came to the Messenger of Allah and his family, bringing his daughter, and said, "O Messenger of Allah, her husband has struck her; grant her retaliation against him." The Messenger of Allah and his family granted her that.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'a man of the ansar came to the messenger of allah and his family bringing his daughter and said o messenger of allah her husband has struck her grant her retaliation against him the messenger of allah and his family granted her that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 173, NULL, 'Then Allah, mighty and majestic, sent down: «الرِّجَالُ قَوَّامُونَ عَلَى النِّسَاءِ بِمَا فَضَّلَ اللَّهُ بَعْضَهُمْ عَلَىٰ بَعْضٍ وَبِمَا أَنفَقُوا مِنْ أَمْوَالِهِمْ ۚ فَالصَّالِحَاتُ قَانِتَاتٌ حَافِظَاتٌ لِّلْغَيْبِ بِمَا حَفِظَ اللَّهُ ۚ وَاللَّاتِي تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَاهْجُرُوهُنَّ فِي الْمَضَاجِعِ وَاضْرِبُوهُنَّ ۖ فَإِنْ أَطَعْنَكُمْ فَلَا تَبْغُوا عَلَيْهِنَّ سَبِيلًا ۗ إِنَّ اللَّهَ كَانَ عَلِيًّا كَبِيرًا» — "Men are the protectors and maintainers of women, because Allah has favored some of them over others, and because they spend of their wealth."', '', '«الرِّجَالُ قَوَّامُونَ عَلَى النِّسَاءِ بِمَا فَضَّلَ اللَّهُ بَعْضَهُمْ عَلَىٰ بَعْضٍ وَبِمَا أَنفَقُوا مِنْ أَمْوَالِهِمْ ۚ فَالصَّالِحَاتُ قَانِتَاتٌ حَافِظَاتٌ لِّلْغَيْبِ بِمَا حَفِظَ اللَّهُ ۚ وَاللَّاتِي تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَاهْجُرُوهُنَّ فِي الْمَضَاجِعِ وَاضْرِبُوهُنَّ ۖ فَإِنْ أَطَعْنَكُمْ فَلَا تَبْغُوا عَلَيْهِنَّ سَبِيلًا ۗ إِنَّ اللَّهَ كَانَ عَلِيًّا كَبِيرًا»', NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'then allah mighty and majestic sent down الرجال قوامون علي النساء بما فضل الله بعضهم علي بعض وبما انفقوا من اموالهم فالصالحات قانتات حافظات للغيب بما حفظ الله واللاتي تخافون نشوزهن فعظوهن واهجروهن في المضاجع واضربوهن فان اطعنكم فلا تبغوا عليهن سبيلا ان الله كان عليا كبيرا men are the protectors and maintainers of women because allah has favored some of them over others and because they spend of their wealth', 'الرجال قوامون علي النساء بما فضل الله بعضهم علي بعض وبما انفقوا من اموالهم فالصالحات قانتات حافظات للغيب بما حفظ الله واللاتي تخافون نشوزهن فعظوهن واهجروهن في المضاجع واضربوهن فان اطعنكم فلا تبغوا عليهن سبيلا ان الله كان عليا كبيرا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 174, NULL, 'The Messenger of Allah then said: «أَرَدْتُ أَمْرًا وَأَرَادَ اللَّهُ غَيْرَهُ» — "I intended one thing, and Allah intended another."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the messenger of allah then said اردت امرا واراد الله غيره i intended one thing and allah intended another', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 175, NULL, 'It is also reported from him that jealousy is a part of faith, and careless yielding is a part of hypocrisy — jealousy meaning what is felt over what Allah has forbidden, and yielding meaning what brings men and women together in what is forbidden. A further report, from Ali, may Allah''s blessings be upon him and upon the Messenger of Allah and his family, records that the Prophet forbade al-madhal — the abandonment of due jealousy. The root of the word derives from a man''s making his secret known, that is, exposing it, and from this root comes the sense of exposing one''s womenfolk to other men. Jealousy over what is lawful, however, is disliked and forbidden.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it is also reported from him that jealousy is a part of faith and careless yielding is a part of hypocrisy jealousy meaning what is felt over what allah has forbidden and yielding meaning what brings men and women together in what is forbidden a further report from ali may allahs blessings be upon him and upon the messenger of allah and his family records that the prophet forbade al madhal the abandonment of due jealousy the root of the word derives from a mans making his secret known that is exposing it and from this root comes the sense of exposing ones womenfolk to other men jealousy over what is lawful however is disliked and forbidden', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 176, NULL, 'Ali, may Allah''s blessings be upon him, said: there is no jealousy in what is lawful. This is borne out by what the Messenger of Allah and his family did on the night he brought Fatimah, may Allah''s blessings be upon her, to her husband, after she had become his wife. He said to them: «لَا تُحْدِثَا شَيْئًا حَتَّىٰ آتِيَكُمَا» — "Do not do anything until I come to you." He said this after they had already lain down. Ali, may Allah''s blessings be upon him, held back accordingly, and the Messenger of Allah and his family entered, prayed for them, blessed them, and then departed.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'ali may allahs blessings be upon him said there is no jealousy in what is lawful this is borne out by what the messenger of allah and his family did on the night he brought fatimah may allahs blessings be upon her to her husband after she had become his wife he said to them لا تحدثا شييا حتي اتيكما do not do anything until i come to you he said this after they had already lain down ali may allahs blessings be upon him held back accordingly and the messenger of allah and his family entered prayed for them blessed them and then departed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 177, NULL, 'The Messenger of Allah said: «كُتِبَ الْجِهَادُ عَلَىٰ رِجَالِ أُمَّتِي وَالْغَيْرَةُ عَلَىٰ نِسَائِهَا، فَمَنْ صَبَرَتْ مِنْهُنَّ وَاحْتَسَبَتْ أَعْطَاهَا اللَّهُ أَجْرَ شَهِيدٍ» — "Striving has been prescribed upon the men of my community, and jealousy upon its women; so whichever of them is patient and seeks her reward, Allah, mighty and majestic, grants her the reward of a martyr."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the messenger of allah said كتب الجهاد علي رجال امتي والغيره علي نسايها فمن صبرت منهن واحتسبت اعطاها الله اجر شهيد striving has been prescribed upon the men of my community and jealousy upon its women so whichever of them is patient and seeks her reward allah mighty and majestic grants her the reward of a martyr', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 178, NULL, 'From the Messenger also came a word on women and what they ask of men. When they deck themselves in gold and wear silk, he said, they place a burden on men — burdening the rich and wearing out the poor.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'from the messenger also came a word on women and what they ask of men when they deck themselves in gold and wear silk he said they place a burden on men burdening the rich and wearing out the poor', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 179, NULL, 'From Ali, may Allah''s blessings be upon him: whoever obeys his wife in four things, Allah casts him upon his face into the Fire:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'from ali may allahs blessings be upon him whoever obeys his wife in four things allah casts him upon his face into the fire', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 180, NULL, 'obeying her in attending wedding feasts obeying her in attending gatherings of wailing obeying her in paying visits obeying her in going to the bathhouses', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'obeying her in attending wedding feasts obeying her in attending gatherings of wailing obeying her in paying visits obeying her in going to the bathhouses', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 181, NULL, 'On Marriage Through Guardians', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'on marriage through guardians', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 182, NULL, 'The tradition transmitted from the Imams of the Prophet''s family runs: «لَا نِكَاحَ إِلَّا بِوَلِيٍّ وَشَاهِدَيْ عَدْلٍ» — "There is no marriage save with a guardian and two upright witnesses." Alongside this, the Prophet forbade that any woman be given in marriage until she has been consulted.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the tradition transmitted from the imams of the prophets family runs لا نكاح الا بولي وشاهدي عدل there is no marriage save with a guardian and two upright witnesses alongside this the prophet forbade that any woman be given in marriage until she has been consulted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 183, NULL, 'From Ali, may Allah''s blessings be upon him: "None of you should give his daughter in marriage until he consults her, for she knows herself best. If she keeps silent, or weeps, or laughs, that is her consent; and if she refuses, he does not marry her off."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'from ali may allahs blessings be upon him none of you should give his daughter in marriage until he consults her for she knows herself best if she keeps silent or weeps or laughs that is her consent and if she refuses he does not marry her off', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 184, NULL, 'A father''s arrangement of marriage on behalf of his minor sons and daughters is permissible. Once they come of age, they have no right to dissolve that marriage. Likewise, when an agent is duly authorized to contract a marriage, the contract is valid.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'a fathers arrangement of marriage on behalf of his minor sons and daughters is permissible once they come of age they have no right to dissolve that marriage likewise when an agent is duly authorized to contract a marriage the contract is valid', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 185, NULL, 'From Ali, may Allah''s blessings be upon him: "If a Muslim woman who has reached majority authorizes her Christian father to give her in marriage, and he does so, the marriage is valid. But if he gives her in marriage while she is still a child, it is not valid — for a disbeliever holds no guardianship over a Muslim."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'from ali may allahs blessings be upon him if a muslim woman who has reached majority authorizes her christian father to give her in marriage and he does so the marriage is valid but if he gives her in marriage while she is still a child it is not valid for a disbeliever holds no guardianship over a muslim', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 186, NULL, 'When a woman delegates her marriage to two guardians simultaneously and each contracts her to a different man, the marriage belongs to the first contract made, provided that the first guardian was unaware of the other''s contract. If both contracts are concluded at exactly the same moment, one is annulled and the matter begins again.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'when a woman delegates her marriage to two guardians simultaneously and each contracts her to a different man the marriage belongs to the first contract made provided that the first guardian was unaware of the others contract if both contracts are concluded at exactly the same moment one is annulled and the matter begins again', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 187, NULL, 'It is related from Abu Jafar Muhammad ibn Ali and from Jafar ibn Muhammad that a paternal grandfather may contract the marriage of his son''s minor daughter just as the father may, and he holds prior right in this even if both were to act at the same moment. All parties are bound by whichever contract was concluded first, even if the guardian whose contract is dissolved was unaware of the other at the time and learns of it only afterward — in which case the matter is resumed.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it is related from abu jafar muhammad ibn ali and from jafar ibn muhammad that a paternal grandfather may contract the marriage of his sons minor daughter just as the father may and he holds prior right in this even if both were to act at the same moment all parties are bound by whichever contract was concluded first even if the guardian whose contract is dissolved was unaware of the other at the time and learns of it only afterward in which case the matter is resumed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 188, NULL, 'From Abu Jafar Muhammad ibn Ali it is related that whatever testimony is admissible in financial matters is admissible in marriage, and the testimony of women and of slaves is accepted in it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'from abu jafar muhammad ibn ali it is related that whatever testimony is admissible in financial matters is admissible in marriage and the testimony of women and of slaves is accepted in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 189, NULL, 'From Jafar ibn Muhammad: he was asked about two witnesses who testified that a woman''s father had given her in marriage while she was unwilling, while a third witness testified that he had given her in marriage with her consent. He said that the marriage is valid with her consent. He was also asked about two witnesses, one of whom testified that the dowry was one thousand and the other that it was two thousand. He said that if she claims the greater amount, she takes an oath together with her witness, and it is decreed for her. If one witness testifies that her father gave her in marriage while she was a child, and the other testifies that he gave her in marriage when she was of age and without her consent, the testimony is void.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'from jafar ibn muhammad he was asked about two witnesses who testified that a womans father had given her in marriage while she was unwilling while a third witness testified that he had given her in marriage with her consent he said that the marriage is valid with her consent he was also asked about two witnesses one of whom testified that the dowry was one thousand and the other that it was two thousand he said that if she claims the greater amount she takes an oath together with her witness and it is decreed for her if one witness testifies that her father gave her in marriage while she was a child and the other testifies that he gave her in marriage when she was of age and without her consent the testimony is void', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 190, NULL, 'Mentioning the Witnesses in Marriage', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'mentioning the witnesses in marriage', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 191, NULL, 'The Messenger of Allah, may Allah bless him and his family and grant them peace, said that there is no marriage save with a guardian and two witnesses. This is the command upon which action is taken and by which the marriage is established. It is related from Ali that he said a marriage is not valid except with a guardian and witnesses.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the messenger of allah may allah bless him and his family and grant them peace said that there is no marriage save with a guardian and two witnesses this is the command upon which action is taken and by which the marriage is established it is related from ali that he said a marriage is not valid except with a guardian and witnesses', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 192, NULL, 'Abu Jafar and Abu Abdullah (عَلَيْهِمُ السَّلَامُ) said that witnesses were appointed in marriage only for the sake of the child, so that his father may be known — and as a safeguard against either spouse denying the marriage, and out of caution before the authorities, lest the two be charged with living together unlawfully. For these reasons, and for whatever resembles them, seeking witnesses in marriage is obligatory.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'abu jafar and abu abdullah عليهم السلام said that witnesses were appointed in marriage only for the sake of the child so that his father may be known and as a safeguard against either spouse denying the marriage and out of caution before the authorities lest the two be charged with living together unlawfully for these reasons and for whatever resembles them seeking witnesses in marriage is obligatory', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 193, NULL, 'As for what lies between a person and Allah, Mighty and Majestic, no obligation falls upon him if he forgoes witnesses, for Allah, Mighty and Majestic, mentioned witnessing in the matter of divorce but not in the matter of marriage. Even so, witnesses in marriage cannot be dispensed with: through them the marriage is established, lineage is confirmed, and doubt is removed. Upright persons bear witness to it, and among the witnesses, women and slaves are admissible, provided they are upright.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'as for what lies between a person and allah mighty and majestic no obligation falls upon him if he forgoes witnesses for allah mighty and majestic mentioned witnessing in the matter of divorce but not in the matter of marriage even so witnesses in marriage cannot be dispensed with through them the marriage is established lineage is confirmed and doubt is removed upright persons bear witness to it and among the witnesses women and slaves are admissible provided they are upright', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 194, NULL, 'Mentioning the Dowries', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'mentioning the dowries', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 195, NULL, 'Concerning the Commander of the Believers (ع), it is narrated that Allah, exalted be the One who speaks, said: ﴿ وَآتُوا النِّسَاءَ صَدُقَاتِهِنَّ نِحْلَةً ﴾. Ali said, regarding the words of Allah, Mighty and Majestic, ﴿ وَآتُوا النِّسَاءَ صَدُقَاتِهِنَّ نِحْلَةً ﴾: "Allah, Mighty and Majestic, is saying: give them the gift by which you have made their private parts lawful to you. Whoever wrongs a woman in her dowry has made her private part lawful to himself through fornication."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'concerning the commander of the believers ع it is narrated that allah exalted be the one who speaks said واتوا النساء صدقاتهن نحله ali said regarding the words of allah mighty and majestic واتوا النساء صدقاتهن نحله allah mighty and majestic is saying give them the gift by which you have made their private parts lawful to you whoever wrongs a woman in her dowry has made her private part lawful to himself through fornication', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 196, NULL, 'The Messenger of Allah, may Allah bless him and his family and grant them peace, said: "Allah, Mighty and Majestic, forgives every sin save the sin of a man who has defrauded a hired laborer of his wage, or a woman of her dowry, or who has sold a free person."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the messenger of allah may allah bless him and his family and grant them peace said allah mighty and majestic forgives every sin save the sin of a man who has defrauded a hired laborer of his wage or a woman of her dowry or who has sold a free person', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 197, NULL, 'It is also related that he said: "The Messenger of Allah, may Allah bless him and his family and grant them peace, did not marry any of his wives, nor did he give any of his daughters in marriage, for more than twelve uqiyyahs and a nashsh of silver." An uqiyyah is forty dirhams, and a nashsh is half an uqiyyah — five hundred dirhams in all — together with a woven cloak and a bed of ram''s hide. This is the dowry of the Sunnah. No fixed limit is placed upon dowries; whatever sum is named, whether little or much, the marriage is contracted upon it. It is, however, recommended that the matter be made easy.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it is also related that he said the messenger of allah may allah bless him and his family and grant them peace did not marry any of his wives nor did he give any of his daughters in marriage for more than twelve uqiyyahs and a nashsh of silver an uqiyyah is forty dirhams and a nashsh is half an uqiyyah five hundred dirhams in all together with a woven cloak and a bed of rams hide this is the dowry of the sunnah no fixed limit is placed upon dowries whatever sum is named whether little or much the marriage is contracted upon it it is however recommended that the matter be made easy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 198, NULL, 'Ali said: "Among the blessings of a woman is the ease of her marriage and the ease of her womb, so do not be excessive in the dowries of women, for that breeds enmity."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'ali said among the blessings of a woman is the ease of her marriage and the ease of her womb so do not be excessive in the dowries of women for that breeds enmity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 199, NULL, 'A man came to the Prophet, may Allah bless him and his family, and said: "O Messenger of Allah, I wish to marry a certain woman." The Prophet asked whether he had anything to give her. The man replied: "No, by Allah, I have nothing." The Prophet then looked at the ring on the man''s hand and said: "This ring that is on your hand." The man said: "Yes, O Messenger of Allah." The Messenger of Allah, may Allah bless him and his family and grant them peace, said: "Then you have married her with this ring of yours."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'a man came to the prophet may allah bless him and his family and said o messenger of allah i wish to marry a certain woman the prophet asked whether he had anything to give her the man replied no by allah i have nothing the prophet then looked at the ring on the mans hand and said this ring that is on your hand the man said yes o messenger of allah the messenger of allah may allah bless him and his family and grant them peace said then you have married her with this ring of yours', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 200, NULL, 'Ease in marriage is a virtue, as this tradition attests, and there is equally no harm in going beyond it. Allah, Mighty and Majestic, says: ﴿ وَآتَيْتُمْ إِحْدَاهُنَّ قِنطَارًا فَلَا تَأْخُذُوا مِنْهُ شَيْئًا ﴾. It is also reported of al-Husayn ibn Ali, peace be upon them both, that he married a woman and sent to her one hundred slave girls, each accompanied by a thousand dirhams.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'ease in marriage is a virtue as this tradition attests and there is equally no harm in going beyond it allah mighty and majestic says واتيتم احداهن قنطارا فلا تاخذوا منه شييا it is also reported of al husayn ibn ali peace be upon them both that he married a woman and sent to her one hundred slave girls each accompanied by a thousand dirhams', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 201, NULL, 'It is reported from Abu Abdullah that he was asked about the dowry. He said: "It is whatever the two spouses agree upon, little or much. A dowry there must be — no marriage is permissible without one — though there is no harm in contracting a marriage without naming a specific amount. He may not consummate the marriage, however, until he gives her something, whatever it may be."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it is reported from abu abdullah that he was asked about the dowry he said it is whatever the two spouses agree upon little or much a dowry there must be no marriage is permissible without one though there is no harm in contracting a marriage without naming a specific amount he may not consummate the marriage however until he gives her something whatever it may be', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 202, NULL, 'This accords with the words of Allah, Mighty and Majestic: ﴿ لَا جُنَاحَ عَلَيْكُمْ إِن طَلَّقْتُمُ النِّسَاءَ مَا لَمْ تَمَسُّوهُنَّ أَوْ تَفْرِضُوا لَهُنَّ فَرِيضَةً ﴾. A contract without a named dowry is therefore permissible, but consummation must wait until he gives her something. Abu Abdullah Jafar ibn Muhammad was asked about this and said: "My father married a woman and did not name a dowry for her, and when he wished to consummate the marriage he took a garment from me and handed it to her."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'this accords with the words of allah mighty and majestic لا جناح عليكم ان طلقتم النساء ما لم تمسوهن او تفرضوا لهن فريضه a contract without a named dowry is therefore permissible but consummation must wait until he gives her something abu abdullah jafar ibn muhammad was asked about this and said my father married a woman and did not name a dowry for her and when he wished to consummate the marriage he took a garment from me and handed it to her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 203, NULL, 'He was asked about the words of Allah, Mighty and Majestic: ﴿ وَامْرَأَةً مُؤْمِنَةً إِن وَهَبَتْ نَفْسَهَا لِلنَّبِيِّ ﴾. He said that this dispensation was singled out for the Messenger of Allah, may Allah bless him and his family and grant them peace. No marriage is sound without a dowry. If a man names no dowry for his wife and then dies before her, or divorces her before consummating the marriage, she has no dowry — yet he inherits from her and she from him, and she must observe the waiting period. If he has consummated the marriage, she is entitled to a dowry equivalent to that of women of her family, assessed according to her circumstances, her wealth, and her beauty, and measured against a man of comparable standing and means — provided the amount does not exceed the dowry of the Sunnah. Should it exceed that, the excess is returned to him. The dowry of the Sunnah, as previously noted, is five hundred dirhams.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he was asked about the words of allah mighty and majestic وامراه مومنه ان وهبت نفسها للنبي he said that this dispensation was singled out for the messenger of allah may allah bless him and his family and grant them peace no marriage is sound without a dowry if a man names no dowry for his wife and then dies before her or divorces her before consummating the marriage she has no dowry yet he inherits from her and she from him and she must observe the waiting period if he has consummated the marriage she is entitled to a dowry equivalent to that of women of her family assessed according to her circumstances her wealth and her beauty and measured against a man of comparable standing and means provided the amount does not exceed the dowry of the sunnah should it exceed that the excess is returned to him the dowry of the sunnah as previously noted is five hundred dirhams', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 204, NULL, 'It is also related from him concerning a man who married a woman leaving the dowry to her own determination: the marriage is valid. If the two parties then disagree over the amount, she is entitled to the equivalent of the dowry customary among women of her family — neither falling short nor going to excess — and it may not exceed the dowry of the Sunnah.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it is also related from him concerning a man who married a woman leaving the dowry to her own determination the marriage is valid if the two parties then disagree over the amount she is entitled to the equivalent of the dowry customary among women of her family neither falling short nor going to excess and it may not exceed the dowry of the sunnah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 205, NULL, 'It is related from him that the Messenger of Allah, may Allah bless him and his family and grant them peace, forbade the marriage of exchange. Abu Abdullah Jafar ibn Muhammad said: The marriage of exchange — shighar — is when a man gives his daughter in marriage to another man on the condition that the other gives him his daughter in marriage, with no dowry between them. He said: Two men came to Ali, each having married the other''s daughter without a dowry, and he rejected it, saying: "No, there must be a dowry."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it is related from him that the messenger of allah may allah bless him and his family and grant them peace forbade the marriage of exchange abu abdullah jafar ibn muhammad said the marriage of exchange shighar is when a man gives his daughter in marriage to another man on the condition that the other gives him his daughter in marriage with no dowry between them he said two men came to ali each having married the others daughter without a dowry and he rejected it saying no there must be a dowry', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 206, NULL, 'This ruling applies when the contract is made on the basis that each marriage stands as the recompense for the other, the parties binding themselves to that arrangement explicitly. If, however, they contract the marriage as an ordinary marriage without a named dowry — without stipulating what has just been described — then the contract is valid, and each of the two women is entitled to the equivalent of the dowry customary among women of her family, in the manner already described.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'this ruling applies when the contract is made on the basis that each marriage stands as the recompense for the other the parties binding themselves to that arrangement explicitly if however they contract the marriage as an ordinary marriage without a named dowry without stipulating what has just been described then the contract is valid and each of the two women is entitled to the equivalent of the dowry customary among women of her family in the manner already described', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 207, NULL, 'The jurists permitted contracting a marriage upon goods that are described and known. It is narrated from Ali that he said, concerning a man who married a woman in return for a young servant: neither falling short nor going to excess. Abu Abdullah Jafar ibn Muhammad said: "Whoever marries a woman for an unknown dowry has not thereby invalidated the marriage; she is entitled to the equivalent of the dowry customary among women of her peers, and it shall be no more than the dowry of the Sunnah."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the jurists permitted contracting a marriage upon goods that are described and known it is narrated from ali that he said concerning a man who married a woman in return for a young servant neither falling short nor going to excess abu abdullah jafar ibn muhammad said whoever marries a woman for an unknown dowry has not thereby invalidated the marriage she is entitled to the equivalent of the dowry customary among women of her peers and it shall be no more than the dowry of the sunnah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 208, NULL, 'The Master was asked about a man who had married a woman in return for a slave girl of his who had been pledged her freedom upon his death, and who then divorced her before the marriage was consummated. He said that the woman was entitled to half the slave girl''s service — one day''s service belonging to the woman and the next to the master — and that if the master revoked the pledge of freedom or sold the slave girl, the woman was entitled to half her value. It was affirmed that the dowry belongs to the woman.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the master was asked about a man who had married a woman in return for a slave girl of his who had been pledged her freedom upon his death and who then divorced her before the marriage was consummated he said that the woman was entitled to half the slave girls service one days service belonging to the woman and the next to the master and that if the master revoked the pledge of freedom or sold the slave girl the woman was entitled to half her value it was affirmed that the dowry belongs to the woman', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 209, NULL, 'It is narrated from Ali that he said: "Marriage in return for a wage paid to the father is not lawful in Islam, in the manner that Moses hired himself out. The dowry belongs to the wife alone." If a man marries a woman on the condition that he perform some work for her, the marriage is valid, and that wage stands in place of the dowry; he may not consummate the marriage until he has performed the work for which he was engaged, or has given her something in its stead.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it is narrated from ali that he said marriage in return for a wage paid to the father is not lawful in islam in the manner that moses hired himself out the dowry belongs to the wife alone if a man marries a woman on the condition that he perform some work for her the marriage is valid and that wage stands in place of the dowry he may not consummate the marriage until he has performed the work for which he was engaged or has given her something in its stead', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 210, NULL, 'Abu Jafar Muhammad ibn Ali said: "A woman came to the Messenger of Allah, may Allah bless him and his family and grant them peace, and said: O Messenger of Allah, give me in marriage. He said: Who will take this woman? A man among the people said: I, O Messenger of Allah. He said: What will you give her? He said: I have no wealth. He said: With no wealth at all? The woman turned to go. The Messenger of Allah, may Allah bless him and his family and grant them peace, repeated his words, yet no one rose but that same man, and the woman turned away again. A third time the Messenger of Allah, may Allah bless him and his family and grant them peace, addressed the man: Do you know anything of the Quran? He said: Yes. He said: I have given her to you in marriage for what you know of the Quran."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'abu jafar muhammad ibn ali said a woman came to the messenger of allah may allah bless him and his family and grant them peace and said o messenger of allah give me in marriage he said who will take this woman a man among the people said i o messenger of allah he said what will you give her he said i have no wealth he said with no wealth at all the woman turned to go the messenger of allah may allah bless him and his family and grant them peace repeated his words yet no one rose but that same man and the woman turned away again a third time the messenger of allah may allah bless him and his family and grant them peace addressed the man do you know anything of the quran he said yes he said i have given her to you in marriage for what you know of the quran', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 211, NULL, 'Abu Jafar Muhammad ibn Ali said: "If a man marries a woman on the condition that he will teach her a chapter from the Book of Allah, he may not consummate the marriage until he has taught her, or has given her something in its stead."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'abu jafar muhammad ibn ali said if a man marries a woman on the condition that he will teach her a chapter from the book of allah he may not consummate the marriage until he has taught her or has given her something in its stead', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 212, NULL, 'From Ali it is related that once a woman has been brought to her husband, she has no claim to her dowry after she has entered upon him — except by clear proof — meaning, if she claims he gave her nothing and that something of her dowry remains owing.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'from ali it is related that once a woman has been brought to her husband she has no claim to her dowry after she has entered upon him except by clear proof meaning if she claims he gave her nothing and that something of her dowry remains owing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 213, NULL, 'Abu Abdullah Jafar ibn Muhammad said: "If a man marries a woman with a portion of the dowry paid immediately and a portion deferred, the immediate portion falls due before consummation. She may lawfully withhold herself from him until he pays it, and he may not consummate the marriage while she does so. The deferred portion runs until death or separation — that is, when no specific time of payment has been stipulated."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'abu abdullah jafar ibn muhammad said if a man marries a woman with a portion of the dowry paid immediately and a portion deferred the immediate portion falls due before consummation she may lawfully withhold herself from him until he pays it and he may not consummate the marriage while she does so the deferred portion runs until death or separation that is when no specific time of payment has been stipulated', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 214, NULL, 'If, however, she stipulates that the deferred portion becomes due after consummation, a case has been related from Ali bearing on this: a woman brought before him a man who had married her, consummated the marriage, and named a term for her dowry. Ali said: "There is no term for you in her dowry once you have consummated the marriage; her right has fallen due, so pay her her right."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'if however she stipulates that the deferred portion becomes due after consummation a case has been related from ali bearing on this a woman brought before him a man who had married her consummated the marriage and named a term for her dowry ali said there is no term for you in her dowry once you have consummated the marriage her right has fallen due so pay her her right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 215, NULL, 'This ruling — and Allah knows best — applies when he had paid her nothing in advance and had named neither an immediate nor a deferred portion. If, on the other hand, he had named both and had already paid what he obligated upon himself at once, then the deferred remainder runs to the time he stipulated, in accordance with the words of the Messenger of Allah, may Allah bless him and his family and grant them peace: "People are bound by their conditions."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'this ruling and allah knows best applies when he had paid her nothing in advance and had named neither an immediate nor a deferred portion if on the other hand he had named both and had already paid what he obligated upon himself at once then the deferred remainder runs to the time he stipulated in accordance with the words of the messenger of allah may allah bless him and his family and grant them peace people are bound by their conditions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 216, NULL, 'Likewise, if he named no term but named a dowry, and she refused to permit consummation until he discharged it, that refusal is her right.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'likewise if he named no term but named a dowry and she refused to permit consummation until he discharged it that refusal is her right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 217, NULL, 'Also related from Ali is a ruling concerning a man who marries a woman and convenes two sets of witnesses — a secret gathering on one dowry and a public gathering on a larger one: the first contract is the binding one, and the matter is settled by it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'also related from ali is a ruling concerning a man who marries a woman and convenes two sets of witnesses a secret gathering on one dowry and a public gathering on a larger one the first contract is the binding one and the matter is settled by it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 218, NULL, 'From him as well: when the curtains are drawn and the doors are shut, the dowry falls due in full. This is the position of Abu Jafar and Abu Abdullah, and it applies when the wife claims that consummation took place. If, however, she acknowledges that he did not touch her — even though he had drawn the curtain and shut the door upon them — and he then divorces her, she is entitled to no more than half the dowry. She must also observe the waiting period, for her acknowledgment that he did not touch her does not waive the waiting period once he has shut his door and drawn the curtain over her.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'from him as well when the curtains are drawn and the doors are shut the dowry falls due in full this is the position of abu jafar and abu abdullah and it applies when the wife claims that consummation took place if however she acknowledges that he did not touch her even though he had drawn the curtain and shut the door upon them and he then divorces her she is entitled to no more than half the dowry she must also observe the waiting period for her acknowledgment that he did not touch her does not waive the waiting period once he has shut his door and drawn the curtain over her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 219, NULL, 'It is related from Ali, Abu Jafar, and Abu Abdullah that they ruled a man may take the freeing of his slave woman as her dowry, and that this is permissible. Abu Jafar Muhammad ibn Ali clarified the condition: the stipulation must be set before the act of freeing. That is, the man says, "I marry you on the condition that I have made your dowry your freedom," and then he frees her. If, however, he frees her first — saying, "I free you for the sake of Allah on the condition that your freedom is your dowry, and I marry you upon that" — then the choice passes to her. She may marry him if she wishes, or she may refuse, for she has already been freed and has come to own herself independently of him. Should he then marry her, he must do so with a proper dowry.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it is related from ali abu jafar and abu abdullah that they ruled a man may take the freeing of his slave woman as her dowry and that this is permissible abu jafar muhammad ibn ali clarified the condition the stipulation must be set before the act of freeing that is the man says i marry you on the condition that i have made your dowry your freedom and then he frees her if however he frees her first saying i free you for the sake of allah on the condition that your freedom is your dowry and i marry you upon that then the choice passes to her she may marry him if she wishes or she may refuse for she has already been freed and has come to own herself independently of him should he then marry her he must do so with a proper dowry', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 220, NULL, 'It is related from Ali that he was asked about a man who steals wealth and uses it either to contract a marriage or to purchase a slave girl. Ali said: "The union is lawful, but the liability for the stolen wealth remains upon him. He is a sinner for what he has done, and he must make restitution for what he stole."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it is related from ali that he was asked about a man who steals wealth and uses it either to contract a marriage or to purchase a slave girl ali said the union is lawful but the liability for the stolen wealth remains upon him he is a sinner for what he has done and he must make restitution for what he stole', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 221, NULL, 'Mentioning the Conditions in Marriage', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'mentioning the conditions in marriage', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 222, NULL, 'The Imams of the household of the Messenger of Allah — may Allah bless him and his family and grant them peace — are reported to have said: "Every condition that contradicts the Book of Allah is to be rejected."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the imams of the household of the messenger of allah may allah bless him and his family and grant them peace are reported to have said every condition that contradicts the book of allah is to be rejected', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 223, NULL, 'It is related from Ali that he ruled concerning a man who married a woman and stipulated to her family that if he were to take another wife over her she would be divorced, or if he were to take a concubine over her the concubine would be free. Ali said: "The condition of Allah, Mighty and Majestic, comes before their conditions. If he wishes, he fulfills his promise; and if he wishes, he marries another over her or takes a concubine — and no wife is divorced from him should he marry another, nor is any concubine freed should he take one."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it is related from ali that he ruled concerning a man who married a woman and stipulated to her family that if he were to take another wife over her she would be divorced or if he were to take a concubine over her the concubine would be free ali said the condition of allah mighty and majestic comes before their conditions if he wishes he fulfills his promise and if he wishes he marries another over her or takes a concubine and no wife is divorced from him should he marry another nor is any concubine freed should he take one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 224, NULL, 'The same ruling is related from Abu Jafar and Abu Abdullah.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the same ruling is related from abu jafar and abu abdullah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 225, NULL, 'It is further narrated from Abu Jafar and Abu Abd-Allah (عَلَيْهِمُ السَّلَامُ), and likewise from Ali, that he gave judgment concerning a man who married a woman and stipulated that she should hold authority over her own affairs. Ali said: "This departs from the Sunnah and assigns a right to one who is not its rightful holder. The husband is the guardian; intimacy and divorce rest in his hand." Ali therefore ruled that the dowry was owed by the husband, that intimacy and divorce remained his, and he nullified the condition.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it is further narrated from abu jafar and abu abd allah عليهم السلام and likewise from ali that he gave judgment concerning a man who married a woman and stipulated that she should hold authority over her own affairs ali said this departs from the sunnah and assigns a right to one who is not its rightful holder the husband is the guardian intimacy and divorce rest in his hand ali therefore ruled that the dowry was owed by the husband that intimacy and divorce remained his and he nullified the condition', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 226, NULL, 'Jafar ibn Muhammad said: "A condition that is lawful — one that does not contradict the Book of Allah — is binding upon the man who married the woman on its basis. Among such valid conditions is that she shall remain with her family in a known land, or in a specified dwelling. This is permissible."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'jafar ibn muhammad said a condition that is lawful one that does not contradict the book of allah is binding upon the man who married the woman on its basis among such valid conditions is that she shall remain with her family in a known land or in a specified dwelling this is permissible', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 227, NULL, 'It was also narrated from him that he said: "Whoever marries a woman on the condition that he will provide her a fixed daily maintenance and not be absent from her during the day — that condition does not invalidate the marriage, but neither is it itself binding. She retains the right to the division of nights and to the maintenance due to wives generally. Yet if a woman fears that her husband may harm her or divorce her, and he agrees with her to forgo some of his rights regarding her maintenance and the division of nights, that arrangement is permissible, in accordance with the words of Allah the Almighty: If a woman fears discord or desertion from her husband, there is no blame upon them if they come to an agreement between themselves'' (al-Nisa 128)."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was also narrated from him that he said whoever marries a woman on the condition that he will provide her a fixed daily maintenance and not be absent from her during the day that condition does not invalidate the marriage but neither is it itself binding she retains the right to the division of nights and to the maintenance due to wives generally yet if a woman fears that her husband may harm her or divorce her and he agrees with her to forgo some of his rights regarding her maintenance and the division of nights that arrangement is permissible in accordance with the words of allah the almighty if a woman fears discord or desertion from her husband there is no blame upon them if they come to an agreement between themselves al nisa 128', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 228, NULL, 'Abu Abd-Allah Jafar ibn Muhammad said: "If a man stipulates that, should he take another wife or a concubine, she shall receive one hundred dinars or whatever sum he has bound himself to, the marriage is permissible. If that sum is drawn from the original dowry, it is binding; if it rests only on the added stipulation, it is not binding."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'abu abd allah jafar ibn muhammad said if a man stipulates that should he take another wife or a concubine she shall receive one hundred dinars or whatever sum he has bound himself to the marriage is permissible if that sum is drawn from the original dowry it is binding if it rests only on the added stipulation it is not binding', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 229, NULL, 'This is the import of what Abu Jafar Muhammad ibn Ali said: a man should not make the divorce of one wife a condition for marrying another. The Messenger of Allah (ع and his family) forbade a woman to seek the divorce of her sister wife in order to take her place, for Allah the Almighty is the One who provides for her. And the Messenger of Allah (ع and his family) forbade the marriage of pleasure (mutah).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'this is the import of what abu jafar muhammad ibn ali said a man should not make the divorce of one wife a condition for marrying another the messenger of allah ع and his family forbade a woman to seek the divorce of her sister wife in order to take her place for allah the almighty is the one who provides for her and the messenger of allah ع and his family forbade the marriage of pleasure mutah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 230, NULL, 'Concerning the marriage of pleasure, which some had permitted: a man would say to a woman, "Give yourself to me in marriage," naming a sum — a dirham, two dirhams, or whatever was agreed — for a single union, a day, two days, or any other fixed term. Once the parties agreed on the term, those who allowed it held:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'concerning the marriage of pleasure which some had permitted a man would say to a woman give yourself to me in marriage naming a sum a dirham two dirhams or whatever was agreed for a single union a day two days or any other fixed term once the parties agreed on the term those who allowed it held', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 231, NULL, 'the union was lawful until that term expired, at which point separation occurred of itself, without divorce; no waiting period (iddah) was required of the woman; neither party inherited from the other; such an arrangement was not permissible with a virgin — though some among them held that it was permissible even with women already married.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the union was lawful until that term expired at which point separation occurred of itself without divorce no waiting period iddah was required of the woman neither party inherited from the other such an arrangement was not permissible with a virgin though some among them held that it was permissible even with women already married', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 232, NULL, 'This is pure fornication. There is no ambiguity in it, and no covering conceals what it is. Allah the Almighty has made intimacy lawful by two paths only: the bond of marriage and the right of possession (milk al-yamin). The Almighty said:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'this is pure fornication there is no ambiguity in it and no covering conceals what it is allah the almighty has made intimacy lawful by two paths only the bond of marriage and the right of possession milk al yamin the almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 233, NULL, '"Those who guard their private parts, except with their wives or what their right hands possess, for they are not blameworthy; but whoever seeks beyond that, those are the transgressors." (al-Muminun 5–7)', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'those who guard their private parts except with their wives or what their right hands possess for they are not blameworthy but whoever seeks beyond that those are the transgressors al muminun 5 7', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'marriage and the household', '6. Marriage and the Household', 234, NULL, 'At-Talaq: 1يَٓأَيُّهَا ٱلنَّبِىُّ إِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا۟ ٱلْعِدَّةَ', '', 'يَٓأَيُّهَا ٱلنَّبِىُّ إِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا۟ ٱلْعِدَّةَ', 'At-Talaq: 1', 65, 1, 'mukhtasar ul asaar 2 6 marriage and the household', 'at talaq 1يايها النبي اذا طلقتم النساء فطلقوهن لعدتهن واحصوا العده', 'يايها النبي اذا طلقتم النساء فطلقوهن لعدتهن واحصوا العده');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 235, NULL, 'Had such a union been a marriage, the woman could not be separated from the man without divorce and without iddah, for Allah the Almighty says: "O Prophet, when you divorce women, divorce them at the beginning of their waiting period" (al-Talaq 1). She would inherit and be inherited from, as Allah says: "And you shall have half of what your wives leave" (al-Nisa 12), and "They shall have a fourth of what you leave" (al-Nisa 12). The child, likewise, would be attached to both parents, for the Messenger of Allah (ع and his family) said: "The child belongs to the bed" — meaning to the owner of the bed. Yet in such an arrangement there is neither marriage nor right of possession, and what remains is forbidden.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'had such a union been a marriage the woman could not be separated from the man without divorce and without iddah for allah the almighty says o prophet when you divorce women divorce them at the beginning of their waiting period al talaq 1 she would inherit and be inherited from as allah says and you shall have half of what your wives leave al nisa 12 and they shall have a fourth of what you leave al nisa 12 the child likewise would be attached to both parents for the messenger of allah ع and his family said the child belongs to the bed meaning to the owner of the bed yet in such an arrangement there is neither marriage nor right of possession and what remains is forbidden', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 236, NULL, 'The reports forbidding the marriage of pleasure on the authority of the Messenger of Allah (ع and his family) are numerous, among them his saying: "There is no marriage except with a guardian and two upright witnesses." Those who uphold the marriage of pleasure themselves acknowledge that it is contracted without a guardian and without witnesses — and on that ground alone it cannot stand.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the reports forbidding the marriage of pleasure on the authority of the messenger of allah ع and his family are numerous among them his saying there is no marriage except with a guardian and two upright witnesses those who uphold the marriage of pleasure themselves acknowledge that it is contracted without a guardian and without witnesses and on that ground alone it cannot stand', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 237, NULL, 'It was narrated from Ali, Abu Jafar, and Abu Abd-Allah that they declared the marriage of pleasure void, forbade it, and prohibited it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was narrated from ali abu jafar and abu abd allah that they declared the marriage of pleasure void forbade it and prohibited it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 238, NULL, 'It was narrated from Ali that he gave judgment in a case concerning a slave-woman who had fled from her master and deceived a man by claiming to be free, so that he married her on that basis and she bore him children — until her master established his claim over her. Ali ruled that she be returned to her master, and that the deceived man owed the master the value of the children she had borne him, unless the master chose to grant those children to their father. If the man had purchased her and she bore him a child, and her master then established his claim, she was to be returned to the one whose right was vindicated, and the value of the child was owed by the father, who could in turn recover that amount from the one who had sold her to him. If, however, he had taken her by force, or had known at the time of the marriage that she was owned and that her master had not given her in marriage, then both she and her child belonged to the master.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was narrated from ali that he gave judgment in a case concerning a slave woman who had fled from her master and deceived a man by claiming to be free so that he married her on that basis and she bore him children until her master established his claim over her ali ruled that she be returned to her master and that the deceived man owed the master the value of the children she had borne him unless the master chose to grant those children to their father if the man had purchased her and she bore him a child and her master then established his claim she was to be returned to the one whose right was vindicated and the value of the child was owed by the father who could in turn recover that amount from the one who had sold her to him if however he had taken her by force or had known at the time of the marriage that she was owned and that her master had not given her in marriage then both she and her child belonged to the master', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 239, NULL, 'From Ali it was narrated concerning a free woman whom a male slave had approached, claiming to be free, so that she married him on that basis and then discovered he was owned: they may be separated if the woman wishes. Abu Jafar Muhammad ibn Ali said that she holds authority over her own decision — if she wishes she may remain with him, and if she wishes she may leave. If she chooses to separate and the marriage has not been consummated, she is owed nothing; but if it has been consummated, she is entitled to her dowry, and the liability falls upon whoever deceived her, whether the slave himself or another. When the slave is eventually freed, if his lord does not then give him in marriage to her, the dowry rests with the slave once he is free; but if the lord had given him in marriage, or had given him leave to marry her, then her dowry is owed by the lord.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'from ali it was narrated concerning a free woman whom a male slave had approached claiming to be free so that she married him on that basis and then discovered he was owned they may be separated if the woman wishes abu jafar muhammad ibn ali said that she holds authority over her own decision if she wishes she may remain with him and if she wishes she may leave if she chooses to separate and the marriage has not been consummated she is owed nothing but if it has been consummated she is entitled to her dowry and the liability falls upon whoever deceived her whether the slave himself or another when the slave is eventually freed if his lord does not then give him in marriage to her the dowry rests with the slave once he is free but if the lord had given him in marriage or had given him leave to marry her then her dowry is owed by the lord', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 240, NULL, 'It was narrated from Ali, Abu Jafar, and Abu Abd-Allah concerning a man to whom another woman was brought as a bride, so that he consummated the marriage believing her to be his wife and only afterward learned otherwise: he must return that woman, she is entitled to a dowry for what was done to her — claimed against the one who deceived him — and his true wife, the one he had actually married, is to be restored to him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was narrated from ali abu jafar and abu abd allah concerning a man to whom another woman was brought as a bride so that he consummated the marriage believing her to be his wife and only afterward learned otherwise he must return that woman she is entitled to a dowry for what was done to her claimed against the one who deceived him and his true wife the one he had actually married is to be restored to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 241, NULL, 'Concerning a man who is impotent and unable to approach women yet conceals this from his wife: once she learns of it, the choice is hers, and if she exercises that choice after consummation she is entitled to her dowry. They also ruled on a man who marries a woman and discovers in her leprosy, vitiligo, blindness, insanity, a condition of the private parts that prevents intercourse, or a manifest lameness: the choice in that case belongs to the husband. He may keep her if he wishes, or return her if he wishes. If he has had intercourse with her, she is entitled to her dowry, and his claim for it lies against whoever deceived him — the woman herself owes nothing. For defects other than these, she is not to be returned.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'concerning a man who is impotent and unable to approach women yet conceals this from his wife once she learns of it the choice is hers and if she exercises that choice after consummation she is entitled to her dowry they also ruled on a man who marries a woman and discovers in her leprosy vitiligo blindness insanity a condition of the private parts that prevents intercourse or a manifest lameness the choice in that case belongs to the husband he may keep her if he wishes or return her if he wishes if he has had intercourse with her she is entitled to her dowry and his claim for it lies against whoever deceived him the woman herself owes nothing for defects other than these she is not to be returned', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 242, NULL, 'It was narrated from Ali concerning a man who marries a woman as a virgin and finds her otherwise: he saw nothing objectionable in this, and said that virginity may be lost through a leap, through ablution, or through the passing of long years.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was narrated from ali concerning a man who marries a woman as a virgin and finds her otherwise he saw nothing objectionable in this and said that virginity may be lost through a leap through ablution or through the passing of long years', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 243, NULL, 'Mentioning the Forbidden Marriage and the Permissible Marriage', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'mentioning the forbidden marriage and the permissible marriage', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 244, NULL, 'Allah the Almighty said: "And do not marry those whom your fathers married of women, except what has already passed; it is an indecency and a hateful thing and an evil way. Forbidden to you are your mothers, your daughters..." (al-Nisa 22–23). Allah, Mighty and Majestic, has thus forbidden in the plain text of His Book the marriage of those He named explicitly, and the Messenger of Allah ﷺ and the Imams of his house made clear what required clarification.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'allah the almighty said and do not marry those whom your fathers married of women except what has already passed it is an indecency and a hateful thing and an evil way forbidden to you are your mothers your daughters al nisa 22 23 allah mighty and majestic has thus forbidden in the plain text of his book the marriage of those he named explicitly and the messenger of allah ﷺ and the imams of his house made clear what required clarification', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'marriage and the household', '6. Marriage and the Household', 245, NULL, 'An-Nisa: 23وَرَبَٓئِبُكُمُ ٱلَّتِى فِى حُجُورِكُم مِّن نِّسَآئِكُمُ ٱلَّتِى دَخَلْتُم بِهِنَّ فَإِن لَّمْ تَكُونُوا۟ دَخَلْتُم بِهِنَّ فَلَا جُنَاحَ عَلَيْكُمْ', '', 'وَرَبَٓئِبُكُمُ ٱلَّتِى فِى حُجُورِكُم مِّن نِّسَآئِكُمُ ٱلَّتِى دَخَلْتُم بِهِنَّ فَإِن لَّمْ تَكُونُوا۟ دَخَلْتُم بِهِنَّ فَلَا جُنَاحَ عَلَيْكُمْ', 'An-Nisa: 23', 4, 23, 'mukhtasar ul asaar 2 6 marriage and the household', 'an nisa 23وربيبكم التي في حجوركم من نسايكم التي دخلتم بهن فان لم تكونوا دخلتم بهن فلا جناح عليكم', 'وربيبكم التي في حجوركم من نسايكم التي دخلتم بهن فان لم تكونوا دخلتم بهن فلا جناح عليكم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 246, NULL, 'Both Ali and Abu Abd-Allah are reported to have held that a wife''s mother is forbidden without qualification: the moment a man contracts a marriage with a woman, her mother becomes unlawful to him, whether or not the marriage has been consummated.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'both ali and abu abd allah are reported to have held that a wifes mother is forbidden without qualification the moment a man contracts a marriage with a woman her mother becomes unlawful to him whether or not the marriage has been consummated', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 247, NULL, 'They said that if a man marries a woman and then divorces her, or if she dies before consummation, her daughter remains lawful to him. This accords with the words of Allah: "And your stepdaughters under your guardianship, born of your wives with whom you have consummated marriage; but if you have not consummated with them — فَإِن لَّمْ تَكُونُوا۟ دَخَلْتُم بِهِنَّ فَلَا جُنَاحَ عَلَيْكُمْ — there is no blame upon you" (al-Nisa 23). The word تكونوا۟ fixes the condition on the husband''s act; بهن names the wives in question; and جناح — the blame — is what is lifted when consummation has not occurred. The "guardianship" spoken of in the verse is the bond of inviolability. If the marriage with the mother was consummated, however, her daughter becomes forbidden to him; and the same prohibition holds if he has seen of her what other men are not permitted to see — in that case too he may not marry her daughter.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'they said that if a man marries a woman and then divorces her or if she dies before consummation her daughter remains lawful to him this accords with the words of allah and your stepdaughters under your guardianship born of your wives with whom you have consummated marriage but if you have not consummated with them فان لم تكونوا دخلتم بهن فلا جناح عليكم there is no blame upon you al nisa 23 the word تكونوا fixes the condition on the husbands act بهن names the wives in question and جناح the blame is what is lifted when consummation has not occurred the guardianship spoken of in the verse is the bond of inviolability if the marriage with the mother was consummated however her daughter becomes forbidden to him and the same prohibition holds if he has seen of her what other men are not permitted to see in that case too he may not marry her daughter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 248, NULL, 'From Jafar ibn Muhammad it was transmitted concerning a man who marries a woman and then dies while she is still his wife, or divorces her before consummation: she is forbidden to his son through every generation that descends from him, and to his fathers however far the line ascends. Likewise, if a man looks upon his bondswoman with desire, or touches her, or looks upon her nakedness, she becomes forbidden to his sons and to his fathers. If, however, one of them owned her without approaching her, without touching her, and without looking upon her with desire, and another then came to own her, she is lawful to him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'from jafar ibn muhammad it was transmitted concerning a man who marries a woman and then dies while she is still his wife or divorces her before consummation she is forbidden to his son through every generation that descends from him and to his fathers however far the line ascends likewise if a man looks upon his bondswoman with desire or touches her or looks upon her nakedness she becomes forbidden to his sons and to his fathers if however one of them owned her without approaching her without touching her and without looking upon her with desire and another then came to own her she is lawful to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 249, NULL, 'The ruling permitted two sisters to be owned together while forbidding their combination in marriage. If a man has approached one of the two, the other becomes forbidden to him; he may not approach the second until the first has left his ownership — whether by manumission, by sale, or by gift. Transferring her to his son does not suffice. If the first sister dies, the other becomes lawful to him. What is forbidden is solely their combination, for God says: "And that you combine two sisters" (al-Nisa 23), and that verse draws no distinction between the bondswoman and the free woman.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the ruling permitted two sisters to be owned together while forbidding their combination in marriage if a man has approached one of the two the other becomes forbidden to him he may not approach the second until the first has left his ownership whether by manumission by sale or by gift transferring her to his son does not suffice if the first sister dies the other becomes lawful to him what is forbidden is solely their combination for god says and that you combine two sisters al nisa 23 and that verse draws no distinction between the bondswoman and the free woman', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 250, NULL, 'A man may not marry the sister of a woman he has divorced until her waiting period has elapsed and his right of revocation over her is fully extinguished. For as long as that right remains, he has in effect joined the two sisters together. If the divorce was final and irrevocable, however, he may marry her sister, or any other woman, provided he has no more than three other free wives besides her. It was also transmitted from Ali, Abu Jafar, and Abu Abd-Allah that a woman may not be joined in marriage with her paternal aunt, nor with her maternal aunt.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'a man may not marry the sister of a woman he has divorced until her waiting period has elapsed and his right of revocation over her is fully extinguished for as long as that right remains he has in effect joined the two sisters together if the divorce was final and irrevocable however he may marry her sister or any other woman provided he has no more than three other free wives besides her it was also transmitted from ali abu jafar and abu abd allah that a woman may not be joined in marriage with her paternal aunt nor with her maternal aunt', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 251, NULL, 'Ali said: "The Messenger of Allah and his family forbade that, and made it unlawful. The daughter of Hamza was offered to him in marriage, and he said: Do you not know that she is the daughter of my brother through suckling, for I was nursed together with Hamza."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'ali said the messenger of allah and his family forbade that and made it unlawful the daughter of hamza was offered to him in marriage and he said do you not know that she is the daughter of my brother through suckling for i was nursed together with hamza', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 252, NULL, 'They saw no harm in joining the daughters of paternal uncles with the daughters of maternal uncles, nor in a man''s marrying both his wife and a daughter of his by another woman. Likewise, if a man divorces a woman or dies, and another man then marries her, there is no harm in the son of her first husband — by a different wife — marrying the daughter of her second husband by a different wife.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'they saw no harm in joining the daughters of paternal uncles with the daughters of maternal uncles nor in a mans marrying both his wife and a daughter of his by another woman likewise if a man divorces a woman or dies and another man then marries her there is no harm in the son of her first husband by a different wife marrying the daughter of her second husband by a different wife', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 253, NULL, 'They held that if a man commits fornication with his wife''s mother, her sister, or her daughter, that act does not corrupt the marriage, for the unlawful does not corrupt the lawful. If, however, he commits fornication with a woman and she subsequently bears a child, it is not proper for his son by another wife to marry that woman''s daughter. Permission was granted in the case of the woman with whom a man had committed fornication, once both parties had repented.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'they held that if a man commits fornication with his wifes mother her sister or her daughter that act does not corrupt the marriage for the unlawful does not corrupt the lawful if however he commits fornication with a woman and she subsequently bears a child it is not proper for his son by another wife to marry that womans daughter permission was granted in the case of the woman with whom a man had committed fornication once both parties had repented', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 254, NULL, 'It was narrated from Ali concerning a woman who commits adultery before her husband has consummated the marriage with her: they are to be separated, she is owed no dowry, and the prescribed punishment — the hadd — is carried out upon her. Her dowry is forfeited because the offense arose from her side. The separation, however, rests upon the husband''s will: if he chooses to remain with her, she is still his wife.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was narrated from ali concerning a woman who commits adultery before her husband has consummated the marriage with her they are to be separated she is owed no dowry and the prescribed punishment the hadd is carried out upon her her dowry is forfeited because the offense arose from her side the separation however rests upon the husbands will if he chooses to remain with her she is still his wife', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 255, NULL, 'Abu Jafar Muhammad ibn Ali, when asked about a sick man who contracts a marriage and then dies, said that the marriage is valid and she inherits from him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'abu jafar muhammad ibn ali when asked about a sick man who contracts a marriage and then dies said that the marriage is valid and she inherits from him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 256, NULL, 'Jafar ibn Muhammad was reported to have ruled on the case of a man who marries two sisters, or five women, in a single contract:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'jafar ibn muhammad was reported to have ruled on the case of a man who marries two sisters or five women in a single contract', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 257, NULL, 'The sister whose name was spoken first at the time of the contract has a valid marriage; the marriage of the second sister is annulled. Of the five women, the first four have valid marriages; the marriage of the fifth is annulled. If it cannot be determined which name was mentioned first, the entire contract is void.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the sister whose name was spoken first at the time of the contract has a valid marriage the marriage of the second sister is annulled of the five women the first four have valid marriages the marriage of the fifth is annulled if it cannot be determined which name was mentioned first the entire contract is void', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 258, NULL, 'Concerning a man who marries a woman during her waiting period, or who marries while either party is in a state of consecration, both knowing the act to be unlawful: they are separated, and she is never again lawful to him. If they were ignorant of the prohibition, they are separated, but may contract a new marriage once she becomes lawful to suitors.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'concerning a man who marries a woman during her waiting period or who marries while either party is in a state of consecration both knowing the act to be unlawful they are separated and she is never again lawful to him if they were ignorant of the prohibition they are separated but may contract a new marriage once she becomes lawful to suitors', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 259, NULL, 'Mentioning the Missing Husband', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'mentioning the missing husband', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 260, NULL, 'Abu Jafar Muhammad ibn Ali was reported to have said: if a man is reported dead to his family, and his wife on that basis observes her waiting period and then remarries, and the first husband subsequently returns — the first husband has the greater right to her, regardless of whether the second husband has consummated the marriage. If the second husband has consummated it, she is entitled to her dowry for what was made lawful from her.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'abu jafar muhammad ibn ali was reported to have said if a man is reported dead to his family and his wife on that basis observes her waiting period and then remarries and the first husband subsequently returns the first husband has the greater right to her regardless of whether the second husband has consummated the marriage if the second husband has consummated it she is entitled to her dowry for what was made lawful from her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 261, NULL, 'Jafar ibn Muhammad said: the wife of a missing man is to remain in her situation for as long as she keeps silent. If she brings her case before the governor, however, he sets for her a waiting period of four years and writes to make inquiries about her husband. If those four years pass with no news of him, the governor summons the missing man''s guardian and asks whether the missing man has any wealth. If he does — and the guardian spends upon her from it, or spends upon her from his own means — she has no grounds to remarry. If the guardian will not maintain her and the missing man has no wealth, the governor compels the guardian to pronounce a single divorce at the onset of her waiting period while she is in a state of purity; that divorce by the guardian stands as the husband''s own divorce. Should her husband return before her waiting period is complete, he has the greater right to her. If her waiting period has ended, she is lawful to other suitors.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'jafar ibn muhammad said the wife of a missing man is to remain in her situation for as long as she keeps silent if she brings her case before the governor however he sets for her a waiting period of four years and writes to make inquiries about her husband if those four years pass with no news of him the governor summons the missing mans guardian and asks whether the missing man has any wealth if he does and the guardian spends upon her from it or spends upon her from his own means she has no grounds to remarry if the guardian will not maintain her and the missing man has no wealth the governor compels the guardian to pronounce a single divorce at the onset of her waiting period while she is in a state of purity that divorce by the guardian stands as the husbands own divorce should her husband return before her waiting period is complete he has the greater right to her if her waiting period has ended she is lawful to other suitors', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 262, NULL, 'It was said to him: O son of the Messenger of Allah and his family, what is to be done if the guardian does provide for her, yet she says, "I cannot be patient; I want what other women have"? He answered that she has no such recourse, and no claim to it, so long as the guardian provides for her.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was said to him o son of the messenger of allah and his family what is to be done if the guardian does provide for her yet she says i cannot be patient i want what other women have he answered that she has no such recourse and no claim to it so long as the guardian provides for her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 263, NULL, 'The missing man — al-mafqud — is one who has left his home and whose whereabouts are unknown. He may have been seen between two battle lines in time of war, after which the people scattered and he was lost; or he may have been aboard a ship that capsized; or it may simply be that no one from the journey knows where he settled. A man whose location is known, by contrast, does not fall under this ruling. His wife is treated as the wife of an absent man — al-ghaib: she may not remarry unless he dies or divorces her. The Master said: if the whereabouts of the absent man are known, his wife may not remarry.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the missing man al mafqud is one who has left his home and whose whereabouts are unknown he may have been seen between two battle lines in time of war after which the people scattered and he was lost or he may have been aboard a ship that capsized or it may simply be that no one from the journey knows where he settled a man whose location is known by contrast does not fall under this ruling his wife is treated as the wife of an absent man al ghaib she may not remarry unless he dies or divorces her the master said if the whereabouts of the absent man are known his wife may not remarry', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 264, NULL, 'On Breastfeeding (al-Rida)', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'on breastfeeding al rida', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'marriage and the household', '6. Marriage and the Household', 265, NULL, 'An-Nisa: 23وَرَبَٓئِبُكُمُ ٱلَّتِى فِى حُجُورِكُم مِّن نِّسَآئِكُمُ ٱلَّتِى دَخَلْتُم بِهِنَّ فَإِن لَّمْ تَكُونُوا۟ دَخَلْتُم بِهِنَّ فَلَا جُنَاحَ عَلَيْكُمْ', '', 'وَرَبَٓئِبُكُمُ ٱلَّتِى فِى حُجُورِكُم مِّن نِّسَآئِكُمُ ٱلَّتِى دَخَلْتُم بِهِنَّ فَإِن لَّمْ تَكُونُوا۟ دَخَلْتُم بِهِنَّ فَلَا جُنَاحَ عَلَيْكُمْ', 'An-Nisa: 23', 4, 23, 'mukhtasar ul asaar 2 6 marriage and the household', 'an nisa 23وربيبكم التي في حجوركم من نسايكم التي دخلتم بهن فان لم تكونوا دخلتم بهن فلا جناح عليكم', 'وربيبكم التي في حجوركم من نسايكم التي دخلتم بهن فان لم تكونوا دخلتم بهن فلا جناح عليكم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 266, NULL, 'The saying of God Almighty has already been cited: ﴿وَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ وَأَخَوَاتُكُم مِّنَ الرَّضَاعَةِ﴾ — "and your mothers who have suckled you, and your sisters through breastfeeding." It is narrated from the Imams of the family of the Messenger of Allah that whatever is forbidden through lineage is likewise forbidden through breastfeeding. The women forbidden in marriage have already been set out, and whoever comes, through breastfeeding, to occupy the place of one of them holds the same standing of prohibition.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the saying of god almighty has already been cited وامهاتكم اللاتي ارضعنكم واخواتكم من الرضاعه and your mothers who have suckled you and your sisters through breastfeeding it is narrated from the imams of the family of the messenger of allah that whatever is forbidden through lineage is likewise forbidden through breastfeeding the women forbidden in marriage have already been set out and whoever comes through breastfeeding to occupy the place of one of them holds the same standing of prohibition', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 267, NULL, 'A man may marry a woman who has breastfed his sons, and he may marry those of her daughters whom she did not nurse alongside him, since such a woman is neither his mother through breastfeeding nor a wife of his father. He may likewise marry the daughter of a woman who breastfed his brother or his sister. In the same way, a man may marry the daughters of women who breastfed his son — and their daughters as well — for they did not nurse him, and no bond, whether through breastfeeding or otherwise, exists between them and him. What is forbidden is marrying the nursing woman herself. Paternal and maternal cousins through breastfeeding, however, are lawful in marriage, just as they are lawful through lineage. A man may marry a woman while his father marries her daughter by another man, and a father and son may each marry one of two sisters.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'a man may marry a woman who has breastfed his sons and he may marry those of her daughters whom she did not nurse alongside him since such a woman is neither his mother through breastfeeding nor a wife of his father he may likewise marry the daughter of a woman who breastfed his brother or his sister in the same way a man may marry the daughters of women who breastfed his son and their daughters as well for they did not nurse him and no bond whether through breastfeeding or otherwise exists between them and him what is forbidden is marrying the nursing woman herself paternal and maternal cousins through breastfeeding however are lawful in marriage just as they are lawful through lineage a man may marry a woman while his father marries her daughter by another man and a father and son may each marry one of two sisters', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 268, NULL, 'Ali is reported to have said that breastfeeding creates prohibition whether the amount is little or much — even a single suckle suffices to establish it, by the word of Allah Almighty, ﴿وَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ﴾, "and your mothers who have suckled you." The ruling applies equally to a small amount and a large one, for even a small quantity nourishes: from it flesh and blood grow, and bone is strengthened in proportion.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'ali is reported to have said that breastfeeding creates prohibition whether the amount is little or much even a single suckle suffices to establish it by the word of allah almighty وامهاتكم اللاتي ارضعنكم and your mothers who have suckled you the ruling applies equally to a small amount and a large one for even a small quantity nourishes from it flesh and blood grow and bone is strengthened in proportion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 269, NULL, 'Ali is also reported to have said that the breastfeeding which creates prohibition is that which takes place within the first two years of life, for Allah says: ﴿وَالْوَالِدَاتُ يُرْضِعْنَ أَوْلَادَهُنَّ حَوْلَيْنِ كَامِلَيْنِ لِمَنْ أَرَادَ أَن يُتِمَّ الرَّضَاعَةَ﴾, "and mothers shall suckle their children for two complete years, for whoever wishes to complete the suckling." Whatever occurs after those two years does not constitute breastfeeding and establishes no prohibition. The Messenger of Allah (upon him and his family be peace) said: "لَا رِضَاعَ بَعْدَ فِطَامٍ" — "There is no breastfeeding after weaning."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'ali is also reported to have said that the breastfeeding which creates prohibition is that which takes place within the first two years of life for allah says والوالدات يرضعن اولادهن حولين كاملين لمن اراد ان يتم الرضاعه and mothers shall suckle their children for two complete years for whoever wishes to complete the suckling whatever occurs after those two years does not constitute breastfeeding and establishes no prohibition the messenger of allah upon him and his family be peace said لا رضاع بعد فطام there is no breastfeeding after weaning', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 270, NULL, 'From Ali, Abu Jafar, and Abu Abd Allah it is narrated concerning a woman who gives her husband her milk to drink — intending by that device to make herself forbidden to him — or who gives her milk to her bondswoman, or nurses her, with the same aim: they said that the man may discipline his wife for such conduct, but that no prohibition arises from it, because the breastfeeding of an adult does not count as breastfeeding. If a man is suckled after two years have elapsed from his birth, or if a wife gives her husband her milk to drink, nothing is thereby made forbidden. Whatever occurs before the two years, however — whether by suckling directly, by drinking a woman''s milk, or by its being administered into the throat (wajur) or the nose (saut) — constitutes breastfeeding and carries the ruling in full.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'from ali abu jafar and abu abd allah it is narrated concerning a woman who gives her husband her milk to drink intending by that device to make herself forbidden to him or who gives her milk to her bondswoman or nurses her with the same aim they said that the man may discipline his wife for such conduct but that no prohibition arises from it because the breastfeeding of an adult does not count as breastfeeding if a man is suckled after two years have elapsed from his birth or if a wife gives her husband her milk to drink nothing is thereby made forbidden whatever occurs before the two years however whether by suckling directly by drinking a womans milk or by its being administered into the throat wajur or the nose saut constitutes breastfeeding and carries the ruling in full', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 271, NULL, 'The milk of the stallion creates prohibition — meaning milk attributed to the man who fathered it. This applies when a man has several wives, or umm-walad mothers, in his household, and one of them nurses a slave boy while another nurses a slave girl: the two become siblings through breastfeeding, even though they did not nurse at the breast of one woman. The one father unites them, for they were nourished by the milk of his wives, and the milk is attributed to him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the milk of the stallion creates prohibition meaning milk attributed to the man who fathered it this applies when a man has several wives or umm walad mothers in his household and one of them nurses a slave boy while another nurses a slave girl the two become siblings through breastfeeding even though they did not nurse at the breast of one woman the one father unites them for they were nourished by the milk of his wives and the milk is attributed to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 272, NULL, 'Abu Jafar Muhammad ibn Ali was asked about the wife of a man who had nursed a slave girl: could the man''s son by another woman lawfully marry her? He said: No. He was then asked whether the slave girl stood to that son as a sister through breastfeeding. He said: Yes, from the father''s side.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'abu jafar muhammad ibn ali was asked about the wife of a man who had nursed a slave girl could the mans son by another woman lawfully marry her he said no he was then asked whether the slave girl stood to that son as a sister through breastfeeding he said yes from the fathers side', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 273, NULL, 'He went on to put a case: a man had two wives, each of whom had borne him a son, and one of the two wives nursed a slave girl belonging to other people. He said that the other son may not marry that slave girl, for she was nursed by the milk of the same father — and what lineage forbids, breastfeeding forbids.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he went on to put a case a man had two wives each of whom had borne him a son and one of the two wives nursed a slave girl belonging to other people he said that the other son may not marry that slave girl for she was nursed by the milk of the same father and what lineage forbids breastfeeding forbids', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 274, NULL, 'When asked about a slave girl belonging to a man whose wife, or the mother of his child, claimed to have nursed her, he said that the woman was not to be believed, since she was drawing a benefit to herself. Regarding a woman who said she had nursed a slave boy and a slave girl and then retracted that claim, he said that her retraction stood. It was put to him: what if she later withdrew her denial and again claimed to have nursed them? He said she was not to be believed. The testimony of a single upright woman is accepted in matters of breastfeeding; but where no upright woman is available, her testimony alone does not suffice.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'when asked about a slave girl belonging to a man whose wife or the mother of his child claimed to have nursed her he said that the woman was not to be believed since she was drawing a benefit to herself regarding a woman who said she had nursed a slave boy and a slave girl and then retracted that claim he said that her retraction stood it was put to him what if she later withdrew her denial and again claimed to have nursed them he said she was not to be believed the testimony of a single upright woman is accepted in matters of breastfeeding but where no upright woman is available her testimony alone does not suffice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 275, NULL, 'They forbade seeking a wet-nurse whose milk comes of fornication — as in the case of a woman who commits adultery and bears a child by it. Such a woman was not to be sought as a wet-nurse, nor taken as a foster-nurse (zir), and neither was her daughter born of adultery. They did, however, permit seeking a wet-nurse among polytheist women who were within a marriage, while disapproving of seeking one from the milk of those known for enmity toward the family of Muhammad and his family. Breastfeeding by the milk of fornication makes nothing forbidden. Jafar ibn Muhammad said that unlawful milk does not render the lawful unlawful — as in the case of a woman nursed first by lawful milk and afterward by the milk of fornication. He said that whoever nurses a girl with the milk of fornication does not thereby make it forbidden to marry her, because unlawful milk does not render the lawful forbidden.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'they forbade seeking a wet nurse whose milk comes of fornication as in the case of a woman who commits adultery and bears a child by it such a woman was not to be sought as a wet nurse nor taken as a foster nurse zir and neither was her daughter born of adultery they did however permit seeking a wet nurse among polytheist women who were within a marriage while disapproving of seeking one from the milk of those known for enmity toward the family of muhammad and his family breastfeeding by the milk of fornication makes nothing forbidden jafar ibn muhammad said that unlawful milk does not render the lawful unlawful as in the case of a woman nursed first by lawful milk and afterward by the milk of fornication he said that whoever nurses a girl with the milk of fornication does not thereby make it forbidden to marry her because unlawful milk does not render the lawful forbidden', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 276, NULL, 'A ruling attributed to Ali holds that if a man marries a woman, pays her dowry, and then — before consummating the marriage — a nursing relationship between them comes to light, she must return to him what she received. It was also narrated from the Messenger of Allah and his family that he forbade women from freely nursing boys they do not know.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'a ruling attributed to ali holds that if a man marries a woman pays her dowry and then before consummating the marriage a nursing relationship between them comes to light she must return to him what she received it was also narrated from the messenger of allah and his family that he forbade women from freely nursing boys they do not know', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 277, NULL, 'On the Marriage of Bondswomen (Nikah al-Ima)', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'on the marriage of bondswomen nikah al ima', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'marriage and the household', '6. Marriage and the Household', 278, NULL, 'An-Nisa: 25وَمَن لَّمْ يَسْتَطِعْ مِنكُمْ طَوْلًا أَن يَنكِحَ ٱلْمُحْصَنَتِ ٱلْمُؤْمِنَتِ فَمِن مَّا مَلَكَتْ أَيْمَنُكُم مِّن فَتَيَتِكُمُ ٱلْمُؤْمِنَتِ', '', 'وَمَن لَّمْ يَسْتَطِعْ مِنكُمْ طَوْلًا أَن يَنكِحَ ٱلْمُحْصَنَتِ ٱلْمُؤْمِنَتِ فَمِن مَّا مَلَكَتْ أَيْمَنُكُم مِّن فَتَيَتِكُمُ ٱلْمُؤْمِنَتِ', 'An-Nisa: 25', 4, 25, 'mukhtasar ul asaar 2 6 marriage and the household', 'an nisa 25ومن لم يستطع منكم طولا ان ينكح المحصنت المومنت فمن ما ملكت ايمنكم من فتيتكم المومنت', 'ومن لم يستطع منكم طولا ان ينكح المحصنت المومنت فمن ما ملكت ايمنكم من فتيتكم المومنت');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 279, NULL, 'Allah Almighty said: ﴿وَمَن لَّمْ يَسْتَطِعْ مِنكُمْ طَوْلًا أَن يَنكِحَ الْمُحْصَنَاتِ الْمُؤْمِنَاتِ فَمِن مَّا مَلَكَتْ أَيْمَانُكُم مِّن فَتَيَاتِكُمُ الْمُؤْمِنَاتِ﴾, up to His saying ﴿ذَٰلِكَ لِمَنْ خَشِيَ الْعَنَتَ مِنكُمْ ۚ وَأَن تَصْبِرُوا خَيْرٌ لَّكُمْ ۗ وَاللَّهُ غَفُورٌ رَّحِيمٌ﴾: "And whoever among you cannot afford to marry free believing women, then from those whom your right hands possess, of your believing bondswomen" — up to His saying, "That is for him among you who fears falling into sin; and that you be patient is better for you, and Allah is Forgiving, Merciful."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'allah almighty said ومن لم يستطع منكم طولا ان ينكح المحصنات المومنات فمن ما ملكت ايمانكم من فتياتكم المومنات up to his saying ذلك لمن خشي العنت منكم وان تصبروا خير لكم والله غفور رحيم and whoever among you cannot afford to marry free believing women then from those whom your right hands possess of your believing bondswomen up to his saying that is for him among you who fears falling into sin and that you be patient is better for you and allah is forgiving merciful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 280, NULL, 'Ali, commenting on the words of Allah Almighty ﴿ذَٰلِكَ لِمَنْ خَشِيَ الْعَنَتَ مِنكُمْ﴾ — "That is for him among you who fears falling into sin" — said that the sin referred to is adultery, and nothing else. A free Muslim may not marry a bondswoman unless he fears being overwhelmed by desire and lacks the means to marry a free woman. If he has the means to marry a free woman, he may not marry a bondswoman; and if he does not fear falling into sin, he likewise may not marry her. Allah Almighty has permitted free men to marry bondswomen only upon these two conditions.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'ali commenting on the words of allah almighty ذلك لمن خشي العنت منكم that is for him among you who fears falling into sin said that the sin referred to is adultery and nothing else a free muslim may not marry a bondswoman unless he fears being overwhelmed by desire and lacks the means to marry a free woman if he has the means to marry a free woman he may not marry a bondswoman and if he does not fear falling into sin he likewise may not marry her allah almighty has permitted free men to marry bondswomen only upon these two conditions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 281, NULL, 'Abu Abd Allah Jafar ibn Muhammad said that a free man may not marry a bondswoman until two conditions are met in him together:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'abu abd allah jafar ibn muhammad said that a free man may not marry a bondswoman until two conditions are met in him together', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 282, NULL, 'the fear of sin, and the lack of means to marry a free woman.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the fear of sin and the lack of means to marry a free woman', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 283, NULL, 'Only when both are present may he marry her.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'only when both are present may he marry her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 284, NULL, 'When a free man marries a bondswoman, the children she bears him belong to her master as slaves — unless he stipulates at the time of marriage that whatever children she bears shall be free, in which case they are free. The ruling on the child follows the ruling on the mother, in freedom as in bondage. If a slave marries a free woman, their children are free, and his master may not stipulate that the free woman''s children be slaves, as he might stipulate regarding the children of a bondswoman. This is because the freeing of a bondswoman''s children rests with her master, who may free them if he wishes. A free woman, by contrast, cannot hold ownership of her own children while they are free, nor can anyone else.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'when a free man marries a bondswoman the children she bears him belong to her master as slaves unless he stipulates at the time of marriage that whatever children she bears shall be free in which case they are free the ruling on the child follows the ruling on the mother in freedom as in bondage if a slave marries a free woman their children are free and his master may not stipulate that the free womans children be slaves as he might stipulate regarding the children of a bondswoman this is because the freeing of a bondswomans children rests with her master who may free them if he wishes a free woman by contrast cannot hold ownership of her own children while they are free nor can anyone else', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 285, NULL, 'A bondswoman may not be given in marriage except with the permission of her master, for Allah says: ﴿فَانكِحُوهُنَّ بِإِذْنِ أَهْلِهِنَّ﴾ — "So marry them with the permission of their families." When a bondswoman is jointly owned by two men, she is not lawful to either of them, even if the other permits it, because a person cannot be divided, nor can a divided share be made lawful by gift. If one of the two gives her in marriage without his partner''s permission, the marriage is not valid unless the other ratifies it. The husband may not consummate the marriage until the second owner permits it; if he does not permit it, the marriage is dissolved.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'a bondswoman may not be given in marriage except with the permission of her master for allah says فانكحوهن باذن اهلهن so marry them with the permission of their families when a bondswoman is jointly owned by two men she is not lawful to either of them even if the other permits it because a person cannot be divided nor can a divided share be made lawful by gift if one of the two gives her in marriage without his partners permission the marriage is not valid unless the other ratifies it the husband may not consummate the marriage until the second owner permits it if he does not permit it the marriage is dissolved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 286, NULL, 'Abu Abd Allah Jafar ibn Muhammad was asked about a bondswoman jointly owned by two men, one of whom gives her in marriage while the other is absent: is the marriage valid? He said that if the absent owner is averse to it, it is not valid.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'abu abd allah jafar ibn muhammad was asked about a bondswoman jointly owned by two men one of whom gives her in marriage while the other is absent is the marriage valid he said that if the absent owner is averse to it it is not valid', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 287, NULL, 'It was narrated from Ali that he said: it is not lawful for a free Muslim to marry a Jewish or a Christian bondswoman, for Allah Almighty says ﴿مِّن فَتَيَاتِكُمُ الْمُؤْمِنَاتِ﴾ — "of your believing bondswomen." Likewise, a free man should not marry a Magian or a polytheist bondswoman; for were that lawful, the polytheists would come to enslave the children of the Muslims. If a man wishes to marry a bondswoman, let him free her first, and then marry her if he wishes and she wishes.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was narrated from ali that he said it is not lawful for a free muslim to marry a jewish or a christian bondswoman for allah almighty says من فتياتكم المومنات of your believing bondswomen likewise a free man should not marry a magian or a polytheist bondswoman for were that lawful the polytheists would come to enslave the children of the muslims if a man wishes to marry a bondswoman let him free her first and then marry her if he wishes and she wishes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 288, NULL, 'The Messenger of Allah ((ع) and his family) married Safiyyah bint Huyayy ibn Akhtab and drew the veil (حِجَاب) over her. Jafar ibn Muhammad said: any man who frees his slave woman and wishes to marry her, let it be with witnesses and an appointed dower; and if he makes her emancipation her dower, that is permitted, as has been explained in the foregoing.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the messenger of allah ع and his family married safiyyah bint huyayy ibn akhtab and drew the veil حجاب over her jafar ibn muhammad said any man who frees his slave woman and wishes to marry her let it be with witnesses and an appointed dower and if he makes her emancipation her dower that is permitted as has been explained in the foregoing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 289, NULL, 'A woman under a contract of emancipation (mukatabah) may be married with the permission of her master. Ali was asked about the marriage of a mukatabah, and he said: she may marry; and whatever child is born to her during her contract of emancipation stands in her own position, so that of that child what is freed in her is freed, and what remains in bondage in her remains in bondage. That reckoning is taken up in the chapter on emancipation contracts, if Allah wills.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'a woman under a contract of emancipation mukatabah may be married with the permission of her master ali was asked about the marriage of a mukatabah and he said she may marry and whatever child is born to her during her contract of emancipation stands in her own position so that of that child what is freed in her is freed and what remains in bondage in her remains in bondage that reckoning is taken up in the chapter on emancipation contracts if allah wills', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 290, NULL, 'Ali is reported to have said that if a man marries a bondswoman while already married to a free wife, the two are to be separated. He is liable for her dower in proportion to what he made lawful of her person, but only if the marriage was consummated; if it was not, she is owed nothing.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'ali is reported to have said that if a man marries a bondswoman while already married to a free wife the two are to be separated he is liable for her dower in proportion to what he made lawful of her person but only if the marriage was consummated if it was not she is owed nothing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 291, NULL, 'Abu Abd Allah Jafar ibn Muhammad said: if a man marries a free woman alongside a bondswoman and the free woman knows of the arrangement, he may divide his time between them — two portions to the free woman and one to the bondswoman. If the free woman did not know at the time of her marriage that he had a bondswoman, and she learns of it afterward, the choice is hers: she may remain with him, or she may leave his bond. If she chooses to leave and the marriage was consummated, she is owed the dower for what he made lawful of her person; if it was not consummated and she parts from him, she is owed nothing.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'abu abd allah jafar ibn muhammad said if a man marries a free woman alongside a bondswoman and the free woman knows of the arrangement he may divide his time between them two portions to the free woman and one to the bondswoman if the free woman did not know at the time of her marriage that he had a bondswoman and she learns of it afterward the choice is hers she may remain with him or she may leave his bond if she chooses to leave and the marriage was consummated she is owed the dower for what he made lawful of her person if it was not consummated and she parts from him she is owed nothing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 292, NULL, 'It was narrated from him that a free man may not lawfully marry a bondswoman on her own. If he marries a free woman and a bondswoman in a single contract, the determining factor is whose name opened the contract: if the free woman''s name came first, the bondswoman''s marriage is void; if the bondswoman''s name came first and the free woman consents to remain alongside her, both marriages stand — provided the man is one for whom marriage to a bondswoman is lawful, as already described. A man may contract marriage upon a free woman even when he lacks the means for her dower; but if he does have the means, the bondswoman''s marriage is void regardless of whether her name came first or second. Equally, if it cannot be established with which of them the bondswoman''s marriage began, that marriage is invalid.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was narrated from him that a free man may not lawfully marry a bondswoman on her own if he marries a free woman and a bondswoman in a single contract the determining factor is whose name opened the contract if the free womans name came first the bondswomans marriage is void if the bondswomans name came first and the free woman consents to remain alongside her both marriages stand provided the man is one for whom marriage to a bondswoman is lawful as already described a man may contract marriage upon a free woman even when he lacks the means for her dower but if he does have the means the bondswomans marriage is void regardless of whether her name came first or second equally if it cannot be established with which of them the bondswomans marriage began that marriage is invalid', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 293, NULL, 'He was then asked about the maintenance (نَفَقَة) owed to a bondswoman wife. He said: when a free man marries a bondswoman, she serves her household by day and comes to her husband by night, and he owes her maintenance so long as this arrangement holds; but if her people bar her from him at night, he owes her no maintenance.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he was then asked about the maintenance نفقه owed to a bondswoman wife he said when a free man marries a bondswoman she serves her household by day and comes to her husband by night and he owes her maintenance so long as this arrangement holds but if her people bar her from him at night he owes her no maintenance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 294, NULL, 'Jafar ibn Muhammad was asked about a man whose young children own a slave girl: may he lie with her? He said: if he desires her, let him set a fair value on himself for her, so that her price stands against him as a debt owed to his children; he then owns her and may lie with her if he wishes. If the children are grown, however, she is not lawful to him unless they sell her to him, and it is not lawful for him to proceed otherwise. A man has no right to any part of his child''s wealth except by the child''s own goodwill — save that, if he is driven to it, he may eat of it what sustains him, in the customary measure and without excess, when he is in hardship and the child is wealthy.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'jafar ibn muhammad was asked about a man whose young children own a slave girl may he lie with her he said if he desires her let him set a fair value on himself for her so that her price stands against him as a debt owed to his children he then owns her and may lie with her if he wishes if the children are grown however she is not lawful to him unless they sell her to him and it is not lawful for him to proceed otherwise a man has no right to any part of his childs wealth except by the childs own goodwill save that if he is driven to it he may eat of it what sustains him in the customary measure and without excess when he is in hardship and the child is wealthy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 295, NULL, 'It was also narrated from him that he was asked about a man who had a slave girl, and his wife — fearing that he would take her for himself — ordered her son to lie with her, and he did. He said: she has sinned, and her son has sinned, and the son is liable to the prescribed punishment (hadd) if he is an adult. He further disapproved of men approaching her thereafter, even though she is by that act forbidden to the master, because the unlawful does not render the lawful forbidden.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was also narrated from him that he was asked about a man who had a slave girl and his wife fearing that he would take her for himself ordered her son to lie with her and he did he said she has sinned and her son has sinned and the son is liable to the prescribed punishment hadd if he is an adult he further disapproved of men approaching her thereafter even though she is by that act forbidden to the master because the unlawful does not render the lawful forbidden', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 296, NULL, 'From Ali it was transmitted that he disapproved of a man lying with a bondswoman over whom another person holds a stipulated right. A mudabbarah may be married with her master''s permission, and her legal status remains that of a bondswoman until her master dies, at which point she is freed. If a bondswoman is freed while already married: should her husband be a free man, she remains his wife and has no choice in the matter; should he be a slave, she has the choice, upon her emancipation, to remain with him or to leave.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'from ali it was transmitted that he disapproved of a man lying with a bondswoman over whom another person holds a stipulated right a mudabbarah may be married with her masters permission and her legal status remains that of a bondswoman until her master dies at which point she is freed if a bondswoman is freed while already married should her husband be a free man she remains his wife and has no choice in the matter should he be a slave she has the choice upon her emancipation to remain with him or to leave', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 297, NULL, 'The case of the freed slave woman is settled by what the Messenger of Allah and his family did with Barirah. She was a slave woman married to a slave man, and her situation caused her grief. When she was set free, the Messenger of Allah gave her the choice, and she chose herself over her husband. He then ordered her to observe a waiting period of three menstrual cycles. It was further stated that if a bondswoman''s master assists her in fulfilling her emancipation contract — even if she is elderly — she has no right of choice against her husband on account of that assistance.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the case of the freed slave woman is settled by what the messenger of allah and his family did with barirah she was a slave woman married to a slave man and her situation caused her grief when she was set free the messenger of allah gave her the choice and she chose herself over her husband he then ordered her to observe a waiting period of three menstrual cycles it was further stated that if a bondswomans master assists her in fulfilling her emancipation contract even if she is elderly she has no right of choice against her husband on account of that assistance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 298, NULL, 'The marriage of slaves', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the marriage of slaves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 299, NULL, 'Allah, exalted be He, said: ﴿ عَبْدًا مَمْلُوكًا لَا يَقْدِرُ عَلَىٰ شَيْءٍ ﴾ — "A slave who is owned and has no power over anything" (al-Nahl: 75). The Messenger of Allah and his family forbade a slave to marry without the permission of his master. He said that any free woman who gives herself in marriage to a slave without the permission of her guardian has made her person unlawful and is owed no dower — this being the case when the master denies the marriage. If the master permits his slave to marry, however, the marriage is valid, and the dower falls upon the master when he consents to it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'allah exalted be he said عبدا مملوكا لا يقدر علي شيء a slave who is owned and has no power over anything al nahl 75 the messenger of allah and his family forbade a slave to marry without the permission of his master he said that any free woman who gives herself in marriage to a slave without the permission of her guardian has made her person unlawful and is owed no dower this being the case when the master denies the marriage if the master permits his slave to marry however the marriage is valid and the dower falls upon the master when he consents to it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 300, NULL, 'Jafar ibn Muhammad was asked about a man who marries his own slave woman to one of his male slaves. He said that the master declares, "I have given her to you in marriage," and gives her some small thing as a dower. The right of separation remains in the master''s hand:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'jafar ibn muhammad was asked about a man who marries his own slave woman to one of his male slaves he said that the master declares i have given her to you in marriage and gives her some small thing as a dower the right of separation remains in the masters hand', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 301, NULL, 'If he wishes, he may part them without a divorce. If he sells the male slave, that sale is itself a separation between them. If he sells them together, the buyer may part them if he wishes.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'if he wishes he may part them without a divorce if he sells the male slave that sale is itself a separation between them if he sells them together the buyer may part them if he wishes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 302, NULL, 'Jafar ibn Muhammad held that if a slave woman is sold while she has a free husband, she remains his wife. Her person is not lawful to the buyer until the husband either divorces her or dies and she completes her waiting period. From Ali comes the ruling that if a woman comes to own her husband — or any portion of him — the marriage is dissolved by the ownership itself, and she becomes the owner of her own person. It is not lawful for a woman to marry her own slave unless she first frees him; if she wishes, she may free him and marry him afterward.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'jafar ibn muhammad held that if a slave woman is sold while she has a free husband she remains his wife her person is not lawful to the buyer until the husband either divorces her or dies and she completes her waiting period from ali comes the ruling that if a woman comes to own her husband or any portion of him the marriage is dissolved by the ownership itself and she becomes the owner of her own person it is not lawful for a woman to marry her own slave unless she first frees him if she wishes she may free him and marry him afterward', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 303, NULL, 'From Jafar ibn Muhammad: a slave may buy and sell, and may approach whichever of the slave women his master has permitted him. He may not marry more than two free women. He may, however, marry up to four slave women, and the divorce of any woman he marries rests in his master''s hand — the master may divorce them on the slave''s behalf whenever he wishes.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'from jafar ibn muhammad a slave may buy and sell and may approach whichever of the slave women his master has permitted him he may not marry more than two free women he may however marry up to four slave women and the divorce of any woman he marries rests in his masters hand the master may divorce them on the slaves behalf whenever he wishes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 304, NULL, 'The marriage of polytheists', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the marriage of polytheists', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 305, NULL, 'The marriages of polytheists among themselves are valid when contracted according to the requirements of their own religion, whether the two parties belong to the same religious community or to different ones, and it is not fitting that such marriages be annulled.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the marriages of polytheists among themselves are valid when contracted according to the requirements of their own religion whether the two parties belong to the same religious community or to different ones and it is not fitting that such marriages be annulled', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 306, NULL, 'It is narrated from Ali that he said: if a man and his wife are taken among the spoils together, their marriage holds. Even if the husband is captured some days after the wife, they remain as they were — unless one of them is carried off and brought into the House of Islam. Should that occur, the marriage is dissolved, and she is not lawful to him except by a new contract, regardless of which of the two was taken first. So long as either of them remains a captive among the spoils, their marriage stands between them. Once one of them enters the House of Islam, however, the marriage is dissolved.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it is narrated from ali that he said if a man and his wife are taken among the spoils together their marriage holds even if the husband is captured some days after the wife they remain as they were unless one of them is carried off and brought into the house of islam should that occur the marriage is dissolved and she is not lawful to him except by a new contract regardless of which of the two was taken first so long as either of them remains a captive among the spoils their marriage stands between them once one of them enters the house of islam however the marriage is dissolved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 307, NULL, 'If the wife embraces Islam and her husband is then captured after her conversion, and she has already passed three menstrual cycles — yet she had not been carried away and her husband had not embraced Islam — they remain upon their marriage. The one who owns them both may separate them if he wishes, as he may with any of his other slaves, unless at the time of their capture they were granted safe conduct on the condition that they not be parted, and that condition was formally contracted for them — in which case their separation is not obligatory.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'if the wife embraces islam and her husband is then captured after her conversion and she has already passed three menstrual cycles yet she had not been carried away and her husband had not embraced islam they remain upon their marriage the one who owns them both may separate them if he wishes as he may with any of his other slaves unless at the time of their capture they were granted safe conduct on the condition that they not be parted and that condition was formally contracted for them in which case their separation is not obligatory', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 308, NULL, 'According to a transmission from Ali, it is not lawful for Muslims to marry polytheist women in the abode of war while the rulings of the polytheists hold sway there. A further transmission from him states that if a woman from the abode of war is granted safe conduct and enters the House of Islam while she still has a polytheist husband, his marital bond to her is severed. She may remarry after her waiting period has cleared her womb. Should her husband then enter under safe conduct as a Muslim, he has no claim upon her except through a new marriage, for the bond was already severed the moment she entered the House of Islam.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'according to a transmission from ali it is not lawful for muslims to marry polytheist women in the abode of war while the rulings of the polytheists hold sway there a further transmission from him states that if a woman from the abode of war is granted safe conduct and enters the house of islam while she still has a polytheist husband his marital bond to her is severed she may remarry after her waiting period has cleared her womb should her husband then enter under safe conduct as a muslim he has no claim upon her except through a new marriage for the bond was already severed the moment she entered the house of islam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 309, NULL, 'If a man embraces Islam while his wife remains a polytheist, she stays his wife. If a woman embraces Islam while her husband remains a polytheist, a separation is made between them. Should her husband embrace Islam before her waiting period expires, they remain upon their marriage; if her waiting period has run its course, she becomes the owner of her own person.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'if a man embraces islam while his wife remains a polytheist she stays his wife if a woman embraces islam while her husband remains a polytheist a separation is made between them should her husband embrace islam before her waiting period expires they remain upon their marriage if her waiting period has run its course she becomes the owner of her own person', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 310, NULL, 'Both Ali and Abu Jafar transmitted a prohibition against marrying Christian women of Arab descent and against eating animals slaughtered by them.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'both ali and abu jafar transmitted a prohibition against marrying christian women of arab descent and against eating animals slaughtered by them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 311, NULL, 'Ali also transmitted a ruling on the apostate who renounces his faith and joins the abode of war: he stands in the position of a dead man. His wealth is distributed among his heirs, his wives observe the waiting period prescribed for widows, and they may then remarry as they wish.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'ali also transmitted a ruling on the apostate who renounces his faith and joins the abode of war he stands in the position of a dead man his wealth is distributed among his heirs his wives observe the waiting period prescribed for widows and they may then remarry as they wish', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 312, NULL, 'From Jafar ibn Muhammad: if a woman embraces Islam while her husband remains a polytheist, she is separated from him should he fail to embrace Islam, and she retains her full dower. If he had not yet consummated the marriage, she is entitled to half the dower. Where polytheists embrace Islam together, their existing marriages remain intact. The Messenger of Allah and his family said: "Confirm the people of the age of ignorance upon whatever state they entered Islam, whether of marriage, divorce, or inheritance."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'from jafar ibn muhammad if a woman embraces islam while her husband remains a polytheist she is separated from him should he fail to embrace islam and she retains her full dower if he had not yet consummated the marriage she is entitled to half the dower where polytheists embrace islam together their existing marriages remain intact the messenger of allah and his family said confirm the people of the age of ignorance upon whatever state they entered islam whether of marriage divorce or inheritance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 313, NULL, 'From Ali, on the polytheist who embraces Islam while he has two free sisters as wives, or more than four free wives:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'from ali on the polytheist who embraces islam while he has two free sisters as wives or more than four free wives', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 314, NULL, 'He is left with the first of the two sisters he married, and a separation is made between him and the second. A separation is likewise made between him and any wives he took beyond the four free women.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he is left with the first of the two sisters he married and a separation is made between him and the second a separation is likewise made between him and any wives he took beyond the four free women', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 315, NULL, 'Ali also transmitted that Allah made the women of the People of the Book lawful to Muslims only when Muslim women were few. When Muslim women became many, Allah, mighty and majestic, said: ﴿ وَلَا تَنْكِحُوا الْمُشْرِكَاتِ حَتَّى يُؤْمِنَّ ﴾ — "And do not marry polytheist women until they believe" (al-Baqarah: 221). And He said: ﴿ وَلَا تُمْسِكُوا بِعِصَمِ الْكَوَافِرِ ﴾ — "And do not hold to the marriage bonds of disbelieving women" (al-Mumtahanah: 10). The Messenger of Allah and his family forbade a Muslim man to marry a non-Muslim woman while he is able to find a Muslim woman, and forbade a polytheist to marry a Muslim woman.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'ali also transmitted that allah made the women of the people of the book lawful to muslims only when muslim women were few when muslim women became many allah mighty and majestic said ولا تنكحوا المشركات حتي يومن and do not marry polytheist women until they believe al baqarah 221 and he said ولا تمسكوا بعصم الكوافر and do not hold to the marriage bonds of disbelieving women al mumtahanah 10 the messenger of allah and his family forbade a muslim man to marry a non muslim woman while he is able to find a muslim woman and forbade a polytheist to marry a muslim woman', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 316, NULL, 'If a polytheist embraces Islam while his wife is still a polytheist, he may keep her with him if he wishes, in the hope that Allah, mighty and majestic, will guide her, and he may take up to three Muslim women as additional wives, provided she is aware of her standing. If he marries a Muslim woman while the polytheist wife remains in his household, and the Muslim woman does not know of this, and she discovers it after consummation, the matter is placed in her own hand: she may stay if she chooses, or she may go. She is entitled to her dower for what was made lawful of her person, and once her waiting period has elapsed she may marry whomever she wishes, without need of a divorce. If, however, he divorces the polytheist wife before the waiting period — counted from the day the Muslim wife exercised her choice — has elapsed, then he holds the greater right to the Muslim wife.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'if a polytheist embraces islam while his wife is still a polytheist he may keep her with him if he wishes in the hope that allah mighty and majestic will guide her and he may take up to three muslim women as additional wives provided she is aware of her standing if he marries a muslim woman while the polytheist wife remains in his household and the muslim woman does not know of this and she discovers it after consummation the matter is placed in her own hand she may stay if she chooses or she may go she is entitled to her dower for what was made lawful of her person and once her waiting period has elapsed she may marry whomever she wishes without need of a divorce if however he divorces the polytheist wife before the waiting period counted from the day the muslim wife exercised her choice has elapsed then he holds the greater right to the muslim wife', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 317, NULL, 'The division of turns among co-wives', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the division of turns among co wives', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 318, NULL, 'Allah, mighty and majestic, said: ﴿ وَلَنْ تَسْتَطِيعُوا أَنْ تَعْدِلُوا بَيْنَ النِّسَاءِ وَلَوْ حَرَصْتُمْ فَلَا تَمِيلُوا كُلَّ الْمَيْلِ فَتَذَرُوهَا كَالْمُعَلَّقَةِ ﴾ — "You will never be able to deal justly between wives, even though you are eager to do so; yet do not incline altogether away, so as to leave her as one suspended" (al-Nisa: 129). With this, the Exalted made plain that perfect justice between wives in matters of affection, desire, and ardor — setting aside intercourse — lies beyond a man''s reach, whereas justice in matters of maintenance, lodging, gifts, and the like can indeed be practiced. It therefore falls upon a man who has several wives to spend time with each of them, by day and by night, in turn.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'allah mighty and majestic said ولن تستطيعوا ان تعدلوا بين النساء ولو حرصتم فلا تميلوا كل الميل فتذروها كالمعلقه you will never be able to deal justly between wives even though you are eager to do so yet do not incline altogether away so as to leave her as one suspended al nisa 129 with this the exalted made plain that perfect justice between wives in matters of affection desire and ardor setting aside intercourse lies beyond a mans reach whereas justice in matters of maintenance lodging gifts and the like can indeed be practiced it therefore falls upon a man who has several wives to spend time with each of them by day and by night in turn', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 319, NULL, 'Jafar ibn Muhammad was asked about a man who has several wives and is intimate with some but not others. He said that the man is obliged to spend each wife''s allotted night with her and to remain through her morning. If he feels no stirring toward intercourse, nothing is held against him; but if he does feel such a stirring while with one of his wives, it is not fitting that he turn away from her and withhold himself for another.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'jafar ibn muhammad was asked about a man who has several wives and is intimate with some but not others he said that the man is obliged to spend each wifes allotted night with her and to remain through her morning if he feels no stirring toward intercourse nothing is held against him but if he does feel such a stirring while with one of his wives it is not fitting that he turn away from her and withhold himself for another', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 320, NULL, 'From Ali, when he was asked about a man who has wives and then sets out on a journey: he said that on returning the man should begin with the wife whose turn is due. Ali also said that if a man has only one wife, it is not fitting that he leave her without spending the night with her at least one night in four; in the remaining three nights he may do as Allah has made lawful for him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'from ali when he was asked about a man who has wives and then sets out on a journey he said that on returning the man should begin with the wife whose turn is due ali also said that if a man has only one wife it is not fitting that he leave her without spending the night with her at least one night in four in the remaining three nights he may do as allah has made lawful for him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 321, NULL, 'Jafar ibn Muhammad said that if a man has two wives, he may reserve three nights for himself and assign to one wife her single night, devoting the other night to the second wife. Likewise, if he has three wives, he assigns each her night and devotes the fourth night to whichever of them he wishes. If he has four wives, he may not favor one above another.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'jafar ibn muhammad said that if a man has two wives he may reserve three nights for himself and assign to one wife her single night devoting the other night to the second wife likewise if he has three wives he assigns each her night and devotes the fourth night to whichever of them he wishes if he has four wives he may not favor one above another', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 322, NULL, 'From Ali: if a man who already has one wife or several wives takes a new wife, he stays with her seven nights if she is a virgin, and three nights if she has been married before. After that, he divides his nights equally among all his wives.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'from ali if a man who already has one wife or several wives takes a new wife he stays with her seven nights if she is a virgin and three nights if she has been married before after that he divides his nights equally among all his wives', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 323, NULL, 'Ali was also asked about the words of Allah, mighty and majestic: ﴿ وَإِنِ امْرَأَةٌ خَافَتْ مِنْ بَعْلِهَا نُشُوزًا أَوْ إِعْرَاضًا فَلَا جُنَاحَ عَلَيْهِمَا أَنْ يُصْلِحَا بَيْنَهُمَا صُلْحًا وَالصُّلْحُ خَيْرٌ ﴾ — "If a woman fears ill treatment or aversion from her husband, there is no blame upon them if they reach a reconciliation between themselves, and reconciliation is best" (al-Nisa: 128). He said the verse concerns a man with two wives who has become unable to fulfill the rights of one of them — or she is a dhimmi woman — and so turns his attention to the other, intending to divorce the first. She refuses the divorce and instead reaches a settlement with him: either he will visit her from time to time, or she will relinquish her allotted share of his nights.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'ali was also asked about the words of allah mighty and majestic وان امراه خافت من بعلها نشوزا او اعراضا فلا جناح عليهما ان يصلحا بينهما صلحا والصلح خير if a woman fears ill treatment or aversion from her husband there is no blame upon them if they reach a reconciliation between themselves and reconciliation is best al nisa 128 he said the verse concerns a man with two wives who has become unable to fulfill the rights of one of them or she is a dhimmi woman and so turns his attention to the other intending to divorce the first she refuses the divorce and instead reaches a settlement with him either he will visit her from time to time or she will relinquish her allotted share of his nights', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 324, NULL, 'Maintenance owed to wives', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'maintenance owed to wives', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'marriage and the household', '6. Marriage and the Household', 325, NULL, 'Al-Ahzab: 50قَدْ عَلِمْنَا مَا فَرَضْنَا عَلَيْهِمْ فِىٓ أَزْوَجِهِمْ وَمَا مَلَكَتْ أَيْمَنُهُمْ', '', 'قَدْ عَلِمْنَا مَا فَرَضْنَا عَلَيْهِمْ فِىٓ أَزْوَجِهِمْ وَمَا مَلَكَتْ أَيْمَنُهُمْ', 'Al-Ahzab: 50', 33, 50, 'mukhtasar ul asaar 2 6 marriage and the household', 'al ahzab 50قد علمنا ما فرضنا عليهم في ازوجهم وما ملكت ايمنهم', 'قد علمنا ما فرضنا عليهم في ازوجهم وما ملكت ايمنهم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 326, NULL, 'Allah, mighty and majestic, said: ﴿ قَدْ عَلِمْنَا مَا فَرَضْنَا عَلَيْهِمْ فِي أَزْوَاجِهِمْ وَمَا مَلَكَتْ أَيْمَانُهُمْ ﴾, "We have known what We have made obligatory upon them concerning their wives (أزواجهم) and those whom their right hands possess (أيمانهم)" (al-Ahzab: 50). He, the Blessed and Exalted, also said: ﴿ وَارْزُقُوهُمْ فِيهَا وَاكْسُوهُمْ وَقُولُوا لَهُمْ قَوْلًا مَعْرُوفًا ﴾, "And provide for them therein and clothe them, and speak to them words of kindness" (al-Nisa: 5).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'allah mighty and majestic said قد علمنا ما فرضنا عليهم في ازواجهم وما ملكت ايمانهم we have known what we have made obligatory upon them concerning their wives ازواجهم and those whom their right hands possess ايمانهم al ahzab 50 he the blessed and exalted also said وارزقوهم فيها واكسوهم وقولوا لهم قولا معروفا and provide for them therein and clothe them and speak to them words of kindness al nisa 5', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 327, NULL, 'It is narrated from the family of the Messenger of Allah that he addressed the people during the Farewell Pilgrimage, spoke of women, and called on those present to treat them well, saying: "They have over you their sustenance and their clothing in a fitting manner." He — and his family — forbade that a man eat his fill while his family went hungry, and he said: "It is enough sin for a man that he neglect those whom he supports."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it is narrated from the family of the messenger of allah that he addressed the people during the farewell pilgrimage spoke of women and called on those present to treat them well saying they have over you their sustenance and their clothing in a fitting manner he and his family forbade that a man eat his fill while his family went hungry and he said it is enough sin for a man that he neglect those whom he supports', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 328, NULL, 'It is also narrated from him and his family that he said: "There are seven among the foremost of deeds, so keep to them" — and he mentioned maintenance for one''s dependents among them.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it is also narrated from him and his family that he said there are seven among the foremost of deeds so keep to them and he mentioned maintenance for ones dependents among them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 329, NULL, 'Further narrations from him and his family record:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'further narrations from him and his family record', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 330, NULL, '"The severest of trials is many dependents with little wealth, and few dependents is one of the two forms of ease." "Whoever is moderate in his livelihood, Allah provides for him, and whoever is wasteful, Allah deprives him." "When Allah, mighty and majestic, intends good for a household, He grants them understanding in religion, provides them gentleness in their livelihood, and grants them moderation in their affairs." "Gentle moderation is half of livelihood; no man who lives in moderation is ever in want."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'the severest of trials is many dependents with little wealth and few dependents is one of the two forms of ease whoever is moderate in his livelihood allah provides for him and whoever is wasteful allah deprives him when allah mighty and majestic intends good for a household he grants them understanding in religion provides them gentleness in their livelihood and grants them moderation in their affairs gentle moderation is half of livelihood no man who lives in moderation is ever in want', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 331, NULL, 'From Ali: if a man finds nothing to spend on his wife, he is granted a respite. If he brings her what is sufficient to feed her, they are not separated. If he finds nothing at all, a term is set, after which they are separated. Also from him: a woman brought a complaint against her husband for withholding her maintenance in order to harm her, and he had the husband imprisoned on her account. He further ruled that any woman who leaves her husband''s house without his permission is owed no maintenance until she returns.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'from ali if a man finds nothing to spend on his wife he is granted a respite if he brings her what is sufficient to feed her they are not separated if he finds nothing at all a term is set after which they are separated also from him a woman brought a complaint against her husband for withholding her maintenance in order to harm her and he had the husband imprisoned on her account he further ruled that any woman who leaves her husbands house without his permission is owed no maintenance until she returns', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 332, NULL, 'Also from him, concerning the man who divorces his wife while she is still nursing his child: the mother holds the stronger right to nurse the child, and she receives from him what would be paid to a wet nurse. If her husband dies and leaves with her a child of his whom she is nursing, she is entitled to a nurse''s wage drawn from the child''s own wealth — whether that wealth comes from inheritance or from another source — and the guardian has no right to remove the child from her care.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'also from him concerning the man who divorces his wife while she is still nursing his child the mother holds the stronger right to nurse the child and she receives from him what would be paid to a wet nurse if her husband dies and leaves with her a child of his whom she is nursing she is entitled to a nurses wage drawn from the childs own wealth whether that wealth comes from inheritance or from another source and the guardian has no right to remove the child from her care', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'marriage and the household', '6. Marriage and the Household', 333, NULL, 'Al-Furqan: 67وَٱلَّذِينَ إِذَآ أَنفَقُوا۟ لَمْ يُسْرِفُوا۟ وَلَمْ يَقْتُرُوا۟ وَكَانَ بَيْنَ ذَلِكَ قَوَامًۭا', '', 'وَٱلَّذِينَ إِذَآ أَنفَقُوا۟ لَمْ يُسْرِفُوا۟ وَلَمْ يَقْتُرُوا۟ وَكَانَ بَيْنَ ذَلِكَ قَوَامًۭا', 'Al-Furqan: 67', 25, 67, 'mukhtasar ul asaar 2 6 marriage and the household', 'al furqan 67والذين اذا انفقوا لم يسرفوا ولم يقتروا وكان بين ذلك قواما', 'والذين اذا انفقوا لم يسرفوا ولم يقتروا وكان بين ذلك قواما');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 334, NULL, 'Maintenance owed to wives, and to those relatives for whom it is obligatory, is measured against one''s means and capacity. Allah, mighty and majestic, said: ﴿ لِيُنْفِقْ ذُو سَعَةٍ مِنْ سَعَتِهِ وَمَنْ قُدِرَ عَلَيْهِ رِزْقُهُ فَلْيُنْفِقْ مِمَّا آتَاهُ اللَّهُ ﴾ — "Let a man of ample means spend out of his ampleness, and whoever has his provision straitened, let him spend out of what Allah has given him" (al-Talaq: 7). The ruler accordingly imposes on the one who bears the obligation a level of maintenance fitting his station — neither extravagant nor stinting. Allah, mighty and majestic, said: ﴿ وَالَّذِينَ إِذَا أَنْفَقُوا لَمْ يُسْرِفُوا وَلَمْ يَقْتُرُوا وَكَانَ بَيْنَ ذَلِكَ قَوَامًا ﴾ — "And those who, when they spend, are neither extravagant nor stinting, but hold a just balance between the two" (al-Furqan: 67).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'maintenance owed to wives and to those relatives for whom it is obligatory is measured against ones means and capacity allah mighty and majestic said لينفق ذو سعه من سعته ومن قدر عليه رزقه فلينفق مما اتاه الله let a man of ample means spend out of his ampleness and whoever has his provision straitened let him spend out of what allah has given him al talaq 7 the ruler accordingly imposes on the one who bears the obligation a level of maintenance fitting his station neither extravagant nor stinting allah mighty and majestic said والذين اذا انفقوا لم يسرفوا ولم يقتروا وكان بين ذلك قواما and those who when they spend are neither extravagant nor stinting but hold a just balance between the two al furqan 67', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 335, NULL, 'This is a matter well established and without obscurity. It requires neither personal opinion nor independent legal reasoning, for its measure is known by custom in every place and time — varying with need and abundance, with what is available, with cheapness and dearness, and with poverty and wealth.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'this is a matter well established and without obscurity it requires neither personal opinion nor independent legal reasoning for its measure is known by custom in every place and time varying with need and abundance with what is available with cheapness and dearness and with poverty and wealth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 336, NULL, 'Every poor person who is unable to manage his affairs or to work is owed maintenance by whoever would inherit from him at his death, in proportion to that heir''s share of his estate — with one exception: the wife. Her maintenance falls upon her husband alone, and he owes her nothing beyond it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'every poor person who is unable to manage his affairs or to work is owed maintenance by whoever would inherit from him at his death in proportion to that heirs share of his estate with one exception the wife her maintenance falls upon her husband alone and he owes her nothing beyond it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 337, NULL, 'If the one upon whom maintenance is obligatory is himself poor and has nothing to spend, his situation is like that of a person who has no guardian to provide for him: he seeks his provision from the provision of ٱلله, glorified be His mention.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'if the one upon whom maintenance is obligatory is himself poor and has nothing to spend his situation is like that of a person who has no guardian to provide for him he seeks his provision from the provision of الله glorified be his mention', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 338, NULL, 'A man is not bound to provide for a distant relative who would not inherit from him at his death, when his own heir is poor and without means, for maintenance is owed only to those within the circle of inheritance. Allah, mighty and majestic, has excused him from what lies beyond his capacity, in His words: ﴿ لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا ﴾ — "Allah does not burden a soul beyond its capacity" (al-Baqarah: 286) — and in His words: ﴿ لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا مَا آتَاهَا ﴾ — "Allah does not burden a soul except with what He has given it" (al-Talaq: 7).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'a man is not bound to provide for a distant relative who would not inherit from him at his death when his own heir is poor and without means for maintenance is owed only to those within the circle of inheritance allah mighty and majestic has excused him from what lies beyond his capacity in his words لا يكلف الله نفسا الا وسعها allah does not burden a soul beyond its capacity al baqarah 286 and in his words لا يكلف الله نفسا الا ما اتاها allah does not burden a soul except with what he has given it al talaq 7', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 339, NULL, 'Should he afterward come into ease, he provides for those in his charge from that point onward and cannot be held to account for the period already past.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'should he afterward come into ease he provides for those in his charge from that point onward and cannot be held to account for the period already past', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'marriage and the household', '6. Marriage and the Household', 340, NULL, 'Al-Baqarah: 286لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا وُسْعَهَا', '', 'لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا وُسْعَهَا', 'Al-Baqarah: 286', 2, 286, 'mukhtasar ul asaar 2 6 marriage and the household', 'al baqarah 286لا يكلف الله نفسا الا وسعها', 'لا يكلف الله نفسا الا وسعها');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 341, NULL, 'A man of the Ansar once invited the Messenger of Allah ﷺ and his household to a meal, and the Messenger accepted. In the man''s home there was a pregnant slave woman moving back and forth as she served the food. The Messenger of Allah said to him: "What is this?" The man replied: "A slave woman of mine whom I purchased some days ago — she is with child." The Messenger said: "Have you been with her?" He answered: "Yes, O Messenger of Allah, I have." The Messenger of Allah then said to him: "Were it not for the sanctity of your food, I would have called down upon you a curse that would follow you into your grave. Free what is in her womb — your seed has already nourished its hearing, its sight, its flesh, its blood, its hair, and its skin."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'a man of the ansar once invited the messenger of allah ﷺ and his household to a meal and the messenger accepted in the mans home there was a pregnant slave woman moving back and forth as she served the food the messenger of allah said to him what is this the man replied a slave woman of mine whom i purchased some days ago she is with child the messenger said have you been with her he answered yes o messenger of allah i have the messenger of allah then said to him were it not for the sanctity of your food i would have called down upon you a curse that would follow you into your grave free what is in her womb your seed has already nourished its hearing its sight its flesh its blood its hair and its skin', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 342, NULL, 'Ali said: it is not lawful for a man to approach a woman who carries another man''s child until she has delivered and become pure. If he purchases a pregnant slave woman, he must likewise not approach her until she gives birth and becomes pure. From the Messenger of Allah and his household: when a man has been with a slave woman, she is to be cleared by one menstrual cycle.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'ali said it is not lawful for a man to approach a woman who carries another mans child until she has delivered and become pure if he purchases a pregnant slave woman he must likewise not approach her until she gives birth and becomes pure from the messenger of allah and his household when a man has been with a slave woman she is to be cleared by one menstrual cycle', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 343, NULL, 'On istibra', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'on istibra', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 344, NULL, 'Ali said: whoever buys a young slave girl who has not yet reached puberty, shows no sign of it, and presents no risk of pregnancy may approach her if he wishes and is under no obligation to perform istibra upon her.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'ali said whoever buys a young slave girl who has not yet reached puberty shows no sign of it and presents no risk of pregnancy may approach her if he wishes and is under no obligation to perform istibra upon her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 345, NULL, 'He said: whoever buys a slave girl who has despaired of menstruation should set her apart for two months before approaching her. This applies where some doubt remains that she may still menstruate, even though her menses appear to have ceased.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he said whoever buys a slave girl who has despaired of menstruation should set her apart for two months before approaching her this applies where some doubt remains that she may still menstruate even though her menses appear to have ceased', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 346, NULL, 'Abu Abdullah Jafar ibn Muhammad, the prayers of Allah be upon him, said: whoever buys an old woman and knows with certainty that she does not menstruate — there being no doubt in her case — may approach her if he wishes and need not perform istibra.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'abu abdullah jafar ibn muhammad the prayers of allah be upon him said whoever buys an old woman and knows with certainty that she does not menstruate there being no doubt in her case may approach her if he wishes and need not perform istibra', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 347, NULL, 'He said: whoever buys a slave girl from a woman may approach her before performing istibra, and there is no harm in that. If he performs istibra as a safeguard for himself, that is better. The obligation of istibra falls on the seller: if he has been with the slave woman and then wishes to sell her, he must not do so until he has performed istibra upon her by one menstrual cycle, lest she be carrying his child and his offspring be sold along with her.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he said whoever buys a slave girl from a woman may approach her before performing istibra and there is no harm in that if he performs istibra as a safeguard for himself that is better the obligation of istibra falls on the seller if he has been with the slave woman and then wishes to sell her he must not do so until he has performed istibra upon her by one menstrual cycle lest she be carrying his child and his offspring be sold along with her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 348, NULL, 'It was narrated from Ali, the prayers of Allah be upon him, that he said: if a man buys a slave woman who does not menstruate, or one who has reached puberty without having menstruated, he must observe istibra upon her for forty-five nights.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was narrated from ali the prayers of allah be upon him that he said if a man buys a slave woman who does not menstruate or one who has reached puberty without having menstruated he must observe istibra upon her for forty five nights', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 349, NULL, 'Ali, the prayers of Allah be upon him, was asked about a man who bought a slave girl who had reached the age of discernment but had not menstruated and was a virgin, whose seller had taken her back and then sold her. He said that her case was grave: the buyer must perform istibra upon her for nine months, and may approach her afterward only if no pregnancy has appeared — that being the cautious course.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'ali the prayers of allah be upon him was asked about a man who bought a slave girl who had reached the age of discernment but had not menstruated and was a virgin whose seller had taken her back and then sold her he said that her case was grave the buyer must perform istibra upon her for nine months and may approach her afterward only if no pregnancy has appeared that being the cautious course', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 350, NULL, 'It was also related from him concerning a man who buys a slave girl while she is in a state of purity, and whose seller informs him that he has not approached her since her last menstruation, nor during the present purity in which she is. He said that if the seller is trustworthy in the buyer''s eyes, the buyer may approach her if he wishes; and if he performs istibra, that is the more cautious course for him. He further said that whoever buys a slave girl who has had no husband, and whose master has not approached her, must nonetheless perform istibra upon her by one menstrual cycle.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was also related from him concerning a man who buys a slave girl while she is in a state of purity and whose seller informs him that he has not approached her since her last menstruation nor during the present purity in which she is he said that if the seller is trustworthy in the buyers eyes the buyer may approach her if he wishes and if he performs istibra that is the more cautious course for him he further said that whoever buys a slave girl who has had no husband and whose master has not approached her must nonetheless perform istibra upon her by one menstrual cycle', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 351, NULL, 'He was asked about a man who bought a slave girl, then freed her and married her, and whether he might approach her. He said that the man must perform istibra of her womb by one menstrual cycle; and if he approaches her before doing so, there is no harm in it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he was asked about a man who bought a slave girl then freed her and married her and whether he might approach her he said that the man must perform istibra of her womb by one menstrual cycle and if he approaches her before doing so there is no harm in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 352, NULL, 'It was narrated from Jafar ibn Muhammad that he was asked about a man who had lain with his slave woman and then wished to give her in marriage before performing istibra. He said: No. He was then asked by how much the istibra should be performed. He said: by one menstrual cycle, though two are more beloved to him. A man must likewise perform istibra of a slave woman when he wishes to sell her, just as he performs it when he buys her.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was narrated from jafar ibn muhammad that he was asked about a man who had lain with his slave woman and then wished to give her in marriage before performing istibra he said no he was then asked by how much the istibra should be performed he said by one menstrual cycle though two are more beloved to him a man must likewise perform istibra of a slave woman when he wishes to sell her just as he performs it when he buys her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 353, NULL, 'It was narrated from Ali, may the prayers of Allah be upon him, that he said: when a man buys a slave woman, there is no harm in his enjoying of her what falls short of intercourse before he performs istibra — meaning fondling, kissing, and approach short of the private part. It was further narrated from him that he was asked about a man who bought a slave woman and feared she might be pregnant; he said that the man must perform istibra upon her for forty-five nights.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was narrated from ali may the prayers of allah be upon him that he said when a man buys a slave woman there is no harm in his enjoying of her what falls short of intercourse before he performs istibra meaning fondling kissing and approach short of the private part it was further narrated from him that he was asked about a man who bought a slave woman and feared she might be pregnant he said that the man must perform istibra upon her for forty five nights', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 354, NULL, 'He was asked about a slave woman who had committed adultery, whether her master might approach her. He said that the master does not approach her until he has performed istibra upon her. Likewise, if a man commits adultery with a slave woman and then buys her, he ought not to approach her until he has performed istibra upon her. Should she have conceived by him through that adultery, the child is not attributed to him, for the Messenger of Allah said: "الْوَلَدُ لِلْفِرَاشِ وَالْعَاهِرُ الْحَجَرُ" — meaning the child belongs to the marriage bed, and for the fornicator is the stone.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'he was asked about a slave woman who had committed adultery whether her master might approach her he said that the master does not approach her until he has performed istibra upon her likewise if a man commits adultery with a slave woman and then buys her he ought not to approach her until he has performed istibra upon her should she have conceived by him through that adultery the child is not attributed to him for the messenger of allah said الولد للفراش والعاهر الحجر meaning the child belongs to the marriage bed and for the fornicator is the stone', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'marriage and the household', '6. Marriage and the Household', 355, NULL, 'It was narrated from Jafar ibn Muhammad that he said: whoever buys a slave girl while she is menstruating, once she becomes pure he may approach her if he wishes. It was further narrated from Ali that he said concerning a woman taken captive who has a husband: she performs istibra by one menstrual cycle, and once she is pure her master may approach her. And if a woman is coerced and violated, her husband does not approach her until she has performed istibra by one menstrual cycle.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 6 marriage and the household', 'it was narrated from jafar ibn muhammad that he said whoever buys a slave girl while she is menstruating once she becomes pure he may approach her if he wishes it was further narrated from ali that he said concerning a woman taken captive who has a husband she performs istibra by one menstrual cycle and once she is pure her master may approach her and if a woman is coerced and violated her husband does not approach her until she has performed istibra by one menstrual cycle', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 0, NULL, 'Chapters of Divorce', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'chapters of divorce', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 1, NULL, 'At-Talaq: 1يَٓأَيُّهَا ٱلنَّبِىُّ إِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا۟ ٱلْعِدَّةَ', '', 'يَٓأَيُّهَا ٱلنَّبِىُّ إِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا۟ ٱلْعِدَّةَ', 'At-Talaq: 1', 65, 1, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'at talaq 1يايها النبي اذا طلقتم النساء فطلقوهن لعدتهن واحصوا العده', 'يايها النبي اذا طلقتم النساء فطلقوهن لعدتهن واحصوا العده');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 2, NULL, '﴿ يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا الْعِدَّةَ ﴾ "O Prophet, when you divorce women, divorce them at the onset of their waiting period, and count the iddah." And He, glorified and exalted, has said: ﴿ وَإِن يَتَفَرَّقَا يُغْنِ اللَّهُ كُلًّا مِّن سَعَتِهِ ﴾ "And if the two separate, Allah will enrich each of them out of His abundance."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'يا ايها النبي اذا طلقتم النساء فطلقوهن لعدتهن واحصوا العده o prophet when you divorce women divorce them at the onset of their waiting period and count the iddah and he glorified and exalted has said وان يتفرقا يغن الله كلا من سعته and if the two separate allah will enrich each of them out of his abundance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 3, NULL, 'Allah, mighty and majestic, has permitted divorce in His Book and placed it in the hands of men rather than women. A man may divorce his wife whenever he wishes, whether for a cause or for none. Yet it is reported from Ali, may Allah''s prayers be upon him, that he disliked divorce without cause — though he did not forbid it, nor did he invalidate a divorce pronounced without one.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'allah mighty and majestic has permitted divorce in his book and placed it in the hands of men rather than women a man may divorce his wife whenever he wishes whether for a cause or for none yet it is reported from ali may allahs prayers be upon him that he disliked divorce without cause though he did not forbid it nor did he invalidate a divorce pronounced without one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 4, NULL, 'At-Talaq: 1يَٓأَيُّهَا ٱلنَّبِىُّ إِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا۟ ٱلْعِدَّةَ', '', 'يَٓأَيُّهَا ٱلنَّبِىُّ إِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا۟ ٱلْعِدَّةَ', 'At-Talaq: 1', 65, 1, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'at talaq 1يايها النبي اذا طلقتم النساء فطلقوهن لعدتهن واحصوا العده', 'يايها النبي اذا طلقتم النساء فطلقوهن لعدتهن واحصوا العده');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 5, NULL, 'Umm Said, his servant, related that one day she was pouring water over his hands — peace be upon him — when he raised his head toward her and said, "O Umm Said." She said, "At your service, O Commander of the Faithful." He said, "I have longed to be a bridegroom." She said, "And what prevents the Commander of the Faithful from that?" He said, "Woe to you — after four, and in al-Rahbah?" She said, "Then divorce one and bring another in her place." He said, "Woe to you, divorce is an ugly thing, and I dislike it."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'umm said his servant related that one day she was pouring water over his hands peace be upon him when he raised his head toward her and said o umm said she said at your service o commander of the faithful he said i have longed to be a bridegroom she said and what prevents the commander of the faithful from that he said woe to you after four and in al rahbah she said then divorce one and bring another in her place he said woe to you divorce is an ugly thing and i dislike it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 6, NULL, 'Al-Hasan — peace be upon him — was much given to divorce and divorced a great number of women without cause. It is said that he once passed by a group of women who sent word to him asking, "Do you know this company of women?" He said, "No." One of them said, "There is not one among us but that you have married her and then divorced her." The most that Ali — may the prayers of Allah be upon him — said concerning this was: "O people of Kufa, do not give your daughters in marriage to al-Hasan, for he is a man much given to divorce."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'al hasan peace be upon him was much given to divorce and divorced a great number of women without cause it is said that he once passed by a group of women who sent word to him asking do you know this company of women he said no one of them said there is not one among us but that you have married her and then divorced her the most that ali may the prayers of allah be upon him said concerning this was o people of kufa do not give your daughters in marriage to al hasan for he is a man much given to divorce', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 7, NULL, 'The divorce that is forbidden and the divorce that is permitted', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the divorce that is forbidden and the divorce that is permitted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 8, NULL, 'From the Imams of the household of the Messenger of Allah — peace and prayers be upon him and upon the Imams of his household — it is narrated that word was brought to him that Abdullah ibn Umar had divorced his wife three times while she was menstruating. He said to Umar: command him to take her back, then divorce her according to the Sunnah — إذا طلقتم النساء فطلقوهن — if he wishes.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'from the imams of the household of the messenger of allah peace and prayers be upon him and upon the imams of his household it is narrated that word was brought to him that abdullah ibn umar had divorced his wife three times while she was menstruating he said to umar command him to take her back then divorce her according to the sunnah اذا طلقتم النساء فطلقوهن if he wishes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 9, NULL, 'Whoever divorces his wife after consummating the marriage in any of the following circumstances has pronounced no divorce, and she remains his wife:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'whoever divorces his wife after consummating the marriage in any of the following circumstances has pronounced no divorce and she remains his wife', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 10, NULL, 'while she is in a period of purity during which he has already been intimate with her; while she is menstruating; without calling witnesses, as Allah Almighty has commanded; during her postnatal bleeding; by swearing a conditional oath of divorce and then breaking it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'while she is in a period of purity during which he has already been intimate with her while she is menstruating without calling witnesses as allah almighty has commanded during her postnatal bleeding by swearing a conditional oath of divorce and then breaking it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 11, NULL, 'This is the divorce of innovation, for it runs contrary to what Allah, mighty and majestic, has commanded and to the Sunnah of His Messenger concerning divorce according to the Sunnah. Both forms of divorce are, despite the difference in wording, one in substance.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'this is the divorce of innovation for it runs contrary to what allah mighty and majestic has commanded and to the sunnah of his messenger concerning divorce according to the sunnah both forms of divorce are despite the difference in wording one in substance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 12, NULL, 'When a man wishes to divorce his wife — one who menstruates — he waits until she has her period, then becomes pure. Once she has cleansed herself of the blood and bathed after her menses, he divorces her before touching her, in a state of purity in which he has not yet approached her, with a single pronouncement, calling two witnesses of just character, as Allah Almighty has commanded. He retains the stronger right to take her back and may do so if he wishes; she remains with him, with two pronouncements now counted against her, until she has menstruated three full times. When those three periods are complete, she has the stronger right over herself, and he has no path back to her unless both he and she are willing. In that case, he may marry her again by a fresh contract, with a dowry, a guardian, and witnesses, and she remains with him with two pronouncements remaining. This is the Sunnah divorce — the one that is recommended — on account of the words of Allah, mighty and majestic:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'when a man wishes to divorce his wife one who menstruates he waits until she has her period then becomes pure once she has cleansed herself of the blood and bathed after her menses he divorces her before touching her in a state of purity in which he has not yet approached her with a single pronouncement calling two witnesses of just character as allah almighty has commanded he retains the stronger right to take her back and may do so if he wishes she remains with him with two pronouncements now counted against her until she has menstruated three full times when those three periods are complete she has the stronger right over herself and he has no path back to her unless both he and she are willing in that case he may marry her again by a fresh contract with a dowry a guardian and witnesses and she remains with him with two pronouncements remaining this is the sunnah divorce the one that is recommended on account of the words of allah mighty and majestic', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 13, NULL, '﴿ لَا تَدْرِي لَعَلَّ اللَّهَ يُحْدِثُ بَعْدَ ذَٰلِكَ أَمْرًا ﴾', '', '﴿ لَا تَدْرِي لَعَلَّ اللَّهَ يُحْدِثُ بَعْدَ ذَٰلِكَ أَمْرًا ﴾', NULL, 65, 1, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'لا تدري لعل الله يحدث بعد ذلك امرا', 'لا تدري لعل الله يحدث بعد ذلك امرا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 14, NULL, '"You do not know; perhaps Allah will bring about, after that, some new matter" — meaning the taking back.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'you do not know perhaps allah will bring about after that some new matter meaning the taking back', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 15, NULL, 'If he divorces her in the manner first described — with a single pronouncement — and then takes her back before her waiting period has elapsed, or after it by a fresh contract, he may not divorce her again until he has been intimate with her. When he then wishes to divorce her a second time, he leaves her until she menstruates and becomes pure, then pronounces the divorce while she is in a state of purity in which he has not touched her, calling two witnesses of upright character. If he wishes to take her back, he does so in the way described earlier, at any point before her waiting period ends. If her waiting period has elapsed, she has the greater right over herself; and if both he and she are willing, he may marry her again by a renewed contract as previously described. Whether he takes her back or marries her anew in this way, she is his wife, and there now remains against her with him a single pronouncement.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'if he divorces her in the manner first described with a single pronouncement and then takes her back before her waiting period has elapsed or after it by a fresh contract he may not divorce her again until he has been intimate with her when he then wishes to divorce her a second time he leaves her until she menstruates and becomes pure then pronounces the divorce while she is in a state of purity in which he has not touched her calling two witnesses of upright character if he wishes to take her back he does so in the way described earlier at any point before her waiting period ends if her waiting period has elapsed she has the greater right over herself and if both he and she are willing he may marry her again by a renewed contract as previously described whether he takes her back or marries her anew in this way she is his wife and there now remains against her with him a single pronouncement', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 16, NULL, 'If he then wishes to divorce her, he may not do so until he has been intimate with her. He leaves her until she menstruates and becomes pure, then divorces her while she is in a state of purity in which he has not touched her — this time with a third pronouncement. She thereby becomes irrevocably separated from him and is not lawful to him until she has married another husband, as Allah, mighty and majestic, has said.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'if he then wishes to divorce her he may not do so until he has been intimate with her he leaves her until she menstruates and becomes pure then divorces her while she is in a state of purity in which he has not touched her this time with a third pronouncement she thereby becomes irrevocably separated from him and is not lawful to him until she has married another husband as allah mighty and majestic has said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 17, NULL, 'This is the divorce of the iddah: he divorces her, takes her back and is intimate with her, then divorces her across three pronouncements in the manner described. This is the sound and permissible form of divorce, and there is no disagreement on the matter.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'this is the divorce of the iddah he divorces her takes her back and is intimate with her then divorces her across three pronouncements in the manner described this is the sound and permissible form of divorce and there is no disagreement on the matter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 18, NULL, 'If a man divorces his wife twice or three times within a single period of purity, the additional pronouncements are not valid. Once he has pronounced the first divorce, she is divorced; the second pronouncement cannot fall upon her until he has taken her back and she has become his wife again. A divorce pronounced upon a woman who is already divorced does not take effect, just as a divorce pronounced upon a woman who is not one''s wife — without the authorization of her husband — would not take effect.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'if a man divorces his wife twice or three times within a single period of purity the additional pronouncements are not valid once he has pronounced the first divorce she is divorced the second pronouncement cannot fall upon her until he has taken her back and she has become his wife again a divorce pronounced upon a woman who is already divorced does not take effect just as a divorce pronounced upon a woman who is not ones wife without the authorization of her husband would not take effect', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 19, NULL, 'Equally, if he pronounces divorce three times, or names any number of pronouncements, in a single sitting and within a single period of purity, only one divorce falls upon her — provided she was in a period of purity during which he had not been intimate with her.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'equally if he pronounces divorce three times or names any number of pronouncements in a single sitting and within a single period of purity only one divorce falls upon her provided she was in a period of purity during which he had not been intimate with her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 20, NULL, 'The following pronouncements are invalid, because each is contrary to what Allah, mighty and majestic, has commanded concerning divorce and contrary to the Sunnah of His Messenger:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the following pronouncements are invalid because each is contrary to what allah mighty and majestic has commanded concerning divorce and contrary to the sunnah of his messenger', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 21, NULL, 'A divorce pronounced while she is menstruating. A divorce pronounced during a period of purity in which he has been intimate with her. A divorce pronounced without witnesses being called to it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'a divorce pronounced while she is menstruating a divorce pronounced during a period of purity in which he has been intimate with her a divorce pronounced without witnesses being called to it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 22, NULL, 'The same position is held by those who permit this form of divorce and call it a Sunnah of the general body of Muslims, in direct contradiction of the Book and the Sunnah. They concede that the one who pronounces it is a transgressor who has overstepped, yet they maintain that the divorce takes effect and is binding.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the same position is held by those who permit this form of divorce and call it a sunnah of the general body of muslims in direct contradiction of the book and the sunnah they concede that the one who pronounces it is a transgressor who has overstepped yet they maintain that the divorce takes effect and is binding', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 23, NULL, 'The reply put to them is this: what would they say if a man were to contract a marriage contrary to the Book and the Sunnah — marrying a woman while she is still in her waiting period, for instance, or while she already has a husband? Their own position is that such a marriage is impermissible, and they forbid it. When pressed on why they forbid a marriage that contradicts the Book and the Sunnah while permitting a divorce that does the same, they have no proof to offer.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the reply put to them is this what would they say if a man were to contract a marriage contrary to the book and the sunnah marrying a woman while she is still in her waiting period for instance or while she already has a husband their own position is that such a marriage is impermissible and they forbid it when pressed on why they forbid a marriage that contradicts the book and the sunnah while permitting a divorce that does the same they have no proof to offer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 24, NULL, 'The argument is pressed further. This divorce, which they have permitted despite its being contrary to the Book and the Sunnah, is itself what opens the door to a marriage that is contrary to the Book and the Sunnah — the very marriage they declared impermissible in their own doctrine. For this divorce renders the woman forbidden to the man who divorced her and makes her lawful to another who would marry her. Were the divorce invalid, that subsequent marriage would likewise be invalid, since she would remain a woman with a living husband. Their annulment of her first marriage through this divorce is precisely what, on their own reasoning, establishes the validity of her marriage to the second man. The result is that a marriage has been made lawful by means contrary to the Book and the Sunnah — which is the very outcome they themselves reject.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the argument is pressed further this divorce which they have permitted despite its being contrary to the book and the sunnah is itself what opens the door to a marriage that is contrary to the book and the sunnah the very marriage they declared impermissible in their own doctrine for this divorce renders the woman forbidden to the man who divorced her and makes her lawful to another who would marry her were the divorce invalid that subsequent marriage would likewise be invalid since she would remain a woman with a living husband their annulment of her first marriage through this divorce is precisely what on their own reasoning establishes the validity of her marriage to the second man the result is that a marriage has been made lawful by means contrary to the book and the sunnah which is the very outcome they themselves reject', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 25, NULL, 'The arguments that arise in a matter such as this run long, and they pass beyond the bounds of this book.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the arguments that arise in a matter such as this run long and they pass beyond the bounds of this book', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 26, NULL, 'The testimony of women is not admissible in divorce, for Allah, mighty and majestic, said concerning it: ﴿ وَأَشْهِدُوا ذَوَيْ عَدْلٍ مِّنكُمْ ﴾ "And call to witness two of just character from among you."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the testimony of women is not admissible in divorce for allah mighty and majestic said concerning it واشهدوا ذوي عدل منكم and call to witness two of just character from among you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 27, NULL, 'Divorce falls upon five kinds of women, who are divorced under any circumstance, with no waiting for a menstrual cycle or a period of purity:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'divorce falls upon five kinds of women who are divorced under any circumstance with no waiting for a menstrual cycle or a period of purity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 28, NULL, 'The pregnant woman whose pregnancy has become apparent. The young girl who has not yet reached the age of menstruation. The woman past her courses, whose menstruation has ceased entirely. The woman whose husband has not consummated the marriage with her. The woman whose husband is away on a distant journey.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the pregnant woman whose pregnancy has become apparent the young girl who has not yet reached the age of menstruation the woman past her courses whose menstruation has ceased entirely the woman whose husband has not consummated the marriage with her the woman whose husband is away on a distant journey', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 29, NULL, 'Whenever any one of these women is divorced, the divorce takes effect immediately, and she observes her waiting period by counting months — each month standing in place of a menstrual cycle. The exception is the woman with whom the marriage was never consummated: if her husband divorces her, she has no waiting period to observe, in accordance with the words of Allah, mighty and majestic: ﴿ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا ﴾ "You have against them no waiting period that you may count."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'whenever any one of these women is divorced the divorce takes effect immediately and she observes her waiting period by counting months each month standing in place of a menstrual cycle the exception is the woman with whom the marriage was never consummated if her husband divorces her she has no waiting period to observe in accordance with the words of allah mighty and majestic فما لكم عليهن من عده تعتدونها you have against them no waiting period that you may count', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 30, NULL, 'Metaphors for divorce, and the word of divorce', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'metaphors for divorce and the word of divorce', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 31, NULL, 'A husband who intends to divorce his wife may do so by saying to her, "You are divorced," or by naming her and saying, "So-and-so is divorced," or, when she is named to him, by saying, "She is divorced." He may also say to her, "Reckon your waiting period," intending divorce by those words, or convey any of these formulas through a messenger, or direct that "So-and-so should reckon her waiting period." These are the only two vehicles for divorce — the explicit word of divorce and the reference to the waiting period — for they are precisely the two that Allah, mighty and majestic, mentioned in His Book:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'a husband who intends to divorce his wife may do so by saying to her you are divorced or by naming her and saying so and so is divorced or when she is named to him by saying she is divorced he may also say to her reckon your waiting period intending divorce by those words or convey any of these formulas through a messenger or direct that so and so should reckon her waiting period these are the only two vehicles for divorce the explicit word of divorce and the reference to the waiting period for they are precisely the two that allah mighty and majestic mentioned in his book', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 32, NULL, '﴿ يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ ﴾', '', '﴿ يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ ﴾', NULL, 65, 1, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'يا ايها النبي اذا طلقتم النساء فطلقوهن لعدتهن', 'يا ايها النبي اذا طلقتم النساء فطلقوهن لعدتهن');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 33, NULL, '"O Prophet, when you divorce women, divorce them at the onset of their waiting period."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'o prophet when you divorce women divorce them at the onset of their waiting period', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 34, NULL, 'The verse names nothing beyond the divorce itself and the waiting period. Should a husband say to his wife, "You are set loose," or "a wilderness," or "severed," or "cut off," or "forbidden," or any other expression besides these two, his words effect nothing — just as any other speech he might address to her falls outside the category of divorce. Likewise, if he says, "You are forbidden to me," or "your private part is forbidden to me," or declares any part of her forbidden to himself, no legal consequence follows from those words, and she is not rendered forbidden to him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the verse names nothing beyond the divorce itself and the waiting period should a husband say to his wife you are set loose or a wilderness or severed or cut off or forbidden or any other expression besides these two his words effect nothing just as any other speech he might address to her falls outside the category of divorce likewise if he says you are forbidden to me or your private part is forbidden to me or declares any part of her forbidden to himself no legal consequence follows from those words and she is not rendered forbidden to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 35, NULL, 'Abu Jafar Muhammad ibn Ali, prayers of Allah be upon him, is recorded as having said of a man who said to his wife, "You are forbidden to me": had he authority over such a man, he would have struck him soundly on the head, and said to him that Allah made her lawful, and yet he forbids her? The man has done nothing more than lie, claiming that what Allah made lawful to him is forbidden. No divorce falls upon him by those words, nor is any expiation binding.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'abu jafar muhammad ibn ali prayers of allah be upon him is recorded as having said of a man who said to his wife you are forbidden to me had he authority over such a man he would have struck him soundly on the head and said to him that allah made her lawful and yet he forbids her the man has done nothing more than lie claiming that what allah made lawful to him is forbidden no divorce falls upon him by those words nor is any expiation binding', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 36, NULL, 'An objection was put to him: did not the words of Allah, mighty and majestic — ﴿ يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ ﴾ — "O Prophet, why do you forbid what Allah has made lawful to you" — place an expiation in the matter?', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'an objection was put to him did not the words of allah mighty and majestic يا ايها النبي لم تحرم ما احل الله لك o prophet why do you forbid what allah has made lawful to you place an expiation in the matter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 37, NULL, 'He replied that this very verse confirmed the position he had stated. Allah, mighty and majestic, had reproached His Prophet, and He made expiation binding upon him only because the Prophet had, alongside that act, sworn an oath. This is made plain by His words: ﴿ قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ ﴾ — "Allah has ordained for you the absolution of your oaths."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'he replied that this very verse confirmed the position he had stated allah mighty and majestic had reproached his prophet and he made expiation binding upon him only because the prophet had alongside that act sworn an oath this is made plain by his words قد فرض الله لكم تحله ايمانكم allah has ordained for you the absolution of your oaths', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 38, NULL, 'The Master said that this was because the Messenger of Allah had been alone with Mariyah the Copt, his slave woman, before she bore Ibrahim (ع). Aishah came upon this and was grieved by it. Wishing to please her, he forbade Mariyah to himself and swore an oath that he would not approach her again. He confided this to Aishah as a secret and bade her conceal it, but she told it to Hafsah, and the two of them united against the Messenger of Allah. So Allah, mighty and majestic, sent down: "O Prophet, why do you forbid what Allah has made lawful to you, seeking the approval of your wives? And Allah is Forgiving, Merciful. Allah has already ordained for you the absolution of your oaths; and Allah is your Protector, and He is the All-Knowing, the All-Wise. And when the Prophet confided a matter to one of his wives, and she then disclosed it, and Allah made it known to him, he made known part of it and turned away from part; and when he informed her of it, she said, Who told you this? He said, The All-Knowing, the All-Aware told me."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the master said that this was because the messenger of allah had been alone with mariyah the copt his slave woman before she bore ibrahim ع aishah came upon this and was grieved by it wishing to please her he forbade mariyah to himself and swore an oath that he would not approach her again he confided this to aishah as a secret and bade her conceal it but she told it to hafsah and the two of them united against the messenger of allah so allah mighty and majestic sent down o prophet why do you forbid what allah has made lawful to you seeking the approval of your wives and allah is forgiving merciful allah has already ordained for you the absolution of your oaths and allah is your protector and he is the all knowing the all wise and when the prophet confided a matter to one of his wives and she then disclosed it and allah made it known to him he made known part of it and turned away from part and when he informed her of it she said who told you this he said the all knowing the all aware told me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 39, NULL, 'When a man pronounces divorce upon his wife, the only words that carry weight are those Allah Almighty named in His Book, where He said:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'when a man pronounces divorce upon his wife the only words that carry weight are those allah almighty named in his book where he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 40, NULL, '﴿يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ﴾', '', '﴿يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ﴾', NULL, 65, 1, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'يا ايها النبي اذا طلقتم النساء فطلقوهن لعدتهن', 'يا ايها النبي اذا طلقتم النساء فطلقوهن لعدتهن');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 41, NULL, '"O Prophet, when you divorce women, divorce them at the beginning of their waiting period."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'o prophet when you divorce women divorce them at the beginning of their waiting period', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 42, NULL, 'He named nothing but the divorce (al-talaq) and the waiting period (al-idda). If a man says to his wife, "You are loosed," or "You are quit of me," or "You are severed," or "You are cut off," or "You are forbidden," or any such word that falls outside those two terms, it counts for nothing. Such speech is no different from anything else he might say to her that lies beyond them. And if he says, "You are forbidden to me," or "Your body is forbidden to me," or declares any part of her forbidden to himself, no consequence follows, and she does not become unlawful to him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'he named nothing but the divorce al talaq and the waiting period al idda if a man says to his wife you are loosed or you are quit of me or you are severed or you are cut off or you are forbidden or any such word that falls outside those two terms it counts for nothing such speech is no different from anything else he might say to her that lies beyond them and if he says you are forbidden to me or your body is forbidden to me or declares any part of her forbidden to himself no consequence follows and she does not become unlawful to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 43, NULL, 'Abu Jafar Muhammad ibn Ali (ع) said of a man who told his wife, "You are forbidden to me": "Had I any authority over him, I would strike his head and say, Allah made her lawful for you, and then you forbid her? He has done no more than tell a lie, claiming that what Allah made lawful for him is forbidden to him. No divorce enters upon him through that, and no expiation is binding."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'abu jafar muhammad ibn ali ع said of a man who told his wife you are forbidden to me had i any authority over him i would strike his head and say allah made her lawful for you and then you forbid her he has done no more than tell a lie claiming that what allah made lawful for him is forbidden to him no divorce enters upon him through that and no expiation is binding', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 44, NULL, 'Someone raised the objection: "But Allah Almighty says, ﴿يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ﴾ — O Prophet, why do you forbid yourself what Allah has made lawful for you? — and He placed an expiation in it."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'someone raised the objection but allah almighty says يا ايها النبي لم تحرم ما احل الله لك o prophet why do you forbid yourself what allah has made lawful for you and he placed an expiation in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 45, NULL, 'The Master replied: "This confirms what we have said. Allah Almighty was reproaching His Prophet (may Allah''s blessings be upon him and his family). The expiation was laid upon him only because he had joined an oath to it. The proof is His saying, ﴿قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ﴾ — Allah has already ordained for you the absolution of your oaths."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the master replied this confirms what we have said allah almighty was reproaching his prophet may allahs blessings be upon him and his family the expiation was laid upon him only because he had joined an oath to it the proof is his saying قد فرض الله لكم تحله ايمانكم allah has already ordained for you the absolution of your oaths', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 46, NULL, 'The Master then explained the circumstances. The Messenger of Allah (may Allah''s blessings be upon him and his family) had withdrawn in private with Mariya the Copt, his bondwoman, before she gave birth to Ibrahim. Aisha came upon them, and the discovery grieved her. Wishing to appease her, he forbade Mariya to himself and swore that he would not approach her again. He confided this to Aisha and asked her to keep it secret, but she disclosed it to Hafsa, and the two of them united against the Messenger of Allah (may Allah''s blessings be upon him and his family). Allah Almighty then revealed verses concerning the matter, setting things right between the Prophet and his wives. The revelation declared that Jibril, the righteous among the believers, and the angels were his supporters, and that if he were to divorce his wives, his Lord would replace them with wives better than they, as He said:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the master then explained the circumstances the messenger of allah may allahs blessings be upon him and his family had withdrawn in private with mariya the copt his bondwoman before she gave birth to ibrahim aisha came upon them and the discovery grieved her wishing to appease her he forbade mariya to himself and swore that he would not approach her again he confided this to aisha and asked her to keep it secret but she disclosed it to hafsa and the two of them united against the messenger of allah may allahs blessings be upon him and his family allah almighty then revealed verses concerning the matter setting things right between the prophet and his wives the revelation declared that jibril the righteous among the believers and the angels were his supporters and that if he were to divorce his wives his lord would replace them with wives better than they as he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 47, NULL, '﴿عَسَىٰ رَبُّهُ إِن طَلَّقَكُنَّ أَن يُبْدِلَهُ أَزْوَاجًا خَيْرًا مِّنكُنَّ مُسْلِمَاتٍ مُّؤْمِنَاتٍ قَانِتَاتٍ تَائِبَاتٍ عَابِدَاتٍ سَائِحَاتٍ ثَيِّبَاتٍ وَأَبْكَارًا﴾', '', '﴿عَسَىٰ رَبُّهُ إِن طَلَّقَكُنَّ أَن يُبْدِلَهُ أَزْوَاجًا خَيْرًا مِّنكُنَّ مُسْلِمَاتٍ مُّؤْمِنَاتٍ قَانِتَاتٍ تَائِبَاتٍ عَابِدَاتٍ سَائِحَاتٍ ثَيِّبَاتٍ وَأَبْكَارًا﴾', NULL, 66, 5, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'عسي ربه ان طلقكن ان يبدله ازواجا خيرا منكن مسلمات مومنات قانتات تايبات عابدات سايحات ثيبات وابكارا', 'عسي ربه ان طلقكن ان يبدله ازواجا خيرا منكن مسلمات مومنات قانتات تايبات عابدات سايحات ثيبات وابكارا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 48, NULL, '"obedient, believing, devoutly worshipping, repentant, given to worship, given to fasting, both previously married and virgins."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'obedient believing devoutly worshipping repentant given to worship given to fasting both previously married and virgins', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 49, NULL, 'Allah then commanded him to expiate the oath he had sworn. He did so and returned to Mariya, and Ibrahim was born of her. She thus became the mother of his child (may Allah''s blessings be upon him and his family).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'allah then commanded him to expiate the oath he had sworn he did so and returned to mariya and ibrahim was born of her she thus became the mother of his child may allahs blessings be upon him and his family', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 50, NULL, 'The option and the transfer of authority', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the option and the transfer of authority', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 51, NULL, 'Az-Zumar: 9ٱلَّذِينَ يَعْلَمُونَ وَٱلَّذِينَ لَا يَعْلَمُونَ ۗ إِنَّمَا', '', 'ٱلَّذِينَ يَعْلَمُونَ وَٱلَّذِينَ لَا يَعْلَمُونَ ۗ إِنَّمَا', 'Az-Zumar: 9', 39, 9, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'az zumar 9الذين يعلمون والذين لا يعلمون انما', 'الذين يعلمون والذين لا يعلمون انما');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 52, NULL, 'The traditions transmitted from the Imams of the household of the Messenger of Allah ﷺ record that his wives expressed discontent and pressed him for more of the goods of this world, as women are wont to do, and that the most severe among them in this was Hafsa. She said to him, "If you divorced us, we would find among our own people men of equal standing." The Messenger of Allah (may Allah''s blessings be upon him and his family) bore with them patiently, withdrew from their company, and revelation was withheld for twenty days. Then Allah Almighty revealed:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the traditions transmitted from the imams of the household of the messenger of allah ﷺ record that his wives expressed discontent and pressed him for more of the goods of this world as women are wont to do and that the most severe among them in this was hafsa she said to him if you divorced us we would find among our own people men of equal standing the messenger of allah may allahs blessings be upon him and his family bore with them patiently withdrew from their company and revelation was withheld for twenty days then allah almighty revealed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 53, NULL, '﴿يَا أَيُّهَا النَّبِيُّ قُل لِّأَزْوَاجِكَ إِن كُنتُنَّ تُرِدْنَ الْحَيَاةَ الدُّنْيَا وَزِينَتَهَا فَتَعَالَيْنَ أُمَتِّعْكُنَّ وَأُسَرِّحْكُنَّ سَرَاحًا جَمِيلًا ۝ وَإِن كُنتُنَّ تُرِدْنَ اللَّهَ وَرَسُولَهُ وَالدَّارَ الْآخِرَةَ فَإِنَّ اللَّهَ أَعَدَّ لِلْمُحْسِنَاتِ مِنكُنَّ أَجْرًا عَظِيمًا﴾', '', '﴿يَا أَيُّهَا النَّبِيُّ قُل لِّأَزْوَاجِكَ إِن كُنتُنَّ تُرِدْنَ الْحَيَاةَ الدُّنْيَا وَزِينَتَهَا فَتَعَالَيْنَ أُمَتِّعْكُنَّ وَأُسَرِّحْكُنَّ سَرَاحًا جَمِيلًا ۝ وَإِن كُنتُنَّ تُرِدْنَ اللَّهَ وَرَسُولَهُ وَالدَّارَ الْآخِرَةَ فَإِنَّ اللَّهَ أَعَدَّ لِلْمُحْسِنَاتِ مِنكُنَّ أَجْرًا عَظِيمًا﴾', NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'يا ايها النبي قل لازواجك ان كنتن تردن الحياه الدنيا وزينتها فتعالين امتعكن واسرحكن سراحا جميلا وان كنتن تردن الله ورسوله والدار الاخره فان الله اعد للمحسنات منكن اجرا عظيما', 'يا ايها النبي قل لازواجك ان كنتن تردن الحياه الدنيا وزينتها فتعالين امتعكن واسرحكن سراحا جميلا وان كنتن تردن الله ورسوله والدار الاخره فان الله اعد للمحسنات منكن اجرا عظيما');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 54, NULL, 'He withdrew from all of them for twenty-nine nights, keeping to the chamber of Umm Ibrahim. He then called them together, recited to them what Allah had revealed concerning them, offered them the choice, and they chose him — may Allah''s blessings be upon him and his family.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'he withdrew from all of them for twenty nine nights keeping to the chamber of umm ibrahim he then called them together recited to them what allah had revealed concerning them offered them the choice and they chose him may allahs blessings be upon him and his family', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 55, NULL, 'Abu Jafar and Abu Abdillah (عَلَيْهِمُ السَّلَامُ) held that what the Prophet did was not itself a divorce, though had the wives chosen themselves, it would have counted as a single, irrevocable divorce. Abu Abdillah added that when a man wishes to give his wife the option, he should first withdraw from her — as the Messenger of Allah, may Allah''s blessings be upon him and his family, did — until she menstruates and then purifies herself. He then presents the option while she is in a state of purity in which he has not been intimate with her, and he calls witnesses.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'abu jafar and abu abdillah عليهم السلام held that what the prophet did was not itself a divorce though had the wives chosen themselves it would have counted as a single irrevocable divorce abu abdillah added that when a man wishes to give his wife the option he should first withdraw from her as the messenger of allah may allahs blessings be upon him and his family did until she menstruates and then purifies herself he then presents the option while she is in a state of purity in which he has not been intimate with her and he calls witnesses', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 56, NULL, 'If she chooses herself, the divorce is irrevocable and he has no right of return over her. He may court her again, and if both parties wish it, they may contract a new marriage. If she chooses him, no divorce takes place.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'if she chooses herself the divorce is irrevocable and he has no right of return over her he may court her again and if both parties wish it they may contract a new marriage if she chooses him no divorce takes place', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 57, NULL, 'The option is exercised by her saying, "I have chosen myself," or "I have chosen you." Two outcomes follow from what she does next:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the option is exercised by her saying i have chosen myself or i have chosen you two outcomes follow from what she does next', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 58, NULL, 'If she chooses herself, the matter is settled. If she remains silent until one of them rises and they part from where they were sitting, the option lapses.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'if she chooses herself the matter is settled if she remains silent until one of them rises and they part from where they were sitting the option lapses', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 59, NULL, 'Likewise, if he withdraws the option before she has exercised it, she retains no right to choose. If he approaches her — laying his hand upon her, kissing her, or being intimate with her — before she speaks, the option granted to her lapses. If he offers her the option and she says, "I do not accept your option," she has no option.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'likewise if he withdraws the option before she has exercised it she retains no right to choose if he approaches her laying his hand upon her kissing her or being intimate with her before she speaks the option granted to her lapses if he offers her the option and she says i do not accept your option she has no option', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 60, NULL, 'If he grants her the option while she is menstruating, or during a period of purity in which he has been intimate with her, or without two witnesses present, the option counts for nothing.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'if he grants her the option while she is menstruating or during a period of purity in which he has been intimate with her or without two witnesses present the option counts for nothing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 61, NULL, 'The Master said: "No divorce, no khul, no mutual release, and no granting of the option takes effect except by the testimony of two witnesses, during a period of purity untouched by intercourse."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the master said no divorce no khul no mutual release and no granting of the option takes effect except by the testimony of two witnesses during a period of purity untouched by intercourse', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 62, NULL, 'He said: "If a man entrusts the option to his wife, or to her father, or her brother, or her guardian, and she is content that the one entrusted should decide the matter, that is permissible." The transfer of authority carries the same standing as the option itself: it is his saying to her, "I have placed you in command of yourself," or "I have placed your affair in your hands." This stands in the place of his saying to her, "Choose."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'he said if a man entrusts the option to his wife or to her father or her brother or her guardian and she is content that the one entrusted should decide the matter that is permissible the transfer of authority carries the same standing as the option itself it is his saying to her i have placed you in command of yourself or i have placed your affair in your hands this stands in the place of his saying to her choose', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 63, NULL, 'What is binding in divorce and what is not', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'what is binding in divorce and what is not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 64, NULL, 'Narrated from the Imams of the household of the Messenger of Allah ﷺ is that he said, "There is no divorce except after marriage, and no divorce for one who has not married." And Ali (ع) said: "There is no divorce except after marriage, no emancipation except after ownership, no continuous fasting that joins two days without breaking fast, no fasting that is silence from speech from morning until night, no suckling after weaning, and no orphanhood after a child reaches maturity."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'narrated from the imams of the household of the messenger of allah ﷺ is that he said there is no divorce except after marriage and no divorce for one who has not married and ali ع said there is no divorce except after marriage no emancipation except after ownership no continuous fasting that joins two days without breaking fast no fasting that is silence from speech from morning until night no suckling after weaning and no orphanhood after a child reaches maturity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 65, NULL, 'A man put a question to Abu Jafar ibn Muhammad (ع): "I have a kinswoman who has been offered to me in marriage. I wished to marry her, but before today I had said, The day I marry her, she is divorced." Abu Jafar asked whether he had already married her. The man said he had not. Abu Jafar replied that he might marry her if he wished, for divorcing a woman whose marriage bond one does not yet hold is no divorce at all.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'a man put a question to abu jafar ibn muhammad ع i have a kinswoman who has been offered to me in marriage i wished to marry her but before today i had said the day i marry her she is divorced abu jafar asked whether he had already married her the man said he had not abu jafar replied that he might marry her if he wished for divorcing a woman whose marriage bond one does not yet hold is no divorce at all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 66, NULL, 'Abu Abdillah Jafar ibn Muhammad was asked about a man who says, "If I marry such a woman, or marry in such a land, or buy such a slave, or take a concubine, or purchase such-and-such — then the one I marry is divorced, the one I buy or take as concubine is free, and what I buy is given as charity." Abu Abdillah answered that none of this amounted to anything: a man''s divorce of a woman not yet bound to him in marriage is invalid, as is his emancipation of one he does not yet own, and his giving as charity what he does not yet possess.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'abu abdillah jafar ibn muhammad was asked about a man who says if i marry such a woman or marry in such a land or buy such a slave or take a concubine or purchase such and such then the one i marry is divorced the one i buy or take as concubine is free and what i buy is given as charity abu abdillah answered that none of this amounted to anything a mans divorce of a woman not yet bound to him in marriage is invalid as is his emancipation of one he does not yet own and his giving as charity what he does not yet possess', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 67, NULL, 'Abu Abdillah was then asked about a man who divorced his wife while ill, where either her waiting period expired or it did not, and one of the two died. He replied that if her waiting period expired — whether while he was still ill or after he had recovered — he inherits nothing from her; yet she inherits from him should he die of that illness, whether her waiting period has expired or not, unless he recovers.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'abu abdillah was then asked about a man who divorced his wife while ill where either her waiting period expired or it did not and one of the two died he replied that if her waiting period expired whether while he was still ill or after he had recovered he inherits nothing from her yet she inherits from him should he die of that illness whether her waiting period has expired or not unless he recovers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 68, NULL, 'From Ali: "Every divorce is valid" — meaning as duly required — "except the divorce of one bereft of reason." From Abu Jafar and Abu Abdillah alike: the divorce of a man bereft of reason, whose mind has gone from him, is not valid, nor is his emancipation.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'from ali every divorce is valid meaning as duly required except the divorce of one bereft of reason from abu jafar and abu abdillah alike the divorce of a man bereft of reason whose mind has gone from him is not valid nor is his emancipation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 69, NULL, 'Ali was asked about a man who saw in a dream that he had divorced his wife. He said: "That is from Satan. The divorce of a sleeping man is nothing, even if his tongue utters it while he sleeps, until he wakes and pronounces divorce as it is required." No divorce stands from one bereft of reason, nor from one who raves, nor from one in delirium, nor from a boy who has not reached puberty, nor from a drunkard who does not comprehend.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'ali was asked about a man who saw in a dream that he had divorced his wife he said that is from satan the divorce of a sleeping man is nothing even if his tongue utters it while he sleeps until he wakes and pronounces divorce as it is required no divorce stands from one bereft of reason nor from one who raves nor from one in delirium nor from a boy who has not reached puberty nor from a drunkard who does not comprehend', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 70, NULL, 'From Jafar ibn Muhammad: "Whoever is compelled to divorce his wife, his divorce is not valid. There is no divorce and no emancipation under compulsion."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'from jafar ibn muhammad whoever is compelled to divorce his wife his divorce is not valid there is no divorce and no emancipation under compulsion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 71, NULL, 'On the matter of a man who says to his wife, divorce being duly due, "You are divorced one and a half times," the ruling is that she is divorced once, for divorce admits no fractions. The same applies if he says, "You are divorced three quarters, or a quarter, or a sixth of a divorce" — or names any other fraction, or leaves it unnamed: she is divorced once. If a man addresses four wives or fewer, divorce being duly permissible, and says, "I have divorced you, one divorce shared among you," each of them is divorced once. Likewise, if he says, "I have divorced all of you, two divorces shared among you" — or three, or four — each of them is divorced once. And if he says, "I have divorced you, five divorces shared among you," each of them is still bound by only a single divorce. This rests upon the principle already established: within a single period of purity, only one divorce is binding, and whatever exceeds it counts for nothing.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'on the matter of a man who says to his wife divorce being duly due you are divorced one and a half times the ruling is that she is divorced once for divorce admits no fractions the same applies if he says you are divorced three quarters or a quarter or a sixth of a divorce or names any other fraction or leaves it unnamed she is divorced once if a man addresses four wives or fewer divorce being duly permissible and says i have divorced you one divorce shared among you each of them is divorced once likewise if he says i have divorced all of you two divorces shared among you or three or four each of them is divorced once and if he says i have divorced you five divorces shared among you each of them is still bound by only a single divorce this rests upon the principle already established within a single period of purity only one divorce is binding and whatever exceeds it counts for nothing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 72, NULL, 'Khul and mutual release (mubarat)', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'khul and mutual release mubarat', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 73, NULL, 'Allah Almighty said:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'allah almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 74, NULL, '﴿وَلَا يَحِلُّ لَكُمْ أَن تَأْخُذُوا مِمَّا آتَيْتُمُوهُنَّ شَيْئًا إِلَّا أَن يَخَافَا أَلَّا يُقِيمَا حُدُودَ اللَّهِ ۖ فَإِنْ خِفْتُمْ أَلَّا يُقِيمَا حُدُودَ اللَّهِ فَلَا جُنَاحَ عَلَيْهِمَا فِيمَا افْتَدَتْ بِهِ﴾', '', '﴿وَلَا يَحِلُّ لَكُمْ أَن تَأْخُذُوا مِمَّا آتَيْتُمُوهُنَّ شَيْئًا إِلَّا أَن يَخَافَا أَلَّا يُقِيمَا حُدُودَ اللَّهِ ۖ فَإِنْ خِفْتُمْ أَلَّا يُقِيمَا حُدُودَ اللَّهِ فَلَا جُنَاحَ عَلَيْهِمَا فِيمَا افْتَدَتْ بِهِ﴾', NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'ولا يحل لكم ان تاخذوا مما اتيتموهن شييا الا ان يخافا الا يقيما حدود الله فان خفتم الا يقيما حدود الله فلا جناح عليهما فيما افتدت به', 'ولا يحل لكم ان تاخذوا مما اتيتموهن شييا الا ان يخافا الا يقيما حدود الله فان خفتم الا يقيما حدود الله فلا جناح عليهما فيما افتدت به');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 75, NULL, 'The Imams of the household of the Prophet of Allah (may Allah''s blessings be upon him and his family) — among them Ali and the Imams of his line — are reported to have held that khul is permissible when the man places it in its proper context: that is, when his wife says to him, "I fear that I will not maintain the limits of Allah toward you, so I give you such-and-such — set me free," or when her husband says something to the same effect. In either case, it is permissible for them to act on what they have agreed.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the imams of the household of the prophet of allah may allahs blessings be upon him and his family among them ali and the imams of his line are reported to have held that khul is permissible when the man places it in its proper context that is when his wife says to him i fear that i will not maintain the limits of allah toward you so i give you such and such set me free or when her husband says something to the same effect in either case it is permissible for them to act on what they have agreed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 76, NULL, 'Jafar ibn Muhammad said that the husband has no right to take anything from her unless she transgresses in her speech. That transgression consists in her saying to him:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'jafar ibn muhammad said that the husband has no right to take anything from her unless she transgresses in her speech that transgression consists in her saying to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 77, NULL, '"I will not obey any command of yours." "I will not honor any oath to you." "I will not purify myself from impurity for you." "I will not let you share my bed." "I will admit to your house one whom you dislike." "I will enter upon you without your leave."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'i will not obey any command of yours i will not honor any oath to you i will not purify myself from impurity for you i will not let you share my bed i will admit to your house one whom you dislike i will enter upon you without your leave', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 78, NULL, 'Or she says, "I will not maintain the limits of Allah toward you," and makes that plain. When she says such a thing, it becomes lawful for him to take whatever she ransoms herself with, even if it exceeds what he originally gave her. But if she says no such thing, he ought not to take from her more than what he gave her.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'or she says i will not maintain the limits of allah toward you and makes that plain when she says such a thing it becomes lawful for him to take whatever she ransoms herself with even if it exceeds what he originally gave her but if she says no such thing he ought not to take from her more than what he gave her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 79, NULL, 'The Master said: "Khul and mutual release take effect only as divorce does — in a state of purity during which he has not touched her, and before witnesses." When he releases her in this way, he divorces her with a single divorce, as described above. She thereby becomes clearly separated from him, and he has no right of return unless she too consents, so that they reconcile through a fresh marriage. She remains with him according to whatever is left of her divorce count, and he may marry her again — if both parties wish it — whether before her waiting period expires or after.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the master said khul and mutual release take effect only as divorce does in a state of purity during which he has not touched her and before witnesses when he releases her in this way he divorces her with a single divorce as described above she thereby becomes clearly separated from him and he has no right of return unless she too consents so that they reconcile through a fresh marriage she remains with him according to whatever is left of her divorce count and he may marry her again if both parties wish it whether before her waiting period expires or after', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 80, NULL, 'As for the words of Allah Almighty:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'as for the words of allah almighty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 81, NULL, '﴿وَإِنْ خِفْتُمْ شِقَاقَ بَيْنِهِمَا فَابْعَثُوا حَكَمًا مِّنْ أَهْلِهِ وَحَكَمًا مِّنْ أَهْلِهَا إِن يُرِيدَا إِصْلَاحًا يُوَفِّقِ اللَّهُ بَيْنَهُمَا ۗ إِنَّ اللَّهَ كَانَ عَلِيمًا خَبِيرًا﴾', '', '﴿وَإِنْ خِفْتُمْ شِقَاقَ بَيْنِهِمَا فَابْعَثُوا حَكَمًا مِّنْ أَهْلِهِ وَحَكَمًا مِّنْ أَهْلِهَا إِن يُرِيدَا إِصْلَاحًا يُوَفِّقِ اللَّهُ بَيْنَهُمَا ۗ إِنَّ اللَّهَ كَانَ عَلِيمًا خَبِيرًا﴾', NULL, 4, 35, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'وان خفتم شقاق بينهما فابعثوا حكما من اهله وحكما من اهلها ان يريدا اصلاحا يوفق الله بينهما ان الله كان عليما خبيرا', 'وان خفتم شقاق بينهما فابعثوا حكما من اهله وحكما من اهلها ان يريدا اصلاحا يوفق الله بينهما ان الله كان عليما خبيرا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 82, NULL, '"And if you fear a breach between the two, appoint an arbitrator from his family and an arbitrator from her family. If they both desire reconciliation, Allah will bring about agreement between them. Indeed, Allah is All-Knowing, All-Aware."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'and if you fear a breach between the two appoint an arbitrator from his family and an arbitrator from her family if they both desire reconciliation allah will bring about agreement between them indeed allah is all knowing all aware', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 83, NULL, 'It has come from Ali, Abu Jafar, and Abu Abdillah that this verse applies to a husband and wife who fall into discord, cannot reach agreement, and whose quarrel is prolonged until they bring the matter before the ruler. He then appoints an arbitrator from the man''s family and an arbitrator from the woman''s family. If the two arbitrators are able to reconcile the couple, they do so. If reconciliation proves impossible and they move toward separating the couple, they may not do so until both the man and the woman are first consulted. If the couple do not consent to separation, the two are not parted.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'it has come from ali abu jafar and abu abdillah that this verse applies to a husband and wife who fall into discord cannot reach agreement and whose quarrel is prolonged until they bring the matter before the ruler he then appoints an arbitrator from the mans family and an arbitrator from the womans family if the two arbitrators are able to reconcile the couple they do so if reconciliation proves impossible and they move toward separating the couple they may not do so until both the man and the woman are first consulted if the couple do not consent to separation the two are not parted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 84, NULL, 'Al-Ila (the oath of abstention)', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'al ila the oath of abstention', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 85, NULL, 'Allah Almighty said:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'allah almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 86, NULL, '﴿لِّلَّذِينَ يُؤْلُونَ مِن نِّسَائِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ ۖ فَإِن فَاءُوا فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ ۝ وَإِنْ عَزَمُوا الطَّلَاقَ فَإِنَّ اللَّهَ سَمِيعٌ عَلِيمٌ﴾', '', '﴿لِّلَّذِينَ يُؤْلُونَ مِن نِّسَائِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ ۖ فَإِن فَاءُوا فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ ۝ وَإِنْ عَزَمُوا الطَّلَاقَ فَإِنَّ اللَّهَ سَمِيعٌ عَلِيمٌ﴾', NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'للذين يولون من نسايهم تربص اربعه اشهر فان فاءوا فان الله غفور رحيم وان عزموا الطلاق فان الله سميع عليم', 'للذين يولون من نسايهم تربص اربعه اشهر فان فاءوا فان الله غفور رحيم وان عزموا الطلاق فان الله سميع عليم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 87, NULL, '"For those who swear off their wives there is a waiting of four months. Then if they return, Allah is Forgiving, Merciful. But if they are resolved on divorce, then Allah is All-Hearing, All-Knowing."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'for those who swear off their wives there is a waiting of four months then if they return allah is forgiving merciful but if they are resolved on divorce then allah is all hearing all knowing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 88, NULL, 'The Imams of the household of the Messenger — may Allah''s blessings be upon him and his family — transmit this teaching through Ali and the Imams of his line: al-Ila is the oath by which a man swears to his wife that he will not have intercourse with her, keeping apart from her until four months have passed.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the imams of the household of the messenger may allahs blessings be upon him and his family transmit this teaching through ali and the imams of his line al ila is the oath by which a man swears to his wife that he will not have intercourse with her keeping apart from her until four months have passed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 89, NULL, 'Abu Abdillah Jafar ibn Muhammad said: "It is not for the woman to bring her husband to account before four months have passed from the day of his oath. Once four months or more have elapsed, she may bring him to account whenever she wishes, taking the matter to the ruler. When she does so, he gives the husband the choice between returning to her — that is, resuming relations with her in the proper manner — or divorcing her. He must do one of the two. If he merely keeps apart from her without an oath, abstaining for as long as he wishes, that is not al-Ila and is not counted a divorce, until the woman takes the matter to the ruler and the ruler compels him: either he returns or he divorces then and there. Al-Ila takes effect only in a state of purity untouched by intercourse, and with witnesses, as divorce does. It falls only upon a wife whose marriage has been consummated; it does not fall upon one with whom he has not yet been intimate."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'abu abdillah jafar ibn muhammad said it is not for the woman to bring her husband to account before four months have passed from the day of his oath once four months or more have elapsed she may bring him to account whenever she wishes taking the matter to the ruler when she does so he gives the husband the choice between returning to her that is resuming relations with her in the proper manner or divorcing her he must do one of the two if he merely keeps apart from her without an oath abstaining for as long as he wishes that is not al ila and is not counted a divorce until the woman takes the matter to the ruler and the ruler compels him either he returns or he divorces then and there al ila takes effect only in a state of purity untouched by intercourse and with witnesses as divorce does it falls only upon a wife whose marriage has been consummated it does not fall upon one with whom he has not yet been intimate', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 90, NULL, 'A man is at liberty when he swears off his wife for four months or less. Once four months pass and she brings him to account, nothing is lawful for him but to return to her in the proper manner or to divorce her. The return is intercourse. If he is unable to do so through illness, a chronic complaint, or travel, and he affirms his return with his tongue and calls witnesses, that suffices and is permissible. When he is able, he returns to her in the proper manner.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'a man is at liberty when he swears off his wife for four months or less once four months pass and she brings him to account nothing is lawful for him but to return to her in the proper manner or to divorce her the return is intercourse if he is unable to do so through illness a chronic complaint or travel and he affirms his return with his tongue and calls witnesses that suffices and is permissible when he is able he returns to her in the proper manner', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 91, NULL, 'From Ali: "When the one bound by al-Ila is halted and resolves upon divorce, let him leave her until she menstruates and purifies herself. When she is pure, he divorces her and calls two upright witnesses. He is then the more entitled to take her back so long as three menstrual cycles have not elapsed. Once they have elapsed, he is but one suitor among others, and she is in command of herself. If he wishes and she wishes, he may marry her afresh, and she remains with him according to what is left of her divorce count."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'from ali when the one bound by al ila is halted and resolves upon divorce let him leave her until she menstruates and purifies herself when she is pure he divorces her and calls two upright witnesses he is then the more entitled to take her back so long as three menstrual cycles have not elapsed once they have elapsed he is but one suitor among others and she is in command of herself if he wishes and she wishes he may marry her afresh and she remains with him according to what is left of her divorce count', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 92, NULL, 'A man asked Abu Jafar, saying, "My wife bore a boy, and I feared that if I were intimate with her she would conceive and the child would perish, so I swore by Allah that I would not approach her until she had weaned him." Ali said, "There is no al-Ila upon you in seeking the child''s welfare."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'a man asked abu jafar saying my wife bore a boy and i feared that if i were intimate with her she would conceive and the child would perish so i swore by allah that i would not approach her until she had weaned him ali said there is no al ila upon you in seeking the childs welfare', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 93, NULL, 'By this he meant that whoever swears to his wife that he will not approach her for a month, or for less than four months, that is not al-Ila. Equally, if he approaches her before four months have passed, no al-Ila applies, for al-Ila exists only by oath — the oath is its binding force. Even if he persists until four months have elapsed, it still does not constitute al-Ila, for there is no al-Ila without the swearing, and al-Ila is the swearing itself.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'by this he meant that whoever swears to his wife that he will not approach her for a month or for less than four months that is not al ila equally if he approaches her before four months have passed no al ila applies for al ila exists only by oath the oath is its binding force even if he persists until four months have elapsed it still does not constitute al ila for there is no al ila without the swearing and al ila is the swearing itself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 94, NULL, 'From Jafar ibn Muhammad: "If the one bound by al-Ila says, I have already had intercourse with her, his word is accepted along with his oath" — meaning, if he had been intimate with her prior to that. When a man has been intimate with his wife and later becomes incapable of intimacy, no separation is made between them. But if he has not been intimate with her, or is incapable at the outset, he is given a term, after which separation may be made between them. He said: "And if he swears off her for more than four months, he is one bound by al-Ila."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'from jafar ibn muhammad if the one bound by al ila says i have already had intercourse with her his word is accepted along with his oath meaning if he had been intimate with her prior to that when a man has been intimate with his wife and later becomes incapable of intimacy no separation is made between them but if he has not been intimate with her or is incapable at the outset he is given a term after which separation may be made between them he said and if he swears off her for more than four months he is one bound by al ila', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 95, NULL, 'Al-Dhihar', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'al dhihar', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 96, NULL, 'Allah, exalted be His remembrance, said:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'allah exalted be his remembrance said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 97, NULL, '﴿الَّذِينَ يُظَاهِرُونَ مِنكُم مِّن نِّسَائِهِم﴾', '', '﴿الَّذِينَ يُظَاهِرُونَ مِنكُم مِّن نِّسَائِهِم﴾', NULL, 58, 2, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'الذين يظاهرون منكم من نسايهم', 'الذين يظاهرون منكم من نسايهم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 98, NULL, '"Those among you who pronounce dhihar against their wives" — to the end of the passage on al-Dhihar.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'those among you who pronounce dhihar against their wives to the end of the passage on al dhihar', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 99, NULL, 'A narration transmitted from the Imams of the household of the Messenger of Allah — may Allah''s blessings be upon him and his family — relates that a man came to him and said, "O Messenger of Allah, I have pronounced dhihar against my wife." He said, "Go and free a slave." The man said, "I have none." He said, "Then fast two consecutive months." The man said, "I am not able." He said, "Then go and feed sixty poor persons."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'a narration transmitted from the imams of the household of the messenger of allah may allahs blessings be upon him and his family relates that a man came to him and said o messenger of allah i have pronounced dhihar against my wife he said go and free a slave the man said i have none he said then fast two consecutive months the man said i am not able he said then go and feed sixty poor persons', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 100, NULL, 'Ali said: "When the one who has pronounced dhihar possesses the means to free a slave, he frees one, and fasting does not suffice for him. If he is able to fast, he fasts, and feeding does not suffice for him. If he finds nothing to free and is unable to fast, he feeds."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'ali said when the one who has pronounced dhihar possesses the means to free a slave he frees one and fasting does not suffice for him if he is able to fast he fasts and feeding does not suffice for him if he finds nothing to free and is unable to fast he feeds', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 101, NULL, 'Abu Abdillah Jafar ibn Muhammad said: "Everything in the Quran that uses أو, or leaves its doer free to choose whichever of them he wishes — as in the saying of Him who is the Speaker:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'abu abdillah jafar ibn muhammad said everything in the quran that uses او or leaves its doer free to choose whichever of them he wishes as in the saying of him who is the speaker', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 102, NULL, '﴿لَا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ الْأَيْمَانَ ۖ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ﴾', '', '﴿لَا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ الْأَيْمَانَ ۖ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ﴾', NULL, 5, 89, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'لا يواخذكم الله باللغو في ايمانكم ولكن يواخذكم بما عقدتم الايمان فكفارته اطعام عشره مساكين من اوسط ما تطعمون اهليكم او كسوتهم او تحرير رقبه', 'لا يواخذكم الله باللغو في ايمانكم ولكن يواخذكم بما عقدتم الايمان فكفارته اطعام عشره مساكين من اوسط ما تطعمون اهليكم او كسوتهم او تحرير رقبه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 103, NULL, 'The one performing expiation is free to choose whichever of those options he wishes. Where the divine words specify if he does not find such-and-such or if he is unable to do such-and-such, the latter option is not lawful until he has genuinely failed to find the former or is genuinely unable to perform it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the one performing expiation is free to choose whichever of those options he wishes where the divine words specify if he does not find such and such or if he is unable to do such and such the latter option is not lawful until he has genuinely failed to find the former or is genuinely unable to perform it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 104, NULL, 'The Master said: "Al-Dhihar takes effect only when the wife is in a state of purity untouched by intercourse, and in the presence of two witnesses — as is the case with divorce. If either condition is absent, it counts for nothing. Al-Dhihar does not occur within an oath, just as divorce does not. It occurs only when a man intends it and says to his wife, while she is in a state of purity and before two upright witnesses, You are to me as my mother''s back — without adding any conditional such as if you do such-and-such.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the master said al dhihar takes effect only when the wife is in a state of purity untouched by intercourse and in the presence of two witnesses as is the case with divorce if either condition is absent it counts for nothing al dhihar does not occur within an oath just as divorce does not it occurs only when a man intends it and says to his wife while she is in a state of purity and before two upright witnesses you are to me as my mothers back without adding any conditional such as if you do such and such', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 105, NULL, '"Al-Dhihar cannot be pronounced more than once within a single period of purity, in a single sitting; if that happens, only one expiation is due. If he pronounces it on separate, duly completed occasions, each instance carries its own expiation. If he pronounces dhihar against four wives, each wife incurs a separate expiation. Al-Dhihar is binding with respect to every woman within the forbidden degrees, as when he says, You are to me as my mother''s back."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'al dhihar cannot be pronounced more than once within a single period of purity in a single sitting if that happens only one expiation is due if he pronounces it on separate duly completed occasions each instance carries its own expiation if he pronounces dhihar against four wives each wife incurs a separate expiation al dhihar is binding with respect to every woman within the forbidden degrees as when he says you are to me as my mothers back', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 106, NULL, 'When a man has pronounced zihar (ظِهَار) against his wife and seeks to discharge its consequence, the order of expiation is fixed. If he owns a slave he is able to free, he must free that slave; fasting is not open to him while emancipation remains within his power. If he is capable of fasting, he fasts; feeding the poor is not open to him while fasting remains within his power. Only when he can neither free a slave nor fast does he feed the poor.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'when a man has pronounced zihar ظهار against his wife and seeks to discharge its consequence the order of expiation is fixed if he owns a slave he is able to free he must free that slave fasting is not open to him while emancipation remains within his power if he is capable of fasting he fasts feeding the poor is not open to him while fasting remains within his power only when he can neither free a slave nor fast does he feed the poor', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 107, NULL, 'Abu Abdullah Jafar ibn Muhammad said: "Everything in the Quran in which there is an or — offering a choice — its owner may do whichever of them he wishes." This is like the saying of Allah, exalted be His mention:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'abu abdullah jafar ibn muhammad said everything in the quran in which there is an or offering a choice its owner may do whichever of them he wishes this is like the saying of allah exalted be his mention', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 108, NULL, '﴿ لَا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ الْأَيْمَانَ ۖ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ ﴾', '', '﴿ لَا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ الْأَيْمَانَ ۖ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ ﴾', NULL, 5, 89, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'لا يواخذكم الله باللغو في ايمانكم ولكن يواخذكم بما عقدتم الايمان فكفارته اطعام عشره مساكين من اوسط ما تطعمون اهليكم او كسوتهم او تحرير رقبه', 'لا يواخذكم الله باللغو في ايمانكم ولكن يواخذكم بما عقدتم الايمان فكفارته اطعام عشره مساكين من اوسط ما تطعمون اهليكم او كسوتهم او تحرير رقبه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 109, NULL, 'In this case, the one expiating may choose whichever of the three options he wishes. Where the wording runs "and whoever does not find such-and-such, or is unable," however, the second option is not available to him until he has first failed to find, or been unable to perform, the option that precedes it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'in this case the one expiating may choose whichever of the three options he wishes where the wording runs and whoever does not find such and such or is unable however the second option is not available to him until he has first failed to find or been unable to perform the option that precedes it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 110, NULL, 'The Master said: "Zihar is valid only in a state of purity in which he has not touched her, and with the testimony of two witnesses, just as is required for divorce. If it is otherwise, it counts for nothing. There is no zihar within an oath, just as there is no divorce within one."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the master said zihar is valid only in a state of purity in which he has not touched her and with the testimony of two witnesses just as is required for divorce if it is otherwise it counts for nothing there is no zihar within an oath just as there is no divorce within one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 111, NULL, 'Zihar comes about only when the man intends it and speaks to her while she is in a state of purity and in the presence of two upright witnesses, saying, "You are to me as my mother''s back," أنتِ عليَّ كظهر أمي, without adding any conditional such as "if I do such-and-such."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'zihar comes about only when the man intends it and speaks to her while she is in a state of purity and in the presence of two upright witnesses saying you are to me as my mothers back انت علي كظهر امي without adding any conditional such as if i do such and such', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 112, NULL, 'Zihar does not occur more than once in a single sitting within one period of purity, and a single expiation suffices even if the man repeats the pronouncement several times within that sitting. If he pronounces it on separate occasions, however, an expiation falls due for each. Likewise, if he pronounces it against four wives, an expiation is owed for each one of them.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'zihar does not occur more than once in a single sitting within one period of purity and a single expiation suffices even if the man repeats the pronouncement several times within that sitting if he pronounces it on separate occasions however an expiation falls due for each likewise if he pronounces it against four wives an expiation is owed for each one of them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 113, NULL, 'Zihar binds a man with respect to every woman who is permanently unmarriageable to him — as when he says, "You are to me as my mother''s back," or names his sister, his paternal aunt, his maternal aunt, or any other of his unmarriageable kin.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'zihar binds a man with respect to every woman who is permanently unmarriageable to him as when he says you are to me as my mothers back or names his sister his paternal aunt his maternal aunt or any other of his unmarriageable kin', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 114, NULL, 'The zihar remains binding until he has intercourse with her, and zihar does not apply between a man and his slave-woman. If he wishes to approach his wife after pronouncing it, he must first make expiation and may not draw near her until he has done so. Should he approach her before that, he has acted wrongly; he then expiates afterward, seeks forgiveness from Allah, and turns to Him in repentance. If he divorces her after pronouncing zihar but before approaching her, no expiation is required of him. If he takes her back after that divorce, he may not approach her until he has performed the expiation for zihar. If, however, he leaves her until the separation is complete and then marries her anew, no zihar attaches to the new marriage, for she had already become fully separated from him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the zihar remains binding until he has intercourse with her and zihar does not apply between a man and his slave woman if he wishes to approach his wife after pronouncing it he must first make expiation and may not draw near her until he has done so should he approach her before that he has acted wrongly he then expiates afterward seeks forgiveness from allah and turns to him in repentance if he divorces her after pronouncing zihar but before approaching her no expiation is required of him if he takes her back after that divorce he may not approach her until he has performed the expiation for zihar if however he leaves her until the separation is complete and then marries her anew no zihar attaches to the new marriage for she had already become fully separated from him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 115, NULL, 'A slave incurs zihar just as a free man does when he pronounces it against his wife, yet he owes no freeing of a slave and no feeding of the poor unless his master grants him the means to do so. If the master does not, the slave fasts one month — half of what the free man fasts. The free man''s fast for zihar is two consecutive months, as Allah, exalted be His mention, has commanded. If the slave fasts a month or less and then breaks his fast, he must begin again from the start, and what he has already fasted does not count. If, however, he fasts a full month and then breaks off a day or two — or more — into the second month before completing it, he makes up only what remains, because he has already joined the two months in succession.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'a slave incurs zihar just as a free man does when he pronounces it against his wife yet he owes no freeing of a slave and no feeding of the poor unless his master grants him the means to do so if the master does not the slave fasts one month half of what the free man fasts the free mans fast for zihar is two consecutive months as allah exalted be his mention has commanded if the slave fasts a month or less and then breaks his fast he must begin again from the start and what he has already fasted does not count if however he fasts a full month and then breaks off a day or two or more into the second month before completing it he makes up only what remains because he has already joined the two months in succession', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 116, NULL, 'As for the freeing of a slave as expiation for zihar, any slave suffices — young or old, Muslim or non-Muslim, male or female — because Allah, mighty and majestic, said ﴿ فَتَحْرِيرُ رَقَبَةٍ ﴾, "then the freeing of a slave," and placed no condition upon it. It is not permitted in zihar to free:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'as for the freeing of a slave as expiation for zihar any slave suffices young or old muslim or non muslim male or female because allah mighty and majestic said فتحرير رقبه then the freeing of a slave and placed no condition upon it it is not permitted in zihar to free', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 117, NULL, 'an insane slave one with a corrupting defect a mudabbar, since his manumission may be revoked a mukatab who is still paying off his installments', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'an insane slave one with a corrupting defect a mudabbar since his manumission may be revoked a mukatab who is still paying off his installments', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 118, NULL, 'According to a report from Ali, if the one who has pronounced zihar cannot find a slave to free and so begins fasting, but then acquires the means to free a slave before his fast is complete, he frees the slave and the fast is thereby annulled. If, however, he completes the fast and only afterward finds himself able to free a slave, nothing further is required of him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'according to a report from ali if the one who has pronounced zihar cannot find a slave to free and so begins fasting but then acquires the means to free a slave before his fast is complete he frees the slave and the fast is thereby annulled if however he completes the fast and only afterward finds himself able to free a slave nothing further is required of him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 119, NULL, 'A further report from Ali states that the expiation by feeding consists of providing sixty poor persons each with half a sa. Jafar ibn Muhammad held that feeding each poor person a mudd is sufficient. What Ali said is the obligation upon one who is able, while what Jafar ibn Muhammad said applies to one who is unable — his ruling entering by way of the latitude that the law extends in cases of hardship. What Ali said is the commanded measure, yet whoever feeds each poor person a mudd has discharged the duty, as Jafar ibn Muhammad affirmed.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'a further report from ali states that the expiation by feeding consists of providing sixty poor persons each with half a sa jafar ibn muhammad held that feeding each poor person a mudd is sufficient what ali said is the obligation upon one who is able while what jafar ibn muhammad said applies to one who is unable his ruling entering by way of the latitude that the law extends in cases of hardship what ali said is the commanded measure yet whoever feeds each poor person a mudd has discharged the duty as jafar ibn muhammad affirmed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 120, NULL, 'Neither zihar nor its expiation becomes binding except where there has been intercourse with the wife — and this remains the case even if the man has not approached any of his wives. If a man approaches his wife without first having expiated, he has done wrong and committed a grave sin; he must seek the forgiveness of Allah and turn to Him in repentance.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'neither zihar nor its expiation becomes binding except where there has been intercourse with the wife and this remains the case even if the man has not approached any of his wives if a man approaches his wife without first having expiated he has done wrong and committed a grave sin he must seek the forgiveness of allah and turn to him in repentance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 121, NULL, 'Mention of Lian', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'mention of lian', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 122, NULL, 'Allah, exalted be His mention, said:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'allah exalted be his mention said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 123, NULL, '﴿ وَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ وَلَمْ يَكُن لَّهُمْ شُهَدَاءُ إِلَّا أَنفُسُهُمْ فَشَهَادَةُ أَحَدِهِمْ أَرْبَعُ شَهَادَاتٍ بِاللَّهِ ۙ إِنَّهُ لَمِنَ الصَّادِقِينَ ۝ وَالْخَامِسَةُ أَنَّ لَعْنَتَ اللَّهِ عَلَيْهِ إِن كَانَ مِنَ الْكَاذِبِينَ ۝ وَيَدْرَأُ عَنْهَا الْعَذَابَ أَن تَشْهَدَ أَرْبَعَ شَهَادَاتٍ بِاللَّهِ ۙ إِنَّهُ لَمِنَ الْكَاذِبِينَ ۝ وَالْخَامِسَةَ أَنَّ غَضَبَ اللَّهِ عَلَيْهَا إِن كَانَ مِنَ الصَّادِقِينَ ۝ وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ وَأَنَّ اللَّهَ تَوَّابٌ حَكِيمٌ ﴾', '', '﴿ وَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ وَلَمْ يَكُن لَّهُمْ شُهَدَاءُ إِلَّا أَنفُسُهُمْ فَشَهَادَةُ أَحَدِهِمْ أَرْبَعُ شَهَادَاتٍ بِاللَّهِ ۙ إِنَّهُ لَمِنَ الصَّادِقِينَ ۝ وَالْخَامِسَةُ أَنَّ لَعْنَتَ اللَّهِ عَلَيْهِ إِن كَانَ مِنَ الْكَاذِبِينَ ۝ وَيَدْرَأُ عَنْهَا الْعَذَابَ أَن تَشْهَدَ أَرْبَعَ شَهَادَاتٍ بِاللَّهِ ۙ إِنَّهُ لَمِنَ الْكَاذِبِينَ ۝ وَالْخَامِسَةَ أَنَّ غَضَبَ اللَّهِ عَلَيْهَا إِن كَانَ مِنَ الصَّادِقِينَ ۝ وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ وَأَنَّ اللَّهَ تَوَّابٌ حَكِيمٌ ﴾', NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'والذين يرمون ازواجهم ولم يكن لهم شهداء الا انفسهم فشهاده احدهم اربع شهادات بالله انه لمن الصادقين والخامسه ان لعنت الله عليه ان كان من الكاذبين ويدرا عنها العذاب ان تشهد اربع شهادات بالله انه لمن الكاذبين والخامسه ان غضب الله عليها ان كان من الصادقين ولولا فضل الله عليكم ورحمته وان الله تواب حكيم', 'والذين يرمون ازواجهم ولم يكن لهم شهداء الا انفسهم فشهاده احدهم اربع شهادات بالله انه لمن الصادقين والخامسه ان لعنت الله عليه ان كان من الكاذبين ويدرا عنها العذاب ان تشهد اربع شهادات بالله انه لمن الكاذبين والخامسه ان غضب الله عليها ان كان من الصادقين ولولا فضل الله عليكم ورحمته وان الله تواب حكيم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 124, NULL, 'These verses establish the procedure of lian — the oath of condemnation — for a husband who accuses his wife of adultery but has no witnesses to support the charge. He testifies four times, swearing by God that he speaks the truth, and a fifth time calling God''s curse upon himself if he is lying. She, in turn, may avert punishment by testifying four times that he is lying, and a fifth time calling God''s wrath upon herself if he speaks the truth. The passage closes by reminding that, were it not for God''s grace, mercy, and His willingness to accept repentance, the consequences of such accusations would be far graver still.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'these verses establish the procedure of lian the oath of condemnation for a husband who accuses his wife of adultery but has no witnesses to support the charge he testifies four times swearing by god that he speaks the truth and a fifth time calling gods curse upon himself if he is lying she in turn may avert punishment by testifying four times that he is lying and a fifth time calling gods wrath upon herself if he speaks the truth the passage closes by reminding that were it not for gods grace mercy and his willingness to accept repentance the consequences of such accusations would be far graver still', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 125, NULL, 'According to Ali, no lian arises between husband and wife unless he either claims to have witnessed the act directly — saying, "I saw a man between her legs committing adultery with her" — or disavows her child. In the account transmitted from Jafar ibn Muhammad, the procedure takes place only before a judge, and only after the husband has held firmly to his statement without retracting it and she has denied his charge. At that point the judge orders him to perform lian.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'according to ali no lian arises between husband and wife unless he either claims to have witnessed the act directly saying i saw a man between her legs committing adultery with her or disavows her child in the account transmitted from jafar ibn muhammad the procedure takes place only before a judge and only after the husband has held firmly to his statement without retracting it and she has denied his charge at that point the judge orders him to perform lian', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 126, NULL, 'The husband''s lian runs as follows: he declares, "I bear witness by Allah that I have indeed seen a man committing adultery with her," or, "I bear witness that this child is not mine." He repeats this four times, then says on the fifth, "If I am lying, then the curse of Allah be upon me." The judge says, "Amin."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the husbands lian runs as follows he declares i bear witness by allah that i have indeed seen a man committing adultery with her or i bear witness that this child is not mine he repeats this four times then says on the fifth if i am lying then the curse of allah be upon me the judge says amin', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 127, NULL, 'The judge then turns to the woman. If she affirms what her husband said, she is stoned. If she denies it, she declares, "I bear witness by Allah that he is among the liars in what he has accused me of," repeating this four times, then says on the fifth, "If he is truthful, then the wrath of Allah be upon me." The judge again says, "Amin."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the judge then turns to the woman if she affirms what her husband said she is stoned if she denies it she declares i bear witness by allah that he is among the liars in what he has accused me of repeating this four times then says on the fifth if he is truthful then the wrath of allah be upon me the judge again says amin', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 128, NULL, 'Once this has been completed, the judge separates the two, and she is never again lawful to him. The child whose paternity was disavowed is not attributed to the one who disavowed him; he is ascribed to his mother and her maternal kin, and his inheritance passes to them. The woman''s dowry becomes the liability of the one who performed lian against her.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'once this has been completed the judge separates the two and she is never again lawful to him the child whose paternity was disavowed is not attributed to the one who disavowed him he is ascribed to his mother and her maternal kin and his inheritance passes to them the womans dowry becomes the liability of the one who performed lian against her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 129, NULL, 'Lian may only be performed before a judge. It is not valid between husband and wife unless he has consummated the marriage, even if he accuses her of adultery or disavows the child she bore. If he refuses to perform lian and she brings the matter before the authority, he receives the hadd lashing for slander, unless he can produce proof. If he does produce proof and four upright men testify to her adultery, she is stoned and lian is no longer applicable. Likewise, if he disavows the child she bore and refuses to perform lian, he receives the hadd lashing once she brings the matter forward, and she remains his wife unless he divorces her.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'lian may only be performed before a judge it is not valid between husband and wife unless he has consummated the marriage even if he accuses her of adultery or disavows the child she bore if he refuses to perform lian and she brings the matter before the authority he receives the hadd lashing for slander unless he can produce proof if he does produce proof and four upright men testify to her adultery she is stoned and lian is no longer applicable likewise if he disavows the child she bore and refuses to perform lian he receives the hadd lashing once she brings the matter forward and she remains his wife unless he divorces her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 130, NULL, 'If he performs lian and then retracts his accusation, declaring himself a liar, he receives the hadd lashing. She does not return to him, yet the child inherits from him, though he inherits nothing from the child.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'if he performs lian and then retracts his accusation declaring himself a liar he receives the hadd lashing she does not return to him yet the child inherits from him though he inherits nothing from the child', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 131, NULL, 'Lian is valid in the following pairings:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'lian is valid in the following pairings', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 132, NULL, 'A Muslim man and a dhimmi woman A free man and a slave-woman Two slaves Any married couple, provided both are of age', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'a muslim man and a dhimmi woman a free man and a slave woman two slaves any married couple provided both are of age', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 133, NULL, 'Lian is not valid between two minors. Once they reach maturity, the husband may not perform lian against his wife for an accusation he made while both were still minors. Nor is it valid between a mute husband and a mute wife, since lian is enacted by spoken words alone. If a man accuses a mute wife, the two are separated and no lian is performed. A husband may not perform lian against a pregnant wife; he waits until she has given birth, and only then proceeds.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'lian is not valid between two minors once they reach maturity the husband may not perform lian against his wife for an accusation he made while both were still minors nor is it valid between a mute husband and a mute wife since lian is enacted by spoken words alone if a man accuses a mute wife the two are separated and no lian is performed a husband may not perform lian against a pregnant wife he waits until she has given birth and only then proceeds', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 134, NULL, 'If a man impugns his wife only through insinuation, lian does not apply. If he says to her, "I did not find you a virgin," nothing is required of him and no lian is performed, because virginity may be lost through means other than intercourse. If he accuses her before the marriage has been consummated, he receives the hadd lashing and she remains his wife.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'if a man impugns his wife only through insinuation lian does not apply if he says to her i did not find you a virgin nothing is required of him and no lian is performed because virginity may be lost through means other than intercourse if he accuses her before the marriage has been consummated he receives the hadd lashing and she remains his wife', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 135, NULL, 'The two parties perform lian standing, not seated.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the two parties perform lian standing not seated', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 136, NULL, 'If a man accuses his wife and then divorces her, and she raises the matter while still within her iddah, he performs lian. If she raises it after the iddah has elapsed, he receives the hadd lashing unless he produces proof of his accusation.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'if a man accuses his wife and then divorces her and she raises the matter while still within her iddah he performs lian if she raises it after the iddah has elapsed he receives the hadd lashing unless he produces proof of his accusation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 137, NULL, 'If he accuses her and she dies before lian is performed, and one of her guardians steps forward to pursue lian against the husband on her behalf, the husband takes no inheritance from her. If no guardian steps forward, he inherits from her.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'if he accuses her and she dies before lian is performed and one of her guardians steps forward to pursue lian against the husband on her behalf the husband takes no inheritance from her if no guardian steps forward he inherits from her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 138, NULL, 'If a man divorces his wife before consummation and she then claims to be pregnant by him while he denies it, the following applies: if she establishes that he had drawn a veil over her in seclusion, he performs lian; otherwise, he swears that he never drew a veil over her nor approached her, and her claim is set aside. All of this is the teaching of the Ahl al-Bayt (عَلَيْهِمُ السَّلَامُ).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'if a man divorces his wife before consummation and she then claims to be pregnant by him while he denies it the following applies if she establishes that he had drawn a veil over her in seclusion he performs lian otherwise he swears that he never drew a veil over her nor approached her and her claim is set aside all of this is the teaching of the ahl al bayt عليهم السلام', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 139, NULL, '**Mention of the Iddah, the Maintenance Within It, and the Mourning**', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'mention of the iddah the maintenance within it and the mourning', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 140, NULL, 'Allah, mighty and majestic, said:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'allah mighty and majestic said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 141, NULL, '﴿ وَالَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَاجًا يَتَرَبَّصْنَ بِأَنفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا ﴾', '', '﴿ وَالَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَاجًا يَتَرَبَّصْنَ بِأَنفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا ﴾', NULL, 2, 234, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'والذين يتوفون منكم ويذرون ازواجا يتربصن بانفسهن اربعه اشهر وعشرا', 'والذين يتوفون منكم ويذرون ازواجا يتربصن بانفسهن اربعه اشهر وعشرا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 142, NULL, '"And those of you who die and leave wives behind, they shall wait by themselves four months and ten days" (al-Baqarah: 234). And He said:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'and those of you who die and leave wives behind they shall wait by themselves four months and ten days al baqarah 234 and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 143, NULL, '﴿ وَالْمُطَلَّقَاتُ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ ثَلَاثَةَ قُرُوءٍ ﴾', '', '﴿ وَالْمُطَلَّقَاتُ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ ثَلَاثَةَ قُرُوءٍ ﴾', NULL, 2, 228, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'والمطلقات يتربصن بانفسهن ثلاثه قروء', 'والمطلقات يتربصن بانفسهن ثلاثه قروء');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 144, NULL, '"And divorced women shall wait by themselves three menstrual cycles" (al-Baqarah: 228). And He said:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'and divorced women shall wait by themselves three menstrual cycles al baqarah 228 and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 145, NULL, '﴿ وَأُولَاتُ الْأَحْمَالِ أَجَلُهُنَّ أَن يَضَعْنَ حَمْلَهُنَّ ﴾', '', '﴿ وَأُولَاتُ الْأَحْمَالِ أَجَلُهُنَّ أَن يَضَعْنَ حَمْلَهُنَّ ﴾', NULL, 65, 4, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'واولات الاحمال اجلهن ان يضعن حملهن', 'واولات الاحمال اجلهن ان يضعن حملهن');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 146, NULL, '"And as for those who are pregnant, their term is that they deliver their burden" (al-Talaq: 4). And He said:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'and as for those who are pregnant their term is that they deliver their burden al talaq 4 and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 147, NULL, '﴿ ثُمَّ طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا ﴾', '', '﴿ ثُمَّ طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا ﴾', NULL, 33, 49, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'ثم طلقتموهن من قبل ان تمسوهن فما لكم عليهن من عده تعتدونها', 'ثم طلقتموهن من قبل ان تمسوهن فما لكم عليهن من عده تعتدونها');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 148, NULL, '"Then you divorce them before you have touched them, you have no waiting period over them to count" (al-Ahzab: 49).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'then you divorce them before you have touched them you have no waiting period over them to count al ahzab 49', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 149, NULL, 'When a man dies leaving a wife, she observes a waiting period of four months and ten nights — whether he had consummated the marriage or not, and whether she is an adult or a child — because Allah, mighty and majestic, said: ﴿ وَالَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَاجًا يَتَرَبَّصْنَ بِأَنفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا ﴾, drawing no distinction between a wife whose marriage was consummated and one whose was not, nor between a child and an adult. She may observe this waiting period wherever she wishes, whether in her late husband''s house or elsewhere.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'when a man dies leaving a wife she observes a waiting period of four months and ten nights whether he had consummated the marriage or not and whether she is an adult or a child because allah mighty and majestic said والذين يتوفون منكم ويذرون ازواجا يتربصن بانفسهن اربعه اشهر وعشرا drawing no distinction between a wife whose marriage was consummated and one whose was not nor between a child and an adult she may observe this waiting period wherever she wishes whether in her late husbands house or elsewhere', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 150, NULL, 'If a man divorces his wife while she is menstruating, her iddah is three menstrual cycles, and she observes it only in her husband''s house. A pregnant woman whose husband dies observes the longer of the two terms. If she gives birth before the four months and ten nights have passed, she completes the four months and ten; if the four months and ten pass and she has not yet given birth, she waits until she gives birth, because Allah, mighty and majestic, said: ﴿ وَأُولَاتُ الْأَحْمَالِ أَجَلُهُنَّ أَن يَضَعْنَ حَمْلَهُنَّ ﴾, and said: ﴿ وَالَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَاجًا ﴾, making no exception in either verse. If he divorces her while she is pregnant, her term ends when she delivers her burden; whenever she delivers, the separation from him is complete. Everything she brings forth that is recognizably a child effects that separation. If her womb holds two children or more, however, she is not separated until she delivers the last of them.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'if a man divorces his wife while she is menstruating her iddah is three menstrual cycles and she observes it only in her husbands house a pregnant woman whose husband dies observes the longer of the two terms if she gives birth before the four months and ten nights have passed she completes the four months and ten if the four months and ten pass and she has not yet given birth she waits until she gives birth because allah mighty and majestic said واولات الاحمال اجلهن ان يضعن حملهن and said والذين يتوفون منكم ويذرون ازواجا making no exception in either verse if he divorces her while she is pregnant her term ends when she delivers her burden whenever she delivers the separation from him is complete everything she brings forth that is recognizably a child effects that separation if her womb holds two children or more however she is not separated until she delivers the last of them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 151, NULL, 'If a man divorces his wife with one or two revocable pronouncements and then dies while she remains in that state, she observes the waiting period of death, for she had not yet become separate from him — he died while she was still within his bond. Allah, mighty and majestic, says: ﴿ وَالَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَاجًا يَتَرَبَّصْنَ بِأَنفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا ﴾.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'if a man divorces his wife with one or two revocable pronouncements and then dies while she remains in that state she observes the waiting period of death for she had not yet become separate from him he died while she was still within his bond allah mighty and majestic says والذين يتوفون منكم ويذرون ازواجا يتربصن بانفسهن اربعه اشهر وعشرا', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 152, NULL, 'If a man divorces his wife while he is absent, her waiting period is reckoned from the day he pronounced the divorce, even if the news reaches her only some time afterward; once the period has run its course, she becomes lawful for other husbands. If, however, he dies while absent, she must begin her waiting period from the moment the news of his death reaches her, and whatever time elapsed before that is not counted. The reason lies in a distinction between the two cases: mourning is obligatory upon a widow, whereas no mourning falls upon a divorced woman.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'if a man divorces his wife while he is absent her waiting period is reckoned from the day he pronounced the divorce even if the news reaches her only some time afterward once the period has run its course she becomes lawful for other husbands if however he dies while absent she must begin her waiting period from the moment the news of his death reaches her and whatever time elapsed before that is not counted the reason lies in a distinction between the two cases mourning is obligatory upon a widow whereas no mourning falls upon a divorced woman', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 153, NULL, 'A woman divorced before consummation has no waiting period and may remarry whenever she wishes. A divorced woman suffering from istihada counts her waiting period by the onset of menstruation. The distinction between the two kinds of blood has already been set out: menstrual blood is thick, dark, foul-smelling, and warm, while the blood of istihada is thin and clear, neither warm nor foul. When she recognizes the blood of istihada, she reckons her waiting period accordingly. If she does not know how to tell one from the other, she counts by months instead. The same applies to a woman who is divorced and menstruates once or twice before her menstruation stops: she begins her waiting period again from the beginning, counting by months, and the menstrual cycles already passed are not carried forward. God, mighty and majestic, has imposed three complete cycles upon the woman who menstruates and three months upon the woman who has despaired of menstruation. Because this woman did not complete three cycles before her menstruation ceased, she is required to observe a waiting period of three months.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'a woman divorced before consummation has no waiting period and may remarry whenever she wishes a divorced woman suffering from istihada counts her waiting period by the onset of menstruation the distinction between the two kinds of blood has already been set out menstrual blood is thick dark foul smelling and warm while the blood of istihada is thin and clear neither warm nor foul when she recognizes the blood of istihada she reckons her waiting period accordingly if she does not know how to tell one from the other she counts by months instead the same applies to a woman who is divorced and menstruates once or twice before her menstruation stops she begins her waiting period again from the beginning counting by months and the menstrual cycles already passed are not carried forward god mighty and majestic has imposed three complete cycles upon the woman who menstruates and three months upon the woman who has despaired of menstruation because this woman did not complete three cycles before her menstruation ceased she is required to observe a waiting period of three months', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 154, NULL, 'Beyond the reckoning of the waiting period itself lies the question of what a woman is owed once the marriage has come apart. The law weighs carefully the different ways in which a marriage may end:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'beyond the reckoning of the waiting period itself lies the question of what a woman is owed once the marriage has come apart the law weighs carefully the different ways in which a marriage may end', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 155, NULL, 'A divorced pregnant woman is entitled to both maintenance and accommodation. A widowed pregnant woman whose husband has died has no entitlement to maintenance. A woman divorced revocably, while passing her waiting period, is entitled to maintenance and accommodation until that period is complete. A woman divorced irrevocably has neither maintenance nor accommodation.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'a divorced pregnant woman is entitled to both maintenance and accommodation a widowed pregnant woman whose husband has died has no entitlement to maintenance a woman divorced revocably while passing her waiting period is entitled to maintenance and accommodation until that period is complete a woman divorced irrevocably has neither maintenance nor accommodation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 156, NULL, 'Mourning belongs to the widow whose husband has died. It is not required of the divorced woman, nor of the woman parted from her husband by khul, nor of the woman parted by mubarah, nor of the woman parted by lian. Mourning means that the widow, throughout her waiting period, does not comb her hair or dye it, does not perfume herself or apply kohl, does not adorn herself or wear a dyed garment — unless that garment is black. She does not leave her house during the day, nor does she pass the night away from it. She may, if she wishes, go out in the final part of the night, provided she returns before evening. This is the essence of mourning.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'mourning belongs to the widow whose husband has died it is not required of the divorced woman nor of the woman parted from her husband by khul nor of the woman parted by mubarah nor of the woman parted by lian mourning means that the widow throughout her waiting period does not comb her hair or dye it does not perfume herself or apply kohl does not adorn herself or wear a dyed garment unless that garment is black she does not leave her house during the day nor does she pass the night away from it she may if she wishes go out in the final part of the night provided she returns before evening this is the essence of mourning', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 158, NULL, 'Allah, mighty and majestic, said:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'allah mighty and majestic said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 159, NULL, 'Al-Baqarah: 236لَا جُنَاحَ عَلَيْكُمْ إِنْ طَلَّقْتُمُ النِّسَاءَ مَا لَمْ تَمَسُّوهُنَّ أَوْ تَفْرِضُوا لَهُنَّ فَرِيضَةً ۚ وَمَتِّعُوهُنَّ عَلَى الْمُوسِعِ قَدَرُهُ وَعَلَى الْمُقْتِرِ قَدَرُهُ مَتَاعًا بِالْمَعْرُوفِ ۖ حَقًّا عَلَى الْمُحْسِنِينَ"There is no blame upon you if you divorce women whom you have not touched, or for whom you have not specified an obligation.', '', 'لَا جُنَاحَ عَلَيْكُمْ إِنْ طَلَّقْتُمُ النِّسَاءَ مَا لَمْ تَمَسُّوهُنَّ أَوْ تَفْرِضُوا لَهُنَّ فَرِيضَةً ۚ وَمَتِّعُوهُنَّ عَلَى الْمُوسِعِ قَدَرُهُ وَعَلَى الْمُقْتِرِ قَدَرُهُ مَتَاعًا بِالْمَعْرُوفِ ۖ حَقًّا عَلَى الْمُحْسِنِينَ', 'Al-Baqarah: 236', 2, 236, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'al baqarah 236لا جناح عليكم ان طلقتم النساء ما لم تمسوهن او تفرضوا لهن فريضه ومتعوهن علي الموسع قدره وعلي المقتر قدره متاعا بالمعروف حقا علي المحسنين there is no blame upon you if you divorce women whom you have not touched or for whom you have not specified an obligation', 'لا جناح عليكم ان طلقتم النساء ما لم تمسوهن او تفرضوا لهن فريضه ومتعوهن علي الموسع قدره وعلي المقتر قدره متاعا بالمعروف حقا علي المحسنين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 160, NULL, 'The provision is therefore obligatory. He also said:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the provision is therefore obligatory he also said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 161, NULL, 'Al-Baqarah: 241وَلِلْمُطَلَّقَاتِ مَتَاعٌ بِالْمَعْرُوفِ ۖ حَقًّا عَلَى الْمُتَّقِينَ"And for divorced women there is a provision in kindness, a duty upon the God-fearing." (Al-Baqarah 241)', '', NULL, 'Al-Baqarah: 241', NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'al baqarah 241وللمطلقات متاع بالمعروف حقا علي المتقين and for divorced women there is a provision in kindness a duty upon the god fearing al baqarah 241', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 162, NULL, 'Al-Baqarah: 236لَّا جُنَاحَ عَلَيْكُمْ إِن طَلَّقْتُمُ ٱلنِّسَآءَ مَا لَمْ تَمَسُّوهُنَّ أَوْ تَفْرِضُوا۟ لَهُنَّ فَرِيضَةًۭ', '', 'لَّا جُنَاحَ عَلَيْكُمْ إِن طَلَّقْتُمُ ٱلنِّسَآءَ مَا لَمْ تَمَسُّوهُنَّ أَوْ تَفْرِضُوا۟ لَهُنَّ فَرِيضَةًۭ', 'Al-Baqarah: 236', 2, 236, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'al baqarah 236لا جناح عليكم ان طلقتم النساء ما لم تمسوهن او تفرضوا لهن فريضه', 'لا جناح عليكم ان طلقتم النساء ما لم تمسوهن او تفرضوا لهن فريضه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 163, NULL, 'The provision of muta is owed to the woman divorced according to the Sunnah and to the woman passing her iddah, whether or not the marriage was consummated. No muta is owed to the woman separated by khul, nor to the woman separated by mubarah. No fixed amount is prescribed. The obligation falls upon the man according to his means, as Allah, mighty and majestic, said: "upon the wealthy according to his means and upon the straitened according to his means." Whatever the divorcing husband provides fulfills the obligation. When a man has means, it is recommended that he be generous in what he provides — whether dinars or dirhams, a slave or a slave-girl, goods or food — all of which has been narrated from the Imams (عَلَيْهِمُ السَّلَامُ). The provision is not given until after the iddah has ended and the separation has become complete. For as long as he still holds hope of her return, and she of his, the provision is not yet given.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'the provision of muta is owed to the woman divorced according to the sunnah and to the woman passing her iddah whether or not the marriage was consummated no muta is owed to the woman separated by khul nor to the woman separated by mubarah no fixed amount is prescribed the obligation falls upon the man according to his means as allah mighty and majestic said upon the wealthy according to his means and upon the straitened according to his means whatever the divorcing husband provides fulfills the obligation when a man has means it is recommended that he be generous in what he provides whether dinars or dirhams a slave or a slave girl goods or food all of which has been narrated from the imams عليهم السلام the provision is not given until after the iddah has ended and the separation has become complete for as long as he still holds hope of her return and she of his the provision is not yet given', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 164, NULL, 'If a man divorces his wife — whether by the iddah divorce or the Sunnah divorce, with three pronouncements — she does not become lawful to him again, as Allah, mighty and majestic, said, except after another husband has married her and consummated the marriage with her.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'if a man divorces his wife whether by the iddah divorce or the sunnah divorce with three pronouncements she does not become lawful to him again as allah mighty and majestic said except after another husband has married her and consummated the marriage with her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 165, NULL, 'That second husband may then divorce her, or he may die. Once her waiting period from the second husband has expired, the first husband may marry her again if both parties wish it — a fresh and renewed marriage — and she stands before him with the full count of divorce beginning anew. If he divorces her three times in this new marriage, and she then marries another man, and he afterward seeks to take her back, she does not become lawful to him again on the strength of those three, no matter how many times she remarries. She becomes lawful to him only through a marriage of genuine desire — nikah ghibta — with an adult man who consummates the marriage and has intercourse with her. A castrated man does not make her lawful to him. Nor does a boy who has not yet reached puberty, unless he has intercourse with her after reaching puberty. A marriage of muta does not make her lawful to him either. It is likewise unlawful for him to collude with a man so that the man will marry her and thereby make her lawful for him, or to arrange for any other man to serve that purpose.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'that second husband may then divorce her or he may die once her waiting period from the second husband has expired the first husband may marry her again if both parties wish it a fresh and renewed marriage and she stands before him with the full count of divorce beginning anew if he divorces her three times in this new marriage and she then marries another man and he afterward seeks to take her back she does not become lawful to him again on the strength of those three no matter how many times she remarries she becomes lawful to him only through a marriage of genuine desire nikah ghibta with an adult man who consummates the marriage and has intercourse with her a castrated man does not make her lawful to him nor does a boy who has not yet reached puberty unless he has intercourse with her after reaching puberty a marriage of muta does not make her lawful to him either it is likewise unlawful for him to collude with a man so that the man will marry her and thereby make her lawful for him or to arrange for any other man to serve that purpose', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 166, NULL, 'If he divorces her once or twice, so that she becomes separated from him, and she then marries another man who either dies or divorces her, and the first husband marries her again after her waiting period from the second husband has expired, she stands with him for whatever remained of her count of divorces, up to the full three, as set out above. She does not become lawful to him except through a husband. All of this is the teaching of the Ahl al-Bayt.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'if he divorces her once or twice so that she becomes separated from him and she then marries another man who either dies or divorces her and the first husband marries her again after her waiting period from the second husband has expired she stands with him for whatever remained of her count of divorces up to the full three as set out above she does not become lawful to him except through a husband all of this is the teaching of the ahl al bayt', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 168, NULL, 'When a man divorces his wife, he may take her back so long as her waiting period has not ended. Once it has ended, he is but one suitor among suitors. If both parties are willing, he marries her in a fresh and renewed marriage, and she stands with him for whatever remains of her count of divorces. If he takes her back before her waiting period expires, that is his right whether she consents or refuses, and she stands with him for whatever remains of her count of divorces. The return must be witnessed by two just witnesses. When he takes her back before her waiting period has ended, he does so without any compensation and without a new dowry. If her waiting period has passed and both parties agree upon a return, he may not take her back except with a new dowry that he names for her.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'when a man divorces his wife he may take her back so long as her waiting period has not ended once it has ended he is but one suitor among suitors if both parties are willing he marries her in a fresh and renewed marriage and she stands with him for whatever remains of her count of divorces if he takes her back before her waiting period expires that is his right whether she consents or refuses and she stands with him for whatever remains of her count of divorces the return must be witnessed by two just witnesses when he takes her back before her waiting period has ended he does so without any compensation and without a new dowry if her waiting period has passed and both parties agree upon a return he may not take her back except with a new dowry that he names for her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 169, NULL, 'A man does not need his wife''s permission to return to her so long as he retains the right of return. If he divorces her a third time, no return is possible. A divorce pronounced by a slave against a free woman counts as three; a divorce pronounced by a free man or a slave against a slave-woman counts as two.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'a man does not need his wifes permission to return to her so long as he retains the right of return if he divorces her a third time no return is possible a divorce pronounced by a slave against a free woman counts as three a divorce pronounced by a free man or a slave against a slave woman counts as two', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 170, NULL, 'If a man divorces his wife before consummating the marriage, she receives half the dowry, as Allah said. Where he had given her an animal as her dowry and that animal bore young while in her keeping, and he then divorced her before consummation, the matter is examined:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'if a man divorces his wife before consummating the marriage she receives half the dowry as allah said where he had given her an animal as her dowry and that animal bore young while in her keeping and he then divorced her before consummation the matter is examined', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 171, NULL, 'If the animal was already pregnant at the time it was given as dowry, he takes back half of it and half of its offspring. If the pregnancy occurred while the animal was in her keeping, the offspring belong entirely to her, and she returns half of the mother-animals.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'if the animal was already pregnant at the time it was given as dowry he takes back half of it and half of its offspring if the pregnancy occurred while the animal was in her keeping the offspring belong entirely to her and she returns half of the mother animals', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 172, NULL, 'If he had given her a dowry and she afterward returned it to him as a gift or bestowed it upon him as charity, and he then divorced her before consummation, he takes back half of it from her.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'if he had given her a dowry and she afterward returned it to him as a gift or bestowed it upon him as charity and he then divorced her before consummation he takes back half of it from her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 173, NULL, 'If the dowry was her own freedom — that is, she was his slave-woman and he had made her manumission her dowry, as described earlier — and he divorced her before consummation, he takes back half of her assessed value as calculated on the day of the marriage.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'if the dowry was her own freedom that is she was his slave woman and he had made her manumission her dowry as described earlier and he divorced her before consummation he takes back half of her assessed value as calculated on the day of the marriage', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'when a marriage ends: divorce and separation', '7. When a Marriage Ends: Divorce and Separation', 174, NULL, 'If he dies without having named a dowry for her and without having consummated the marriage, she has no claim to a dowry, yet she inherits from him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 7 when a marriage ends divorce and separation', 'if he dies without having named a dowry for her and without having consummated the marriage she has no claim to a dowry yet she inherits from him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 2, NULL, 'Gifts, good works, and acts of beneficence offered for the sake of God Almighty and in pursuit of His reward carry within them virtue, righteousness, and recompense. The Messenger of God — peace be upon him and his family — said: "All of creation are the children of God, and the most beloved of creation to God Almighty is the one who benefits His children, who brings joy to a household, and who walks with a Muslim brother in his time of need." Such a person, he said, is more beloved to God Almighty than two months of itikaf in the Sacred Mosque.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'gifts good works and acts of beneficence offered for the sake of god almighty and in pursuit of his reward carry within them virtue righteousness and recompense the messenger of god peace be upon him and his family said all of creation are the children of god and the most beloved of creation to god almighty is the one who benefits his children who brings joy to a household and who walks with a muslim brother in his time of need such a person he said is more beloved to god almighty than two months of itikaf in the sacred mosque', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 3, NULL, 'Ali, prayers of God be upon him, said that the people of goodness stand in greater need of having their goodness accepted than the needy stand in need of them, because through that goodness come praise, reward, and remembrance for them from God. Whoever performs a kind act toward one of God''s creatures has in truth ennobled himself by it and adorned his own honor.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'ali prayers of god be upon him said that the people of goodness stand in greater need of having their goodness accepted than the needy stand in need of them because through that goodness come praise reward and remembrance for them from god whoever performs a kind act toward one of gods creatures has in truth ennobled himself by it and adorned his own honor', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 4, NULL, 'Abu Jafar Muhammad ibn Ali, prayers of God be upon him, said: "When God raises the believer from his grave, a beautiful figure goes forth with him. As he passes through those terrors, it says to him, Do not fear, no harm shall come to you, and it does not cease to reassure him and give him glad tidings until it brings him before God, who calls him to an easy reckoning and then commands that he be taken to Paradise. The believer says to it, Who are you, may God have mercy upon you? You promised me and were truthful to me and gave me security. It replies, I am a creation your Lord fashioned out of the joy you used to bring to the believers. Today it is I who gladden you."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'abu jafar muhammad ibn ali prayers of god be upon him said when god raises the believer from his grave a beautiful figure goes forth with him as he passes through those terrors it says to him do not fear no harm shall come to you and it does not cease to reassure him and give him glad tidings until it brings him before god who calls him to an easy reckoning and then commands that he be taken to paradise the believer says to it who are you may god have mercy upon you you promised me and were truthful to me and gave me security it replies i am a creation your lord fashioned out of the joy you used to bring to the believers today it is i who gladden you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 5, NULL, 'Jafar ibn Muhammad, prayers of God be upon him, said: "There is nothing more excellent than beneficence except its reward, and beneficence is a gift from God Almighty to His believing servant. Not everyone who loves to do good to people is opened to it; not everyone who desires it is able to do it; not everyone who is able to do it is given leave to do it. When God Almighty bestows His grace upon a servant, He gathers together for him three things:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'jafar ibn muhammad prayers of god be upon him said there is nothing more excellent than beneficence except its reward and beneficence is a gift from god almighty to his believing servant not everyone who loves to do good to people is opened to it not everyone who desires it is able to do it not everyone who is able to do it is given leave to do it when god almighty bestows his grace upon a servant he gathers together for him three things', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 6, NULL, 'the desire for beneficence, the ability to perform it, and the leave to act upon it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the desire for beneficence the ability to perform it and the leave to act upon it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 7, NULL, 'There, happiness and honor are complete — both for the one who seeks the good and for the one to whom it is directed."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'there happiness and honor are complete both for the one who seeks the good and for the one to whom it is directed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 8, NULL, 'The Master said, peace be upon him: "Beneficence is not made complete except by three qualities: making little of it, making it easy, and hastening it. When you make little of it, you have made it great in the eyes of the one to whom you do it; when you make it easy, you have rendered it complete for him; and when you hasten it, you have made it a cause of joy for him. But if you do not do these things, you have spoiled it and rendered it thankless."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the master said peace be upon him beneficence is not made complete except by three qualities making little of it making it easy and hastening it when you make little of it you have made it great in the eyes of the one to whom you do it when you make it easy you have rendered it complete for him and when you hasten it you have made it a cause of joy for him but if you do not do these things you have spoiled it and rendered it thankless', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 9, NULL, 'He said: "The best of Muslims is the one who joins, helps, and gives." And he said: "I heard my father say: the doing of good wards off the calamities of evil. Every kindness is a charity, and the people of goodness in this world are the people of goodness in the Hereafter. The first to enter Paradise are the people of goodness."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'he said the best of muslims is the one who joins helps and gives and he said i heard my father say the doing of good wards off the calamities of evil every kindness is a charity and the people of goodness in this world are the people of goodness in the hereafter the first to enter paradise are the people of goodness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 10, NULL, 'The Messenger of God and his family said: "Whoever has a kindness done to him, let him repay it; if he is unable, let him praise the one who did it; and if he does not, then he has been ungrateful for the blessing."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the messenger of god and his family said whoever has a kindness done to him let him repay it if he is unable let him praise the one who did it and if he does not then he has been ungrateful for the blessing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 11, NULL, 'The Imams of the People of the House of the Messenger of God, prayers of God be upon them, permitted a man to favor some of his children over others in wealth and gifts, if he chose to do so. A gift or a charity is valid whether or not possession has been transferred to the recipient. Whoever gives a gift for the sake of God Almighty, or to a blood relative or kinsman, has no right to take it back. If, however, he gives a gift or grant expecting compensation in return, that is disliked, and he may reclaim it if no compensation is given. Whoever gives a gift or charity to a blood relative or kinsman who then dies — so that it returns to him through inheritance — there is no harm in that.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the imams of the people of the house of the messenger of god prayers of god be upon them permitted a man to favor some of his children over others in wealth and gifts if he chose to do so a gift or a charity is valid whether or not possession has been transferred to the recipient whoever gives a gift for the sake of god almighty or to a blood relative or kinsman has no right to take it back if however he gives a gift or grant expecting compensation in return that is disliked and he may reclaim it if no compensation is given whoever gives a gift or charity to a blood relative or kinsman who then dies so that it returns to him through inheritance there is no harm in that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 12, NULL, 'The umra, the ruqba, and the sukna are among those arrangements that carry merit and reward. The umra is a grant by which a man gives another man the use of a house, an estate, or any other property for the duration of that other man''s life. The ruqba carries the same general meaning, but with one distinguishing condition: whichever of the two parties dies first, the property reverts to the original grantor or to his heirs.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the umra the ruqba and the sukna are among those arrangements that carry merit and reward the umra is a grant by which a man gives another man the use of a house an estate or any other property for the duration of that other mans life the ruqba carries the same general meaning but with one distinguishing condition whichever of the two parties dies first the property reverts to the original grantor or to his heirs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 13, NULL, 'The terms of such a grant determine where the property rests:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the terms of such a grant determine where the property rests', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 14, NULL, 'If a man grants something for his own lifetime, it remains his for as long as he lives. If the condition is tied to the grantor''s life and he dies, the property returns to his heirs. If the condition is tied to the recipient''s life, the property belongs to the recipient for the duration of his life; should the grantor die in the interim, the grantor''s heirs have no claim over it — the recipient may continue to dwell in it and make use of it until his own death. If the grantor made the grant for the recipient and his heirs, then it belongs to the recipient and passes to his heirs after him, in accordance with whatever the grantor originally settled.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'if a man grants something for his own lifetime it remains his for as long as he lives if the condition is tied to the grantors life and he dies the property returns to his heirs if the condition is tied to the recipients life the property belongs to the recipient for the duration of his life should the grantor die in the interim the grantors heirs have no claim over it the recipient may continue to dwell in it and make use of it until his own death if the grantor made the grant for the recipient and his heirs then it belongs to the recipient and passes to his heirs after him in accordance with whatever the grantor originally settled', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 15, NULL, 'Presents are commended when they are given for the sake of God Almighty and for His pleasure alone. No good attaches to a present given to curry favor in something false, to obtain a like return, to secure the fulfillment of a need, or to win the attention of the recipient. Attending to a believer''s needs and caring for him in what is right is an obligation upon his believing brother; if he takes payment for that, what he takes is unlawful gain. The same applies to whatever he receives in exchange for collusion in falsehood.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'presents are commended when they are given for the sake of god almighty and for his pleasure alone no good attaches to a present given to curry favor in something false to obtain a like return to secure the fulfillment of a need or to win the attention of the recipient attending to a believers needs and caring for him in what is right is an obligation upon his believing brother if he takes payment for that what he takes is unlawful gain the same applies to whatever he receives in exchange for collusion in falsehood', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 16, NULL, 'Al-Baqarah: 271إِن تُبْدُوا۟ ٱلصَّدَقَتِ فَنِعِمَّا هِىَ ۖ وَإِن تُخْفُوهَا وَتُؤْتُوهَا ٱلْفُقَرَآءَ فَهُوَ خَيْرٌۭ لَّكُمْ', '', 'إِن تُبْدُوا۟ ٱلصَّدَقَتِ فَنِعِمَّا هِىَ ۖ وَإِن تُخْفُوهَا وَتُؤْتُوهَا ٱلْفُقَرَآءَ فَهُوَ خَيْرٌۭ لَّكُمْ', 'Al-Baqarah: 271', 2, 271, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'al baqarah 271ان تبدوا الصدقت فنعما هي وان تخفوها وتوتوها الفقراء فهو خير لكم', 'ان تبدوا الصدقت فنعما هي وان تخفوها وتوتوها الفقراء فهو خير لكم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 17, NULL, 'Obligatory giving — zakat and its like — is best given openly and announced. Voluntary charity is best kept secret, though announcing it carries no harm. God, exalted be He, has said: ﴿إِنْ تُبْدُوا الصَّدَقَاتِ فَنِعِمَّا هِيَ وَإِنْ تُخْفُوهَا وَتُؤْتُوهَا الْفُقَرَاءَ فَهُوَ خَيْرٌ لَكُمْ﴾ — "If you disclose your charities, that is good; but if you conceal them and give them to the poor, that is better for you." (Al-Baqarah: 271)', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'obligatory giving zakat and its like is best given openly and announced voluntary charity is best kept secret though announcing it carries no harm god exalted be he has said ان تبدوا الصدقات فنعما هي وان تخفوها وتوتوها الفقراء فهو خير لكم if you disclose your charities that is good but if you conceal them and give them to the poor that is better for you al baqarah 271', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 18, NULL, 'The same principle governs every act of righteousness. Obligatory portions are finer when disclosed and mentioned; voluntary portions are finer when concealed. The obligatory prayer is best performed in the mosque and in congregation; the voluntary prayer is best performed in seclusion. A man who says, "I have prayed the noon prayer" — or the afternoon prayer, or whatever obligatory prayer he names — says nothing wrong; and the same holds if he says, "I have fasted the month of Ramadan." But if he says, "I have risen for the night prayer," or "I have fasted such-and-such" of the voluntary acts, that declaration is disliked, because it opens a door to ostentation. All deeds run on this principle.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the same principle governs every act of righteousness obligatory portions are finer when disclosed and mentioned voluntary portions are finer when concealed the obligatory prayer is best performed in the mosque and in congregation the voluntary prayer is best performed in seclusion a man who says i have prayed the noon prayer or the afternoon prayer or whatever obligatory prayer he names says nothing wrong and the same holds if he says i have fasted the month of ramadan but if he says i have risen for the night prayer or i have fasted such and such of the voluntary acts that declaration is disliked because it opens a door to ostentation all deeds run on this principle', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 19, NULL, 'Whoever owns something not yet taken into his possession may still give it in charity or as a gift. Whoever gives something in charity may not take it back.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'whoever owns something not yet taken into his possession may still give it in charity or as a gift whoever gives something in charity may not take it back', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 20, NULL, 'Whoever sets something aside as an endowment for his child, his freed clients, or particular named individuals — removing it from his own possession and delivering it to them — that endowment is valid. It stands according to whatever conditions he stipulates and the terms by which he restricts it. If those beneficiaries later fall into dispute and corruption among them is feared, they may sell the endowment and divide the proceeds in proportion to each person''s assigned share, provided the endowment was made to them by name. If, however, he set it aside for them and their descendants, or declared, "When they die out, it becomes a charity," then it is a charity, and they may not sell it. If he designated its final destination as a charity, then when those for whom it was set aside die out, it passes to the poor and the needy. If he made no such final designation and those for whom it was endowed die out, it returns to him if he is still living, or to whoever is entitled to his inheritance if he has died.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'whoever sets something aside as an endowment for his child his freed clients or particular named individuals removing it from his own possession and delivering it to them that endowment is valid it stands according to whatever conditions he stipulates and the terms by which he restricts it if those beneficiaries later fall into dispute and corruption among them is feared they may sell the endowment and divide the proceeds in proportion to each persons assigned share provided the endowment was made to them by name if however he set it aside for them and their descendants or declared when they die out it becomes a charity then it is a charity and they may not sell it if he designated its final destination as a charity then when those for whom it was set aside die out it passes to the poor and the needy if he made no such final designation and those for whom it was endowed die out it returns to him if he is still living or to whoever is entitled to his inheritance if he has died', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 21, NULL, 'If he stipulated that any woman among the beneficiaries who marries forfeits her right in the endowment — and those women are later widowed and return — the condition holds and their right is restored. If, on the other hand, he said, "If I am in need, I have the better right to it," then the endowment is void. In that case it forms part of his estate for his heirs at his death, and he may reclaim it whenever he wishes.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'if he stipulated that any woman among the beneficiaries who marries forfeits her right in the endowment and those women are later widowed and return the condition holds and their right is restored if on the other hand he said if i am in need i have the better right to it then the endowment is void in that case it forms part of his estate for his heirs at his death and he may reclaim it whenever he wishes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 23, NULL, 'Al-Baqarah: 180كُتِبَ عَلَيْكُمْ إِذَا حَضَرَ أَحَدَكُمُ ٱلْمَوْتُ إِن تَرَكَ خَيْرًا ٱلْوَصِيَّةُ', '', 'كُتِبَ عَلَيْكُمْ إِذَا حَضَرَ أَحَدَكُمُ ٱلْمَوْتُ إِن تَرَكَ خَيْرًا ٱلْوَصِيَّةُ', 'Al-Baqarah: 180', 2, 180, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'al baqarah 180كتب عليكم اذا حضر احدكم الموت ان ترك خيرا الوصيه', 'كتب عليكم اذا حضر احدكم الموت ان ترك خيرا الوصيه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 24, NULL, 'God, exalted be He, has said: ﴿كُتِبَ عَلَيْكُمْ إِذَا حَضَرَ أَحَدَكُمُ الْمَوْتُ إِنْ تَرَكَ خَيْرًا الْوَصِيَّةُ﴾ — "It is prescribed for you, when death approaches one of you and he leaves wealth behind, that he make a bequest." (Al-Baqarah: 180) Death stands present for every living soul, and no one knows when it will come. He also said: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا شَهَادَةُ بَيْنِكُمْ إِذَا حَضَرَ أَحَدَكُمُ الْمَوْتُ حِينَ الْوَصِيَّةِ﴾ — "O you who believe, let there be testimony among you when death approaches one of you, at the time of the bequest." (Al-Maidah: 106)', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'god exalted be he has said كتب عليكم اذا حضر احدكم الموت ان ترك خيرا الوصيه it is prescribed for you when death approaches one of you and he leaves wealth behind that he make a bequest al baqarah 180 death stands present for every living soul and no one knows when it will come he also said يا ايها الذين امنوا شهاده بينكم اذا حضر احدكم الموت حين الوصيه o you who believe let there be testimony among you when death approaches one of you at the time of the bequest al maidah 106', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 25, NULL, 'The Messenger of God, upon him and his family be peace, said: "It does not befit a Muslim to let two nights pass without his will written and kept at his head." He also said: "Whoever fails to make his bequest well at the hour of death has fallen short in his manliness and his reason." They asked, "O Messenger of God, how does the dying man make his bequest?" He said that when death comes to him, the people are to be gathered, and he bears witness and makes his bequest — and on this he spoke at length.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the messenger of god upon him and his family be peace said it does not befit a muslim to let two nights pass without his will written and kept at his head he also said whoever fails to make his bequest well at the hour of death has fallen short in his manliness and his reason they asked o messenger of god how does the dying man make his bequest he said that when death comes to him the people are to be gathered and he bears witness and makes his bequest and on this he spoke at length', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 26, NULL, 'Abu Jafar Muhammad ibn Ali, prayers of God be upon him, said: "The bequest is a duty upon every Muslim." And Jafar ibn Muhammad, prayers of God be upon him, said: "The bequest is obligatory upon every Muslim, and it does not befit anyone to let two nights pass without his will written. No dying person meets death except that God Almighty restores to him his reason, his hearing, and his sight before death so that he may make his bequest — whether he takes that opportunity or leaves it."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'abu jafar muhammad ibn ali prayers of god be upon him said the bequest is a duty upon every muslim and jafar ibn muhammad prayers of god be upon him said the bequest is obligatory upon every muslim and it does not befit anyone to let two nights pass without his will written no dying person meets death except that god almighty restores to him his reason his hearing and his sight before death so that he may make his bequest whether he takes that opportunity or leaves it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 27, NULL, 'The Imams of the House of the Messenger of God permitted a bequest of up to one-third of what the testator leaves, and no more, and they did not allow anything beyond that third except with the consent of the heirs.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the imams of the house of the messenger of god permitted a bequest of up to one third of what the testator leaves and no more and they did not allow anything beyond that third except with the consent of the heirs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 28, NULL, 'Where a testator frames a set of bequests directing that the Hajj be performed on his behalf, that a slave be freed, and that expiation be made for his oaths, the following order applies — provided he had not performed the Hajj and was unable to, and the bequest falls within the third:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'where a testator frames a set of bequests directing that the hajj be performed on his behalf that a slave be freed and that expiation be made for his oaths the following order applies provided he had not performed the hajj and was unable to and the bequest falls within the third', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 29, NULL, 'The Hajj is discharged first. The expiation is discharged second. The manumission is discharged third. Whatever shortfall remains is met from what is left.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the hajj is discharged first the expiation is discharged second the manumission is discharged third whatever shortfall remains is met from what is left', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 30, NULL, 'This order governs when the testator has framed the bequest with words such as "Let my third be brought out and spent on such-and-such." If, however, he made a bequest without naming a third or any fixed sum, and simply directed that the Hajj be performed for him when he had not yet performed it, then the cost of the Hajj is drawn from the whole of the estate. Equally, if he declares that he owes zakat or any other binding obligation and directs that it be discharged on his behalf, it too is drawn from the entire estate. Whatever is voluntary, by contrast, is drawn only from the third. Accordingly, if he had already performed the Hajj and then directs that a further Hajj be performed for him, that direction is voluntary in nature and is met from the third alone.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'this order governs when the testator has framed the bequest with words such as let my third be brought out and spent on such and such if however he made a bequest without naming a third or any fixed sum and simply directed that the hajj be performed for him when he had not yet performed it then the cost of the hajj is drawn from the whole of the estate equally if he declares that he owes zakat or any other binding obligation and directs that it be discharged on his behalf it too is drawn from the entire estate whatever is voluntary by contrast is drawn only from the third accordingly if he had already performed the hajj and then directs that a further hajj be performed for him that direction is voluntary in nature and is met from the third alone', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 31, NULL, 'No bequest may be made to an heir unless the remaining heirs consent to it, for God Almighty has already fixed each heir''s share, and nothing may be added to it. An exception arises when the testator makes a bequest for a parent or relative who does not inherit from him — as when his parents are enslaved or non-Muslim, or related to him through nursing, or are foster parents.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'no bequest may be made to an heir unless the remaining heirs consent to it for god almighty has already fixed each heirs share and nothing may be added to it an exception arises when the testator makes a bequest for a parent or relative who does not inherit from him as when his parents are enslaved or non muslim or related to him through nursing or are foster parents', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 32, NULL, 'When a man, during the illness from which he dies, acknowledges a debt in the presence of his heirs or some of them, his situation is examined. If he is under suspicion, his acknowledgment carries no weight unless clear proof establishes the origin of the debt he has acknowledged — unless the remaining heirs consent to it. If, however, he is sick yet known to be upright and trustworthy, his acknowledgment is accepted without further proof.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'when a man during the illness from which he dies acknowledges a debt in the presence of his heirs or some of them his situation is examined if he is under suspicion his acknowledgment carries no weight unless clear proof establishes the origin of the debt he has acknowledged unless the remaining heirs consent to it if however he is sick yet known to be upright and trustworthy his acknowledgment is accepted without further proof', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 33, NULL, 'Once a man has made his bequest, he may revoke it. He may also add to it or subtract from it at any point while he is alive and of sound understanding. If his bequests exceed the third and his heirs learn of this during his lifetime and give their approval, they have no right to withdraw that approval after his death.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'once a man has made his bequest he may revoke it he may also add to it or subtract from it at any point while he is alive and of sound understanding if his bequests exceed the third and his heirs learn of this during his lifetime and give their approval they have no right to withdraw that approval after his death', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 35, NULL, 'What follows concerns the shares of the child, the parents, the spouses, the grandfather, the grandmother, and the brothers.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'what follows concerns the shares of the child the parents the spouses the grandfather the grandmother and the brothers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 36, NULL, 'God, mighty and majestic, has said: ﴿يُوصِيكُمُ اللَّهُ فِي أَوْلَادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ فَإِنْ كُنَّ نِسَاءً فَوْقَ اثْنَتَيْنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَ وَإِنْ كَانَتْ وَاحِدَةً فَلَهَا النِّصْفُ وَلِأَبَوَيْهِ لِكُلِّ وَاحِدٍ مِنْهُمَا السُّدُسُ مِمَّا تَرَكَ إِنْ كَانَ لَهُ وَلَدٌ فَإِنْ لَمْ يَكُنْ لَهُ وَلَدٌ وَوَرِثَهُ أَبَوَاهُ فَلِأُمِّهِ الثُّلُثُ فَإِنْ كَانَ لَهُ إِخْوَةٌ فَلِأُمِّهِ السُّدُسُ مِنْ بَعْدِ وَصِيَّةٍ يُوصِي بِهَا أَوْ دَيْنٍ﴾ — "God charges you concerning your children: to the male the like of the share of two females.', '', '﴿يُوصِيكُمُ اللَّهُ فِي أَوْلَادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ فَإِنْ كُنَّ نِسَاءً فَوْقَ اثْنَتَيْنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَ وَإِنْ كَانَتْ وَاحِدَةً فَلَهَا النِّصْفُ وَلِأَبَوَيْهِ لِكُلِّ وَاحِدٍ مِنْهُمَا السُّدُسُ مِمَّا تَرَكَ إِنْ كَانَ لَهُ وَلَدٌ فَإِنْ لَمْ يَكُنْ لَهُ وَلَدٌ وَوَرِثَهُ أَبَوَاهُ فَلِأُمِّهِ الثُّلُثُ فَإِنْ كَانَ لَهُ إِخْوَةٌ فَلِأُمِّهِ السُّدُسُ مِنْ بَعْدِ وَصِيَّةٍ يُوصِي بِهَا أَوْ دَيْنٍ﴾', NULL, 4, 11, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'god mighty and majestic has said يوصيكم الله في اولادكم للذكر مثل حظ الانثيين فان كن نساء فوق اثنتين فلهن ثلثا ما ترك وان كانت واحده فلها النصف ولابويه لكل واحد منهما السدس مما ترك ان كان له ولد فان لم يكن له ولد وورثه ابواه فلامه الثلث فان كان له اخوه فلامه السدس من بعد وصيه يوصي بها او دين god charges you concerning your children to the male the like of the share of two females', 'يوصيكم الله في اولادكم للذكر مثل حظ الانثيين فان كن نساء فوق اثنتين فلهن ثلثا ما ترك وان كانت واحده فلها النصف ولابويه لكل واحد منهما السدس مما ترك ان كان له ولد فان لم يكن له ولد وورثه ابواه فلامه الثلث فان كان له اخوه فلامه السدس من بعد وصيه يوصي بها او دين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 37, NULL, 'The narration from the People of the House, prayers of God be upon them, continues: when a man dies leaving children — sons and daughters, with no other heir — his estate is divided among them so that each son receives the equivalent of two daughters'' shares. The same rule applies when he leaves a single son and a single daughter: the son takes two-thirds and the daughter one-third. If he leaves only a single son with no other heir, the entire estate passes to that son. If he leaves two sons, or more, the estate is divided equally among them.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the narration from the people of the house prayers of god be upon them continues when a man dies leaving children sons and daughters with no other heir his estate is divided among them so that each son receives the equivalent of two daughters shares the same rule applies when he leaves a single son and a single daughter the son takes two thirds and the daughter one third if he leaves only a single son with no other heir the entire estate passes to that son if he leaves two sons or more the estate is divided equally among them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 38, NULL, 'Al-Anfal: 75وَٱلَّذِينَ آمَنُوا۟ مِنۢ بَعْدُ وَهَاجَرُوا۟ وَجَهَدُوا۟ مَعَكُمْ فَأُو۟لَٓئِكَ مِنكُمْ ۚ وَأُو۟لُوا۟ ٱلْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍۢ فِى كِتَبِ ٱللَّهِ ۗ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌۢ', '', 'وَٱلَّذِينَ آمَنُوا۟ مِنۢ بَعْدُ وَهَاجَرُوا۟ وَجَهَدُوا۟ مَعَكُمْ فَأُو۟لَٓئِكَ مِنكُمْ ۚ وَأُو۟لُوا۟ ٱلْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍۢ فِى كِتَبِ ٱللَّهِ ۗ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌۢ', 'Al-Anfal: 75', 8, 75, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'al anfal 75والذين امنوا من بعد وهاجروا وجهدوا معكم فاوليك منكم واولوا الارحام بعضهم اولي ببعض في كتب الله ان الله بكل شيء عليم', 'والذين امنوا من بعد وهاجروا وجهدوا معكم فاوليك منكم واولوا الارحام بعضهم اولي ببعض في كتب الله ان الله بكل شيء عليم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 39, NULL, 'If he leaves a single daughter with no other heir, she takes one half by the share God Almighty has named for her in the verses already recited, and the remaining half is returned to her by the tie of kinship, in accordance with the word of God, mighty and majestic: ﴿وَالَّذِينَ آمَنُوا مِنْ بَعْدُ وَهَاجَرُوا وَجَاهَدُوا مَعَكُمْ فَأُولَئِكَ مِنْكُمْ وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ إِنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ﴾ — "And those who believed afterward and emigrated and struggled along with you, they are of you; and those who are bound by blood are nearer to one another in the Book of God. Truly God has knowledge of all things." (Al-Anfal: 75) If there are two daughters, or more, two-thirds is theirs, divided equally among them by the named share, and the remaining third is returned to them by the tie of kinship.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'if he leaves a single daughter with no other heir she takes one half by the share god almighty has named for her in the verses already recited and the remaining half is returned to her by the tie of kinship in accordance with the word of god mighty and majestic والذين امنوا من بعد وهاجروا وجاهدوا معكم فاوليك منكم واولو الارحام بعضهم اولي ببعض في كتاب الله ان الله بكل شيء عليم and those who believed afterward and emigrated and struggled along with you they are of you and those who are bound by blood are nearer to one another in the book of god truly god has knowledge of all things al anfal 75 if there are two daughters or more two thirds is theirs divided equally among them by the named share and the remaining third is returned to them by the tie of kinship', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 40, NULL, 'When children are present alongside those entitled to fixed shares — the husband, the wife, the grandmother, and the parents — those fixed-share heirs receive what God Almighty has named for them, and whatever remains passes to the child or children as already described. If there is no child but there is a grandchild, the grandchild stands in the child''s place: males among them as males, females as females, however far the descent extends, provided no one nearer to the deceased exists among them — for whoever is nearer screens out whoever is more remote.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'when children are present alongside those entitled to fixed shares the husband the wife the grandmother and the parents those fixed share heirs receive what god almighty has named for them and whatever remains passes to the child or children as already described if there is no child but there is a grandchild the grandchild stands in the childs place males among them as males females as females however far the descent extends provided no one nearer to the deceased exists among them for whoever is nearer screens out whoever is more remote', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 41, NULL, 'Every heir for whom God Almighty has named a share in the Book holds a stronger claim than one He has not named. When something remains beyond what He named for a given heir, it is returned to that heir, and to sons and the broader group in proportion to their respective inheritance shares — with one exception: nothing is returned to the husband or the wife unless a tie of kinship independently qualifies them for the return.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'every heir for whom god almighty has named a share in the book holds a stronger claim than one he has not named when something remains beyond what he named for a given heir it is returned to that heir and to sons and the broader group in proportion to their respective inheritance shares with one exception nothing is returned to the husband or the wife unless a tie of kinship independently qualifies them for the return', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 42, NULL, 'To illustrate: a man dies leaving both parents and a daughter. The parents receive two sixths, and the daughter receives the half — her named share. One sixth remains. Since the two sixths assigned to the parents account for two shares, and the half assigned to the daughter amounts to three sixths, five shares have been distributed in total, leaving one share over. That remaining share is returned to the heirs in proportion to their shares, so the estate reverts to five parts: three-fifths to the daughter and two-fifths to the parents.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'to illustrate a man dies leaving both parents and a daughter the parents receive two sixths and the daughter receives the half her named share one sixth remains since the two sixths assigned to the parents account for two shares and the half assigned to the daughter amounts to three sixths five shares have been distributed in total leaving one share over that remaining share is returned to the heirs in proportion to their shares so the estate reverts to five parts three fifths to the daughter and two fifths to the parents', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 43, NULL, 'If instead the man leaves a daughter, a father, and a mother, the daughter again takes the half, and the father or the mother takes the sixth. The estate then reverts, on the same principle, to fourths: one quarter to the father or the mother, and three-quarters to the daughter. Whatever cases follow this pattern are resolved by the same method.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'if instead the man leaves a daughter a father and a mother the daughter again takes the half and the father or the mother takes the sixth the estate then reverts on the same principle to fourths one quarter to the father or the mother and three quarters to the daughter whatever cases follow this pattern are resolved by the same method', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 45, NULL, 'When only the parents survive and no other heir is present, the father receives two thirds and the mother receives one third. If a child is also present, the rule proceeds as already described — even when the children are many, and whether they are male or female: they take what remains after the fixed shares are satisfied, with each male receiving the equivalent of two female shares, regardless of how few or how many there are. If two sons survive, they divide what remains equally between them. If two children survive alongside the parents, the children together receive two thirds. What falls to a single child has already been set out above.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'when only the parents survive and no other heir is present the father receives two thirds and the mother receives one third if a child is also present the rule proceeds as already described even when the children are many and whether they are male or female they take what remains after the fixed shares are satisfied with each male receiving the equivalent of two female shares regardless of how few or how many there are if two sons survive they divide what remains equally between them if two children survive alongside the parents the children together receive two thirds what falls to a single child has already been set out above', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 46, NULL, 'When a person leaves behind both parents together with brothers — whether full brothers or brothers through the father — those brothers receive nothing. The mother receives one sixth, and the father takes the remainder, as Allah, mighty and majestic, has stated in His Book. Brothers through the mother do not deprive the mother of her third by inheriting for themselves; they only reduce her share, so that the father receives two thirds and the mother one third. The father inherits alongside the child and alongside the parents, and none inherits together with the child and the parents except the husband, the wife, and the grandmother.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'when a person leaves behind both parents together with brothers whether full brothers or brothers through the father those brothers receive nothing the mother receives one sixth and the father takes the remainder as allah mighty and majestic has stated in his book brothers through the mother do not deprive the mother of her third by inheriting for themselves they only reduce her share so that the father receives two thirds and the mother one third the father inherits alongside the child and alongside the parents and none inherits together with the child and the parents except the husband the wife and the grandmother', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 47, NULL, 'It is narrated from the Messenger of Allah, may Allah bless him and his family and grant them peace, that he assigned an inheritance to the grandmother and fixed one sixth for her, looking to her children as they divided among themselves. The grandmother therefore inherits one sixth alongside both parents, and one sixth alongside either parent alone. If she stands alone with no one to exclude her and no other heir survives, she takes one sixth by the naming of her share, and the remainder is then returned to her, so that she gathers the whole inheritance. If two grandmothers survive — one on the father''s side and one on the mother''s side — the father''s mother and the mother''s mother share two thirds between them, while the mother''s mother alone takes one third. Among the grandmothers, whichever is closer in degree excludes the one more remote.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'it is narrated from the messenger of allah may allah bless him and his family and grant them peace that he assigned an inheritance to the grandmother and fixed one sixth for her looking to her children as they divided among themselves the grandmother therefore inherits one sixth alongside both parents and one sixth alongside either parent alone if she stands alone with no one to exclude her and no other heir survives she takes one sixth by the naming of her share and the remainder is then returned to her so that she gathers the whole inheritance if two grandmothers survive one on the fathers side and one on the mothers side the fathers mother and the mothers mother share two thirds between them while the mothers mother alone takes one third among the grandmothers whichever is closer in degree excludes the one more remote', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 48, NULL, 'The paternal grandfather stands in the position of the full brothers, and the brothers through the father inherit as they inherit. He is counted as one of them, and whoever excludes them excludes him. The maternal grandfather stands in the position of the uterine brother, inheriting as they inherit and excluded as they are excluded. This is because the grandfather''s kinship to the deceased mirrors the brother''s kinship to the deceased: each is connected to the deceased through his father, and that connection through the father is a single bond — the grandfather being that father''s father, and the brother being that father''s son.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the paternal grandfather stands in the position of the full brothers and the brothers through the father inherit as they inherit he is counted as one of them and whoever excludes them excludes him the maternal grandfather stands in the position of the uterine brother inheriting as they inherit and excluded as they are excluded this is because the grandfathers kinship to the deceased mirrors the brothers kinship to the deceased each is connected to the deceased through his father and that connection through the father is a single bond the grandfather being that fathers father and the brother being that fathers son', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 49, NULL, 'An-Nisa: 12وَلَدٌۭ ۚ فَإِن كَانَ لَكُمْ وَلَدٌۭ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكْتُم ۚ مِّنۢ بَعْدِ وَصِيَّةٍۢ تُوصُونَ بِهَآ أَوْ دَيْنٍۢ ۗ وَإِن كَانَ رَجُلٌۭ يُورَثُ كَلَلَةً أَوِ ٱمْرَأَةٌۭ وَلَهُۥٓ أَخٌ أَوْ أُخْتٌۭ فَلِكُلِّ وَحِدٍۢ مِّنْهُمَا ٱلسُّدُسُ ۚ فَإِن كَانُوٓا۟ أَكْثَرَ مِن ذَلِكَ فَهُمْ شُرَكَآءُ فِى ٱلثُّلُثِ ۚ مِنۢ بَعْدِ وَصِيَّةٍۢ يُوصَىٰ بِهَآ أَوْ دَيْنٍ غَيْرَ مُضَآرٍّۢ ۚ وَصِيَّةًۭ مِّنَ ٱللَّهِ ۗ وَٱللَّهُ عَلِيمٌ حَلِيمٌۭ', '', 'وَلَدٌۭ ۚ فَإِن كَانَ لَكُمْ وَلَدٌۭ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكْتُم ۚ مِّنۢ بَعْدِ وَصِيَّةٍۢ تُوصُونَ بِهَآ أَوْ دَيْنٍۢ ۗ وَإِن كَانَ رَجُلٌۭ يُورَثُ كَلَلَةً أَوِ ٱمْرَأَةٌۭ وَلَهُۥٓ أَخٌ أَوْ أُخْتٌۭ فَلِكُلِّ وَحِدٍۢ مِّنْهُمَا ٱلسُّدُسُ ۚ فَإِن كَانُوٓا۟ أَكْثَرَ مِن ذَلِكَ فَهُمْ شُرَكَآءُ فِى ٱلثُّلُثِ ۚ مِنۢ بَعْدِ وَصِيَّةٍۢ يُوصَىٰ بِهَآ أَوْ دَيْنٍ غَيْرَ مُضَآرٍّۢ ۚ وَصِيَّةًۭ مِّنَ ٱللَّهِ ۗ وَٱللَّهُ عَلِيمٌ حَلِيمٌۭ', 'An-Nisa: 12', 4, 12, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'an nisa 12ولد فان كان لكم ولد فلهن الثمن مما تركتم من بعد وصيه توصون بها او دين وان كان رجل يورث كلله او امراه وله اخ او اخت فلكل وحد منهما السدس فان كانوا اكثر من ذلك فهم شركاء في الثلث من بعد وصيه يوصي بها او دين غير مضار وصيه من الله والله عليم حليم', 'ولد فان كان لكم ولد فلهن الثمن مما تركتم من بعد وصيه توصون بها او دين وان كان رجل يورث كلله او امراه وله اخ او اخت فلكل وحد منهما السدس فان كانوا اكثر من ذلك فهم شركاء في الثلث من بعد وصيه يوصي بها او دين غير مضار وصيه من الله والله عليم حليم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 50, NULL, 'Where the deceased leaves behind no father, no mother, and no other ascendant, but is survived by brothers, the inheritance belongs to those brothers. Full brothers exclude brothers through the father; where there are no full brothers, the paternal brothers stand in their place. When both full brothers and paternal brothers are present together, the estate is divided among them according to the male and female shares. Where the brothers are through the mother alone, the inheritance is divided equally between male and female, as Allah, mighty and majestic, said: ﴿وَإِن كَانَ رَجُلٌ يُورَثُ كَلَالَةً أَوِ امْرَأَةٌ وَلَهُ أَخٌ أَوْ أُخْتٌ فَلِكُلِّ وَاحِدٍ مِّنْهُمَا السُّدُسُ فَإِن كَانُوا أَكْثَرَ مِن ذَٰلِكَ فَهُمْ شُرَكَاءُ فِي الثُّلُثِ﴾ "If a man dies leaving no children, and he has a brother or a sister, each of them receives one sixth; but if there are more than that, they share one third" (al-Nisa 12). It is narrated that this verse was revealed concerning a brother and a sister through the mother.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'where the deceased leaves behind no father no mother and no other ascendant but is survived by brothers the inheritance belongs to those brothers full brothers exclude brothers through the father where there are no full brothers the paternal brothers stand in their place when both full brothers and paternal brothers are present together the estate is divided among them according to the male and female shares where the brothers are through the mother alone the inheritance is divided equally between male and female as allah mighty and majestic said وان كان رجل يورث كلاله او امراه وله اخ او اخت فلكل واحد منهما السدس فان كانوا اكثر من ذلك فهم شركاء في الثلث if a man dies leaving no children and he has a brother or a sister each of them receives one sixth but if there are more than that they share one third al nisa 12 it is narrated that this verse was revealed concerning a brother and a sister through the mother', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 51, NULL, 'When full brothers and brothers through the father are present together, the full brothers receive two thirds divided among them, the male taking the equivalent of two females'' shares, whether they are few or many. If maternal siblings are also present — male or female, two or more, whether two sisters, a brother and sister, or brothers and sisters — one third belongs to those maternal siblings, divided equally among them regardless of sex and however many they may be, while the brothers through the father are set aside. Likewise, if a person leaves behind one maternal brother or one maternal sister, that single one receives one sixth; if there are several, they receive one third together. If there is a full sister, she receives one half, and the remainder returns to her through kinship.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'when full brothers and brothers through the father are present together the full brothers receive two thirds divided among them the male taking the equivalent of two females shares whether they are few or many if maternal siblings are also present male or female two or more whether two sisters a brother and sister or brothers and sisters one third belongs to those maternal siblings divided equally among them regardless of sex and however many they may be while the brothers through the father are set aside likewise if a person leaves behind one maternal brother or one maternal sister that single one receives one sixth if there are several they receive one third together if there is a full sister she receives one half and the remainder returns to her through kinship', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 52, NULL, 'Brothers and sisters inherit alongside the spouses. The spouse''s share is given first, and what remains goes to the brothers as described. The husband receives half of his wife''s estate if she has no child, and a quarter if she has a child, whether male, female, or several. The wife receives a quarter of her husband''s estate if he has no child, and one eighth if he has a child, whether male, female, or several — as the explicit text of the Book prescribes. Two, three, or four wives share equally in that same portion: one eighth where there is a child, and a quarter where there is none, dividing it equally among them with nothing added to it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'brothers and sisters inherit alongside the spouses the spouses share is given first and what remains goes to the brothers as described the husband receives half of his wifes estate if she has no child and a quarter if she has a child whether male female or several the wife receives a quarter of her husbands estate if he has no child and one eighth if he has a child whether male female or several as the explicit text of the book prescribes two three or four wives share equally in that same portion one eighth where there is a child and a quarter where there is none dividing it equally among them with nothing added to it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 53, NULL, 'When a man dies leaving two parents and a wife, the husband receives half his wife''s estate, the wife receives a quarter of her husband''s estate, the mother receives one third, and the father takes the remainder — as the text of the Book prescribes. By the same principle that gives the father precedence over the mother when brothers are present, the deficiency here falls upon him, for Allah, mighty and majestic, said: ﴿فَإِن كَانَ لَهُ إِخْوَةٌ فَلِأُمِّهِ السُّدُسُ﴾ — "If he has brothers, his mother receives one sixth" (al-Nisa 11). Since brothers do not inherit alongside the parents, whatever remains passes to the parents. The mother therefore receives one third when there are no brothers, and one sixth when there are brothers. All of this is the position of the Ahl al-Bayt, may the prayers of Allah be upon them all.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'when a man dies leaving two parents and a wife the husband receives half his wifes estate the wife receives a quarter of her husbands estate the mother receives one third and the father takes the remainder as the text of the book prescribes by the same principle that gives the father precedence over the mother when brothers are present the deficiency here falls upon him for allah mighty and majestic said فان كان له اخوه فلامه السدس if he has brothers his mother receives one sixth al nisa 11 since brothers do not inherit alongside the parents whatever remains passes to the parents the mother therefore receives one third when there are no brothers and one sixth when there are brothers all of this is the position of the ahl al bayt may the prayers of allah be upon them all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 55, NULL, 'The Ahl al-Bayt, may the prayers of Allah be upon them, have transmitted the following: whoever dies leaving behind those who hold fixed shares named in the Book, they inherit according to the shares Allah, mighty and majestic, has named therein. If he leaves behind none of those named sharers, his estate passes to whichever of his kindred stand nearest to him; where two or more stand at equal distance, the estate is divided among them. A relative who draws near through someone who holds a named share takes precedence over one who draws near through someone who holds no named share. Those who are nearer exclude those who are more remote. The line of succession then runs as follows:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the ahl al bayt may the prayers of allah be upon them have transmitted the following whoever dies leaving behind those who hold fixed shares named in the book they inherit according to the shares allah mighty and majestic has named therein if he leaves behind none of those named sharers his estate passes to whichever of his kindred stand nearest to him where two or more stand at equal distance the estate is divided among them a relative who draws near through someone who holds a named share takes precedence over one who draws near through someone who holds no named share those who are nearer exclude those who are more remote the line of succession then runs as follows', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 56, NULL, 'Whoever is related through the deceased''s father inherits the father''s share, as though the father were alive. Whoever is related through the mother inherits the mother''s share. Whoever is related through a brother inherits that brother''s share. Whoever is related through a sister inherits her share.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'whoever is related through the deceaseds father inherits the fathers share as though the father were alive whoever is related through the mother inherits the mothers share whoever is related through a brother inherits that brothers share whoever is related through a sister inherits her share', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 57, NULL, 'A man dies leaving a son''s son and a son''s daughter. The estate is divided between them with the male receiving the equivalent of two female shares.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'a man dies leaving a sons son and a sons daughter the estate is divided between them with the male receiving the equivalent of two female shares', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 58, NULL, 'If he leaves a daughter''s son and a son''s daughter, the son''s daughter receives two thirds — her father''s share — and the daughter''s son receives one third, which is his mother''s share.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'if he leaves a daughters son and a sons daughter the sons daughter receives two thirds her fathers share and the daughters son receives one third which is his mothers share', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 59, NULL, 'If he leaves sons and daughters of a predeceased son together with a son or daughter of a predeceased daughter, the division runs as follows:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'if he leaves sons and daughters of a predeceased son together with a son or daughter of a predeceased daughter the division runs as follows', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 60, NULL, 'One third goes to the single son or single daughter of the daughter, or to all the daughter''s children however many they are. Two thirds go to the children of the son, divided among them with the male receiving the equivalent of two female shares, whether few or many.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'one third goes to the single son or single daughter of the daughter or to all the daughters children however many they are two thirds go to the children of the son divided among them with the male receiving the equivalent of two female shares whether few or many', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 61, NULL, 'The children of the son inherit their father''s share as though he were alive, and the children of the daughter inherit their mother''s share as though she were alive, whether each group is few or many.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the children of the son inherit their fathers share as though he were alive and the children of the daughter inherit their mothers share as though she were alive whether each group is few or many', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 62, NULL, 'Those who draw near through the mother''s kinship inherit as brothers through the mother inherit — male and female alike. Those who draw near through the father''s kinship inherit with the male receiving the equivalent of two female shares.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'those who draw near through the mothers kinship inherit as brothers through the mother inherit male and female alike those who draw near through the fathers kinship inherit with the male receiving the equivalent of two female shares', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 63, NULL, 'The sons of brothers and their daughters, and the sisters, inherit in the manner already described when there is no direct child or grandchild, just as the grandchildren inherit as explained earlier. Where they descend from one father or one mother, the sons of the brother divide the wealth among themselves with the male receiving the equivalent of two female shares.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the sons of brothers and their daughters and the sisters inherit in the manner already described when there is no direct child or grandchild just as the grandchildren inherit as explained earlier where they descend from one father or one mother the sons of the brother divide the wealth among themselves with the male receiving the equivalent of two female shares', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 64, NULL, 'The same principle governs the sons of paternal uncles and the sons of maternal uncles: the sons of maternal uncles divide equally between male and female, each group inheriting what would have belonged to its father or mother had that parent been alive, whether they are few or many.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the same principle governs the sons of paternal uncles and the sons of maternal uncles the sons of maternal uncles divide equally between male and female each group inheriting what would have belonged to its father or mother had that parent been alive whether they are few or many', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 65, NULL, 'The maternal uncle and the maternal aunt share the wealth equally between them. The paternal uncle and the paternal aunt share it with the male receiving the equivalent of two female shares. Their children divide on the same basis respectively.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the maternal uncle and the maternal aunt share the wealth equally between them the paternal uncle and the paternal aunt share it with the male receiving the equivalent of two female shares their children divide on the same basis respectively', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 66, NULL, 'Of the total estate:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'of the total estate', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 67, NULL, 'One third goes to the sons of the maternal uncle and the sons of the maternal aunt, shared among them, their males and females alike. Two thirds go to the sons of the paternal uncle and the paternal aunt, divided among them with the male receiving the equivalent of two female shares.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'one third goes to the sons of the maternal uncle and the sons of the maternal aunt shared among them their males and females alike two thirds go to the sons of the paternal uncle and the paternal aunt divided among them with the male receiving the equivalent of two female shares', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 68, NULL, 'Among the kindred and the connections, the nearer relative excludes the more remote. The paternal uncle excludes the cousin; the son of the maternal uncle and the maternal aunt excludes the cousin and the son of the maternal uncle; the paternal aunt excludes the cousin and the son of the maternal uncle; and the maternal aunt excludes the cousin and the son of the maternal aunt — each of these standing one degree closer to the deceased than the one excluded. Whoever draws near through a full brother is more deserving than one who draws near through a half-brother on the father''s side. To the kindred through the mother belongs their portion of the sixth that was the share of the person through whom they are related, divided among them, males and females alike. Whoever draws near through one who holds a fixed share excludes whoever draws near through one who does not. When several groups each draw near through a different shareholder, each group receives the share of the person through whom they are related, as has already been established.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'among the kindred and the connections the nearer relative excludes the more remote the paternal uncle excludes the cousin the son of the maternal uncle and the maternal aunt excludes the cousin and the son of the maternal uncle the paternal aunt excludes the cousin and the son of the maternal uncle and the maternal aunt excludes the cousin and the son of the maternal aunt each of these standing one degree closer to the deceased than the one excluded whoever draws near through a full brother is more deserving than one who draws near through a half brother on the fathers side to the kindred through the mother belongs their portion of the sixth that was the share of the person through whom they are related divided among them males and females alike whoever draws near through one who holds a fixed share excludes whoever draws near through one who does not when several groups each draw near through a different shareholder each group receives the share of the person through whom they are related as has already been established', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 69, NULL, 'There is no proportional reduction — no awl — in any fixed apportionment. The reckoning begins with the one whom Allah, mighty and majestic, has placed first. Whoever Allah, mighty and majestic, has assigned a fixed share when alone, and whose share is then reduced by the presence of another, suffers no deduction from that second named portion. This holds for the husband, the wife, the mother, and the father: nothing is deducted from the husband''s quarter, nothing from the wife''s eighth, and nothing from either parent''s sixth. The deficiency falls upon the residuary heir, and to that heir likewise belongs any increase.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'there is no proportional reduction no awl in any fixed apportionment the reckoning begins with the one whom allah mighty and majestic has placed first whoever allah mighty and majestic has assigned a fixed share when alone and whose share is then reduced by the presence of another suffers no deduction from that second named portion this holds for the husband the wife the mother and the father nothing is deducted from the husbands quarter nothing from the wifes eighth and nothing from either parents sixth the deficiency falls upon the residuary heir and to that heir likewise belongs any increase', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 70, NULL, 'An-Nisa: 12وَلَدٌۭ ۚ فَإِن كَانَ لَكُمْ وَلَدٌۭ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكْتُم ۚ مِّنۢ بَعْدِ وَصِيَّةٍۢ تُوصُونَ بِهَآ أَوْ دَيْنٍۢ ۗ وَإِن كَانَ رَجُلٌۭ يُورَثُ كَلَلَةً أَوِ ٱمْرَأَةٌۭ وَلَهُۥٓ أَخٌ أَوْ أُخْتٌۭ فَلِكُلِّ وَحِدٍۢ مِّنْهُمَا ٱلسُّدُسُ ۚ فَإِن كَانُوٓا۟ أَكْثَرَ مِن ذَلِكَ فَهُمْ شُرَكَآءُ فِى ٱلثُّلُثِ ۚ مِنۢ بَعْدِ وَصِيَّةٍۢ يُوصَىٰ بِهَآ أَوْ دَيْنٍ غَيْرَ مُضَآرٍّۢ ۚ وَصِيَّةًۭ مِّنَ ٱللَّهِ ۗ وَٱللَّهُ عَلِيمٌ حَلِيمٌۭ', '', 'وَلَدٌۭ ۚ فَإِن كَانَ لَكُمْ وَلَدٌۭ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكْتُم ۚ مِّنۢ بَعْدِ وَصِيَّةٍۢ تُوصُونَ بِهَآ أَوْ دَيْنٍۢ ۗ وَإِن كَانَ رَجُلٌۭ يُورَثُ كَلَلَةً أَوِ ٱمْرَأَةٌۭ وَلَهُۥٓ أَخٌ أَوْ أُخْتٌۭ فَلِكُلِّ وَحِدٍۢ مِّنْهُمَا ٱلسُّدُسُ ۚ فَإِن كَانُوٓا۟ أَكْثَرَ مِن ذَلِكَ فَهُمْ شُرَكَآءُ فِى ٱلثُّلُثِ ۚ مِنۢ بَعْدِ وَصِيَّةٍۢ يُوصَىٰ بِهَآ أَوْ دَيْنٍ غَيْرَ مُضَآرٍّۢ ۚ وَصِيَّةًۭ مِّنَ ٱللَّهِ ۗ وَٱللَّهُ عَلِيمٌ حَلِيمٌۭ', 'An-Nisa: 12', 4, 12, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'an nisa 12ولد فان كان لكم ولد فلهن الثمن مما تركتم من بعد وصيه توصون بها او دين وان كان رجل يورث كلله او امراه وله اخ او اخت فلكل وحد منهما السدس فان كانوا اكثر من ذلك فهم شركاء في الثلث من بعد وصيه يوصي بها او دين غير مضار وصيه من الله والله عليم حليم', 'ولد فان كان لكم ولد فلهن الثمن مما تركتم من بعد وصيه توصون بها او دين وان كان رجل يورث كلله او امراه وله اخ او اخت فلكل وحد منهما السدس فان كانوا اكثر من ذلك فهم شركاء في الثلث من بعد وصيه يوصي بها او دين غير مضار وصيه من الله والله عليم حليم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 71, NULL, 'An example is a woman who dies leaving behind her husband, her maternal brothers, and her paternal sister. God, mighty and majestic, assigned one half to the husband — she having no child — one half to the sister, and one third to the two maternal brothers, according to the plain reading of what He prescribed. When the highest fixed shares in this case were examined, the calculation proved bewildering, and some inflated the denominator, expanding six shares into eight. Yet God, mighty and majestic, said: ﴿إِنِ امْرُؤٌ هَلَكَ لَيْسَ لَهُ وَلَدٌ وَلَهُ أُخْتٌ فَلَهَا نِصْفُ مَا تَرَكَ وَهُوَ يَرِثُهَا إِن لَّمْ يَكُن لَّهَا وَلَدٌ﴾ "If a man dies having no child, and he has a sister, she receives half of what he left; and he inherits from her if she has no child" (al-Nisa 176). The Almighty thereby made plain that this ruling applies to the sister alone — not when others share the estate alongside her.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'an example is a woman who dies leaving behind her husband her maternal brothers and her paternal sister god mighty and majestic assigned one half to the husband she having no child one half to the sister and one third to the two maternal brothers according to the plain reading of what he prescribed when the highest fixed shares in this case were examined the calculation proved bewildering and some inflated the denominator expanding six shares into eight yet god mighty and majestic said ان امرو هلك ليس له ولد وله اخت فلها نصف ما ترك وهو يرثها ان لم يكن لها ولد if a man dies having no child and he has a sister she receives half of what he left and he inherits from her if she has no child al nisa 176 the almighty thereby made plain that this ruling applies to the sister alone not when others share the estate alongside her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 72, NULL, 'The Master also said: ﴿وَإِن كَانَ رَجُلٌ يُورَثُ كَلَالَةً أَوِ امْرَأَةٌ وَلَهُ أَخٌ أَوْ أُخْتٌ فَلِكُلِّ وَاحِدٍ مِّنْهُمَا السُّدُسُ فَإِن كَانُوا أَكْثَرَ مِن ذَٰلِكَ فَهُمْ شُرَكَاءُ فِي الثُّلُثِ﴾ "If a man dies leaving no children, and he has a brother or a sister, each of them receives one sixth; but if there are more than that, they are partners in one third" (al-Nisa 12). Those scholars themselves hold that the brother for whom God named the whole share, were he to stand in the sister''s place, would receive only one sixth. In that case, therefore, the husband receives one half, the maternal brothers receive one third, and the paternal sister receives one sixth.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the master also said وان كان رجل يورث كلاله او امراه وله اخ او اخت فلكل واحد منهما السدس فان كانوا اكثر من ذلك فهم شركاء في الثلث if a man dies leaving no children and he has a brother or a sister each of them receives one sixth but if there are more than that they are partners in one third al nisa 12 those scholars themselves hold that the brother for whom god named the whole share were he to stand in the sisters place would receive only one sixth in that case therefore the husband receives one half the maternal brothers receive one third and the paternal sister receives one sixth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 73, NULL, 'Likewise, if a woman leaves a husband, two parents, and a daughter, the husband receives a quarter, the two parents receive two sixths, and whatever remains goes to the daughter — for were she a son, she would receive no more than this. The deficiency falls upon the one to whom the surplus belongs. All the questions of awl proceed on this basis. As for those questions that mention brothers and sisters alongside the mother, it has already been established that they inherit nothing in her presence; any questions of awl reported in such cases rest on that meaning. All of this is the position of the Ahl al-Bayt, may the prayers of Allah be upon them all.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'likewise if a woman leaves a husband two parents and a daughter the husband receives a quarter the two parents receive two sixths and whatever remains goes to the daughter for were she a son she would receive no more than this the deficiency falls upon the one to whom the surplus belongs all the questions of awl proceed on this basis as for those questions that mention brothers and sisters alongside the mother it has already been established that they inherit nothing in her presence any questions of awl reported in such cases rest on that meaning all of this is the position of the ahl al bayt may the prayers of allah be upon them all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 75, NULL, 'The lian and its procedure have been discussed earlier, along with the ruling that when a man disavows a child his wife has borne and carries out the lian against her on that account, the child is no longer attributed to him. The child''s lineage runs through his mother, and his inheritance belongs to her kindred. The man who disavowed him does not inherit from him, nor does anyone inherit through that man — unless he acknowledged the child after the lian. For it has been established that if a man carries out the lian against a child and then subsequently acknowledges him, the child inherits from him; however, the one who carried out the lian against the child''s mother does not inherit from the child, nor does anyone inherit through that man. Rather, the child inherits, and those who are close to him through his own kinship inherit alongside him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the lian and its procedure have been discussed earlier along with the ruling that when a man disavows a child his wife has borne and carries out the lian against her on that account the child is no longer attributed to him the childs lineage runs through his mother and his inheritance belongs to her kindred the man who disavowed him does not inherit from him nor does anyone inherit through that man unless he acknowledged the child after the lian for it has been established that if a man carries out the lian against a child and then subsequently acknowledges him the child inherits from him however the one who carried out the lian against the childs mother does not inherit from the child nor does anyone inherit through that man rather the child inherits and those who are close to him through his own kinship inherit alongside him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 76, NULL, 'The child of adultery is not joined to the adulterer who lay with his mother and fathered him. He is not attributed to that man, and neither inherits from the other, whether the man acknowledges him or denies him. His mother inherits from him and he from her; kinship flows through her in both directions. No kinship flows through his father — he draws near to no one through his father, and no one draws near to him by that path. As for the foundling who has neither known mother nor known father, he neither inherits nor is inherited from, and no one draws near to him through parents.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the child of adultery is not joined to the adulterer who lay with his mother and fathered him he is not attributed to that man and neither inherits from the other whether the man acknowledges him or denies him his mother inherits from him and he from her kinship flows through her in both directions no kinship flows through his father he draws near to no one through his father and no one draws near to him by that path as for the foundling who has neither known mother nor known father he neither inherits nor is inherited from and no one draws near to him through parents', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 77, NULL, 'The captive of unknown kin is a person taken from the land of disbelief while another is taken alongside him — or before him, or after him. The two come to recognize each other in the abode of Islam and affirm their kinship. They continue in that affirmation for the remainder of their lives, until one of them dies. The survivor then inherits from the deceased by virtue of the kinship they affirmed while both were living; they inherit from one another and stand in relation to one another through that kinship.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the captive of unknown kin is a person taken from the land of disbelief while another is taken alongside him or before him or after him the two come to recognize each other in the abode of islam and affirm their kinship they continue in that affirmation for the remainder of their lives until one of them dies the survivor then inherits from the deceased by virtue of the kinship they affirmed while both were living they inherit from one another and stand in relation to one another through that kinship', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 78, NULL, 'The Messenger of Allah, may Allah bless him and his family and grant them peace, is reported to have said, "The people of two different faiths do not inherit from one another." On this basis, no two people of differing faiths inherit from each other. Mutual inheritance, by its nature, means that each party inherits from the other. In Arabic, this form is reciprocal, and reciprocal action in the speech of the Arabs requires two agents, even though the simple act may proceed from one. One says that two men struck one another when each struck his companion, and that a man struck another when only one struck the other.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the messenger of allah may allah bless him and his family and grant them peace is reported to have said the people of two different faiths do not inherit from one another on this basis no two people of differing faiths inherit from each other mutual inheritance by its nature means that each party inherits from the other in arabic this form is reciprocal and reciprocal action in the speech of the arabs requires two agents even though the simple act may proceed from one one says that two men struck one another when each struck his companion and that a man struck another when only one struck the other', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 79, NULL, 'Accordingly, the Jew does not inherit from the Christian, nor the Christian from the Jew; and the Christian, the Jew, and the Magian do not inherit from the Muslim. The Muslim, however, does inherit from them by virtue of kinship — as has come down from the Imams, may the prayers of Allah be upon them — and the disbelief of the non-Muslim relative does not bar the Muslim from that inheritance. The narration supporting this is sound: the polytheists do not inherit from the Muslims, while the Muslims do inherit from them. The two directions are not equal.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'accordingly the jew does not inherit from the christian nor the christian from the jew and the christian the jew and the magian do not inherit from the muslim the muslim however does inherit from them by virtue of kinship as has come down from the imams may the prayers of allah be upon them and the disbelief of the non muslim relative does not bar the muslim from that inheritance the narration supporting this is sound the polytheists do not inherit from the muslims while the muslims do inherit from them the two directions are not equal', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 80, NULL, 'Among themselves, the people of each faith inherit according to the fixed shares their own religion prescribes, and that is what is adjudicated between them. If they bring an inheritance dispute before the Muslim authorities, it is judged in accordance with what their own religion and faith prescribe. If they do not raise the matter to the Muslim authorities, they are left to themselves and not interfered with.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'among themselves the people of each faith inherit according to the fixed shares their own religion prescribes and that is what is adjudicated between them if they bring an inheritance dispute before the muslim authorities it is judged in accordance with what their own religion and faith prescribe if they do not raise the matter to the muslim authorities they are left to themselves and not interfered with', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 81, NULL, 'A bondservant does not inherit from a free person, nor does a free person inherit from a bondservant through kinship; the bondservant''s wealth belongs to his master. If a person embraces Islam after disbelief, or is freed from bondage, before the one from whom he would inherit has died and before the estate has been divided, he receives his share. If he is freed after the division, he receives nothing. All of this is the position of the Ahl al-Bayt, may the prayers of Allah be upon them all.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'a bondservant does not inherit from a free person nor does a free person inherit from a bondservant through kinship the bondservants wealth belongs to his master if a person embraces islam after disbelief or is freed from bondage before the one from whom he would inherit has died and before the estate has been divided he receives his share if he is freed after the division he receives nothing all of this is the position of the ahl al bayt may the prayers of allah be upon them all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 83, NULL, 'Further questions concern the fixed shares and the matter of one heir acknowledging another. Whoever kills another person — whether deliberately or by mistake — does not inherit from him, nor from his descendants, even if he would otherwise have been entitled to that inheritance. As for the parents, if they did not cause the death, they inherit from him according to the shares Allah, mighty and majestic, has fixed. A man inherits from his wife''s blood money, and a woman inherits from her husband''s blood money — with the exception of brothers through the mother, who take nothing from the blood money.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'further questions concern the fixed shares and the matter of one heir acknowledging another whoever kills another person whether deliberately or by mistake does not inherit from him nor from his descendants even if he would otherwise have been entitled to that inheritance as for the parents if they did not cause the death they inherit from him according to the shares allah mighty and majestic has fixed a man inherits from his wifes blood money and a woman inherits from her husbands blood money with the exception of brothers through the mother who take nothing from the blood money', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 84, NULL, 'The intersexed person is one who possesses both a male organ and a female organ. Such a person inherits and is inherited from, marries and is given in marriage, and is judged according to the passage of urine. If urine passes from the male organ, the person is a man: the rulings governing men apply to him, he marries women, no man may marry him, and he inherits and is inherited from according to a man''s share. If urine passes from the female organ, the rulings governing women apply: she follows the course of women in all things and the course of men in nothing. If urine passes from both organs, one looks to which it passes from first. If it precedes from the male organ, the ruling is that of men; if it precedes from the female organ, the ruling is that of women. If it passes from both at once, or if the person has neither organ, the matter is uncertain, and the judge determines it by lot. He writes on one card "the servant of Allah" and on another "the handmaid of Allah," sets each card inside a pellet of clay, turns them about in his hand, and says, "O Allah, You know best this naming and how You created it; so bring forth the lot."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the intersexed person is one who possesses both a male organ and a female organ such a person inherits and is inherited from marries and is given in marriage and is judged according to the passage of urine if urine passes from the male organ the person is a man the rulings governing men apply to him he marries women no man may marry him and he inherits and is inherited from according to a mans share if urine passes from the female organ the rulings governing women apply she follows the course of women in all things and the course of men in nothing if urine passes from both organs one looks to which it passes from first if it precedes from the male organ the ruling is that of men if it precedes from the female organ the ruling is that of women if it passes from both at once or if the person has neither organ the matter is uncertain and the judge determines it by lot he writes on one card the servant of allah and on another the handmaid of allah sets each card inside a pellet of clay turns them about in his hand and says o allah you know best this naming and how you created it so bring forth the lot', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 85, NULL, 'The lot is then drawn. The one casting it holds the piece in his hand and says: "O Allah, You know best about this person and how You created them, so bring out the arrow for the one You have made heir among them and the one You have appointed as ruler over the rulings." He then draws one of the two clay pieces, neither of which has been seen, and the contents of neither are known. Whatever emerges determines the ruling that is applied.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the lot is then drawn the one casting it holds the piece in his hand and says o allah you know best about this person and how you created them so bring out the arrow for the one you have made heir among them and the one you have appointed as ruler over the rulings he then draws one of the two clay pieces neither of which has been seen and the contents of neither are known whatever emerges determines the ruling that is applied', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 86, NULL, 'After this, the urine is examined. The person is made to stand facing a wall with both hands extended and is directed to step back from it as far as possible. If the urine reaches the wall, it is known to have issued from the male organ; if it runs down between the legs, it is known to have issued from the female organ. Neither men nor women look upon the person beforehand, so that no prior judgment is formed about what the person is before the test has been completed.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'after this the urine is examined the person is made to stand facing a wall with both hands extended and is directed to step back from it as far as possible if the urine reaches the wall it is known to have issued from the male organ if it runs down between the legs it is known to have issued from the female organ neither men nor women look upon the person beforehand so that no prior judgment is formed about what the person is before the test has been completed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 87, NULL, 'When a group of people perish together — drowned in a shipwreck, buried under a collapsed building, consumed by fire, or killed together in battle — and it cannot be determined which of them died before his companion, while they stood in a relationship of kinship to one another, each of them inherits from the other according to what he would have inherited, and the other inherits from him in turn according to his own portion. They inherit from one another whatever each has left behind.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'when a group of people perish together drowned in a shipwreck buried under a collapsed building consumed by fire or killed together in battle and it cannot be determined which of them died before his companion while they stood in a relationship of kinship to one another each of them inherits from the other according to what he would have inherited and the other inherits from him in turn according to his own portion they inherit from one another whatever each has left behind', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 88, NULL, 'An illustration of this is two brothers who die together in such a manner, one the freed client (mawla) of one people and the other the freed client of another, having no heir besides their respective patrons. One leaves a thousand dinars, the other a hundred. The owner of the hundred is treated as though he had remained alive and his brother had died before him, and his share of the thousand is taken accordingly; the owner of the thousand is treated in the same way, and his share of the hundred is taken on that basis. The result is that the patron of the one who left the thousand receives a hundred, and the patron of the one who left the hundred receives a thousand. In this manner the like of it proceeds: each patron inherits from his deceased client, is himself then inherited from in turn, and thereafter the heirs of each inherit from him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'an illustration of this is two brothers who die together in such a manner one the freed client mawla of one people and the other the freed client of another having no heir besides their respective patrons one leaves a thousand dinars the other a hundred the owner of the hundred is treated as though he had remained alive and his brother had died before him and his share of the thousand is taken accordingly the owner of the thousand is treated in the same way and his share of the hundred is taken on that basis the result is that the patron of the one who left the thousand receives a hundred and the patron of the one who left the hundred receives a thousand in this manner the like of it proceeds each patron inherits from his deceased client is himself then inherited from in turn and thereafter the heirs of each inherit from him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 89, NULL, 'As for a man who pronounces an irrevocable divorce upon his wife — one that leaves him no right of return — there is no inheritance between them. The one exception is a man who divorces his wife while he is ill: she inherits from him for as long as that same illness persists, unless he recovers or she remarries. Should he regain his health, or should she take another husband, her right to inherit from him is extinguished. As for a man who divorces his wife with a revocable divorce — one in which he retains the right of return — each inherits from the other, provided her waiting period has not yet expired.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'as for a man who pronounces an irrevocable divorce upon his wife one that leaves him no right of return there is no inheritance between them the one exception is a man who divorces his wife while he is ill she inherits from him for as long as that same illness persists unless he recovers or she remarries should he regain his health or should she take another husband her right to inherit from him is extinguished as for a man who divorces his wife with a revocable divorce one in which he retains the right of return each inherits from the other provided her waiting period has not yet expired', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 90, NULL, 'Whoever dies leaving no heir other than the patrons (mawali) who freed him — or those who became patrons through their agency — his inheritance belongs to those patrons. If he has a blood relative, however, the inheritance passes to that relative by right of kinship, not by right of patronage.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'whoever dies leaving no heir other than the patrons mawali who freed him or those who became patrons through their agency his inheritance belongs to those patrons if he has a blood relative however the inheritance passes to that relative by right of kinship not by right of patronage', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 91, NULL, 'The bond of patronage (al-wala) is inherited by men and women alike. Its closeness is established through the father who freed the slave, just as kinship among men is generally established through the father. Whoever stands nearer in the degree of patronage has the stronger claim over one who stands more remote — the same principle already noted regarding the one who frees a slave.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the bond of patronage al wala is inherited by men and women alike its closeness is established through the father who freed the slave just as kinship among men is generally established through the father whoever stands nearer in the degree of patronage has the stronger claim over one who stands more remote the same principle already noted regarding the one who frees a slave', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 92, NULL, 'The application runs as follows. A man frees a slave, and that freed man later dies leaving two sons. One of those sons dies, leaving a son of his own. The patron then dies with no close relative surviving him. His inheritance passes to the son of his patron''s son — who stands one degree nearer — rather than to the more remote son still living. The rule of inheritance by kinship follows the same logic.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the application runs as follows a man frees a slave and that freed man later dies leaving two sons one of those sons dies leaving a son of his own the patron then dies with no close relative surviving him his inheritance passes to the son of his patrons son who stands one degree nearer rather than to the more remote son still living the rule of inheritance by kinship follows the same logic', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 93, NULL, 'Whoever leaves no heir at the level of an inheritor except a slave he himself had freed is inherited by that freed slave, just as he would have inherited from the freed slave had their positions been reversed. If, however, he leaves both a slave he had freed and a patron who had freed him, his inheritance goes to the patron who freed him rather than to the slave whom he freed.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'whoever leaves no heir at the level of an inheritor except a slave he himself had freed is inherited by that freed slave just as he would have inherited from the freed slave had their positions been reversed if however he leaves both a slave he had freed and a patron who had freed him his inheritance goes to the patron who freed him rather than to the slave whom he freed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 94, NULL, 'When some heirs acknowledge a claimant whom the remaining heirs deny, and no attested proof establishes his standing, the one who is nearer inherits according to what he would have inherited. Those who acknowledge the claimant hand over to him whatever remains in excess of their own shares — that is, of what has come to them — while those who do not acknowledge him owe him nothing, and their own inheritance remains complete.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'when some heirs acknowledge a claimant whom the remaining heirs deny and no attested proof establishes his standing the one who is nearer inherits according to what he would have inherited those who acknowledge the claimant hand over to him whatever remains in excess of their own shares that is of what has come to them while those who do not acknowledge him owe him nothing and their own inheritance remains complete', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 95, NULL, 'An illustration is a man who dies leaving two sons. One of them acknowledges a third brother; the other denies him. The son who denies inherits one half from his father. The son who acknowledges inherits one third, and pays over one sixth to the one he has acknowledged, corresponding to what that one would have inherited had all three brothers shared the estate in equal thirds.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'an illustration is a man who dies leaving two sons one of them acknowledges a third brother the other denies him the son who denies inherits one half from his father the son who acknowledges inherits one third and pays over one sixth to the one he has acknowledged corresponding to what that one would have inherited had all three brothers shared the estate in equal thirds', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 96, NULL, 'The shroud of the deceased is drawn from the principal of the estate — from whatever he has left — before any division takes place. His debts, if any lie against him, are settled in the same way. A bequest, if he made one, is taken from a third of the estate or less; beyond that limit it cannot be carried out without the consent of the heirs, unless they choose to discharge it in full. Whatever remains is then divided according to the ordained obligations of inheritance.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'the shroud of the deceased is drawn from the principal of the estate from whatever he has left before any division takes place his debts if any lie against him are settled in the same way a bequest if he made one is taken from a third of the estate or less beyond that limit it cannot be carried out without the consent of the heirs unless they choose to discharge it in full whatever remains is then divided according to the ordained obligations of inheritance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 97, NULL, 'As for the mukatab — the slave bound by a written contract of manumission (kitabah) — and the one of whom only a part has been set free: such persons inherit and are inherited from in proportion to the degree of freedom they have attained, as has already been established. The ruling on the validity of the kitabah, and how the intention of manumission takes effect, has been set out in the chapter on the mukatab. Whoever has no known heir, his estate passes to the treasury of the Muslims.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'as for the mukatab the slave bound by a written contract of manumission kitabah and the one of whom only a part has been set free such persons inherit and are inherited from in proportion to the degree of freedom they have attained as has already been established the ruling on the validity of the kitabah and how the intention of manumission takes effect has been set out in the chapter on the mukatab whoever has no known heir his estate passes to the treasury of the muslims', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'freedom, generosity, and the division of estates', '8. Freedom, Generosity, and the Division of Estates', 98, NULL, 'If some of the heirs acknowledge a debt, each one who does so is bound to pay it from his own share of the inheritance, in proportion to what he has acknowledged. If he bears witness to it, being a man of upright standing, his testimony is admitted on behalf of all the heirs. If a man acknowledges a child borne by his slave-woman and his wife, and afterward disowns that child, the disavowal is not permitted: the child remains his son. All of this is the teaching of the Ahl al-Bayt, may the prayers of Allah be upon them all.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 8 freedom generosity and the division of estates', 'if some of the heirs acknowledge a debt each one who does so is bound to pay it from his own share of the inheritance in proportion to what he has acknowledged if he bears witness to it being a man of upright standing his testimony is admitted on behalf of all the heirs if a man acknowledges a child borne by his slave woman and his wife and afterward disowns that child the disavowal is not permitted the child remains his son all of this is the teaching of the ahl al bayt may the prayers of allah be upon them all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 0, NULL, 'Allah Almighty said: "And do not kill the soul which Allah has forbidden except by right, and whoever is killed unjustly — We have given his heir authority" (Al-Isra 33). And He said: "And whoever kills a believer intentionally, his recompense is Hell, wherein he will abide eternally, and Allah has become angry with him and has cursed him and has prepared for him a great punishment" (Al-Nisa 93). And He said: "O you who have believed, do not consume one another''s wealth unjustly but only in lawful business by mutual consent. And do not kill yourselves; indeed, Allah is to you ever Merciful. And whoever does that in aggression and injustice — then We will drive him into a Fire" (Al-Nisa 29-30). And He said: "Because of that, We decreed upon the Children of Israel that whoever kills a soul unless for a soul or for corruption in the land — it is as if he had slain all mankind entirely. And whoever saves one — it is as if he had saved all mankind entirely" (Al-Maidah 32).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'allah almighty said and do not kill the soul which allah has forbidden except by right and whoever is killed unjustly we have given his heir authority al isra 33 and he said and whoever kills a believer intentionally his recompense is hell wherein he will abide eternally and allah has become angry with him and has cursed him and has prepared for him a great punishment al nisa 93 and he said o you who have believed do not consume one anothers wealth unjustly but only in lawful business by mutual consent and do not kill yourselves indeed allah is to you ever merciful and whoever does that in aggression and injustice then we will drive him into a fire al nisa 29 30 and he said because of that we decreed upon the children of israel that whoever kills a soul unless for a soul or for corruption in the land it is as if he had slain all mankind entirely and whoever saves one it is as if he had saved all mankind entirely al maidah 32', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 1, NULL, 'The Messenger of Allah, peace be upon him and his family, said: "If the entire nation were to gather to kill a believer, Allah Almighty would cast them all into the Fire of Hell." He also said: "In Hell there is a valley called Sair; if that valley were opened, it would fill with fire — Allah has prepared it for murderers." And he said: "The deliberate murder of a believer is among the major sins." The son of Adam who killed his brother — Cain, who slew Abel — was the first to be killed unjustly.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the messenger of allah peace be upon him and his family said if the entire nation were to gather to kill a believer allah almighty would cast them all into the fire of hell he also said in hell there is a valley called sair if that valley were opened it would fill with fire allah has prepared it for murderers and he said the deliberate murder of a believer is among the major sins the son of adam who killed his brother cain who slew abel was the first to be killed unjustly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 2, NULL, 'The Messenger of Allah, peace be upon him, said that believers are equal in blood. A man is killed for killing a woman; and if he kills her and her guardians choose compensation rather than retribution, they receive half the blood money — five hundred dinars, half that of a man.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the messenger of allah peace be upon him said that believers are equal in blood a man is killed for killing a woman and if he kills her and her guardians choose compensation rather than retribution they receive half the blood money five hundred dinars half that of a man', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 3, NULL, 'When the heirs of a slain man are of differing condition — some present and some absent, some grown and some still children — the right of retribution belongs to those who have reached maturity. The killer is not held back until the young ones come of age, nor until the absent return. It was on this basis that al-Hasan ibn Ali, peace be upon him, put to death the enemy of Allah, Ibn Muljam — may Allah curse him — the man who struck Ali, peace be upon him, even though Ali''s own children had not yet reached puberty.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'when the heirs of a slain man are of differing condition some present and some absent some grown and some still children the right of retribution belongs to those who have reached maturity the killer is not held back until the young ones come of age nor until the absent return it was on this basis that al hasan ibn ali peace be upon him put to death the enemy of allah ibn muljam may allah curse him the man who struck ali peace be upon him even though alis own children had not yet reached puberty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 4, NULL, 'As for one who is slain, whether by an iron weapon or by any other means: if the killer intended his victim''s death and struck him deliberately with whatever he used, and the victim died from that blow, the guardians of the slain may demand retaliation. Retaliation, however, is carried out by no means other than the sword, for the Messenger of Allah, may God''s peace and blessings be upon him and his family, said: "There is no execution except by the sword" (لَا قَوَدَ إِلَّا بِحَدِيدَةٍ). The condemned is to be struck upon the neck with the sword; he is neither to be tortured nor to be mutilated.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'as for one who is slain whether by an iron weapon or by any other means if the killer intended his victims death and struck him deliberately with whatever he used and the victim died from that blow the guardians of the slain may demand retaliation retaliation however is carried out by no means other than the sword for the messenger of allah may gods peace and blessings be upon him and his family said there is no execution except by the sword لا قود الا بحديده the condemned is to be struck upon the neck with the sword he is neither to be tortured nor to be mutilated', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 5, NULL, 'The accused may be questioned and his confession drawn out by gentle means, but not by beating. A confession extracted under compulsion carries no legal force and does not bind him. If, however, two upright witnesses testify that he committed the killing, or if he confesses freely and of his own will, the killing is established against him. The testimony of women is not admitted in cases of bloodshed, nor in any of the prescribed punishments (hudud) or in retaliation (qisas), though it is admitted in matters where wealth is owed.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the accused may be questioned and his confession drawn out by gentle means but not by beating a confession extracted under compulsion carries no legal force and does not bind him if however two upright witnesses testify that he committed the killing or if he confesses freely and of his own will the killing is established against him the testimony of women is not admitted in cases of bloodshed nor in any of the prescribed punishments hudud or in retaliation qisas though it is admitted in matters where wealth is owed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 6, NULL, 'When a single man is slain by two people, or by a group who acted together against him — each of them striking him until he died from their combined blows — the guardians of the slain may single out one of those killers and put him to death for their kinsman, for Allah Almighty has said: "A soul for a soul" (النَّفْسَ بِالنَّفْسِ). They may not put more than one man to death in return for one. They then turn to the remaining killers and take from each of them blood money proportionate to his share:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'when a single man is slain by two people or by a group who acted together against him each of them striking him until he died from their combined blows the guardians of the slain may single out one of those killers and put him to death for their kinsman for allah almighty has said a soul for a soul النفس بالنفس they may not put more than one man to death in return for one they then turn to the remaining killers and take from each of them blood money proportionate to his share', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 7, NULL, 'If there were three killers and one was executed, his guardians take two-thirds of the blood money from the remaining two. If there were two killers and one was executed, his guardians take half the blood money from the other. If there were more than three, the shares are reckoned accordingly.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'if there were three killers and one was executed his guardians take two thirds of the blood money from the remaining two if there were two killers and one was executed his guardians take half the blood money from the other if there were more than three the shares are reckoned accordingly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 8, NULL, 'In every such case, those who were not executed are further subjected to a disciplinary punishment.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'in every such case those who were not executed are further subjected to a disciplinary punishment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 9, NULL, 'If one man restrains another while a third kills him, the killer is put to death and the one who held the victim is imprisoned until he dies, having first been flogged. If a man kills his own slave, he receives a severe punishment. If the victim''s guardians pardon the killer, no further claim lies against him, and whoever kills him after that pardon is himself put to death in retaliation. Likewise, if the guardians accept blood money, they are entitled to nothing beyond it, for Allah Almighty has said: "And whoever transgresses after that, for him is a painful punishment" (فَمَنِ اعْتَدَى بَعْدَ ذَلِكَ فَلَهُ عَذَابٌ أَلِيمٌ).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'if one man restrains another while a third kills him the killer is put to death and the one who held the victim is imprisoned until he dies having first been flogged if a man kills his own slave he receives a severe punishment if the victims guardians pardon the killer no further claim lies against him and whoever kills him after that pardon is himself put to death in retaliation likewise if the guardians accept blood money they are entitled to nothing beyond it for allah almighty has said and whoever transgresses after that for him is a painful punishment فمن اعتدي بعد ذلك فله عذاب اليم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 10, NULL, 'Every wound for which retaliation can be carried out without risk of excess and without harm to the one from whom it is taken — such as the surface wound (al-mudihah) and what lies below it — is subject to retaliation. The wound is measured along its length upon the skin, a mark is set, and the one taking retaliation cuts at the corresponding place to the same length and to the same depth in the flesh.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'every wound for which retaliation can be carried out without risk of excess and without harm to the one from whom it is taken such as the surface wound al mudihah and what lies below it is subject to retaliation the wound is measured along its length upon the skin a mark is set and the one taking retaliation cuts at the corresponding place to the same length and to the same depth in the flesh', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 11, NULL, 'Retaliation likewise extends to a tooth for a tooth, an eye for an eye, a nose for a nose, an ear for an ear, and to whatever portion of these has been severed — in accordance with the word of Allah Almighty: "And the eye for the eye, and the nose for the nose, and the ear for the ear, and the tooth for the tooth, and for wounds is retaliation" (وَالْعَيْنَ بِالْعَيْنِ وَالْأَنْفَ بِالْأَنْفِ وَالْأُذُنَ بِالْأُذُنِ وَالسِّنَّ بِالسِّنِّ وَالْجُرُوحَ قِصَاصٌ). This applies when the act was deliberate. Where the wound was inflicted in error, however, or where its nature is such that retaliation would risk further harm to the offender, or where the wound has dried and healed, or where a bone has been broken, or where the injury is graver than the surface wound — in all such cases blood money is owed, and its rules will be set out in their proper place. One who inflicts such wounds deliberately is also subject to punishment, so that a man of means does not find it a simple matter to wound and merely pay the blood money in discharge.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'retaliation likewise extends to a tooth for a tooth an eye for an eye a nose for a nose an ear for an ear and to whatever portion of these has been severed in accordance with the word of allah almighty and the eye for the eye and the nose for the nose and the ear for the ear and the tooth for the tooth and for wounds is retaliation والعين بالعين والانف بالانف والاذن بالاذن والسن بالسن والجروح قصاص this applies when the act was deliberate where the wound was inflicted in error however or where its nature is such that retaliation would risk further harm to the offender or where the wound has dried and healed or where a bone has been broken or where the injury is graver than the surface wound in all such cases blood money is owed and its rules will be set out in their proper place one who inflicts such wounds deliberately is also subject to punishment so that a man of means does not find it a simple matter to wound and merely pay the blood money in discharge', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 12, NULL, 'In wounds, retaliation is taken from a woman for a man and from a man for a woman in respect of the surface wound and what lies below it. As for retaliation in the eye: the eye not subject to retaliation is bound, an iron or a mirror is heated and brought close to the eye from which retaliation is to be taken, and that eye is held open until it flows. All of this is the teaching of the Ahl al-Bayt, may the prayers of Allah be upon them all.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'in wounds retaliation is taken from a woman for a man and from a man for a woman in respect of the surface wound and what lies below it as for retaliation in the eye the eye not subject to retaliation is bound an iron or a mirror is heated and brought close to the eye from which retaliation is to be taken and that eye is held open until it flows all of this is the teaching of the ahl al bayt may the prayers of allah be upon them all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 14, NULL, 'The blood money for a free Muslim man — whether young or old — is one thousand dinars, owed by those who deal in gold, or its equivalent value from people whose wealth takes another form. They are not compelled to sell their possessions in order to pay in gold; rather, the equivalent of one thousand dinars is taken from them in the currency of their land:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the blood money for a free muslim man whether young or old is one thousand dinars owed by those who deal in gold or its equivalent value from people whose wealth takes another form they are not compelled to sell their possessions in order to pay in gold rather the equivalent of one thousand dinars is taken from them in the currency of their land', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 15, NULL, 'from the people of silver: the value of one thousand dinars in silver from the people of camels: one hundred camels from the people of cattle: two hundred cows from the people of sheep: one thousand sheep from the people of cloth: two hundred garments of like value', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'from the people of silver the value of one thousand dinars in silver from the people of camels one hundred camels from the people of cattle two hundred cows from the people of sheep one thousand sheep from the people of cloth two hundred garments of like value', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 16, NULL, 'This is how the Sunnah has run, and this is the blood money for the soul.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'this is how the sunnah has run and this is the blood money for the soul', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 17, NULL, 'Blood money is owed only in cases of error — that is, where the killer did not intend the death of the one he killed, as when he meant to strike another and hit this man instead. If, however, he acted deliberately with whatever he used, that is intentional killing, and he is subject to retaliation, unless the guardians of the slain accept blood money from him or pardon him altogether. The one who killed in error must, after paying the blood money, expiate his act by freeing a believing slave; if he cannot find one, then by fasting two consecutive months; and if he is unable to do that, then by feeding sixty poor persons.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'blood money is owed only in cases of error that is where the killer did not intend the death of the one he killed as when he meant to strike another and hit this man instead if however he acted deliberately with whatever he used that is intentional killing and he is subject to retaliation unless the guardians of the slain accept blood money from him or pardon him altogether the one who killed in error must after paying the blood money expiate his act by freeing a believing slave if he cannot find one then by fasting two consecutive months and if he is unable to do that then by feeding sixty poor persons', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 18, NULL, 'The blood money is borne by the aqila — the heirs who would inherit from the offender were he to die — with the exception of his maternal aunts, who neither carry this responsibility nor receive any share of the blood money. The deliberate acts of children and of the insane are treated as error, and their blood money likewise falls upon the aqila; yet nothing is laid upon those among the aqila who are poor, nor upon anyone who possesses nothing. The aqila is not bound except where liability is established through clear evidence. Where a person of good standing confesses and acts upon that confession, or where the matter concerns a slave, the aqila bears nothing. Nor does the aqila bear unintentional offenses unless the amount reaches one third of the full blood money or more; whatever falls below that third is paid from the offender''s own wealth. As for the people of the dhimma, whatever they incur comes from their own wealth, and their aqila bears none of it. Whoever offends alone bears the consequence alone.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the blood money is borne by the aqila the heirs who would inherit from the offender were he to die with the exception of his maternal aunts who neither carry this responsibility nor receive any share of the blood money the deliberate acts of children and of the insane are treated as error and their blood money likewise falls upon the aqila yet nothing is laid upon those among the aqila who are poor nor upon anyone who possesses nothing the aqila is not bound except where liability is established through clear evidence where a person of good standing confesses and acts upon that confession or where the matter concerns a slave the aqila bears nothing nor does the aqila bear unintentional offenses unless the amount reaches one third of the full blood money or more whatever falls below that third is paid from the offenders own wealth as for the people of the dhimma whatever they incur comes from their own wealth and their aqila bears none of it whoever offends alone bears the consequence alone', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 19, NULL, 'Whoever strikes a pregnant woman so that she expels the seed after it has settled in the womb owes twenty dinars. If she expels a clot — that is, the blood (عَلَقَة) — the liability is forty dinars. For the morsel of flesh (مُضْغَة), once it has taken on the form of flesh, the amount is sixty dinars. If bone has formed within it, eighty dinars are due. If she expels a fully formed child before the spirit has been breathed into it, the liability is one hundred dinars; and once the spirit has been breathed into it, the full blood money is due.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whoever strikes a pregnant woman so that she expels the seed after it has settled in the womb owes twenty dinars if she expels a clot that is the blood علقه the liability is forty dinars for the morsel of flesh مضغه once it has taken on the form of flesh the amount is sixty dinars if bone has formed within it eighty dinars are due if she expels a fully formed child before the spirit has been breathed into it the liability is one hundred dinars and once the spirit has been breathed into it the full blood money is due', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 20, NULL, 'Whoever offends against one already dead — severing his head, or doing to him what would have killed him had he been alive — owes one hundred dinars. For any wound or injury done to him, the offender owes the proportionate share of his blood money. That sum is spent on his behalf in works of piety; the Hajj is performed for him if he had not yet performed it; and his heirs inherit none of it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whoever offends against one already dead severing his head or doing to him what would have killed him had he been alive owes one hundred dinars for any wound or injury done to him the offender owes the proportionate share of his blood money that sum is spent on his behalf in works of piety the hajj is performed for him if he had not yet performed it and his heirs inherit none of it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 21, NULL, 'Offenses against beasts are reckoned by their value. Whoever kills a beast is fined its worth. Whoever wounds it or breaks one of its limbs owes the amount by which its value has diminished. If a beast breaks loose and causes harm, that harm is without redress — and likewise if one enters upon it in its own place. But if its owners loose it, or station it where they have no right to do so, they are answerable for whatever harm it causes.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'offenses against beasts are reckoned by their value whoever kills a beast is fined its worth whoever wounds it or breaks one of its limbs owes the amount by which its value has diminished if a beast breaks loose and causes harm that harm is without redress and likewise if one enters upon it in its own place but if its owners loose it or station it where they have no right to do so they are answerable for whatever harm it causes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 22, NULL, 'When a thief seeks a man''s wealth and fights him, and the man so threatened kills the thief, the thief''s blood is forfeit. Whoever is slain in defense of his wealth dies a martyr; and if he yields his wealth without fighting for it, no blame rests upon him. Whoever seeks to overcome a woman against her will, and she repels him and kills or wounds him in doing so, whatever she inflicts is without redress. Whoever dies under a prescribed punishment (hadd) or under lawful retaliation, no claim arises on his behalf. Whoever peers into the private quarters of a people and they put out his eye, his claim is forfeit.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'when a thief seeks a mans wealth and fights him and the man so threatened kills the thief the thiefs blood is forfeit whoever is slain in defense of his wealth dies a martyr and if he yields his wealth without fighting for it no blame rests upon him whoever seeks to overcome a woman against her will and she repels him and kills or wounds him in doing so whatever she inflicts is without redress whoever dies under a prescribed punishment hadd or under lawful retaliation no claim arises on his behalf whoever peers into the private quarters of a people and they put out his eye his claim is forfeit', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 23, NULL, 'The Messenger of Allah ruled by al-Qasamah, which applies when a man is killed and his killer is unknown. If, before he dies, the slain man says, "So-and-so killed me," or if his guardians come forward bearing a mark of accusation against the one they charge with his death — declaring, "He killed him" — then fifty men among them swear oaths that he killed him, and the accused is handed over to them. If they do not number fifty, those present repeat their oaths until fifty oaths are completed. If they prefer, they may have the accused swear oaths instead. And if the accused bring proof of their innocence, it is accepted from them.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the messenger of allah ruled by al qasamah which applies when a man is killed and his killer is unknown if before he dies the slain man says so and so killed me or if his guardians come forward bearing a mark of accusation against the one they charge with his death declaring he killed him then fifty men among them swear oaths that he killed him and the accused is handed over to them if they do not number fifty those present repeat their oaths until fifty oaths are completed if they prefer they may have the accused swear oaths instead and if the accused bring proof of their innocence it is accepted from them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 24, NULL, 'When a slain man is found in a village and it is not known who killed him, and its people are the people of that one village with no others mixing among them, they swear that they did not kill him and do not know his killer, and they are then made to pay his blood money. If he is found between two villages, the responsibility falls upon whichever of them is nearer to the place where he lay. But if the place where he was struck down is a great city, or a village in which all manner of people mix, or a road along which travelers pass between villages, then the burden of proof falls upon whoever is accused — provided no mark of accusation is found against them — and al-Qasamah is established.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'when a slain man is found in a village and it is not known who killed him and its people are the people of that one village with no others mixing among them they swear that they did not kill him and do not know his killer and they are then made to pay his blood money if he is found between two villages the responsibility falls upon whichever of them is nearer to the place where he lay but if the place where he was struck down is a great city or a village in which all manner of people mix or a road along which travelers pass between villages then the burden of proof falls upon whoever is accused provided no mark of accusation is found against them and al qasamah is established', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 25, NULL, 'If two horsemen ride toward each other and collide, and one of them dies, half the blood money is due — for his death resulted from his own action combined with that of his companion. If only one of them was moving while the other stood still or walked, and the one who charged was killed, nothing is owed by the one who stood still. But if the one who was struck died, the full blood money falls upon the one who charged, provided he did not intend it; if he did intend it, retaliation is due from him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'if two horsemen ride toward each other and collide and one of them dies half the blood money is due for his death resulted from his own action combined with that of his companion if only one of them was moving while the other stood still or walked and the one who charged was killed nothing is owed by the one who stood still but if the one who was struck died the full blood money falls upon the one who charged provided he did not intend it if he did intend it retaliation is due from him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 26, NULL, 'A physician or veterinarian is answerable for harm caused by ignorance of their craft; and if they were knowledgeable yet intended harm, they are answerable on that ground as well. A circumciser is answerable for whatever flesh he cuts beyond the proper place of cutting, and a woman who performs the equivalent procedure on girls is held to the same standard when she exceeds the proper limit. Whoever digs a well or pit in a public road, or places an obstruction in it, is answerable for whatever harm results; but if the road lies within his own property, nothing is owed.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'a physician or veterinarian is answerable for harm caused by ignorance of their craft and if they were knowledgeable yet intended harm they are answerable on that ground as well a circumciser is answerable for whatever flesh he cuts beyond the proper place of cutting and a woman who performs the equivalent procedure on girls is held to the same standard when she exceeds the proper limit whoever digs a well or pit in a public road or places an obstruction in it is answerable for whatever harm results but if the road lies within his own property nothing is owed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 27, NULL, 'A rider is answerable for whatever his mount strikes with its foreleg or chest, but not for what it strikes with its hind leg, since that is beyond his control. When a wall begins to lean and its owner is made aware of it — whether he discovers this himself or is informed — yet he neither rights it nor pulls it down, and it falls, he is answerable for whatever damage it causes. When a man hires a laborer who then dies in the course of his work, nothing is owed on account of that death. When a dog is kept within someone''s dwelling or within their property, and a person enters without their permission and is bitten, nothing falls upon them; but if they granted him leave to enter, they are answerable.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'a rider is answerable for whatever his mount strikes with its foreleg or chest but not for what it strikes with its hind leg since that is beyond his control when a wall begins to lean and its owner is made aware of it whether he discovers this himself or is informed yet he neither rights it nor pulls it down and it falls he is answerable for whatever damage it causes when a man hires a laborer who then dies in the course of his work nothing is owed on account of that death when a dog is kept within someones dwelling or within their property and a person enters without their permission and is bitten nothing falls upon them but if they granted him leave to enter they are answerable', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 28, NULL, 'When a woman severs a man''s organ, or a man severs a woman''s part, there is no retaliation between them, for the offense has no true like that can be taken from the offender. Instead, the full blood money falls upon him, and if he acted deliberately, he is severely punished. When a man forces himself upon a woman who is not fit to be approached in that way, or uses violence against her and tears her — leaving her unable to bear children, or causing her to lose control of her water or her bowels, or killing her outright — the full blood money is upon him in every one of these cases. Whoever is found dead bearing no mark of injury, and it is not known that anyone killed him, nothing is owed on his account beyond the oath of the one accused of the killing. All of this is the teaching of the Ahl al-Bayt, may the prayers of Allah be upon them.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'when a woman severs a mans organ or a man severs a womans part there is no retaliation between them for the offense has no true like that can be taken from the offender instead the full blood money falls upon him and if he acted deliberately he is severely punished when a man forces himself upon a woman who is not fit to be approached in that way or uses violence against her and tears her leaving her unable to bear children or causing her to lose control of her water or her bowels or killing her outright the full blood money is upon him in every one of these cases whoever is found dead bearing no mark of injury and it is not known that anyone killed him nothing is owed on his account beyond the oath of the one accused of the killing all of this is the teaching of the ahl al bayt may the prayers of allah be upon them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 30, NULL, 'It has been established that retaliation is taken for a deliberate act in every case where it can be reached exactly, where excess in its execution is guarded against, and where no harm to the offender is feared in the taking of it. Where true retaliation cannot be achieved, however, or where the safety of the offender cannot be assured, the blood money falls upon the offender if the act was deliberate, and upon the aqila if it was done in error.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'it has been established that retaliation is taken for a deliberate act in every case where it can be reached exactly where excess in its execution is guarded against and where no harm to the offender is feared in the taking of it where true retaliation cannot be achieved however or where the safety of the offender cannot be assured the blood money falls upon the offender if the act was deliberate and upon the aqila if it was done in error', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 31, NULL, 'For every part of the body of which a person has only one, the full blood money is owed. For every part of which there are two, half the blood money is owed for each.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'for every part of the body of which a person has only one the full blood money is owed for every part of which there are two half the blood money is owed for each', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 32, NULL, 'For the hair of the head — if it is plucked, falls out as a result of injury, or is burned and does not grow back — the full blood money is owed. The same applies to the skin of the head if it is flayed. If the forehead is struck and the bone is reset, one hundred dinars are owed. If the nose or the tongue is severed, or an offense is committed against the beard such that it does not grow back, the full blood money is owed in each of these cases.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'for the hair of the head if it is plucked falls out as a result of injury or is burned and does not grow back the full blood money is owed the same applies to the skin of the head if it is flayed if the forehead is struck and the bone is reset one hundred dinars are owed if the nose or the tongue is severed or an offense is committed against the beard such that it does not grow back the full blood money is owed in each of these cases', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 33, NULL, 'For each of the following, half the blood money is owed individually, and the full blood money when both are taken together:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'for each of the following half the blood money is owed individually and the full blood money when both are taken together', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 34, NULL, 'the eyebrow the eye the ear the hand the foot one of the two organs of generation', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the eyebrow the eye the ear the hand the foot one of the two organs of generation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 35, NULL, 'For the eye of a one-eyed man, the full blood money is owed. For hearing, if it is lost entirely, the full blood money is owed. For speech, if it is lost entirely, the full blood money is owed. For sight, the full blood money is owed even when the pupils themselves remain intact.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'for the eye of a one eyed man the full blood money is owed for hearing if it is lost entirely the full blood money is owed for speech if it is lost entirely the full blood money is owed for sight the full blood money is owed even when the pupils themselves remain intact', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 36, NULL, 'For any partial diminishment of these faculties or members, the compensation is reckoned in proportion to what has been lost.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'for any partial diminishment of these faculties or members the compensation is reckoned in proportion to what has been lost', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 37, NULL, 'When a man strikes another and causes a partial loss of sight in one eye, the following procedure determines the compensation owed. The sound eye is covered and the injured eye left open. An egg is emptied of its contents and hung by a hair. The injured man is asked to look at it, and it is drawn away from him until he says he can no longer see the hair. That point is marked. The measurement is then taken — without the injured man knowing what is being measured — and repeated from four directions. If all four measurements agree, his truthfulness is established.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'when a man strikes another and causes a partial loss of sight in one eye the following procedure determines the compensation owed the sound eye is covered and the injured eye left open an egg is emptied of its contents and hung by a hair the injured man is asked to look at it and it is drawn away from him until he says he can no longer see the hair that point is marked the measurement is then taken without the injured man knowing what is being measured and repeated from four directions if all four measurements agree his truthfulness is established', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 38, NULL, 'The process is then reversed: the injured eye is covered and the sound eye left open, and the same procedure is carried out again from four directions. If that account agrees as well, the matter is settled. If it does not, he is told:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the process is then reversed the injured eye is covered and the sound eye left open and the same procedure is carried out again from four directions if that account agrees as well the matter is settled if it does not he is told', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 39, NULL, '"You have lied; return to the truth."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'you have lied return to the truth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 40, NULL, 'If his account holds consistent across all four directions for both eyes, the examiner compares what the injured eye has lost against what the sound eye sees. The blood money is awarded in proportion to that loss:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'if his account holds consistent across all four directions for both eyes the examiner compares what the injured eye has lost against what the sound eye sees the blood money is awarded in proportion to that loss', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 41, NULL, 'If the injured eye has lost half its sight, half the blood money is due. If it has lost a third, a third is due. Whatever fraction has been lost — whether greater or smaller — the compensation is reckoned accordingly.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'if the injured eye has lost half its sight half the blood money is due if it has lost a third a third is due whatever fraction has been lost whether greater or smaller the compensation is reckoned accordingly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 42, NULL, 'Where the loss of sight affects both eyes together, the injured man is measured against the sight of an upright man of middling vision — then against two such men, then three. When they agree, or come near to agreement, his own sight is tested against that standard from all four directions, as already described. When the measurements are consistent and his truthfulness is established, he receives blood money in proportion to what has been lost, as set out above.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'where the loss of sight affects both eyes together the injured man is measured against the sight of an upright man of middling vision then against two such men then three when they agree or come near to agreement his own sight is tested against that standard from all four directions as already described when the measurements are consistent and his truthfulness is established he receives blood money in proportion to what has been lost as set out above', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 43, NULL, 'Where the loss is in hearing, the same procedure applies: a dirham is struck near him until he says, "I do not hear it," and he is then measured by the same method described for the eyes — whether the injury is to one ear or to both.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'where the loss is in hearing the same procedure applies a dirham is struck near him until he says i do not hear it and he is then measured by the same method described for the eyes whether the injury is to one ear or to both', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 44, NULL, 'Where the loss is in the sense of smell, something bearing a scent is brought close and then drawn away by the same reckoning used for sight and hearing, and he is compensated according to his share of the loss.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'where the loss is in the sense of smell something bearing a scent is brought close and then drawn away by the same reckoning used for sight and hearing and he is compensated according to his share of the loss', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 45, NULL, 'Where the loss is in speech, what has fallen away is measured against the full count of the letters.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'where the loss is in speech what has fallen away is measured against the full count of the letters', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 46, NULL, 'Speech injuries are assessed against the full Arabic alphabet, which numbers twenty-eight letters; blood money is owed in proportion to the letters lost. For the lips, half the blood money is due for the upper lip and two-thirds for the lower — that is, a half and a sixth — reckoned by its role in eating and in the softness of speech.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'speech injuries are assessed against the full arabic alphabet which numbers twenty eight letters blood money is owed in proportion to the letters lost for the lips half the blood money is due for the upper lip and two thirds for the lower that is a half and a sixth reckoned by its role in eating and in the softness of speech', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 47, NULL, 'For the teeth, the assessment divides by position:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'for the teeth the assessment divides by position', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 48, NULL, 'Front teeth — four incisors, four lateral incisors, and four canines — each carries fifty dinars. Back teeth — the molars — each carries twenty-five dinars, and together they complete the full blood money.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'front teeth four incisors four lateral incisors and four canines each carries fifty dinars back teeth the molars each carries twenty five dinars and together they complete the full blood money', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 49, NULL, 'The molars number four in each jaw, four above and four below, making up the complete count of teeth as natural creation intends. Some people have five molars in each jaw, the fifth being superfluous. Blood money is apportioned according to the perfect original count, and whatever is lost — superfluous or not — carries twenty-five dinars per tooth.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the molars number four in each jaw four above and four below making up the complete count of teeth as natural creation intends some people have five molars in each jaw the fifth being superfluous blood money is apportioned according to the perfect original count and whatever is lost superfluous or not carries twenty five dinars per tooth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 50, NULL, 'If part of a tooth is broken, blood money is owed in proportion to the portion broken. If a tooth turns black, its full blood money is due, for it has been ruined.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'if part of a tooth is broken blood money is owed in proportion to the portion broken if a tooth turns black its full blood money is due for it has been ruined', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 51, NULL, 'For a child''s tooth knocked out before its natural time to fall: ten dinars are owed for an incisor and five for a molar, provided it grows back afterward. If it does not grow back, the full blood money for that tooth is due.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'for a childs tooth knocked out before its natural time to fall ten dinars are owed for an incisor and five for a molar provided it grows back afterward if it does not grow back the full blood money for that tooth is due', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 52, NULL, 'For the shoulder, the upper arm, and the elbow: if any one of them is broken or dislocated and then heals without defect, one hundred dinars are owed for each. For the forearm and the wrist, one-third of the blood money applies to each. For every finger of the hands and the feet, one hundred dinars. For the shoulder blade, forty dinars. For the ribs joined to the chest, twenty-five dinars per rib; for the ribs not joined to it and not meeting the breastbone, ten dinars per rib. For the hip, the thigh, and the knee, one-fifth of the blood money for each. For the jaifa — a blow that penetrates into the inner cavity of the body — one-third of the blood money is due. For a blow to the face that leaves it red without drawing blood and without turning black or green, two and a half dinars; if it turns black or green, three dinars. If the blow falls around the eye and turns it green, three dinars are owed; if it turns black, six dinars.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'for the shoulder the upper arm and the elbow if any one of them is broken or dislocated and then heals without defect one hundred dinars are owed for each for the forearm and the wrist one third of the blood money applies to each for every finger of the hands and the feet one hundred dinars for the shoulder blade forty dinars for the ribs joined to the chest twenty five dinars per rib for the ribs not joined to it and not meeting the breastbone ten dinars per rib for the hip the thigh and the knee one fifth of the blood money for each for the jaifa a blow that penetrates into the inner cavity of the body one third of the blood money is due for a blow to the face that leaves it red without drawing blood and without turning black or green two and a half dinars if it turns black or green three dinars if the blow falls around the eye and turns it green three dinars are owed if it turns black six dinars', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 53, NULL, 'For the damiya — the wound from which blood flows — ten dinars are owed. For the faqira, which breaks the skin and reaches the flesh without cutting into it, twelve dinars. For the badia, which cuts the skin and enters the flesh, severing part of it, twenty dinars. For the mutalahima, which cuts deep into the flesh, thirty dinars. For the mishaq — also called the miltat — which cuts through the skin and all the flesh down to the membrane over the bone without cutting that membrane, forty dinars. For the mudiha, which cuts through all of that and lays the bone bare, fifty dinars. For the hashima, which does all of that and breaks the bone, one hundred dinars. For the munaqqila, which breaks the bone and draws out a fragment of it, one hundred and fifty dinars. For the mamuma, in which the membrane of the brain becomes visible and is reached without any injury beyond it, one-third of the blood money is due.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'for the damiya the wound from which blood flows ten dinars are owed for the faqira which breaks the skin and reaches the flesh without cutting into it twelve dinars for the badia which cuts the skin and enters the flesh severing part of it twenty dinars for the mutalahima which cuts deep into the flesh thirty dinars for the mishaq also called the miltat which cuts through the skin and all the flesh down to the membrane over the bone without cutting that membrane forty dinars for the mudiha which cuts through all of that and lays the bone bare fifty dinars for the hashima which does all of that and breaks the bone one hundred dinars for the munaqqila which breaks the bone and draws out a fragment of it one hundred and fifty dinars for the mamuma in which the membrane of the brain becomes visible and is reached without any injury beyond it one third of the blood money is due', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 54, NULL, 'All of this applies to wounds of the head and face. For wounds to the rest of the body, half these amounts apply. Where a limb is injured — the fingers and the like — blood money is owed in proportion to that limb''s share of the full blood money, as already set out. All of this is the teaching of the Ahl al-Bayt, may.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'all of this applies to wounds of the head and face for wounds to the rest of the body half these amounts apply where a limb is injured the fingers and the like blood money is owed in proportion to that limbs share of the full blood money as already set out all of this is the teaching of the ahl al bayt may', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 56, NULL, 'At-Talaq: 1يَٓأَيُّهَا ٱلنَّبِىُّ إِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا۟ ٱلْعِدَّةَ', '', 'يَٓأَيُّهَا ٱلنَّبِىُّ إِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا۟ ٱلْعِدَّةَ', 'At-Talaq: 1', 65, 1, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'at talaq 1يايها النبي اذا طلقتم النساء فطلقوهن لعدتهن واحصوا العده', 'يايها النبي اذا طلقتم النساء فطلقوهن لعدتهن واحصوا العده');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 57, NULL, 'Allah, Mighty and Majestic, has said: "And whoever transgresses the limits of Allah has wronged himself." (Surah al-Talaq, 65:1)', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'allah mighty and majestic has said and whoever transgresses the limits of allah has wronged himself surah al talaq 65 1', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 58, NULL, 'The Messenger of Allah, may Allah bless him and his family and grant them peace, forbade the neglect of the prescribed limits. He said: "The Children of Israel perished only because, when a man of noble standing among them committed an offense that incurred a limit, they would not carry it out against him, but when a lowly man committed it, they would establish it upon him."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the messenger of allah may allah bless him and his family and grant them peace forbade the neglect of the prescribed limits he said the children of israel perished only because when a man of noble standing among them committed an offense that incurred a limit they would not carry it out against him but when a lowly man committed it they would establish it upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 59, NULL, 'A woman of Quraysh stole a garment during the time of the Messenger of Allah, may Allah bless him and his family, and he ordered her hand to be cut off. A group of Quraysh came to him and said: "O Messenger of Allah, she is a woman of ours who holds honor among her people, and what she has stolen is a trifle."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'a woman of quraysh stole a garment during the time of the messenger of allah may allah bless him and his family and he ordered her hand to be cut off a group of quraysh came to him and said o messenger of allah she is a woman of ours who holds honor among her people and what she has stolen is a trifle', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 60, NULL, 'The Messenger of Allah said: "It was by the like of this that those before you were destroyed: they would establish the limit upon their weak and leave their strong and their nobles, and so they perished."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the messenger of allah said it was by the like of this that those before you were destroyed they would establish the limit upon their weak and leave their strong and their nobles and so they perished', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 61, NULL, 'The Prophet, may Allah bless him and his family, also forbade intercession in the prescribed limits, declaring: "Whoever intercedes to nullify one of the limits of Allah has been insolent toward Allah and has striven to undo His limits; and whoever is insolent toward Allah and strives to undo His limits, Allah, Mighty and Majestic, will punish him on the Day of Resurrection." Safwan ibn Umayyah brought before the Messenger of Allah, may Allah bless him and his family, a man who had stolen a cloak of his, and the Messenger of Allah ordered the man''s hand to be cut off. Safwan said: "O Messenger of Allah, is his hand to be cut off for the sake of a cloak? I have given it to him." The Messenger of Allah replied: "Why was that not before you brought him to me? Once the limit has been raised to the ruler, it is not fitting for him to leave it unenforced." And he gave the order, and the hand was cut off.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the prophet may allah bless him and his family also forbade intercession in the prescribed limits declaring whoever intercedes to nullify one of the limits of allah has been insolent toward allah and has striven to undo his limits and whoever is insolent toward allah and strives to undo his limits allah mighty and majestic will punish him on the day of resurrection safwan ibn umayyah brought before the messenger of allah may allah bless him and his family a man who had stolen a cloak of his and the messenger of allah ordered the mans hand to be cut off safwan said o messenger of allah is his hand to be cut off for the sake of a cloak i have given it to him the messenger of allah replied why was that not before you brought him to me once the limit has been raised to the ruler it is not fitting for him to leave it unenforced and he gave the order and the hand was cut off', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 62, NULL, 'At-Talaq: 1يَٓأَيُّهَا ٱلنَّبِىُّ إِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا۟ ٱلْعِدَّةَ', '', 'يَٓأَيُّهَا ٱلنَّبِىُّ إِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا۟ ٱلْعِدَّةَ', 'At-Talaq: 1', 65, 1, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'at talaq 1يايها النبي اذا طلقتم النساء فطلقوهن لعدتهن واحصوا العده', 'يايها النبي اذا طلقتم النساء فطلقوهن لعدتهن واحصوا العده');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 63, NULL, 'It is related from him, may Allah bless him and his family, that he said: "The back of the believer is inviolable, except for a limit that is due." He forbade anyone from exceeding one of the limits of Allah, whether by falling short or by going beyond what has been prescribed, and he said: "Allah, Mighty and Majestic, has made the limits clear, so whoever transgresses them has wronged himself, as He, exalted be His remembrance, has said." And he set a limit upon whoever transgresses a limit. He, may Allah bless him and his family, said: "The most hateful of creation to Allah is one who bares the back of a Muslim without right." He forbade the carrying out of prescribed limits inside the mosques. It is also related from him that he said: "Whoever commits a sin and is punished for it in this world — Allah is more just than to repeat that punishment upon His servant in the Hereafter; and whoever commits a sin and Allah conceals it for him in this world — He is more generous than to return to something He has already pardoned and concealed."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'it is related from him may allah bless him and his family that he said the back of the believer is inviolable except for a limit that is due he forbade anyone from exceeding one of the limits of allah whether by falling short or by going beyond what has been prescribed and he said allah mighty and majestic has made the limits clear so whoever transgresses them has wronged himself as he exalted be his remembrance has said and he set a limit upon whoever transgresses a limit he may allah bless him and his family said the most hateful of creation to allah is one who bares the back of a muslim without right he forbade the carrying out of prescribed limits inside the mosques it is also related from him that he said whoever commits a sin and is punished for it in this world allah is more just than to repeat that punishment upon his servant in the hereafter and whoever commits a sin and allah conceals it for him in this world he is more generous than to return to something he has already pardoned and concealed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 64, NULL, 'Ali, may the blessings of Allah be upon him, wrote to Rifaa ibn Shaddad, his judge over al-Ahwaz, a letter in which he said: "Establish the limits upon the near, that the distant may shun them; do not let blood be shed in vain, and do not let the limits be neglected."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'ali may the blessings of allah be upon him wrote to rifaa ibn shaddad his judge over al ahwaz a letter in which he said establish the limits upon the near that the distant may shun them do not let blood be shed in vain and do not let the limits be neglected', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 65, NULL, 'When Uthman was brought al-Waleed ibn Utbah, and witnesses testified against him, and the offense he had committed against the Muslims was made plain, the Muslims declared that the limits of Allah had been neglected. Al-Waleed was placed in a room at the side of the house, and it was announced: "Let whoever holds that the limit is due upon him rise and carry it out." Yet whenever a man came in to flog him, al-Waleed would say: "I adjure you by Allah not to sever my kinship, and not to expose me before the Commander of the Faithful" — and the man would turn back from him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'when uthman was brought al waleed ibn utbah and witnesses testified against him and the offense he had committed against the muslims was made plain the muslims declared that the limits of allah had been neglected al waleed was placed in a room at the side of the house and it was announced let whoever holds that the limit is due upon him rise and carry it out yet whenever a man came in to flog him al waleed would say i adjure you by allah not to sever my kinship and not to expose me before the commander of the faithful and the man would turn back from him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 66, NULL, 'When Ali, may the blessings of Allah be upon him, saw that a limit from among the limits of Allah was being neglected, he took up the whip and went in to him. Al-Waleed said the like to him. Al-Husayn ibn Ali, may both be blessed, followed him in and said: "O my father, what is between you and him? Leave him be; you see what the people have made of his case." But Ali, may the blessings of Allah be upon him, pressed against the chest of al-Husayn (ع) and spoke sharply to him, so that he withdrew. Then Ali took the whip and flogged al-Waleed until the limit was carried out in full.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'when ali may the blessings of allah be upon him saw that a limit from among the limits of allah was being neglected he took up the whip and went in to him al waleed said the like to him al husayn ibn ali may both be blessed followed him in and said o my father what is between you and him leave him be you see what the people have made of his case but ali may the blessings of allah be upon him pressed against the chest of al husayn ع and spoke sharply to him so that he withdrew then ali took the whip and flogged al waleed until the limit was carried out in full', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 67, NULL, 'It is related from him that he said: "Three things, if you do them, no affliction will descend upon you: that you wage struggle against your enemy; that you raise your limits to your imams and let them judge in them with justice; and that you submit to their command."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'it is related from him that he said three things if you do them no affliction will descend upon you that you wage struggle against your enemy that you raise your limits to your imams and let them judge in them with justice and that you submit to their command', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 68, NULL, 'Umar said to him: "Counsel me, O Abu al-Hasan."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'umar said to him counsel me o abu al hasan', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 69, NULL, 'He said: "I counsel you to judge by the Book of Allah in contentment and in anger, to apportion with justice between the red and the black, and to establish the limits upon the distant and the near alike."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'he said i counsel you to judge by the book of allah in contentment and in anger to apportion with justice between the red and the black and to establish the limits upon the distant and the near alike', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 70, NULL, 'Umar said to him: "You have been brief and you have reached the heart of it."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'umar said to him you have been brief and you have reached the heart of it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 71, NULL, 'Every Friday, Ali — may the blessings of Allah be upon him — reviewed the prisons, and whenever a prescribed punishment was found to be due against anyone, he carried it out without delay. On one occasion, three men came before him to testify against a man for adultery. He asked: "Where is the fourth?" The fourth witness was absent. They replied: "We will bring him shortly, O Commander of the Faithful." He said: "There is no waiting even an hour in the prescribed limits" — and he flogged the three for false accusation.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'every friday ali may the blessings of allah be upon him reviewed the prisons and whenever a prescribed punishment was found to be due against anyone he carried it out without delay on one occasion three men came before him to testify against a man for adultery he asked where is the fourth the fourth witness was absent they replied we will bring him shortly o commander of the faithful he said there is no waiting even an hour in the prescribed limits and he flogged the three for false accusation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 72, NULL, 'A delegation came to him and said: "O Commander of the Faithful, we have come to ask you for something." He said: "Ask me for nothing that I possess but that I will give it to you." They had come on behalf of a man of the Banu Asad against whom a prescribed punishment was due, and they said: "Grant us so-and-so." He brought the man out and carried out the punishment. They said: "Did you not promise us, O Commander of the Faithful, to release him?" He said: "I promised you what I possess; but this belongs to Allah, and I do not possess it."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'a delegation came to him and said o commander of the faithful we have come to ask you for something he said ask me for nothing that i possess but that i will give it to you they had come on behalf of a man of the banu asad against whom a prescribed punishment was due and they said grant us so and so he brought the man out and carried out the punishment they said did you not promise us o commander of the faithful to release him he said i promised you what i possess but this belongs to allah and i do not possess it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 73, NULL, 'He once ordered his servant Qanbar to flog a man the prescribed number of lashes. Qanbar, carried away by anger, gave three lashes more than the limit. When this was brought to Ali''s attention, he granted the man retaliation against Qanbar and had Qanbar flogged three lashes in return.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'he once ordered his servant qanbar to flog a man the prescribed number of lashes qanbar carried away by anger gave three lashes more than the limit when this was brought to alis attention he granted the man retaliation against qanbar and had qanbar flogged three lashes in return', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 74, NULL, 'He also wrote to Rifaa: "Shield the believer as much as you are able, for his back is a sanctuary of Allah, his soul is honored before Allah, and to him belongs the reward of Allah."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'he also wrote to rifaa shield the believer as much as you are able for his back is a sanctuary of allah his soul is honored before allah and to him belongs the reward of allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 75, NULL, 'It is related from him that he said, concerning a people who had held out in enemy territory and asked for a covenant exempting them from accountability for what had passed: "Do not grant a covenant that would set aside one of the limits of Allah. How can the limits be lifted from those to whom they apply, when it is the friends of Allah and those who strive in His path who go forth to establish them?"', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'it is related from him that he said concerning a people who had held out in enemy territory and asked for a covenant exempting them from accountability for what had passed do not grant a covenant that would set aside one of the limits of allah how can the limits be lifted from those to whom they apply when it is the friends of allah and those who strive in his path who go forth to establish them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 76, NULL, 'It is related from Abu Jafar Muhammad ibn Ali, may the blessings of Allah be upon him, that he said: "Pardon nothing of the limits that belong to Allah, Mighty and Majestic. Whoever comes to know of one of them has no fitting course but to raise it to the Imam. As for the rights of people that fall within the limits, there is no harm in pardoning those before the matter reaches the ruler — as with the thief before he is brought before the Imam — but pardon is not permissible once the matter has reached him. And whoever pardons a limit that is his own right, then later wishes to enforce it, has no standing to do so."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'it is related from abu jafar muhammad ibn ali may the blessings of allah be upon him that he said pardon nothing of the limits that belong to allah mighty and majestic whoever comes to know of one of them has no fitting course but to raise it to the imam as for the rights of people that fall within the limits there is no harm in pardoning those before the matter reaches the ruler as with the thief before he is brought before the imam but pardon is not permissible once the matter has reached him and whoever pardons a limit that is his own right then later wishes to enforce it has no standing to do so', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 77, NULL, 'It is related from Jafar ibn Muhammad, may the blessings of Allah be upon him, that he said: "Whoever seizes a thief and pardons him, there is no harm in it. But once the thief has been raised to the Sultan, his hand is to be cut off."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'it is related from jafar ibn muhammad may the blessings of allah be upon him that he said whoever seizes a thief and pardons him there is no harm in it but once the thief has been raised to the sultan his hand is to be cut off', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 78, NULL, 'If the one from whom the theft was made says he pardons the thief, the prescribed penalty is not averted, for pardon would have been effective only before the matter was raised to the ruler. Once it has been raised, the limit is not set aside — by the word of Allah, Mighty and Majestic: and those who keep the limits of Allah. Once the limit has been raised to the Imam, no one has the standing to abandon it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'if the one from whom the theft was made says he pardons the thief the prescribed penalty is not averted for pardon would have been effective only before the matter was raised to the ruler once it has been raised the limit is not set aside by the word of allah mighty and majestic and those who keep the limits of allah once the limit has been raised to the imam no one has the standing to abandon it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 80, NULL, 'Allah, Mighty and Majestic, has said: "And do not approach adultery; indeed it is an indecency and an evil way." (Surah al-Isra, 17:32) And He said: "And those who do not call upon another god alongside Allah, nor kill the soul that Allah has forbidden except in truth, nor commit adultery; and whoever does that will meet a penalty. The punishment will be multiplied for him on the Day of Resurrection, and he will abide in it humiliated, except for whoever repents." (Surah al-Furqan, 25:68–70)', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'allah mighty and majestic has said and do not approach adultery indeed it is an indecency and an evil way surah al isra 17 32 and he said and those who do not call upon another god alongside allah nor kill the soul that allah has forbidden except in truth nor commit adultery and whoever does that will meet a penalty the punishment will be multiplied for him on the day of resurrection and he will abide in it humiliated except for whoever repents surah al furqan 25 68 70', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 81, NULL, 'The Messenger of Allah, may Allah bless him and his family, said: "The wrath of Allah grows severe against a woman who brings into a people one who is not of them, so that he gazes upon what is sacred to them and treads upon their beds. And the most severely punished of people on the Day of Resurrection is the one who plants his seed in a womb forbidden to him."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the messenger of allah may allah bless him and his family said the wrath of allah grows severe against a woman who brings into a people one who is not of them so that he gazes upon what is sacred to them and treads upon their beds and the most severely punished of people on the day of resurrection is the one who plants his seed in a womb forbidden to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 82, NULL, 'He, may Allah bless him and his family, also said: "The adulterer will stand on the Day of Resurrection above the people of the Fire, and a drop will fall from his private part by which the people of Hell will be tormented, and they will say to the keepers, What is this foul stench? and it will be said to them, This is the smell of an adulterer. And an adulteress will be brought, and a drop will fall from her, and the people of the Fire will be tormented by her stench."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'he may allah bless him and his family also said the adulterer will stand on the day of resurrection above the people of the fire and a drop will fall from his private part by which the people of hell will be tormented and they will say to the keepers what is this foul stench and it will be said to them this is the smell of an adulterer and an adulteress will be brought and a drop will fall from her and the people of the fire will be tormented by her stench', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 83, NULL, 'He, may Allah bless him and his family, said: "There is no sin greater before Allah, Mighty and Majestic, after associating partners with Him, than unlawful seed that a man places in a womb not lawful to him."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'he may allah bless him and his family said there is no sin greater before allah mighty and majestic after associating partners with him than unlawful seed that a man places in a womb not lawful to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 84, NULL, 'And he said: "Adultery and goodness do not gather in a single house."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'and he said adultery and goodness do not gather in a single house', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 85, NULL, 'He also delivered a sermon, may Allah bless him and his family, in which he said: "Three whom Allah will not speak to on the Day of Resurrection, nor purify, and for whom there is a painful punishment: an adulterous old man, a tyrant king, and a proud pauper."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'he also delivered a sermon may allah bless him and his family in which he said three whom allah will not speak to on the day of resurrection nor purify and for whom there is a painful punishment an adulterous old man a tyrant king and a proud pauper', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 86, NULL, 'And he said: "The adulterer does not commit adultery while he is a believer."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'and he said the adulterer does not commit adultery while he is a believer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 87, NULL, 'Jafar ibn Muhammad, may the blessings of Allah be upon him, said: "When he lies upon her belly, the spirit of faith departs from him; and when he rises and seeks the forgiveness of Allah, it returns to him."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'jafar ibn muhammad may the blessings of allah be upon him said when he lies upon her belly the spirit of faith departs from him and when he rises and seeks the forgiveness of allah it returns to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 88, NULL, 'Adultery is the placing of the private part in one who is neither a spouse nor lawfully possessed by a man''s right hand. Allah, Mighty and Majestic, has said: "And those who guard their private parts, except from their spouses or those whom their right hands possess, for then they are not to be blamed; but whoever seeks beyond that, those are the transgressors." (Surah al-Muminun, 23:5–7)', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'adultery is the placing of the private part in one who is neither a spouse nor lawfully possessed by a mans right hand allah mighty and majestic has said and those who guard their private parts except from their spouses or those whom their right hands possess for then they are not to be blamed but whoever seeks beyond that those are the transgressors surah al muminun 23 5 7', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 89, NULL, 'When an adulterer is found, the legal proof against him may be established in one of three ways:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'when an adulterer is found the legal proof against him may be established in one of three ways', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 90, NULL, 'Four men of just standing testify that they witnessed him commit adultery with a woman — having seen the organ enter her private part — while he held a lawful wife with whom he had consummated marriage and the woman held a lawful husband. Both the man and the woman confess. One of them confesses and witness testimony is established against the other.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'four men of just standing testify that they witnessed him commit adultery with a woman having seen the organ enter her private part while he held a lawful wife with whom he had consummated marriage and the woman held a lawful husband both the man and the woman confess one of them confesses and witness testimony is established against the other', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 91, NULL, 'In any of these cases, each party — whether the one who confessed or the one against whom proof was given — receives one hundred lashes. They are then brought out, and a pit is dug for each to the depth of the navel; each is placed upright within it and packed in. Where the matter rested on confession, the judge before whom the confession was made begins the stoning and then directs the people to continue, using stones of moderate size — such as fill the palm or less — until death. The condemned are then brought out, washed, prayed over, and buried.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'in any of these cases each party whether the one who confessed or the one against whom proof was given receives one hundred lashes they are then brought out and a pit is dug for each to the depth of the navel each is placed upright within it and packed in where the matter rested on confession the judge before whom the confession was made begins the stoning and then directs the people to continue using stones of moderate size such as fill the palm or less until death the condemned are then brought out washed prayed over and buried', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 92, NULL, 'The confession of an adulterer is not established unless it is made on four separate occasions, while the person is of sound mind, willing, and free from coercion. Where the matter rests on the testimony of witnesses, the witnesses cast the first stones, then the judge, then the people.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the confession of an adulterer is not established unless it is made on four separate occasions while the person is of sound mind willing and free from coercion where the matter rests on the testimony of witnesses the witnesses cast the first stones then the judge then the people', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 93, NULL, 'A man is not counted as protected until he has consummated marriage with his wife and she is in his keeping; a bondwoman does not render a free man protected, nor does a bondman render a free woman protected. If one party is protected and the other is not, the protected one is stoned after being flogged, and the unprotected one receives a hundred lashes.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'a man is not counted as protected until he has consummated marriage with his wife and she is in his keeping a bondwoman does not render a free man protected nor does a bondman render a free woman protected if one party is protected and the other is not the protected one is stoned after being flogged and the unprotected one receives a hundred lashes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 94, NULL, 'The floggings are ranked by severity:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the floggings are ranked by severity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 95, NULL, 'The flogging of the adulterer The flogging of the false accuser The flogging of the drinker The flogging of discretionary punishment', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the flogging of the adulterer the flogging of the false accuser the flogging of the drinker the flogging of discretionary punishment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 96, NULL, 'A pregnant woman is not flogged until she has delivered and is purified of her postnatal bleeding. No limit falls upon a child, whether boy or girl; yet if an adult commits this sin with a child, the limit is established upon the adult.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'a pregnant woman is not flogged until she has delivered and is purified of her postnatal bleeding no limit falls upon a child whether boy or girl yet if an adult commits this sin with a child the limit is established upon the adult', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 97, NULL, 'When a single child is claimed by more than one man, the elder of the claimants takes precedence, and whoever withheld the child from one of them bears the responsibility for what was done. As for the act of the people of Lot, the one who performs the act upon another is stoned just as two who commit adultery are stoned. If the act is intercrural, the hadd falls due upon both parties. For the act committed between women, each receives a hundred lashes.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'when a single child is claimed by more than one man the elder of the claimants takes precedence and whoever withheld the child from one of them bears the responsibility for what was done as for the act of the people of lot the one who performs the act upon another is stoned just as two who commit adultery are stoned if the act is intercrural the hadd falls due upon both parties for the act committed between women each receives a hundred lashes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 98, NULL, 'Whoever commits adultery with a relative whom it is unlawful for him to marry is put to death, and she too is put to death if she consented, provided neither of them is bound by marriage. If both are married, the hadd is applied and they are stoned. Whoever forces a woman against her will is put to death if he is unmarried, and is flogged the hadd and stoned if he is married. No hadd falls upon the coerced woman, and if he has taken her virginity she is owed a dowry equal to that of her peers. If she is a slave girl, she is owed a tenth of her price; if she is a non-virgin, half a tenth of her price.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whoever commits adultery with a relative whom it is unlawful for him to marry is put to death and she too is put to death if she consented provided neither of them is bound by marriage if both are married the hadd is applied and they are stoned whoever forces a woman against her will is put to death if he is unmarried and is flogged the hadd and stoned if he is married no hadd falls upon the coerced woman and if he has taken her virginity she is owed a dowry equal to that of her peers if she is a slave girl she is owed a tenth of her price if she is a non virgin half a tenth of her price', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 99, NULL, 'No hadd falls upon one who has lost his reason, nor upon one who enters an unlawful union that nevertheless bears the outward form of a marriage — such as a man who marries a woman during her waiting period, or upon a contract that does not meet the requirements of a valid marriage. If two men are found together under a single cover, or a man and a woman in like circumstance, the hadd is applied. If two women are found together in like manner, they are flogged with a punishment short of the hadd of stoning. If a slave or a slave girl commits adultery, each receives fifty lashes, whether or not they are married.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'no hadd falls upon one who has lost his reason nor upon one who enters an unlawful union that nevertheless bears the outward form of a marriage such as a man who marries a woman during her waiting period or upon a contract that does not meet the requirements of a valid marriage if two men are found together under a single cover or a man and a woman in like circumstance the hadd is applied if two women are found together in like manner they are flogged with a punishment short of the hadd of stoning if a slave or a slave girl commits adultery each receives fifty lashes whether or not they are married', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 100, NULL, 'When the adulterer is brought forward to be flogged, the believers are commanded to attend the punishment as witnesses, as Allah Almighty says:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'when the adulterer is brought forward to be flogged the believers are commanded to attend the punishment as witnesses as allah almighty says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 101, NULL, 'An-Nur: 2﴿وَلْيَشْهَدْ عَذَابَهُمَا طَائِفَةٌ مِّنَ الْمُؤْمِنِينَ﴾"And let a group of the believers witness their punishment." (al-Nur 2)', '', NULL, 'An-Nur: 2', NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'an nur 2 وليشهد عذابهما طايفه من المومنين and let a group of the believers witness their punishment al nur 2', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 102, NULL, 'The adulterer is flogged in the condition in which he is found. If he is naked, he remains naked; if he is clothed, he remains clothed and is struck through his garments. Anything that would shield him from the effect of the blows — a thick fur or the like — is removed. The woman is seated and kept covered, and every limb is struck except the face, the private parts, and the vital organs. If striking the back alone is the practice, that is permissible, and it is what is customarily done. The blows must not be of a severity that kills. Neither a woman in her post-natal bleeding nor a menstruating woman is flogged until she has been purified.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the adulterer is flogged in the condition in which he is found if he is naked he remains naked if he is clothed he remains clothed and is struck through his garments anything that would shield him from the effect of the blows a thick fur or the like is removed the woman is seated and kept covered and every limb is struck except the face the private parts and the vital organs if striking the back alone is the practice that is permissible and it is what is customarily done the blows must not be of a severity that kills neither a woman in her post natal bleeding nor a menstruating woman is flogged until she has been purified', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 103, NULL, 'If the adulterer and the adulteress confess and then retract, they are left alone until they have confessed four times; a retraction made after that is not accepted. Whoever commits adultery with his wife''s mother is subject to the hadd. If a man has intercourse with a slave woman in whom he holds a partial share, he is flogged in proportion to the share that is not his, and the hadd is averted from him in proportion to his own share. Likewise, if she is his slave woman who has contracted to purchase her freedom, he is struck in proportion to the part of her that has been freed, and the hadd is averted from him in proportion to the part still owned.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'if the adulterer and the adulteress confess and then retract they are left alone until they have confessed four times a retraction made after that is not accepted whoever commits adultery with his wifes mother is subject to the hadd if a man has intercourse with a slave woman in whom he holds a partial share he is flogged in proportion to the share that is not his and the hadd is averted from him in proportion to his own share likewise if she is his slave woman who has contracted to purchase her freedom he is struck in proportion to the part of her that has been freed and the hadd is averted from him in proportion to the part still owned', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 104, NULL, 'A man who imitates women in his manner is disciplined; if he persists, he is banished from inhabited dwellings. Whoever commits an act with an animal is punished, and the price of the animal is paid to its owner. If the animal is of a kind that is eaten, it is slaughtered and buried, and eating it is not lawful. If it is not of a kind that is eaten, it is sold and removed to a place where it will not be recognized, and the one who committed the act is publicly reproached.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'a man who imitates women in his manner is disciplined if he persists he is banished from inhabited dwellings whoever commits an act with an animal is punished and the price of the animal is paid to its owner if the animal is of a kind that is eaten it is slaughtered and buried and eating it is not lawful if it is not of a kind that is eaten it is sold and removed to a place where it will not be recognized and the one who committed the act is publicly reproached', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 105, NULL, 'A slave under a contract of manumission is flogged with the hadd of a free man in proportion to the part of him that has been freed, and with the hadd of a slave in proportion to the part still in bondage. All of this is the unanimous teaching of the Ahl al-Bayt, may.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'a slave under a contract of manumission is flogged with the hadd of a free man in proportion to the part of him that has been freed and with the hadd of a slave in proportion to the part still in bondage all of this is the unanimous teaching of the ahl al bayt may', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 107, NULL, 'Allah Almighty said:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'allah almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 108, NULL, 'An-Nur: 23﴿إِنَّ الَّذِينَ يَرْمُونَ الْمُحْصَنَاتِ الْغَافِلَاتِ الْمُؤْمِنَاتِ لُعِنُوا فِي الدُّنْيَا وَالْآخِرَةِ وَلَهُمْ عَذَابٌ عَظِيمٌ﴾"Indeed, those who accuse chaste, heedless, believing women are cursed in this world and the Hereafter, and for them is a great punishment." (al-Nur 23)', '', NULL, 'An-Nur: 23', NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'an nur 23 ان الذين يرمون المحصنات الغافلات المومنات لعنوا في الدنيا والاخره ولهم عذاب عظيم indeed those who accuse chaste heedless believing women are cursed in this world and the hereafter and for them is a great punishment al nur 23', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 109, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 110, NULL, 'An-Nur: 4, Ali ''Imran: 89﴿وَالَّذِينَ يَرْمُونَ الْمُحْصَنَاتِ ثُمَّ لَمْ يَأْتُوا بِأَرْبَعَةِ شُهَدَاءَ فَاجْلِدُوهُمْ ثَمَانِينَ جَلْدَةً وَلَا تَقْبَلُوا لَهُمْ شَهَادَةً أَبَدًا وَأُولَٰئِكَ هُمُ الْفَاسِقُونَ ۝ إِلَّا الَّذِينَ تَابُوا مِن بَعْدِ ذَٰلِكَ وَأَصْلَحُوا فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ﴾"And those who accuse chaste women and then do not produce four witnesses, flog them with eighty lashes and never accept their testimony thereafter; it is they who are the defiantly disobedient, except those who repent after that and make amends, for indeed Allah is Forgiving and Merciful." (al-Nur 4 to 5)', '', NULL, 'An-Nur: 4, Ali ''Imran: 89', NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'an nur 4 ali imran 89 والذين يرمون المحصنات ثم لم ياتوا باربعه شهداء فاجلدوهم ثمانين جلده ولا تقبلوا لهم شهاده ابدا واوليك هم الفاسقون الا الذين تابوا من بعد ذلك واصلحوا فان الله غفور رحيم and those who accuse chaste women and then do not produce four witnesses flog them with eighty lashes and never accept their testimony thereafter it is they who are the defiantly disobedient except those who repent after that and make amends for indeed allah is forgiving and merciful al nur 4 to 5', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 111, NULL, 'It is narrated from Ali that he said: "The major sins are associating partners with Allah Almighty, killing a believer while under covenant, fleeing from the battle line except as one wheeling to fight or withdrawing to rejoin his own troop, consuming usury after the proof of its prohibition has been established, devouring the wealth of the orphan unjustly, reverting to the life of the desert after the Emigration, and accusing chaste, heedless, believing women."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'it is narrated from ali that he said the major sins are associating partners with allah almighty killing a believer while under covenant fleeing from the battle line except as one wheeling to fight or withdrawing to rejoin his own troop consuming usury after the proof of its prohibition has been established devouring the wealth of the orphan unjustly reverting to the life of the desert after the emigration and accusing chaste heedless believing women', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 112, NULL, 'It is narrated from Abu Abdullah Jafar ibn Muhammad, (ع), that he said: "Whoever falsely accuses a believing man or a believing woman of something that is not in them, Allah Almighty casts him into the clay of corruption until he comes forth from what he said." He was asked about a man who slanders a chaste Muslim woman, and he said: "The hadd is established against him once it is proven, and his repentance consists in his declaring himself a liar before the people and turning back from what he did. If he does this, his testimony is accepted thereafter."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'it is narrated from abu abdullah jafar ibn muhammad ع that he said whoever falsely accuses a believing man or a believing woman of something that is not in them allah almighty casts him into the clay of corruption until he comes forth from what he said he was asked about a man who slanders a chaste muslim woman and he said the hadd is established against him once it is proven and his repentance consists in his declaring himself a liar before the people and turning back from what he did if he does this his testimony is accepted thereafter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 113, NULL, 'The slanderer is flogged eighty lashes. If he slanders a group and they bring their claims against him together, he receives a single hadd covering all of them; but if they come forward one after another, he receives a separate hadd for each. If the one slandered — man or woman — confesses to what was said of them, or the evidence of it is established against them as Allah Almighty has indicated, then no hadd falls upon the slanderer. Whoever slanders a polytheist incurs no hadd, unless the polytheist has a Muslim child, in which case the hadd is applied out of regard for the sanctity of Islam. It does not befit a Muslim to slander a polytheist, nor anyone else.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the slanderer is flogged eighty lashes if he slanders a group and they bring their claims against him together he receives a single hadd covering all of them but if they come forward one after another he receives a separate hadd for each if the one slandered man or woman confesses to what was said of them or the evidence of it is established against them as allah almighty has indicated then no hadd falls upon the slanderer whoever slanders a polytheist incurs no hadd unless the polytheist has a muslim child in which case the hadd is applied out of regard for the sanctity of islam it does not befit a muslim to slander a polytheist nor anyone else', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 114, NULL, 'If a free man slanders a slave, he receives a disciplinary punishment but not the full hadd. If a slave slanders a free man, the full hadd is applied. If a dhimmi slanders a Muslim, the hadd is applied and he is made a public example. If a man slanders another man and that man slanders him in return, and both bring the matter before the authority, each receives a discretionary punishment. Whoever says to his wife, "I did not find you a virgin," incurs no hadd.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'if a free man slanders a slave he receives a disciplinary punishment but not the full hadd if a slave slanders a free man the full hadd is applied if a dhimmi slanders a muslim the hadd is applied and he is made a public example if a man slanders another man and that man slanders him in return and both bring the matter before the authority each receives a discretionary punishment whoever says to his wife i did not find you a virgin incurs no hadd', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 115, NULL, 'Whoever has already incurred one hadd and is then falsely accused of another offense, the slanderer is flogged the hadd for that accusation. Whoever acknowledges a child as his own and then disavows him is flogged the hadd, the child''s lineage is fixed to him, and a mere insinuation — falling short of an explicit claim — carries no hadd. Whoever insults the Prophet, may the, is put to death. Whoever insults any of the Imams (عَلَيْهِمُ السَّلَامُ) is likewise put to death. Whoever commits slander in any language has the hadd imposed upon him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whoever has already incurred one hadd and is then falsely accused of another offense the slanderer is flogged the hadd for that accusation whoever acknowledges a child as his own and then disavows him is flogged the hadd the childs lineage is fixed to him and a mere insinuation falling short of an explicit claim carries no hadd whoever insults the prophet may the is put to death whoever insults any of the imams عليهم السلام is likewise put to death whoever commits slander in any language has the hadd imposed upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 116, NULL, 'Whoever slanders another and then pardons the one he accused before raising the matter to the authority, that pardon is valid; the right to pursue the claim is extinguished. If, however, he has already raised the matter to the authority and lodged a petition against the accused, no pardon is accepted after that point.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whoever slanders another and then pardons the one he accused before raising the matter to the authority that pardon is valid the right to pursue the claim is extinguished if however he has already raised the matter to the authority and lodged a petition against the accused no pardon is accepted after that point', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 117, NULL, 'If someone slanders a child or a person who has lost his reason, no hadd falls upon them, though the child is disciplined so that he does not grow bold in slander. If a man or a woman slanders their own child, no hadd is imposed upon them; but if the child slanders them, the hadd is applied on their behalf. If a man says to another, "O sodomite," no hadd falls upon him, because he has only ascribed the man to Lot (ع); but if he says, "O you who do the work of the people of Lot," the hadd becomes obligatory. If a man slanders an absent or a deceased woman, her guardian may rise against him on her behalf, and the hadd belongs to him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'if someone slanders a child or a person who has lost his reason no hadd falls upon them though the child is disciplined so that he does not grow bold in slander if a man or a woman slanders their own child no hadd is imposed upon them but if the child slanders them the hadd is applied on their behalf if a man says to another o sodomite no hadd falls upon him because he has only ascribed the man to lot ع but if he says o you who do the work of the people of lot the hadd becomes obligatory if a man slanders an absent or a deceased woman her guardian may rise against him on her behalf and the hadd belongs to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 118, NULL, 'Whoever denies a man his lineage incurs the hadd. Whoever reviles a man or a woman receives a discretionary punishment on their behalf — as when he says, "O immoral one," "O malicious one," "son of a Christian," "son of a Zoroastrian," and the like among curses and insults. All of this is the teaching of the Ahl al-Bayt (عَلَيْهِمُ السَّلَامُ).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whoever denies a man his lineage incurs the hadd whoever reviles a man or a woman receives a discretionary punishment on their behalf as when he says o immoral one o malicious one son of a christian son of a zoroastrian and the like among curses and insults all of this is the teaching of the ahl al bayt عليهم السلام', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 120, NULL, 'Allah Almighty said:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'allah almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 121, NULL, 'Al-Ma''idah: 90﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالْأَنْصَابُ وَالْأَزْلَامُ رِجْسٌ مِّنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ﴾"O you who believe, wine, gambling, idols, and divining arrows are only a defilement from the work of Satan, so avoid it, that you may be successful." (al-Maidah 90)', '', NULL, 'Al-Ma''idah: 90', NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'al maidah 90 يا ايها الذين امنوا انما الخمر والميسر والانصاب والازلام رجس من عمل الشيطان فاجتنبوه لعلكم تفلحون o you who believe wine gambling idols and divining arrows are only a defilement from the work of satan so avoid it that you may be successful al maidah 90', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 122, NULL, 'The Messenger of Allah said: "May Allah curse wine, the one who presses it, the one who has it pressed, its seller, its buyer, the one who pours it, the one who consumes its price, its drinker, the one who carries it, and the one to whom it is carried." He also said: "There is no one who drinks wine in this world and then drinks it in the Enclosure of Holiness."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the messenger of allah said may allah curse wine the one who presses it the one who has it pressed its seller its buyer the one who pours it the one who consumes its price its drinker the one who carries it and the one to whom it is carried he also said there is no one who drinks wine in this world and then drinks it in the enclosure of holiness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 123, NULL, 'Abu Jafar Muhammad ibn Ali (ع) said: "One addicted to wine meets Allah Almighty, when he meets Him, as one who worships an idol." And whoever drinks a single draft of it, Allah does not accept a prayer from him for forty nights.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'abu jafar muhammad ibn ali ع said one addicted to wine meets allah almighty when he meets him as one who worships an idol and whoever drinks a single draft of it allah does not accept a prayer from him for forty nights', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 124, NULL, 'The Messenger of Allah said: "Every intoxicant is forbidden, and whatever intoxicates in a large quantity, a small quantity of it is forbidden as well."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the messenger of allah said every intoxicant is forbidden and whatever intoxicates in a large quantity a small quantity of it is forbidden as well', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 125, NULL, 'Whoever drinks wine, whether little or much, has the hadd applied to him. If he confesses to drinking it a second time, he is struck again; and if he drinks it a third time, he is put to death — though not until the hadd has been administered upon him twice.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whoever drinks wine whether little or much has the hadd applied to him if he confesses to drinking it a second time he is struck again and if he drinks it a third time he is put to death though not until the hadd has been administered upon him twice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 126, NULL, 'Whoever drinks an intoxicant and becomes so intoxicated that he does not know his own state is flogged the hadd of eighty lashes. If he returns to it after being struck once, he is struck again; and if he returns after being struck twice, he is put to death on the third occasion. If he drinks but does not become intoxicated, he receives a discretionary punishment; and if he returns to it, he is punished with a severe chastisement.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whoever drinks an intoxicant and becomes so intoxicated that he does not know his own state is flogged the hadd of eighty lashes if he returns to it after being struck once he is struck again and if he returns after being struck twice he is put to death on the third occasion if he drinks but does not become intoxicated he receives a discretionary punishment and if he returns to it he is punished with a severe chastisement', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 127, NULL, 'Whoever drinks wine or an intoxicant without knowing it is forbidden incurs no hadd. Whoever acknowledges drinking wine and then denies it is still given the hadd, and no regard is paid to his denial.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whoever drinks wine or an intoxicant without knowing it is forbidden incurs no hadd whoever acknowledges drinking wine and then denies it is still given the hadd and no regard is paid to his denial', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 128, NULL, 'The hadd for a slave in the matter of wine is eighty lashes — the same as the hadd for a free man.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the hadd for a slave in the matter of wine is eighty lashes the same as the hadd for a free man', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 129, NULL, 'If the people of the dhimma openly drink wine or an intoxicant, they are struck just as Muslims are struck, for their covenant was granted to them only on the condition that they not openly display anything forbidden in the religion of Islam.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'if the people of the dhimma openly drink wine or an intoxicant they are struck just as muslims are struck for their covenant was granted to them only on the condition that they not openly display anything forbidden in the religion of islam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 130, NULL, 'When doubt arises concerning a hadd, it is suspended. There is no surety in a hadd, no testimony built upon testimony, no oath, and no letter from one judge to another taken as a basis for it. No hadd is carried out on the strength of intimidation, nor on a confession extracted under duress; for that reason, a man is neither imprisoned nor beaten to produce one. If several hadd punishments fall due upon a single person, all of them are carried out; and where death is among them, the lesser penalties are applied first, and he is then put to death. A man may not carry out a hadd upon his own slave except by permission of the authority. If a hadd becomes due upon someone and its prescribed measure is unspecified, he is beaten until the one striking him desists. Whoever is testified against for a hadd is held until the evidence is duly established; once it is established and the hadd is applied, he is not held in further detention.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'when doubt arises concerning a hadd it is suspended there is no surety in a hadd no testimony built upon testimony no oath and no letter from one judge to another taken as a basis for it no hadd is carried out on the strength of intimidation nor on a confession extracted under duress for that reason a man is neither imprisoned nor beaten to produce one if several hadd punishments fall due upon a single person all of them are carried out and where death is among them the lesser penalties are applied first and he is then put to death a man may not carry out a hadd upon his own slave except by permission of the authority if a hadd becomes due upon someone and its prescribed measure is unspecified he is beaten until the one striking him desists whoever is testified against for a hadd is held until the evidence is duly established once it is established and the hadd is applied he is not held in further detention', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 132, NULL, 'Allah Almighty said:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'allah almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 133, NULL, 'Al-Baqarah: 188﴿وَلَا تَأْكُلُوا أَمْوَالَكُم بَيْنَكُم بِالْبَاطِلِ﴾"And do not consume one another''s wealth among yourselves through falsehood." (al-Baqarah 188)', '', NULL, 'Al-Baqarah: 188', NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'al baqarah 188 ولا تاكلوا اموالكم بينكم بالباطل and do not consume one anothers wealth among yourselves through falsehood al baqarah 188', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 134, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 135, NULL, 'Al-Ma''idah: 38﴿وَالسَّارِقُ وَالسَّارِقَةُ فَاقْطَعُوا أَيْدِيَهُمَا﴾"As for the thief, male and female, cut off their hands." (al-Maidah 38)', '', NULL, 'Al-Ma''idah: 38', NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'al maidah 38 والسارق والسارقه فاقطعوا ايديهما as for the thief male and female cut off their hands al maidah 38', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 136, NULL, 'The Messenger of Allah, may the blessings and peace of Allah be upon him, said: "I have seen in the Fire the man with the crooked staff who used to steal from the pilgrims with it." And he said: "The thief does not steal while he is a believer."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the messenger of allah may the blessings and peace of allah be upon him said i have seen in the fire the man with the crooked staff who used to steal from the pilgrims with it and he said the thief does not steal while he is a believer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 137, NULL, 'Whoever enters another''s home without permission and steals from their property — or removes from a secured place goods worth five dinars — and either confesses or is convicted by evidence, has his right hand cut off at the joint where the four fingers meet the palm; the thumb and palm are left to him for his use. Should he steal a second time, his left foot is cut off at mid-foot, the heel and what adjoins it being left to him so that he may still walk. A third offense results in life imprisonment, and if he steals while imprisoned, he is put to death. When amputation is carried out, the site is cauterized with fire to hasten healing and to protect him from mortal harm. If the one performing the amputation errs — cutting the left hand or the right foot instead — that suffices, and nothing further is taken from him. Whatever of the stolen goods is found still in his possession is returned to its owners, and he is held liable for whatever he has destroyed. After the amputation is carried out, he is banished to a land other than the one in which the sentence was executed.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whoever enters anothers home without permission and steals from their property or removes from a secured place goods worth five dinars and either confesses or is convicted by evidence has his right hand cut off at the joint where the four fingers meet the palm the thumb and palm are left to him for his use should he steal a second time his left foot is cut off at mid foot the heel and what adjoins it being left to him so that he may still walk a third offense results in life imprisonment and if he steals while imprisoned he is put to death when amputation is carried out the site is cauterized with fire to hasten healing and to protect him from mortal harm if the one performing the amputation errs cutting the left hand or the right foot instead that suffices and nothing further is taken from him whatever of the stolen goods is found still in his possession is returned to its owners and he is held liable for whatever he has destroyed after the amputation is carried out he is banished to a land other than the one in which the sentence was executed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 138, NULL, 'No cutting applies to a guest who steals from his hosts, to a hired man who steals from the household that employed him and admitted him, or to anyone who entered the premises with the household''s permission. Snatching carries no cutting, nor does open robbery committed within a town — such as seizing an item and overpowering its owner in plain sight. The one who grabs openly and flees is not subject to amputation, nor is the pickpocket; both are punished by public example instead.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'no cutting applies to a guest who steals from his hosts to a hired man who steals from the household that employed him and admitted him or to anyone who entered the premises with the households permission snatching carries no cutting nor does open robbery committed within a town such as seizing an item and overpowering its owner in plain sight the one who grabs openly and flees is not subject to amputation nor is the pickpocket both are punished by public example instead', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 139, NULL, 'When such acts are committed on the road, however, the perpetrator is a brigand. Once he is brought before the Imam, the ruler holds discretion in the matter:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'when such acts are committed on the road however the perpetrator is a brigand once he is brought before the imam the ruler holds discretion in the matter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 140, NULL, 'He may put him to death. He may crucify him and leave him alive until he dies. He may cut off his hand and his foot from opposite sides. He may banish him from one land to another.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'he may put him to death he may crucify him and leave him alive until he dies he may cut off his hand and his foot from opposite sides he may banish him from one land to another', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 141, NULL, 'This is the treatment applied when the brigand has terrorized the road and waylaid Muslims. If he repents before he is seized, he is pardoned. Whoever fights such an aggressor in defense of himself and kills or wounds him bears no liability for that.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'this is the treatment applied when the brigand has terrorized the road and waylaid muslims if he repents before he is seized he is pardoned whoever fights such an aggressor in defense of himself and kills or wounds him bears no liability for that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 142, NULL, 'If the brigand is captured and wealth is found with him, it is returned to its owners, provided they are known. If its owners are not known, and he confesses or witnesses testify that the wealth belongs to what he plundered, it is placed in the treasury of the Muslims until a rightful claimant comes forward.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'if the brigand is captured and wealth is found with him it is returned to its owners provided they are known if its owners are not known and he confesses or witnesses testify that the wealth belongs to what he plundered it is placed in the treasury of the muslims until a rightful claimant comes forward', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 143, NULL, 'A thief who holds a share in what he steals is not subject to the cutting penalty. Nor is cutting imposed on one who bores a hole or forces open a door but carries nothing away. There is no cutting for an ordinary stone, however valuable its appearance — only a precious gem crosses that threshold — nor for fruit stolen from the tree, nor for the pith of the palm, nor for any bird. What is taken from places open to the public likewise falls outside the penalty: mosques, inns, bathhouses, open courtyards, and every place a person may enter without permission. The exception is when stolen goods are removed from a secured enclosure within such a place; that changes the judgment. Sheep stolen from open pasture carry no cutting penalty either.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'a thief who holds a share in what he steals is not subject to the cutting penalty nor is cutting imposed on one who bores a hole or forces open a door but carries nothing away there is no cutting for an ordinary stone however valuable its appearance only a precious gem crosses that threshold nor for fruit stolen from the tree nor for the pith of the palm nor for any bird what is taken from places open to the public likewise falls outside the penalty mosques inns bathhouses open courtyards and every place a person may enter without permission the exception is when stolen goods are removed from a secured enclosure within such a place that changes the judgment sheep stolen from open pasture carry no cutting penalty either', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 144, NULL, 'When a thief steals repeatedly and evades capture, then is finally caught, his hand is cut and he is held liable for everything he took across all those offenses. When a man is found in possession of stolen property but neither confesses nor has the theft proven against him, he is not subject to cutting; the property is simply taken from him and restored to its rightful owner.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'when a thief steals repeatedly and evades capture then is finally caught his hand is cut and he is held liable for everything he took across all those offenses when a man is found in possession of stolen property but neither confesses nor has the theft proven against him he is not subject to cutting the property is simply taken from him and restored to its rightful owner', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 145, NULL, 'A madman who steals is not subject to cutting, nor is a boy who has not yet reached puberty, nor a minor — though the child is disciplined so that he does not grow bold in stealing. A grave robber has his hand cut when he removes the shroud from the grave, for the grave is a secured place. If someone whose hand has been cut dies as a result of the cutting, no liability follows. The thief ought to be admonished after the cutting. It is narrated that Ali cut the hands of a group who had stolen, then brought fire, then fed them and gave them drink until they had recovered, then clothed them, and commanded them to take their severed hands in their sound hands.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'a madman who steals is not subject to cutting nor is a boy who has not yet reached puberty nor a minor though the child is disciplined so that he does not grow bold in stealing a grave robber has his hand cut when he removes the shroud from the grave for the grave is a secured place if someone whose hand has been cut dies as a result of the cutting no liability follows the thief ought to be admonished after the cutting it is narrated that ali cut the hands of a group who had stolen then brought fire then fed them and gave them drink until they had recovered then clothed them and commanded them to take their severed hands in their sound hands', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 146, NULL, 'He then said to them, "Raise your hands toward the sky and say: O Allah, Ali has cut off our hands according to Your Book and the Sunnah of Your Messenger." When they had said it, he replied, "Yes, O Lord, upon Your Book and the Sunnah of Your Messenger." Then he said to them, "These are your hands. They have gone ahead of you to the Fire. Whoever among you repents, his hand will drag him to Paradise, and whoever does not repent, it will drag him to Hell."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'he then said to them raise your hands toward the sky and say o allah ali has cut off our hands according to your book and the sunnah of your messenger when they had said it he replied yes o lord upon your book and the sunnah of your messenger then he said to them these are your hands they have gone ahead of you to the fire whoever among you repents his hand will drag him to paradise and whoever does not repent it will drag him to hell', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 147, NULL, 'There are cases in which no hand is cut at all. If a slave steals the property of his master, his hand is not cut off, though if he steals from anyone other than his master, it is. If a father steals from his son''s property, or a child from his father''s, or a wife from her husband''s, or a husband from his wife''s, or a sister from her brother''s, or a brother from his sister''s, no cutting applies in any of these cases. Nor is a thief''s hand to be cut if he stole during a year of famine and hardship. All of this is the position of the Ahl al-Bayt.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'there are cases in which no hand is cut at all if a slave steals the property of his master his hand is not cut off though if he steals from anyone other than his master it is if a father steals from his sons property or a child from his fathers or a wife from her husbands or a husband from his wifes or a sister from her brothers or a brother from his sisters no cutting applies in any of these cases nor is a thiefs hand to be cut if he stole during a year of famine and hardship all of this is the position of the ahl al bayt', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 148, NULL, 'Mention of the rulings on apostates and innovators', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'mention of the rulings on apostates and innovators', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 149, NULL, 'Allah the Almighty said: "How shall Allah guide a people who disbelieved after their faith?" And He said: "Whoever of you turns back from his religion and dies while he is a disbeliever, those are the ones whose deeds have become worthless in this world and the Hereafter." And He said: "It has been revealed to you and to those before you: if you associate partners with Allah, your deeds will surely become worthless, and you will surely be among the losers."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'allah the almighty said how shall allah guide a people who disbelieved after their faith and he said whoever of you turns back from his religion and dies while he is a disbeliever those are the ones whose deeds have become worthless in this world and the hereafter and he said it has been revealed to you and to those before you if you associate partners with allah your deeds will surely become worthless and you will surely be among the losers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 150, NULL, 'The Messenger of Allah said: "It is not permissible to kill a believing man except for one of three things: disbelief after faith, fornication after the establishment of marriage, or the taking of a life for no life." And he said: "Every innovation is misguidance, and every misguidance is in the Fire." And he said: "Whoever changes his religion, kill him."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the messenger of allah said it is not permissible to kill a believing man except for one of three things disbelief after faith fornication after the establishment of marriage or the taking of a life for no life and he said every innovation is misguidance and every misguidance is in the fire and he said whoever changes his religion kill him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 151, NULL, 'Whoever is born into Islam and then departs from it into any form of disbelief is killed and is not invited to repent. If the apostate is a woman, however, she is imprisoned until she repents.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whoever is born into islam and then departs from it into any form of disbelief is killed and is not invited to repent if the apostate is a woman however she is imprisoned until she repents', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 152, NULL, 'As for the heretic — one who denies the resurrection and the reckoning, or who denies the prophethood of the Prophets — or one who held a religion other than Islam, then submitted, and afterward reverted, Islam and repentance are presented to him over three days. If he repents, he is left alone. If he persists in his position, he is killed on the fourth day and is not invited to repent at that point. If he repents of his own accord before then, he is left; if he does not, he is killed.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'as for the heretic one who denies the resurrection and the reckoning or who denies the prophethood of the prophets or one who held a religion other than islam then submitted and afterward reverted islam and repentance are presented to him over three days if he repents he is left alone if he persists in his position he is killed on the fourth day and is not invited to repent at that point if he repents of his own accord before then he is left if he does not he is killed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 153, NULL, 'A male slave is likewise killed if his case is such.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'a male slave is likewise killed if his case is such', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 154, NULL, 'As for a female slave who apostatizes, the terms imposed upon her are harsher. She is put to the most demanding service, clothed only with what covers her nakedness, and fed only with what sustains her life, until she repents or dies. She is not killed outright, so that her family is not deprived of her through destruction. The same ruling applies to the mother of a child.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'as for a female slave who apostatizes the terms imposed upon her are harsher she is put to the most demanding service clothed only with what covers her nakedness and fed only with what sustains her life until she repents or dies she is not killed outright so that her family is not deprived of her through destruction the same ruling applies to the mother of a child', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 155, NULL, 'When an apostate apostatizes, whatever property he leaves behind passes as inheritance to his heirs, since his apostasy is treated as his death. His wife observes her waiting period and may remarry if she wishes. His children remain Muslims. Whichever parent submits to Islam, that parent''s minor children — and any children born thereafter — are Muslims by virtue of that parent''s Islam. If they grow up and refuse Islam, they stand in the position of apostates, and what is done to apostates is done to them.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'when an apostate apostatizes whatever property he leaves behind passes as inheritance to his heirs since his apostasy is treated as his death his wife observes her waiting period and may remarry if she wishes his children remain muslims whichever parent submits to islam that parents minor children and any children born thereafter are muslims by virtue of that parents islam if they grow up and refuse islam they stand in the position of apostates and what is done to apostates is done to them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 156, NULL, 'Whoever works sorcery against the Muslims has disbelieved, for Allah, exalted is He, says concerning the two angels: "And they taught no one until they said: We are only a trial, so do not disbelieve." And He says: "And they followed what the devils recited during the reign of Solomon, and Solomon did not disbelieve, but the devils disbelieved." The Messenger of Allah said: "The sorcerer among the Muslims is killed, but the sorcerer among the polytheists is not killed." It was asked, "O Messenger of Allah, and why is that?" He said, "Because the shirk he is upon is greater than the sorcery." Sorcery and shirk are thus bound together upon one tether. Whoever embraces Islam and then partakes of anything forbidden in Islam is beaten; and if that act carries a prescribed penalty, the penalty is carried out upon him. All of this is the saying of the Ahl al-Bayt.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whoever works sorcery against the muslims has disbelieved for allah exalted is he says concerning the two angels and they taught no one until they said we are only a trial so do not disbelieve and he says and they followed what the devils recited during the reign of solomon and solomon did not disbelieve but the devils disbelieved the messenger of allah said the sorcerer among the muslims is killed but the sorcerer among the polytheists is not killed it was asked o messenger of allah and why is that he said because the shirk he is upon is greater than the sorcery sorcery and shirk are thus bound together upon one tether whoever embraces islam and then partakes of anything forbidden in islam is beaten and if that act carries a prescribed penalty the penalty is carried out upon him all of this is the saying of the ahl al bayt', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 157, NULL, 'Mention of usurpation and transgression', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'mention of usurpation and transgression', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 158, NULL, 'Allah, the most truthful of all who speak, said: "And do not transgress; indeed, Allah does not love those who transgress." And He said: "And do not consume your wealth among yourselves through falsehood." The Messenger of Allah said: "The sanctity of your wealth among you is like the sanctity of this sacred day, in this sacred month, in this sacred land."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'allah the most truthful of all who speak said and do not transgress indeed allah does not love those who transgress and he said and do not consume your wealth among yourselves through falsehood the messenger of allah said the sanctity of your wealth among you is like the sanctity of this sacred day in this sacred month in this sacred land', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 159, NULL, 'Whoever comes into unlawful wealth is therefore obligated to repent and to free himself of it. Repentance admits of no other form than this: he must rid himself of that wealth and return it to its owners, if he knows who they are. If he does not know them, he places it in the treasury of the Muslims until the one entitled to it comes forward. If no path to that exists, he gives it in charity — and if its owners later make themselves known to him, he makes restitution to them. He may neither keep that wealth nor draw any benefit from it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whoever comes into unlawful wealth is therefore obligated to repent and to free himself of it repentance admits of no other form than this he must rid himself of that wealth and return it to its owners if he knows who they are if he does not know them he places it in the treasury of the muslims until the one entitled to it comes forward if no path to that exists he gives it in charity and if its owners later make themselves known to him he makes restitution to them he may neither keep that wealth nor draw any benefit from it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 160, NULL, 'As for the one who has been wronged — who has had something usurped from him, or stolen — he must not himself transgress, usurp, or steal from the one who wronged him, even if he has the power to do so. Usurpation, betrayal, theft, and transgression are all forbidden, without exception. That a forbidden act has been done to a person does not permit him to do the like of it in return. Rather, he must hold to his trust: he must not betray, and he must not steal. Al-Sadiq Jafar ibn Muhammad said: "Render up your trusts, and do not betray the one who betrayed you."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'as for the one who has been wronged who has had something usurped from him or stolen he must not himself transgress usurp or steal from the one who wronged him even if he has the power to do so usurpation betrayal theft and transgression are all forbidden without exception that a forbidden act has been done to a person does not permit him to do the like of it in return rather he must hold to his trust he must not betray and he must not steal al sadiq jafar ibn muhammad said render up your trusts and do not betray the one who betrayed you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 161, NULL, 'Whoever usurps a slave woman and she bears him a child must return her to the one from whom she was taken, and his child by her belongs as a slave to that same person. If he usurped her and then sold her to a man who, knowing she was usurped, fathered a child by her, she is returned to her original owner, the buyer pays the value of the child, and he then has recourse against the usurping seller for her price and for the value of the child he surrendered.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whoever usurps a slave woman and she bears him a child must return her to the one from whom she was taken and his child by her belongs as a slave to that same person if he usurped her and then sold her to a man who knowing she was usurped fathered a child by her she is returned to her original owner the buyer pays the value of the child and he then has recourse against the usurping seller for her price and for the value of the child he surrendered', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 162, NULL, 'Whoever usurps a slave, a beast, or anything whatever, and it perishes in his possession, owes its value or its like-in-kind. If the usurped property increased in his hands, the increase belongs to its rightful owner. If it diminished, the usurper is liable for what was lost. If he hired it out, the hire belongs to its owner. If what he seized were sheep or other animals that bred, then the animals and their offspring alike belong to the one from whom they were taken.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whoever usurps a slave a beast or anything whatever and it perishes in his possession owes its value or its like in kind if the usurped property increased in his hands the increase belongs to its rightful owner if it diminished the usurper is liable for what was lost if he hired it out the hire belongs to its owner if what he seized were sheep or other animals that bred then the animals and their offspring alike belong to the one from whom they were taken', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 163, NULL, 'Whoever assaults something belonging to the instruments of frivolity and breaks it, or pours out wine or any intoxicant, bears no liability for that.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whoever assaults something belonging to the instruments of frivolity and breaks it or pours out wine or any intoxicant bears no liability for that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 164, NULL, 'Whoever has wealth stolen or usurped from him and then comes upon the very thing itself may take it back, but it is not lawful for him to take some substitute in its place.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whoever has wealth stolen or usurped from him and then comes upon the very thing itself may take it back but it is not lawful for him to take some substitute in its place', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 165, NULL, 'On loans and deposits', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'on loans and deposits', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 166, NULL, 'Allah, mighty and majestic, said: "And do not forget generosity among yourselves." The Messenger of Allah said: "A loan of use is an act of affection." Jafar ibn Muhammad said: "The loan, the lending of an article, and the hosting of the guest are obligations within the Sunnah." And Ali said: "Whoever guards the property of an orphan, Allah, mighty and majestic, makes Paradise obligatory for him, just as He has made the Fire obligatory for the one who devours it." As sin falls upon the one who betrays a trust, so the reward belongs to the one who receives a trust and renders it faithfully.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'allah mighty and majestic said and do not forget generosity among yourselves the messenger of allah said a loan of use is an act of affection jafar ibn muhammad said the loan the lending of an article and the hosting of the guest are obligations within the sunnah and ali said whoever guards the property of an orphan allah mighty and majestic makes paradise obligatory for him just as he has made the fire obligatory for the one who devours it as sin falls upon the one who betrays a trust so the reward belongs to the one who receives a trust and renders it faithfully', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 167, NULL, 'Whoever borrows an article and stands surety for it to the lender, and it then perishes or is lost in his keeping, is liable to make it good — whether or not any fault on his part caused the loss. If he did not stand surety for it but then wronged it, transgressed against it, or wasted it, he is likewise liable. If, however, it perished or was damaged through no wrongdoing and no neglect of his, no liability falls upon him, and his word is accepted if he is a man of trust. If he borrows dinars or dirhams and they perish', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whoever borrows an article and stands surety for it to the lender and it then perishes or is lost in his keeping is liable to make it good whether or not any fault on his part caused the loss if he did not stand surety for it but then wronged it transgressed against it or wasted it he is likewise liable if however it perished or was damaged through no wrongdoing and no neglect of his no liability falls upon him and his word is accepted if he is a man of trust if he borrows dinars or dirhams and they perish', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 168, NULL, 'He is liable for them, because they become a loan. If, however, he borrows something identified as a particular item — a specific dirham, for instance — it cannot rightly be treated as a loan. Whoever borrows a piece of property and then mortgages or sells it is subject to this rule: if the owner is at hand, the owner may recover it, and the buyer may seek restitution from the seller for the price paid. Whoever pledges borrowed property is liable for an equivalent pledge, or for whatever that pledge was worth, unless the owner of the borrowed item had given permission to pledge or sell it. If the property remains in his possession, no obligation falls upon him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'he is liable for them because they become a loan if however he borrows something identified as a particular item a specific dirham for instance it cannot rightly be treated as a loan whoever borrows a piece of property and then mortgages or sells it is subject to this rule if the owner is at hand the owner may recover it and the buyer may seek restitution from the seller for the price paid whoever pledges borrowed property is liable for an equivalent pledge or for whatever that pledge was worth unless the owner of the borrowed item had given permission to pledge or sell it if the property remains in his possession no obligation falls upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 169, NULL, 'Whoever receives a deposit must preserve and safeguard it as a person of comparable standing would. If it is destroyed or lost through no act of wrongdoing on his part, after he has taken proper care of it, no liability falls upon him. If, however, he loses it through negligence, misuse, or transgression, he is liable for it. If the owner of the deposit instructs him to deliver it to a certain man, and he claims to have done so, but that man denies receiving it and the owner does not accept his word, then he must pay for it after all of them have sworn oaths.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whoever receives a deposit must preserve and safeguard it as a person of comparable standing would if it is destroyed or lost through no act of wrongdoing on his part after he has taken proper care of it no liability falls upon him if however he loses it through negligence misuse or transgression he is liable for it if the owner of the deposit instructs him to deliver it to a certain man and he claims to have done so but that man denies receiving it and the owner does not accept his word then he must pay for it after all of them have sworn oaths', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 170, NULL, 'A holder of a deposit may draw upon it if he carries a corresponding debt and can attest to that; the deposit then becomes his responsibility. If a child or an insane person entrusts a deposit and it is lost, no recourse falls against the one who held it, for he was misled through no fault of his own. If a slave receives a deposit without his master''s permission and the deposit is lost, the slave bears responsibility for it — though the claim is made against him only once he is freed, not against his master. If two men jointly entrust something to a third party and one of them comes to claim it while the other is absent, the holder should release only half, since it was deposited jointly; he may not hand the whole to one without the other being present. Nor may the one present take any portion until his companion arrives — unless the absent party has died and his heirs come in his stead, in which case the deposit may be released to them. This is the position of the Ahl al-Bayt.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'a holder of a deposit may draw upon it if he carries a corresponding debt and can attest to that the deposit then becomes his responsibility if a child or an insane person entrusts a deposit and it is lost no recourse falls against the one who held it for he was misled through no fault of his own if a slave receives a deposit without his masters permission and the deposit is lost the slave bears responsibility for it though the claim is made against him only once he is freed not against his master if two men jointly entrust something to a third party and one of them comes to claim it while the other is absent the holder should release only half since it was deposited jointly he may not hand the whole to one without the other being present nor may the one present take any portion until his companion arrives unless the absent party has died and his heirs come in his stead in which case the deposit may be released to them this is the position of the ahl al bayt', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 171, NULL, 'On Found Property, the Foundling, and Related Matters', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'on found property the foundling and related matters', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 172, NULL, 'Whoever finds lost property within the Haram of Makkah, or in any place where he is confident of its safety and does not fear it will be taken, should announce it and leave it where it lies until its owner returns for it. If the property is not within the Haram and he fears for its safety, he should take it up if he is able, for he cannot simply abandon it — the Messenger of Allah, (ع), forbade the wasting of wealth. Once he takes it, he announces it publicly. If the owner comes forward and can testify to it or describe it, it is returned to him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whoever finds lost property within the haram of makkah or in any place where he is confident of its safety and does not fear it will be taken should announce it and leave it where it lies until its owner returns for it if the property is not within the haram and he fears for its safety he should take it up if he is able for he cannot simply abandon it the messenger of allah ع forbade the wasting of wealth once he takes it he announces it publicly if the owner comes forward and can testify to it or describe it it is returned to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 173, NULL, 'If no claimant appears within the period specified in the Sunnah, during which he has continued to make his announcement, he places it in the treasury of the Muslims if a means of doing so is available. If none is available, he has two options:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'if no claimant appears within the period specified in the sunnah during which he has continued to make his announcement he places it in the treasury of the muslims if a means of doing so is available if none is available he has two options', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 174, NULL, 'He may give the property in charity on the owner''s behalf, on the understanding that should the owner later come forward, he restores its value to him. He may keep it with him, given his inability to deposit it in the treasury of the Muslims.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'he may give the property in charity on the owners behalf on the understanding that should the owner later come forward he restores its value to him he may keep it with him given his inability to deposit it in the treasury of the muslims', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 175, NULL, 'Picking up a stray camel found in a safe place is disliked, because such animals can endure thirst and hunger long enough to reach their owners. If time passes and the finder fears for the animal''s safety, however, he may take it in and care for it, spending on its upkeep, to be reimbursed by the owners when they come to reclaim it. Should no claimant appear after a prolonged period, the matter is referred to the governing authority, who sells the animal, retains the proceeds, and treats the price as found property is treated — whether the animal in question is a sheep, cattle, a slave, or any other beast. No stray animal is simply left where it was found; the procedure described above applies in every case. If a claimant does come forward and demands a fee from the finder, that fee is not obligatory, for God Almighty has made the safeguarding of believers'' wealth a duty that believers owe one another. The finder receives a reward when his intention was righteous, and whatever he spent in caring for the animal is to be repaid to him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'picking up a stray camel found in a safe place is disliked because such animals can endure thirst and hunger long enough to reach their owners if time passes and the finder fears for the animals safety however he may take it in and care for it spending on its upkeep to be reimbursed by the owners when they come to reclaim it should no claimant appear after a prolonged period the matter is referred to the governing authority who sells the animal retains the proceeds and treats the price as found property is treated whether the animal in question is a sheep cattle a slave or any other beast no stray animal is simply left where it was found the procedure described above applies in every case if a claimant does come forward and demands a fee from the finder that fee is not obligatory for god almighty has made the safeguarding of believers wealth a duty that believers owe one another the finder receives a reward when his intention was righteous and whatever he spent in caring for the animal is to be repaid to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 176, NULL, 'Whoever finds perishable property that would spoil if left in place should sell it and handle the proceeds as he would handle found property. Whoever finds property buried inside someone''s home: that property belongs to the people of that home, provided they claim it — even if the structure is a ruin that people pass through, in which case the standard procedure for found property applies. If what is found was buried and bears the appearance of wealth from a prior age, it is conveyed to the treasury of the Muslims. What is obligatory for the finder in such cases has already been set out.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whoever finds perishable property that would spoil if left in place should sell it and handle the proceeds as he would handle found property whoever finds property buried inside someones home that property belongs to the people of that home provided they claim it even if the structure is a ruin that people pass through in which case the standard procedure for found property applies if what is found was buried and bears the appearance of wealth from a prior age it is conveyed to the treasury of the muslims what is obligatory for the finder in such cases has already been set out', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 177, NULL, 'A foundling whose parents are unknown is considered free. His inheritance passes to the treasury of the Muslims; no relative inherits from him by lineage, and he neither inherits nor is inherited from except through the bond of marriage. When he reaches adulthood and his circumstances improve, and the person who took him in and raised him seeks repayment of the costs of that upbringing, the foundling is obliged to make it good. Whoever offers a reward for the return of a runaway slave or a stray animal, and the search is carried out, is bound to pay that reward as he himself stipulated. All of this is the position of the Ahl al-Bayt.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'a foundling whose parents are unknown is considered free his inheritance passes to the treasury of the muslims no relative inherits from him by lineage and he neither inherits nor is inherited from except through the bond of marriage when he reaches adulthood and his circumstances improve and the person who took him in and raised him seeks repayment of the costs of that upbringing the foundling is obliged to make it good whoever offers a reward for the return of a runaway slave or a stray animal and the search is carried out is bound to pay that reward as he himself stipulated all of this is the position of the ahl al bayt', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 178, NULL, 'On Division and Property Structures', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'on division and property structures', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 179, NULL, 'Whatever lies between dwelling walls, and whatever wealth is held between partners that admits of division without being ruined by it, is to be divided among them if any or all of the partners request it. If the thing is of a kind that division would ruin, or that would harm one or more of the partners when divided, it is sold and the proceeds distributed. There is no objection to dividing a house so that its lower portion belongs to some partners and its upper portion to others. The roof of the lower level and its walls are the responsibility of the owner of the lower portion; what lies above belongs to the owner of the upper level, and the ground beneath that upper level is likewise the upper owner''s. If the lower portion falls into disrepair through no fault of the upper owner, the lower owner is responsible for its repair, as he is for the lower walls upon which the upper level rests. Whoever causes damage to any part of the structure is bound to repair what he has damaged. Everything belonging to the lower level is the lower owner''s responsibility to repair, because it is his property — even though the upper level is borne upon it and rests upon it — and on that basis the house is valued at the time of division.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whatever lies between dwelling walls and whatever wealth is held between partners that admits of division without being ruined by it is to be divided among them if any or all of the partners request it if the thing is of a kind that division would ruin or that would harm one or more of the partners when divided it is sold and the proceeds distributed there is no objection to dividing a house so that its lower portion belongs to some partners and its upper portion to others the roof of the lower level and its walls are the responsibility of the owner of the lower portion what lies above belongs to the owner of the upper level and the ground beneath that upper level is likewise the upper owners if the lower portion falls into disrepair through no fault of the upper owner the lower owner is responsible for its repair as he is for the lower walls upon which the upper level rests whoever causes damage to any part of the structure is bound to repair what he has damaged everything belonging to the lower level is the lower owners responsibility to repair because it is his property even though the upper level is borne upon it and rests upon it and on that basis the house is valued at the time of division', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 180, NULL, 'When a wall stands between two men and it falls, both are obliged to rebuild it. If one of them rebuilds it alone, the other may not benefit from it until he pays half the cost. If the wall belongs to one of them alone and it falls, that owner is obliged to rebuild it; and if he abandons it and the other man rebuilds it in his place, the one who abandoned it retains no right in it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'when a wall stands between two men and it falls both are obliged to rebuild it if one of them rebuilds it alone the other may not benefit from it until he pays half the cost if the wall belongs to one of them alone and it falls that owner is obliged to rebuild it and if he abandons it and the other man rebuilds it in his place the one who abandoned it retains no right in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 181, NULL, 'No one may open an aperture in his wall through which he can look into his neighbor''s private quarters. If, however, he opens it for light and air, and it affords no view into those quarters, he is entitled to do so — and his neighbor, in turn, is entitled to build a wall within his own property to block it, should he wish.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'no one may open an aperture in his wall through which he can look into his neighbors private quarters if however he opens it for light and air and it affords no view into those quarters he is entitled to do so and his neighbor in turn is entitled to build a wall within his own property to block it should he wish', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 182, NULL, 'No one may be prevented from building within his own property in a way that screens a neighbor''s view, provided he acts within his right.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'no one may be prevented from building within his own property in a way that screens a neighbors view provided he acts within his right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 183, NULL, 'Whoever opens a door onto a thoroughfare, or digs a well within the bounds of his own wall, is not to be prevented from doing so when the street in question is a passable, through-running public road. If it gives onto a dead-end lane, he may not do so except with the permission of those whose path runs through it. If it stands at the very end of the lane, where none of them has a path past it, he may do as he wishes in the portion adjoining him through which no one else passes.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whoever opens a door onto a thoroughfare or digs a well within the bounds of his own wall is not to be prevented from doing so when the street in question is a passable through running public road if it gives onto a dead end lane he may not do so except with the permission of those whose path runs through it if it stands at the very end of the lane where none of them has a path past it he may do as he wishes in the portion adjoining him through which no one else passes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 184, NULL, 'No one should divert a public, through-running road from its course. If, however, the road belongs to him and lies entirely at his disposal, the diversion is his to make.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'no one should divert a public through running road from its course if however the road belongs to him and lies entirely at his disposal the diversion is his to make', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 185, NULL, 'All of this is the position of the Ahl al-Bayt.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'all of this is the position of the ahl al bayt', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 186, NULL, 'On Testimony', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'on testimony', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 187, NULL, 'Al-Baqarah: 282رِّجَالِكُمْ ۖ فَإِن لَّمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌۭ وَٱمْرَأَتَانِ مِمَّن تَرْضَوْنَ مِنَ ٱلشُّهَدَآءِ', '', 'رِّجَالِكُمْ ۖ فَإِن لَّمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌۭ وَٱمْرَأَتَانِ مِمَّن تَرْضَوْنَ مِنَ ٱلشُّهَدَآءِ', 'Al-Baqarah: 282', 2, 282, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'al baqarah 282رجالكم فان لم يكونا رجلين فرجل وامراتان ممن ترضون من الشهداء', 'رجالكم فان لم يكونا رجلين فرجل وامراتان ممن ترضون من الشهداء');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 188, NULL, 'Allah Almighty said, "Establish the testimony for the sake of Allah" (Al-Talaq: 2), and "Call to witness two witnesses from among your men; and if there are not two men, then one man and two women from among those whom you approve as witnesses" (Al-Baqarah: 282), and "Let two just men from among you bear witness" (Al-Talaq: 2). He also said, "Do not conceal testimony; whoever conceals it, his heart is sinful" (Al-Baqarah: 283), and "That is nearer to their bearing witness in its proper form" (Al-Maidah: 108), and "And shun the word of falsehood" (Al-Hajj: 30).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'allah almighty said establish the testimony for the sake of allah al talaq 2 and call to witness two witnesses from among your men and if there are not two men then one man and two women from among those whom you approve as witnesses al baqarah 282 and let two just men from among you bear witness al talaq 2 he also said do not conceal testimony whoever conceals it his heart is sinful al baqarah 283 and that is nearer to their bearing witness in its proper form al maidah 108 and and shun the word of falsehood al hajj 30', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 189, NULL, 'The Messenger of Allah said that whoever conceals knowledge he possesses will come on the Day of Resurrection bridled with a bridle of fire. He, (ع), also said that the false witness will be raised on the Day of Resurrection lapping at his tongue in the Fire as a dog laps its tongue in a vessel. And he said that the false witness is among the reviled. Abu Jafar Muhammad ibn Ali said that the witness must deliver what he was asked to witness and must fear Allah his Lord, for it is among the forms of false witness that a man bears witness to what he does not know and denies what he does know. Whoever bears false witness, and this becomes known of him, is given a painful flogging, is paraded about, and his deed is made public — and he is liable for whatever was lost through his testimony.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the messenger of allah said that whoever conceals knowledge he possesses will come on the day of resurrection bridled with a bridle of fire he ع also said that the false witness will be raised on the day of resurrection lapping at his tongue in the fire as a dog laps its tongue in a vessel and he said that the false witness is among the reviled abu jafar muhammad ibn ali said that the witness must deliver what he was asked to witness and must fear allah his lord for it is among the forms of false witness that a man bears witness to what he does not know and denies what he does know whoever bears false witness and this becomes known of him is given a painful flogging is paraded about and his deed is made public and he is liable for whatever was lost through his testimony', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 190, NULL, 'The testimony of a just believer is admissible on behalf of anyone, whether near of kin or distant. A just slave''s testimony is likewise admissible, except in favor of his masters or in any matter that would result in his manumission; once he has been freed from that bond, however, his testimony in such a matter becomes admissible. The testimony of boys in a bloodshed case carries the weight of a presumption upon which the qasama oath may be administered, but it is not admissible in any other matter until they reach maturity.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the testimony of a just believer is admissible on behalf of anyone whether near of kin or distant a just slaves testimony is likewise admissible except in favor of his masters or in any matter that would result in his manumission once he has been freed from that bond however his testimony in such a matter becomes admissible the testimony of boys in a bloodshed case carries the weight of a presumption upon which the qasama oath may be administered but it is not admissible in any other matter until they reach maturity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 191, NULL, 'The following testimony is inadmissible:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the following testimony is inadmissible', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 192, NULL, 'Two suspect persons testifying together One who is himself under accusation A child of adultery A partner testifying against his partner in a matter that lies between the two of them — though his testimony is admissible in matters outside their shared dealings, provided he is just', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'two suspect persons testifying together one who is himself under accusation a child of adultery a partner testifying against his partner in a matter that lies between the two of them though his testimony is admissible in matters outside their shared dealings provided he is just', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 193, NULL, 'A follower, a hired man, or a servant who is just may testify on behalf of the one he serves, works for, or follows, except in any matter that would draw a benefit to himself or in which he is suspect. A neighbor may not testify in his own favor. The testimony of an adversary against his opponent is inadmissible, as is the testimony of people of deviant inclinations against the believers.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'a follower a hired man or a servant who is just may testify on behalf of the one he serves works for or follows except in any matter that would draw a benefit to himself or in which he is suspect a neighbor may not testify in his own favor the testimony of an adversary against his opponent is inadmissible as is the testimony of people of deviant inclinations against the believers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 194, NULL, 'If a slanderer repents, his testimony becomes admissible. If a witness''s testimony has been established and the one testified against then challenges him — bringing forward just witnesses who discredit him on grounds of something objectionable, of suspicion, or of conduct unbecoming of just people — that testimony is set aside.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'if a slanderer repents his testimony becomes admissible if a witnesss testimony has been established and the one testified against then challenges him bringing forward just witnesses who discredit him on grounds of something objectionable of suspicion or of conduct unbecoming of just people that testimony is set aside', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 195, NULL, 'Whoever prays at the congregational mosque, presents himself well, and has no known fault to his name is an admissible witness, unless grounds for discrediting him are established.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whoever prays at the congregational mosque presents himself well and has no known fault to his name is an admissible witness unless grounds for discrediting him are established', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 196, NULL, 'The testimony of a Muslim is admissible against the people of shirk, but the testimony of a polytheist is not admissible against Muslims. The one exception concerns a bequest made during travel when no other witness is available — in that case, the polytheist''s testimony stands, provided he swears an oath alongside it. The testimony of non-Muslims against one another is admissible when it is sound within their own religion and nothing discrediting is known of them.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the testimony of a muslim is admissible against the people of shirk but the testimony of a polytheist is not admissible against muslims the one exception concerns a bequest made during travel when no other witness is available in that case the polytheists testimony stands provided he swears an oath alongside it the testimony of non muslims against one another is admissible when it is sound within their own religion and nothing discrediting is known of them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 197, NULL, 'If a person gives testimony while still in a state of disbelief, or while still a minor, and thereafter the disbeliever embraces Islam and the minor reaches maturity, their testimony is admissible — provided they are just at the time they deliver it. The exception is when that testimony was already given earlier and was at that time rejected: in such a case, it must be given afresh.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'if a person gives testimony while still in a state of disbelief or while still a minor and thereafter the disbeliever embraces islam and the minor reaches maturity their testimony is admissible provided they are just at the time they deliver it the exception is when that testimony was already given earlier and was at that time rejected in such a case it must be given afresh', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 198, NULL, 'The testimony of women is admissible in matters of marriage and wealth, but not in divorce, prescribed punishments, or anything that falls between those categories. If three men and two women testify to adultery, stoning becomes obligatory; but if there are two men and four women, their testimony to adultery is not admissible. Women''s testimony is admissible in the matter of istihlal — the cry of the newborn — and the testimony of a single midwife is accepted if she is just and no other woman is present. When a newborn cries and then dies, that cry establishes that it was born alive. Women''s testimony is not admissible for sighting the crescent of Ramadan, and so cannot initiate or end the fast; it is, however, admissible in matters of the waiting period, the postpartum period, and those things concerning women that men are not permitted to witness.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the testimony of women is admissible in matters of marriage and wealth but not in divorce prescribed punishments or anything that falls between those categories if three men and two women testify to adultery stoning becomes obligatory but if there are two men and four women their testimony to adultery is not admissible womens testimony is admissible in the matter of istihlal the cry of the newborn and the testimony of a single midwife is accepted if she is just and no other woman is present when a newborn cries and then dies that cry establishes that it was born alive womens testimony is not admissible for sighting the crescent of ramadan and so cannot initiate or end the fast it is however admissible in matters of the waiting period the postpartum period and those things concerning women that men are not permitted to witness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 199, NULL, 'No testimony may be given upon another''s testimony in cases involving a prescribed punishment, killing, or retaliation. Testimony relayed on behalf of a single original witness requires two men to carry it, and it is only admissible under specific conditions:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'no testimony may be given upon anothers testimony in cases involving a prescribed punishment killing or retaliation testimony relayed on behalf of a single original witness requires two men to carry it and it is only admissible under specific conditions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 200, NULL, 'The original witness is absent in a place distant enough to permit shortening the prayer and breaking the fast while traveling. The original witness is ill or infirm and unable to attend the judge''s session. The original witness has died after entrusting his testimony to others.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the original witness is absent in a place distant enough to permit shortening the prayer and breaking the fast while traveling the original witness is ill or infirm and unable to attend the judges session the original witness has died after entrusting his testimony to others', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 201, NULL, 'If the original witness is present and in sound health, no one may testify in his place — he must appear and testify in person. A witness may only testify to what he himself knows.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'if the original witness is present and in sound health no one may testify in his place he must appear and testify in person a witness may only testify to what he himself knows', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 202, NULL, 'Az-Zukhruf: 86إِلَّا مَن شَهِدَ بِٱلْحَقِّ وَهُمْ يَعْلَمُونَ', '', 'إِلَّا مَن شَهِدَ بِٱلْحَقِّ وَهُمْ يَعْلَمُونَ', 'Az-Zukhruf: 86', 43, 86, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'az zukhruf 86الا من شهد بالحق وهم يعلمون', 'الا من شهد بالحق وهم يعلمون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 203, NULL, 'If the witnesses disagree over a divorce — one testifying that he divorced her in accordance with the prescribed waiting period and the other testifying otherwise — their testimony is inadmissible. If they disagree over the dowry, one testifying to the lesser amount and the other to the greater, the woman has a choice: she may swear an oath alongside the witness who testified to the greater amount and claim it, or she may take the lesser amount without an oath — unless her adversary wishes to swear against her in that case. A man may swear an oath together with his two witnesses, just as such an oath is admissible on behalf of one for whom two witnesses have already testified, for rights are sometimes forfeited in ways unknown both to the witnesses and to the one against whom testimony is given. No one may bear witness upon a written document unless he can establish his own testimony to it and knows it for certain. Allah, the most truthful of all speakers, said:', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'if the witnesses disagree over a divorce one testifying that he divorced her in accordance with the prescribed waiting period and the other testifying otherwise their testimony is inadmissible if they disagree over the dowry one testifying to the lesser amount and the other to the greater the woman has a choice she may swear an oath alongside the witness who testified to the greater amount and claim it or she may take the lesser amount without an oath unless her adversary wishes to swear against her in that case a man may swear an oath together with his two witnesses just as such an oath is admissible on behalf of one for whom two witnesses have already testified for rights are sometimes forfeited in ways unknown both to the witnesses and to the one against whom testimony is given no one may bear witness upon a written document unless he can establish his own testimony to it and knows it for certain allah the most truthful of all speakers said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 204, NULL, 'Sayingإِلَّا مَن شَهِدَ بِٱلْحَقِّ وَهُمْ يَعْلَمُونَ"Except for those who bear witness to the truth while they know." (Al-Zukhruf: 86)', '', NULL, 'Saying', NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'sayingالا من شهد بالحق وهم يعلمون except for those who bear witness to the truth while they know al zukhruf 86', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 205, NULL, 'Al-Baqarah: 282رِّجَالِكُمْ ۖ فَإِن لَّمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌۭ وَٱمْرَأَتَانِ مِمَّن تَرْضَوْنَ مِنَ ٱلشُّهَدَآءِ', '', 'رِّجَالِكُمْ ۖ فَإِن لَّمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌۭ وَٱمْرَأَتَانِ مِمَّن تَرْضَوْنَ مِنَ ٱلشُّهَدَآءِ', 'Al-Baqarah: 282', 2, 282, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'al baqarah 282رجالكم فان لم يكونا رجلين فرجل وامراتان ممن ترضون من الشهداء', 'رجالكم فان لم يكونا رجلين فرجل وامراتان ممن ترضون من الشهداء');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 206, NULL, 'If witnesses give their testimony and then seek to retract it before judgment is issued, the retraction is accepted and no ruling is made upon their testimony. If they seek to retract after judgment has been issued, the retraction is not accepted, and they are liable for whatever was lost as a result of their testimony.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'if witnesses give their testimony and then seek to retract it before judgment is issued the retraction is accepted and no ruling is made upon their testimony if they seek to retract after judgment has been issued the retraction is not accepted and they are liable for whatever was lost as a result of their testimony', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 207, NULL, 'Whoever is summoned to give testimony may not refuse, for Allah, exalted be He, declared: "And let not the witnesses refuse when they are called" (Al-Baqarah: 282). Whoever has witnessed something and is called upon to testify must do so, in keeping with the words of Allah Almighty: "Do not conceal testimony; whoever conceals it, his heart is sinful" (Al-Baqarah: 283).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whoever is summoned to give testimony may not refuse for allah exalted be he declared and let not the witnesses refuse when they are called al baqarah 282 whoever has witnessed something and is called upon to testify must do so in keeping with the words of allah almighty do not conceal testimony whoever conceals it his heart is sinful al baqarah 283', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 208, NULL, 'As for one who happens to overhear people settling their accounts, or hears one man acknowledge a debt to another, without having been asked to witness the exchange — if the one who made the acknowledgment later calls upon him to testify to what he heard, the choice is his: if he wishes, he may bear witness to what he heard.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'as for one who happens to overhear people settling their accounts or hears one man acknowledge a debt to another without having been asked to witness the exchange if the one who made the acknowledgment later calls upon him to testify to what he heard the choice is his if he wishes he may bear witness to what he heard', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 209, NULL, 'When asked to testify to what he heard, a man must do so truthfully; if he declines, no fault attaches to him, since he was never formally summoned as a witness. In matters of death, lineage, ancestral standing, and long-established possession, testimony on the basis of report and common knowledge is admissible — knowledge that has spread widely among the people. Through such report, people come to know one another. They testify to the death of one who has died, and to a man''s attribution to his father, though most of them never witnessed these things with their own eyes and never heard the acknowledgment firsthand; in such matters, the reported acknowledgment is accepted. All of this is the position of the Ahl al-Bayt, may Allah''s blessings be upon them.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'when asked to testify to what he heard a man must do so truthfully if he declines no fault attaches to him since he was never formally summoned as a witness in matters of death lineage ancestral standing and long established possession testimony on the basis of report and common knowledge is admissible knowledge that has spread widely among the people through such report people come to know one another they testify to the death of one who has died and to a mans attribution to his father though most of them never witnessed these things with their own eyes and never heard the acknowledgment firsthand in such matters the reported acknowledgment is accepted all of this is the position of the ahl al bayt may allahs blessings be upon them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 211, NULL, 'Al-Baqarah: 188وَلَا تَأْكُلُوٓا۟ أَمْوَلَكُم بَيْنَكُم بِٱلْبَطِلِ وَتُدْلُوا۟ بِهَآ إِلَى ٱلْحُكَّامِ لِتَأْكُلُوا۟ فَرِيقًۭا مِّنْ أَمْوَلِ ٱلنَّاسِ بِٱلْإِثْمِ وَأَنتُمْ تَعْلَمُونَ', '', 'وَلَا تَأْكُلُوٓا۟ أَمْوَلَكُم بَيْنَكُم بِٱلْبَطِلِ وَتُدْلُوا۟ بِهَآ إِلَى ٱلْحُكَّامِ لِتَأْكُلُوا۟ فَرِيقًۭا مِّنْ أَمْوَلِ ٱلنَّاسِ بِٱلْإِثْمِ وَأَنتُمْ تَعْلَمُونَ', 'Al-Baqarah: 188', 2, 188, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'al baqarah 188ولا تاكلوا امولكم بينكم بالبطل وتدلوا بها الي الحكام لتاكلوا فريقا من امول الناس بالاثم وانتم تعلمون', 'ولا تاكلوا امولكم بينكم بالبطل وتدلوا بها الي الحكام لتاكلوا فريقا من امول الناس بالاثم وانتم تعلمون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 212, NULL, 'Allah, exalted is He, said: "And do not consume one another''s wealth unjustly, nor proffer it to the judges that you may sinfully consume a portion of the people''s wealth while you know" ﴿وَلَا تَأْكُلُوا أَمْوَالَكُم بَيْنَكُم بِالْبَاطِلِ وَتُدْلُوا بِهَا إِلَى الْحُكَّامِ لِتَأْكُلُوا فَرِيقًا مِّنْ أَمْوَالِ النَّاسِ بِالْإِثْمِ وَأَنتُمْ تَعْلَمُونَ﴾ (Al-Baqarah: 188).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'allah exalted is he said and do not consume one anothers wealth unjustly nor proffer it to the judges that you may sinfully consume a portion of the peoples wealth while you know ولا تاكلوا اموالكم بينكم بالباطل وتدلوا بها الي الحكام لتاكلوا فريقا من اموال الناس بالاثم وانتم تعلمون al baqarah 188', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 213, NULL, 'And He said: "Indeed, Allah commands you to render trusts to their rightful owners, and when you judge between people to judge with justice" ﴿إِنَّ اللَّهَ يَأْمُرُكُمْ أَن تُؤَدُّوا الْأَمَانَاتِ إِلَىٰ أَهْلِهَا وَإِذَا حَكَمْتُم بَيْنَ النَّاسِ أَن تَحْكُمُوا بِالْعَدْلِ﴾ (Al-Nisa: 58).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'and he said indeed allah commands you to render trusts to their rightful owners and when you judge between people to judge with justice ان الله يامركم ان تودوا الامانات الي اهلها واذا حكمتم بين الناس ان تحكموا بالعدل al nisa 58', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 214, NULL, 'The Messenger of Allah and his family said: "I judge between you only by evidence and oaths. Some of you may be more persuasive in his plea than others; so whoever I award something out of his brother''s wealth, I have only cut off for him a piece of the Fire." He and his family likewise forbade the seizing of a Muslim''s wealth by a false oath. The ruling of a judge does not make lawful what is otherwise unlawful for the one in whose favor it is given. Whoever is awarded what is not rightfully his may not lawfully take it, for the judge rules by what is outwardly apparent, while Allah knows the unseen and the hidden.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the messenger of allah and his family said i judge between you only by evidence and oaths some of you may be more persuasive in his plea than others so whoever i award something out of his brothers wealth i have only cut off for him a piece of the fire he and his family likewise forbade the seizing of a muslims wealth by a false oath the ruling of a judge does not make lawful what is otherwise unlawful for the one in whose favor it is given whoever is awarded what is not rightfully his may not lawfully take it for the judge rules by what is outwardly apparent while allah knows the unseen and the hidden', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 215, NULL, 'The burden of evidence in claims over wealth lies upon the claimant, and the oath lies upon the one against whom the claim is made. That oath is sworn by Allah, mighty and majestic, and by none other. The Messenger of Allah and his family said: "Whoever swears, let him swear by Allah; and whoever has an oath sworn to him by Allah, let him accept it; and whoever does not do so is not a Muslim."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the burden of evidence in claims over wealth lies upon the claimant and the oath lies upon the one against whom the claim is made that oath is sworn by allah mighty and majestic and by none other the messenger of allah and his family said whoever swears let him swear by allah and whoever has an oath sworn to him by allah let him accept it and whoever does not do so is not a muslim', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 216, NULL, 'If the claimant presses his claim and the defendant denies it, the judge asks the defendant to swear. Should the defendant refer the oath back to the claimant — saying, "Let him swear to what he claims against me, and I will give it to him" — that is his right, for had the claimant wished to swear alongside his evidence, that too would have been his right. If the claimant then swears, judgment is given in his favor on the strength of his claim together with his oath. If, however, he declines to swear, the defendant is relieved of the obligation, nothing is awarded to the claimant, and nothing further lies against the defendant beyond this.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'if the claimant presses his claim and the defendant denies it the judge asks the defendant to swear should the defendant refer the oath back to the claimant saying let him swear to what he claims against me and i will give it to him that is his right for had the claimant wished to swear alongside his evidence that too would have been his right if the claimant then swears judgment is given in his favor on the strength of his claim together with his oath if however he declines to swear the defendant is relieved of the obligation nothing is awarded to the claimant and nothing further lies against the defendant beyond this', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 217, NULL, 'Once evidence has been established, the defendant has the right to ask the claimant to swear that his claim against him remains exactly as the testimony showed — that nothing of it, great or small, has lapsed. This right exists because rights, as has been noted, may lapse in ways the witnesses have no knowledge of. If the defendant stands to incur no liability unless the claimant swears, and the claimant has not requested that oath, a judge who is aware of this right should bring it to the claimant''s attention, since most people do not know what they are entitled to. Once informed, if the claimant asks for the oath it is administered; if he does not ask, the matter rests as it stands. Where the testimony concerns a minor or an absent party, the judge does not rule in the claimant''s favor until the claimant has sworn alongside the evidence. And if the claimant swears and judgment is given for him, but the defendant afterward produces upright witnesses, the judge grants the defendant his right and sets aside any weight that the claimant''s earlier oath might have carried.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'once evidence has been established the defendant has the right to ask the claimant to swear that his claim against him remains exactly as the testimony showed that nothing of it great or small has lapsed this right exists because rights as has been noted may lapse in ways the witnesses have no knowledge of if the defendant stands to incur no liability unless the claimant swears and the claimant has not requested that oath a judge who is aware of this right should bring it to the claimants attention since most people do not know what they are entitled to once informed if the claimant asks for the oath it is administered if he does not ask the matter rests as it stands where the testimony concerns a minor or an absent party the judge does not rule in the claimants favor until the claimant has sworn alongside the evidence and if the claimant swears and judgment is given for him but the defendant afterward produces upright witnesses the judge grants the defendant his right and sets aside any weight that the claimants earlier oath might have carried', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 218, NULL, 'Judgment on the testimony of a single witness together with the claimant''s oath is valid in matters of wealth alone; it does not apply to anything other than wealth.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'judgment on the testimony of a single witness together with the claimants oath is valid in matters of wealth alone it does not apply to anything other than wealth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 219, NULL, 'When the proofs are evenly matched over a single object — whether the object is in the hand of one of the two adversaries, in the hands of both together, or in neither''s hand — and each party brings upright witnesses, both adversaries are required to swear. If one declines the oath, the object is awarded to the one who swore, on the strength of his evidence. If both swear, the matter is settled by lot, and whichever party''s lot is drawn receives the object. The same applies when the object is in both their hands and both have sworn: the lot is cast between them. If the object is in the hand of a third party and both decline the oath, it is awarded to neither. Likewise, if the object is in the hand of one of them and the other declines the oath, it is not awarded to that other party but remains with the one who holds it; and if the holder also declines the oath, it still remains in his hand, and if he swears it is left with him in the same way.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'when the proofs are evenly matched over a single object whether the object is in the hand of one of the two adversaries in the hands of both together or in neithers hand and each party brings upright witnesses both adversaries are required to swear if one declines the oath the object is awarded to the one who swore on the strength of his evidence if both swear the matter is settled by lot and whichever partys lot is drawn receives the object the same applies when the object is in both their hands and both have sworn the lot is cast between them if the object is in the hand of a third party and both decline the oath it is awarded to neither likewise if the object is in the hand of one of them and the other declines the oath it is not awarded to that other party but remains with the one who holds it and if the holder also declines the oath it still remains in his hand and if he swears it is left with him in the same way', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 220, NULL, 'Where the testimony of one party establishes that the object originated with him — that it was bred or produced in his possession — while the testimony of the other asserts only that the object is his, without establishing its origin, the object is awarded to the party whose evidence accounts for both its origin and its increase.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'where the testimony of one party establishes that the object originated with him that it was bred or produced in his possession while the testimony of the other asserts only that the object is his without establishing its origin the object is awarded to the party whose evidence accounts for both its origin and its increase', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 221, NULL, 'Whoever willingly acknowledges that he is a slave is held to be a slave. Should he afterward claim his freedom, or should freedom be claimed on his behalf, that claim is not accepted without evidence. If, however, he made the acknowledgment of servitude under compulsion and then asserts that he is free, the burden of proof falls on whoever claims his servitude.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'whoever willingly acknowledges that he is a slave is held to be a slave should he afterward claim his freedom or should freedom be claimed on his behalf that claim is not accepted without evidence if however he made the acknowledgment of servitude under compulsion and then asserts that he is free the burden of proof falls on whoever claims his servitude', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 222, NULL, 'When a man receives dinars or dirhams from another and then returns to him alleging that some of the coin was defective — while the giver denies this — the giver must swear that he handed over only sound coin and that he knows of no defect in what he gave. Should the giver decline that oath, the recipient swears that the defect was indeed present in what was given to him, and the giver must then replace it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'when a man receives dinars or dirhams from another and then returns to him alleging that some of the coin was defective while the giver denies this the giver must swear that he handed over only sound coin and that he knows of no defect in what he gave should the giver decline that oath the recipient swears that the defect was indeed present in what was given to him and the giver must then replace it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 223, NULL, 'When a man and a woman dispute over the furnishings of a household — or their heirs dispute, or one of the original parties disputes with the heirs of the other — whoever among them produces evidence for what he or she claims is awarded it. If neither party has evidence, they swear against each other; whoever declines the oath is ruled against on the opponent''s claim in the matter disputed. If both decline to swear, or both swear, and neither has evidence, then the man receives what custom recognizes as belonging to men, and the woman receives what custom recognizes as belonging to women.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'when a man and a woman dispute over the furnishings of a household or their heirs dispute or one of the original parties disputes with the heirs of the other whoever among them produces evidence for what he or she claims is awarded it if neither party has evidence they swear against each other whoever declines the oath is ruled against on the opponents claim in the matter disputed if both decline to swear or both swear and neither has evidence then the man receives what custom recognizes as belonging to men and the woman receives what custom recognizes as belonging to women', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 224, NULL, 'When two men, or a group, lie with one woman within a single term — whether they are free men, slaves, or free polytheists — and she conceives, and each man claims the child, lots are cast; whoever''s lot is drawn is awarded the child, and paternity is attributed to him. If the lot falls to a polytheist while the child''s mother is a Muslim, the child is Muslim, and the polytheist holds no claim over the child of a Muslim woman. If the mother is herself a polytheist and the lot falls to the polytheist, the child follows the religion of them both. If the lot falls to a Muslim or to a freed slave, the child is a free Muslim.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'when two men or a group lie with one woman within a single term whether they are free men slaves or free polytheists and she conceives and each man claims the child lots are cast whoevers lot is drawn is awarded the child and paternity is attributed to him if the lot falls to a polytheist while the childs mother is a muslim the child is muslim and the polytheist holds no claim over the child of a muslim woman if the mother is herself a polytheist and the lot falls to the polytheist the child follows the religion of them both if the lot falls to a muslim or to a freed slave the child is a free muslim', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 225, NULL, 'When someone sends an item with a bearer to a third party, and the bearer says he delivered it while the intended recipient denies receiving it, the bearer''s word is not accepted without evidence. If, however, the item was delivered and the sender then instructed the bearer to give it as charity, and the bearer says he has already done so, his word is accepted along with his oath — provided he is under suspicion. All of this is the position of the Ahl al-Bayt, may.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'when someone sends an item with a bearer to a third party and the bearer says he delivered it while the intended recipient denies receiving it the bearers word is not accepted without evidence if however the item was delivered and the sender then instructed the bearer to give it as charity and the bearer says he has already done so his word is accepted along with his oath provided he is under suspicion all of this is the position of the ahl al bayt may', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'verse', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 227, NULL, 'Sad: 26يَدَاوُۥدُ إِنَّا جَعَلْنَكَ خَلِيفَةًۭ فِى ٱلْأَرْضِ فَٱحْكُم بَيْنَ ٱلنَّاسِ بِٱلْحَقِّ', '', 'يَدَاوُۥدُ إِنَّا جَعَلْنَكَ خَلِيفَةًۭ فِى ٱلْأَرْضِ فَٱحْكُم بَيْنَ ٱلنَّاسِ بِٱلْحَقِّ', 'Sad: 26', 38, 26, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'sad 26يداود انا جعلنك خليفه في الارض فاحكم بين الناس بالحق', 'يداود انا جعلنك خليفه في الارض فاحكم بين الناس بالحق');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 228, NULL, 'Allah, mighty and majestic, said: "O David, We have made you a vicegerent upon the earth, so judge between the people in truth" ﴿يَا دَاوُودُ إِنَّا جَعَلْنَاكَ خَلِيفَةً فِي الْأَرْضِ فَاحْكُم بَيْنَ النَّاسِ بِالْحَقِّ﴾ (Sad: 26). And He said: "And judge between them by what Allah has revealed" ﴿وَأَنِ احْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ﴾ (Al-Maidah: 49).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'allah mighty and majestic said o david we have made you a vicegerent upon the earth so judge between the people in truth يا داوود انا جعلناك خليفه في الارض فاحكم بين الناس بالحق sad 26 and he said and judge between them by what allah has revealed وان احكم بينهم بما انزل الله al maidah 49', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 229, NULL, 'And He said: "And whoever does not judge by what Allah has revealed, those are the disbelievers" ﴿وَمَن لَّمْ يَحْكُم بِمَا أَنزَلَ اللَّهُ فَأُولَٰئِكَ هُمُ الْكَافِرُونَ﴾ (Al-Maidah: 44). And He said: "And whoever does not judge by what Allah has revealed, those are the wrongdoers" ﴿وَمَن لَّمْ يَحْكُم بِمَا أَنزَلَ اللَّهُ فَأُولَٰئِكَ هُمُ الظَّالِمُونَ﴾ (Al-Maidah: 45).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'and he said and whoever does not judge by what allah has revealed those are the disbelievers ومن لم يحكم بما انزل الله فاوليك هم الكافرون al maidah 44 and he said and whoever does not judge by what allah has revealed those are the wrongdoers ومن لم يحكم بما انزل الله فاوليك هم الظالمون al maidah 45', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 230, NULL, 'And He said: "And whoever does not judge by what Allah has revealed, those are the defiantly disobedient" ﴿وَمَن لَّمْ يَحْكُم بِمَا أَنزَلَ اللَّهُ فَأُولَٰئِكَ هُمُ الْفَاسِقُونَ﴾ (Al-Maidah: 47).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'and he said and whoever does not judge by what allah has revealed those are the defiantly disobedient ومن لم يحكم بما انزل الله فاوليك هم الفاسقون al maidah 47', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 231, NULL, 'And He said: "Have you not seen those who claim to believe in what was revealed to you and what was revealed before you, yet wish to take their disputes to the Taghut, though they were commanded to reject it; and Satan wishes to lead them far astray" ﴿أَلَمْ تَرَ إِلَى الَّذِينَ يَزْعُمُونَ أَنَّهُمْ آمَنُوا بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ يُرِيدُونَ أَن يَتَحَاكَمُوا إِلَى الطَّاغُوتِ وَقَدْ أُمِرُوا أَن يَكْفُرُوا بِهِ وَيُرِيدُ الشَّيْطَانُ أَن يُضِلَّهُمْ ضَلَالًا بَعِيدًا﴾ (Al-Nisa: 60).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'and he said have you not seen those who claim to believe in what was revealed to you and what was revealed before you yet wish to take their disputes to the taghut though they were commanded to reject it and satan wishes to lead them far astray الم تر الي الذين يزعمون انهم امنوا بما انزل اليك وما انزل من قبلك يريدون ان يتحاكموا الي الطاغوت وقد امروا ان يكفروا به ويريد الشيطان ان يضلهم ضلالا بعيدا al nisa 60', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 232, NULL, 'The Messenger of Allah and his family said: "Do not ask for command, for whoever asks for it is left to it, and whoever is given it without asking is helped in it." He forbade anyone from putting himself forward for the office of judge. Yet for one whom a just imam has summoned to it, and who is competent in it, the proper course is not to hold back. It is not permitted to him to judge for a tyrannical imam, nor to judge while he has no knowledge of the science of judgment.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the messenger of allah and his family said do not ask for command for whoever asks for it is left to it and whoever is given it without asking is helped in it he forbade anyone from putting himself forward for the office of judge yet for one whom a just imam has summoned to it and who is competent in it the proper course is not to hold back it is not permitted to him to judge for a tyrannical imam nor to judge while he has no knowledge of the science of judgment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 233, NULL, 'Al-Kahf: 51كُنتُ مُتَّخِذَ ٱلْمُضِلِّينَ عَضُدًۭاThe Messenger of Allah and his family said: "Whoever gives a legal ruling without knowledge is cursed by the angels of heaven and the angels of the earth; and whoever judges and errs will come on the Day of Resurrection with his hands shackled to his neck."', '', NULL, 'Al-Kahf: 51', NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'al kahf 51كنت متخذ المضلين عضداthe messenger of allah and his family said whoever gives a legal ruling without knowledge is cursed by the angels of heaven and the angels of the earth and whoever judges and errs will come on the day of resurrection with his hands shackled to his neck', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 234, NULL, 'He forbade, and his family forbade, that one who has no knowledge be appointed to judge. And Ali, may the blessings of Allah be upon him, wrote to Rifaa: "Do not employ anyone whose word concerning us you cannot trust; otherwise Allah will be your adversary and will demand from you." When it was said to him concerning Muawiyah, "Were you to employ him, then once he has affirmed your authority you could dismiss him," he replied: "Where then is the word of Allah, mighty and majestic: And I would not take the misleaders as helpers ﴿وَمَا كُنتُ مُتَّخِذَ الْمُضِلِّينَ عَضُدًا﴾ (Al-Kahf: 51)?"', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'he forbade and his family forbade that one who has no knowledge be appointed to judge and ali may the blessings of allah be upon him wrote to rifaa do not employ anyone whose word concerning us you cannot trust otherwise allah will be your adversary and will demand from you when it was said to him concerning muawiyah were you to employ him then once he has affirmed your authority you could dismiss him he replied where then is the word of allah mighty and majestic and i would not take the misleaders as helpers وما كنت متخذ المضلين عضدا al kahf 51', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 235, NULL, 'He delivered a sermon, and within it he said: "As for what follows: my pledge is held in surety, and I stand answerable for it. For one who takes warning, godliness keeps watch, so that no people''s crop of piety is left to wither, and no rooted stock that rests upon piety is left to thirst. Truth and good belong to the one who knows his own measure, and it is ignorance enough in a man that he does not know his own measure.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'he delivered a sermon and within it he said as for what follows my pledge is held in surety and i stand answerable for it for one who takes warning godliness keeps watch so that no peoples crop of piety is left to wither and no rooted stock that rests upon piety is left to thirst truth and good belong to the one who knows his own measure and it is ignorance enough in a man that he does not know his own measure', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 236, NULL, '"Among the most hateful of creatures to Allah, mighty and majestic, are two men. One is a man whom Allah has abandoned to himself: he has swerved from the straight path, enamored of an innovation, given over to fasting and prayer within it, so that he becomes a trial for whoever is dazzled by his worship. He has strayed from the guidance of those who came before him and leads astray those who follow him after, bearing the weight of sins belonging to others whom he misled by his error.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'among the most hateful of creatures to allah mighty and majestic are two men one is a man whom allah has abandoned to himself he has swerved from the straight path enamored of an innovation given over to fasting and prayer within it so that he becomes a trial for whoever is dazzled by his worship he has strayed from the guidance of those who came before him and leads astray those who follow him after bearing the weight of sins belonging to others whom he misled by his error', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 237, NULL, '"The other is a man who has heaped up ignorance and moves among the rabble of the people, plunging into the murk of discord. The ignorant have named him a scholar, though he has not passed even a single sound day in knowledge. He hoards much of that whose little is better than its much, until he has drunk his fill from stagnant water and amassed what is of no worth.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the other is a man who has heaped up ignorance and moves among the rabble of the people plunging into the murk of discord the ignorant have named him a scholar though he has not passed even a single sound day in knowledge he hoards much of that whose little is better than its much until he has drunk his fill from stagnant water and amassed what is of no worth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 238, NULL, 'He sits among the people as a judge, appointing himself to resolve what has confounded others. When he differs from a judge who came before him, he offers no surety in his own ruling. When a difficult case is brought before him, he stuffs it with padding drawn from his own opinion and then cuts the matter short. He stands upon a web of doubts as a spider stands upon its own spinning, never knowing whether he has struck the mark or missed it entirely. When he is right, he fears he has erred; when he errs, he hopes he was right. He does not reckon with knowledge in anything he has rejected, and he cannot see that beyond what he has reached there may be further doctrine. When he measures one thing by another, he does not consider his own view false; and when a matter darkens over him, he conceals his ignorance, lest it be said that he does not know — and then he sits and delivers judgment. He is a key to obscurities, a rider of doubts, a man who flounders through ignorance. He does not excuse himself from what he does not know, that he might at least be safe; nor does he bite down with a firm tooth upon knowledge, that he might gain something from it. He scatters narrations as the wind scatters dry chaff. Inheritances weep on his account, and blood cries out on his account, and through his judgment what is lawful in marriage is made forbidden. By Allah, he is not competent to rule on what is brought before him, nor is he fit for what has been entrusted to him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'he sits among the people as a judge appointing himself to resolve what has confounded others when he differs from a judge who came before him he offers no surety in his own ruling when a difficult case is brought before him he stuffs it with padding drawn from his own opinion and then cuts the matter short he stands upon a web of doubts as a spider stands upon its own spinning never knowing whether he has struck the mark or missed it entirely when he is right he fears he has erred when he errs he hopes he was right he does not reckon with knowledge in anything he has rejected and he cannot see that beyond what he has reached there may be further doctrine when he measures one thing by another he does not consider his own view false and when a matter darkens over him he conceals his ignorance lest it be said that he does not know and then he sits and delivers judgment he is a key to obscurities a rider of doubts a man who flounders through ignorance he does not excuse himself from what he does not know that he might at least be safe nor does he bite down with a firm tooth upon knowledge that he might gain something from it he scatters narrations as the wind scatters dry chaff inheritances weep on his account and blood cries out on his account and through his judgment what is lawful in marriage is made forbidden by allah he is not competent to rule on what is brought before him nor is he fit for what has been entrusted to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 239, NULL, '"O people, look closely at the flaw of these veins of injustice, and hold fast to the obedience of one whose ignorance you cannot excuse; for the knowledge with which Adam, (ع), came down, and all that with which the prophets were favored, is found in the Seal of the Prophets, Muhammad and his family, and in his pure progeny. If you are led astray, then where are you going?"', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'o people look closely at the flaw of these veins of injustice and hold fast to the obedience of one whose ignorance you cannot excuse for the knowledge with which adam ع came down and all that with which the prophets were favored is found in the seal of the prophets muhammad and his family and in his pure progeny if you are led astray then where are you going', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 240, NULL, 'He said: "When the Messenger of Allah, (ع) and his family, sent me to Yemen, I said: O Messenger of Allah, you send me to judge between them while I am a young man and there are men of years among them, and I have no knowledge of judgment. He struck me upon my chest and said: O Allah, guide his heart and make his tongue firm. By the One who splits the seed and creates the soul, never after that did I doubt in judging between two parties."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'he said when the messenger of allah ع and his family sent me to yemen i said o messenger of allah you send me to judge between them while i am a young man and there are men of years among them and i have no knowledge of judgment he struck me upon my chest and said o allah guide his heart and make his tongue firm by the one who splits the seed and creates the soul never after that did i doubt in judging between two parties', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 241, NULL, 'He said: "Discords arise only from passions that are followed and rulings that are newly invented, in which the judgment of Allah is opposed and men give their loyalty to other men. Were truth pure and unmixed, there would be no disagreement; and were falsehood pure and unmixed, it would not be hidden from those of discernment. But a handful is taken from this and a handful from that, and the two are mingled together — and there it is that Satan masters his followers, while those for whom the best reward has already been decreed are saved."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'he said discords arise only from passions that are followed and rulings that are newly invented in which the judgment of allah is opposed and men give their loyalty to other men were truth pure and unmixed there would be no disagreement and were falsehood pure and unmixed it would not be hidden from those of discernment but a handful is taken from this and a handful from that and the two are mingled together and there it is that satan masters his followers while those for whom the best reward has already been decreed are saved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 242, NULL, 'The Master said: "The Muslims should not be placed under one who is greedy, lest he covet their wealth; nor under the ignorant, who would ruin them through his ignorance; nor under the miser, who would withhold their rights from them; nor under the harsh man, whose harshness would drive them to harshness in return; nor under one who betrays his trust over the public funds, taking from one people and giving to another; nor under one who takes bribes in judgment, so that the rights of the people are lost; nor under one who suspends the Sunnah, for he would destroy the community."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the master said the muslims should not be placed under one who is greedy lest he covet their wealth nor under the ignorant who would ruin them through his ignorance nor under the miser who would withhold their rights from them nor under the harsh man whose harshness would drive them to harshness in return nor under one who betrays his trust over the public funds taking from one people and giving to another nor under one who takes bribes in judgment so that the rights of the people are lost nor under one who suspends the sunnah for he would destroy the community', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 243, NULL, 'The Messenger of Allah and his family said: "Whoever acts wrongfully as a judge, whether deliberately or in error, is in the Fire." And Ali (ع) wrote to Rifaa, his judge over Ahvaz: "Know that this office of command is a trust; so whoever turns it into a betrayal, upon him is the curse of Allah until the Day of Resurrection."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the messenger of allah and his family said whoever acts wrongfully as a judge whether deliberately or in error is in the fire and ali ع wrote to rifaa his judge over ahvaz know that this office of command is a trust so whoever turns it into a betrayal upon him is the curse of allah until the day of resurrection', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 244, NULL, 'The Messenger of Allah and his family forbade the judge from favoring either party by giving one more of his attention and presence of mind than the other, and forbade him from speaking before he had heard the statements of both adversaries.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the messenger of allah and his family forbade the judge from favoring either party by giving one more of his attention and presence of mind than the other and forbade him from speaking before he had heard the statements of both adversaries', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 245, NULL, 'Abu Jafar Muhammad ibn Ali said: "Whoever among you knows anything of our rulings, let him be a judge among you, for I have made him a judge; so bring your disputes before him." And he said: "Whoever consumes unlawful gain consumes the bribe given in judgment."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'abu jafar muhammad ibn ali said whoever among you knows anything of our rulings let him be a judge among you for i have made him a judge so bring your disputes before him and he said whoever consumes unlawful gain consumes the bribe given in judgment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 246, NULL, 'The judge should deal equitably between the two adversaries in his ruling, treating them alike in his speech, his attention, and his regard, and he should not speak until he has heard the statements of both. He should not give judgment in the mosque, nor carry out a prescribed punishment within it, though there is no harm in his administering correction there to one who deserves it. He should possess dignity, deliberateness, and care in examining the condition of those he relies upon and admits near him. He should restrain himself from mixing with common traders and from personally engaging in buying and selling, entrusting that instead to one in whose faith and trustworthiness he has confidence, and warning him against any breach of it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the judge should deal equitably between the two adversaries in his ruling treating them alike in his speech his attention and his regard and he should not speak until he has heard the statements of both he should not give judgment in the mosque nor carry out a prescribed punishment within it though there is no harm in his administering correction there to one who deserves it he should possess dignity deliberateness and care in examining the condition of those he relies upon and admits near him he should restrain himself from mixing with common traders and from personally engaging in buying and selling entrusting that instead to one in whose faith and trustworthiness he has confidence and warning him against any breach of it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 247, NULL, 'As for the one entrusted to judge between the Muslims, he keeps himself apart from mingling with the market folk and from engaging personally in buying and selling. He delegates such matters to those he trusts in their religion and honesty, and he warns them against underestimating or neglecting their duties.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'as for the one entrusted to judge between the muslims he keeps himself apart from mingling with the market folk and from engaging personally in buying and selling he delegates such matters to those he trusts in their religion and honesty and he warns them against underestimating or neglecting their duties', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 248, NULL, 'He rules according to the Book of Allah the Almighty. What he does not find there, he seeks in what is authentically established from the Messenger of Allah and his family, and from the Imams of his lineage. If the ruling remains unknown to him, he refers the matter to the Imam of his time and asks him. He rules neither by his own opinion nor by his own desire, neither by analogy nor by approbation. He accepts no intercession, nor does the party on whose behalf intercession is made receive the intercessor with favor in a way that would draw the judge toward him. Before him, the noble and the humble, the virtuous and the questionable, the strong and the weak stand as equals. He does not hear one party in the absence of the other, nor does he coach one side in its argument, assist it, or lean toward either party in any matter whatsoever.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'he rules according to the book of allah the almighty what he does not find there he seeks in what is authentically established from the messenger of allah and his family and from the imams of his lineage if the ruling remains unknown to him he refers the matter to the imam of his time and asks him he rules neither by his own opinion nor by his own desire neither by analogy nor by approbation he accepts no intercession nor does the party on whose behalf intercession is made receive the intercessor with favor in a way that would draw the judge toward him before him the noble and the humble the virtuous and the questionable the strong and the weak stand as equals he does not hear one party in the absence of the other nor does he coach one side in its argument assist it or lean toward either party in any matter whatsoever', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 249, NULL, 'If he decides a case and it afterward becomes clear to him that his ruling has violated the right, he overturns it and rules by the truth. He does the same with cases brought before him in the past upon which he had already ruled.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'if he decides a case and it afterward becomes clear to him that his ruling has violated the right he overturns it and rules by the truth he does the same with cases brought before him in the past upon which he had already ruled', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 250, NULL, 'Abu Jafar Muhammad ibn Ali said: Among the Children of Israel there was a judge who judged them with truth. When death came upon him, his wife began to weep at his side. He said to her: Why do you weep for me, when I am passing, Allah willing, to what is good? For I know that I once judged unjustly. She asked: And what is the sign of that? He said: When I am laid in my grave, come down to me and uncover my face, and you will see the sign of it.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'abu jafar muhammad ibn ali said among the children of israel there was a judge who judged them with truth when death came upon him his wife began to weep at his side he said to her why do you weep for me when i am passing allah willing to what is good for i know that i once judged unjustly she asked and what is the sign of that he said when i am laid in my grave come down to me and uncover my face and you will see the sign of it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 251, NULL, 'She did so, and she saw a great worm crossing within his nostril. Frightened, she covered him again and left.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'she did so and she saw a great worm crossing within his nostril frightened she covered him again and left', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 252, NULL, 'When night came she saw him in a dream, and he said to her: Did what you saw of me alarm you? She said: Yes, I was indeed alarmed. He said: What you saw befell me only on account of you. Your brother once brought a dispute against a man, and I wished that you might be the one in the right, so that I would rule in your favor; and so it was. That affliction reached me because of my desire that the right should be yours.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'when night came she saw him in a dream and he said to her did what you saw of me alarm you she said yes i was indeed alarmed he said what you saw befell me only on account of you your brother once brought a dispute against a man and i wished that you might be the one in the right so that i would rule in your favor and so it was that affliction reached me because of my desire that the right should be yours', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 253, NULL, 'The account of the judge''s dream closes there. Elsewhere, Abu Abdullah Jafar ibn Muhammad was asked about the words of Allah the Almighty and Exalted: ﴿And do not consume your wealth among yourselves unjustly, and offer it as a bribe to the rulers so that you may consume a portion of the wealth of the people in sin, while you know﴾ (al-Baqarah 188). He said: "Allah, mighty and exalted, knew that there would be rulers in this nation who act unjustly. He did not intend by this verse the rulers among the people of justice; He intended the rulers among the people of injustice. If a man holds a right against another, summons him before the rulers of the people of justice, and that other man refuses — instead bringing the matter before the rulers of the people of injustice — then he is among those who have sought judgment from al-Taghut (اَلطَّاغُوت). That is the meaning of Allah the Almighty''s words: ﴿Have you not seen those who claim to believe in what has been revealed to you and what has been revealed before you, yet they wish to take their disputes to al-Taghut﴾ (al-Nisa 60).', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the account of the judges dream closes there elsewhere abu abdullah jafar ibn muhammad was asked about the words of allah the almighty and exalted and do not consume your wealth among yourselves unjustly and offer it as a bribe to the rulers so that you may consume a portion of the wealth of the people in sin while you know al baqarah 188 he said allah mighty and exalted knew that there would be rulers in this nation who act unjustly he did not intend by this verse the rulers among the people of justice he intended the rulers among the people of injustice if a man holds a right against another summons him before the rulers of the people of justice and that other man refuses instead bringing the matter before the rulers of the people of injustice then he is among those who have sought judgment from al taghut الطاغوت that is the meaning of allah the almightys words have you not seen those who claim to believe in what has been revealed to you and what has been revealed before you yet they wish to take their disputes to al taghut al nisa 60', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 254, NULL, '"The people of injustice are those who oppose you in your affair. Beware, therefore, of carrying your disputes against one another to the people of injustice. Instead, look among yourselves for a man who knows something of our rulings and appoint him as an arbitrator, for I have made him a judge. Bring your disputes to him. As for whatever was decreed against the households of the wrongdoers by those who ruled against them in the days of their power — leave it, and do not pursue it."', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the people of injustice are those who oppose you in your affair beware therefore of carrying your disputes against one another to the people of injustice instead look among yourselves for a man who knows something of our rulings and appoint him as an arbitrator for i have made him a judge bring your disputes to him as for whatever was decreed against the households of the wrongdoers by those who ruled against them in the days of their power leave it and do not pursue it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 255, NULL, 'The judge does not rule in a way that allows one party to profit from the arguments used against the party convicted. He may accept what comes to him from the public treasury, but he may not take anything for himself in the matter he is deciding between the parties. He may inspect the markets of the Muslims, their measures and their weights, and he may delegate this oversight to someone he trusts. He does not imprison anyone on mere suspicion, except in a matter of blood. He strikes with the durrah in cases of slander, in discretionary punishment, and in discipline; when the prescribed punishments fall due, the flogging is carried out with the whip. He does not imprison a man who is in straitened circumstances over a debt.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the judge does not rule in a way that allows one party to profit from the arguments used against the party convicted he may accept what comes to him from the public treasury but he may not take anything for himself in the matter he is deciding between the parties he may inspect the markets of the muslims their measures and their weights and he may delegate this oversight to someone he trusts he does not imprison anyone on mere suspicion except in a matter of blood he strikes with the durrah in cases of slander in discretionary punishment and in discipline when the prescribed punishments fall due the flogging is carried out with the whip he does not imprison a man who is in straitened circumstances over a debt', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 256, NULL, 'If, however, the debtor is found to be solvent and possesses the means to satisfy what has been ruled against him, and that wealth is in his hands, the judge orders him to hand it over. If he refuses, he is beaten until he discharges what has been adjudged against him. If the debtor is absent, he is detained until he produces what is owed, and the judgment is then carried out against him. If, after his return, he persists in withholding it, his property is sold on his behalf and his debt is settled from the proceeds.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'if however the debtor is found to be solvent and possesses the means to satisfy what has been ruled against him and that wealth is in his hands the judge orders him to hand it over if he refuses he is beaten until he discharges what has been adjudged against him if the debtor is absent he is detained until he produces what is owed and the judgment is then carried out against him if after his return he persists in withholding it his property is sold on his behalf and his debt is settled from the proceeds', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 257, NULL, 'A judge does not accept a written ruling sent from another judge in matters involving a prescribed punishment, nor in divorce. He does not accept testimony upon testimony, and he takes no guarantor in a matter of a prescribed punishment. He carries out the judgment of a just judge, but he will not act on another judge''s letter unless someone he trusts bears witness to its authenticity.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'a judge does not accept a written ruling sent from another judge in matters involving a prescribed punishment nor in divorce he does not accept testimony upon testimony and he takes no guarantor in a matter of a prescribed punishment he carries out the judgment of a just judge but he will not act on another judges letter unless someone he trusts bears witness to its authenticity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 258, NULL, 'If testimony against a defendant had been established in a prior judge''s court but never carried into effect, and the witnesses against the defendant subsequently deny it, the sitting judge has the defendant take an oath in favor of the claimant — provided the claimant requests it. If the defendant swears that the claim was never discharged against him, the judge asks the claimant to produce his evidence.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'if testimony against a defendant had been established in a prior judges court but never carried into effect and the witnesses against the defendant subsequently deny it the sitting judge has the defendant take an oath in favor of the claimant provided the claimant requests it if the defendant swears that the claim was never discharged against him the judge asks the claimant to produce his evidence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 259, NULL, 'The judge accepts the appointment of an agent, and testimony in such matters is heard whether the litigant is present or absent. He rules against the absent party and holds him to presenting his argument upon his return. He likewise judges between the People of the Book with truth when they bring their dispute before him.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'the judge accepts the appointment of an agent and testimony in such matters is heard whether the litigant is present or absent he rules against the absent party and holds him to presenting his argument upon his return he likewise judges between the people of the book with truth when they bring their dispute before him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('mukhtasar-ul-asar-2', 'chapter', 'wrong and redress: crime, property disputes, and the judge', '9. Wrong and Redress: Crime, Property Disputes, and the Judge', 260, NULL, 'All of this is the position of the Ahl al-Bayt.', '', NULL, NULL, NULL, NULL, 'mukhtasar ul asaar 2 9 wrong and redress crime property disputes and the judge', 'all of this is the position of the ahl al bayt', '');
